const getYoutubeId = (url: string) => {
  if (!url) return null;
  const match = url.match(
    /(?:youtu\.be\/|youtube\.com\/(?:embed\/|v\/|watch\?v=|watch\?.+&v=))([^&?]+)/,
  );
  return match ? match[1] : null;
};

// Countdown Timer Komponen
const PreviewCountdown = ({
  expiresAt,
  theme,
}: {
  expiresAt: string;
  theme: string;
}) => {
  const [timeLeft, setTimeLeft] = useState("");

  useEffect(() => {
    if (!expiresAt) return;
    const interval = setInterval(() => {
      const distance = new Date(expiresAt).getTime() - new Date().getTime();
      if (distance < 0) {
        setTimeLeft("EXPIRED");
        clearInterval(interval);
        return;
      }
      const d = Math.floor(distance / (1000 * 60 * 60 * 24));
      const h = Math.floor(
        (distance % (1000 * 60 * 60 * 24)) / (1000 * 60 * 60),
      );
      const m = Math.floor((distance % (1000 * 60 * 60)) / (1000 * 60));
      const s = Math.floor((distance % (1000 * 60)) / 1000);
      setTimeLeft(`${d}d ${h}h ${m}m ${s}s`);
    }, 1000);
    return () => clearInterval(interval);
  }, [expiresAt]);

  if (!expiresAt || !timeLeft) return null;
  if (timeLeft === "EXPIRED") return null;

  return (
    <div
      className={`text-[8px] font-mono font-bold mb-1.5 px-2 py-0.5 rounded-sm inline-flex items-center gap-1 ${theme === "dark" ? "bg-rose-500/20 text-rose-400" : "bg-rose-100 text-rose-600"}`}
    >
      <svg
        className="w-3 h-3"
        fill="none"
        viewBox="0 0 24 24"
        stroke="currentColor"
      >
        <path
          strokeLinecap="round"
          strokeLinejoin="round"
          strokeWidth={2}
          d="M12 8v4l3 3m6-3a9 9 0 11-18 0 9 9 0 0118 0z"
        />
      </svg>
      ENDS IN: {timeLeft}
    </div>
  );
};

export default function DashboardBioPage() {
  const defaultSocials = {
    instagram: "",
    tiktok: "",
    youtube: "",
    linkedin: "",
  };
  const [profile, setProfile] = useState({
    name: "DPW IKA UII DIY",
    description: "Wadah silaturahmi & kolaborasi Alumni UII di DIY.",
    logoUrl: "",
    theme: "dark",
    highlightColor: "#FFD700",
    socials: defaultSocials,
  });
  const [links, setLinks] = useState<any[]>([]);
  const [news, setNews] = useState<any[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [isSaving, setIsSaving] = useState(false);
  const [message, setMessage] = useState("");

  const [isProfileExpanded, setIsProfileExpanded] = useState(true);
  const dragItem = useRef<number | null>(null);
  const dragOverItem = useRef<number | null>(null);

  useEffect(() => {
    fetchBioData();
  }, []);

  const fetchBioData = async () => {
    try {
      const snap = await getDoc(doc(db, "settings", "bio_engine"));
      if (snap.exists()) {
        const data = snap.data();
        setProfile({
          ...data.profile,
          highlightColor: data.profile.highlightColor || "#FFD700",
          socials: data.profile.socials || defaultSocials,
        });
        setLinks(
          (data.links || []).map((l: any) => ({ ...l, isExpanded: false })),
        );
        setNews(
          (data.news || []).map((n: any) => ({ ...n, isExpanded: false })),
        );
      }
    } catch (error) {
      console.error(error);
    } finally {
      setIsLoading(false);
    }
  };

  const handleSave = async () => {
    setIsSaving(true);
    try {
      const linksToSave = links.map(({ isExpanded, ...rest }) => rest);
      const newsToSave = news.map(({ isExpanded, ...rest }) => rest);
      await setDoc(
        doc(db, "settings", "bio_engine"),
        { profile, links: linksToSave, news: newsToSave },
        { merge: true },
      );
      setMessage("Konfigurasi Bio berhasil diperbarui");
      setTimeout(() => setMessage(""), 3000);
    } catch (e) {
      setMessage("Gagal menyimpan data");
    } finally {
      setIsSaving(false);
    }
  };

  const addLink = () =>
    setLinks([
      ...links,
      {
        id: Date.now().toString(),
        title: "Tautan Baru",
        url: "",
        type: "link",
        label: "",
        isHighlight: false,
        expiresAt: "",
        isActive: true,
        clicks: 0,
        isExpanded: true,
      },
    ]);
  const addNews = () =>
    setNews([
      ...news,
      {
        id: Date.now().toString(),
        title: "Berita Baru",
        snippet: "",
        url: "",
        imageUrl: "",
        isActive: true,
        isExpanded: true,
      },
    ]);
  const toggleExpandLink = (id: string) =>
    setLinks(
      links.map((l) => (l.id === id ? { ...l, isExpanded: !l.isExpanded } : l)),
    );
  const toggleExpandNews = (id: string) =>
    setNews(
      news.map((n) => (n.id === id ? { ...n, isExpanded: !n.isExpanded } : n)),
    );

  const handleSort = () => {
    if (dragItem.current === null || dragOverItem.current === null) return;
    const _links = [...links];
    const draggedItemContent = _links.splice(dragItem.current, 1)[0];
    _links.splice(dragOverItem.current, 0, draggedItemContent);
    dragItem.current = null;
    dragOverItem.current = null;
    setLinks(_links);
  };

  if (isLoading)
    return (
      <div className="flex h-[70vh] items-center justify-center font-bold text-[#1A73E8] text-xs tracking-widest bg-[#F8F9FA]">
        MEMUAT DATA...
      </div>
    );

  const activeNews = news.filter((n: any) => n.isActive);
  const shouldMarquee = activeNews.length > 2; // Hanya muter kalau berita lebih dari 2

  // Komponen Helper untuk Merender Kartu Berita di Preview
  const NewsCardPreview = ({ item }: { item: any }) => (
    <div
      className={`w-[180px] shrink-0 rounded-lg border overflow-hidden flex flex-col shadow-sm ${profile.theme === "dark" ? "bg-white/5 border-white/10" : "bg-slate-50 border-slate-200"}`}
    >
      {item.imageUrl && (
        <div className="h-20 bg-slate-200 border-b border-white/5">
          <img src={item.imageUrl} className="w-full h-full object-cover" />
        </div>
      )}
      <div className="p-2.5 flex-1 flex flex-col">
        <h4
          className={`text-[10px] font-bold line-clamp-2 leading-tight ${profile.theme === "dark" ? "text-slate-200" : "text-slate-800"}`}
        >
          {item.title}
        </h4>
        <p className="text-[8px] text-slate-500 mt-1 line-clamp-2 flex-1 leading-relaxed">
          {item.snippet}
        </p>
        <span className="text-[8px] font-bold text-[var(--theme-highlight)] mt-2 uppercase tracking-wider">
          Buka ↗
        </span>
      </div>
    </div>
  );

  return (
    <div
      className="p-6 md:p-8 max-w-[1400px] mx-auto font-sans text-slate-700 bg-[#F8F9FA] min-h-screen"
      style={
        { "--theme-highlight": profile.highlightColor } as React.CSSProperties
      }
    >
      <style
        dangerouslySetInnerHTML={{
          __html: `
        @keyframes marquee-admin { 0% { transform: translateX(0); } 100% { transform: translateX(-50%); } }
        .animate-marquee-admin { display: flex; width: max-content; animation: marquee-admin 15s linear infinite; }
        .animate-marquee-admin:hover { animation-play-state: paused; }
        .custom-scrollbar::-webkit-scrollbar { width: 3px; height: 3px; }
        .custom-scrollbar::-webkit-scrollbar-track { background: transparent; }
        .custom-scrollbar::-webkit-scrollbar-thumb { background: rgba(150,150,150,0.3); border-radius: 10px; }
      `,
        }}
      />

      <header className="flex flex-col md:flex-row justify-between items-start md:items-center mb-6 gap-4 border-b border-[#DADCE0] pb-6">
        <div>
          <h1 className="text-2xl font-bold text-slate-800 tracking-tight">
            Manajemen Link in Bio
          </h1>
          <p className="text-sm text-slate-500 mt-1">
            Pusat kendali tautan bio resmi (ikadiy.uii.ac.id/bio).
          </p>
        </div>
        <button
          onClick={handleSave}
          disabled={isSaving}
          className="bg-[#1A73E8] hover:bg-[#1557B0] text-white px-5 py-2.5 rounded-lg font-medium flex items-center gap-2 shadow-sm transition-all disabled:opacity-50 text-sm"
        >
          {isSaving ? (
            "Menyimpan..."
          ) : (
            <>
              <IconSave /> Simpan Perubahan
            </>
          )}
        </button>
      </header>

      {message && (
        <div className="fixed top-6 right-6 bg-slate-800 text-white px-5 py-3 rounded-lg shadow-xl z-50 animate-in slide-in-from-top-4 font-medium text-sm flex items-center gap-2 border border-slate-700">
          <IconCheck /> {message}
        </div>
      )}

      <div className="grid grid-cols-1 lg:grid-cols-12 gap-8 items-start">
        {/* KOLOM KIRI (ADMIN INPUT) */}
        <div className="lg:col-span-8 space-y-6">
          {/* PROFILE IDENTITY */}
          <div className="bg-white rounded-xl border border-[#DADCE0] shadow-sm overflow-hidden">
            <div
              className="flex items-center justify-between p-5 bg-slate-50 hover:bg-slate-100 cursor-pointer border-b border-[#DADCE0]"
              onClick={() => setIsProfileExpanded(!isProfileExpanded)}
            >
              <h2 className="text-base font-bold text-slate-800 flex items-center gap-2">
                <IconSettings /> Identitas & Tema
              </h2>
              <div className="text-slate-400">
                <IconChevronDown isOpen={isProfileExpanded} />
              </div>
            </div>

            {isProfileExpanded && (
              <div className="p-6 animate-in slide-in-from-top-2">
                <div className="flex flex-wrap justify-between items-center mb-6 gap-4">
                  <div className="flex items-center gap-3">
                    <label className="text-xs font-bold text-slate-500 uppercase tracking-wider">
                      Warna Highlight:
                    </label>
                    <div className="flex items-center gap-2 bg-slate-50 border border-[#DADCE0] p-1 rounded-lg">
                      <input
                        type="color"
                        value={profile.highlightColor}
                        onChange={(e) =>
                          setProfile({
                            ...profile,
                            highlightColor: e.target.value,
                          })
                        }
                        className="w-8 h-8 rounded cursor-pointer border-0 bg-transparent p-0"
                      />
                      <span className="text-xs font-mono font-bold px-2">
                        {profile.highlightColor.toUpperCase()}
                      </span>
                    </div>
                  </div>
                  <div className="flex items-center gap-2 bg-slate-100 p-1 rounded-lg">
                    <button
                      onClick={() => setProfile({ ...profile, theme: "light" })}
                      className={`px-3 py-1.5 text-xs font-bold rounded-md transition-colors ${profile.theme === "light" ? "bg-white shadow text-slate-800" : "text-slate-500"}`}
                    >
                      Light Mode
                    </button>
                    <button
                      onClick={() => setProfile({ ...profile, theme: "dark" })}
                      className={`px-3 py-1.5 text-xs font-bold rounded-md transition-colors ${profile.theme === "dark" ? "bg-slate-800 shadow text-white" : "text-slate-500"}`}
                    >
                      Dark Mode
                    </button>
                  </div>
                </div>

                <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                  <div>
                    <label className="text-xs font-bold text-slate-500 uppercase tracking-wider">
                      Nama Tampilan
                    </label>
                    <input
                      value={profile.name}
                      onChange={(e) =>
                        setProfile({ ...profile, name: e.target.value })
                      }
                      className="w-full mt-1.5 p-2.5 bg-slate-50 border border-[#DADCE0] rounded-md text-sm font-semibold focus:border-[#1A73E8] outline-none"
                    />
                  </div>
                  <div>
                    <label className="text-xs font-bold text-slate-500 uppercase tracking-wider">
                      URL Logo
                    </label>
                    <input
                      value={profile.logoUrl}
                      onChange={(e) =>
                        setProfile({ ...profile, logoUrl: e.target.value })
                      }
                      className="w-full mt-1.5 p-2.5 bg-slate-50 border border-[#DADCE0] rounded-md text-sm focus:border-[#1A73E8] outline-none"
                      placeholder="https://..."
                    />
                  </div>
                  <div className="md:col-span-2">
                    <label className="text-xs font-bold text-slate-500 uppercase tracking-wider">
                      Deskripsi Singkat (Bio)
                    </label>
                    <textarea
                      value={profile.description}
                      onChange={(e) =>
                        setProfile({ ...profile, description: e.target.value })
                      }
                      className="w-full mt-1.5 p-2.5 bg-slate-50 border border-[#DADCE0] rounded-md text-sm leading-relaxed resize-none focus:border-[#1A73E8] outline-none"
                      rows={2}
                    />
                  </div>
                </div>

                <div className="mt-6 pt-6 border-t border-[#DADCE0]">
                  <h3 className="text-xs font-bold text-slate-500 uppercase tracking-wider mb-3">
                    Tautan Sosial Media
                  </h3>
                  <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-3">
                    <div className="flex items-center bg-slate-50 border border-[#DADCE0] rounded-md px-2">
                      <span className="text-slate-400">{SocIcons.ig}</span>
                      <input
                        value={profile.socials?.instagram}
                        onChange={(e) =>
                          setProfile({
                            ...profile,
                            socials: {
                              ...profile.socials,
                              instagram: e.target.value,
                            },
                          })
                        }
                        className="w-full p-2 bg-transparent text-xs outline-none"
                        placeholder="Username IG"
                      />
                    </div>
                    <div className="flex items-center bg-slate-50 border border-[#DADCE0] rounded-md px-2">
                      <span className="text-slate-400">{SocIcons.tiktok}</span>
                      <input
                        value={profile.socials?.tiktok}
                        onChange={(e) =>
                          setProfile({
                            ...profile,
                            socials: {
                              ...profile.socials,
                              tiktok: e.target.value,
                            },
                          })
                        }
                        className="w-full p-2 bg-transparent text-xs outline-none"
                        placeholder="Username TikTok"
                      />
                    </div>
                    <div className="flex items-center bg-slate-50 border border-[#DADCE0] rounded-md px-2">
                      <span className="text-slate-400">{SocIcons.yt}</span>
                      <input
                        value={profile.socials?.youtube}
                        onChange={(e) =>
                          setProfile({
                            ...profile,
                            socials: {
                              ...profile.socials,
                              youtube: e.target.value,
                            },
                          })
                        }
                        className="w-full p-2 bg-transparent text-xs outline-none"
                        placeholder="URL Channel"
                      />
                    </div>
                    <div className="flex items-center bg-slate-50 border border-[#DADCE0] rounded-md px-2">
                      <span className="text-slate-400">
                        {SocIcons.linkedin}
                      </span>
                      <input
                        value={profile.socials?.linkedin}
                        onChange={(e) =>
                          setProfile({
                            ...profile,
                            socials: {
                              ...profile.socials,
                              linkedin: e.target.value,
                            },
                          })
                        }
                        className="w-full p-2 bg-transparent text-xs outline-none"
                        placeholder="URL LinkedIn"
                      />
                    </div>
                  </div>
                </div>
              </div>
            )}
          </div>

          {/* BERITA & PENGUMUMAN */}
          <div className="bg-white p-6 rounded-xl border border-[#DADCE0] shadow-sm">
            <div className="flex justify-between items-center border-b border-[#DADCE0] pb-4 mb-4">
              <h2 className="text-base font-bold text-slate-800 flex items-center gap-2">
                <IconNews /> Berita & Highlight
              </h2>
              <button
                onClick={addNews}
                className="text-xs font-bold text-[#1A73E8] bg-blue-50/50 px-4 py-2 rounded-md border border-blue-100 hover:bg-blue-50 transition-colors flex items-center gap-1.5"
              >
                <IconPlus /> Tambah Berita
              </button>
            </div>
            <div className="space-y-3">
              {news.length === 0 && (
                <div className="text-center p-8 border border-dashed border-[#DADCE0] rounded-xl text-slate-500 text-sm">
                  Belum ada berita.
                </div>
              )}
              {news.map((item, idx) => (
                <div
                  key={item.id}
                  className="border border-[#DADCE0] rounded-xl overflow-hidden shadow-sm bg-white"
                >
                  <div className="flex items-center justify-between p-3 bg-slate-50 border-b border-[#DADCE0]">
                    <div
                      className="cursor-pointer flex items-center gap-3 w-full"
                      onClick={() => toggleExpandNews(item.id)}
                    >
                      <span className="bg-slate-200 text-slate-600 font-bold text-[10px] px-2 py-0.5 rounded">
                        N{idx + 1}
                      </span>
                      <span className="font-semibold text-sm text-slate-700 truncate">
                        {item.title || "(Tanpa Judul Berita)"}
                      </span>
                      {!item.isActive && (
                        <span className="bg-slate-200 text-slate-500 text-[9px] font-bold px-1.5 py-0.5 rounded uppercase">
                          Sembunyi
                        </span>
                      )}
                    </div>
                    <div className="flex items-center gap-3">
                      <button
                        onClick={() =>
                          setNews(news.filter((n) => n.id !== item.id))
                        }
                        className="text-slate-400 hover:text-red-500 p-1"
                      >
                        <IconTrash />
                      </button>
                      <button
                        onClick={() => toggleExpandNews(item.id)}
                        className="text-slate-400"
                      >
                        <IconChevronDown isOpen={item.isExpanded} />
                      </button>
                    </div>
                  </div>
                  {item.isExpanded && (
                    <div className="p-5">
                      <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                        <div className="md:col-span-2">
                          <label className="text-xs font-bold text-slate-500 uppercase">
                            Judul Berita
                          </label>
                          <input
                            value={item.title}
                            onChange={(e) =>
                              setNews(
                                news.map((n) =>
                                  n.id === item.id
                                    ? { ...n, title: e.target.value }
                                    : n,
                                ),
                              )
                            }
                            className="w-full mt-1.5 p-2.5 bg-slate-50 border border-[#DADCE0] rounded-md font-semibold text-sm focus:border-[#1A73E8] outline-none"
                          />
                        </div>
                        <div className="md:col-span-2">
                          <label className="text-xs font-bold text-slate-500 uppercase">
                            Ringkasan Singkat
                          </label>
                          <textarea
                            value={item.snippet}
                            onChange={(e) =>
                              setNews(
                                news.map((n) =>
                                  n.id === item.id
                                    ? { ...n, snippet: e.target.value }
                                    : n,
                                ),
                              )
                            }
                            className="w-full mt-1.5 p-2.5 bg-slate-50 border border-[#DADCE0] rounded-md text-sm focus:border-[#1A73E8] outline-none"
                            rows={2}
                          />
                        </div>
                        <div>
                          <label className="text-xs font-bold text-slate-500 uppercase">
                            URL Tautan Berita
                          </label>
                          <input
                            value={item.url}
                            onChange={(e) =>
                              setNews(
                                news.map((n) =>
                                  n.id === item.id
                                    ? { ...n, url: e.target.value }
                                    : n,
                                ),
                              )
                            }
                            className="w-full mt-1.5 p-2.5 bg-slate-50 border border-[#DADCE0] rounded-md text-sm focus:border-[#1A73E8] outline-none"
                            placeholder="https://..."
                          />
                        </div>
                        <div>
                          <label className="text-xs font-bold text-slate-500 uppercase">
                            URL Gambar Thumbnail
                          </label>
                          <input
                            value={item.imageUrl}
                            onChange={(e) =>
                              setNews(
                                news.map((n) =>
                                  n.id === item.id
                                    ? { ...n, imageUrl: e.target.value }
                                    : n,
                                ),
                              )
                            }
                            className="w-full mt-1.5 p-2.5 bg-slate-50 border border-[#DADCE0] rounded-md text-sm focus:border-[#1A73E8] outline-none"
                            placeholder="https://..."
                          />
                        </div>
                      </div>
                      <div className="mt-4 pt-4 border-t border-[#DADCE0] flex items-center justify-between">
                        <label className="flex items-center gap-2 cursor-pointer">
                          <input
                            type="checkbox"
                            checked={item.isActive}
                            onChange={(e) =>
                              setNews(
                                news.map((n) =>
                                  n.id === item.id
                                    ? { ...n, isActive: e.target.checked }
                                    : n,
                                ),
                              )
                            }
                            className="w-3.5 h-3.5 rounded border-slate-300 text-[#1A73E8]"
                          />
                          <span className="text-xs font-medium text-slate-600">
                            Tampilkan ke Publik
                          </span>
                        </label>
                      </div>
                    </div>
                  )}
                </div>
              ))}
            </div>
          </div>

          {/* LINKS MANAGEMENT */}
          <div className="bg-white p-6 rounded-xl border border-[#DADCE0] shadow-sm">
            <div className="flex justify-between items-center border-b border-[#DADCE0] pb-4 mb-4">
              <h2 className="text-base font-bold text-slate-800 flex items-center gap-2">
                <IconLink /> Daftar Tautan
              </h2>
              <button
                onClick={addLink}
                className="text-xs font-bold text-[#1A73E8] bg-blue-50/50 px-4 py-2 rounded-md border border-blue-100 hover:bg-blue-50 transition-colors flex items-center gap-1.5"
              >
                <IconPlus /> Tambah Tautan
              </button>
            </div>
            <div className="space-y-3">
              {links.length === 0 && (
                <div className="text-center p-8 border border-dashed border-[#DADCE0] rounded-xl text-slate-500 text-sm">
                  Belum ada tautan.
                </div>
              )}
              {links.map((link, idx) => (
                <div
                  key={link.id}
                  draggable
                  onDragStart={() => (dragItem.current = idx)}
                  onDragEnter={() => (dragOverItem.current = idx)}
                  onDragEnd={handleSort}
                  onDragOver={(e) => e.preventDefault()}
                  className="border border-[#DADCE0] rounded-xl overflow-hidden shadow-sm bg-white"
                >
                  <div className="flex items-center justify-between p-3 bg-slate-50 border-b border-[#DADCE0]">
                    <div className="flex items-center gap-3 overflow-hidden w-full">
                      <div className="px-2 cursor-grab text-slate-400 hover:text-slate-600">
                        <IconGrip />
                      </div>
                      <div
                        className="cursor-pointer flex items-center gap-3 w-full"
                        onClick={() => toggleExpandLink(link.id)}
                      >
                        <span className="bg-slate-200 text-slate-600 font-bold text-[10px] px-2 py-0.5 rounded">
                          #{idx + 1}
                        </span>
                        <span className="font-semibold text-sm text-slate-700 truncate">
                          {link.title || "(Tanpa Judul)"}
                        </span>
                        {!link.isActive && (
                          <span className="bg-slate-200 text-slate-500 text-[9px] font-bold px-1.5 py-0.5 rounded uppercase">
                            Sembunyi
                          </span>
                        )}
                      </div>
                    </div>
                    <div className="flex items-center gap-3">
                      <button
                        onClick={() =>
                          setLinks(links.filter((l) => l.id !== link.id))
                        }
                        className="text-slate-400 hover:text-red-500 p-1"
                      >
                        <IconTrash />
                      </button>
                      <button
                        onClick={() => toggleExpandLink(link.id)}
                        className="text-slate-400"
                      >
                        <IconChevronDown isOpen={link.isExpanded} />
                      </button>
                    </div>
                  </div>
                  {link.isExpanded && (
                    <div className="p-5">
                      <div className="grid grid-cols-1 md:grid-cols-12 gap-6">
                        <div className="md:col-span-7 space-y-4">
                          <div>
                            <label className="text-xs font-bold text-slate-500 uppercase">
                              Judul Konten
                            </label>
                            <input
                              value={link.title}
                              onChange={(e) =>
                                setLinks(
                                  links.map((l) =>
                                    l.id === link.id
                                      ? { ...l, title: e.target.value }
                                      : l,
                                  ),
                                )
                              }
                              className="w-full mt-1.5 p-2.5 bg-slate-50 border border-[#DADCE0] rounded-md focus:border-[#1A73E8] outline-none font-semibold text-sm"
                            />
                          </div>
                          <div>
                            <label className="text-xs font-bold text-slate-500 uppercase">
                              URL Tujuan
                            </label>
                            <input
                              value={link.url}
                              onChange={(e) =>
                                setLinks(
                                  links.map((l) =>
                                    l.id === link.id
                                      ? { ...l, url: e.target.value }
                                      : l,
                                  ),
                                )
                              }
                              className="w-full mt-1.5 p-2.5 bg-slate-50 border border-[#DADCE0] rounded-md text-sm font-mono focus:border-[#1A73E8] outline-none"
                            />
                          </div>
                        </div>
                        <div className="md:col-span-5 space-y-4 border-l border-[#DADCE0] pl-5">
                          <div className="grid grid-cols-2 gap-4">
                            <div>
                              <label className="text-[10px] font-bold text-slate-500 uppercase">
                                Format
                              </label>
                              <select
                                value={link.type}
                                onChange={(e) =>
                                  setLinks(
                                    links.map((l) =>
                                      l.id === link.id
                                        ? { ...l, type: e.target.value }
                                        : l,
                                    ),
                                  )
                                }
                                className="w-full mt-1.5 p-2.5 bg-white border border-[#DADCE0] rounded-md text-xs focus:border-[#1A73E8] outline-none"
                              >
                                <option value="link">Tautan Teks</option>
                                <option value="video">Video YouTube</option>
                              </select>
                            </div>
                            <div>
                              <label className="text-[10px] font-bold text-slate-500 uppercase">
                                Label (Stiker)
                              </label>
                              <input
                                value={link.label}
                                onChange={(e) =>
                                  setLinks(
                                    links.map((l) =>
                                      l.id === link.id
                                        ? { ...l, label: e.target.value }
                                        : l,
                                    ),
                                  )
                                }
                                className="w-full mt-1.5 p-2.5 bg-white border border-[#DADCE0] rounded-md text-xs font-medium text-[#1A73E8] focus:border-[#1A73E8] outline-none"
                                placeholder="NEW"
                              />
                            </div>
                          </div>
                          <div>
                            <label className="text-[10px] font-bold text-slate-500 uppercase">
                              Batas Waktu (Timer Lock)
                            </label>
                            <input
                              type="datetime-local"
                              value={link.expiresAt}
                              onChange={(e) =>
                                setLinks(
                                  links.map((l) =>
                                    l.id === link.id
                                      ? { ...l, expiresAt: e.target.value }
                                      : l,
                                  ),
                                )
                              }
                              className="w-full mt-1.5 p-2 bg-white border border-[#DADCE0] rounded-md text-[11px] focus:border-[#1A73E8] outline-none"
                            />
                          </div>
                        </div>
                      </div>
                      <div className="mt-4 pt-4 border-t border-[#DADCE0] flex flex-wrap justify-between gap-4">
                        <div className="flex items-center gap-6">
                          <label className="flex items-center gap-2 cursor-pointer">
                            <input
                              type="checkbox"
                              checked={link.isHighlight}
                              onChange={(e) =>
                                setLinks(
                                  links.map((l) =>
                                    l.id === link.id
                                      ? { ...l, isHighlight: e.target.checked }
                                      : l,
                                  ),
                                )
                              }
                              className="w-3.5 h-3.5 rounded border-slate-300"
                            />
                            <span className="text-xs font-medium text-slate-600">
                              Beri Highlight Warna
                            </span>
                          </label>
                          <label className="flex items-center gap-2 cursor-pointer">
                            <input
                              type="checkbox"
                              checked={link.isActive}
                              onChange={(e) =>
                                setLinks(
                                  links.map((l) =>
                                    l.id === link.id
                                      ? { ...l, isActive: e.target.checked }
                                      : l,
                                  ),
                                )
                              }
                              className="w-3.5 h-3.5 rounded border-slate-300 text-[#1A73E8]"
                            />
                            <span className="text-xs font-medium text-slate-600">
                              Tampilkan
                            </span>
                          </label>
                        </div>
                        <div className="bg-slate-50 px-2 py-1 rounded border border-[#DADCE0] text-[10px] text-slate-500 font-medium">
                          <IconChart /> {link.clicks || 0} KLIK
                        </div>
                      </div>
                    </div>
                  )}
                </div>
              ))}
            </div>
          </div>
        </div>

        {/* KOLOM KANAN: LIVE PREVIEW */}
        <div className="lg:col-span-4 sticky top-6">
          <div className="text-center mb-2">
            <span className="text-xs font-bold uppercase tracking-widest text-slate-400">
              Live Preview ({profile.theme})
            </span>
          </div>

          <div
            className={`w-[320px] h-[650px] mx-auto border-[8px] rounded-[2.5rem] shadow-2xl relative overflow-hidden flex flex-col font-sans transition-colors duration-500 ${profile.theme === "dark" ? "bg-[#050810] border-slate-800 text-slate-300" : "bg-slate-100 border-slate-300 text-slate-800"}`}
          >
            <div
              className={`absolute top-0 inset-x-0 h-5 rounded-b-xl w-32 mx-auto z-50 ${profile.theme === "dark" ? "bg-slate-800" : "bg-slate-300"}`}
            ></div>
            <div
              className={`absolute top-0 right-0 w-full h-[300px] blur-[60px] pointer-events-none ${profile.theme === "dark" ? "bg-[#1A3A8F]/30" : "bg-blue-300/40"}`}
            ></div>

            <div
              className={`flex-1 overflow-y-auto mt-8 mb-0 mx-3 rounded-t-xl border shadow-lg relative z-10 custom-scrollbar transition-colors duration-500 ${profile.theme === "dark" ? "bg-[#0A0F1D] border-white/10" : "bg-white border-slate-200"}`}
            >
              <div
                className={`px-3 py-2 flex items-center justify-between border-b sticky top-0 z-20 ${profile.theme === "dark" ? "bg-[#060913] border-white/10" : "bg-slate-50 border-slate-200"}`}
              >
                <div className="flex gap-1">
                  <div className="w-2 h-2 rounded-full bg-rose-500/80"></div>
                  <div className="w-2 h-2 rounded-full bg-amber-500/80"></div>
                  <div className="w-2 h-2 rounded-full bg-emerald-500/80"></div>
                </div>
                <div className="text-[8px] font-mono text-slate-500 tracking-wider">
                  ~/ikadiy/links.tsx
                </div>
                <div className="w-6"></div>
              </div>

              <div className="p-4 space-y-6 pb-10">
                <div className="flex flex-col items-center text-center space-y-4">
                  <div
                    className={`w-16 h-16 rounded-full border flex items-center justify-center overflow-hidden relative shadow-md ${profile.theme === "dark" ? "border-[var(--theme-highlight)]/50 bg-[#060913]" : "border-slate-200 bg-white"}`}
                  >
                    {profile.logoUrl ? (
                      <img
                        src={profile.logoUrl}
                        alt="Logo"
                        className="w-full h-full object-cover p-1"
                      />
                    ) : (
                      <span className="font-black text-sm text-[var(--theme-highlight)]">
                        IKA
                      </span>
                    )}
                  </div>
                  <div>
                    <h1 className="font-mono text-[10px] font-bold flex justify-center flex-wrap leading-tight">
                      <span className="text-pink-500">const</span>&nbsp;
                      <span className="text-blue-500">admin</span>&nbsp;
                      <span
                        className={
                          profile.theme === "dark"
                            ? "text-white"
                            : "text-slate-800"
                        }
                      >
                        =
                      </span>
                      &nbsp;
                      <span className="text-[var(--theme-highlight)]">
                        "{profile.name}"
                      </span>
                      <VerifiedBadge />
                    </h1>
                    {profile.description && (
                      <div className="font-mono text-[9px] mt-2 leading-relaxed text-left inline-block">
                        <span className="text-slate-400">/**</span>
                        <br />
                        <span className="text-slate-500">
                          {" "}
                          * {profile.description}
                        </span>
                        <br />
                        <span className="text-slate-400"> */</span>
                      </div>
                    )}
                  </div>
                </div>

                {/* PREVIEW BERITA (KONDISIONAL: JALAN/DIAM) */}
                {activeNews.length > 0 && (
                  <div className="space-y-2 -mx-3 overflow-hidden">
                    <h3 className="font-mono text-[9px] text-slate-500 font-bold uppercase px-3 flex items-center gap-1.5">
                      <span className="w-1.5 h-1.5 bg-red-500 animate-pulse rounded-full"></span>{" "}
                      LATEST NEWS
                    </h3>
                    <div className="overflow-hidden w-full relative">
                      {shouldMarquee ? (
                        // LEBIH DARI 2 BERITA: MARQUEE BERJALAN
                        <div className="animate-marquee-admin flex gap-3 pl-3 cursor-grab">
                          <div className="flex gap-3">
                            {activeNews.map((item: any, idx: number) => (
                              <NewsCardPreview
                                key={`n1-${item.id}-${idx}`}
                                item={item}
                              />
                            ))}
                          </div>
                          <div className="flex gap-3">
                            {activeNews.map((item: any, idx: number) => (
                              <NewsCardPreview
                                key={`n2-${item.id}-${idx}`}
                                item={item}
                              />
                            ))}
                          </div>
                        </div>
                      ) : (
                        // 1 ATAU 2 BERITA: DIAM (SCROLL MANUAL JIKA PERLU)
                        <div className="flex gap-3 px-3 overflow-x-auto custom-scrollbar pb-2">
                          {activeNews.map((item: any, idx: number) => (
                            <NewsCardPreview
                              key={`ns-${item.id}-${idx}`}
                              item={item}
                            />
                          ))}
                        </div>
                      )}
                    </div>
                  </div>
                )}

                {/* PREVIEW LINK & VIDEO */}
                <div className="space-y-3">
                  {links
                    .filter((l) => l.isActive)
                    .map((link) => {
                      const ytId =
                        link.type === "video" ? getYoutubeId(link.url) : null;
                      return (
                        <div key={`link-${link.id}`}>
                          {link.type === "video" && ytId ? (
                            <div
                              className={`rounded-xl overflow-hidden border shadow-sm relative ${link.isHighlight ? "border-[var(--theme-highlight)] ring-1 ring-[var(--theme-highlight)]/50" : profile.theme === "dark" ? "border-white/10" : "border-slate-200"}`}
                            >
                              <div className="aspect-video relative bg-black">
                                <img
                                  src={`https://img.youtube.com/vi/${ytId}/hqdefault.jpg`}
                                  className="w-full h-full object-cover opacity-80"
                                />
                                <div className="absolute inset-0 bg-black/20 flex items-center justify-center">
                                  <div className="w-8 h-8 bg-red-600 rounded-full flex items-center justify-center pl-1">
                                    <svg
                                      className="w-4 h-4 text-white"
                                      fill="currentColor"
                                      viewBox="0 0 24 24"
                                    >
                                      <path d="M8 5v14l11-7z" />
                                    </svg>
                                  </div>
                                </div>
                              </div>
                              <div
                                className={`p-2 text-[9px] font-bold font-mono truncate ${profile.theme === "dark" ? "bg-[#060913] text-slate-300" : "bg-white text-slate-700"}`}
                              >
                                {link.title || "Video YouTube"}
                              </div>
                            </div>
                          ) : (
                            <div
                              className={`p-3 rounded-xl border flex items-center justify-between ${link.isHighlight ? "border-[var(--theme-highlight)]/50 bg-[var(--theme-highlight)]/10" : profile.theme === "dark" ? "bg-white/5 border-white/10" : "bg-white border-slate-200"}`}
                            >
                              <div className="flex items-center gap-2 overflow-hidden">
                                <span
                                  className={`font-mono text-[10px] font-bold ${link.isHighlight ? "text-[var(--theme-highlight)]" : "text-blue-500"}`}
                                >
                                  {">_"}
                                </span>
                                <span
                                  className={`font-semibold text-[10px] truncate ${link.isHighlight ? (profile.theme === "dark" ? "text-[var(--theme-highlight)]" : "text-slate-800") : profile.theme === "dark" ? "text-slate-200" : "text-slate-700"}`}
                                >
                                  {link.title || "Tautan"}
                                </span>
                              </div>
                            </div>
                          )}
                        </div>
                      );
                    })}
                </div>

                {/* Footer Preview */}
                <div
                  className={`pt-6 mt-4 flex flex-col items-center justify-center gap-4 border-t ${profile.theme === "dark" ? "border-white/5 text-slate-400" : "border-slate-200 text-slate-500"}`}
                >
                  <div className="flex items-center gap-4">
                    {profile.socials?.instagram && <div>{SocIcons.ig}</div>}
                    {profile.socials?.tiktok && <div>{SocIcons.tiktok}</div>}
                    {profile.socials?.youtube && <div>{SocIcons.yt}</div>}
                    {profile.socials?.linkedin && (
                      <div>{SocIcons.linkedin}</div>
                    )}
                  </div>
                  <div className="text-[8px] font-mono opacity-50">
                    &copy; {new Date().getFullYear()} IKA UII DIY.
                  </div>
                </div>
              </div>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
}

"use client";

import { useState, useEffect } from "react";
import { db } from "@/lib/firebase";
import {
  collection,
  query,
  orderBy,
  getDocs,
  addDoc,
  updateDoc,
  deleteDoc,
  doc,
  serverTimestamp,
} from "firebase/firestore";
import * as XLSX from "xlsx";
import { sendEmailAction } from "@/app/actions/email";


const KATEGORI_LIST = [
  "Kuliner",
  "Teknologi",
  "Jasa",
  "Retail",
  "Kesehatan",
  "Pendidikan",
  "Properti",
  "Lainnya",
];

export default function AdminDirektoriPage() {
  const [activeTab, setActiveTab] = useState<
    "antrean" | "master" | "iklan" | "merch"
  >("antrean");

  const [bisnisList, setBisnisList] = useState<any[]>([]);
  const [iklanList, setIklanList] = useState<any[]>([]);
  const [usulanMerchList, setUsulanMerchList] = useState<any[]>([]);

  const [isLoading, setIsLoading] = useState(true);
  const [isSaving, setIsSaving] = useState(false);
  const [isSendingMail, setIsSendingMail] = useState<string | null>(null);
  const [uploadProgress, setUploadProgress] = useState("");

  const [selectedIds, setSelectedIds] = useState<string[]>([]);

  const [dialog, setDialog] = useState<{
    isOpen: boolean;
    type: "alert" | "confirm" | "prompt";
    title: string;
    message: string;
    onConfirm?: (inputValue?: string) => void;
  }>({
    isOpen: false,
    type: "alert",
    title: "",
    message: "",
  });

  const [isBisnisModalOpen, setIsBisnisModalOpen] = useState(false);
  const [isIklanModalOpen, setIsIklanModalOpen] = useState(false);
  const [modalMode, setModalMode] = useState<"add" | "edit" | "review">("add");
  const [iklanModalMode, setIklanModalMode] = useState<
    "add" | "edit" | "review"
  >("add");
  const [selectedId, setSelectedId] = useState<string | null>(null);

  const [formData, setFormData] = useState({
    namaAlumni: "",
    email: "",
    fakultasAngkatan: "",
    prodi: "",
    namaBisnis: "",
    kategori: "Kuliner",
    kategoriLainnya: "",
    deskripsi: "",
    alamatUsaha: "",
    fasilitas: "",
    waBisnis: "",
    linkBisnis: "",
    foto: "",
    status: "Pending",
  });

  const [iklanData, setIklanData] = useState({
    namaSponsor: "",
    emailSponsor: "",
    noWA: "",
    fotoUrl: "",
    linkTujuan: "",
    tanggalBerakhir: "",
    isActive: true,
    status: "Pending",
  });

  const closeDialog = () => setDialog({ ...dialog, isOpen: false });
  const showAlert = (title: string, message: string) =>
    setDialog({ isOpen: true, type: "alert", title, message });
  const showConfirm = (title: string, message: string, onConfirm: () => void) =>
    setDialog({ isOpen: true, type: "confirm", title, message, onConfirm });
  const showPrompt = (
    title: string,
    message: string,
    onConfirm: (val?: string) => void,
  ) => setDialog({ isOpen: true, type: "prompt", title, message, onConfirm });

  const fetchData = async () => {
    setIsLoading(true);
    try {
      // 1. Fetch Bisnis Master & Pending
      const qBisnis = query(
        collection(db, "direktori_bisnis"),
        orderBy("createdAt", "desc"),
      );
      const snapBisnis = await getDocs(qBisnis);
      const dataBisnis = snapBisnis.docs.map((d) => ({
        id: d.id,
        isPendingCol: false,
        ...d.data(),
      }));

      const qPendaftaran = query(
        collection(db, "pendaftaran_bisnis"),
        orderBy("createdAt", "desc"),
      );
      const snapPendaftaran = await getDocs(qPendaftaran);
      const dataPendaftaran = snapPendaftaran.docs.map((d) => ({
        id: d.id,
        isPendingCol: true,
        ...d.data(),
      }));

      const combinedBisnis = [...dataPendaftaran, ...dataBisnis].sort(
        (a: any, b: any) => {
          const dateA = a.createdAt?.toMillis ? a.createdAt.toMillis() : 0;
          const dateB = b.createdAt?.toMillis ? b.createdAt.toMillis() : 0;
          return dateB - dateA;
        },
      );
      setBisnisList(combinedBisnis);

      // 2. Fetch Iklan Master & Pending
      const qIklan = query(
        collection(db, "iklan_direktori"),
        orderBy("createdAt", "desc"),
      );
      const snapIklan = await getDocs(qIklan);
      const dataIklanLive = snapIklan.docs.map((d) => ({
        id: d.id,
        isPendingCol: false,
        ...d.data(),
      }));

      let dataIklanPending: any[] = [];
      try {
        const qIklanPending = query(
          collection(db, "pendaftaran_iklan"),
          orderBy("createdAt", "desc"),
        );
        const snapIklanPending = await getDocs(qIklanPending);
        dataIklanPending = snapIklanPending.docs.map((d) => ({
          id: d.id,
          isPendingCol: true,
          ...d.data(),
        }));
      } catch (e) {
        console.warn("Koleksi pendaftaran_iklan belum tersedia.");
      }

      const combinedIklan = [...dataIklanPending, ...dataIklanLive].sort(
        (a, b) => {
          const dateA = a.createdAt?.toMillis ? a.createdAt.toMillis() : 0;
          const dateB = b.createdAt?.toMillis ? b.createdAt.toMillis() : 0;
          return dateB - dateA;
        },
      );
      setIklanList(combinedIklan);

      // 3. Fetch Usulan Merch
      try {
        const qMerch = query(
          collection(db, "usulan_merch"),
          orderBy("createdAt", "desc"),
        );
        const snapMerch = await getDocs(qMerch);
        setUsulanMerchList(
          snapMerch.docs.map((d) => ({ id: d.id, ...d.data() })),
        );
      } catch (e) {
        console.warn("Koleksi usulan_merch belum tersedia.");
      }
    } catch (error) {
      console.error("Gagal memuat data:", error);
      showAlert("Kesalahan Sistem", "Gagal memuat data dari database.");
    } finally {
      setIsLoading(false);
      setSelectedIds([]);
    }
  };

  useEffect(() => {
    fetchData();
  }, []);

  const pendingList = bisnisList.filter((b) => b.isPendingCol);
  const masterList = bisnisList.filter((b) => !b.isPendingCol);

  const pendingIklanList = iklanList.filter((i) => i.isPendingCol);
  const masterIklanList = iklanList.filter((i) => !i.isPendingCol);

  const handleTabChange = (tab: "antrean" | "master" | "iklan" | "merch") => {
    setActiveTab(tab);
    setSelectedIds([]);
  };

  const handleSelectAll = (
    e: React.ChangeEvent<HTMLInputElement>,
    list: any[],
  ) => {
    if (e.target.checked) setSelectedIds(list.map((item) => item.id));
    else setSelectedIds([]);
  };

  const handleSelectOne = (
    e: React.ChangeEvent<HTMLInputElement>,
    id: string,
  ) => {
    if (e.target.checked) setSelectedIds((prev) => [...prev, id]);
    else setSelectedIds((prev) => prev.filter((item) => item !== id));
  };

  const handleImageUpload = async (e: any, type: "bisnis" | "iklan") => {
    const file = e.target.files[0];
    if (!file) return;

    setUploadProgress("Mengunggah...");
    const data = new FormData();
    data.append("file", file);
    data.append("upload_preset", "bisnis");
    data.append("cloud_name", "dp8hmxuix");

    try {
      const res = await fetch(
        `https://api.cloudinary.com/v1_1/dp8hmxuix/image/upload`,
        {
          method: "POST",
          body: data,
        },
      );
      const json = await res.json();
      if (type === "bisnis")
        setFormData({ ...formData, foto: json.secure_url });
      if (type === "iklan")
        setIklanData({ ...iklanData, fotoUrl: json.secure_url });
      setUploadProgress("Unggah sukses!");
      setTimeout(() => setUploadProgress(""), 3000);
    } catch (error) {
      setUploadProgress("Gagal mengunggah.");
    }
  };

  const sendEmailAPI = async (
    type: string,
    email: string,
    nama: string,
    detail: any,
  ) => {
    try {
      const res = await sendEmailAction({ type, email, nama, detail });
      if (!res.success) return false;
      return true;
    } catch (error) {
      return false;
    }
  };

  // --- LOGIKA BISNIS ---
  const openBisnisModal = (
    mode: "add" | "edit" | "review",
    data: any = null,
  ) => {
    setModalMode(mode);
    if (data) {
      setSelectedId(data.id);
      let cat = data.kategori || "Kuliner";
      let catLainnya = "";
      if (data.kategori && !KATEGORI_LIST.includes(data.kategori)) {
        cat = "Lainnya";
        catLainnya = data.kategori;
      }
      setFormData({
        namaAlumni: data.namaAlumni || data.owner || "",
        email: data.email || data.emailPemilik || "",
        fakultasAngkatan: data.fakultasAngkatan || "",
        prodi: data.prodi || "",
        namaBisnis: data.namaBisnis || data.nama || "",
        kategori: cat,
        kategoriLainnya: catLainnya,
        deskripsi: data.deskripsi || "",
        alamatUsaha: data.alamatUsaha || "",
        fasilitas: data.fasilitas || "",
        waBisnis: data.waBisnis || data.noWA || data.wa || "",
        linkBisnis: data.linkBisnis || "",
        foto: data.foto || data.fotoUrl || "",
        status: data.status || "Pending",
      });
    } else {
      setSelectedId(null);
      setFormData({
        namaAlumni: "",
        email: "",
        fakultasAngkatan: "",
        prodi: "",
        namaBisnis: "",
        kategori: "Kuliner",
        kategoriLainnya: "",
        deskripsi: "",
        alamatUsaha: "",
        fasilitas: "",
        waBisnis: "",
        linkBisnis: "",
        foto: "",
        status: "Approved",
      });
    }
    setIsBisnisModalOpen(true);
  };

  const handleSaveBisnis = async (e: React.FormEvent, forceStatus?: string) => {
    e.preventDefault();
    setIsSaving(true);
    const finalStatus = forceStatus || formData.status;
    const finalKategori =
      formData.kategori === "Lainnya"
        ? formData.kategoriLainnya
        : formData.kategori;
    const payload = {
      ...formData,
      kategori: finalKategori,
      status: finalStatus,
    };

    try {
      let finalId = selectedId;
      if (modalMode === "add") {
        await addDoc(collection(db, "direktori_bisnis"), {
          ...payload,
          createdAt: serverTimestamp(),
        });
        showAlert("Berhasil", "Data bisnis baru berhasil ditambahkan.");
      } else if (selectedId) {
        const currentData = bisnisList.find((b) => b.id === selectedId);
        if (currentData?.isPendingCol && forceStatus === "Approved") {
          const newDocRef = await addDoc(collection(db, "direktori_bisnis"), {
            ...payload,
            createdAt: serverTimestamp(),
          });
          finalId = newDocRef.id;
          await deleteDoc(doc(db, "pendaftaran_bisnis", selectedId));
        } else if (currentData?.isPendingCol) {
          await updateDoc(doc(db, "pendaftaran_bisnis", selectedId), {
            ...payload,
          });
        } else {
          await updateDoc(doc(db, "direktori_bisnis", selectedId), {
            ...payload,
          });
        }

        if (forceStatus === "Approved") {
          const emailSuccess = await sendEmailAPI(
            "approve_bisnis",
            formData.email,
            formData.namaAlumni,
            { id: finalId, namaBisnis: formData.namaBisnis },
          );
          await updateDoc(doc(db, "direktori_bisnis", finalId!), {
            emailSent: emailSuccess,
          });
          if (emailSuccess) {
            showAlert(
              "Disetujui",
              "Bisnis berhasil ditayangkan dan email notifikasi telah terkirim.",
            );
          } else {
            showAlert(
              "Peringatan Sistem",
              "Bisnis ditayangkan, NAMUN gagal mengirim email. Tombol 'Kirim Ulang' diaktifkan di menu Edit.",
            );
          }
        } else if (!forceStatus) {
          showAlert("Berhasil", "Data bisnis berhasil diperbarui.");
        }
      }
      setIsBisnisModalOpen(false);
      fetchData();
    } catch (error) {
      showAlert("Gagal", "Terjadi kesalahan saat menyimpan data.");
    } finally {
      setIsSaving(false);
    }
  };

  const handleRejectBisnis = () => {
    showPrompt(
      "Tolak Pendaftaran",
      "Masukkan alasan penolakan (akan dikirim ke email pendaftar):",
      async (alasan) => {
        if (!alasan) return;
        closeDialog();
        setIsSaving(true);
        try {
          const currentData = bisnisList.find((b) => b.id === selectedId);
          const payload = {
            ...formData,
            status: "Ditolak",
            alasanPenolakan: alasan,
          };
          let targetId = selectedId!;

          if (currentData?.isPendingCol) {
            const newRef = await addDoc(collection(db, "direktori_bisnis"), {
              ...payload,
              createdAt: serverTimestamp(),
            });
            targetId = newRef.id;
            await deleteDoc(doc(db, "pendaftaran_bisnis", selectedId!));
          } else {
            await updateDoc(doc(db, "direktori_bisnis", selectedId!), payload);
          }

          const emailSuccess = await sendEmailAPI(
            "reject_bisnis",
            formData.email,
            formData.namaAlumni,
            { namaBisnis: formData.namaBisnis, alasan },
          );
          await updateDoc(doc(db, "direktori_bisnis", targetId), {
            emailSent: emailSuccess,
          });

          setIsBisnisModalOpen(false);
          fetchData();
          setTimeout(() => {
            if (emailSuccess)
              showAlert(
                "Ditolak",
                "Pendaftaran ditolak dan email pemberitahuan dikirim.",
              );
            else
              showAlert(
                "Peringatan Sistem",
                "Pendaftaran ditolak, NAMUN gagal mengirim email penolakan.",
              );
          }, 300);
        } catch (error) {
          showAlert("Gagal", "Terjadi kesalahan sistem.");
        } finally {
          setIsSaving(false);
        }
      },
    );
  };

  const handleResendBisnisEmail = async (b: any) => {
    showConfirm(
      "Kirim Ulang Notifikasi",
      `Kirim ulang email notifikasi (${b.status === "Approved" ? "Disetujui" : "Ditolak"}) ke ${b.email || b.emailPemilik}?`,
      async () => {
        closeDialog();
        setIsSendingMail(b.id);
        try {
          let emailSuccess = false;
          if (b.status === "Approved") {
            emailSuccess = await sendEmailAPI(
              "approve_bisnis",
              b.email || b.emailPemilik,
              b.namaAlumni || b.owner,
              { id: b.id, namaBisnis: b.namaBisnis || b.nama },
            );
          } else if (b.status === "Ditolak") {
            emailSuccess = await sendEmailAPI(
              "reject_bisnis",
              b.email || b.emailPemilik,
              b.namaAlumni || b.owner,
              {
                namaBisnis: b.namaBisnis || b.nama,
                alasan: b.alasanPenolakan || "Tidak memenuhi kriteria.",
              },
            );
          }

          if (emailSuccess) {
            await updateDoc(doc(db, "direktori_bisnis", b.id), {
              emailSent: true,
            });
            fetchData();
            setTimeout(
              () =>
                showAlert(
                  "Terkirim",
                  "Email notifikasi berhasil dikirim ulang!",
                ),
              300,
            );
          } else {
            showAlert(
              "Gagal Mengirim",
              "Sistem server menolak pengiriman email.",
            );
          }
        } catch (error) {
          showAlert(
            "Kesalahan",
            "Terjadi kesalahan sistem saat mengirim email.",
          );
        } finally {
          setIsSendingMail(null);
        }
      },
    );
  };

  const handleDeleteBisnis = (id: string, nama: string) => {
    showConfirm(
      "Hapus Permanen",
      `Yakin ingin menghapus data bisnis "${nama}"?`,
      async () => {
        closeDialog();
        try {
          const currentData = bisnisList.find((b) => b.id === id);
          await deleteDoc(
            doc(
              db,
              currentData?.isPendingCol
                ? "pendaftaran_bisnis"
                : "direktori_bisnis",
              id,
            ),
          );
          fetchData();
        } catch (error) {
          showAlert("Gagal", "Terjadi kesalahan saat menghapus data.");
        }
      },
    );
  };

  const handleBulkDeleteBisnis = () => {
    showConfirm(
      "Hapus Terpilih",
      `Yakin menghapus ${selectedIds.length} data bisnis terpilih?`,
      async () => {
        closeDialog();
        setIsSaving(true);
        try {
          await Promise.all(
            selectedIds.map((id) => {
              const currentData = bisnisList.find((b) => b.id === id);
              return deleteDoc(
                doc(
                  db,
                  currentData?.isPendingCol
                    ? "pendaftaran_bisnis"
                    : "direktori_bisnis",
                  id,
                ),
              );
            }),
          );
          setSelectedIds([]);
          fetchData();
          setTimeout(
            () =>
              showAlert("Berhasil", "Data bisnis terpilih berhasil dihapus."),
            300,
          );
        } catch (error) {
          showAlert("Gagal", "Terjadi kesalahan saat menghapus data massal.");
        } finally {
          setIsSaving(false);
        }
      },
    );
  };

  const handleExportExcel = () => {
    const dataExport = masterList.map((d, i) => ({
      No: i + 1,
      "Nama Bisnis": d.namaBisnis || d.nama,
      Kategori: d.kategori,
      "Pemilik (Alumni)": d.namaAlumni || d.owner,
      Email: d.email || d.emailPemilik,
      "No. WhatsApp": d.waBisnis || d.noWA || d.wa,
      "Fakultas/Angkatan": d.fakultasAngkatan,
      Prodi: d.prodi,
      Alamat: d.alamatUsaha,
      Fasilitas: d.fasilitas,
      Status: d.status,
    }));
    const ws = XLSX.utils.json_to_sheet(dataExport);
    const wb = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(wb, ws, "Direktori_Live");
    XLSX.writeFile(wb, "Data_Direktori_Bisnis_IKA_UII.xlsx");
  };

  // --- LOGIKA IKLAN ---
  const openIklanModal = (
    mode: "add" | "edit" | "review" = "add",
    data: any = null,
  ) => {
    setIklanModalMode(mode);
    if (data) {
      setSelectedId(data.id);
      setIklanData({
        namaSponsor: data.namaSponsor || "",
        emailSponsor: data.emailSponsor || "",
        noWA: data.noWA || "",
        fotoUrl: data.fotoUrl || "",
        linkTujuan: data.linkTujuan || "",
        tanggalBerakhir: data.tanggalBerakhir || "",
        isActive: data.isActive ?? true,
        status: data.status || "Pending",
      });
    } else {
      setSelectedId(null);
      setIklanData({
        namaSponsor: "",
        emailSponsor: "",
        noWA: "",
        fotoUrl: "",
        linkTujuan: "",
        tanggalBerakhir: "",
        isActive: true,
        status: "Approved",
      });
    }
    setIsIklanModalOpen(true);
  };

  const handleSaveIklan = async (e: React.FormEvent, forceStatus?: string) => {
    e.preventDefault();
    setIsSaving(true);
    const finalStatus = forceStatus || iklanData.status || "Approved";
    const payload = {
      ...iklanData,
      status: finalStatus,
      isActive: finalStatus === "Approved",
    };

    try {
      if (iklanModalMode === "add") {
        await addDoc(collection(db, "iklan_direktori"), {
          ...payload,
          createdAt: serverTimestamp(),
        });
        showAlert("Berhasil", "Data banner iklan baru berhasil ditambahkan.");
      } else if (selectedId) {
        const currentData = iklanList.find((i) => i.id === selectedId);

        if (currentData?.isPendingCol && forceStatus === "Approved") {
          await addDoc(collection(db, "iklan_direktori"), {
            ...payload,
            createdAt: serverTimestamp(),
          });
          await deleteDoc(doc(db, "pendaftaran_iklan", selectedId));
          showAlert(
            "Disetujui",
            "Permohonan iklan berhasil disetujui dan dipindah ke daftar aktif.",
          );
        } else if (currentData?.isPendingCol) {
          await updateDoc(doc(db, "pendaftaran_iklan", selectedId), payload);
          showAlert("Berhasil", "Data permohonan berhasil diperbarui.");
        } else {
          await updateDoc(doc(db, "iklan_direktori", selectedId), payload);
          showAlert("Berhasil", "Data banner iklan berhasil diperbarui.");
        }
      }
      setIsIklanModalOpen(false);
      fetchData();
    } catch (error) {
      showAlert("Gagal", "Terjadi kesalahan saat menyimpan banner.");
    } finally {
      setIsSaving(false);
    }
  };

  const handleRejectIklan = () => {
    showPrompt(
      "Tolak Permohonan Iklan",
      "Masukkan alasan penolakan untuk pengiklan:",
      async (alasan) => {
        if (!alasan) return;
        closeDialog();
        setIsSaving(true);
        try {
          const currentData = iklanList.find((i) => i.id === selectedId);
          const payload = {
            ...iklanData,
            status: "Ditolak",
            alasanPenolakan: alasan,
          };

          if (currentData?.isPendingCol) {
            await addDoc(collection(db, "iklan_direktori"), {
              ...payload,
              createdAt: serverTimestamp(),
            });
            await deleteDoc(doc(db, "pendaftaran_iklan", selectedId!));
          } else {
            await updateDoc(doc(db, "iklan_direktori", selectedId!), payload);
          }
          setIsIklanModalOpen(false);
          fetchData();
          setTimeout(
            () =>
              showAlert(
                "Ditolak",
                "Permohonan iklan telah ditolak dan diarsipkan.",
              ),
            300,
          );
        } catch (error) {
          showAlert("Gagal", "Terjadi kesalahan sistem.");
        } finally {
          setIsSaving(false);
        }
      },
    );
  };

  const handleSendIklanEmail = async (iklan: any) => {
    showConfirm(
      "Kirim Bukti Tayang",
      `Email pemberitahuan akan dikirim ke ${iklan.emailSponsor}. Lanjutkan?`,
      async () => {
        closeDialog();
        setIsSendingMail(iklan.id);
        try {
          const emailSuccess = await sendEmailAPI(
            "iklan_tayang",
            iklan.emailSponsor,
            iklan.namaSponsor,
            { tanggalBerakhir: iklan.tanggalBerakhir },
          );
          if (emailSuccess) {
            await updateDoc(doc(db, "iklan_direktori", iklan.id), {
              emailSent: true,
            });
            fetchData();
            setTimeout(
              () =>
                showAlert(
                  "Terkirim",
                  "Email bukti tayang berhasil dikirim ke sponsor.",
                ),
              300,
            );
          } else {
            showAlert(
              "Gagal Mengirim",
              "Sistem server menolak pengiriman email. Cek kredensial SMTP Anda.",
            );
          }
        } catch (error) {
          showAlert(
            "Gagal",
            "Sistem gagal mengeksekusi proses pengiriman email.",
          );
        } finally {
          setIsSendingMail(null);
        }
      },
    );
  };

  const toggleIklanStatus = async (id: string, currentStatus: boolean) => {
    await updateDoc(doc(db, "iklan_direktori", id), {
      isActive: !currentStatus,
    });
    fetchData();
  };

  const handleDeleteIklan = (id: string) => {
    showConfirm(
      "Hapus Banner",
      "Yakin ingin menghapus banner iklan ini secara permanen?",
      async () => {
        closeDialog();
        const currentData = iklanList.find((i) => i.id === id);
        await deleteDoc(
          doc(
            db,
            currentData?.isPendingCol ? "pendaftaran_iklan" : "iklan_direktori",
            id,
          ),
        );
        fetchData();
      },
    );
  };

  // --- LOGIKA MERCHANDISE ---
  const handleUpdateStatusMerch = async (id: string, newStatus: string) => {
    try {
      await updateDoc(doc(db, "usulan_merch", id), { status: newStatus });
      fetchData();
    } catch (error) {
      showAlert("Gagal", "Terjadi kesalahan saat mengupdate status usulan.");
    }
  };

  const handleDeleteMerch = (id: string) => {
    showConfirm(
      "Hapus Usulan",
      "Yakin ingin menghapus usulan merchandise ini?",
      async () => {
        closeDialog();
        try {
          await deleteDoc(doc(db, "usulan_merch", id));
          fetchData();
        } catch (error) {
          showAlert("Gagal", "Gagal menghapus data usulan.");
        }
      },
    );
  };

  return (
    <div className="min-h-screen bg-[#F8F9FA] pb-12 font-sans text-[#202124]">
      {/* CUSTOM DIALOG */}
      {dialog.isOpen && (
        <div className="fixed inset-0 z-[200] flex items-center justify-center p-4 bg-slate-900/40 backdrop-blur-sm animate-in fade-in duration-200">
          <div className="bg-white rounded-lg w-full max-w-sm shadow-2xl flex flex-col overflow-hidden border border-[#DADCE0] animate-in zoom-in-95">
            <div className="px-6 py-5">
              <h2
                className={`text-lg font-medium mb-2 ${dialog.title.includes("Gagal") || dialog.title.includes("Tolak") || dialog.title.includes("Hapus") || dialog.title.includes("Peringatan") ? "text-[#D93025]" : "text-[#1A73E8]"}`}
              >
                {dialog.title}
              </h2>
              <p className="text-sm text-[#5F6368] leading-relaxed">
                {dialog.message}
              </p>
              {dialog.type === "prompt" && (
                <textarea
                  id="promptInput"
                  rows={3}
                  className="w-full mt-3 px-3 py-2 border border-[#DADCE0] rounded focus:border-[#D93025] outline-none text-sm resize-none"
                  placeholder="Ketik alasan penolakan..."
                ></textarea>
              )}
            </div>
            <div className="px-6 py-4 bg-[#F8F9FA] border-t border-[#DADCE0] flex justify-end gap-3">
              {(dialog.type === "confirm" || dialog.type === "prompt") && (
                <button
                  onClick={closeDialog}
                  className="px-4 py-2 text-sm font-medium text-[#5F6368] hover:bg-[#E8EAED] rounded transition-colors"
                >
                  Batal
                </button>
              )}
              <button
                onClick={() => {
                  if (dialog.type === "prompt" && dialog.onConfirm) {
                    const val = (
                      document.getElementById(
                        "promptInput",
                      ) as HTMLTextAreaElement
                    ).value;
                    dialog.onConfirm(val);
                  } else if (dialog.type === "confirm" && dialog.onConfirm) {
                    dialog.onConfirm();
                  } else {
                    closeDialog();
                  }
                }}
                className={`px-5 py-2 text-sm font-medium text-white rounded transition-colors shadow-sm ${dialog.title.includes("Hapus") || dialog.title.includes("Tolak") ? "bg-[#D93025] hover:bg-[#b52a1f]" : "bg-[#1A73E8] hover:bg-[#1557B0]"}`}
              >
                {dialog.type === "confirm" || dialog.type === "prompt"
                  ? dialog.title.includes("Hapus") ||
                    dialog.title.includes("Tolak")
                    ? "Lanjutkan"
                    : "Ya, Lanjutkan"
                  : "Mengerti"}
              </button>
            </div>
          </div>
        </div>
      )}

      <div className="max-w-7xl mx-auto px-4 sm:px-6 pt-8">
        {/* HEADER SECTION */}
        <div className="flex flex-col md:flex-row md:items-end justify-between gap-4 mb-6">
          <div>
            <h1 className="text-3xl font-medium text-[#202124] mb-1 tracking-tight">
              Manajemen Direktori & Iklan
            </h1>
            <p className="text-[#5F6368] text-sm">
              Kelola pendaftaran bisnis, Banner Iklan, dan Usulan Merchandise
              Alumni.
            </p>
          </div>
        </div>

        {/* WORKSPACE TABS NAVIGATION */}
        <div className="flex border-b border-[#DADCE0] mb-6 overflow-x-auto no-scrollbar">
          <button
            onClick={() => handleTabChange("antrean")}
            className={`px-6 py-3 text-sm font-medium whitespace-nowrap transition-colors border-b-2 ${activeTab === "antrean" ? "border-[#1A73E8] text-[#1A73E8]" : "border-transparent text-[#5F6368] hover:text-[#202124] hover:bg-slate-50"}`}
          >
            Antrean Pendaftar
            <span className="ml-2 bg-[#D93025] text-white text-[10px] px-1.5 py-0.5 rounded-full">
              {pendingList.length}
            </span>
          </button>
          <button
            onClick={() => handleTabChange("master")}
            className={`px-6 py-3 text-sm font-medium whitespace-nowrap transition-colors border-b-2 ${activeTab === "master" ? "border-[#1A73E8] text-[#1A73E8]" : "border-transparent text-[#5F6368] hover:text-[#202124] hover:bg-slate-50"}`}
          >
            Master Data (Live)
          </button>
          <button
            onClick={() => handleTabChange("iklan")}
            className={`px-6 py-3 text-sm font-medium whitespace-nowrap transition-colors border-b-2 ${activeTab === "iklan" ? "border-[#1A73E8] text-[#1A73E8]" : "border-transparent text-[#5F6368] hover:text-[#202124] hover:bg-slate-50"}`}
          >
            Kelola Banner Iklan
            {pendingIklanList.length > 0 && (
              <span className="ml-2 bg-yellow-500 text-white text-[10px] px-1.5 py-0.5 rounded-full">
                {pendingIklanList.length}
              </span>
            )}
          </button>
          <button
            onClick={() => handleTabChange("merch")}
            className={`px-6 py-3 text-sm font-medium whitespace-nowrap transition-colors border-b-2 ${activeTab === "merch" ? "border-[#1A73E8] text-[#1A73E8]" : "border-transparent text-[#5F6368] hover:text-[#202124] hover:bg-slate-50"}`}
          >
            Usulan Merch
            {usulanMerchList.filter((m) => m.status === "Baru").length > 0 && (
              <span className="ml-2 bg-yellow-500 text-white text-[10px] px-1.5 py-0.5 rounded-full">
                {usulanMerchList.filter((m) => m.status === "Baru").length}
              </span>
            )}
          </button>
        </div>

        {isLoading && (
          <div className="flex justify-center items-center py-20">
            <div className="w-8 h-8 border-4 border-[#E8F0FE] border-t-[#1A73E8] rounded-full animate-spin"></div>
          </div>
        )}

        {/* TAB 1: ANTREAN PENDAFTAR (BISNIS) */}
        {!isLoading && activeTab === "antrean" && (
          <div className="bg-white rounded-xl border border-[#DADCE0] shadow-sm overflow-hidden animate-in fade-in">
            <div className="p-4 border-b border-[#DADCE0] bg-[#F8F9FA] flex justify-between items-center">
              <h2 className="font-medium text-[13px] text-[#5F6368] uppercase tracking-wider">
                Menunggu Verifikasi Admin
              </h2>
              {selectedIds.length > 0 && (
                <button
                  onClick={handleBulkDeleteBisnis}
                  className="bg-white border border-[#FCE8E6] text-[#D93025] hover:bg-[#FCE8E6] px-3 py-1.5 rounded text-xs font-medium flex items-center gap-1.5 transition-colors shadow-sm"
                >
                  <svg
                    className="w-3.5 h-3.5"
                    fill="none"
                    viewBox="0 0 24 24"
                    stroke="currentColor"
                  >
                    <path
                      strokeLinecap="round"
                      strokeLinejoin="round"
                      strokeWidth={2}
                      d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16"
                    />
                  </svg>
                  Hapus Terpilih ({selectedIds.length})
                </button>
              )}
            </div>
            <div className="overflow-x-auto">
              <table className="w-full text-left text-sm">
                <thead className="border-b border-[#DADCE0] text-[#5F6368] bg-white">
                  <tr>
                    <th className="px-6 py-3 w-10 text-center border-r border-[#DADCE0]">
                      <input
                        type="checkbox"
                        onChange={(e) => handleSelectAll(e, pendingList)}
                        checked={
                          pendingList.length > 0 &&
                          selectedIds.length === pendingList.length
                        }
                        className="rounded border-[#DADCE0] text-[#1A73E8] focus:ring-[#1A73E8] cursor-pointer"
                      />
                    </th>
                    <th className="px-6 py-3 font-medium w-1/3">
                      Informasi Bisnis
                    </th>
                    <th className="px-6 py-3 font-medium w-1/3">
                      Data Pendaftar
                    </th>
                    <th className="px-6 py-3 font-medium text-center">
                      Status
                    </th>
                    <th className="px-6 py-3 font-medium text-right">Aksi</th>
                  </tr>
                </thead>
                <tbody className="divide-y divide-[#DADCE0]">
                  {pendingList.length === 0 ? (
                    <tr>
                      <td
                        colSpan={5}
                        className="text-center py-10 text-[#9AA0A6]"
                      >
                        Tidak ada pendaftar baru.
                      </td>
                    </tr>
                  ) : (
                    pendingList.map((b) => (
                      <tr
                        key={b.id}
                        className="hover:bg-[#F8F9FA] transition-colors"
                      >
                        <td className="px-6 py-4 text-center border-r border-slate-50 align-middle">
                          <input
                            type="checkbox"
                            checked={selectedIds.includes(b.id)}
                            onChange={(e) => handleSelectOne(e, b.id)}
                            className="rounded border-[#DADCE0] text-[#1A73E8] focus:ring-[#1A73E8] cursor-pointer"
                          />
                        </td>
                        <td className="px-6 py-4 align-top">
                          <p className="font-bold text-[#1A73E8] mb-1">
                            {b.namaBisnis}
                          </p>
                          <span className="text-[10px] bg-[#E8F0FE] text-[#1A73E8] px-2 py-0.5 rounded border border-[#1A73E8]/20">
                            {b.kategori}
                          </span>
                          <p className="text-xs text-[#5F6368] mt-2 line-clamp-2">
                            {b.deskripsi}
                          </p>
                        </td>
                        <td className="px-6 py-4 align-top">
                          <p className="font-bold text-[#202124]">
                            {b.namaAlumni || b.owner}
                          </p>
                          <p className="text-xs text-[#5F6368] font-mono mb-1">
                            {b.emailPemilik || b.email}
                          </p>
                          <p className="text-[11px] text-[#5F6368]">
                            WA: {b.noWA || b.waBisnis}
                          </p>
                        </td>
                        <td className="px-6 py-4 text-center align-middle">
                          <span className="text-[10px] font-bold bg-[#FEF7E0] text-[#B06000] border border-[#FCE8B2] px-2.5 py-1 rounded">
                            PENDING
                          </span>
                        </td>
                        <td className="px-6 py-4 text-right align-middle">
                          <button
                            onClick={() => openBisnisModal("review", b)}
                            className="bg-white border border-[#DADCE0] hover:bg-[#E8F0FE] hover:text-[#1A73E8] text-[#5F6368] px-4 py-1.5 rounded text-xs font-medium transition-colors"
                          >
                            Review & Eksekusi
                          </button>
                        </td>
                      </tr>
                    ))
                  )}
                </tbody>
              </table>
            </div>
          </div>
        )}

        {/* TAB 2: MASTER DATA BISNIS */}
        {!isLoading && activeTab === "master" && (
          <div className="bg-white rounded-xl border border-[#DADCE0] shadow-sm overflow-hidden animate-in fade-in">
            <div className="p-4 border-b border-[#DADCE0] bg-[#F8F9FA] flex justify-between items-center">
              <h2 className="font-medium text-[13px] text-[#5F6368] uppercase tracking-wider">
                Database Bisnis Publik
              </h2>
              <div className="flex gap-2 items-center">
                {selectedIds.length > 0 && (
                  <button
                    onClick={handleBulkDeleteBisnis}
                    className="bg-white border border-[#FCE8E6] text-[#D93025] hover:bg-[#FCE8E6] px-3 py-1.5 rounded text-xs font-medium flex items-center gap-1.5 transition-colors shadow-sm mr-2"
                  >
                    <svg
                      className="w-3.5 h-3.5"
                      fill="none"
                      viewBox="0 0 24 24"
                      stroke="currentColor"
                    >
                      <path
                        strokeLinecap="round"
                        strokeLinejoin="round"
                        strokeWidth={2}
                        d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16"
                      />
                    </svg>{" "}
                    Hapus ({selectedIds.length})
                  </button>
                )}
                <button
                  onClick={handleExportExcel}
                  className="bg-white border border-[#DADCE0] hover:bg-[#E6F4EA] text-[#1E8E3E] px-3 py-1.5 rounded text-xs font-medium flex items-center gap-1.5 transition-colors"
                >
                  <svg
                    className="w-3.5 h-3.5"
                    fill="none"
                    viewBox="0 0 24 24"
                    stroke="currentColor"
                  >
                    <path
                      strokeLinecap="round"
                      strokeLinejoin="round"
                      strokeWidth={2}
                      d="M12 10v6m0 0l-3-3m3 3l3-3m2 8H7a2 2 0 01-2-2V5a2 2 0 012-2h5.586a1 1 0 01.707.293l5.414 5.414a1 1 0 01.293.707V19a2 2 0 01-2 2z"
                    />
                  </svg>{" "}
                  Unduh Excel
                </button>
                <button
                  onClick={() => openBisnisModal("add")}
                  className="bg-[#1A73E8] hover:bg-[#1557B0] text-white px-3 py-1.5 rounded text-xs font-medium flex items-center gap-1.5 transition-colors"
                >
                  <svg
                    className="w-3.5 h-3.5"
                    fill="none"
                    viewBox="0 0 24 24"
                    stroke="currentColor"
                  >
                    <path
                      strokeLinecap="round"
                      strokeLinejoin="round"
                      strokeWidth={2}
                      d="M12 4v16m8-8H4"
                    />
                  </svg>{" "}
                  Tambah Manual
                </button>
              </div>
            </div>
            <div className="overflow-x-auto">
              <table className="w-full text-left text-sm">
                <thead className="border-b border-[#DADCE0] text-[#5F6368] bg-white">
                  <tr>
                    <th className="px-6 py-3 w-10 text-center border-r border-[#DADCE0]">
                      <input
                        type="checkbox"
                        onChange={(e) => handleSelectAll(e, masterList)}
                        checked={
                          masterList.length > 0 &&
                          selectedIds.length === masterList.length
                        }
                        className="rounded border-[#DADCE0] text-[#1A73E8] focus:ring-[#1A73E8] cursor-pointer"
                      />
                    </th>
                    <th className="px-6 py-3 font-medium">Bisnis</th>
                    <th className="px-6 py-3 font-medium">Pemilik</th>
                    <th className="px-6 py-3 font-medium text-center">
                      Status
                    </th>
                    <th className="px-6 py-3 font-medium text-right">Aksi</th>
                  </tr>
                </thead>
                <tbody className="divide-y divide-[#DADCE0]">
                  {masterList.length === 0 ? (
                    <tr>
                      <td
                        colSpan={5}
                        className="text-center py-10 text-[#9AA0A6]"
                      >
                        Belum ada data bisnis.
                      </td>
                    </tr>
                  ) : (
                    masterList.map((b) => (
                      <tr
                        key={b.id}
                        className="hover:bg-[#F8F9FA] transition-colors"
                      >
                        <td className="px-6 py-4 text-center border-r border-slate-50 align-middle">
                          <input
                            type="checkbox"
                            checked={selectedIds.includes(b.id)}
                            onChange={(e) => handleSelectOne(e, b.id)}
                            className="rounded border-[#DADCE0] text-[#1A73E8] focus:ring-[#1A73E8] cursor-pointer"
                          />
                        </td>
                        <td className="px-6 py-4">
                          <div className="flex items-center gap-3">
                            <img
                              src={b.foto || b.fotoUrl || "/logo-dpp-ika.png"}
                              alt="foto"
                              className="w-10 h-10 rounded object-cover border border-[#DADCE0]"
                            />
                            <div>
                              <p className="font-bold text-[#202124]">
                                {b.namaBisnis || b.nama}
                              </p>
                              <span className="text-[10px] text-[#5F6368] uppercase">
                                {b.kategori}
                              </span>
                            </div>
                          </div>
                        </td>
                        <td className="px-6 py-4">
                          <p className="font-medium text-[#202124]">
                            {b.namaAlumni || b.owner}
                          </p>
                          <p className="text-[11px] text-[#5F6368]">
                            {b.noWA || b.waBisnis}
                          </p>
                        </td>
                        <td className="px-6 py-4 text-center">
                          {b.status === "Ditolak" ? (
                            <span className="text-[10px] font-bold bg-[#FCE8E6] text-[#D93025] border border-[#FAD2CF] px-2 py-0.5 rounded">
                              DITOLAK
                            </span>
                          ) : (
                            <span className="text-[10px] font-bold bg-[#E6F4EA] text-[#1E8E3E] border border-[#CEEAD6] px-2 py-0.5 rounded">
                              LIVE
                            </span>
                          )}
                        </td>
                        <td className="px-6 py-4 text-right">
                          <div className="flex justify-end gap-2 items-center">
                            {b.emailSent === true && (
                              <span
                                className="text-[10px] font-bold text-[#1E8E3E] bg-[#E6F4EA] px-2 py-1 rounded flex items-center gap-1 border border-[#CEEAD6]"
                                title="Email notifikasi berhasil terkirim"
                              >
                                <svg
                                  className="w-3 h-3"
                                  fill="none"
                                  viewBox="0 0 24 24"
                                  stroke="currentColor"
                                >
                                  <path
                                    strokeLinecap="round"
                                    strokeLinejoin="round"
                                    strokeWidth={3}
                                    d="M5 13l4 4L19 7"
                                  />
                                </svg>{" "}
                                Terkirim
                              </span>
                            )}
                            <button
                              onClick={() => openBisnisModal("edit", b)}
                              className="p-1.5 text-[#5F6368] hover:text-[#1A73E8] hover:bg-[#E8F0FE] rounded transition-colors"
                            >
                              <svg
                                className="w-4 h-4"
                                fill="none"
                                viewBox="0 0 24 24"
                                stroke="currentColor"
                              >
                                <path
                                  strokeLinecap="round"
                                  strokeLinejoin="round"
                                  strokeWidth={2}
                                  d="M15.232 5.232l3.536 3.536m-2.036-5.036a2.5 2.5 0 113.536 3.536L6.5 21.036H3v-3.572L16.732 3.732z"
                                />
                              </svg>
                            </button>
                            <button
                              onClick={() =>
                                handleDeleteBisnis(b.id, b.namaBisnis)
                              }
                              className="p-1.5 text-[#5F6368] hover:text-[#D93025] hover:bg-[#FCE8E6] rounded transition-colors"
                            >
                              <svg
                                className="w-4 h-4"
                                fill="none"
                                viewBox="0 0 24 24"
                                stroke="currentColor"
                              >
                                <path
                                  strokeLinecap="round"
                                  strokeLinejoin="round"
                                  strokeWidth={2}
                                  d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16"
                                />
                              </svg>
                            </button>
                          </div>
                        </td>
                      </tr>
                    ))
                  )}
                </tbody>
              </table>
            </div>
          </div>
        )}

        {/* TAB 3: KELOLA IKLAN */}
        {!isLoading && activeTab === "iklan" && (
          <div className="space-y-6 animate-in fade-in">
            {/* Tabel Pendaftaran Iklan Baru */}
            {pendingIklanList.length > 0 && (
              <div className="bg-white rounded-xl border border-[#DADCE0] shadow-sm overflow-hidden">
                <div className="p-4 border-b border-[#DADCE0] bg-[#FFF8E1] flex justify-between items-center">
                  <h2 className="font-medium text-[13px] text-[#E65100] uppercase tracking-wider flex items-center gap-2">
                    <svg
                      className="w-4 h-4"
                      fill="none"
                      viewBox="0 0 24 24"
                      stroke="currentColor"
                    >
                      <path
                        strokeLinecap="round"
                        strokeLinejoin="round"
                        strokeWidth={2}
                        d="M12 9v2m0 4h.01m-6.938 4h13.856c1.54 0 2.502-1.667 1.732-3L13.732 4c-.77-1.333-2.694-1.333-3.464 0L3.34 16c-.77 1.333.192 3 1.732 3z"
                      />
                    </svg>
                    Permohonan Iklan Baru ({pendingIklanList.length})
                  </h2>
                </div>
                <div className="overflow-x-auto">
                  <table className="w-full text-left text-sm">
                    <thead className="border-b border-[#DADCE0] text-[#5F6368] bg-white">
                      <tr>
                        <th className="px-6 py-3 font-medium">Sponsor</th>
                        <th className="px-6 py-3 font-medium">Link Tujuan</th>
                        <th className="px-6 py-3 font-medium text-center">
                          Status
                        </th>
                        <th className="px-6 py-3 font-medium text-right">
                          Aksi
                        </th>
                      </tr>
                    </thead>
                    <tbody className="divide-y divide-[#DADCE0]">
                      {pendingIklanList.map((iklan) => (
                        <tr
                          key={iklan.id}
                          className="hover:bg-[#F8F9FA] transition-colors"
                        >
                          <td className="px-6 py-4">
                            <div className="flex items-center gap-3">
                              <img
                                src={iklan.fotoUrl || "/logo-dpp-ika.png"}
                                alt="foto"
                                className="w-12 h-8 rounded object-cover border border-[#DADCE0]"
                              />
                              <div>
                                <p className="font-bold text-[#1A73E8]">
                                  {iklan.namaSponsor}
                                </p>
                                <p className="text-[10px] text-[#5F6368]">
                                  {iklan.emailSponsor} | {iklan.noWA}
                                </p>
                              </div>
                            </div>
                          </td>
                          <td className="px-6 py-4">
                            <a
                              href={iklan.linkTujuan}
                              target="_blank"
                              className="text-[#1A73E8] hover:underline truncate max-w-[200px] block"
                            >
                              {iklan.linkTujuan}
                            </a>
                          </td>
                          <td className="px-6 py-4 text-center">
                            <span className="text-[10px] font-bold bg-[#FEF7E0] text-[#B06000] border border-[#FCE8B2] px-2.5 py-1 rounded">
                              MENUNGGU
                            </span>
                          </td>
                          <td className="px-6 py-4 text-right">
                            <button
                              onClick={() => openIklanModal("review", iklan)}
                              className="bg-white border border-[#DADCE0] hover:bg-[#E8F0FE] hover:text-[#1A73E8] text-[#5F6368] px-4 py-1.5 rounded text-xs font-medium transition-colors"
                            >
                              Review & Tayangkan
                            </button>
                          </td>
                        </tr>
                      ))}
                    </tbody>
                  </table>
                </div>
              </div>
            )}

            {/* Grid Master Iklan Aktif */}
            <div className="bg-white rounded-xl border border-[#DADCE0] shadow-sm overflow-hidden">
              <div className="p-4 border-b border-[#DADCE0] bg-[#F8F9FA] flex justify-between items-center">
                <h2 className="font-medium text-[13px] text-[#5F6368] uppercase tracking-wider">
                  Manajemen Slider Publik
                </h2>
                <button
                  onClick={() => openIklanModal("add")}
                  className="bg-[#1A73E8] hover:bg-[#1557B0] text-white px-3 py-1.5 rounded text-xs font-medium flex items-center gap-1.5 transition-colors"
                >
                  <svg
                    className="w-3.5 h-3.5"
                    fill="none"
                    viewBox="0 0 24 24"
                    stroke="currentColor"
                  >
                    <path
                      strokeLinecap="round"
                      strokeLinejoin="round"
                      strokeWidth={2}
                      d="M12 4v16m8-8H4"
                    />
                  </svg>{" "}
                  Tambah Banner
                </button>
              </div>
              <div className="p-6 grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
                {masterIklanList.length === 0 ? (
                  <div className="col-span-full text-center py-10 text-[#9AA0A6] text-sm">
                    Belum ada banner iklan yang disetujui. Slider otomatis
                    disembunyikan.
                  </div>
                ) : (
                  masterIklanList.map((iklan) => (
                    <div
                      key={iklan.id}
                      className="border border-[#DADCE0] rounded-xl overflow-hidden shadow-sm flex flex-col"
                    >
                      <div className="h-32 bg-slate-100 relative">
                        <img
                          src={iklan.fotoUrl}
                          alt="Iklan"
                          className={`w-full h-full object-cover ${!iklan.isActive ? "grayscale opacity-50" : ""}`}
                        />
                        <div className="absolute top-2 right-2 bg-white/90 backdrop-blur px-2 py-0.5 rounded text-[10px] font-bold shadow-sm">
                          {iklan.isActive ? (
                            <span className="text-[#1E8E3E]">AKTIF</span>
                          ) : (
                            <span className="text-[#D93025]">HIDDEN</span>
                          )}
                        </div>
                      </div>
                      <div className="p-4 flex-grow bg-white">
                        <p className="font-bold text-[#202124] text-sm mb-1">
                          {iklan.namaSponsor}
                        </p>
                        <p className="text-[11px] text-[#5F6368] font-mono mb-2">
                          {iklan.emailSponsor}
                        </p>
                        <p className="text-[10px] text-[#D93025] font-bold bg-[#FCE8E6] px-2 py-1 rounded inline-block">
                          Exp: {iklan.tanggalBerakhir}
                        </p>
                      </div>
                      <div className="border-t border-[#DADCE0] bg-[#F8F9FA] p-3 flex gap-2 justify-between">
                        <button
                          onClick={() =>
                            toggleIklanStatus(iklan.id, iklan.isActive)
                          }
                          className="p-1.5 text-[#5F6368] hover:bg-[#E8EAED] rounded transition-colors"
                          title="Toggle Status"
                        >
                          {iklan.isActive ? (
                            <svg
                              className="w-4 h-4"
                              fill="none"
                              viewBox="0 0 24 24"
                              stroke="currentColor"
                            >
                              <path
                                strokeLinecap="round"
                                strokeLinejoin="round"
                                strokeWidth={2}
                                d="M15 12a3 3 0 11-6 0 3 3 0 016 0z"
                              />
                              <path
                                strokeLinecap="round"
                                strokeLinejoin="round"
                                strokeWidth={2}
                                d="M2.458 12C3.732 7.943 7.523 5 12 5c4.478 0 8.268 2.943 9.542 7-1.274 4.057-5.064 7-9.542 7-4.477 0-8.268-2.943-9.542-7z"
                              />
                            </svg>
                          ) : (
                            <svg
                              className="w-4 h-4 text-[#D93025]"
                              fill="none"
                              viewBox="0 0 24 24"
                              stroke="currentColor"
                            >
                              <path
                                strokeLinecap="round"
                                strokeLinejoin="round"
                                strokeWidth={2}
                                d="M13.875 18.825A10.05 10.05 0 0112 19c-4.478 0-8.268-2.943-9.543-7a9.97 9.97 0 011.563-3.029m5.858.908a3 3 0 114.243 4.243M9.878 9.878l4.242 4.242M9.88 9.88l-3.29-3.29m7.532 7.532l3.29 3.29M3 3l3.29 3.29m0 0a9.97 9.97 0 013.03-1.562M21.543 12c-1.274-4.057-5.064-7-9.542-7M21 21l-3.29-3.29"
                              />
                            </svg>
                          )}
                        </button>
                        <div className="flex gap-1 items-center">
                          {iklan.emailSent ? (
                            <span className="text-[10px] text-[#1E8E3E] font-bold flex items-center gap-1">
                              <svg
                                className="w-3 h-3"
                                fill="none"
                                viewBox="0 0 24 24"
                                stroke="currentColor"
                              >
                                <path
                                  strokeLinecap="round"
                                  strokeLinejoin="round"
                                  strokeWidth={3}
                                  d="M5 13l4 4L19 7"
                                />
                              </svg>{" "}
                              Terkirim
                            </span>
                          ) : (
                            <button
                              onClick={() => handleSendIklanEmail(iklan)}
                              disabled={isSendingMail === iklan.id}
                              className="text-[10px] font-bold bg-white border border-[#DADCE0] px-2 py-1 rounded text-[#5F6368] hover:text-[#1A73E8] transition-colors disabled:opacity-50"
                            >
                              {isSendingMail === iklan.id
                                ? "Sending..."
                                : "Kirim Email"}
                            </button>
                          )}
                          <button
                            onClick={() => openIklanModal("edit", iklan)}
                            className="p-1.5 text-[#5F6368] hover:bg-[#E8EAED] rounded transition-colors ml-1"
                          >
                            <svg
                              className="w-4 h-4"
                              fill="none"
                              viewBox="0 0 24 24"
                              stroke="currentColor"
                            >
                              <path
                                strokeLinecap="round"
                                strokeLinejoin="round"
                                strokeWidth={2}
                                d="M15.232 5.232l3.536 3.536m-2.036-5.036a2.5 2.5 0 113.536 3.536L6.5 21.036H3v-3.572L16.732 3.732z"
                              />
                            </svg>
                          </button>
                          <button
                            onClick={() => handleDeleteIklan(iklan.id)}
                            className="p-1.5 text-[#5F6368] hover:text-[#D93025] hover:bg-[#FCE8E6] rounded transition-colors"
                          >
                            <svg
                              className="w-4 h-4"
                              fill="none"
                              viewBox="0 0 24 24"
                              stroke="currentColor"
                            >
                              <path
                                strokeLinecap="round"
                                strokeLinejoin="round"
                                strokeWidth={2}
                                d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16"
                              />
                            </svg>
                          </button>
                        </div>
                      </div>
                    </div>
                  ))
                )}
              </div>
            </div>
          </div>
        )}

        {/* TAB 4: USULAN MERCHANDISE */}
        {!isLoading && activeTab === "merch" && (
          <div className="bg-white rounded-xl border border-[#DADCE0] shadow-sm overflow-hidden animate-in fade-in">
            <div className="p-4 border-b border-[#DADCE0] bg-[#F8F9FA] flex justify-between items-center">
              <h2 className="font-medium text-[13px] text-[#5F6368] uppercase tracking-wider">
                Daftar Usulan Merchandise Anggota
              </h2>
            </div>
            <div className="overflow-x-auto">
              <table className="w-full text-left text-sm">
                <thead className="border-b border-[#DADCE0] text-[#5F6368] bg-white">
                  <tr>
                    <th className="px-6 py-3 font-medium w-1/5">
                      Tanggal & Pendaftar
                    </th>
                    <th className="px-6 py-3 font-medium w-2/5">
                      Usulan / Detail Ide
                    </th>
                    <th className="px-6 py-3 font-medium text-center w-1/5">
                      Update Status
                    </th>
                    <th className="px-6 py-3 font-medium text-right">Aksi</th>
                  </tr>
                </thead>
                <tbody className="divide-y divide-[#DADCE0]">
                  {usulanMerchList.length === 0 ? (
                    <tr>
                      <td
                        colSpan={4}
                        className="text-center py-10 text-[#9AA0A6]"
                      >
                        Belum ada usulan merchandise masuk.
                      </td>
                    </tr>
                  ) : (
                    usulanMerchList.map((merch) => (
                      <tr
                        key={merch.id}
                        className="hover:bg-[#F8F9FA] transition-colors"
                      >
                        <td className="px-6 py-4 align-top">
                          <p className="text-[11px] text-[#5F6368] mb-1 font-mono">
                            {merch.createdAt?.toDate
                              ? merch.createdAt
                                  .toDate()
                                  .toLocaleDateString("id-ID")
                              : new Date(merch.createdAt).toLocaleDateString(
                                  "id-ID",
                                )}
                          </p>
                          <p className="font-bold text-[#202124]">
                            {merch.nama}
                          </p>
                          <p className="text-[11px] text-[#5F6368]">
                            {merch.email}
                          </p>
                        </td>
                        <td className="px-6 py-4 align-top">
                          <p className="text-[#202124] text-sm leading-relaxed whitespace-pre-wrap">
                            {merch.usulan}
                          </p>
                        </td>
                        <td className="px-6 py-4 text-center align-top">
                          <div className="flex justify-center">
                            <select
                              value={merch.status || "Baru"}
                              onChange={async (e) => {
                                try {
                                  await updateDoc(
                                    doc(db, "usulan_merch", merch.id),
                                    { status: e.target.value },
                                  );
                                  fetchData();
                                } catch (error) {
                                  showAlert(
                                    "Gagal",
                                    "Tidak dapat mengupdate status.",
                                  );
                                }
                              }}
                              className={`text-[11px] font-bold px-2 py-1 rounded outline-none border cursor-pointer ${
                                merch.status === "Baru"
                                  ? "bg-blue-50 text-blue-700 border-blue-200"
                                  : merch.status === "Diproses"
                                    ? "bg-amber-50 text-amber-700 border-amber-200"
                                    : merch.status === "Diterima"
                                      ? "bg-emerald-50 text-emerald-700 border-emerald-200"
                                      : "bg-rose-50 text-rose-700 border-rose-200"
                              }`}
                            >
                              <option value="Baru">🌟 Baru</option>
                              <option value="Diproses">⏳ Diproses</option>
                              <option value="Diterima">
                                ✅ Diterima (Akan Diproduksi)
                              </option>
                              <option value="Ditolak">
                                ❌ Ditolak (Arsip)
                              </option>
                            </select>
                          </div>
                        </td>
                        <td className="px-6 py-4 text-right align-top">
                          <button
                            onClick={() => {
                              showConfirm(
                                "Hapus Usulan",
                                "Yakin ingin menghapus usulan ini secara permanen?",
                                async () => {
                                  closeDialog();
                                  await deleteDoc(
                                    doc(db, "usulan_merch", merch.id),
                                  );
                                  fetchData();
                                },
                              );
                            }}
                            className="bg-white border border-[#DADCE0] hover:bg-[#FCE8E6] text-[#D93025] px-3 py-1.5 rounded text-xs font-medium transition-colors inline-flex items-center gap-1.5 shadow-sm"
                          >
                            <svg
                              className="w-3.5 h-3.5"
                              fill="none"
                              viewBox="0 0 24 24"
                              stroke="currentColor"
                            >
                              <path
                                strokeLinecap="round"
                                strokeLinejoin="round"
                                strokeWidth={2}
                                d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16"
                              />
                            </svg>{" "}
                            Hapus
                          </button>
                        </td>
                      </tr>
                    ))
                  )}
                </tbody>
              </table>
            </div>
          </div>
        )}
      </div>

      {/* MODAL FORM BISNIS */}
      {isBisnisModalOpen && (
        <div className="fixed inset-0 bg-slate-900/60 backdrop-blur-sm z-[100] flex items-center justify-center p-4 animate-in fade-in">
          <div className="bg-white rounded-2xl p-6 md:p-8 max-w-2xl w-full shadow-2xl relative max-h-[90vh] overflow-y-auto custom-scrollbar border border-[#DADCE0]">
            <button
              onClick={() => setIsBisnisModalOpen(false)}
              className="absolute top-5 right-5 p-2 bg-slate-50 rounded-full text-slate-500 hover:bg-[#FCE8E6] hover:text-[#D93025] transition-colors z-10"
            >
              <svg
                className="w-5 h-5"
                fill="none"
                viewBox="0 0 24 24"
                stroke="currentColor"
              >
                <path
                  strokeLinecap="round"
                  strokeLinejoin="round"
                  strokeWidth={2.5}
                  d="M6 18L18 6M6 6l12 12"
                />
              </svg>
            </button>
            <div className="mb-6 mt-1 border-b border-[#DADCE0] pb-5 flex items-center gap-3">
              <div
                className={`w-12 h-12 rounded-xl flex items-center justify-center shrink-0 ${modalMode === "review" ? "bg-[#FEF7E0] text-[#B06000]" : "bg-[#E8F0FE] text-[#1A73E8]"}`}
              >
                <svg
                  className="w-6 h-6"
                  fill="none"
                  viewBox="0 0 24 24"
                  stroke="currentColor"
                >
                  <path
                    strokeLinecap="round"
                    strokeLinejoin="round"
                    strokeWidth={2}
                    d="M9 12h6m-6 4h6m2 5H7a2 2 0 01-2-2V5a2 2 0 012-2h5.586a1 1 0 01.707.293l5.414 5.414a1 1 0 01.293.707V19a2 2 0 01-2 2z"
                  />
                </svg>
              </div>
              <div>
                <h3 className="text-xl font-bold text-[#202124] leading-tight">
                  {modalMode === "review"
                    ? "Review Data Pendaftar"
                    : modalMode === "add"
                      ? "Tambah Bisnis Manual"
                      : "Edit Data Bisnis"}
                </h3>
                <p className="text-xs text-[#5F6368] mt-0.5">
                  {modalMode === "review"
                    ? "Perbaiki typo / redaksi sebelum menyetujui penayangan."
                    : "Isi form di bawah ini dengan lengkap."}
                </p>
              </div>
            </div>

            <form onSubmit={(e) => handleSaveBisnis(e)} className="space-y-4">
              <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                <div>
                  <label className="block text-[11px] font-bold text-[#5F6368] uppercase tracking-widest mb-1.5">
                    Nama Pemilik
                  </label>
                  <input
                    required
                    type="text"
                    value={formData.namaAlumni}
                    onChange={(e) =>
                      setFormData({ ...formData, namaAlumni: e.target.value })
                    }
                    className="w-full px-3.5 py-2.5 bg-[#F8F9FA] border border-[#DADCE0] rounded-xl focus:border-[#1A73E8] focus:bg-white outline-none text-sm transition-colors"
                  />
                </div>
                <div>
                  <label className="block text-[11px] font-bold text-[#5F6368] uppercase tracking-widest mb-1.5">
                    Email Aktif
                  </label>
                  <input
                    required
                    type="email"
                    value={formData.email}
                    onChange={(e) =>
                      setFormData({ ...formData, email: e.target.value })
                    }
                    className="w-full px-3.5 py-2.5 bg-[#F8F9FA] border border-[#DADCE0] rounded-xl focus:border-[#1A73E8] focus:bg-white outline-none text-sm transition-colors"
                  />
                </div>
              </div>

              <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                <div>
                  <label className="block text-[11px] font-bold text-[#5F6368] uppercase tracking-widest mb-1.5">
                    Fakultas / Angkatan
                  </label>
                  <input
                    required
                    type="text"
                    value={formData.fakultasAngkatan}
                    onChange={(e) =>
                      setFormData({
                        ...formData,
                        fakultasAngkatan: e.target.value,
                      })
                    }
                    className="w-full px-3.5 py-2.5 bg-[#F8F9FA] border border-[#DADCE0] rounded-xl focus:border-[#1A73E8] focus:bg-white outline-none text-sm transition-colors"
                  />
                </div>
                <div>
                  <label className="block text-[11px] font-bold text-[#5F6368] uppercase tracking-widest mb-1.5">
                    Program Studi
                  </label>
                  <input
                    required
                    type="text"
                    value={formData.prodi}
                    onChange={(e) =>
                      setFormData({ ...formData, prodi: e.target.value })
                    }
                    className="w-full px-3.5 py-2.5 bg-[#F8F9FA] border border-[#DADCE0] rounded-xl focus:border-[#1A73E8] focus:bg-white outline-none text-sm transition-colors"
                  />
                </div>
              </div>

              <div className="border-t border-[#DADCE0] pt-4 mt-2">
                <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                  <div>
                    <label className="block text-[11px] font-bold text-[#5F6368] uppercase tracking-widest mb-1.5">
                      Nama Usaha
                    </label>
                    <input
                      required
                      type="text"
                      value={formData.namaBisnis}
                      onChange={(e) =>
                        setFormData({ ...formData, namaBisnis: e.target.value })
                      }
                      className="w-full px-3.5 py-2.5 bg-[#F8F9FA] border border-[#DADCE0] rounded-xl focus:border-[#1A73E8] focus:bg-white outline-none text-sm font-bold text-[#202124] transition-colors"
                    />
                  </div>
                  <div>
                    <label className="block text-[11px] font-bold text-[#5F6368] uppercase tracking-widest mb-1.5">
                      Kategori
                    </label>
                    <select
                      required
                      value={formData.kategori}
                      onChange={(e) =>
                        setFormData({ ...formData, kategori: e.target.value })
                      }
                      className={`w-full px-3.5 py-2.5 bg-[#F8F9FA] border border-[#DADCE0] rounded-xl focus:border-[#1A73E8] focus:bg-white outline-none text-sm transition-colors cursor-pointer ${formData.kategori === "Lainnya" ? "mb-2" : ""}`}
                    >
                      {KATEGORI_LIST.map((kat) => (
                        <option key={kat} value={kat}>
                          {kat}
                        </option>
                      ))}
                    </select>
                    {formData.kategori === "Lainnya" && (
                      <input
                        required
                        type="text"
                        value={formData.kategoriLainnya}
                        onChange={(e) =>
                          setFormData({
                            ...formData,
                            kategoriLainnya: e.target.value,
                          })
                        }
                        placeholder="Ketik kategori spesifik..."
                        className="w-full px-3.5 py-2.5 bg-[#E8F0FE] border border-[#1A73E8]/30 rounded-xl focus:border-[#1A73E8] focus:bg-white outline-none text-sm transition-colors animate-in fade-in"
                      />
                    )}
                  </div>
                </div>
              </div>

              <div>
                <label className="block text-[11px] font-bold text-[#5F6368] uppercase tracking-widest mb-1.5">
                  Alamat Lengkap Usaha
                </label>
                <textarea
                  required
                  rows={2}
                  value={formData.alamatUsaha}
                  onChange={(e) =>
                    setFormData({ ...formData, alamatUsaha: e.target.value })
                  }
                  className="w-full px-3.5 py-2.5 bg-[#F8F9FA] border border-[#DADCE0] rounded-xl focus:border-[#1A73E8] focus:bg-white outline-none text-sm resize-none transition-colors"
                ></textarea>
              </div>

              <div>
                <label className="block text-[11px] font-bold text-[#5F6368] uppercase tracking-widest mb-1.5">
                  Fasilitas Bisnis (Pemisah Koma)
                </label>
                <input
                  required
                  type="text"
                  value={formData.fasilitas}
                  onChange={(e) =>
                    setFormData({ ...formData, fasilitas: e.target.value })
                  }
                  className="w-full px-3.5 py-2.5 bg-[#F8F9FA] border border-[#DADCE0] rounded-xl focus:border-[#1A73E8] focus:bg-white outline-none text-sm transition-colors"
                />
              </div>

              <div>
                <label className="block text-[11px] font-bold text-[#5F6368] uppercase tracking-widest mb-1.5">
                  Deskripsi Singkat
                </label>
                <textarea
                  required
                  rows={3}
                  value={formData.deskripsi}
                  onChange={(e) =>
                    setFormData({ ...formData, deskripsi: e.target.value })
                  }
                  className="w-full px-3.5 py-2.5 bg-[#F8F9FA] border border-[#DADCE0] rounded-xl focus:border-[#1A73E8] focus:bg-white outline-none text-sm resize-none transition-colors"
                ></textarea>
              </div>

              <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                <div>
                  <label className="block text-[11px] font-bold text-[#5F6368] uppercase tracking-widest mb-1.5">
                    Nomor WA
                  </label>
                  <input
                    required
                    type="tel"
                    value={formData.waBisnis}
                    onChange={(e) =>
                      setFormData({ ...formData, waBisnis: e.target.value })
                    }
                    className="w-full px-3.5 py-2.5 bg-[#F8F9FA] border border-[#DADCE0] rounded-xl focus:border-[#1A73E8] focus:bg-white outline-none text-sm transition-colors"
                  />
                </div>
                <div>
                  <label className="block text-[11px] font-bold text-[#5F6368] uppercase tracking-widest mb-1.5">
                    Link Web / IG
                  </label>
                  <input
                    type="text"
                    value={formData.linkBisnis}
                    onChange={(e) =>
                      setFormData({ ...formData, linkBisnis: e.target.value })
                    }
                    className="w-full px-3.5 py-2.5 bg-[#F8F9FA] border border-[#DADCE0] rounded-xl focus:border-[#1A73E8] focus:bg-white outline-none text-sm transition-colors"
                  />
                </div>
              </div>

              <div className="bg-[#F8F9FA] p-4 rounded-xl border border-[#DADCE0]">
                <label className="block text-[11px] font-bold text-[#5F6368] uppercase tracking-widest mb-2">
                  Upload / Ganti Gambar
                </label>
                <input
                  type="file"
                  accept="image/*"
                  onChange={(e) => handleImageUpload(e, "bisnis")}
                  className="text-sm file:mr-4 file:py-1.5 file:px-4 file:rounded-full file:border-0 file:text-xs file:font-bold file:bg-[#E8F0FE] file:text-[#1A73E8] cursor-pointer"
                />
                {uploadProgress && (
                  <p className="text-[10px] font-bold text-[#1A73E8] mt-2">
                    {uploadProgress}
                  </p>
                )}
                {formData.foto && (
                  <img
                    src={formData.foto}
                    alt="Preview"
                    className="h-16 mt-2 rounded border border-[#DADCE0] object-cover"
                  />
                )}
              </div>

              <div className="pt-4 mt-6 border-t border-[#DADCE0] flex gap-3 justify-end">
                {modalMode === "review" ? (
                  <>
                    <button
                      type="button"
                      onClick={handleRejectBisnis}
                      disabled={isSaving}
                      className="px-5 py-2.5 bg-white border border-[#DADCE0] text-[#5F6368] hover:text-[#D93025] hover:bg-[#FCE8E6] font-bold rounded-lg text-sm transition-colors shadow-sm"
                    >
                      Tolak Pendaftaran
                    </button>
                    <button
                      type="button"
                      onClick={(e) => handleSaveBisnis(e, "Approved")}
                      disabled={isSaving}
                      className="px-5 py-2.5 bg-[#1E8E3E] hover:bg-[#137333] text-white font-bold rounded-lg shadow-sm transition-all text-sm flex items-center gap-2"
                    >
                      {isSaving ? "Memproses..." : "Setujui & Tayangkan"}
                    </button>
                  </>
                ) : (
                  <div className="flex gap-3 w-full">
                    {modalMode === "edit" &&
                      (formData.status === "Approved" ||
                        formData.status === "Ditolak") && (
                        <button
                          type="button"
                          onClick={() => {
                            const currentBisnis = bisnisList.find(
                              (b) => b.id === selectedId,
                            );
                            if (currentBisnis)
                              handleResendBisnisEmail(currentBisnis);
                          }}
                          disabled={isSendingMail === selectedId || isSaving}
                          className="px-5 py-2.5 bg-white border border-[#DADCE0] text-[#5F6368] hover:bg-[#E8F0FE] hover:text-[#1A73E8] font-bold rounded-lg shadow-sm transition-all text-sm flex items-center justify-center gap-2 w-1/2"
                        >
                          {isSendingMail === selectedId
                            ? "Mengirim..."
                            : "Kirim Ulang Email"}
                        </button>
                      )}
                    <button
                      type="submit"
                      disabled={isSaving}
                      className={`px-5 py-2.5 bg-[#1A73E8] hover:bg-[#1557B0] text-white font-bold rounded-lg shadow-sm transition-all text-sm flex items-center justify-center gap-2 ${modalMode === "edit" && (formData.status === "Approved" || formData.status === "Ditolak") ? "w-1/2" : "w-full"}`}
                    >
                      {isSaving ? "Menyimpan..." : "Simpan Data"}
                    </button>
                  </div>
                )}
              </div>
            </form>
          </div>
        </div>
      )}

      {/* MODAL FORM IKLAN */}
      {isIklanModalOpen && (
        <div className="fixed inset-0 bg-slate-900/60 backdrop-blur-sm z-[100] flex items-center justify-center p-4 animate-in fade-in">
          <div className="bg-white rounded-2xl p-6 md:p-8 max-w-lg w-full shadow-2xl relative border border-[#DADCE0] max-h-[90vh] overflow-y-auto custom-scrollbar">
            <button
              onClick={() => setIsIklanModalOpen(false)}
              className="absolute top-5 right-5 p-2 bg-slate-50 rounded-full text-slate-500 hover:bg-[#FCE8E6] hover:text-[#D93025] transition-colors z-10"
            >
              <svg
                className="w-5 h-5"
                fill="none"
                viewBox="0 0 24 24"
                stroke="currentColor"
              >
                <path
                  strokeLinecap="round"
                  strokeLinejoin="round"
                  strokeWidth={2.5}
                  d="M6 18L18 6M6 6l12 12"
                />
              </svg>
            </button>
            <div className="mb-6 mt-1 border-b border-[#DADCE0] pb-5 flex items-center gap-3">
              <div
                className={`w-12 h-12 rounded-xl flex items-center justify-center shrink-0 ${iklanModalMode === "review" ? "bg-[#FFF8E1] text-[#E65100]" : "bg-[#E8F0FE] text-[#1A73E8]"}`}
              >
                <svg
                  className="w-6 h-6"
                  fill="none"
                  viewBox="0 0 24 24"
                  stroke="currentColor"
                >
                  <path
                    strokeLinecap="round"
                    strokeLinejoin="round"
                    strokeWidth={2}
                    d="M4 16l4.586-4.586a2 2 0 012.828 0L16 16m-2-2l1.586-1.586a2 2 0 012.828 0L20 14m-6-6h.01M6 20h12a2 2 0 002-2V6a2 2 0 00-2-2H6a2 2 0 00-2 2v12a2 2 0 002 2z"
                  />
                </svg>
              </div>
              <div>
                <h3 className="text-xl font-bold text-[#202124] leading-tight">
                  {iklanModalMode === "review"
                    ? "Review Permohonan Iklan"
                    : "Form Banner Iklan"}
                </h3>
                <p className="text-xs text-[#5F6368] mt-0.5">
                  {iklanModalMode === "review"
                    ? "Tinjau dan atur masa tayang sebelum persetujuan."
                    : "Unggah foto banner untuk Slider Halaman Depan."}
                </p>
              </div>
            </div>

            <form
              onSubmit={(e) =>
                handleSaveIklan(
                  e,
                  iklanModalMode === "review" ? "Approved" : undefined,
                )
              }
              className="space-y-4"
            >
              <div>
                <label className="block text-[11px] font-bold text-[#5F6368] uppercase tracking-widest mb-1.5">
                  Nama Sponsor / Klien
                </label>
                <input
                  required
                  type="text"
                  value={iklanData.namaSponsor}
                  onChange={(e) =>
                    setIklanData({ ...iklanData, namaSponsor: e.target.value })
                  }
                  className="w-full px-3.5 py-2.5 bg-[#F8F9FA] border border-[#DADCE0] rounded-xl focus:border-[#1A73E8] focus:bg-white outline-none text-sm transition-colors"
                />
              </div>
              <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                <div>
                  <label className="block text-[11px] font-bold text-[#5F6368] uppercase tracking-widest mb-1.5">
                    Email Sponsor
                  </label>
                  <input
                    required
                    type="email"
                    value={iklanData.emailSponsor}
                    onChange={(e) =>
                      setIklanData({
                        ...iklanData,
                        emailSponsor: e.target.value,
                      })
                    }
                    className="w-full px-3.5 py-2.5 bg-[#F8F9FA] border border-[#DADCE0] rounded-xl focus:border-[#1A73E8] focus:bg-white outline-none text-sm transition-colors"
                  />
                </div>
                <div>
                  <label className="block text-[11px] font-bold text-[#5F6368] uppercase tracking-widest mb-1.5">
                    Nomor WhatsApp
                  </label>
                  <input
                    required
                    type="tel"
                    value={iklanData.noWA}
                    onChange={(e) =>
                      setIklanData({ ...iklanData, noWA: e.target.value })
                    }
                    className="w-full px-3.5 py-2.5 bg-[#F8F9FA] border border-[#DADCE0] rounded-xl focus:border-[#1A73E8] focus:bg-white outline-none text-sm transition-colors"
                  />
                </div>
              </div>
              <div>
                <label className="block text-[11px] font-bold text-[#5F6368] uppercase tracking-widest mb-1.5">
                  Link Tujuan Iklan
                </label>
                <input
                  required
                  type="url"
                  value={iklanData.linkTujuan}
                  onChange={(e) =>
                    setIklanData({ ...iklanData, linkTujuan: e.target.value })
                  }
                  placeholder="https://..."
                  className="w-full px-3.5 py-2.5 bg-[#F8F9FA] border border-[#DADCE0] rounded-xl focus:border-[#1A73E8] focus:bg-white outline-none text-sm transition-colors"
                />
              </div>
              <div>
                <label className="block text-[11px] font-bold text-[#5F6368] uppercase tracking-widest mb-1.5">
                  Berlaku Hingga Tanggal{" "}
                  <span className="text-rose-500">*</span>
                </label>
                <input
                  required
                  type="date"
                  value={iklanData.tanggalBerakhir}
                  onChange={(e) =>
                    setIklanData({
                      ...iklanData,
                      tanggalBerakhir: e.target.value,
                    })
                  }
                  className={`w-full px-3.5 py-2.5 border rounded-xl focus:border-[#1A73E8] focus:bg-white outline-none text-sm transition-colors ${iklanModalMode === "review" && !iklanData.tanggalBerakhir ? "border-rose-400 bg-rose-50" : "bg-[#F8F9FA] border-[#DADCE0]"}`}
                />
                {iklanModalMode === "review" && !iklanData.tanggalBerakhir && (
                  <p className="text-[10px] text-rose-500 font-bold mt-1">
                    Harap tentukan batas tayang sebelum persetujuan.
                  </p>
                )}
              </div>

              <div className="bg-[#F8F9FA] p-4 rounded-xl border border-[#DADCE0]">
                <label className="block text-[11px] font-bold text-[#5F6368] uppercase tracking-widest mb-2">
                  Upload Banner
                </label>
                <input
                  type="file"
                  accept="image/*"
                  onChange={(e) => handleImageUpload(e, "iklan")}
                  className="text-sm file:mr-4 file:py-1.5 file:px-4 file:rounded-full file:border-0 file:text-xs file:font-bold file:bg-[#E8F0FE] file:text-[#1A73E8] cursor-pointer"
                />
                {uploadProgress && (
                  <p className="text-[10px] font-bold text-[#1A73E8] mt-2">
                    {uploadProgress}
                  </p>
                )}
                {iklanData.fotoUrl && (
                  <img
                    src={iklanData.fotoUrl}
                    alt="Preview"
                    className="h-16 mt-2 rounded border border-[#DADCE0] object-cover"
                  />
                )}
              </div>

              <div className="pt-4 mt-6 border-t border-[#DADCE0] flex gap-3 justify-end">
                {iklanModalMode === "review" ? (
                  <>
                    <button
                      type="button"
                      onClick={handleRejectIklan}
                      disabled={isSaving}
                      className="px-5 py-2.5 bg-white border border-[#DADCE0] text-[#5F6368] hover:text-[#D93025] hover:bg-[#FCE8E6] font-bold rounded-lg text-sm transition-colors shadow-sm"
                    >
                      Tolak Permohonan
                    </button>
                    <button
                      type="submit"
                      disabled={
                        isSaving ||
                        !iklanData.fotoUrl ||
                        !iklanData.tanggalBerakhir
                      }
                      className="px-5 py-2.5 bg-[#1E8E3E] hover:bg-[#137333] text-white font-bold rounded-lg shadow-sm transition-all text-sm flex items-center gap-2"
                    >
                      {isSaving ? "Memproses..." : "Setujui & Tayangkan"}
                    </button>
                  </>
                ) : (
                  <button
                    type="submit"
                    disabled={isSaving || !iklanData.fotoUrl}
                    className="w-full bg-[#1A73E8] hover:bg-[#1557B0] text-white font-bold py-3.5 rounded-xl shadow-md transition-all flex items-center justify-center gap-2 text-sm disabled:opacity-50"
                  >
                    {isSaving ? "Menyimpan..." : "Simpan Banner Iklan"}
                  </button>
                )}
              </div>
            </form>
          </div>
        </div>
      )}
    </div>
  );
}

"use client";

import { useState, useEffect } from "react";
import { db } from "@/lib/firebase";
import {
  collection,
  addDoc,
  getDocs,
  deleteDoc,
  doc,
  updateDoc,
  query,
  orderBy,
  where,
} from "firebase/firestore";

// Komponen Ikon Mini
const IconPlus = () => (
  <svg
    className="w-4 h-4"
    fill="none"
    viewBox="0 0 24 24"
    stroke="currentColor"
  >
    <path
      strokeLinecap="round"
      strokeLinejoin="round"
      strokeWidth={2.5}
      d="M12 4v16m8-8H4"
    />
  </svg>
);
const IconAlert = () => (
  <svg
    className="w-6 h-6"
    fill="none"
    viewBox="0 0 24 24"
    stroke="currentColor"
  >
    <path
      strokeLinecap="round"
      strokeLinejoin="round"
      strokeWidth={1.5}
      d="M12 9v2m0 4h.01m-6.938 4h13.856c1.54 0 2.502-1.667 1.732-3L13.732 4c-.77-1.333-2.694-1.333-3.464 0L3.34 16c-.77 1.333.192 3 1.732 3z"
    />
  </svg>
);
const IconCheck = () => (
  <svg
    className="w-5 h-5"
    fill="none"
    viewBox="0 0 24 24"
    stroke="currentColor"
  >
    <path
      strokeLinecap="round"
      strokeLinejoin="round"
      strokeWidth={2}
      d="M5 13l4 4L19 7"
    />
  </svg>
);

export default function TabSuratLegal({
  filterPeriodeId,
}: {
  filterPeriodeId: string;
}) {
  const [docsList, setDocsList] = useState<any[]>([]);
  const [periodeList, setPeriodeList] = useState<any[]>([]);

  const [isLoading, setIsLoading] = useState(true);
  const [isProcessing, setIsProcessing] = useState(false);
  const [viewMode, setViewMode] = useState("list");
  const [editId, setEditId] = useState<string | null>(null);

  const [searchTerm, setSearchTerm] = useState("");
  const [filterKategori, setFilterKategori] = useState("");

  const [toast, setToast] = useState({
    isOpen: false,
    message: "",
    type: "success",
  });
  const [deleteModal, setDeleteModal] = useState({
    isOpen: false,
    id: "",
    title: "",
  });

  const [formData, setFormData] = useState({
    judul: "",
    nomor: "",
    tanggal: "",
    kategori: "Surat Edaran",
    status: "Berlaku",
    fileUrl: "",
    periodeId: "",
  });

  // --- FETCH DATA ARSIP & PERIODE ---
  useEffect(() => {
    const fetchData = async () => {
      setIsLoading(true);
      try {
        const pSnap = await getDocs(
          query(collection(db, "periode"), orderBy("tglMulai", "desc")),
        );
        setPeriodeList(pSnap.docs.map((d) => ({ id: d.id, ...d.data() })));

        let q;
        if (filterPeriodeId === "Semua" || !filterPeriodeId) {
          q = query(
            collection(db, "surat_edaran"),
            orderBy("createdAt", "desc"),
          );
        } else {
          // Hindari error Composite Index
          q = query(
            collection(db, "surat_edaran"),
            where("periodeId", "==", filterPeriodeId),
          );
        }

        const snap = await getDocs(q);
        const data = snap.docs.map((doc) => ({ id: doc.id, ...doc.data() }));

        // Pengurutan manual di sisi Frontend
        if (filterPeriodeId !== "Semua" && filterPeriodeId) {
          data.sort(
            (a: any, b: any) =>
              new Date(b.createdAt || 0).getTime() -
              new Date(a.createdAt || 0).getTime(),
          );
        }

        setDocsList(data);
      } catch (error) {
        console.error("Gagal memuat dokumen legal:", error);
      } finally {
        setIsLoading(false);
      }
    };
    fetchData();
  }, [filterPeriodeId]);

  const filteredList = docsList.filter((d) => {
    const matchSearch =
      (d.judul || "").toLowerCase().includes(searchTerm.toLowerCase()) ||
      (d.nomor || "").toLowerCase().includes(searchTerm.toLowerCase());
    const matchKategori = filterKategori ? d.kategori === filterKategori : true;
    return matchSearch && matchKategori;
  });

  const showToast = (
    message: string,
    type: "success" | "error" = "success",
  ) => {
    setToast({ isOpen: true, message, type });
    setTimeout(
      () => setToast({ isOpen: false, message: "", type: "success" }),
      3500,
    );
  };

  const handleFormChange = (e: any) => {
    setFormData({ ...formData, [e.target.name]: e.target.value });
  };

  const handleSave = async (e: React.FormEvent) => {
    e.preventDefault();
    setIsProcessing(true);
    try {
      const payload = { ...formData, updatedAt: new Date().toISOString() };

      if (editId) {
        await updateDoc(doc(db, "surat_edaran", editId), payload);
        showToast("Dokumen berhasil diperbarui!", "success");
      } else {
        await addDoc(collection(db, "surat_edaran"), {
          ...payload,
          createdAt: new Date().toISOString(),
        });
        showToast("Dokumen baru berhasil ditambahkan!", "success");
      }

      // Refresh Data
      let q;
      if (filterPeriodeId === "Semua" || !filterPeriodeId) {
        q = query(collection(db, "surat_edaran"), orderBy("createdAt", "desc"));
      } else {
        q = query(
          collection(db, "surat_edaran"),
          where("periodeId", "==", filterPeriodeId),
        );
      }

      const snap = await getDocs(q);
      const newData = snap.docs.map((doc) => ({ id: doc.id, ...doc.data() }));

      if (filterPeriodeId !== "Semua" && filterPeriodeId) {
        newData.sort(
          (a: any, b: any) =>
            new Date(b.createdAt || 0).getTime() -
            new Date(a.createdAt || 0).getTime(),
        );
      }
      setDocsList(newData);

      setViewMode("list");
      setEditId(null);
    } catch (error) {
      showToast("Gagal menyimpan dokumen.", "error");
    } finally {
      setIsProcessing(false);
    }
  };

  const executeDelete = async () => {
    setIsProcessing(true);
    try {
      await deleteDoc(doc(db, "surat_edaran", deleteModal.id));
      setDocsList(docsList.filter((d) => d.id !== deleteModal.id));
      showToast("Dokumen berhasil dihapus permanen.", "success");
    } catch (error) {
      showToast("Gagal menghapus dokumen.", "error");
    } finally {
      setIsProcessing(false);
      setDeleteModal({ isOpen: false, id: "", title: "" });
    }
  };

  const openAddForm = () => {
    setFormData({
      judul: "",
      nomor: "",
      tanggal: "",
      kategori: "Surat Edaran",
      status: "Berlaku",
      fileUrl: "",
      periodeId:
        filterPeriodeId !== "Semua"
          ? filterPeriodeId
          : periodeList[0]?.id || "",
    });
    setEditId(null);
    setViewMode("form");
  };

  const openEditForm = (item: any) => {
    setFormData({
      judul: item.judul,
      nomor: item.nomor,
      tanggal: item.tanggal,
      kategori: item.kategori,
      status: item.status,
      fileUrl: item.fileUrl,
      periodeId: item.periodeId,
    });
    setEditId(item.id);
    setViewMode("form");
  };

  return (
    <div className="animate-in fade-in duration-300 relative">
      {/* TOAST NOTIFICATION */}
      <div
        className={`fixed top-6 right-6 z-[200] transition-all duration-300 transform ${toast.isOpen ? "translate-y-0 opacity-100" : "-translate-y-4 opacity-0 pointer-events-none"}`}
      >
        <div
          className={`flex items-center gap-3 px-5 py-4 rounded-xl shadow-lg border ${toast.type === "success" ? "bg-white border-emerald-100" : "bg-white border-red-100"}`}
        >
          <div
            className={`flex-shrink-0 w-8 h-8 rounded-full flex items-center justify-center text-white shadow-sm ${toast.type === "success" ? "bg-emerald-600" : "bg-red-600"}`}
          >
            {toast.type === "success" ? <IconCheck /> : <IconAlert />}
          </div>
          <div>
            <p className="text-sm font-bold text-slate-800">
              {toast.type === "success" ? "Berhasil!" : "Peringatan!"}
            </p>
            <p className="text-[13px] text-slate-500 mt-0.5">{toast.message}</p>
          </div>
        </div>
      </div>

      {/* MODAL HAPUS */}
      {deleteModal.isOpen && (
        <div className="fixed inset-0 z-[150] flex items-center justify-center p-4 bg-slate-900/40 backdrop-blur-sm animate-in fade-in duration-200">
          <div className="bg-white rounded-2xl shadow-xl p-8 max-w-sm w-full text-center border border-slate-100 animate-in zoom-in-95">
            <div className="w-16 h-16 bg-red-50 text-red-600 rounded-full flex items-center justify-center mx-auto mb-5 border-[4px] border-white shadow-sm">
              <IconAlert />
            </div>
            <h3 className="text-xl font-bold text-slate-800 mb-2 tracking-tight">
              Hapus Permanen?
            </h3>
            <p className="text-sm text-slate-500 mb-8 font-medium px-2 leading-relaxed">
              Anda yakin ingin menghapus dokumen{" "}
              <strong className="text-slate-800">"{deleteModal.title}"</strong>?
              Arsip tidak dapat dikembalikan.
            </p>
            <div className="flex gap-3 justify-center">
              <button
                onClick={() =>
                  setDeleteModal({ isOpen: false, id: "", title: "" })
                }
                className="px-5 py-3 rounded-xl text-sm font-bold text-slate-600 bg-slate-100 hover:bg-slate-200 transition-colors w-full"
              >
                Batal
              </button>
              <button
                onClick={executeDelete}
                disabled={isProcessing}
                className="px-5 py-3 rounded-xl text-sm font-bold text-white bg-red-600 hover:bg-red-700 transition-colors shadow-md w-full"
              >
                {isProcessing ? "Proses..." : "Ya, Hapus"}
              </button>
            </div>
          </div>
        </div>
      )}

      {viewMode === "list" ? (
        <>
          {/* HEADER & FILTER LOKAL */}
          <div className="bg-white p-6 rounded-[2rem] shadow-sm border border-slate-200 mb-6 flex flex-col md:flex-row justify-between items-center gap-5">
            <div className="flex gap-4 w-full md:w-auto items-end">
              <div className="flex-1 md:w-64 relative">
                <label className="block text-[11px] font-black text-slate-400 uppercase tracking-widest mb-2 ml-1">
                  Pencarian Dokumen
                </label>
                <input
                  type="text"
                  placeholder="Ketik judul / nomor..."
                  value={searchTerm}
                  onChange={(e) => setSearchTerm(e.target.value)}
                  className="w-full bg-slate-50 border border-slate-200 py-3 px-4 rounded-xl text-sm font-medium focus:ring-2 focus:ring-blue-500 focus:bg-white outline-none transition-all"
                />
              </div>
              <div className="flex-1 md:w-48">
                <label className="block text-[11px] font-black text-slate-400 uppercase tracking-widest mb-2 ml-1">
                  Kategori
                </label>
                <select
                  value={filterKategori}
                  onChange={(e) => setFilterKategori(e.target.value)}
                  className="w-full bg-slate-50 border border-slate-200 py-3 px-4 rounded-xl text-sm font-bold text-blue-900 focus:ring-2 focus:ring-blue-500 focus:bg-white outline-none transition-all cursor-pointer"
                >
                  <option value="">Semua Kategori</option>
                  <option value="Surat Edaran">Surat Edaran</option>
                  <option value="Surat Keputusan">Surat Keputusan</option>
                  <option value="Peraturan Organisasi">
                    Peraturan Organisasi
                  </option>
                </select>
              </div>
            </div>

            <div className="w-full md:w-auto mt-4 md:mt-0 pt-6">
              <button
                onClick={openAddForm}
                className="w-full md:w-auto bg-blue-600 hover:bg-blue-700 text-white font-bold px-6 py-3 rounded-xl transition-all shadow-md shadow-blue-500/20 flex items-center justify-center gap-2"
              >
                <IconPlus /> Tambah Arsip
              </button>
            </div>
          </div>

          {/* TABEL DATA */}
          <div className="bg-white rounded-[2rem] shadow-sm border border-slate-200 overflow-hidden">
            {isLoading ? (
              <div className="p-24 flex flex-col items-center justify-center text-slate-400">
                <div className="w-12 h-12 border-4 border-slate-200 border-t-blue-500 rounded-full animate-spin mb-4"></div>
                <p className="font-bold tracking-widest uppercase text-xs animate-pulse">
                  Menyiapkan Dokumen...
                </p>
              </div>
            ) : filteredList.length === 0 ? (
              <div className="p-24 text-center flex flex-col items-center">
                <div className="w-20 h-20 bg-slate-50 rounded-full flex items-center justify-center mb-4 border border-slate-100 shadow-inner">
                  <span className="text-4xl">📜</span>
                </div>
                <h3 className="font-extrabold text-blue-950 text-xl mb-1">
                  Arsip Kosong
                </h3>
                <p className="text-sm text-slate-500 max-w-sm">
                  Belum ada dokumen surat yang diunggah pada periode
                  kepengurusan ini.
                </p>
              </div>
            ) : (
              <div className="overflow-x-auto">
                <table className="w-full text-left border-collapse whitespace-nowrap">
                  <thead>
                    <tr className="bg-slate-50 border-b border-slate-200 text-slate-500 text-[10px] uppercase tracking-widest">
                      <th className="px-6 py-5 font-black">Informasi Surat</th>
                      <th className="px-6 py-5 font-black text-center">
                        Status
                      </th>
                      <th className="px-6 py-5 font-black text-center border-x border-slate-100 bg-blue-50/30">
                        File Unduhan
                      </th>
                      <th className="px-6 py-5 font-black text-right">
                        Aksi Manajemen
                      </th>
                    </tr>
                  </thead>
                  <tbody className="divide-y divide-slate-100 text-sm">
                    {filteredList.map((d) => (
                      <tr
                        key={d.id}
                        className="hover:bg-slate-50/50 transition-colors group"
                      >
                        <td className="px-6 py-5 align-top">
                          <div className="font-extrabold text-blue-950 text-base mb-1.5 whitespace-normal max-w-sm line-clamp-2">
                            {d.judul}
                          </div>
                          <div className="flex items-center gap-3 text-[11px] mb-1">
                            <span className="text-slate-600 font-bold bg-white px-2 py-0.5 rounded border border-slate-200 shadow-sm uppercase tracking-wider">
                              {d.kategori}
                            </span>
                            <span className="text-blue-600 font-mono font-bold tracking-wider">
                              {d.nomor}
                            </span>
                          </div>
                          <div className="text-[10px] text-slate-400 font-medium mt-2">
                            Diterbitkan: {d.tanggal}
                          </div>
                        </td>

                        <td className="px-6 py-5 text-center align-middle">
                          <span
                            className={`text-[10px] font-black px-4 py-1.5 rounded-md border uppercase tracking-widest inline-block ${d.status === "Berlaku" ? "bg-emerald-50 text-emerald-700 border-emerald-200" : "bg-rose-50 text-rose-700 border-rose-200"}`}
                          >
                            {d.status}
                          </span>
                        </td>

                        <td className="px-6 py-5 text-center border-x border-slate-100 align-middle">
                          {d.fileUrl ? (
                            <a
                              href={d.fileUrl}
                              target="_blank"
                              rel="noopener noreferrer"
                              className="inline-flex items-center justify-center gap-2 bg-white text-blue-600 border border-blue-200 hover:bg-blue-600 hover:text-white px-5 py-2 rounded-xl font-bold transition-all shadow-sm hover:shadow-md text-xs"
                            >
                              Buka Dokumen PDF
                            </a>
                          ) : (
                            <span className="inline-flex items-center text-[10px] text-slate-400 font-bold uppercase tracking-widest bg-slate-50 px-4 py-2 rounded-xl border border-dashed border-slate-200">
                              Tidak Ada File
                            </span>
                          )}
                        </td>

                        <td className="px-6 py-5 text-right align-middle">
                          <div className="flex items-center justify-end gap-2">
                            <button
                              onClick={() => openEditForm(d)}
                              className="bg-white hover:bg-blue-50 text-blue-600 border border-slate-200 hover:border-blue-300 font-bold px-4 py-2 rounded-xl text-xs transition-colors shadow-sm"
                            >
                              Edit
                            </button>
                            <button
                              onClick={() =>
                                setDeleteModal({
                                  isOpen: true,
                                  id: d.id,
                                  title: d.judul,
                                })
                              }
                              className="bg-white hover:bg-red-50 text-red-600 border border-slate-200 hover:border-red-300 font-bold px-4 py-2 rounded-xl text-xs transition-colors shadow-sm"
                            >
                              Hapus
                            </button>
                          </div>
                        </td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              </div>
            )}
          </div>
        </>
      ) : (
        /* ==================== FORM TAMBAH/EDIT ==================== */
        <form
          onSubmit={handleSave}
          className="bg-white rounded-[2rem] border border-slate-200 p-8 sm:p-10 max-w-3xl mx-auto shadow-xl mt-6"
        >
          <h3 className="font-extrabold mb-8 text-2xl text-slate-900 border-b border-slate-100 pb-5">
            {editId ? "Edit Regulasi Organisasi" : "Unggah Arsip Dokumen Baru"}
          </h3>

          <div className="space-y-6">
            <div>
              <label className="block text-[11px] font-bold text-slate-500 mb-2 uppercase tracking-widest">
                Judul Dokumen / Perihal
              </label>
              <input
                type="text"
                name="judul"
                value={formData.judul}
                onChange={handleFormChange}
                required
                placeholder="Cth: Surat Edaran Tata Cara Pendaftaran E-KTA"
                className="w-full border border-slate-200 px-4 py-3 rounded-xl text-sm font-bold text-slate-800 outline-none focus:border-blue-500 bg-slate-50 focus:bg-white transition-colors shadow-sm"
              />
            </div>

            <div className="grid sm:grid-cols-2 gap-6">
              <div>
                <label className="block text-[11px] font-bold text-slate-500 mb-2 uppercase tracking-widest">
                  Nomor Surat Resmi
                </label>
                <input
                  type="text"
                  name="nomor"
                  value={formData.nomor}
                  onChange={handleFormChange}
                  required
                  placeholder="Cth: 01/SE/DPW/V/2026"
                  className="w-full border border-slate-200 px-4 py-3 rounded-xl text-sm font-mono text-blue-900 outline-none focus:border-blue-500 bg-slate-50 focus:bg-white transition-colors shadow-sm"
                />
              </div>
              <div>
                <label className="block text-[11px] font-bold text-slate-500 mb-2 uppercase tracking-widest">
                  Tanggal Diterbitkan
                </label>
                <input
                  type="text"
                  name="tanggal"
                  value={formData.tanggal}
                  onChange={handleFormChange}
                  required
                  placeholder="Cth: 12 Mei 2026"
                  className="w-full border border-slate-200 px-4 py-3 rounded-xl text-sm outline-none focus:border-blue-500 bg-slate-50 focus:bg-white transition-colors shadow-sm"
                />
              </div>
            </div>

            <div className="grid sm:grid-cols-2 gap-6">
              <div>
                <label className="block text-[11px] font-bold text-slate-500 mb-2 uppercase tracking-widest">
                  Kategori Dokumen
                </label>
                <select
                  name="kategori"
                  value={formData.kategori}
                  onChange={handleFormChange}
                  className="w-full border border-slate-200 px-4 py-3 rounded-xl text-sm font-bold text-slate-700 outline-none focus:border-blue-500 bg-slate-50 focus:bg-white transition-colors shadow-sm cursor-pointer"
                >
                  <option value="Surat Edaran">Surat Edaran</option>
                  <option value="Surat Keputusan">Surat Keputusan</option>
                  <option value="Peraturan Organisasi">
                    Peraturan Organisasi
                  </option>
                  <option value="SOP / Panduan">SOP / Panduan</option>
                </select>
              </div>
              <div>
                <label className="block text-[11px] font-bold text-slate-500 mb-2 uppercase tracking-widest">
                  Status Keberlakuan
                </label>
                <select
                  name="status"
                  value={formData.status}
                  onChange={handleFormChange}
                  className="w-full border border-slate-200 px-4 py-3 rounded-xl text-sm font-bold text-slate-700 outline-none focus:border-blue-500 bg-slate-50 focus:bg-white transition-colors shadow-sm cursor-pointer"
                >
                  <option value="Berlaku">Berlaku Aktif</option>
                  <option value="Dicabut">Dicabut / Kadaluarsa</option>
                </select>
              </div>
            </div>

            <div>
              <label className="block text-[11px] font-bold text-slate-500 mb-2 uppercase tracking-widest">
                URL Tautan Dokumen (Google Drive / PDF Link)
              </label>
              <input
                type="url"
                name="fileUrl"
                value={formData.fileUrl}
                onChange={handleFormChange}
                required
                placeholder="https://drive.google.com/..."
                className="w-full border border-slate-200 px-4 py-3 rounded-xl text-sm outline-none focus:border-blue-500 bg-slate-50 focus:bg-white transition-colors shadow-sm"
              />
            </div>

            <div>
              <label className="block text-[11px] font-bold text-[#1A73E8] mb-2 uppercase tracking-widest bg-blue-50 px-2 py-1 rounded w-fit">
                Terikat Pada Masa Periode
              </label>
              <select
                name="periodeId"
                value={formData.periodeId}
                onChange={handleFormChange}
                required
                className="w-full border-2 border-blue-200 px-4 py-3 rounded-xl text-sm font-bold text-[#1A73E8] outline-none focus:border-blue-500 bg-[#E8F0FE] shadow-sm cursor-pointer"
              >
                <option value="" disabled>
                  -- Pilih Periode Kepengurusan --
                </option>
                {periodeList.map((p) => (
                  <option key={p.id} value={p.id}>
                    {p.namaPeriode} {p.status === "Aktif" ? "(Aktif)" : ""}
                  </option>
                ))}
              </select>
            </div>
          </div>

          <div className="flex justify-end gap-3 mt-10 pt-6 border-t border-slate-100">
            <button
              type="button"
              onClick={() => setViewMode("list")}
              className="px-6 py-3 text-sm font-bold text-slate-600 bg-slate-100 hover:bg-slate-200 rounded-xl transition-colors"
            >
              Batal
            </button>
            <button
              type="submit"
              disabled={isProcessing}
              className="px-6 py-3 text-sm font-bold text-white bg-blue-600 hover:bg-blue-700 rounded-xl transition-colors shadow-md shadow-blue-500/20 disabled:opacity-70 flex items-center gap-2"
            >
              {isProcessing ? "Menyimpan..." : "Simpan Dokumen"}
            </button>
          </div>
        </form>
      )}
    </div>
  );
}

"use client";

import { useState, useEffect } from "react";
import { toast } from "@/lib/toast";
import { db, auth } from "@/lib/firebase";
import { onAuthStateChanged } from "firebase/auth";
import {
  collection,
  query,
  orderBy,
  getDocs,
  doc,
  getDoc,
  addDoc,
  updateDoc,
  where,
} from "firebase/firestore";
import * as XLSX from "xlsx";

// --- IKON PROFESIONAL ---
const IconClose = () => (
  <svg
    className="w-5 h-5"
    fill="none"
    viewBox="0 0 24 24"
    stroke="currentColor"
  >
    <path
      strokeLinecap="round"
      strokeLinejoin="round"
      strokeWidth={2}
      d="M6 18L18 6M6 6l12 12"
    />
  </svg>
);
const IconPlus = () => (
  <svg
    className="w-4 h-4"
    fill="none"
    viewBox="0 0 24 24"
    stroke="currentColor"
  >
    <path
      strokeLinecap="round"
      strokeLinejoin="round"
      strokeWidth={2.5}
      d="M12 4.5v15m7.5-7.5h-15"
    />
  </svg>
);
const IconDownload = () => (
  <svg
    className="w-4 h-4"
    fill="none"
    viewBox="0 0 24 24"
    stroke="currentColor"
  >
    <path
      strokeLinecap="round"
      strokeLinejoin="round"
      strokeWidth={2.5}
      d="M3 16.5v2.25A2.25 2.25 0 005.25 21h13.5A2.25 2.25 0 0021 18.75V16.5M16.5 12L12 16.5m0 0L7.5 12m4.5 4.5V3"
    />
  </svg>
);
const IconWallet = () => (
  <svg
    className="w-10 h-10"
    fill="none"
    viewBox="0 0 24 24"
    stroke="currentColor"
  >
    <path
      strokeLinecap="round"
      strokeLinejoin="round"
      strokeWidth={1.5}
      d="M21 12a2.25 2.25 0 00-2.25-2.25H15a3 3 0 11-6 0H4.5A2.25 2.25 0 002.25 12v6.75A2.25 2.25 0 004.5 21h15a2.25 2.25 0 002.25-2.25V12z"
    />
    <path
      strokeLinecap="round"
      strokeLinejoin="round"
      strokeWidth={1.5}
      d="M4.5 10.5h15M4.5 10.5a2.25 2.25 0 00-2.25-2.25h15A2.25 2.25 0 0019.5 6h-15A2.25 2.25 0 002.25 8.25v2.25"
    />
  </svg>
);

export default function PengelolaanDonasiPage() {
  // --- STATE PROTEKSI HALAMAN ---
  const [hasAccess, setHasAccess] = useState<boolean | null>(null);

  // --- STATE PERIODE (SESI) ---
  const [periodeList, setPeriodeList] = useState<any[]>([]);
  const [selectedPeriode, setSelectedPeriode] = useState<any>(null);
  const [isLoadingPeriode, setIsLoadingPeriode] = useState(true);

  // Modal Buat Periode
  const [isModalPeriodeOpen, setIsModalPeriodeOpen] = useState(false);
  const [newPeriode, setNewPeriode] = useState({ judul: "", targetDana: "" });

  // --- STATE TRANSAKSI (DONATUR) ---
  const [transaksiList, setTransaksiList] = useState<any[]>([]);
  const [isLoadingTransaksi, setIsLoadingTransaksi] = useState(false);

  // Modal Tambah Donasi Manual
  const [isModalDonasiOpen, setIsModalDonasiOpen] = useState(false);
  const [newDonasi, setNewDonasi] = useState({
    nama: "",
    nominal: "",
    doa: "",
    metode: "Transfer Bank",
  });

  const [isSubmitting, setIsSubmitting] = useState(false);

  // FORMAT RUPIAH
  const formatRp = (angka: number) => {
    return new Intl.NumberFormat("id-ID", {
      style: "currency",
      currency: "IDR",
      minimumFractionDigits: 0,
    }).format(angka);
  };

  // 0. CEK HAK AKSES SAAT HALAMAN DIBUKA
  useEffect(() => {
    const checkAccess = async () => {
      const unsubscribe = onAuthStateChanged(auth, async (user) => {
        if (user) {
          try {
            const userDoc = await getDoc(doc(db, "users", user.uid));
            if (userDoc.exists()) {
              const data = userDoc.data();
              const isSuperAdmin = data.role === "super_admin";
              const isBidangSosial = (data.bidang || "")
                .toLowerCase()
                .includes("sosial");

              if (isSuperAdmin || isBidangSosial) {
                setHasAccess(true);
              } else {
                setHasAccess(false);
              }
            } else {
              setHasAccess(false);
            }
          } catch (error) {
            console.error("Gagal cek akses:", error);
            setHasAccess(false);
          }
        } else {
          setHasAccess(false);
        }
      });
      return () => unsubscribe();
    };
    checkAccess();
  }, []);

  // 1. FETCH DAFTAR PERIODE
  const fetchPeriode = async () => {
    if (!hasAccess) return;
    try {
      const q = query(
        collection(db, "donasi_periode"),
        orderBy("createdAt", "desc"),
      );
      const snap = await getDocs(q);
      const data = snap.docs.map((d) => ({ id: d.id, ...d.data() }));
      setPeriodeList(data);
      if (data.length > 0 && !selectedPeriode) {
        setSelectedPeriode(data[0]);
      }
    } catch (error) {
      console.error("Gagal load periode:", error);
    } finally {
      setIsLoadingPeriode(false);
    }
  };

  useEffect(() => {
    if (hasAccess) {
      fetchPeriode();
    }
  }, [hasAccess]);

  // 2. FETCH TRANSAKSI BERDASARKAN PERIODE TERPILIH
  useEffect(() => {
    if (!selectedPeriode || !hasAccess) return;
    const fetchTransaksi = async () => {
      setIsLoadingTransaksi(true);
      try {
        const q = query(
          collection(db, "donasi_transaksi"),
          where("periodeId", "==", selectedPeriode.id),
        );
        const snap = await getDocs(q);
        const data = snap.docs.map((d) => ({ id: d.id, ...d.data() }));
        data.sort(
          (a: any, b: any) =>
            new Date(b.createdAt).getTime() - new Date(a.createdAt).getTime(),
        );
        setTransaksiList(data);
      } catch (error) {
        console.error("Gagal load transaksi:", error);
      } finally {
        setIsLoadingTransaksi(false);
      }
    };
    fetchTransaksi();
  }, [selectedPeriode, hasAccess]);

  // 3. FUNGSI BUAT PERIODE BARU
  const handleBuatPeriode = async (e: React.FormEvent) => {
    e.preventDefault();
    setIsSubmitting(true);
    try {
      const docRef = await addDoc(collection(db, "donasi_periode"), {
        judul: newPeriode.judul,
        targetDana: Number(newPeriode.targetDana) || 0,
        status: "Aktif",
        createdAt: new Date().toISOString(),
      });
      setIsModalPeriodeOpen(false);
      setNewPeriode({ judul: "", targetDana: "" });
      fetchPeriode();
      setSelectedPeriode({
        id: docRef.id,
        judul: newPeriode.judul,
        targetDana: Number(newPeriode.targetDana),
        status: "Aktif",
      });
    } catch (error) {
      toast.error("Gagal membuat periode baru.");
    } finally {
      setIsSubmitting(false);
    }
  };

  // 4. FUNGSI TUTUP PERIODE
  const handleTutupPeriode = async (id: string, currentStatus: string) => {
    if (
      confirm(
        `Yakin ingin ${currentStatus === "Aktif" ? "MENUTUP" : "MEMBUKA KEMBALI"} periode donasi ini?`,
      )
    ) {
      const newStatus = currentStatus === "Aktif" ? "Selesai" : "Aktif";
      await updateDoc(doc(db, "donasi_periode", id), { status: newStatus });
      fetchPeriode();
      if (selectedPeriode?.id === id) {
        setSelectedPeriode({ ...selectedPeriode, status: newStatus });
      }
    }
  };

  // 5. FUNGSI INPUT DONASI MANUAL
  const handleInputDonasi = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!selectedPeriode) return;
    setIsSubmitting(true);
    try {
      const nominalNum = Number(newDonasi.nominal);
      await addDoc(collection(db, "donasi_transaksi"), {
        periodeId: selectedPeriode.id,
        nama: newDonasi.nama || "Hamba Allah",
        nominal: nominalNum,
        doa: newDonasi.doa || "-",
        metode: newDonasi.metode,
        statusValidasi: true,
        createdAt: new Date().toISOString(),
      });
      setIsModalDonasiOpen(false);
      setNewDonasi({ nama: "", nominal: "", doa: "", metode: "Transfer Bank" });

      const q = query(
        collection(db, "donasi_transaksi"),
        where("periodeId", "==", selectedPeriode.id),
      );
      const snap = await getDocs(q);
      const data = snap.docs.map((d) => ({ id: d.id, ...d.data() }));
      data.sort(
        (a: any, b: any) =>
          new Date(b.createdAt).getTime() - new Date(a.createdAt).getTime(),
      );
      setTransaksiList(data);
    } catch (error) {
      toast.error("Gagal menginput donasi.");
    } finally {
      setIsSubmitting(false);
    }
  };

  // 6. EXPORT EXCEL
  const downloadExcel = () => {
    const totalTerkumpul = transaksiList.reduce(
      (sum, item) => sum + item.nominal,
      0,
    );
    const dataToExport = transaksiList.map((p, index) => ({
      No: index + 1,
      Tanggal: new Date(p.createdAt).toLocaleString("id-ID"),
      "Nama Donatur": p.nama,
      Nominal: p.nominal,
      Metode: p.metode,
      "Pesan / Doa": p.doa,
      Status: p.statusValidasi ? "Tervalidasi" : "Menunggu",
    }));

    dataToExport.push({
      No: "",
      Tanggal: "",
      "Nama Donatur": "TOTAL TERKUMPUL",
      Nominal: totalTerkumpul,
      Metode: "",
      "Pesan / Doa": "",
      Status: "",
    } as any);

    const worksheet = XLSX.utils.json_to_sheet(dataToExport);
    worksheet["!cols"] = [
      { wch: 5 },
      { wch: 20 },
      { wch: 25 },
      { wch: 15 },
      { wch: 15 },
      { wch: 40 },
      { wch: 15 },
    ];

    const workbook = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(workbook, worksheet, "Rekap Donasi");

    const safeFileName = selectedPeriode.judul
      .replace(/[^a-z0-9]/gi, "_")
      .toLowerCase();
    XLSX.writeFile(workbook, `Rekap_Donasi_${safeFileName}.xlsx`);
  };

  // --- HITUNG TOTAL DINAMIS ---
  const totalTerkumpul = transaksiList.reduce(
    (sum, item) => sum + item.nominal,
    0,
  );
  const persentase =
    selectedPeriode?.targetDana > 0
      ? Math.min(
          Math.round((totalTerkumpul / selectedPeriode.targetDana) * 100),
          100,
        )
      : 0;

  // ==========================================
  // RENDER UI BERDASARKAN STATUS AKSES
  // ==========================================
  if (hasAccess === null) {
    return (
      <div className="min-h-screen bg-[#F8FAFC] flex flex-col items-center justify-center p-6">
        <div className="w-12 h-12 border-4 border-slate-200 border-t-blue-600 rounded-full animate-spin mb-4"></div>
        <p className="text-slate-500 font-bold uppercase tracking-widest text-[10px] animate-pulse">
          Memverifikasi Otoritas Akses...
        </p>
      </div>
    );
  }

  if (hasAccess === false) {
    return (
      <div className="min-h-[70vh] flex flex-col items-center justify-center text-center px-4">
        <div className="bg-rose-50 p-6 rounded-full mb-6 ring-8 ring-rose-50/50">
          <svg
            className="w-16 h-16 text-rose-500"
            fill="none"
            viewBox="0 0 24 24"
            stroke="currentColor"
            strokeWidth={1.5}
          >
            <path
              strokeLinecap="round"
              strokeLinejoin="round"
              d="M16.5 10.5V6.75a4.5 4.5 0 10-9 0v3.75m-.75 11.25h10.5a2.25 2.25 0 002.25-2.25v-6.75a2.25 2.25 0 00-2.25-2.25H6.75a2.25 2.25 0 00-2.25 2.25v6.75a2.25 2.25 0 002.25 2.25z"
            />
          </svg>
        </div>
        <h2 className="text-3xl font-extrabold text-slate-900 mb-3 tracking-tight">
          Akses Ditolak
        </h2>
        <p className="text-slate-500 font-medium leading-relaxed max-w-md">
          Halaman Manajemen Donasi adalah area finansial terbatas. Akses hanya
          diberikan kepada <b>Super Admin</b> atau Koordinator{" "}
          <b>Bidang Sosial dan Keagamaan</b>.
        </p>
        <button
          onClick={() => window.history.back()}
          className="mt-8 bg-slate-900 hover:bg-slate-800 text-white px-6 py-3 rounded-xl font-semibold transition-all shadow-sm"
        >
          Kembali ke Dashboard
        </button>
      </div>
    );
  }

  if (isLoadingPeriode) {
    return (
      <div className="min-h-[70vh] flex flex-col items-center justify-center text-center px-4">
        <div className="w-8 h-8 border-4 border-slate-200 border-t-emerald-500 rounded-full animate-spin mb-4"></div>
        <p className="text-slate-500 font-bold uppercase tracking-widest text-[10px] animate-pulse">
          Memuat Sistem Rekapitulasi...
        </p>
      </div>
    );
  }

  // JIKA AKSES DIBERIKAN, RENDER HALAMAN UTAMA
  return (
    <div className="min-h-screen bg-[#F8FAFC] pb-12 font-sans selection:bg-blue-100 selection:text-blue-900">
      <div className="max-w-[1400px] mx-auto animate-in fade-in duration-500 pt-4 px-4 sm:px-6 lg:px-8">
        {/* --- HEADER --- */}
        <div className="mb-8">
          <div className="inline-flex items-center gap-1.5 bg-emerald-100 text-emerald-800 text-[10px] font-bold px-3 py-1 rounded-full mb-3 uppercase tracking-widest border border-emerald-200">
            <svg
              className="w-3.5 h-3.5"
              fill="none"
              viewBox="0 0 24 24"
              stroke="currentColor"
              strokeWidth={2.5}
            >
              <path
                strokeLinecap="round"
                strokeLinejoin="round"
                d="M12 6v12m-3-2.818l.879.659c1.171.879 3.07.879 4.242 0 1.172-.879 1.172-2.303 0-3.182C13.536 12.219 12.768 12 12 12c-.725 0-1.45-.22-2.003-.659-1.106-.879-1.106-2.303 0-3.182s2.9-.879 4.006 0l.415.33M21 12a9 9 0 11-18 0 9 9 0 0118 0z"
              />
            </svg>
            Finance & Donation Module
          </div>
          <h1 className="text-3xl md:text-4xl font-extrabold text-slate-900 tracking-tight mb-2">
            Manajemen Donasi
          </h1>
          <p className="text-slate-500 text-sm md:text-base max-w-2xl">
            Kelola pendanaan, catat transaksi manual, dan pantau progres
            pencapaian target donasi secara real-time.
          </p>
        </div>

        <div className="grid lg:grid-cols-12 gap-8 items-start">
          {/* ======================================= */}
          {/* KOLOM KIRI: LIST PERIODE / EDISI        */}
          {/* ======================================= */}
          <div className="lg:col-span-4 xl:col-span-3 flex flex-col gap-6">
            {/* Panel Buka Periode */}
            <div className="bg-slate-900 p-6 rounded-2xl shadow-lg shadow-slate-900/10 relative overflow-hidden text-white border border-slate-800">
              <div className="absolute -right-10 -top-10 w-32 h-32 bg-emerald-500 rounded-full blur-3xl opacity-20 pointer-events-none"></div>
              <h3 className="text-base font-bold mb-1 relative z-10">
                Buka Edisi Baru
              </h3>
              <p className="text-xs text-slate-400 mb-5 relative z-10 leading-relaxed">
                Buat sesi donasi baru untuk pekan atau program khusus.
              </p>
              <button
                onClick={() => setIsModalPeriodeOpen(true)}
                className="w-full bg-emerald-500 hover:bg-emerald-400 text-slate-950 font-bold py-2.5 rounded-xl shadow-md transition-colors relative z-10 flex items-center justify-center gap-2 text-sm"
              >
                <IconPlus /> Buat Edisi
              </button>
            </div>

            {/* List Riwayat Edisi */}
            <div className="bg-white rounded-2xl shadow-sm border border-slate-200 overflow-hidden flex flex-col max-h-[600px]">
              <div className="p-4 border-b border-slate-100 bg-slate-50/50">
                <h3 className="font-bold text-slate-700 text-xs uppercase tracking-widest">
                  Riwayat Edisi Donasi
                </h3>
              </div>
              <div className="p-3 overflow-y-auto custom-scrollbar flex-grow space-y-2">
                {periodeList.length === 0 ? (
                  <p className="text-center text-xs text-slate-400 py-8">
                    Belum ada edisi dibuka.
                  </p>
                ) : (
                  periodeList.map((p) => (
                    <div
                      key={p.id}
                      onClick={() => setSelectedPeriode(p)}
                      className={`p-4 rounded-xl cursor-pointer transition-all border ${
                        selectedPeriode?.id === p.id
                          ? "bg-blue-50 border-blue-200 ring-1 ring-blue-500 shadow-sm"
                          : "bg-white border-transparent hover:bg-slate-50 border-slate-100"
                      }`}
                    >
                      <div className="flex justify-between items-start mb-1.5">
                        <h4
                          className={`font-bold text-sm leading-tight pr-2 ${selectedPeriode?.id === p.id ? "text-blue-900" : "text-slate-800"}`}
                        >
                          {p.judul}
                        </h4>
                      </div>
                      <div className="flex items-center justify-between mt-2">
                        <p className="text-[10px] text-slate-400 font-medium">
                          {new Date(p.createdAt).toLocaleDateString("id-ID", {
                            day: "numeric",
                            month: "short",
                            year: "numeric",
                          })}
                        </p>
                        <span
                          className={`text-[9px] font-bold px-2 py-0.5 rounded uppercase tracking-wider ${p.status === "Aktif" ? "bg-emerald-100 text-emerald-700" : "bg-slate-100 text-slate-500"}`}
                        >
                          {p.status}
                        </span>
                      </div>
                    </div>
                  ))
                )}
              </div>
            </div>
          </div>

          {/* ======================================= */}
          {/* KOLOM KANAN: DETAIL REKAP & TRANSAKSI   */}
          {/* ======================================= */}
          <div className="lg:col-span-8 xl:col-span-9 flex flex-col gap-6">
            {!selectedPeriode ? (
              <div className="bg-white rounded-2xl shadow-sm border border-slate-200 flex flex-col items-center justify-center h-[500px]">
                <div className="w-16 h-16 bg-slate-50 text-slate-300 rounded-full flex items-center justify-center mb-4">
                  <IconWallet />
                </div>
                <p className="text-slate-500 font-medium text-sm">
                  Pilih salah satu edisi di samping untuk melihat rekapitulasi.
                </p>
              </div>
            ) : (
              <>
                {/* KARTU STATISTIK ATAS */}
                <div className="bg-white rounded-2xl shadow-sm border border-slate-200 p-6 sm:p-8 relative overflow-hidden">
                  <div className="flex flex-col md:flex-row md:items-end justify-between gap-6 relative z-10">
                    <div>
                      <div className="flex items-center gap-3 mb-2">
                        <h2 className="text-xl sm:text-2xl font-extrabold text-slate-900 tracking-tight">
                          {selectedPeriode.judul}
                        </h2>
                        <button
                          onClick={() =>
                            handleTutupPeriode(
                              selectedPeriode.id,
                              selectedPeriode.status,
                            )
                          }
                          className={`text-[10px] font-bold px-3 py-1 rounded-full uppercase tracking-widest border transition-all ${selectedPeriode.status === "Aktif" ? "bg-rose-50 border-rose-200 text-rose-600 hover:bg-rose-100" : "bg-emerald-50 border-emerald-200 text-emerald-700 hover:bg-emerald-100"}`}
                        >
                          {selectedPeriode.status === "Aktif"
                            ? "Tutup Donasi"
                            : "Buka Kembali"}
                        </button>
                      </div>
                      <p className="text-xs font-bold text-slate-400 uppercase tracking-widest mt-6 mb-1">
                        Total Dana Terkumpul
                      </p>
                      <h1 className="text-4xl sm:text-5xl font-black text-slate-900 tracking-tighter">
                        {formatRp(totalTerkumpul)}
                      </h1>
                    </div>

                    <div className="flex flex-col sm:flex-row gap-3 w-full md:w-auto">
                      <button
                        onClick={() => setIsModalDonasiOpen(true)}
                        className="bg-white hover:bg-slate-50 text-slate-700 border border-slate-300 px-5 py-2.5 rounded-xl font-bold text-sm transition-all shadow-sm flex items-center justify-center gap-2"
                      >
                        <IconPlus /> Input Manual
                      </button>
                      <button
                        onClick={downloadExcel}
                        disabled={transaksiList.length === 0}
                        className="bg-slate-900 hover:bg-slate-800 text-white px-5 py-2.5 rounded-xl font-bold text-sm transition-all shadow-md flex items-center justify-center gap-2 disabled:opacity-50 disabled:cursor-not-allowed"
                      >
                        <IconDownload /> Export Excel
                      </button>
                    </div>
                  </div>

                  {/* PROGRESS BAR */}
                  {selectedPeriode.targetDana > 0 && (
                    <div className="mt-8 relative z-10 pt-6 border-t border-slate-100">
                      <div className="flex justify-between items-end mb-2">
                        <div className="text-xs font-semibold text-slate-500 uppercase tracking-widest">
                          Pencapaian Target
                        </div>
                        <div className="text-right">
                          <span className="text-lg font-bold text-emerald-600">
                            {persentase}%
                          </span>
                          <span className="text-xs font-medium text-slate-400 ml-2">
                            dari {formatRp(selectedPeriode.targetDana)}
                          </span>
                        </div>
                      </div>
                      <div className="w-full bg-slate-100 rounded-full h-3 overflow-hidden border border-slate-200/50">
                        <div
                          className="bg-emerald-500 h-full rounded-full transition-all duration-1000 ease-out relative"
                          style={{ width: `${persentase}%` }}
                        >
                          <div className="absolute inset-0 bg-white/20 w-full animate-[shimmer_2s_infinite]"></div>
                        </div>
                      </div>
                    </div>
                  )}
                </div>

                {/* TABEL RINCIAN DONATUR */}
                <div className="bg-white rounded-2xl shadow-sm border border-slate-200 overflow-hidden flex-grow">
                  <div className="p-5 border-b border-slate-100 bg-slate-50/50 flex justify-between items-center">
                    <h3 className="font-bold text-slate-800 text-sm">
                      Rincian Transaksi Masuk
                    </h3>
                    <span className="bg-white border border-slate-200 text-slate-600 font-semibold text-xs py-1 px-3 rounded-lg shadow-sm">
                      {transaksiList.length} Transaksi
                    </span>
                  </div>

                  {isLoadingTransaksi ? (
                    <div className="p-16 flex justify-center">
                      <div className="w-8 h-8 border-4 border-slate-200 border-t-blue-600 rounded-full animate-spin"></div>
                    </div>
                  ) : transaksiList.length === 0 ? (
                    <div className="p-20 text-center flex flex-col items-center">
                      <div className="w-16 h-16 bg-slate-50 text-slate-300 rounded-full flex items-center justify-center mb-4">
                        <IconWallet />
                      </div>
                      <h3 className="font-semibold text-slate-700">
                        Belum ada transaksi
                      </h3>
                      <p className="text-sm text-slate-500 mt-1">
                        Gunakan tombol "Input Manual" untuk mencatat dana.
                      </p>
                    </div>
                  ) : (
                    <div className="overflow-x-auto">
                      <table className="w-full text-left border-collapse whitespace-nowrap">
                        <thead>
                          <tr className="bg-white border-b border-slate-100 text-[10px] uppercase tracking-widest text-slate-400">
                            <th className="px-6 py-4 font-bold">Waktu</th>
                            <th className="px-6 py-4 font-bold">
                              Donatur & Metode
                            </th>
                            <th className="px-6 py-4 font-bold text-right">
                              Nominal
                            </th>
                            <th className="px-6 py-4 font-bold">
                              Titipan Pesan/Doa
                            </th>
                            <th className="px-6 py-4 font-bold text-center">
                              Status
                            </th>
                          </tr>
                        </thead>
                        <tbody className="divide-y divide-slate-50">
                          {transaksiList.map((t) => (
                            <tr
                              key={t.id}
                              className="hover:bg-slate-50 transition-colors text-sm group"
                            >
                              <td className="px-6 py-4 text-xs text-slate-500 align-top">
                                {new Date(t.createdAt).toLocaleDateString(
                                  "id-ID",
                                  { day: "2-digit", month: "short" },
                                )}
                                <span className="text-[10px] text-slate-400 block mt-0.5">
                                  {new Date(t.createdAt).toLocaleTimeString(
                                    "id-ID",
                                    { hour: "2-digit", minute: "2-digit" },
                                  )}
                                </span>
                              </td>
                              <td className="px-6 py-4 align-top">
                                <p className="font-bold text-slate-800 mb-0.5">
                                  {t.nama}
                                </p>
                                <p className="text-[10px] text-slate-500 font-medium inline-block bg-slate-100 px-2 py-0.5 rounded border border-slate-200">
                                  {t.metode}
                                </p>
                              </td>
                              <td className="px-6 py-4 font-bold text-slate-900 text-right align-top tracking-tight">
                                {formatRp(t.nominal)}
                              </td>
                              <td
                                className="px-6 py-4 text-xs text-slate-600 max-w-[200px] truncate align-top"
                                title={t.doa}
                              >
                                {t.doa === "-" ? (
                                  <span className="text-slate-300 italic">
                                    Tidak ada pesan
                                  </span>
                                ) : (
                                  t.doa
                                )}
                              </td>
                              <td className="px-6 py-4 text-center align-top">
                                {t.statusValidasi ? (
                                  <span className="inline-flex items-center bg-emerald-50 text-emerald-700 border border-emerald-200 text-[10px] font-bold px-2 py-1 rounded uppercase tracking-wider">
                                    Sah
                                  </span>
                                ) : (
                                  <span className="inline-flex items-center bg-amber-50 text-amber-700 border border-amber-200 text-[10px] font-bold px-2 py-1 rounded uppercase tracking-wider">
                                    Pending
                                  </span>
                                )}
                              </td>
                            </tr>
                          ))}
                        </tbody>
                      </table>
                    </div>
                  )}
                </div>
              </>
            )}
          </div>
        </div>
      </div>

      {/* ======================================= */}
      {/* MODAL AREA                              */}
      {/* ======================================= */}

      {/* MODAL BUAT PERIODE BARU */}
      {isModalPeriodeOpen && (
        <div className="fixed inset-0 bg-slate-900/60 backdrop-blur-sm z-50 flex items-center justify-center p-4 font-sans">
          <div className="bg-white rounded-2xl p-6 sm:p-8 max-w-md w-full shadow-2xl relative animate-in zoom-in-95 duration-200 border border-slate-100">
            <button
              onClick={() => setIsModalPeriodeOpen(false)}
              className="absolute top-4 right-4 p-2 text-slate-400 hover:bg-slate-100 rounded-full transition-colors"
            >
              <IconClose />
            </button>
            <div className="flex items-center gap-3 mb-6">
              <div className="bg-emerald-50 text-emerald-600 p-2 rounded-xl border border-emerald-100">
                <IconPlus />
              </div>
              <h3 className="text-lg font-bold text-slate-900 tracking-tight">
                Buka Edisi Baru
              </h3>
            </div>

            <form onSubmit={handleBuatPeriode} className="space-y-4">
              <div>
                <label className="block text-xs font-semibold text-slate-600 uppercase tracking-wide mb-1.5">
                  Nama Edisi / Program
                </label>
                <input
                  type="text"
                  required
                  value={newPeriode.judul}
                  onChange={(e) =>
                    setNewPeriode({ ...newPeriode, judul: e.target.value })
                  }
                  placeholder="Cth: Jum'at Berkah Pekan 2"
                  className="w-full px-4 py-2.5 bg-slate-50 border border-slate-200 rounded-xl focus:bg-white focus:border-emerald-500 focus:ring-2 focus:ring-emerald-100 outline-none text-sm transition-all"
                />
              </div>
              <div>
                <label className="block text-xs font-semibold text-slate-600 uppercase tracking-wide mb-1.5">
                  Target Dana (Opsional)
                </label>
                <div className="relative">
                  <span className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400 font-medium text-sm">
                    Rp
                  </span>
                  <input
                    type="number"
                    value={newPeriode.targetDana}
                    onChange={(e) =>
                      setNewPeriode({
                        ...newPeriode,
                        targetDana: e.target.value,
                      })
                    }
                    placeholder="5000000"
                    className="w-full pl-10 pr-4 py-2.5 bg-slate-50 border border-slate-200 rounded-xl focus:bg-white focus:border-emerald-500 focus:ring-2 focus:ring-emerald-100 outline-none text-sm font-mono transition-all"
                  />
                </div>
              </div>
              <button
                type="submit"
                disabled={isSubmitting}
                className="w-full bg-emerald-600 hover:bg-emerald-700 text-white font-semibold py-3 rounded-xl transition-colors mt-6 shadow-sm disabled:opacity-50 text-sm"
              >
                {isSubmitting ? "Memproses..." : "Buka Periode Sekarang"}
              </button>
            </form>
          </div>
        </div>
      )}

      {/* MODAL INPUT DONASI MANUAL */}
      {isModalDonasiOpen && (
        <div className="fixed inset-0 bg-slate-900/60 backdrop-blur-sm z-50 flex items-center justify-center p-4 font-sans">
          <div className="bg-white rounded-2xl p-6 sm:p-8 max-w-md w-full shadow-2xl relative animate-in zoom-in-95 duration-200 border border-slate-100">
            <button
              onClick={() => setIsModalDonasiOpen(false)}
              className="absolute top-4 right-4 p-2 text-slate-400 hover:bg-slate-100 rounded-full transition-colors"
            >
              <IconClose />
            </button>
            <div className="flex items-center gap-3 mb-2">
              <div className="bg-blue-50 text-blue-600 p-2 rounded-xl border border-blue-100">
                <svg
                  className="w-5 h-5"
                  fill="none"
                  viewBox="0 0 24 24"
                  stroke="currentColor"
                >
                  <path
                    strokeLinecap="round"
                    strokeLinejoin="round"
                    strokeWidth={2}
                    d="M12 6v6m0 0v6m0-6h6m-6 0H6"
                  />
                </svg>
              </div>
              <h3 className="text-lg font-bold text-slate-900 tracking-tight">
                Input Donasi Manual
              </h3>
            </div>
            <p className="text-xs text-slate-500 mb-6 font-medium">
              Catat dana titipan tunai (cash) ke dalam sistem.
            </p>

            <form onSubmit={handleInputDonasi} className="space-y-4">
              <div>
                <label className="block text-xs font-semibold text-slate-600 uppercase tracking-wide mb-1.5">
                  Nama Donatur
                </label>
                <input
                  type="text"
                  value={newDonasi.nama}
                  onChange={(e) =>
                    setNewDonasi({ ...newDonasi, nama: e.target.value })
                  }
                  placeholder="Biarkan kosong untuk Hamba Allah"
                  className="w-full px-4 py-2.5 bg-slate-50 border border-slate-200 rounded-xl focus:bg-white focus:border-blue-500 focus:ring-2 focus:ring-blue-100 outline-none text-sm transition-all"
                />
              </div>
              <div>
                <label className="block text-xs font-semibold text-slate-600 uppercase tracking-wide mb-1.5">
                  Nominal Tunai
                </label>
                <div className="relative">
                  <span className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400 font-medium text-sm">
                    Rp
                  </span>
                  <input
                    type="number"
                    required
                    value={newDonasi.nominal}
                    onChange={(e) =>
                      setNewDonasi({ ...newDonasi, nominal: e.target.value })
                    }
                    placeholder="500000"
                    className="w-full pl-10 pr-4 py-2.5 bg-slate-50 border border-slate-200 rounded-xl focus:bg-white focus:border-blue-500 focus:ring-2 focus:ring-blue-100 outline-none text-sm font-mono transition-all"
                  />
                </div>
              </div>
              <div>
                <label className="block text-xs font-semibold text-slate-600 uppercase tracking-wide mb-1.5">
                  Titipan Pesan / Doa
                </label>
                <textarea
                  value={newDonasi.doa}
                  onChange={(e) =>
                    setNewDonasi({ ...newDonasi, doa: e.target.value })
                  }
                  rows={2}
                  className="w-full px-4 py-3 bg-slate-50 border border-slate-200 rounded-xl focus:bg-white focus:border-blue-500 focus:ring-2 focus:ring-blue-100 outline-none text-sm transition-all custom-scrollbar"
                ></textarea>
              </div>
              <button
                type="submit"
                disabled={isSubmitting}
                className="w-full bg-slate-900 hover:bg-slate-800 text-white font-semibold py-3 rounded-xl transition-colors mt-6 shadow-sm disabled:opacity-50 text-sm"
              >
                {isSubmitting ? "Menyimpan..." : "Simpan Transaksi"}
              </button>
            </form>
          </div>
        </div>
      )}
    </div>
  );
}

"use client";

import { useState, useEffect, useRef } from "react";
import { toast } from "@/lib/toast";
import { db } from "@/lib/firebase";
import {
  collection,
  addDoc,
  getDocs,
  query,
  orderBy,
  updateDoc,
  doc,
  deleteDoc,
} from "firebase/firestore";
import Link from "next/link";

export default function ManajemenNomorSuratPage() {
  const [nomorList, setNomorList] = useState<any[]>([]);
  const [pengurusList, setPengurusList] = useState<any[]>([]);
  const [filterStatus, setFilterStatus] = useState("semua");
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [isLoading, setIsLoading] = useState(true);
  const [isSaving, setIsSaving] = useState(false);

  // State untuk mode edit
  const [editId, setEditId] = useState<string | null>(null);

  const [itemsPerPage, setItemsPerPage] = useState<number>(10);
  const [currentPage, setCurrentPage] = useState<number>(1);

  const [searchPenerima, setSearchPenerima] = useState("");
  const [isDropdownOpen, setIsDropdownOpen] = useState(false);
  const dropdownRef = useRef<HTMLDivElement>(null);

  // 🔥 Form Generator Nomor & Setup Surat (Ditambah Penutup & Jabatan) 🔥
  const [genForm, setGenForm] = useState({
    nomorUrut: "",
    jenis: "Surat Undangan",
    kategori: "Internal",
    index: "UND",
    perihal: "",
    isiSurat:
      "Assalamu’alaikum warahmatullahi wabarakaatuh.\n\nDengan hormat, sehubungan dengan akan dilaksanakannya [nama agenda], kami mengundang Bapak/Ibu untuk berkenan hadir pada rapat koordinasi yang akan dilaksanakan pada:",
    penutupSurat:
      "Demikian surat undangan ini kami sampaikan. Atas perhatian dan kehadirannya, kami ucapkan terima kasih.",
    pembuat: "",
    jabatanPembuat: "",
    tglMasehi: new Date().toISOString().split("T")[0],
    preview: "",
    templateSurat: "Undangan Lipat 3",
    penerima: [] as string[],
    tglPelaksanaan: "",
    waktuPelaksanaan: "",
    tipePelaksanaan: "Offline" as "Offline" | "Online",
    tempatPelaksanaan: "",
    linkZoom: "",
  });

  // 🔥 TAMBAHAN STATE UNTUK MODE AMBIL NOMOR SAJA 🔥
  const [modeForm, setModeForm] = useState<"lengkap" | "cepat">("lengkap");
  const [formCepat, setFormCepat] = useState({
    jenisSurat: "Surat Keluar Umum",
    perihal: "",
    tujuan: "",
    tanggalSurat: new Date().toISOString().split("T")[0],
    pembuat: "",
    jabatanPembuat: "",
  });

  const handleAmbilNomor = async (e: React.FormEvent) => {
    e.preventDefault();
    setIsSaving(true);
    try {
      // 1. Cari nomor urut terakhir
      let nextNo = "001";
      if (nomorList.length > 0) {
        const lastNumber = parseInt(nomorList[0].nomor.split("/")[0]);
        if (!isNaN(lastNumber)) {
          nextNo = String(lastNumber + 1).padStart(3, "0");
        }
      }

      // 2. Format Romawi Bulan & Tahun
      const arrBulan = [
        "I",
        "II",
        "III",
        "IV",
        "V",
        "VI",
        "VII",
        "VIII",
        "IX",
        "X",
        "XI",
        "XII",
      ];
      const d = new Date(formCepat.tanggalSurat);
      const bln = arrBulan[d.getMonth()];
      const thn = d.getFullYear().toString();

      // 3. Tentukan Kode (Bisa disesuaikan)
      let kode = "UM";
      if (formCepat.jenisSurat === "Surat Keputusan") kode = "SKep";
      if (formCepat.jenisSurat === "Surat Tugas") kode = "ST";
      if (formCepat.jenisSurat === "Surat Keterangan") kode = "SK";

      const generatedNomor = `${nextNo}/IKA-UII/DIY/${kode}/${bln}/${thn}`;

      const payload = {
        nomor: generatedNomor,
        jenis: formCepat.jenisSurat,
        perihal: formCepat.perihal,
        penerima: formCepat.tujuan ? [formCepat.tujuan] : [],
        tanggal: formCepat.tanggalSurat,
        tipeForm: "Buku Agenda Manual",
        status: "Sudah terpakai", // Langsung terpakai agar tidak diambil orang lain
        pembuat: formCepat.pembuat,
        jabatanPembuat: formCepat.jabatanPembuat,
        createdAt: Date.now(),
        updatedAt: Date.now(),
      };

      await addDoc(collection(db, "nomor_surat"), payload);
      toast.success(`Berhasil! Nomor Surat Anda: ${generatedNomor}. Silakan salin nomor tersebut ke dokumen Word Anda.`);

      setFormCepat({ ...formCepat, perihal: "", tujuan: "", pembuat: "", jabatanPembuat: "" });
      setIsModalOpen(false);
      fetchData();
    } catch (error) {
      toast.error("Gagal mengambil nomor surat.");
    } finally {
      setIsSaving(false);
    }
  };

  const fetchData = async () => {
    setIsLoading(true);
    try {
      const q = query(
        collection(db, "nomor_surat"),
        orderBy("createdAt", "desc"),
      );
      const snap = await getDocs(q);
      const data = snap.docs.map((d) => ({ id: d.id, ...d.data() }));
      setNomorList(data);

      const qPengurus = query(
        collection(db, "pengurus"),
        orderBy("nama", "asc"),
      );
      const snapPengurus = await getDocs(qPengurus);
      const dataPengurus = snapPengurus.docs.map((d) => ({
        id: d.id,
        ...d.data(),
      }));
      setPengurusList(dataPengurus);

      // Auto-suggest Nomor Urut hanya jika TIDAK sedang mode edit
      if (!editId) {
        if (data.length > 0 && !genForm.nomorUrut) {
          const lastNumber = parseInt((data[0] as any).nomor.split("/")[0]);
          if (!isNaN(lastNumber)) {
            setGenForm((prev) => ({
              ...prev,
              nomorUrut: String(lastNumber + 1).padStart(3, "0"),
            }));
          }
        } else if (data.length === 0) {
          setGenForm((prev) => ({ ...prev, nomorUrut: "001" }));
        }
      }
    } catch (error) {
      console.error("Gagal menarik data:", error);
    } finally {
      setIsLoading(false);
    }
  };

  useEffect(() => {
    fetchData();
  }, []);

  useEffect(() => {
    setCurrentPage(1);
  }, [filterStatus, itemsPerPage]);

  useEffect(() => {
    function handleClickOutside(event: MouseEvent) {
      if (
        dropdownRef.current &&
        !dropdownRef.current.contains(event.target as Node)
      ) {
        setIsDropdownOpen(false);
      }
    }
    document.addEventListener("mousedown", handleClickOutside);
    return () => document.removeEventListener("mousedown", handleClickOutside);
  }, []);

  useEffect(() => {
    const arrBulan = [
      "I",
      "II",
      "III",
      "IV",
      "V",
      "VI",
      "VII",
      "VIII",
      "IX",
      "X",
      "XI",
      "XII",
    ];
    const d = new Date(genForm.tglMasehi);
    const bln = isNaN(d.getTime()) ? "..." : arrBulan[d.getMonth()];
    const thn = isNaN(d.getTime()) ? "..." : d.getFullYear().toString();
    const no = genForm.nomorUrut || "000";
    const kode = genForm.index;
    const result = `[NO]/IKA-UII/DIY/[KODE]/[BLN]/[THN]`
      .replace("[NO]", no)
      .replace("[KODE]", kode)
      .replace("[BLN]", bln)
      .replace("[THN]", thn);
    setGenForm((prev) => ({ ...prev, preview: result }));
  }, [genForm.nomorUrut, genForm.index, genForm.tglMasehi]);

  const handleEdit = (docData: any) => {
    const parts = docData.nomor.split("/");
    const noUrut = parts[0] || "";
    const kode = parts[3] || "UND";

    setGenForm({
      nomorUrut: noUrut,
      index: kode,
      jenis: docData.jenis || "Surat Undangan",
      kategori: docData.kategori || "Internal",
      perihal: docData.perihal || "",
      isiSurat: docData.isiSurat || "",
      penutupSurat:
        docData.penutupSurat ||
        "Demikian surat undangan ini kami sampaikan. Atas perhatian dan kehadirannya, kami ucapkan terima kasih.",
      pembuat: docData.pembuat || "",
      jabatanPembuat: docData.jabatanPembuat || "",
      tglMasehi: docData.tanggal || new Date().toISOString().split("T")[0],
      preview: docData.nomor || "",
      templateSurat: docData.templateSurat || "Undangan Lipat 3",
      penerima: docData.penerima || [],
      tglPelaksanaan: docData.tglPelaksanaan || "",
      waktuPelaksanaan: docData.waktuPelaksanaan || "",
      tipePelaksanaan: docData.tipePelaksanaan || "Offline",
      tempatPelaksanaan: docData.tempatPelaksanaan || "",
      linkZoom: docData.linkZoom || "",
    });
    setEditId(docData.id);
    setModeForm("lengkap");
    setIsModalOpen(true);
  };

  const handleSave = async () => {
    if (!genForm.nomorUrut || !genForm.perihal || !genForm.pembuat) {
      toast.warning("Nomor, Perihal, dan Nama Pembuat wajib diisi!");
      return;
    }
    setIsSaving(true);
    try {
      const payload = {
        nomor: genForm.preview,
        perihal: genForm.perihal,
        isiSurat: genForm.isiSurat,
        penutupSurat: genForm.penutupSurat,
        tglPelaksanaan: genForm.tglPelaksanaan,
        waktuPelaksanaan: genForm.waktuPelaksanaan,
        tipePelaksanaan: genForm.tipePelaksanaan,
        tempatPelaksanaan: genForm.tempatPelaksanaan,
        linkZoom: genForm.linkZoom,
        jenis: genForm.jenis,
        kategori: genForm.kategori,
        tanggal: genForm.tglMasehi,
        pembuat: genForm.pembuat,
        jabatanPembuat: genForm.jabatanPembuat,
        templateSurat: genForm.templateSurat,
        penerima: genForm.penerima,
        updatedAt: Date.now(),
      };

      if (editId) {
        await updateDoc(doc(db, "nomor_surat", editId), payload);
      } else {
        await addDoc(collection(db, "nomor_surat"), {
          ...payload,
          status: "Belum terpakai",
          createdAt: Date.now(),
        });
      }

      setIsModalOpen(false);
      setEditId(null);
      setGenForm({
        nomorUrut: "",
        jenis: "Surat Undangan",
        kategori: "Internal",
        index: "UND",
        perihal: "",
        isiSurat: "Assalamu’alaikum warahmatullahi wabarakaatuh.\n\nDengan hormat, sehubungan dengan akan dilaksanakannya [nama agenda], kami mengundang Bapak/Ibu untuk berkenan hadir pada rapat koordinasi yang akan dilaksanakan pada:",
        penutupSurat: "Demikian surat undangan ini kami sampaikan. Atas perhatian dan kehadirannya, kami ucapkan terima kasih.",
        pembuat: "",
        jabatanPembuat: "",
        tglMasehi: new Date().toISOString().split("T")[0],
        preview: "",
        templateSurat: "Undangan Lipat 3",
        penerima: [],
        tglPelaksanaan: "",
        waktuPelaksanaan: "",
        tipePelaksanaan: "Offline",
        tempatPelaksanaan: "",
        linkZoom: "",
      });
      setSearchPenerima("");
      fetchData();
    } catch (error) {
      toast.error("Gagal menyimpan dokumen.");
      console.error(error);
    } finally {
      setIsSaving(false);
    }
  };

  const toggleStatus = async (id: string, currentStatus: string) => {
    const newStatus =
      currentStatus === "Sudah terpakai" ? "Belum terpakai" : "Sudah terpakai";
    await updateDoc(doc(db, "nomor_surat", id), {
      status: newStatus,
      updatedAt: Date.now(),
    });
    fetchData();
  };

  const handleDelete = async (id: string) => {
    if (confirm("Yakin ingin menghapus nomor surat ini secara permanen?")) {
      await deleteDoc(doc(db, "nomor_surat", id));
      fetchData();
    }
  };

  // 🔥 FITUR MANAJEMEN PENERIMA ANTI REPOT 🔥
  const filteredPengurus = pengurusList.filter(
    (p) =>
      p.nama?.toLowerCase().includes(searchPenerima.toLowerCase()) &&
      !genForm.penerima.includes(p.nama),
  );

  const addPenerima = (nama: string) => {
    if (!nama.trim()) return;
    setGenForm((prev) => ({
      ...prev,
      penerima: [...prev.penerima, nama.trim()],
    }));
    setSearchPenerima("");
    setIsDropdownOpen(false);
  };

  const removePenerima = (nama: string) => {
    setGenForm((prev) => ({
      ...prev,
      penerima: prev.penerima.filter((n) => n !== nama),
    }));
  };

  const addSemuaPengurus = () => {
    const semuaNama = pengurusList.map((p) => p.nama).filter((n) => n);
    setGenForm((prev) => ({ ...prev, penerima: semuaNama }));
  };

  const hapusSemuaPengurus = () => {
    setGenForm((prev) => ({ ...prev, penerima: [] }));
  };

  const handleKeyDownPenerima = (e: React.KeyboardEvent<HTMLInputElement>) => {
    if (e.key === "Enter") {
      e.preventDefault();
      addPenerima(searchPenerima);
    }
  };

  const filteredList = nomorList.filter((n) => {
    if (filterStatus === "terpakai") return n.status === "Sudah terpakai";
    if (filterStatus === "belum") return n.status === "Belum terpakai";
    return true;
  });

  const totalItems = filteredList.length;
  const totalPages =
    itemsPerPage === 0 ? 1 : Math.ceil(totalItems / itemsPerPage);
  const currentTableData =
    itemsPerPage === 0
      ? filteredList
      : filteredList.slice(
          (currentPage - 1) * itemsPerPage,
          currentPage * itemsPerPage,
        );
  const startItem = totalItems === 0 ? 0 : (currentPage - 1) * itemsPerPage + 1;
  const endItem =
    itemsPerPage === 0
      ? totalItems
      : Math.min(currentPage * itemsPerPage, totalItems);

  if (isLoading && nomorList.length === 0) {
    return (
      <div className="min-h-screen flex items-center justify-center bg-[#F8F9FA]">
        <div className="animate-spin w-8 h-8 border-4 border-[#DADCE0] border-t-[#1A73E8] rounded-full"></div>
      </div>
    );
  }

  const DropdownIndexKode = () => (
    <select
      value={genForm.index}
      onChange={(e) => setGenForm({ ...genForm, index: e.target.value })}
      className="w-full bg-white border border-[#DADCE0] px-3 py-2 rounded-md text-sm text-[#202124] outline-none focus:border-[#1A73E8] focus:ring-1 focus:ring-[#1A73E8] transition-colors"
    >
      <option value="SR">SR (Surat Rekomendasi)</option>
      <option value="UND">UND (Surat Undangan)</option>
      <option value="SK">SK (Surat Keterangan)</option>
      <option value="SKep">SKep (Surat Keputusan)</option>
      <option value="SPT">SPT (Surat Pemberitahuan)</option>
      <option value="SPH">SPH (Surat Permohonan)</option>
      <option value="SE">SE (Surat Edaran)</option>
      <option value="SPTG">SPTG (Surat Pengantar)</option>
      <option value="SBL">SBL (Surat Balasan)</option>
      <option value="INS">INS (Surat Instruksi)</option>
      <option value="SNY">SNY (Surat Pernyataan)</option>
      <option value="SPJ">SPJ (Surat Perjanjian)</option>
      <option value="SGH">SGH (Surat Pengesahan)</option>
      <option value="STB">STB (Surat Tembusan)</option>
      <option value="SIZ">SIZ (Surat Izin)</option>
      <option value="SPK">SPK (Surat Penugasan Kegiatan)</option>
      <option value="ND">ND (Nota Dinas)</option>
      <option value="MEM">MEM (Memo)</option>
      <option value="SKL">SKL (Surat Klarifikasi)</option>
      <option value="SPP">SPP (Surat Pemberhentian/Penonaktifan)</option>
      <option value="BA">BA (Berita Acara)</option>
    </select>
  );

  return (
    <div className="min-h-screen pb-12 font-sans text-slate-800">
      <div className="max-w-7xl mx-auto animate-in fade-in duration-500">
        {/* HEADER */}
        <div className="mb-6 mt-4 flex flex-col md:flex-row md:items-end justify-between gap-4">
          <div>
            <h2 className="text-2xl font-medium text-slate-900 mb-1 tracking-tight">
              E-Office & Registri Surat
            </h2>
            <p className="text-slate-500 text-sm">
              Manajemen penomoran dan draf dokumen resmi IKA UII DIY.
            </p>
          </div>
          <div className="flex flex-col sm:flex-row gap-3">
            <button
              onClick={() => {
                setEditId(null);
                setModeForm("cepat");
                fetchData();
                setIsModalOpen(true);
              }}
              className="w-full sm:w-auto bg-white border border-blue-200 hover:border-blue-300 hover:bg-blue-50 text-blue-700 px-5 py-2.5 rounded-xl font-semibold text-sm shadow-sm transition-all flex items-center justify-center gap-2"
            >
              <svg className="w-4 h-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M7 20l4-16m2 16l4-16M6 9h14M4 15h14" /></svg>
              Generate Nomor Surat
            </button>
            <button
              onClick={() => {
                setEditId(null);
                setModeForm("lengkap");
                setGenForm({
                  nomorUrut: "",
                  jenis: "Surat Undangan",
                  kategori: "Internal",
                  index: "UND",
                  perihal: "",
                  isiSurat: "Assalamu’alaikum warahmatullahi wabarakaatuh.\n\nDengan hormat, sehubungan dengan akan dilaksanakannya [nama agenda], kami mengundang Bapak/Ibu untuk berkenan hadir pada rapat koordinasi yang akan dilaksanakan pada:",
                  penutupSurat: "Demikian surat undangan ini kami sampaikan. Atas perhatian dan kehadirannya, kami ucapkan terima kasih.",
                  pembuat: "",
                  jabatanPembuat: "",
                  tglMasehi: new Date().toISOString().split("T")[0],
                  preview: "",
                  templateSurat: "Undangan Lipat 3",
                  penerima: [],
                  tglPelaksanaan: "",
                  waktuPelaksanaan: "",
                  tipePelaksanaan: "Offline",
                  tempatPelaksanaan: "",
                  linkZoom: "",
                });
                fetchData();
                setIsModalOpen(true);
              }}
              className="w-full sm:w-auto bg-gradient-to-r from-blue-600 to-indigo-600 hover:from-blue-700 hover:to-indigo-700 text-white px-5 py-2.5 rounded-xl font-semibold text-sm shadow-md transition-all flex items-center justify-center gap-2"
            >
              <svg className="w-4 h-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 12h6m-6 4h6m2 5H7a2 2 0 01-2-2V5a2 2 0 012-2h5.586a1 1 0 01.707.293l5.414 5.414a1 1 0 01.293.707V19a2 2 0 01-2 2z" /></svg>
              Buat Surat Undangan
            </button>
          </div>
        </div>

        {/* STATISTIK */}
        <div className="grid grid-cols-1 md:grid-cols-3 gap-5 mb-8">
          <div
            onClick={() => setFilterStatus("semua")}
            className={`p-6 rounded-2xl cursor-pointer transition-all border shadow-sm ${filterStatus === "semua" ? "border-blue-200 bg-blue-50/80" : "bg-white/80 border-slate-200 hover:bg-slate-50 hover:shadow-md"}`}
          >
            <div className="text-sm font-medium text-slate-500 mb-2 flex items-center gap-2">
              <svg className="w-4 h-4 text-slate-400" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 12h6m-6 4h6m2 5H7a2 2 0 01-2-2V5a2 2 0 012-2h5.586a1 1 0 01.707.293l5.414 5.414a1 1 0 01.293.707V19a2 2 0 01-2 2z" /></svg>
              Total Dokumen
            </div>
            <h3 className={`text-4xl font-bold ${filterStatus === "semua" ? "text-blue-700" : "text-slate-800"}`}>
              {nomorList.length}
            </h3>
          </div>
          <div
            onClick={() => setFilterStatus("belum")}
            className={`p-6 rounded-2xl cursor-pointer transition-all border shadow-sm ${filterStatus === "belum" ? "border-amber-200 bg-amber-50/80" : "bg-white/80 border-slate-200 hover:bg-slate-50 hover:shadow-md"}`}
          >
            <div className="text-sm font-medium text-slate-500 mb-2 flex items-center gap-2">
              <svg className="w-4 h-4 text-slate-400" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15.232 5.232l3.536 3.536m-2.036-5.036a2.5 2.5 0 113.536 3.536L6.5 21.036H3v-3.572L16.732 3.732z" /></svg>
              Draf / Belum Terpakai
            </div>
            <h3 className={`text-4xl font-bold ${filterStatus === "belum" ? "text-amber-600" : "text-slate-800"}`}>
              {nomorList.filter((n) => n.status === "Belum terpakai").length}
            </h3>
          </div>
          <div
            onClick={() => setFilterStatus("terpakai")}
            className={`p-6 rounded-2xl cursor-pointer transition-all border shadow-sm ${filterStatus === "terpakai" ? "border-emerald-200 bg-emerald-50/80" : "bg-white/80 border-slate-200 hover:bg-slate-50 hover:shadow-md"}`}
          >
            <div className="text-sm font-medium text-slate-500 mb-2 flex items-center gap-2">
              <svg className="w-4 h-4 text-slate-400" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 12l2 2 4-4m6 2a9 9 0 11-18 0 9 9 0 0118 0z" /></svg>
              Dokumen Final
            </div>
            <h3 className={`text-4xl font-bold ${filterStatus === "terpakai" ? "text-emerald-600" : "text-slate-800"}`}>
              {nomorList.filter((n) => n.status === "Sudah terpakai").length}
            </h3>
          </div>
        </div>

        {/* TABEL DATABASE */}
        <div className="bg-white/90 backdrop-blur-md rounded-2xl shadow-sm border border-slate-200 overflow-hidden flex flex-col">
          <div className="p-5 border-b border-slate-200 flex flex-col sm:flex-row justify-between items-center gap-4">
            <div className="flex items-center gap-3">
              <h3 className="font-semibold text-slate-800">
                Daftar Registri
              </h3>
              <span className="bg-slate-100 text-slate-600 border border-slate-200 text-xs font-bold px-2.5 py-1 rounded-md uppercase tracking-wider">
                {filterStatus}
              </span>
            </div>
            <div className="flex items-center gap-2 text-sm text-slate-500">
              <span>Tampilkan:</span>
              <select
                value={itemsPerPage}
                onChange={(e) => setItemsPerPage(Number(e.target.value))}
                className="border border-slate-200 rounded-lg px-3 py-1.5 outline-none focus:border-blue-500 bg-white cursor-pointer"
              >
                <option value={10}>10</option>
                <option value={20}>20</option>
                <option value={50}>50</option>
                <option value={0}>Semua</option>
              </select>
            </div>
          </div>

          <div className="overflow-x-auto">
            <table className="w-full text-left text-sm whitespace-nowrap">
              <thead className="bg-slate-50/80 border-b border-slate-200 text-slate-500 text-xs font-semibold uppercase tracking-wider">
                <tr>
                  <th className="px-6 py-4">Nomor Dokumen</th>
                  <th className="px-6 py-4">Perihal & Template</th>
                  <th className="px-6 py-4">Pembuat / Tanggal</th>
                  <th className="px-6 py-4 text-center">Status</th>
                  <th className="px-6 py-4 text-right">Aksi</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-[#E8EAED]">
                {currentTableData.length === 0 ? (
                  <tr>
                    <td
                      colSpan={5}
                      className="py-12 text-center text-[#5F6368] text-sm"
                    >
                      Tidak ada data untuk ditampilkan.
                    </td>
                  </tr>
                ) : (
                  currentTableData.map((n) => (
                    <tr
                      key={n.id}
                      className="hover:bg-[#F8F9FA] transition-colors"
                    >
                      <td className="px-6 py-4">
                        <div className="font-medium text-[#1A73E8] text-[13px]">
                          {n.nomor}
                        </div>
                        <div className="text-xs text-[#5F6368] mt-1">
                          {n.kategori} • {n.jenis}
                        </div>
                      </td>
                      <td className="px-6 py-4">
                        <div className="text-[#202124] text-sm whitespace-normal line-clamp-2 max-w-sm">
                          {n.perihal}
                        </div>
                        <div className="text-[10px] text-[#5F6368] mt-1 bg-[#F1F3F4] px-1.5 py-0.5 rounded border border-[#DADCE0] w-fit">
                          Template: {n.templateSurat || "Standar A4"}
                        </div>
                      </td>
                      <td className="px-6 py-4">
                        <div className="text-sm text-[#202124]">
                          {n.pembuat}
                          {n.jabatanPembuat && (
                            <span className="text-[10px] text-gray-500 block">
                              {n.jabatanPembuat}
                            </span>
                          )}
                        </div>
                        <div className="text-xs text-[#5F6368] mt-0.5">
                          {new Date(n.tanggal).toLocaleDateString("id-ID", {
                            day: "numeric",
                            month: "short",
                            year: "numeric",
                          })}
                        </div>
                      </td>
                      <td className="px-6 py-4 text-center">
                        <button
                          onClick={() => toggleStatus(n.id, n.status)}
                          className={`text-[11px] font-medium px-2.5 py-1 rounded transition-colors border ${n.status === "Sudah terpakai" ? "bg-[#E6F4EA] text-[#1E8E3E] border-[#CEEAD6] hover:bg-[#CEEAD6]" : "bg-[#F8F9FA] text-[#5F6368] border-[#DADCE0] hover:bg-[#E8EAED]"}`}
                        >
                          {n.status === "Sudah terpakai" ? "Final" : "Draf"}
                        </button>
                      </td>
                      <td className="px-6 py-4 text-right">
                        <div className="flex items-center justify-end gap-2">
                          <Link
                            href={`/dashboard/e-office/print/${n.id}`}
                            target="_blank"
                            className="text-[#1A73E8] hover:text-[#1557B0] bg-[#E8F0FE] hover:bg-[#D2E3FC] px-3 py-1.5 rounded text-xs font-medium transition-colors"
                          >
                            Cetak
                          </Link>
                          {n.jenis === "Surat Undangan" && (
                            <Link
                              href={`/dashboard/e-office/print-presensi/${n.id}`}
                              target="_blank"
                              className="text-[#1E8E3E] hover:text-[#145C27] bg-[#E6F4EA] hover:bg-[#CEEAD6] px-3 py-1.5 rounded text-xs font-medium transition-colors"
                              title="Cetak Daftar Hadir"
                            >
                              Presensi
                            </Link>
                          )}
                          <button
                            onClick={() => handleEdit(n)}
                            className="text-[#5F6368] hover:text-[#E37400] p-1.5 rounded hover:bg-[#FEF7E0] transition-colors"
                            title="Edit Dokumen"
                          >
                            <svg
                              className="w-4 h-4"
                              fill="none"
                              viewBox="0 0 24 24"
                              stroke="currentColor"
                            >
                              <path
                                strokeLinecap="round"
                                strokeLinejoin="round"
                                strokeWidth={2}
                                d="M11 5H6a2 2 0 00-2 2v11a2 2 0 002 2h11a2 2 0 002-2v-5m-1.414-9.414a2 2 0 112.828 2.828L11.828 15H9v-2.828l8.586-8.586z"
                              />
                            </svg>
                          </button>
                          <button
                            onClick={() => handleDelete(n.id)}
                            className="text-[#5F6368] hover:text-[#D93025] p-1.5 rounded hover:bg-[#FCE8E6] transition-colors"
                            title="Hapus"
                          >
                            <svg
                              className="w-4 h-4"
                              fill="none"
                              viewBox="0 0 24 24"
                              stroke="currentColor"
                            >
                              <path
                                strokeLinecap="round"
                                strokeLinejoin="round"
                                strokeWidth={2}
                                d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16"
                              />
                            </svg>
                          </button>
                        </div>
                      </td>
                    </tr>
                  ))
                )}
              </tbody>
            </table>
          </div>

          {totalItems > 0 && itemsPerPage > 0 && (
            <div className="px-6 py-3 border-t border-[#DADCE0] bg-white flex justify-between items-center text-xs text-[#5F6368]">
              <div>
                Menampilkan {startItem}-{endItem} dari {totalItems}
              </div>
              <div className="flex gap-2">
                <button
                  onClick={() => setCurrentPage((p) => Math.max(1, p - 1))}
                  disabled={currentPage === 1}
                  className="px-2 py-1 bg-white border border-[#DADCE0] rounded hover:bg-[#F8F9FA] disabled:opacity-50 transition-colors"
                >
                  Sebelumnya
                </button>
                <button
                  onClick={() =>
                    setCurrentPage((p) => Math.min(totalPages, p + 1))
                  }
                  disabled={currentPage === totalPages}
                  className="px-2 py-1 bg-white border border-[#DADCE0] rounded hover:bg-[#F8F9FA] disabled:opacity-50 transition-colors"
                >
                  Selanjutnya
                </button>
              </div>
            </div>
          )}
        </div>
      </div>

      {/* MODAL PEMBUATAN / EDIT DOKUMEN */}
      {isModalOpen && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center bg-[#202124]/40 p-4">
          <div className="bg-white rounded-lg shadow-xl w-full max-w-5xl flex flex-col max-h-[95vh] border border-[#DADCE0]">
            <div className="px-6 py-4 border-b border-[#DADCE0] flex justify-between items-center bg-white rounded-t-lg">
              <h2 className="text-lg font-normal text-[#202124]">
                {editId ? "Edit Dokumen Registri" : "Setup Dokumen Baru"}
              </h2>
              <button
                onClick={() => setIsModalOpen(false)}
                className="text-[#5F6368] hover:bg-[#F1F3F4] p-1.5 rounded-full transition-colors"
              >
                <svg
                  className="w-5 h-5"
                  fill="none"
                  viewBox="0 0 24 24"
                  stroke="currentColor"
                >
                  <path
                    strokeLinecap="round"
                    strokeLinejoin="round"
                    strokeWidth={2}
                    d="M6 18L18 6M6 6l12 12"
                  />
                </svg>
              </button>
            </div>

            {/* 🔥 TOGGLE MODE (Hanya Muncul Saat Buat Baru) 🔥 */}
            {!editId && (
              <div className="px-6 pt-5 bg-white">
                <div className="flex bg-[#F1F3F4] p-1 rounded-lg w-fit border border-[#DADCE0]">
                  <button
                    onClick={() => setModeForm("lengkap")}
                    className={`px-4 py-1.5 rounded-md text-xs font-bold transition-all ${modeForm === "lengkap" ? "bg-white text-[#1A73E8] shadow-sm" : "text-[#5F6368] hover:text-[#202124]"}`}
                  >
                    📝 Form Surat Lengkap (Web)
                  </button>
                  <button
                    onClick={() => setModeForm("cepat")}
                    className={`px-4 py-1.5 rounded-md text-xs font-bold transition-all ${modeForm === "cepat" ? "bg-white text-[#1E8E3E] shadow-sm" : "text-[#5F6368] hover:text-[#202124]"}`}
                  >
                    ⚡ Ambil Nomor Urut Saja
                  </button>
                </div>
              </div>
            )}

            {/* 🔥 KONDISIONAL RENDER FORM 🔥 */}
            {modeForm === "lengkap" || editId ? (
              <>
                {/* INI FORM LENGKAP LAMA JENENGAN (KOLOM KIRI & KANAN) */}
                <div className="p-6 overflow-y-auto bg-white grid grid-cols-1 md:grid-cols-2 gap-8 custom-scrollbar">
                  {/* KOLOM KIRI */}
                  <div className="space-y-5">
                    <h3 className="text-sm font-medium text-[#1A73E8] border-b border-[#E8EAED] pb-2">
                      Pengaturan Penomoran & Acara
                    </h3>
                    <div className="grid grid-cols-2 gap-4">
                      <div>
                        <label className="block text-xs font-medium text-[#5F6368] mb-1">
                          Nomor Urut
                        </label>
                        <input
                          type="text"
                          value={genForm.nomorUrut}
                          onChange={(e) =>
                            setGenForm({
                              ...genForm,
                              nomorUrut: e.target.value,
                            })
                          }
                          className="w-full border border-[#DADCE0] px-3 py-2 rounded text-sm outline-none focus:border-[#1A73E8] focus:ring-1 focus:ring-[#1A73E8]"
                        />
                      </div>
                      <div>
                        <label className="block text-xs font-medium text-[#5F6368] mb-1">
                          Index Kode
                        </label>
                        <DropdownIndexKode />
                      </div>
                    </div>
                    <div>
                      <label className="block text-xs font-medium text-[#5F6368] mb-1">
                        Tanggal Surat / Dokumen
                      </label>
                      <input
                        type="date"
                        value={genForm.tglMasehi}
                        onChange={(e) =>
                          setGenForm({ ...genForm, tglMasehi: e.target.value })
                        }
                        className="w-full border border-[#DADCE0] px-3 py-2 rounded text-sm outline-none focus:border-[#1A73E8] focus:ring-1 focus:ring-[#1A73E8]"
                      />
                    </div>
                    <div className="grid grid-cols-2 gap-4">
                      <div>
                        <label className="block text-xs font-medium text-[#5F6368] mb-1">
                          Jenis Surat
                        </label>
                        <select
                          value={genForm.jenis}
                          onChange={(e) =>
                            setGenForm({ ...genForm, jenis: e.target.value })
                          }
                          className="w-full border border-[#DADCE0] px-3 py-2 rounded text-sm outline-none focus:border-[#1A73E8] focus:ring-1 focus:ring-[#1A73E8]"
                        >
                          <option value="Surat Undangan">Surat Undangan</option>
                          <option value="Surat Rekomendasi">
                            Surat Rekomendasi
                          </option>
                          <option value="Surat Keterangan">
                            Surat Keterangan
                          </option>
                          <option value="Surat Keputusan">
                            Surat Keputusan
                          </option>
                          <option value="Surat Pemberitahuan">
                            Surat Pemberitahuan
                          </option>
                          <option value="Surat Permohonan">
                            Surat Permohonan
                          </option>
                          <option value="Surat Edaran">Surat Edaran</option>
                          <option value="Surat Balasan">Surat Balasan</option>
                          <option value="Nota Dinas">Nota Dinas</option>
                          <option value="Memo">Memo</option>
                          <option value="Surat Biasa">
                            Surat Biasa (Lainnya)
                          </option>
                        </select>
                      </div>
                      <div>
                        <label className="block text-xs font-medium text-[#5F6368] mb-1">
                          Kategori
                        </label>
                        <select
                          value={genForm.kategori}
                          onChange={(e) =>
                            setGenForm({ ...genForm, kategori: e.target.value })
                          }
                          className="w-full border border-[#DADCE0] px-3 py-2 rounded text-sm outline-none focus:border-[#1A73E8] focus:ring-1 focus:ring-[#1A73E8]"
                        >
                          <option value="Eksternal">Eksternal</option>
                          <option value="Internal">Internal</option>
                        </select>
                      </div>
                    </div>
                    <div className="grid grid-cols-2 gap-4">
                      <div>
                        <label className="block text-xs font-medium text-[#5F6368] mb-1">
                          Penanda Tangan <span className="text-red-500">*</span>
                        </label>
                        <select
                          required
                          value={genForm.pembuat}
                          onChange={(e) => {
                            const selectedNama = e.target.value;
                            const pengurus = pengurusList.find(
                              (p) => p.nama === selectedNama,
                            );
                            setGenForm({
                              ...genForm,
                              pembuat: selectedNama,
                              jabatanPembuat: pengurus ? pengurus.jabatan : "",
                            });
                          }}
