                          <div className="flex items-center gap-2 mb-1.5">
                            <span className="text-[10px] font-bold text-blue-600 uppercase tracking-widest bg-blue-50 px-2 py-0.5 rounded border border-blue-100">{q.kategori}</span>
                            <span className={`text-[10px] font-bold uppercase tracking-widest px-2 py-0.5 rounded border ${q.status === 'Aktif' ? 'bg-emerald-50 text-emerald-600 border-emerald-100' : 'bg-slate-100 text-slate-500 border-slate-200'}`}>
                              {q.status || "Draft"}
                            </span>
                          </div>

                          <h3 className="text-lg font-bold text-slate-800 leading-tight mb-1">{q.judul}</h3>
                          {q.deskripsi && (
                            <p className="text-sm text-slate-500 line-clamp-1 mb-3">{q.deskripsi}</p>
                          )}

                          <div className="flex flex-wrap items-center gap-3 mt-2">
                            <span className="inline-flex items-center gap-1.5 text-xs font-semibold text-slate-600 bg-slate-50 border border-slate-100 px-2.5 py-1 rounded-lg">
                              <svg className="w-3.5 h-3.5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 5H7a2 2 0 00-2 2v12a2 2 0 002 2h10a2 2 0 002-2V7a2 2 0 00-2-2h-2M9 5a2 2 0 002 2h2a2 2 0 002-2M9 5a2 2 0 012-2h2a2 2 0 012 2" /></svg>
                              {q.jmlSoal} Soal
                            </span>
                            <span className="inline-flex items-center gap-1.5 text-xs font-semibold text-slate-600 bg-slate-50 border border-slate-100 px-2.5 py-1 rounded-lg">
                              <svg className="w-3.5 h-3.5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 8v4l3 3m6-3a9 9 0 11-18 0 9 9 0 0118 0z" /></svg>
                              {q.durasi || 15} Menit
                            </span>
                            <span className="inline-flex items-center gap-1.5 text-xs font-bold text-orange-600 bg-orange-50 border border-orange-100 px-2.5 py-1 rounded-lg">
                              🪙 {q.reward} Coin
                            </span>
                          </div>
                        </div>

                        <div className="pl-6 flex flex-col gap-2 border-l border-slate-100 ml-6">
                          <Link href={`/dashboard/kuis/${q.id}`}
                            className="p-2 text-slate-400 hover:bg-blue-50 hover:text-blue-600 rounded-xl transition-colors border border-transparent hover:border-blue-100 inline-flex items-center justify-center"
                            title="Kelola Soal"
                          >
                            <svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M11 5H6a2 2 0 00-2 2v11a2 2 0 002 2h11a2 2 0 002-2v-5m-1.414-9.414a2 2 0 112.828 2.828L11.828 15H9v-2.828l8.586-8.586z" /></svg>
                          </Link>
                          <button 
                            onClick={() => handleDeleteQuiz(q.id)} 
                            className="p-2 text-slate-400 hover:bg-red-50 hover:text-red-500 rounded-xl transition-colors border border-transparent hover:border-red-100"
                            title="Hapus Kuis"
                          >
                            <svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16" /></svg>
                          </button>
                        </div>
                      </div>
                    ))}
                  </div>
                )}
              </div>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
}

"use client";

import { useState, useEffect, useMemo } from "react";
import { toast } from "@/lib/toast";
import { db } from "@/lib/firebase";
import {
  collection,
  addDoc,
  serverTimestamp,
  getDocs,
  query,
  orderBy,
  onSnapshot,
  deleteDoc,
  doc,
} from "firebase/firestore";
import { QRCodeCanvas } from "qrcode.react";

export default function AdminKuitansiPage() {
  const [formData, setFormData] = useState({
    jenisEvent: "",
    terimaDari: "",
    nominal: "",
    keterangan: "",
    tanggalPenerimaan: new Date().toISOString().split("T")[0],
    penandatangan: "",
  });

  const [prokerList, setProkerList] = useState<any[]>([]);
  const [pengurusList, setPengurusList] = useState<any[]>([]);
  const [kuitansiList, setKuitansiList] = useState<any[]>([]);

  const [isGenerating, setIsGenerating] = useState(false);
  const [docIdToRender, setDocIdToRender] = useState("");

  const [showEventDropdown, setShowEventDropdown] = useState(false);
  const [showSignerDropdown, setShowSignerDropdown] = useState(false);

  // 🔥 STATE PENCARIAN & PAGINASI 🔥
  const [searchQuery, setSearchQuery] = useState("");
  const [itemsPerPage, setItemsPerPage] = useState<number | "Semua">(5);
  const [currentPage, setCurrentPage] = useState(1);

  const baseUrl = typeof window !== "undefined" ? window.location.origin : "";

  // --- AMBIL DATA DARI FIREBASE ---
  useEffect(() => {
    const fetchProker = async () => {
      const q = query(collection(db, "proker"), orderBy("createdAt", "desc"));
      const snap = await getDocs(q);
      setProkerList(snap.docs.map((doc) => ({ id: doc.id, ...doc.data() })));
    };

    const fetchPengurus = async () => {
      const snap = await getDocs(collection(db, "pengurus"));
      setPengurusList(snap.docs.map((doc) => ({ id: doc.id, ...doc.data() })));
    };

    const qKuitansi = query(
      collection(db, "kuitansi_organisasi"),
      orderBy("createdAt", "desc"),
    );
    const unsubKuitansi = onSnapshot(qKuitansi, (snap) => {
      setKuitansiList(snap.docs.map((doc) => ({ id: doc.id, ...doc.data() })));
    });

    fetchProker();
    fetchPengurus();

    return () => unsubKuitansi();
  }, []);

  // --- FILTER & PAGINASI LOGIC ---
  const filteredKuitansi = useMemo(() => {
    if (!searchQuery) return kuitansiList;
    const lowerQuery = searchQuery.toLowerCase();
    return kuitansiList.filter(
      (k) =>
        (k.terimaDari && k.terimaDari.toLowerCase().includes(lowerQuery)) ||
        (k.jenisEvent && k.jenisEvent.toLowerCase().includes(lowerQuery)) ||
        (k.nominal && k.nominal.toString().includes(lowerQuery)) ||
        (k.keterangan && k.keterangan.toLowerCase().includes(lowerQuery)),
    );
  }, [kuitansiList, searchQuery]);

  useEffect(() => {
    setCurrentPage(1);
  }, [searchQuery, itemsPerPage]);

  const totalPages =
    itemsPerPage === "Semua"
      ? 1
      : Math.ceil(filteredKuitansi.length / itemsPerPage);

  const currentData = useMemo(() => {
    if (itemsPerPage === "Semua") return filteredKuitansi;
    const start = (currentPage - 1) * itemsPerPage;
    return filteredKuitansi.slice(start, start + itemsPerPage);
  }, [filteredKuitansi, currentPage, itemsPerPage]);

  // --- FUNGSI FORMAT & ACTION ---
  const terbilang = (angka: number) => {
    const huruf = [
      "",
      "Satu",
      "Dua",
      "Tiga",
      "Empat",
      "Lima",
      "Enam",
      "Tujuh",
      "Delapan",
      "Sembilan",
      "Sepuluh",
      "Sebelas",
    ];
    let hasil = "";
    if (angka < 12) hasil = huruf[angka];
    else if (angka < 20) hasil = terbilang(angka - 10) + " Belas";
    else if (angka < 100)
      hasil =
        terbilang(Math.floor(angka / 10)) + " Puluh " + terbilang(angka % 10);
    else if (angka < 200) hasil = "Seratus " + terbilang(angka - 100);
    else if (angka < 1000)
      hasil =
        terbilang(Math.floor(angka / 100)) + " Ratus " + terbilang(angka % 100);
    else if (angka < 2000) hasil = "Seribu " + terbilang(angka - 1000);
    else if (angka < 1000000)
      hasil =
        terbilang(Math.floor(angka / 1000)) +
        " Ribu " +
        terbilang(angka % 1000);
    else if (angka < 1000000000)
      hasil =
        terbilang(Math.floor(angka / 1000000)) +
        " Juta " +
        terbilang(angka % 1000000);
    return hasil.trim();
  };

  const handleDelete = async (id: string) => {
    if (confirm("Yakin ingin menghapus kuitansi ini? Aksi ini permanen.")) {
      try {
        await deleteDoc(doc(db, "kuitansi_organisasi", id));
      } catch (error) {
        toast.error("Gagal menghapus kuitansi.");
      }
    }
  };

  const handleKirimWA = (kuitansi: any) => {
    const text = `Halo Bapak/Ibu *${kuitansi.terimaDari}*,\n\nTerima kasih atas partisipasi dan donasi Anda pada acara *${kuitansi.jenisEvent}*.\n\nBerikut kami lampirkan tautan E-Kuitansi resmi penerimaan dana dari IKA UII DIY sebesar *Rp ${kuitansi.nominal.toLocaleString("id-ID")}*:\n\n🔗 ${baseUrl}/verif-kuitansi/${kuitansi.id}\n\nSalam hangat,\n*Bendahara DPW IKA UII DIY*`;
    const waUrl = `https://wa.me/?text=${encodeURIComponent(text)}`;
    window.open(waUrl, "_blank");
  };

  const handleGenerate = async (e: React.FormEvent) => {
    e.preventDefault();
    setIsGenerating(true);

    try {
      const newDoc = await addDoc(collection(db, "kuitansi_organisasi"), {
        jenisEvent: formData.jenisEvent,
        terimaDari: formData.terimaDari,
        nominal: Number(formData.nominal),
        keterangan: formData.keterangan,
        tanggalPenerimaan: formData.tanggalPenerimaan,
        penandatangan: formData.penandatangan,
        createdAt: serverTimestamp(),
      });

      setDocIdToRender(newDoc.id);

      setTimeout(() => {
        executeCanvasGeneration(newDoc.id, formData);
      }, 1000);
    } catch (error) {
      toast.error("Gagal membuat kuitansi.");
      setIsGenerating(false);
    }
  };

  const handleRedownload = (kuitansi: any) => {
    setDocIdToRender(kuitansi.id);
    setIsGenerating(true);
    setTimeout(() => {
      executeCanvasGeneration(kuitansi.id, kuitansi);
    }, 1000);
  };

  // =========================================================================
  // --- 🔥 ENGINE KUITANSI 21x8 CM (ULTIMATE HD RESOLUTION) 🔥 ---
  // =========================================================================
  const executeCanvasGeneration = (id: string, data: any) => {
    const canvas = document.createElement("canvas");
    const ctx = canvas.getContext("2d");
    if (!ctx) return;

    const baseWidth = 1260;
    const baseHeight = 480;
    const scaleFactor = 2;

    canvas.width = baseWidth * scaleFactor;
    canvas.height = baseHeight * scaleFactor;

    ctx.scale(scaleFactor, scaleFactor);
    ctx.imageSmoothingEnabled = true;
    ctx.imageSmoothingQuality = "high";

    const logoImg = new Image();
    logoImg.src = "/logo-dpp-ika.png";

    logoImg.onload = () => {
      ctx.fillStyle = "#ffffff";
      ctx.fillRect(0, 0, baseWidth, baseHeight);

      ctx.save();
      ctx.globalAlpha = 0.04;
      const wmkSize = 380;
      ctx.drawImage(
        logoImg,
        320 + (940 - wmkSize) / 2,
        (baseHeight - wmkSize) / 2,
        wmkSize,
        wmkSize,
      );
      ctx.restore();

      const sidebarWidth = 320;
      const sidebarGradient = ctx.createLinearGradient(0, 0, sidebarWidth, 0);
      sidebarGradient.addColorStop(0, "#1e3a8a");
      sidebarGradient.addColorStop(1, "#1e40af");
      ctx.fillStyle = sidebarGradient;
      ctx.fillRect(0, 0, sidebarWidth, baseHeight);

      ctx.fillStyle = "#fbbf24";
      ctx.fillRect(sidebarWidth - 4, 0, 4, baseHeight);

      ctx.drawImage(logoImg, 40, 40, 60, 60);

      ctx.fillStyle = "#ffffff";
      ctx.font = "bold 38px Arial";
      ctx.fillText("KUITANSI", 115, 70);
      ctx.font = "16px Arial";
      ctx.fillText("DPW IKA UII DIY", 115, 95);

      ctx.font = "bold 13px Arial";
      ctx.fillStyle = "rgba(255,255,255,0.7)";
      ctx.fillText(`Nomor Dokumen/Invoice:`, 40, 220);
      ctx.font = "bold 18px Arial";
      ctx.fillStyle = "#ffffff";
      ctx.fillText(`KUIT-${id.substring(0, 8).toUpperCase()}`, 40, 245);

      const qrElement = document.getElementById(
        "qr-kuitansi-org",
      ) as HTMLCanvasElement;
      if (qrElement) {
        const qrImg = new Image();
        qrImg.src = qrElement.toDataURL("image/png");
        qrImg.onload = () => {
          ctx.drawImage(qrImg, 40, 270, 160, 160);
          ctx.font = "11px Arial";
          ctx.textAlign = "center";
          ctx.fillStyle = "rgba(255,255,255,0.8)";
          ctx.fillText("Scan untuk validasi kriptografi sah", 120, 450);
          renderRightArea();
        };
      } else {
        renderRightArea();
      }
    };

    logoImg.onerror = () => {
      toast.warning("Peringatan: Gambar Logo /public/logo-dpp-ika.png gagal diload.");
      setIsGenerating(false);
    };

    const renderRightArea = () => {
      ctx.textAlign = "left";

      const startX = 360;
      const colonX = 560;
      const textX = 580;
      const maxTextW = 640;

      let startY = 70;
      const gapY = 35;

      const drawRow = (
        label: string,
        value: string,
        valueColor: string,
        valueFont: string,
        isBox = false,
      ) => {
        ctx.font = "bold 14px Arial";
        ctx.fillStyle = "#5F6368"; // Google Gray
        ctx.fillText(label, startX, startY);

        ctx.fillText(":", colonX, startY);

        ctx.font = valueFont;
        ctx.fillStyle = valueColor;

        if (isBox) {
          ctx.fillStyle = "#F8F9FA";
          ctx.strokeStyle = "#DADCE0";
          ctx.lineWidth = 1;
          ctx.beginPath();
          ctx.roundRect(textX - 15, startY - 30, 420, 45, 8);
          ctx.fill();
          ctx.stroke();

          ctx.fillStyle = valueColor;
          ctx.fillText(value, textX, startY);
          startY += gapY + 25;
        } else {
          const endY = wrapText(ctx, value, textX, startY, maxTextW, 24);
          startY = endY + gapY;
        }
      };

      drawRow(
        "KATEGORI / EVENT",
        data.jenisEvent,
        "#1A73E8",
        "bold 18px Arial",
      );
      drawRow("TELAH TERIMA DARI", data.terimaDari, "#202124", "18px Arial");
      drawRow(
        "UANG SEBESAR",
        `Rp ${Number(data.nominal).toLocaleString("id-ID")}`,
        "#1A73E8",
        "bold 24px Arial",
        true,
      );
      drawRow(
        "TERBILANG",
        `${terbilang(Number(data.nominal))} Rupiah`,
        "#5F6368",
        "italic 16px Arial",
      );
      drawRow("GUNA PEMBAYARAN", data.keterangan, "#5F6368", "16px Arial");

      ctx.textAlign = "center";
      const ttdX = 1050;

      ctx.font = "14px Arial";
      ctx.fillStyle = "#5F6368";
      const tglPenerimaanVal = new Date(data.tanggalPenerimaan);
      ctx.fillText(
        `Yogyakarta, ${tglPenerimaanVal.toLocaleDateString("id-ID", { day: "numeric", month: "long", year: "numeric" })}`,
        ttdX,
        baseHeight - 120,
      );

      const partsTtd = data.penandatangan.split(" (");
      const namaTtd = partsTtd[0];
      const jabatanTtd = partsTtd[1]
        ? partsTtd[1].replace(")", "")
        : "Pengurus";

      ctx.font = "bold 16px Arial";
      ctx.fillStyle = "#202124";
      ctx.fillText(namaTtd, ttdX, baseHeight - 50);

      ctx.font = "13px Arial";
      ctx.fillStyle = "#5F6368";
      ctx.fillText(jabatanTtd, ttdX, baseHeight - 32);

      ctx.strokeStyle = "#DADCE0";
      ctx.lineWidth = 1;
      ctx.beginPath();
      ctx.moveTo(ttdX - 140, baseHeight - 45);
      ctx.lineTo(ttdX + 140, baseHeight - 45);
      ctx.stroke();

      ctx.fillStyle = "#1E8E3E"; // Google Green
      ctx.font = "bold 11px Arial";
      ctx.fillText(
        "TERVERIFIKASI SISTEM (TTE IKA UII DIY)",
        ttdX,
        baseHeight - 15,
      );

      const dataUrl = canvas.toDataURL("image/png");
      const a = document.createElement("a");
      a.href = dataUrl;
      const cleanEventName = data.jenisEvent.replace(/[^a-z0-9]+/gi, "-");
      a.download = `Kuitansi_${cleanEventName}_${id.substring(0, 6)}.png`;
      document.body.appendChild(a);
      a.click();
      document.body.removeChild(a);

      setIsGenerating(false);
      setDocIdToRender("");
      setFormData({
        jenisEvent: "",
        terimaDari: "",
        nominal: "",
        keterangan: "",
        tanggalPenerimaan: new Date().toISOString().split("T")[0],
        penandatangan: "",
      });
    };
  };

  const wrapText = (
    context: CanvasRenderingContext2D,
    text: string,
    x: number,
    y: number,
    maxWidth: number,
    lineHeight: number,
  ) => {
    const words = text.split(" ");
    let line = "";
    let currentY = y;
    for (let n = 0; n < words.length; n++) {
      const testLine = line + words[n] + " ";
      const metrics = context.measureText(testLine);
      if (metrics.width > maxWidth && n > 0) {
        context.fillText(line.trim(), x, currentY);
        line = words[n] + " ";
        currentY += lineHeight;
      } else {
        line = testLine;
      }
    }
    context.fillText(line.trim(), x, currentY);
    return currentY;
  };

  return (
    <div className="max-w-7xl mx-auto animate-in fade-in slide-in-from-bottom-4 pb-12 font-sans">
      {/* HEADER: GOOGLE WORKSPACE STYLE */}
      <div className="mb-8 flex flex-col md:flex-row md:items-center justify-between gap-4 border-b border-[#DADCE0] pb-6">
        <div>
          <h1 className="text-3xl font-medium text-[#202124] tracking-tight mb-1">
            Pabrik Kuitansi Organisasi
          </h1>
          <p className="text-[#5F6368] text-sm max-w-2xl">
            Cetak kuitansi penerimaan dana resmi ber-QR Code untuk berbagai
            keperluan IKA UII. Validasi dapat diakses publik secara realtime.
          </p>
        </div>
        <div className="w-14 h-14 bg-white border border-[#DADCE0] rounded-xl flex items-center justify-center shadow-sm shrink-0">
          <img
            src="/logo-dpp-ika.png"
            alt="IKA UII DIY"
            className="w-8 h-8 object-contain opacity-80"
          />
        </div>
      </div>

      {/* ELEMEN QR TERSEMBUNYI UNTUK CANVAS */}
      {docIdToRender && (
        <div className="hidden">
          <QRCodeCanvas
            id="qr-kuitansi-org"
            value={`${baseUrl}/verif-kuitansi/${docIdToRender}`}
            size={300}
            level="H"
            includeMargin={true}
          />
        </div>
      )}

      <div className="grid lg:grid-cols-12 gap-8 items-start">
        {/* ======================================================== */}
        {/* KOLOM KIRI: FORM GENERATOR (WORKSPACE STYLE) */}
        {/* ======================================================== */}
        <div className="lg:col-span-5">
          <div className="bg-white p-6 sm:p-8 rounded-2xl shadow-sm border border-[#DADCE0] sticky top-24">
            <div className="flex items-center gap-3 mb-6 border-b border-[#DADCE0] pb-4">
              <div className="w-10 h-10 bg-[#E8F0FE] text-[#1A73E8] rounded-full flex items-center justify-center shrink-0">
                <svg
                  className="w-5 h-5"
                  fill="none"
                  viewBox="0 0 24 24"
                  stroke="currentColor"
                  strokeWidth={2}
                >
                  <path
                    strokeLinecap="round"
                    strokeLinejoin="round"
                    d="M12 4v1m6 11h2m-6 0h-2v4m0-11v3m0 0h.01M12 12h4.01M16 20h4M4 12h4m12 0h.01M5 8h2a1 1 0 001-1V5a1 1 0 00-1-1H5a1 1 0 00-1 1v2a1 1 0 001 1zm12 0h2a1 1 0 001-1V5a1 1 0 00-1-1h-2a1 1 0 00-1 1v2a1 1 0 001 1zM5 20h2a1 1 0 001-1v-2a1 1 0 00-1-1H5a1 1 0 00-1 1v2a1 1 0 001 1z"
                  />
                </svg>
              </div>
              <h2 className="font-medium text-[#202124] text-lg">
                Buat Kuitansi Baru
              </h2>
            </div>

            <form onSubmit={handleGenerate} className="space-y-5">
              {/* SMART SEARCH EVENT/KATEGORI */}
              <div className="sm:col-span-2 relative">
                <label className="block text-[11px] font-bold text-[#5F6368] uppercase tracking-widest mb-1.5">
                  Kategori / Event Kuitansi
                </label>
                <div className="relative">
                  <input
                    type="text"
                    required
                    value={formData.jenisEvent}
                    onChange={(e) => {
                      setFormData({ ...formData, jenisEvent: e.target.value });
                      setShowEventDropdown(true);
                    }}
                    onFocus={() => setShowEventDropdown(true)}
                    onBlur={() =>
                      setTimeout(() => setShowEventDropdown(false), 200)
                    }
                    placeholder="Ketik untuk mencari atau input manual..."
                    className="w-full pl-4 pr-10 py-2.5 bg-[#F8F9FA] border border-[#DADCE0] focus:border-[#1A73E8] focus:bg-white rounded-lg outline-none font-medium text-[#202124] transition-colors placeholder:text-[#9AA0A6] placeholder:font-normal text-sm"
                  />
                  <svg
                    className={`w-4 h-4 absolute right-3 top-1/2 -translate-y-1/2 text-[#5F6368] transition-transform ${showEventDropdown ? "rotate-180" : ""}`}
                    fill="none"
                    viewBox="0 0 24 24"
                    stroke="currentColor"
                  >
                    <path
                      strokeLinecap="round"
                      strokeLinejoin="round"
                      strokeWidth={2}
                      d="M19 9l-7 7-7-7"
                    />
                  </svg>
                </div>

                {showEventDropdown && (
                  <div className="absolute z-20 w-full mt-1 bg-white border border-[#DADCE0] rounded-lg shadow-lg max-h-48 overflow-y-auto custom-scrollbar animate-in fade-in slide-in-from-top-1 py-1">
                    {prokerList
                      .filter((p) =>
                        p.namaKegiatan
                          .toLowerCase()
                          .includes(formData.jenisEvent.toLowerCase()),
                      )
                      .map((p) => (
                        <div
                          key={p.id}
                          onClick={() => {
                            setFormData({
                              ...formData,
                              jenisEvent: p.namaKegiatan,
                            });
                            setShowEventDropdown(false);
                          }}
                          className="px-4 py-2 hover:bg-[#F8F9FA] cursor-pointer text-sm font-medium text-[#202124]"
                        >
                          {p.namaKegiatan}
                        </div>
                      ))}
                    <div className="px-4 py-1.5 mt-1 bg-[#F8F9FA] text-[10px] font-bold text-[#5F6368] uppercase tracking-widest sticky top-0 border-y border-[#DADCE0]">
                      Kategori Umum
                    </div>
                    {[
                      "Sponsorship Umum",
                      "Donasi Bebas / Amal",
                      "Iuran Anggota / Kas",
                      "Lainnya (Umum)",
                    ]
                      .filter((e) =>
                        e
                          .toLowerCase()
                          .includes(formData.jenisEvent.toLowerCase()),
                      )
                      .map((e) => (
                        <div
                          key={e}
                          onClick={() => {
                            setFormData({ ...formData, jenisEvent: e });
                            setShowEventDropdown(false);
                          }}
                          className="px-4 py-2 hover:bg-[#F8F9FA] cursor-pointer text-sm font-medium text-[#202124]"
                        >
                          {e}
                        </div>
                      ))}
                  </div>
                )}
              </div>

              <div>
                <label className="block text-[11px] font-bold text-[#5F6368] uppercase tracking-widest mb-1.5">
                  Telah Terima Dari
                </label>
                <input
                  type="text"
                  required
                  value={formData.terimaDari}
                  onChange={(e) =>
                    setFormData({ ...formData, terimaDari: e.target.value })
                  }
                  placeholder="Nama Lengkap / Instansi"
                  className="w-full px-4 py-2.5 bg-[#F8F9FA] border border-[#DADCE0] focus:border-[#1A73E8] focus:bg-white rounded-lg outline-none font-medium text-[#202124] transition-colors placeholder:text-[#9AA0A6] placeholder:font-normal text-sm"
                />
              </div>

              <div className="grid grid-cols-2 gap-4">
                <div>
                  <label className="block text-[11px] font-bold text-[#5F6368] uppercase tracking-widest mb-1.5">
                    Nominal Uang (Rp)
                  </label>
                  <input
                    type="number"
                    required
                    value={formData.nominal}
                    onChange={(e) =>
                      setFormData({ ...formData, nominal: e.target.value })
                    }
                    placeholder="Contoh: 1500000"
                    className="w-full px-4 py-2.5 bg-[#F8F9FA] border border-[#DADCE0] focus:border-[#1A73E8] focus:bg-white rounded-lg outline-none font-mono font-bold text-[#1A73E8] transition-colors placeholder:text-[#9AA0A6] placeholder:font-normal text-sm"
                  />
                </div>
                <div>
                  <label className="block text-[11px] font-bold text-[#5F6368] uppercase tracking-widest mb-1.5">
                    Tanggal Terima
                  </label>
                  <input
                    type="date"
                    required
                    value={formData.tanggalPenerimaan}
                    onChange={(e) =>
                      setFormData({
                        ...formData,
                        tanggalPenerimaan: e.target.value,
                      })
                    }
                    className="w-full px-4 py-2.5 bg-[#F8F9FA] border border-[#DADCE0] focus:border-[#1A73E8] focus:bg-white rounded-lg outline-none font-medium text-[#202124] transition-colors text-sm"
                  />
                </div>
              </div>

              {/* SMART SEARCH PENANDATANGAN */}
              <div className="relative">
                <label className="block text-[11px] font-bold text-[#5F6368] uppercase tracking-widest mb-1.5">
                  Otoritas Penandatangan
                </label>
                <div className="relative">
                  <input
                    type="text"
                    required
                    value={formData.penandatangan}
                    onChange={(e) => {
                      setFormData({
                        ...formData,
                        penandatangan: e.target.value,
                      });
                      setShowSignerDropdown(true);
                    }}
                    onFocus={() => setShowSignerDropdown(true)}
                    onBlur={() =>
                      setTimeout(() => setShowSignerDropdown(false), 200)
                    }
                    placeholder="Ketik untuk mencari nama..."
                    className="w-full pl-4 pr-10 py-2.5 bg-[#F8F9FA] border border-[#DADCE0] focus:border-[#1A73E8] focus:bg-white rounded-lg outline-none font-medium text-[#202124] transition-colors placeholder:text-[#9AA0A6] placeholder:font-normal text-sm"
                  />
                  <svg
                    className={`w-4 h-4 absolute right-3 top-1/2 -translate-y-1/2 text-[#5F6368] transition-transform ${showSignerDropdown ? "rotate-180" : ""}`}
                    fill="none"
                    viewBox="0 0 24 24"
                    stroke="currentColor"
                  >
                    <path
                      strokeLinecap="round"
                      strokeLinejoin="round"
                      strokeWidth={2}
                      d="M19 9l-7 7-7-7"
                    />
                  </svg>
                </div>

                {showSignerDropdown && (
                  <div className="absolute z-20 w-full mt-1 bg-white border border-[#DADCE0] rounded-lg shadow-lg max-h-48 overflow-y-auto custom-scrollbar animate-in fade-in slide-in-from-top-1 py-1">
                    {pengurusList
                      .filter(
                        (p) =>
                          p.nama &&
                          p.nama
                            .toLowerCase()
                            .includes(formData.penandatangan.toLowerCase()),
                      )
                      .map((p) => (
                        <div
                          key={p.id}
                          onClick={() => {
                            setFormData({
                              ...formData,
                              penandatangan: `${p.nama} (${p.jabatan || "Pengurus"})`,
                            });
                            setShowSignerDropdown(false);
                          }}
                          className="px-4 py-2 hover:bg-[#F8F9FA] cursor-pointer flex flex-col"
                        >
                          <span className="text-sm font-medium text-[#202124]">
                            {p.nama}
                          </span>
                          <span className="text-[10px] text-[#5F6368]">
                            {p.jabatan || "Pengurus"}
                          </span>
                        </div>
                      ))}
                    {pengurusList.filter(
                      (p) =>
                        p.nama &&
                        p.nama
                          .toLowerCase()
                          .includes(formData.penandatangan.toLowerCase()),
                    ).length === 0 && (
                      <div className="px-4 py-2 text-xs text-[#9AA0A6] italic">
                        Pencarian tidak ditemukan. Anda tetap bisa menggunakan
                        ketikan ini.
                      </div>
                    )}
                  </div>
                )}
              </div>

              <div>
                <label className="block text-[11px] font-bold text-[#5F6368] uppercase tracking-widest mb-1.5">
                  Guna Pembayaran
                </label>
                <textarea
                  required
                  value={formData.keterangan}
                  onChange={(e) =>
                    setFormData({ ...formData, keterangan: e.target.value })
                  }
                  rows={3}
                  placeholder="Jelaskan rincian pembayaran..."
                  className="w-full px-4 py-2.5 bg-[#F8F9FA] border border-[#DADCE0] focus:border-[#1A73E8] focus:bg-white rounded-lg outline-none font-medium text-[#202124] transition-colors resize-none custom-scrollbar placeholder:text-[#9AA0A6] placeholder:font-normal text-sm"
                ></textarea>
              </div>

              <div className="pt-2">
                <button
                  type="submit"
                  disabled={isGenerating}
                  className="w-full bg-[#1A73E8] hover:bg-[#1557B0] text-white font-medium py-3 rounded-lg transition-colors shadow-sm disabled:opacity-50 flex items-center justify-center gap-2"
                >
                  {isGenerating ? (
                    <>
                      <svg
                        className="w-4 h-4 animate-spin text-white"
                        fill="none"
                        viewBox="0 0 24 24"
                      >
                        <circle
                          className="opacity-25"
                          cx="12"
                          cy="12"
                          r="10"
                          stroke="currentColor"
                          strokeWidth="4"
                        ></circle>
                        <path
                          className="opacity-75"
                          fill="currentColor"
                          d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4z"
                        ></path>
                      </svg>{" "}
                      Memproses HD Canvas...
                    </>
                  ) : (
                    <>Cetak Kuitansi Resmi</>
                  )}
                </button>
              </div>
            </form>
          </div>
        </div>

        {/* ======================================================== */}
        {/* KOLOM KANAN: RIWAYAT KUITANSI (WORKSPACE STYLE) */}
        {/* ======================================================== */}
        <div className="lg:col-span-7">
          <div className="bg-white rounded-2xl shadow-sm border border-[#DADCE0] overflow-hidden flex flex-col h-full">
            {/* HEADER & CONTROLS */}
            <div className="p-5 border-b border-[#DADCE0] bg-[#F8F9FA] flex flex-col gap-4 relative z-10">
              <div className="flex justify-between items-center">
                <div>
                  <h2 className="font-medium text-[#202124] text-lg">
                    Riwayat Kuitansi
                  </h2>
                </div>
                <div className="text-xs font-medium text-[#1A73E8] bg-[#E8F0FE] px-3 py-1 rounded border border-[#1A73E8]/20">
                  Total: {filteredKuitansi.length} Dokumen
                </div>
              </div>

              {/* PENCARIAN & PAGINASI FILTER */}
              <div className="flex flex-col sm:flex-row gap-3">
                <div className="relative flex-1">
                  <svg
                    className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-[#5F6368]"
                    fill="none"
                    viewBox="0 0 24 24"
                    stroke="currentColor"
                  >
                    <path
                      strokeLinecap="round"
                      strokeLinejoin="round"
                      strokeWidth={2}
                      d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z"
                    />
                  </svg>
                  <input
                    type="text"
                    placeholder="Cari nama, event, atau nominal..."
                    value={searchQuery}
                    onChange={(e) => setSearchQuery(e.target.value)}
                    className="w-full pl-9 pr-4 py-2 border border-[#DADCE0] rounded-lg text-sm bg-white focus:outline-none focus:border-[#1A73E8] transition-colors"
                  />
                </div>
                <div className="flex items-center gap-2 shrink-0">
                  <span className="text-[11px] font-bold text-[#5F6368] uppercase tracking-widest">
                    Tampilkan:
                  </span>
                  <select
                    value={itemsPerPage}
                    onChange={(e) =>
                      setItemsPerPage(
                        e.target.value === "Semua"
                          ? "Semua"
                          : Number(e.target.value),
                      )
                    }
                    className="bg-white border border-[#DADCE0] py-2 px-2 rounded-lg text-xs font-medium text-[#202124] focus:border-[#1A73E8] outline-none cursor-pointer"
                  >
                    <option value={5}>5</option>
                    <option value={10}>10</option>
                    <option value={25}>25</option>
                    <option value="Semua">Semua</option>
                  </select>
                </div>
              </div>
            </div>

            {/* LIST KUITANSI */}
            <div className="p-5 flex-grow overflow-y-auto custom-scrollbar bg-white">
              {currentData.length === 0 ? (
                <div className="text-center py-20 bg-[#F8F9FA] rounded-xl border border-[#DADCE0] text-[#5F6368] text-sm">
                  {searchQuery
                    ? "Tidak ditemukan kuitansi dengan kata kunci tersebut."
                    : "Belum ada riwayat pembuatan kuitansi."}
                </div>
              ) : (
                <div className="space-y-4">
                  {currentData.map((kuitansi, index) => {
                    const noUrut =
                      itemsPerPage === "Semua"
                        ? index + 1
                        : (currentPage - 1) * (itemsPerPage as number) +
                          index +
                          1;

                    return (
                      <div
                        key={kuitansi.id}
                        className="bg-white p-5 rounded-xl border border-[#DADCE0] hover:bg-[#F8F9FA] transition-colors group relative animate-in fade-in slide-in-from-top-1"
                      >
                        {/* BADGES KANAN ATAS (NO URUT & KODE KUITANSI) */}
                        <div className="absolute top-4 right-4 flex items-center gap-1.5">
                          <div className="bg-[#E8F0FE] text-[#1A73E8] font-mono text-[10px] font-bold px-2 py-1 rounded border border-[#1A73E8]/20">
                            #{noUrut}
                          </div>
                          <div className="bg-[#F8F9FA] text-[#5F6368] font-mono text-[10px] font-bold px-2.5 py-1 rounded border border-[#DADCE0]">
                            KUIT-{kuitansi.id.substring(0, 6).toUpperCase()}
                          </div>
                        </div>

                        <div className="pr-36">
                          <div className="flex items-center gap-2 mb-2">
                            <span className="w-2 h-2 bg-[#1E8E3E] rounded-full"></span>
                            <p className="text-[10px] font-bold text-[#1A73E8] uppercase tracking-widest">
                              {kuitansi.jenisEvent}
                            </p>
                          </div>
                          <h3 className="font-medium text-[#202124] text-lg mb-1 leading-tight">
                            {kuitansi.terimaDari}
                          </h3>
                          <p className="text-xl font-bold text-[#202124] mb-4">
                            Rp {kuitansi.nominal.toLocaleString("id-ID")}
                          </p>

                          <div className="flex flex-wrap gap-x-6 gap-y-3 text-[11px] mb-5 bg-[#F8F9FA] p-3 rounded-lg border border-[#DADCE0]">
                            <div>
                              <span className="block font-bold text-[#5F6368] uppercase mb-0.5 tracking-wider text-[9px]">
                                Tgl Terima Uang
                              </span>
                              <span className="font-medium text-[#202124] flex items-center gap-1.5">
                                <svg
                                  className="w-3 h-3 text-[#5F6368]"
                                  fill="none"
                                  viewBox="0 0 24 24"
                                  stroke="currentColor"
                                >
                                  <path
                                    strokeLinecap="round"
                                    strokeLinejoin="round"
                                    strokeWidth={2}
                                    d="M8 7V3m8 4V3m-9 8h10M5 21h14a2 2 0 002-2V7a2 2 0 00-2-2H5a2 2 0 00-2 2v12a2 2 0 002 2z"
                                  />
                                </svg>
                                {new Date(
                                  kuitansi.tanggalPenerimaan,
                                ).toLocaleDateString("id-ID", {
                                  day: "numeric",
                                  month: "short",
                                  year: "numeric",
                                })}
                              </span>
                            </div>
                            <div className="border-l border-[#DADCE0] pl-6">
                              <span className="block font-bold text-[#5F6368] uppercase mb-0.5 tracking-wider text-[9px]">
                                Bendahara Umum (TTD)
                              </span>
                              <span className="font-medium text-[#202124] flex items-center gap-1.5">
                                <svg
                                  className="w-3 h-3 text-[#5F6368]"
                                  fill="none"
                                  viewBox="0 0 24 24"
                                  stroke="currentColor"
                                >
                                  <path
                                    strokeLinecap="round"
                                    strokeLinejoin="round"
                                    strokeWidth={2}
                                    d="M16 7a4 4 0 11-8 0 4 4 0 018 0zM12 14a7 7 0 00-7 7h14a7 7 0 00-7-7z"
                                  />
                                </svg>
                                {kuitansi.penandatangan.split(" (")[0]}
                              </span>
                            </div>
                          </div>
                        </div>

                        <div className="flex flex-wrap gap-2 pt-4 border-t border-[#DADCE0]">
                          <button
                            onClick={() => handleRedownload(kuitansi)}
                            className="flex-1 bg-white border border-[#DADCE0] text-[#5F6368] hover:bg-[#F8F9FA] hover:text-[#1A73E8] font-medium py-2 px-3 rounded text-[11px] transition-colors flex items-center justify-center gap-1.5"
                          >
                            <svg
                              className="w-3.5 h-3.5"
                              fill="none"
                              viewBox="0 0 24 24"
                              stroke="currentColor"
                            >
                              <path
                                strokeLinecap="round"
                                strokeLinejoin="round"
                                strokeWidth={2}
                                d="M4 16v1a3 3 0 003 3h10a3 3 0 003-3v-1m-4-4l-4 4m0 0l-4-4m4 4V4"
                              />
                            </svg>
                            Download HD
                          </button>
                          <button
                            onClick={() => handleKirimWA(kuitansi)}
                            className="flex-1 bg-[#1E8E3E] hover:bg-[#137333] text-white font-medium py-2 px-3 rounded text-[11px] transition-colors flex items-center justify-center gap-1.5"
                          >
                            <svg
                              className="w-3.5 h-3.5"
                              fill="currentColor"
                              viewBox="0 0 24 24"
                            >
                              <path d="M12.031 21.031c-1.897 0-3.694-.482-5.263-1.341l-5.834 1.534 1.564-5.69c-.939-1.62-1.436-3.483-1.436-5.434C1.062 4.475 8.536-3 17.5-3S33.938 4.475 33.938 13.438 26.464 29.912 17.5 29.912c-1.921 0-3.76-.486-5.36-1.378l-5.856 1.54 1.57-5.712c-.958-1.644-1.464-3.535-1.464-5.524 0-8.963-7.474-16.438-16.438-16.438zM17.5 1.5C10.925 1.5 5.562 6.862 5.562 13.438c0 2.115.556 4.148 1.614 5.922l.169.284-1.026 3.733 3.821-1.004.292.173c1.727 1.023 3.693 1.565 5.768 1.565 6.575 0 11.938-5.362 11.938-11.938 0-6.575-5.362-11.938-11.938-11.938zm6.541 16.275c-.358-.18-2.122-1.047-2.45-1.168-.328-.12-.567-.18-.806.18-.239.36-.926 1.168-1.135 1.408-.209.24-.418.27-.776.09-.358-.18-1.515-.558-2.881-1.776-1.063-.948-1.782-2.122-1.991-2.482-.209-.36-.022-.555.157-.735.161-.162.358-.42.537-.63.18-.21.239-.36.358-.6.12-.24.06-.45-.03-.63-.09-.18-.806-1.944-1.104-2.66-.291-.698-.586-.603-.806-.615-.209-.012-.448-.012-.687-.012-.239 0-.627.09-.955.45-.328.36-1.254 1.23-1.254 3.003 0 1.773 1.284 3.486 1.463 3.726.18.24 2.54 3.882 6.155 5.433.861.37 1.533.592 2.057.758.865.275 1.651.236 2.274.143.698-.105 2.122-.87 2.42-1.713.299-.843.299-1.563.209-1.713-.09-.15-.328-.24-.686-.42z" />
                            </svg>
                            Kirim WA
                          </button>
                          <button
                            onClick={() => handleDelete(kuitansi.id)}
                            className="px-3 bg-white border border-[#DADCE0] text-[#D93025] hover:bg-[#FCE8E6] hover:border-[#FAD2CF] rounded transition-colors flex items-center justify-center"
                          >
                            <svg
                              className="w-4 h-4"
                              fill="none"
                              viewBox="0 0 24 24"
                              stroke="currentColor"
                            >
                              <path
                                strokeLinecap="round"
                                strokeLinejoin="round"
                                strokeWidth={2}
                                d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16"
                              />
                            </svg>
                          </button>
                        </div>
                      </div>
                    );
                  })}
                </div>
              )}
            </div>

            {/* CONTROLS PAGINASI FOOTER */}
            {itemsPerPage !== "Semua" && totalPages > 1 && (
              <div className="flex items-center justify-between px-5 py-4 border-t border-[#DADCE0] bg-[#F8F9FA]">
                <div className="text-xs font-medium text-[#5F6368]">
                  Hal {currentPage} dari {totalPages}
                </div>
                <div className="flex items-center gap-1">
                  <button
                    onClick={() => setCurrentPage((p) => Math.max(1, p - 1))}
                    disabled={currentPage === 1}
                    className="px-3 py-1.5 border border-[#DADCE0] rounded bg-white text-[#5F6368] hover:bg-[#F8F9FA] hover:text-[#1A73E8] disabled:opacity-50 transition-colors text-xs font-medium"
                  >
                    Prev
                  </button>
                  <button
                    onClick={() =>
                      setCurrentPage((p) => Math.min(totalPages, p + 1))
                    }
                    disabled={currentPage === totalPages}
                    className="px-3 py-1.5 border border-[#DADCE0] rounded bg-white text-[#5F6368] hover:bg-[#F8F9FA] hover:text-[#1A73E8] disabled:opacity-50 transition-colors text-xs font-medium"
                  >
                    Next
                  </button>
                </div>
              </div>
            )}
          </div>
        </div>
      </div>
    </div>
  );
}

"use client";

import { useState, useEffect, useMemo } from "react";
import { db } from "@/lib/firebase";
import { sendWaAction } from "@/app/actions/wa";
import {
  collection,
  getDocs,
  deleteDoc,
  doc,
  updateDoc,
  writeBatch,
  query,
  orderBy,
  limit,
} from "firebase/firestore";
import * as XLSX from "xlsx";
import {
  IconDownload,
  IconSearch,
  IconCheck,
  IconAlert,
  IconEmpty,
  IconInfo,
  IconClose,
} from "./Icons";

export default function TabAnggota() {
  const [anggotaList, setAnggotaList] = useState<any[]>([]);
  const [bidangList, setBidangList] = useState<any[]>([]);
  const [periodeList, setPeriodeList] = useState<any[]>([]);

  const [isLoading, setIsLoading] = useState(true);
  const [isProcessing, setIsProcessing] = useState(false);

  const [search, setSearch] = useState("");
  const [filterBidang, setFilterBidang] = useState("Semua");
  const [selectedIds, setSelectedIds] = useState<string[]>([]);

  // Modals
  const [toast, setToast] = useState({
    isOpen: false,
    message: "",
    type: "success",
  });
  const [deleteModal, setDeleteModal] = useState({
    isOpen: false,
    id: "",
    title: "",
    type: "single",
  });
  const [approveModal, setApproveModal] = useState({
    isOpen: false,
    dataId: "",
    form: {
      nama: "",
      wa: "",
      email: "",
      jabatan: "Anggota",
      bidang: "",
      noUrut: "",
      isInti: false,
      isTampilBeranda: false,
      periodeId: "",
      domisili: "",
    },
  });

  const showToast = (
    message: string,
    type: "success" | "error" = "success",
  ) => {
    setToast({ isOpen: true, message, type });
    setTimeout(() => setToast((prev) => ({ ...prev, isOpen: false })), 4000);
  };

  const triggerWaApi = async (
    type: string,
    phone: string,
    nama: string,
    detailData: any = {},
  ) => {
    if (!phone || phone.length < 9) return false;
    try {
      const data = await sendWaAction({
        type,
        phone,
        nama,
        detail: detailData,
      });
      return data.success;
    } catch (error) {
      return false;
    }
  };

  const fetchData = async () => {
    setIsLoading(true);
    try {
      // 1. Ambil Periode tanpa orderBy (Sort manual pakai JavaScript)
      const pSnap = await getDocs(collection(db, "periode"));
      const pData = pSnap.docs.map((d) => ({ id: d.id, ...d.data() }));
      pData.sort((a: any, b: any) => {
        const dateA = a.tglMulai || "";
        const dateB = b.tglMulai || "";
        return dateB.localeCompare(dateA); // Descending
      });
      setPeriodeList(pData);

      // 2. Ambil Bidang tanpa orderBy (Sort manual pakai JavaScript)
      const bSnap = await getDocs(collection(db, "bidang"));
      const bData = bSnap.docs.map((d) => ({ id: d.id, ...d.data() }));
      bData.sort((a: any, b: any) => {
        const nameA = a.namaBidang || "";
        const nameB = b.namaBidang || "";
        return nameA.localeCompare(nameB); // Ascending
      });
      setBidangList(bData);

      // 3. Ambil User (Anggota) tanpa orderBy untuk menghindari Index Error
      const uSnap = await getDocs(collection(db, "pengurus"));
      const allUsers = uSnap.docs.map((d) => ({ id: d.id, ...d.data() }));
      
      // Filter hanya yang belum sah & Urutkan berdasarkan createdAt di JavaScript
      const pending = allUsers.filter(
        (u: any) =>
          !u.isPengurus &&
          u.role !== "pengurus" &&
          u.status_pengurus !== "Aktif" &&
          !u.tampilDiWeb,
      );
      
      pending.sort((a: any, b: any) => {
        const timeA = a.createdAt || "";
        const timeB = b.createdAt || "";
        return timeB.localeCompare(timeA); // Descending
      });

      setAnggotaList(pending);
    } catch (error: any) {
      console.error("Gagal load data:", error);
      showToast("Gagal memuat data anggota. Cek console.", "error");
    } finally {
      setIsLoading(false);
      setSelectedIds([]);
    }
  };

  useEffect(() => {
    fetchData();
  }, []);

  const filteredData = useMemo(() => {
    let result = anggotaList;
    if (filterBidang !== "Semua")
      result = result.filter((p) => p.bidang === filterBidang);
    if (search) {
      const q = search.toLowerCase();
      result = result.filter(
        (p) =>
          p.nama?.toLowerCase().includes(q) ||
          p.email?.toLowerCase().includes(q) ||
          p.bidang?.toLowerCase().includes(q),
      );
    }
    return result;
  }, [search, filterBidang, anggotaList]);

  const executeDelete = async () => {
    setIsProcessing(true);
    try {
      if (deleteModal.type === "single" && deleteModal.id) {
        await deleteDoc(doc(db, "pengurus", deleteModal.id));
      } else if (deleteModal.type === "bulk" && selectedIds.length > 0) {
        const batch = writeBatch(db);
        selectedIds.forEach((id) => {
          batch.delete(doc(db, "pengurus", id));
        });
        await batch.commit();
      }
      showToast("Data pendaftar ditolak & dihapus.", "success");
      await fetchData();
    } catch (error) {
      showToast("Gagal menghapus data.", "error");
    } finally {
      setIsProcessing(false);
      setDeleteModal({ isOpen: false, id: "", title: "", type: "single" });
    }
  };

  const openApproveModal = (p: any) => {
    const activePeriode = periodeList.find((per) => per.status === "Aktif");
    setApproveModal({
      isOpen: true,
      dataId: p.id,
      form: {
        nama: p.nama || "",
        wa: p.wa || "",
        email: p.email || "",
        jabatan: p.jabatan || "Anggota",
        bidang:
          p.bidang || (bidangList.length > 0 ? bidangList[0].namaBidang : ""),
        noUrut: p.noUrut || "",
        isInti: p.isInti || false,
        isTampilBeranda: p.isTampilBeranda || false,
        periodeId: activePeriode ? activePeriode.id : "",
        domisili: p.domisili || "",
      },
    });
  };

  const executeApprove = async (e: React.FormEvent) => {
    e.preventDefault();
    setIsProcessing(true);
    try {
      // 🔥 Auto-generate NIA: Ambil dari counter_nia dan domisili
      let nia = "";
      try {
        const { getDoc, setDoc, doc } = require("firebase/firestore");
        const counterRef = doc(db, "pengaturan", "counter_nia");
        const counterSnap = await getDoc(counterRef);
        let newNumber = 89;
        if (counterSnap.exists())
          newNumber = (counterSnap.data().lastNumber || 88) + 1;
        await setDoc(counterRef, { lastNumber: newNumber }, { merge: true });

        const dateObj = new Date();
        const yearStr = dateObj.getFullYear().toString().slice(-2);
        const monthStr = String(dateObj.getMonth() + 1).padStart(2, "0");
        let kabStr = "00";
        const dom = (approveModal.form.domisili || "").toLowerCase();
        if (dom.includes("sleman")) kabStr = "04";
        else if (dom.includes("bantul")) kabStr = "02";
        else if (dom.includes("gunung")) kabStr = "03";
        else if (dom.includes("kulon")) kabStr = "01";
        else if (dom.includes("kota") || dom.includes("yogya")) kabStr = "71";

        const urutStr = String(newNumber).padStart(4, "0");
        nia = `${yearStr}.${monthStr}.34.${kabStr}.${urutStr}`;
      } catch (e) {
        console.warn("[TabAnggota] Gagal cari NIA max, fallback timestamp:", e);
        nia = `26.08.34.00.${Date.now().toString().slice(-4)}`;
      }

      const payload = {
        ...approveModal.form,
        noUrut: approveModal.form.noUrut !== ""
          ? Number(approveModal.form.noUrut)
          : 99,
        isPengurus: true,
        status_pengurus: "Aktif",
        role: "pengurus",
        nia,
        domisili: approveModal.form.domisili,
        updatedAt: new Date().toISOString(),
      };

      await updateDoc(doc(db, "pengurus", approveModal.dataId), payload);

      // TRIGGER WA GATEWAY
      try {
        await triggerWaApi(
          "member_verified",
          approveModal.form.wa,
          approveModal.form.nama,
          { nia },
        );
      } catch (waError: any) {
        console.warn("[TabAnggota] WA notification gagal (non-fatal):", waError);
      }

      showToast(
        `${approveModal.form.nama} resmi disahkan! NIA: ${nia}`,
        "success",
      );
      setApproveModal({ 
        isOpen: false, 
        dataId: "", 
        form: { nama: "", wa: "", email: "", jabatan: "Anggota", bidang: "", noUrut: "", isInti: false, isTampilBeranda: false, periodeId: "", domisili: "" } 
      });
      await fetchData();
    } catch (error: any) {
      console.error(`[TabAnggota] GAGAL APPROVE:`, error);
      showToast(
        `Gagal mengesahkan. Cek console.`,
        "error",
      );
    } finally {
      setIsProcessing(false);
    }
  };

  const handleExportData = () => {
    if (filteredData.length === 0)
      return showToast("Tidak ada data untuk diekspor.", "error");
    const wsData = filteredData.map((d, i) => ({
      No: i + 1,
      Nama: d.nama,
      WA: d.wa,
      Email: d.email,
      Bidang_Pilihan: d.bidang,
      Tanggal_Daftar: d.createdAt,
    }));
    const ws = XLSX.utils.json_to_sheet(wsData);
    const wb = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(wb, ws, "Antrean");
    XLSX.writeFile(wb, `Data_ANTREAN_IKA_UII.xlsx`);
  };

  return (
    <div className="relative">
      {/* LOCAL TOAST */}
      <div
        className={`fixed top-6 right-6 z-[200] transition-all duration-300 transform ${toast.isOpen ? "translate-y-0 opacity-100" : "-translate-y-4 opacity-0 pointer-events-none"}`}
      >
        <div
          className={`flex items-center gap-3 px-5 py-4 rounded-xl shadow-lg border ${toast.type === "success" ? "bg-white border-emerald-100" : "bg-white border-red-100"}`}
        >
          <div
            className={`flex-shrink-0 w-9 h-9 rounded-full flex items-center justify-center ${toast.type === "success" ? "bg-emerald-100 text-emerald-600" : "bg-red-100 text-red-600"}`}
          >
            {toast.type === "success" ? <IconCheck /> : <IconAlert />}
          </div>
          <div>
            <p className="text-sm font-bold text-slate-800">
              {toast.type === "success" ? "Berhasil!" : "Peringatan!"}
            </p>
            <p className="text-[13px] text-slate-500 mt-0.5">{toast.message}</p>
          </div>
        </div>
      </div>

      {/* DELETE MODAL */}
      {deleteModal.isOpen && (
        <div className="fixed inset-0 z-[150] flex items-center justify-center p-4 bg-slate-900/40 backdrop-blur-sm">
          <div className="bg-white rounded-xl shadow-xl p-6 max-w-sm w-full text-center border border-[#DADCE0]">
            <div className="flex justify-center text-[#D93025] mb-3">
              <IconAlert />
            </div>
            <h3 className="text-lg font-medium text-[#202124] mb-1">
              Tolak & Hapus?
            </h3>
            <p className="text-sm text-[#5F6368] mb-6">
              Yakin menolak dan menghapus pendaftaran{" "}
              <strong>"{deleteModal.title}"</strong>?
            </p>
            <div className="flex gap-3 justify-center">
              <button
                onClick={() =>
                  setDeleteModal({
                    isOpen: false,
                    id: "",
                    title: "",
                    type: "single",
                  })
                }
                className="px-4 py-2 border rounded-lg hover:bg-slate-50 w-full"
              >
                Batal
              </button>
              <button
                onClick={executeDelete}
                disabled={isProcessing}
                className="px-4 py-2 text-white bg-[#D93025] hover:bg-[#b52a1f] rounded-lg w-full"
              >
                {isProcessing ? "Proses..." : "Hapus"}
              </button>
            </div>
          </div>
        </div>
      )}

      {/* APPROVE MODAL */}
      {approveModal.isOpen && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-slate-900/40 backdrop-blur-sm">
          <div className="bg-white rounded-xl shadow-xl max-w-lg w-full overflow-hidden border border-[#DADCE0]">
            <div className="bg-[#F8F9FA] border-b border-[#DADCE0] p-5 flex justify-between items-center">
              <div className="flex items-center gap-3">
                <div className="w-8 h-8 bg-[#E8F0FE] text-[#1A73E8] rounded-full flex items-center justify-center">
                  <IconInfo />
                </div>
                <div>
                  <h3 className="font-medium text-lg text-[#202124]">
                    Sahkan Anggota
                  </h3>
                  <p className="text-[11px] text-[#5F6368]">
                    Lengkapi Posisi & Jabatan
                  </p>
                </div>
              </div>
              <button
                onClick={() =>
                  setApproveModal({
                    isOpen: false,
                    dataId: "",
                    form: { nama: "", wa: "", email: "", jabatan: "Anggota", bidang: "", noUrut: "", isInti: false, isTampilBeranda: false, periodeId: "", domisili: "" },
                  })
                }
                className="text-[#5F6368] hover:bg-[#E8EAED] p-1.5 rounded-full"
              >
                <IconClose />
              </button>
            </div>
            <form onSubmit={executeApprove} className="p-6 space-y-4">
              <div className="grid grid-cols-2 gap-4">
                <div>
                  <label className="block text-xs font-medium mb-1">Nama</label>
                  <input
                    type="text"
                    value={approveModal.form.nama}
                    onChange={(e) =>
                      setApproveModal((p) => ({
                        ...p,
                        form: { ...p.form, nama: e.target.value },
                      }))
                    }
                    required
                    className="w-full border px-3 py-2 rounded-md text-sm outline-none focus:border-[#1A73E8]"
                  />
                </div>
                <div>
                  <label className="block text-xs font-medium mb-1">
                    WhatsApp
                  </label>
                  <input
                    type="text"
                    value={approveModal.form.wa}
                    onChange={(e) =>
                      setApproveModal((p) => ({
                        ...p,
                        form: { ...p.form, wa: e.target.value },
                      }))
                    }
                    className="w-full border px-3 py-2 rounded-md text-sm outline-none focus:border-[#1A73E8] font-mono"
                  />
                </div>
              </div>
              <div className="grid grid-cols-2 gap-4">
                <div>
                  <label className="block text-xs font-medium mb-1">
                    Pilih Bidang
                  </label>
                  <select
                    value={approveModal.form.bidang}
                    onChange={(e) =>
                      setApproveModal((p) => ({
                        ...p,
                        form: { ...p.form, bidang: e.target.value },
                      }))
                    }
                    className="w-full border px-3 py-2 rounded-md text-sm outline-none focus:border-[#1A73E8]"
                  >
                    {bidangList.map((b) => (
                      <option key={b.id} value={b.namaBidang}>
                        {b.namaBidang}
                      </option>
                    ))}
                  </select>
                </div>
                <div>
                  <label className="block text-xs font-medium mb-1">
                    Tetapkan Jabatan
                  </label>
                  <select
                    value={approveModal.form.jabatan}
                    onChange={(e) =>
                      setApproveModal((p) => ({
                        ...p,
                        form: { ...p.form, jabatan: e.target.value },
                      }))
                    }
                    className="w-full border px-3 py-2 rounded-md text-sm outline-none focus:border-[#1A73E8]"
                  >
                    <option value="Ketua Umum">Ketua Umum</option>
                    <option value="Ketua">Ketua</option>
                    <option value="Wakil Ketua Umum">Wakil Ketua Umum</option>
                    <option value="Wakil Ketua">Wakil Ketua</option>
                    <option value="Sekretaris Wilayah">
                      Sekretaris Wilayah
                    </option>
                    <option value="Wakil Sekretaris">Wakil Sekretaris</option>
                    <option value="Bendahara Umum">Bendahara Umum</option>
                    <option value="Wakil Bendahara">Wakil Bendahara</option>
                    <option value="Koordinator Bidang">
                      Koordinator Bidang
                    </option>
                    <option value="Anggota">Anggota</option>
                  </select>
                </div>
              </div>
              <div>
                <label className="block text-xs font-medium text-[#1A73E8] mb-1">
                  Periode Kepengurusan
                </label>
                <select
                  value={approveModal.form.periodeId}
                  onChange={(e) =>
                    setApproveModal((p) => ({
                      ...p,
                      form: { ...p.form, periodeId: e.target.value },
                    }))
                  }
                  required
                  className="w-full border border-[#1A73E8] bg-[#E8F0FE] text-[#1A73E8] px-3 py-2 rounded-md text-sm font-medium outline-none"
                >
                  <option value="" disabled>
                    -- Pilih Periode --
                  </option>
                  {periodeList.map((p) => (
                    <option key={p.id} value={p.id}>
                      {p.namaPeriode} {p.status === "Aktif" ? "(Aktif)" : ""}
                    </option>
                  ))}
                </select>
              </div>
              <div className="grid grid-cols-1 gap-4 mt-4">
                <div>
                  <label className="block text-xs font-medium mb-1">
                    Pilih Domisili
                  </label>
                  <select
                    value={approveModal.form.domisili}
                    onChange={(e) =>
                      setApproveModal((p) => ({
                        ...p,
                        form: { ...p.form, domisili: e.target.value },
                      }))
                    }
                    className="w-full border px-3 py-2 rounded-md text-sm outline-none focus:border-[#1A73E8]"
                  >
                    <option value="">-- Kosong --</option>
                    <option value="Kabupaten Sleman">Kabupaten Sleman</option>
                    <option value="Kabupaten Bantul">Kabupaten Bantul</option>
                    <option value="Kabupaten Gunungkidul">Kabupaten Gunungkidul</option>
                    <option value="Kabupaten Kulon Progo">Kabupaten Kulon Progo</option>
                    <option value="Kota Yogyakarta">Kota Yogyakarta</option>
                    <option value="Luar DIY">Luar DIY</option>
                  </select>
                </div>
              </div>
              <div className="flex gap-5 pt-2">
                <label className="flex items-center gap-2 cursor-pointer">
                  <input
                    type="checkbox"
                    checked={approveModal.form.isInti}
                    onChange={(e) =>
                      setApproveModal((p) => ({
                        ...p,
                        form: { ...p.form, isInti: e.target.checked },
                      }))
                    }
                    className="w-4 h-4 text-[#1A73E8]"
                  />
                  <span className="text-sm font-medium">SK Inti</span>
                </label>
                <label className="flex items-center gap-2 cursor-pointer">
                  <input
                    type="checkbox"
                    checked={approveModal.form.isTampilBeranda}
                    onChange={(e) =>
                      setApproveModal((p) => ({
                        ...p,
                        form: { ...p.form, isTampilBeranda: e.target.checked },
                      }))
                    }
                    className="w-4 h-4 text-[#1A73E8]"
                  />
                  <span className="text-sm font-medium">Tampil Beranda</span>
                </label>
              </div>
              <div className="pt-4 flex justify-end gap-3 border-t mt-4">
                <button
                  type="button"
                  onClick={() =>
                    setApproveModal({
                      isOpen: false,
                      dataId: "",
                      form: { nama: "", wa: "", email: "", jabatan: "Anggota", bidang: "", noUrut: "", isInti: false, isTampilBeranda: false, periodeId: "", domisili: "" },
                    })
                  }
                  className="px-5 py-2 text-sm font-medium border rounded-md hover:bg-slate-50"
                >
                  Batal
                </button>
                <button
                  type="submit"
                  disabled={isProcessing}
                  className="px-5 py-2 text-sm font-medium text-white bg-[#1A73E8] hover:bg-[#1557B0] rounded-md"
                >
                  {isProcessing ? "Proses..." : "Konfirmasi & Sahkan"}
                </button>
              </div>
            </form>
          </div>
        </div>
      )}

      {/* VIEW UTAMA */}
      <div className="bg-white rounded-lg border border-[#DADCE0] shadow-sm flex flex-col mb-6">
        <div className="p-4 border-b border-[#DADCE0] flex flex-col gap-4 bg-[#FCE8E6]/30">
          <div className="flex justify-between items-center">
            <h3 className="font-medium text-[#202124]">Antrean Konfirmasi</h3>
            <div className="flex gap-2">
              {selectedIds.length > 0 && (
                <button
                  onClick={() =>
                    setDeleteModal({
                      isOpen: true,
                      type: "bulk",
                      id: "",
                      title: `${selectedIds.length} Data Terpilih`,
                    })
                  }
                  className="text-xs bg-white text-[#D93025] border border-[#FCE8E6] hover:bg-[#FCE8E6] px-4 py-2 rounded-lg font-bold"
                >
                  Tolak ({selectedIds.length})
                </button>
              )}
              <button
                onClick={handleExportData}
                className="text-xs font-bold border px-4 py-2 rounded-lg hover:bg-slate-50 flex items-center gap-2"
              >
                <IconDownload /> Export
              </button>
            </div>
          </div>
          <div className="flex flex-wrap items-center gap-3">
            <div className="relative w-full sm:w-64">
              <div className="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none">
                <IconSearch />
              </div>
              <input
                type="text"
                placeholder="Cari nama, email..."
                value={search}
                onChange={(e) => setSearch(e.target.value)}
                className="w-full pl-9 pr-4 py-2 border rounded-lg text-sm outline-none focus:border-[#1A73E8]"
              />
            </div>
            <select
              value={filterBidang}
              onChange={(e) => setFilterBidang(e.target.value)}
              className="border py-2 px-3 rounded-lg text-xs font-medium outline-none"
            >
              <option value="Semua">Semua Pilihan Bidang</option>
              {bidangList.map((b) => (
                <option key={b.id} value={b.namaBidang}>
                  {b.namaBidang}
                </option>
              ))}
            </select>
          </div>
        </div>

        <div className="overflow-x-auto min-h-[400px]">
          {isLoading ? (
            <div className="p-10 text-center text-slate-500">
              Memuat data pendaftar...
            </div>
          ) : (
            <table className="w-full text-left text-sm whitespace-nowrap">
              <thead className="bg-[#F8F9FA] border-b text-slate-500 sticky top-0">
                <tr>
                  <th className="px-4 py-3 w-8">
                    <input
                      type="checkbox"
                      onChange={(e) =>
                        setSelectedIds(
                          e.target.checked ? filteredData.map((d) => d.id) : [],
                        )
                      }
                      checked={
                        filteredData.length > 0 &&
                        selectedIds.length === filteredData.length
                      }
                      className="rounded cursor-pointer"
                    />
                  </th>
                  <th className="px-4 py-3 font-bold text-[11px] uppercase w-12">
                    No
                  </th>
                  <th className="px-4 py-3 font-bold text-[11px] uppercase">
                    Pendaftar
                  </th>
                  <th className="px-4 py-3 font-bold text-[11px] uppercase">
                    Preferensi Bidang
                  </th>
                  <th className="px-4 py-3 font-bold text-[11px] uppercase text-right">
                    Tindakan
                  </th>
                </tr>
              </thead>
              <tbody className="divide-y divide-[#DADCE0]">
                {filteredData.length === 0 ? (
                  <tr>
                    <td colSpan={5} className="text-center py-16">
                      <IconEmpty />
                      <p className="text-slate-500">
                        Tidak ada antrean pendaftar.
                      </p>
                    </td>
                  </tr>
                ) : (
                  filteredData.map((p, i) => (
                    <tr key={p.id} className="hover:bg-[#F8F9FA]">
                      <td className="px-4 py-3">
                        <input
                          type="checkbox"
                          checked={selectedIds.includes(p.id)}
                          onChange={(e) =>
                            setSelectedIds((prev) =>
                              e.target.checked
                                ? [...prev, p.id]
                                : prev.filter((id) => id !== p.id),
                            )
                          }
                          className="rounded cursor-pointer"
                        />
                      </td>
                      <td className="px-4 py-3 font-mono text-xs text-slate-400">
                        {i + 1}
                      </td>
                      <td className="px-4 py-3">
                        <div className="font-medium text-[#202124]">
                          {p.nama}
                        </div>
                        <div className="text-xs text-[#5F6368]">
                          {p.wa} • {p.email}
                        </div>
                      </td>
                      <td className="px-4 py-3 text-sm text-[#3C4043]">
                        {p.bidang || "Belum milih"}
                      </td>
                      <td className="px-4 py-3 text-right space-x-2">
                        <button
                          onClick={() =>
                            setDeleteModal({
                              isOpen: true,
                              id: p.id,
                              title: p.nama,
                              type: "single",
                            })
                          }
                          className="text-xs text-[#D93025] hover:bg-[#FCE8E6] border border-transparent px-3 py-1.5 rounded font-medium"
                        >
                          Tolak
                        </button>
                        <button
                          onClick={() => openApproveModal(p)}
                          className="text-xs text-[#1E8E3E] hover:bg-[#E6F4EA] border border-[#1E8E3E] px-3 py-1.5 rounded font-medium"
                        >
                          Tinjau & Sahkan
                        </button>
                      </td>
                    </tr>
                  ))
                )}
              </tbody>
            </table>
          )}
        </div>
      </div>
    </div>
  );
}

"use client";
import Swal from "sweetalert2";

import { useState, useEffect, useMemo, useRef } from "react";
import { db } from "@/lib/firebase";
import { sendWaAction } from "@/app/actions/wa";
import {
  collection,
  addDoc,
  getDocs,
  getDoc,
  setDoc,
  deleteDoc,
  doc,
  updateDoc,
  query,
  orderBy,
} from "firebase/firestore";
import * as XLSX from "xlsx";
import QRCode from "react-qr-code";
import {
  IconPlus,
  IconDownload,
  IconSearch,
  IconCheck,
  IconAlert,
  IconEmpty,
  IconRefresh,
} from "./Icons";

export default function TabAnggotaSah() {
  const [pengurusList, setPengurusList] = useState<any[]>([]);
  const [periodeList, setPeriodeList] = useState<any[]>([]);
  const [dpdList, setDpdList] = useState<any[]>([]);

  const [isLoading, setIsLoading] = useState(true);
  const [isProcessing, setIsProcessing] = useState(false);
  const [isSendingWA, setIsSendingWA] = useState(false);

  const [view, setView] = useState<"list" | "form">("list");
  const [editId, setEditId] = useState<string | null>(null);
  const [selectedIds, setSelectedIds] = useState<string[]>([]); // Untuk centang massal

  // Filter States
  const [search, setSearch] = useState("");
  const [filterPeriode, setFilterPeriode] = useState("Semua");
  const [sortMode, setSortMode] = useState("nama");

  const [itemsPerPage, setItemsPerPage] = useState<number | string>(10);
  const [currentPage, setCurrentPage] = useState(1);

  // Modals
  const [toast, setToast] = useState({
    isOpen: false,
    message: "",
    type: "success",
  });
  const [deleteModal, setDeleteModal] = useState({
    isOpen: false,
    id: "",
    title: "",
    type: "single",
  });
  const [bypassModal, setBypassModal] = useState({
    isOpen: false,
    user: null as any,
    domisili: "",
  });
  const [detailModal, setDetailModal] = useState({
    isOpen: false,
    data: null as any,
  });
  const [isFlipped, setIsFlipped] = useState(false);

  // Form State
  const [form, setForm] = useState({
    nama: "",
    wa: "",
    email: "",
    jabatan: "Anggota",
    bidang: "",
    linkTTD: "",
    isInti: false,
    fotoUrl: "",
    fotoPosition: "center",
    linkedinUrl: "",
    instagramUrl: "",
    isTampilBeranda: false,
    noUrut: "",
    isPengurus: true,
    status_pengurus: "Aktif",
    nia: "",
    periodeId: "",
    fakultas: "",
    programStudi: "",
    angkatan: "",
    domisili: "",
    role: "anggota",
  });

  const showToast = (
    message: string,
    type: "success" | "error" = "success",
  ) => {
    setToast({ isOpen: true, message, type });
    setTimeout(() => setToast((prev) => ({ ...prev, isOpen: false })), 4000);
  };

  // 🔥 FUNGSI KIRIM WHATSAPP 🔥
  const triggerWaApi = async (
    type: string,
    phone: string,
    nama: string,
    detailData: any = {},
  ) => {
    if (!phone || phone.length < 9) return false;
    try {
      const data = await sendWaAction({
        type,
        phone,
        nama,
        detail: detailData,
      });
      return data.success;
    } catch (error) {
      return false;
    }
  };

  const submitBypassNIA = async () => {
    const user = bypassModal.user;
    const finalDomisili = bypassModal.domisili;
    if (!finalDomisili) {
      return setToast({ isOpen: true, message: "Domisili wajib dipilih untuk kode wilayah NIA.", type: "error" });
    }

    const _swalRes = await Swal.fire({
      title: 'Konfirmasi',
      text: `Anda yakin ingin menerbitkan NIA untuk ${user.nama}?`,
      icon: 'warning',
      showCancelButton: true,
      confirmButtonText: 'Ya, Lanjutkan',
      cancelButtonText: 'Batal',
      confirmButtonColor: '#059669',
      cancelButtonColor: '#ef4444'
    });
    if (_swalRes.isConfirmed) {
      setIsProcessing(true);
      try {
        const counterRef = doc(db, "pengaturan", "counter_nia");
        const counterSnap = await getDoc(counterRef);
        let newNumber = 89;
        if (counterSnap.exists())
          newNumber = (counterSnap.data().lastNumber || 88) + 1;
        await setDoc(counterRef, { lastNumber: newNumber }, { merge: true });

        const dateObj = new Date();
        const yearStr = dateObj.getFullYear().toString().slice(-2);
        const monthStr = String(dateObj.getMonth() + 1).padStart(2, "0");
        let kabStr = "00";
        const dom = finalDomisili.toLowerCase();
        if (dom.includes("sleman")) kabStr = "04";
        else if (dom.includes("bantul")) kabStr = "02";
        else if (dom.includes("gunung")) kabStr = "03";
        else if (dom.includes("kulon")) kabStr = "01";
        else if (dom.includes("kota") || dom.includes("yogya")) kabStr = "71";

        const urutStr = String(newNumber).padStart(4, "0");
        const finalNIA = `${yearStr}.${monthStr}.34.${kabStr}.${urutStr}`;

        await updateDoc(doc(db, "pengurus", user.id), {
          nia: finalNIA,
          domisili: finalDomisili
        });

        setToast({ isOpen: true, message: `NIA berhasil diterbitkan: ${finalNIA}`, type: "success" });
        
        setDetailModal(prev => ({ ...prev, data: { ...prev.data, nia: finalNIA, domisili: finalDomisili } }));
        setBypassModal({ isOpen: false, user: null, domisili: "" });
        fetchData();
      } catch (error) {
        console.error(error);
        setToast({ isOpen: true, message: "Gagal menerbitkan NIA.", type: "error" });
      } finally {
        setIsProcessing(false);
        setTimeout(() => setToast(prev => ({ ...prev, isOpen: false })), 4000);
      }
    }
  };

  const fetchData = async () => {
    setIsLoading(true);
    try {
      const pSnap = await getDocs(
        query(collection(db, "periode"), orderBy("tglMulai", "desc")),
      );
      const pList = pSnap.docs.map((d) => ({ id: d.id, ...d.data() }));
      setPeriodeList(pList);

      const activePeriode = pList.find((p: any) => p.status === "Aktif");
      if (activePeriode && filterPeriode === "Semua")
        setFilterPeriode(activePeriode.id);

      const dSnap = await getDocs(
        query(collection(db, "dpd"), orderBy("nama", "asc")),
      );
      setDpdList(dSnap.docs.map((d) => ({ id: d.id, ...d.data() })));

      const uSnap = await getDocs(
        query(collection(db, "pengurus"), orderBy("createdAt", "desc")),
      );
      const allUsers = uSnap.docs.map((d) => ({ id: d.id, ...d.data() }));
      const sah = allUsers.filter(
        (u: any) => u.role === "anggota" && u.status_pengurus === "Aktif"
      );

      setPengurusList(sah);
    } catch (error) {
      showToast("Gagal memuat data personalia.", "error");
    } finally {
      setIsLoading(false);
      setSelectedIds([]);
    }
  };

  useEffect(() => {
    fetchData();
  }, []);

  const filteredData = useMemo(() => {
    let result = pengurusList;
    if (filterPeriode !== "Semua")
      result = result.filter((p) => p.periodeId === filterPeriode);
    if (search) {
      const q = search.toLowerCase();
      result = result.filter(
        (p) =>
          p.nama?.toLowerCase().includes(q) ||
          p.jabatan?.toLowerCase().includes(q) ||
          p.bidang?.toLowerCase().includes(q) ||
          p.domisili?.toLowerCase().includes(q),
      );
    }
    if (sortMode === "Nama-Asc") {
      result.sort((a, b) => (a.nama || "").localeCompare(b.nama || ""));
    } else if (sortMode === "Nama-Desc") {
      result.sort((a, b) => (b.nama || "").localeCompare(a.nama || ""));
    } else if (sortMode === "NIA-Asc") {
      result.sort((a, b) => (a.nia || "").localeCompare(b.nia || ""));
    } else if (sortMode === "NIA-Desc") {
      result.sort((a, b) => (b.nia || "").localeCompare(a.nia || ""));
    } else if (sortMode === "Fakultas-Asc") {
      result.sort((a, b) => (a.fakultas || "").localeCompare(b.fakultas || ""));
    } else if (sortMode === "Fakultas-Desc") {
      result.sort((a, b) => (b.fakultas || "").localeCompare(a.fakultas || ""));
    }
    return result;
  }, [search, filterPeriode, sortMode, pengurusList]);

  const paginatedData = useMemo(() => {
    if (itemsPerPage === "Semua") return filteredData;
    const startIndex = (currentPage - 1) * (itemsPerPage as number);
    return filteredData.slice(startIndex, startIndex + (itemsPerPage as number));
  }, [filteredData, currentPage, itemsPerPage]);

  useEffect(() => {
    setCurrentPage(1);
  }, [search, filterPeriode, sortMode]);

  const handleFormChange = (e: any) => {
    const value =
      e.target.type === "checkbox" ? e.target.checked : e.target.value;
    setForm({ ...form, [e.target.name]: value });
  };

  const saveData = async (e: React.FormEvent) => {
    e.preventDefault();
    setIsProcessing(true);
    try {
      const finalData = {
        ...form,
        noUrut: form.noUrut ? Number(form.noUrut) : 99,
        role: "anggota",
      };
      if (editId) {
        await updateDoc(doc(db, "pengurus", editId), {
          ...finalData,
          updatedAt: new Date().toISOString(),
        });
        showToast("Data Anggota diperbarui.", "success");
      } else {
        await addDoc(collection(db, "pengurus"), {
          ...finalData,
          createdAt: new Date().toISOString(),
        });
        showToast("Data Anggota baru ditambahkan.", "success");
      }
      setEditId(null);
      await fetchData();
      setView("list");
    } catch (error) {
      showToast("Gagal menyimpan data.", "error");
    } finally {
      setIsProcessing(false);
    }
  };

  const cabutPengurus = async (id: string, nama: string) => {
    const _swalRes = await Swal.fire({
      title: 'Konfirmasi',
      text: `Yakin ingin mencabut status Anggota dari ${nama}?`,
      icon: 'warning',
      showCancelButton: true,
      confirmButtonText: 'Ya, Lanjutkan',
      cancelButtonText: 'Batal',
      confirmButtonColor: '#059669',
      cancelButtonColor: '#ef4444'
    });
    if (!_swalRes.isConfirmed) return;
    setIsProcessing(true);
    try {
      await updateDoc(doc(db, "pengurus", id), {
        status_pengurus: "Nonaktif",
        updatedAt: new Date().toISOString(),
      });
      showToast(`Status Anggota ${nama} dicabut.`, "success");
      await fetchData();
    } catch (error) {
      showToast("Gagal merubah status.", "error");
    } finally {
      setIsProcessing(false);
    }
  };

  const jadikanCalonPengurus = async (id: string, nama: string) => {
    const _swalRes = await Swal.fire({
      title: 'Konfirmasi',
      text: `Yakin ingin mempromosikan ${nama} menjadi Calon Pengurus? Data akan dipindah ke Antrean Daftar.`,
      icon: 'warning',
      showCancelButton: true,
      confirmButtonText: 'Ya, Lanjutkan',
      cancelButtonText: 'Batal',
      confirmButtonColor: '#059669',
      cancelButtonColor: '#ef4444'
    });
    if (!_swalRes.isConfirmed) return;
    setIsProcessing(true);
    try {
      await updateDoc(doc(db, "pengurus", id), {
        role: "calon_pengurus",
        updatedAt: new Date().toISOString(),
      });
      showToast(`${nama} berhasil dipindahkan ke Antrean Daftar.`, "success");
      await fetchData();
    } catch (error) {
      showToast("Gagal merubah status.", "error");
    } finally {
      setIsProcessing(false);
    }
  };

  const executeDelete = async () => {
    setIsProcessing(true);
    try {
      if (deleteModal.type === "single" && deleteModal.id) {
        await deleteDoc(doc(db, "pengurus", deleteModal.id));
      } else if (deleteModal.type === "bulk" && selectedIds.length > 0) {
        await Promise.all(
          selectedIds.map((id) => deleteDoc(doc(db, "pengurus", id))),
        );
      }
      showToast("Data dihapus permanen.", "success");
      await fetchData();
    } catch (error) {
      showToast("Gagal menghapus data.", "error");
    } finally {
      setIsProcessing(false);
      setDeleteModal({ isOpen: false, id: "", title: "", type: "single" });
    }
  };

  const handleExportData = () => {
    if (filteredData.length === 0)
      return showToast("Tidak ada data untuk diekspor.", "error");
    const wsData = filteredData.map((d, i) => ({
      No: i + 1,
      Nama: d.nama,
      WA: d.wa,
      Email: d.email,
      Fakultas: d.fakultas || "-",
      Prodi: d.programStudi || "-",
      Angkatan: d.angkatan || "-",
      Domisili: d.domisili || "-",
      NIA: d.nia || "Belum Terbit",
      Periode_ID: d.periodeId || "",
    }));
    const ws = XLSX.utils.json_to_sheet(wsData);
    const wb = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(wb, ws, "Anggota");
    XLSX.writeFile(wb, `Data_ANGGOTA_SAH.xlsx`);
  };

  const openDetail = (user: any) => {
    setDetailModal({ isOpen: true, data: user });
    setIsFlipped(false);
  };

  const toggleSelectAll = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.checked) {
      setSelectedIds(filteredData.map((d) => d.id));
    } else {
      setSelectedIds([]);
    }
  };

  const toggleSelect = (id: string) => {
    setSelectedIds((prev) =>
      prev.includes(id) ? prev.filter((i) => i !== id) : [...prev, id],
    );
  };

  return (
    <div className="relative">
      {/* LOCAL TOAST */}
      <div
        className={`fixed top-6 right-6 z-[200] transition-all duration-300 transform ${toast.isOpen ? "translate-y-0 opacity-100" : "-translate-y-4 opacity-0 pointer-events-none"}`}
      >
        <div
          className={`flex items-center gap-3 px-5 py-4 rounded-xl shadow-lg border ${toast.type === "success" ? "bg-white border-emerald-100" : "bg-white border-red-100"}`}
        >
          <div
            className={`flex-shrink-0 w-9 h-9 rounded-full flex items-center justify-center ${toast.type === "success" ? "bg-emerald-100 text-emerald-600" : "bg-red-100 text-red-600"}`}
          >
            {toast.type === "success" ? <IconCheck /> : <IconAlert />}
          </div>
          <div>
            <p className="text-sm font-bold text-slate-800">
              {toast.type === "success" ? "Berhasil!" : "Peringatan!"}
            </p>
            <p className="text-[13px] text-slate-500 mt-0.5">{toast.message}</p>
          </div>
        </div>
      </div>

      {/* MODAL PREVIEW KTA & KIRIM WHATSAPP */}
      {detailModal.isOpen && detailModal.data && (
        <div className="fixed inset-0 z-[150] flex items-center justify-center p-4 bg-slate-900/60 backdrop-blur-sm">
          <div className="flex flex-col items-center w-full max-w-sm">
            <div className="w-full max-w-[280px] mt-4 bg-white rounded-xl p-3 shadow-md border border-[#DADCE0]">
              <div className="flex flex-col gap-2">
                <button
                  onClick={() => setDetailModal({ isOpen: false, data: null })}
                  className="flex-1 bg-white text-[#5F6368] font-medium text-xs py-2 rounded-lg border border-[#DADCE0] hover:bg-slate-50 transition-colors"
                >
                  Tutup
                </button>
              </div>
            </div>
          </div>
        </div>
      )}

      {/* VIEW UTAMA */}
      {view === "list" ? (
        <div className="bg-white rounded-xl border border-[#DADCE0] shadow-sm overflow-hidden flex flex-col">
          <div className="p-5 border-b border-[#DADCE0] flex flex-col gap-5">
            <div className="flex flex-col md:flex-row justify-between items-start md:items-center">
              <div>
                <h3 className="font-bold text-[#202124] text-[18px]">
                  Database Anggota Sah
                </h3>
                <p className="text-[12px] text-slate-500 mt-0.5">
                  Daftar anggota yang telah disetujui.
                </p>
              </div>
              <div className="flex gap-2 w-full md:w-auto mt-3 md:mt-0">
                <button
                  onClick={handleExportData}
                  className="w-full md:w-auto text-xs font-bold border border-[#DADCE0] text-slate-600 px-4 py-2 rounded-lg hover:bg-slate-50 flex items-center justify-center gap-2 transition-colors"
                >
                  <IconDownload /> Export Excel
                </button>
              </div>
            </div>

            <div className="flex flex-col md:flex-row items-center gap-3 w-full bg-[#F8F9FA] p-3 rounded-lg border border-[#EBEBEB]">
              <div className="relative w-full md:w-auto flex-1">
                <div className="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none">
                  <IconSearch />
                </div>
                <input
                  type="text"
                  placeholder="Cari nama atau domisili..."
                  value={search}
                  onChange={(e) => setSearch(e.target.value)}
                  className="w-full pl-9 pr-4 py-2.5 border border-[#DADCE0] rounded-lg text-sm bg-white outline-none focus:border-[#1A73E8] transition-colors shadow-sm"
                />
              </div>
            </div>
          </div>

          <div className="overflow-x-auto min-h-[400px]">
            {isLoading ? (
              <div className="p-10 text-center text-slate-500">Memuat data...</div>
            ) : (
              <table className="w-full text-left text-sm">
                <thead className="bg-[#F8F9FA] border-b border-[#DADCE0]">
                  <tr>
                    <th 
                      className="py-4 px-5 text-left text-xs font-bold text-slate-500 uppercase cursor-pointer hover:bg-slate-200 transition-colors group"
                      onClick={() => setSortMode(sortMode === "Nama-Asc" ? "Nama-Desc" : "Nama-Asc")}
                    >
                      <div className="flex items-center gap-1">
                        Nama
                        <span className="text-slate-400 group-hover:text-slate-600">
                          {sortMode === "Nama-Asc" ? "↑" : sortMode === "Nama-Desc" ? "↓" : "↕"}
                        </span>
                      </div>
                    </th>
                    <th 
                      className="py-4 px-5 text-left text-xs font-bold text-slate-500 uppercase cursor-pointer hover:bg-slate-200 transition-colors group"
                      onClick={() => setSortMode(sortMode === "Fakultas-Asc" ? "Fakultas-Desc" : "Fakultas-Asc")}
                    >
                      <div className="flex items-center gap-1">
                        Fakultas / Angkatan
                        <span className="text-slate-400 group-hover:text-slate-600">
                          {sortMode === "Fakultas-Asc" ? "↑" : sortMode === "Fakultas-Desc" ? "↓" : "↕"}
                        </span>
                      </div>
                    </th>
                    <th 
                      className="py-4 px-5 text-left text-xs font-bold text-slate-500 uppercase cursor-pointer hover:bg-slate-200 transition-colors group"
                      onClick={() => setSortMode(sortMode === "NIA-Asc" ? "NIA-Desc" : "NIA-Asc")}
                    >
                      <div className="flex items-center gap-1">
                        NIA
                        <span className="text-slate-400 group-hover:text-slate-600">
                          {sortMode === "NIA-Asc" ? "↑" : sortMode === "NIA-Desc" ? "↓" : "↕"}
                        </span>
                      </div>
                    </th>
                    <th className="py-4 px-5 text-right text-xs font-bold text-slate-500 uppercase">Aksi</th>
                  </tr>
                </thead>
                <tbody className="divide-y divide-[#EBEBEB]">
                  {paginatedData.map((user) => (
                    <tr key={user.id}>
                      <td className="py-4 px-5">{user.nama}</td>
                      <td className="py-4 px-5 text-xs text-slate-600">{user.fakultas || "-"} / {user.angkatan || "-"}</td>
                      <td className="py-4 px-5 font-mono text-xs">{user.nia || "-"}</td>
                      <td className="py-4 px-5 text-right">
                        <div className="flex justify-end gap-2">
                          <button 
                            onClick={() => setBypassModal({ isOpen: true, user: user, domisili: user.domisili || "" })} 
                            className="border border-blue-200 bg-blue-50 text-blue-700 p-1.5 rounded-md hover:bg-blue-100 shadow-sm transition-colors"
                            title={user.nia ? "Reset & Generate Ulang NIA" : "Generate NIA"}
                          >
                            <IconRefresh />
                          </button>
                          <button onClick={() => jadikanCalonPengurus(user.id, user.nama)} className="border border-emerald-200 bg-emerald-50 text-emerald-700 px-3 py-1.5 rounded-md text-xs font-bold hover:bg-emerald-100 shadow-sm transition-colors">Jadikan Pengurus</button>
                          <button onClick={() => cabutPengurus(user.id, user.nama)} className="border border-red-200 text-red-600 px-3 py-1.5 rounded-md text-xs font-bold hover:bg-red-50 shadow-sm transition-colors">Cabut</button>
                        </div>
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            )}
          </div>

          <div className="bg-[#F8F9FA] border-t border-[#DADCE0] px-5 py-4 flex items-center justify-between">
            <div className="flex items-center gap-3">
              <span className="text-sm">Tampilkan:</span>
              <select value={itemsPerPage} onChange={e => setItemsPerPage(e.target.value === "Semua" ? "Semua" : Number(e.target.value))} className="border rounded p-1">
                <option value={10}>10 Baris</option>
                <option value={20}>20 Baris</option>
                <option value="Semua">Semua Data</option>
              </select>
            </div>
            <div className="flex gap-2">
              <button disabled={currentPage === 1} onClick={() => setCurrentPage(p => p - 1)} className="px-3 py-1 border rounded">Sebelumnya</button>
              <button disabled={currentPage * (itemsPerPage as number) >= filteredData.length} onClick={() => setCurrentPage(p => p + 1)} className="px-3 py-1 border rounded">Selanjutnya</button>
            </div>
          </div>
        </div>
      ) : null}

      {/* BYPASS MODAL */}
      {bypassModal.isOpen && (
        <div className="fixed inset-0 z-[150] bg-slate-900/40 backdrop-blur-sm flex items-center justify-center p-4">
          <div className="bg-white w-full max-w-sm rounded-2xl shadow-xl">
            <div className="p-5 border-b border-slate-100 flex items-center gap-3 bg-amber-50">
              <div className="w-10 h-10 rounded-full bg-amber-100 text-amber-600 flex items-center justify-center">
                <svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M13 10V3L4 14h7v7l9-11h-7z" /></svg>
              </div>
              <div>
                <h3 className="text-sm font-bold text-slate-800">Data Anggota Sah</h3>
                <p className="text-xs text-slate-500">Kelola anggota yang telah disetujui</p>
              </div>
            </div>
            <div className="p-5">
              <p className="text-xs text-slate-500 mb-4 leading-relaxed">
                Beberapa data seperti <strong>Foto</strong> akan dilewati (di-bypass), namun <strong>Domisili</strong> wajib diisi untuk menentukan Kode Wilayah pada nomor NIA.
              </p>
              <div className="space-y-4">
                <div>
                  <label className="block text-xs font-bold text-slate-700 mb-1.5">Nama Pengurus</label>
                  <div className="w-full bg-slate-50 border border-slate-200 rounded-lg px-3 py-2 text-sm text-slate-600 font-medium">
                    {bypassModal.user?.nama}
                  </div>
                </div>
                <div>
                  <label className="block text-xs font-bold text-slate-700 mb-1.5">Pilih Domisili <span className="text-rose-500">*</span></label>
                  <select
                    value={bypassModal.domisili}
                    onChange={(e) => setBypassModal({ ...bypassModal, domisili: e.target.value })}
                    className="w-full bg-white border border-slate-300 rounded-lg px-3 py-2 text-sm focus:outline-none focus:border-[#1A73E8] focus:ring-1 focus:ring-[#1A73E8] transition-colors"
                  >
                    <option value="">-- Pilih Kabupaten/Kota --</option>
                    <option value="Kabupaten Sleman">Kabupaten Sleman</option>
                    <option value="Kabupaten Bantul">Kabupaten Bantul</option>
                    <option value="Kabupaten Gunungkidul">Kabupaten Gunungkidul</option>
                    <option value="Kabupaten Kulon Progo">Kabupaten Kulon Progo</option>
                    <option value="Kota Yogyakarta">Kota Yogyakarta</option>
                    <option value="Luar DIY">Luar DIY</option>
                  </select>
                </div>
              </div>
            </div>
            <div className="p-4 bg-slate-50 border-t border-slate-100 flex justify-end gap-3">
              <button 
                onClick={() => setBypassModal({ isOpen: false, user: null, domisili: "" })}
                className="px-4 py-2 text-sm font-bold text-slate-600 hover:bg-slate-200 rounded-lg transition-colors"
              >
                Batal
              </button>
              <button 
                onClick={submitBypassNIA}
                disabled={!bypassModal.domisili || isProcessing}
                className="px-4 py-2 text-sm font-bold text-white bg-amber-500 hover:bg-amber-600 disabled:opacity-50 disabled:cursor-not-allowed rounded-lg transition-colors flex items-center gap-2"
              >
                {isProcessing ? "Memproses..." : "Generate Sekarang"}
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

"use client";

import { useState, useEffect } from "react";
import { db } from "@/lib/firebase";
import {
  collection,
  addDoc,
  getDocs,
  deleteDoc,
  doc,
  updateDoc,
  query,
  orderBy,
} from "firebase/firestore";
import * as XLSX from "xlsx";
import {
  IconPlus,
  IconDownload,
  IconUpload,
  IconCheck,
  IconAlert,
  IconEmpty,
} from "./Icons";

export default function TabBidang() {
  const [dataList, setDataList] = useState<any[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [isProcessing, setIsProcessing] = useState(false);

  const [view, setView] = useState<"list" | "form">("list");
  const [editId, setEditId] = useState<string | null>(null);
  const [selectedIds, setSelectedIds] = useState<string[]>([]);

  const [form, setForm] = useState({
    namaBidang: "",
    deskripsi: "",
  });

  const [toast, setToast] = useState({
    isOpen: false,
    message: "",
    type: "success",
  });
  const [deleteModal, setDeleteModal] = useState({
    isOpen: false,
    id: "",
    title: "",
    type: "single",
  });

  const showToast = (
    message: string,
    type: "success" | "error" = "success",
  ) => {
    setToast({ isOpen: true, message, type });
    setTimeout(() => setToast((prev) => ({ ...prev, isOpen: false })), 4000);
  };

  const fetchData = async () => {
    setIsLoading(true);
    try {
      const snap = await getDocs(
        query(collection(db, "bidang"), orderBy("namaBidang", "asc")),
      );
      setDataList(snap.docs.map((d) => ({ id: d.id, ...d.data() })));
    } catch (error) {
      showToast("Gagal load data bidang.", "error");
    } finally {
      setIsLoading(false);
      setSelectedIds([]);
    }
  };

  useEffect(() => {
    fetchData();
  }, []);

  const handleFormChange = (e: any) =>
    setForm({ ...form, [e.target.name]: e.target.value });

  const saveData = async (e: React.FormEvent) => {
    e.preventDefault();
    setIsProcessing(true);
    try {
      if (editId) {
        await updateDoc(doc(db, "bidang", editId), {
          ...form,
          updatedAt: new Date().toISOString(),
        });
        showToast("Bidang berhasil diperbarui.", "success");
      } else {
        await addDoc(collection(db, "bidang"), {
          ...form,
          createdAt: new Date().toISOString(),
        });
        showToast("Bidang baru berhasil ditambahkan.", "success");
      }
      setForm({ namaBidang: "", deskripsi: "" });
      setEditId(null);
      await fetchData();
      setView("list");
    } catch (error) {
      showToast("Gagal menyimpan data.", "error");
    } finally {
      setIsProcessing(false);
    }
  };

  const executeDelete = async () => {
    setIsProcessing(true);
    try {
      if (deleteModal.type === "single" && deleteModal.id) {
        await deleteDoc(doc(db, "bidang", deleteModal.id));
      } else if (deleteModal.type === "bulk" && selectedIds.length > 0) {
        await Promise.all(
          selectedIds.map((id) => deleteDoc(doc(db, "bidang", id))),
        );
      }
      showToast("Data berhasil dihapus permanen.", "success");
      await fetchData();
    } catch (error) {
      showToast("Gagal menghapus data.", "error");
    } finally {
      setIsProcessing(false);
      setDeleteModal({ isOpen: false, id: "", title: "", type: "single" });
    }
  };

  // --- LOGIKA EXCEL ---
  const handleExportData = () => {
    if (dataList.length === 0)
      return showToast("Tidak ada data untuk diekspor.", "error");
    const formattedData = dataList.map((d) => ({ Nama_Bidang: d.namaBidang }));
    const ws = XLSX.utils.json_to_sheet(formattedData);
    const wb = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(wb, ws, "Data_Bidang");
    XLSX.writeFile(wb, `Data_BIDANG_IKA_UII.xlsx`);
  };

  const downloadTemplateExcel = () => {
    const ws = XLSX.utils.json_to_sheet([{ Nama_Bidang: "Dewan Pakar" }]);
    const wb = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(wb, ws, "Template");
    XLSX.writeFile(wb, `Template_Import_BIDANG.xlsx`);
  };

  const handleImportExcel = async (e: any) => {
    const file = e.target.files[0];
    if (!file) return;
    setIsProcessing(true);
    const reader = new FileReader();
    reader.onload = async (evt: any) => {
      try {
        const bstr = evt.target.result;
        const wb = XLSX.read(bstr, { type: "binary" });
        const data = XLSX.utils.sheet_to_json(wb.Sheets[wb.SheetNames[0]]);
        let count = 0;
        for (const row of data as any[]) {
          if (row.Nama_Bidang) {
            await addDoc(collection(db, "bidang"), {
              namaBidang: row.Nama_Bidang,
              deskripsi: "",
              createdAt: new Date().toISOString(),
            });
            count++;
          }
        }
        showToast(`${count} Data berhasil di-import!`, "success");
        await fetchData();
      } catch (error) {
        showToast("Gagal membaca Excel.", "error");
      } finally {
        setIsProcessing(false);
        e.target.value = null;
      }
    };
    reader.readAsBinaryString(file);
  };

  return (
    <div className="relative">
      {/* LOCAL TOAST */}
      <div
        className={`fixed top-6 right-6 z-[200] transition-all duration-300 transform ${toast.isOpen ? "translate-y-0 opacity-100" : "-translate-y-4 opacity-0 pointer-events-none"}`}
      >
        <div
          className={`flex items-center gap-3 px-5 py-4 rounded-xl shadow-lg border ${toast.type === "success" ? "bg-white border-emerald-100" : "bg-white border-red-100"}`}
        >
          <div
            className={`flex-shrink-0 w-9 h-9 rounded-full flex items-center justify-center ${toast.type === "success" ? "bg-emerald-100 text-emerald-600" : "bg-red-100 text-red-600"}`}
          >
            {toast.type === "success" ? <IconCheck /> : <IconAlert />}
          </div>
          <div>
            <p className="text-sm font-bold text-slate-800">
              {toast.type === "success" ? "Berhasil!" : "Peringatan!"}
            </p>
            <p className="text-[13px] text-slate-500 mt-0.5">{toast.message}</p>
          </div>
        </div>
      </div>

      {/* DELETE MODAL */}
      {deleteModal.isOpen && (
        <div className="fixed inset-0 z-[150] flex items-center justify-center p-4 bg-slate-900/40 backdrop-blur-sm">
          <div className="bg-white rounded-xl shadow-xl p-6 max-w-sm w-full text-center border border-[#DADCE0] animate-in zoom-in-95">
            <div className="flex justify-center text-[#D93025] mb-3">
              <IconAlert />
            </div>
            <h3 className="text-lg font-medium text-[#202124] mb-1">
              Hapus Permanen?
            </h3>
            <p className="text-sm text-[#5F6368] mb-6">
              Anda yakin ingin menghapus <strong>"{deleteModal.title}"</strong>?
            </p>
            <div className="flex gap-3 justify-center">
              <button
                onClick={() =>
                  setDeleteModal({
                    isOpen: false,
                    id: "",
                    title: "",
                    type: "single",
                  })
                }
                className="px-4 py-2 rounded-lg text-sm font-medium border w-full hover:bg-slate-50"
              >
                Batal
              </button>
              <button
                onClick={executeDelete}
                disabled={isProcessing}
                className="px-4 py-2 rounded-lg text-sm font-medium text-white bg-[#D93025] hover:bg-[#b52a1f] w-full"
              >
                {isProcessing ? "Proses..." : "Hapus"}
              </button>
            </div>
          </div>
        </div>
      )}

      {view === "list" ? (
        <div className="bg-white rounded-lg border border-[#DADCE0] shadow-sm overflow-hidden">
          <div className="p-4 flex flex-col sm:flex-row justify-between items-start sm:items-center gap-4 border-b border-[#DADCE0]">
            <h3 className="font-medium text-[#202124] text-base">
              Daftar Bidang Organisasi
            </h3>
            <div className="flex flex-wrap items-center gap-2">
              {selectedIds.length > 0 && (
                <button
                  onClick={() =>
                    setDeleteModal({
                      isOpen: true,
                      type: "bulk",
                      id: "",
                      title: `${selectedIds.length} Data Terpilih`,
                    })
                  }
                  className="text-xs text-[#D93025] border border-[#FCE8E6] bg-white hover:bg-[#FCE8E6] px-4 py-2.5 rounded-lg font-bold"
                >
                  Hapus ({selectedIds.length})
                </button>
              )}
              <button
                onClick={handleExportData}
                className="text-xs font-bold text-slate-700 border px-4 py-2.5 rounded-lg hover:bg-slate-50 flex items-center gap-2"
              >
                <IconDownload /> Export
              </button>
              <button
                onClick={downloadTemplateExcel}
                className="text-xs font-bold text-slate-700 border px-4 py-2.5 rounded-lg hover:bg-slate-50"
              >
                Template
              </button>
              <label className="cursor-pointer text-xs font-bold text-slate-700 border bg-[#F8F9FA] px-4 py-2.5 rounded-lg hover:bg-slate-100 flex items-center gap-2">
                <IconUpload /> Import
                <input
                  type="file"
                  accept=".xlsx, .xls"
                  onChange={handleImportExcel}
                  className="hidden"
                />
              </label>
              <button
                onClick={() => {
                  setView("form");
                  setEditId(null);
                  setForm({ namaBidang: "", deskripsi: "" });
                }}
                className="text-xs bg-[#1A73E8] text-white px-4 py-2.5 rounded-lg font-bold flex items-center gap-1.5 hover:bg-[#1557B0]"
              >
                <IconPlus /> Tambah Baru
              </button>
            </div>
          </div>

          <div className="overflow-x-auto min-h-[300px]">
            {isLoading ? (
              <div className="p-10 text-center text-slate-500">
                Memuat data...
              </div>
            ) : (
              <table className="w-full text-left text-sm whitespace-nowrap">
                <thead className="bg-[#F8F9FA] border-b text-[#5F6368]">
                  <tr>
                    <th className="px-6 py-3 w-8">
                      <input
                        type="checkbox"
                        onChange={(e) =>
                          setSelectedIds(
                            e.target.checked ? dataList.map((d) => d.id) : [],
                          )
                        }
                        checked={
                          dataList.length > 0 &&
                          selectedIds.length === dataList.length
                        }
                        className="rounded cursor-pointer"
                      />
                    </th>
                    <th className="px-6 py-3 font-medium text-xs uppercase">
                      Nama Bidang
                    </th>
                    <th className="px-6 py-3 font-medium text-xs uppercase text-right">
                      Aksi
                    </th>
                  </tr>
                </thead>
                <tbody className="divide-y divide-[#DADCE0]">
                  {dataList.length === 0 ? (
                    <tr>
                      <td colSpan={3} className="text-center py-16">
                        <IconEmpty />
                        <p className="text-slate-500">Belum Ada Bidang</p>
                      </td>
                    </tr>
                  ) : (
                    dataList.map((p) => (
                      <tr key={p.id} className="hover:bg-[#F8F9FA]">
                        <td className="px-6 py-4">
                          <input
                            type="checkbox"
                            checked={selectedIds.includes(p.id)}
                            onChange={(e) =>
                              setSelectedIds((prev) =>
                                e.target.checked
                                  ? [...prev, p.id]
                                  : prev.filter((id) => id !== p.id),
                              )
                            }
                            className="rounded cursor-pointer"
                          />
                        </td>
                        <td className="px-6 py-4 font-medium text-[#202124] text-sm">
                          {p.namaBidang}
                        </td>
                        <td className="px-6 py-4 text-right">
                          <button
                            onClick={() => {
                              setForm(p);
                              setEditId(p.id);
                              setView("form");
                            }}
                            className="text-[#1A73E8] font-medium px-3 py-1.5 hover:bg-[#E8F0FE] rounded transition-colors"
                          >
                            Edit
                          </button>
                        </td>
                      </tr>
                    ))
                  )}
                </tbody>
              </table>
            )}
          </div>
        </div>
      ) : (
        <form
          onSubmit={saveData}
          className="bg-white rounded-lg border border-[#DADCE0] p-6 sm:p-8 max-w-md mx-auto shadow-sm"
        >
          <h3 className="font-medium mb-6 text-lg border-b pb-4">
            {editId ? "Edit Bidang" : "Buat Bidang Baru"}
          </h3>
          <div>
            <label className="block text-xs font-medium text-[#5F6368] mb-1">
              Nama Bidang / Departemen
            </label>
            <input
              type="text"
              name="namaBidang"
              value={form.namaBidang}
              onChange={handleFormChange}
              required
              placeholder="Contoh: Dewan Penasihat"
              className="w-full border px-3 py-2 rounded text-sm focus:border-[#1A73E8] outline-none"
            />
          </div>
          <div className="flex justify-end gap-3 mt-6 pt-4 border-t">
            <button
              type="button"
              onClick={() => setView("list")}
              className="px-5 py-2 text-sm font-medium border rounded hover:bg-slate-50"
            >
              Batal
            </button>
            <button
              type="submit"
              disabled={isProcessing}
              className="px-5 py-2 text-sm font-medium text-white bg-[#1A73E8] rounded hover:bg-[#1557B0]"
            >
              {isProcessing ? "Menyimpan..." : "Simpan"}
            </button>
          </div>
        </form>
      )}
    </div>
  );
}

"use client";

import { useState, useEffect } from "react";
import { db } from "@/lib/firebase";
import {
  collection,
  addDoc,
  getDocs,
  deleteDoc,
  doc,
  updateDoc,
  query,
  orderBy,
} from "firebase/firestore";
import * as XLSX from "xlsx";
import {
  IconPlus,
  IconDownload,
  IconUpload,
  IconCheck,
  IconAlert,
  IconEmpty,
} from "./Icons";

export default function TabDPD() {
  const [dataList, setDataList] = useState<any[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [isProcessing, setIsProcessing] = useState(false);

  const [view, setView] = useState<"list" | "form">("list");
  const [editId, setEditId] = useState<string | null>(null);
  const [selectedIds, setSelectedIds] = useState<string[]>([]);

  const [form, setForm] = useState({
    nama: "",
    ketua: "",
    status: "Aktif",
    fotoUrl: "",
    fotoPosition: "center",
  });

  const [toast, setToast] = useState({
    isOpen: false,
    message: "",
    type: "success",
  });
  const [deleteModal, setDeleteModal] = useState({
    isOpen: false,
    id: "",
    title: "",
    type: "single",
  });

  const showToast = (
    message: string,
    type: "success" | "error" = "success",
  ) => {
    setToast({ isOpen: true, message, type });
    setTimeout(() => setToast((prev) => ({ ...prev, isOpen: false })), 4000);
  };

  const fetchData = async () => {
    setIsLoading(true);
    try {
      const snap = await getDocs(
        query(collection(db, "dpd"), orderBy("nama", "asc")),
      );
      setDataList(snap.docs.map((d) => ({ id: d.id, ...d.data() })));
    } catch (error) {
      showToast("Gagal memuat data DPD.", "error");
    } finally {
      setIsLoading(false);
      setSelectedIds([]);
    }
  };

  useEffect(() => {
    fetchData();
  }, []);

  const handleFormChange = (e: any) =>
    setForm({ ...form, [e.target.name]: e.target.value });

  const saveData = async (e: React.FormEvent) => {
    e.preventDefault();
    setIsProcessing(true);
    try {
      if (editId) {
        await updateDoc(doc(db, "dpd", editId), {
          ...form,
          updatedAt: new Date().toISOString(),
        });
        showToast("Data DPD diperbarui.", "success");
      } else {
        await addDoc(collection(db, "dpd"), {
          ...form,
          createdAt: new Date().toISOString(),
        });
        showToast("Data DPD baru ditambahkan.", "success");
      }
      setForm({
        nama: "",
        ketua: "",
        status: "Aktif",
        fotoUrl: "",
        fotoPosition: "center",
      });
      setEditId(null);
      await fetchData();
      setView("list");
    } catch (error) {
      showToast("Gagal menyimpan data.", "error");
    } finally {
      setIsProcessing(false);
    }
  };

  const executeDelete = async () => {
    setIsProcessing(true);
    try {
      if (deleteModal.type === "single" && deleteModal.id) {
        await deleteDoc(doc(db, "dpd", deleteModal.id));
      } else if (deleteModal.type === "bulk" && selectedIds.length > 0) {
        await Promise.all(
          selectedIds.map((id) => deleteDoc(doc(db, "dpd", id))),
        );
      }
      showToast("Data berhasil dihapus.", "success");
      await fetchData();
    } catch (error) {
      showToast("Gagal menghapus data.", "error");
    } finally {
      setIsProcessing(false);
      setDeleteModal({ isOpen: false, id: "", title: "", type: "single" });
    }
  };

  const handleExportData = () => {
    if (dataList.length === 0)
      return showToast("Tidak ada data untuk diekspor.", "error");
    const wsData = dataList.map((d, i) => ({
      No: i + 1,
      Nama_Daerah: d.nama,
      Ketua: d.ketua,
      Status: d.status,
      Foto_URL: d.fotoUrl || "",
    }));
    const ws = XLSX.utils.json_to_sheet(wsData);
    const wb = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(wb, ws, "DPD");
    XLSX.writeFile(wb, `Data_DPD_IKA_UII.xlsx`);
  };

  const downloadTemplateExcel = () => {
    const ws = XLSX.utils.json_to_sheet([
      {
        Nama_Daerah: "DPD Kabupaten Sleman",
        Ketua: "Ahmad Dahlan",
        Status: "Aktif",
        Foto_URL: "",
      },
    ]);
    const wb = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(wb, ws, "Template");
    XLSX.writeFile(wb, `Template_Import_DPD.xlsx`);
  };

  const handleImportExcel = async (e: any) => {
    const file = e.target.files[0];
    if (!file) return;
    setIsProcessing(true);
    const reader = new FileReader();
    reader.onload = async (evt: any) => {
      try {
        const bstr = evt.target.result;
        const wb = XLSX.read(bstr, { type: "binary" });
        const data = XLSX.utils.sheet_to_json(wb.Sheets[wb.SheetNames[0]]);
        let count = 0;
        for (const row of data as any[]) {
          if (row.Nama_Daerah) {
            await addDoc(collection(db, "dpd"), {
              nama: row.Nama_Daerah,
              ketua: row.Ketua || "",
              status: row.Status || "Aktif",
              fotoUrl: row.Foto_URL || "",
              createdAt: new Date().toISOString(),
            });
            count++;
          }
        }
        showToast(`${count} Data DPD di-import!`, "success");
        await fetchData();
      } catch (error) {
        showToast("Gagal import Excel.", "error");
      } finally {
        setIsProcessing(false);
        e.target.value = null;
      }
    };
    reader.readAsBinaryString(file);
  };

  return (
    <div className="relative">
      {/* LOCAL TOAST */}
      <div
        className={`fixed top-6 right-6 z-[200] transition-all duration-300 transform ${toast.isOpen ? "translate-y-0 opacity-100" : "-translate-y-4 opacity-0 pointer-events-none"}`}
      >
        <div
          className={`flex items-center gap-3 px-5 py-4 rounded-xl shadow-lg border ${toast.type === "success" ? "bg-white border-emerald-100" : "bg-white border-red-100"}`}
        >
          <div
            className={`flex-shrink-0 w-9 h-9 rounded-full flex items-center justify-center ${toast.type === "success" ? "bg-emerald-100 text-emerald-600" : "bg-red-100 text-red-600"}`}
          >
            {toast.type === "success" ? <IconCheck /> : <IconAlert />}
          </div>
          <div>
            <p className="text-sm font-bold text-slate-800">
              {toast.type === "success" ? "Berhasil!" : "Peringatan!"}
            </p>
            <p className="text-[13px] text-slate-500 mt-0.5">{toast.message}</p>
          </div>
        </div>
      </div>

      {/* DELETE MODAL */}
      {deleteModal.isOpen && (
        <div className="fixed inset-0 z-[150] flex items-center justify-center p-4 bg-slate-900/40 backdrop-blur-sm">
          <div className="bg-white rounded-xl shadow-xl p-6 max-w-sm w-full text-center border border-[#DADCE0]">
            <div className="flex justify-center text-[#D93025] mb-3">
              <IconAlert />
            </div>
            <h3 className="text-lg font-medium mb-1">Hapus Permanen?</h3>
            <p className="text-sm text-[#5F6368] mb-6">
              Yakin menghapus data <strong>"{deleteModal.title}"</strong>?
            </p>
            <div className="flex gap-3 justify-center">
              <button
                onClick={() =>
                  setDeleteModal({
                    isOpen: false,
                    id: "",
                    title: "",
                    type: "single",
                  })
                }
                className="px-4 py-2 border rounded-lg hover:bg-slate-50 w-full"
              >
                Batal
              </button>
              <button
                onClick={executeDelete}
                disabled={isProcessing}
                className="px-4 py-2 text-white bg-[#D93025] hover:bg-[#b52a1f] rounded-lg w-full"
              >
                {isProcessing ? "Proses..." : "Hapus"}
              </button>
            </div>
          </div>
        </div>
      )}

      {view === "list" ? (
        <div className="bg-white rounded-lg border border-[#DADCE0] shadow-sm mb-6 overflow-hidden">
          <div className="p-4 flex flex-col xl:flex-row justify-between items-start xl:items-center gap-4 border-b border-[#DADCE0]">
            <h3 className="font-medium text-[#202124]">Jaringan Wilayah</h3>
            <div className="flex flex-wrap gap-2">
              {selectedIds.length > 0 && (
                <button
                  onClick={() =>
                    setDeleteModal({
                      isOpen: true,
                      type: "bulk",
                      id: "",
                      title: `${selectedIds.length} Data Terpilih`,
                    })
                  }
                  className="text-xs text-[#D93025] border border-[#FCE8E6] hover:bg-[#FCE8E6] px-4 py-2 rounded-lg font-bold"
                >
                  Hapus ({selectedIds.length})
                </button>
              )}
              <button
                onClick={handleExportData}
                className="text-xs font-bold border px-4 py-2.5 rounded-lg hover:bg-slate-50 flex items-center gap-2"
              >
                <IconDownload /> Export
              </button>
              <button
                onClick={downloadTemplateExcel}
                className="text-xs font-bold border px-4 py-2.5 rounded-lg hover:bg-slate-50"
              >
                Template
              </button>
              <label className="cursor-pointer text-xs font-bold bg-[#F8F9FA] border px-4 py-2.5 rounded-lg hover:bg-slate-100 flex items-center gap-2">
                <IconUpload /> Import
                <input
                  type="file"
                  accept=".xlsx, .xls"
                  onChange={handleImportExcel}
                  className="hidden"
                />
              </label>
              <button
                onClick={() => {
                  setView("form");
                  setEditId(null);
                  setForm({
                    nama: "",
                    ketua: "",
                    status: "Aktif",
                    fotoUrl: "",
                    fotoPosition: "center",
                  });
                }}
                className="text-xs bg-[#1A73E8] hover:bg-[#1557B0] text-white px-4 py-2.5 rounded-lg font-bold flex items-center gap-1.5"
              >
                <IconPlus /> Tambah Baru
              </button>
            </div>
          </div>

          <div className="overflow-x-auto min-h-[300px]">
            {isLoading ? (
              <div className="p-10 text-center text-slate-500">
                Memuat data...
              </div>
            ) : (
              <table className="w-full text-left text-sm whitespace-nowrap">
                <thead className="bg-[#F8F9FA] border-b text-slate-500">
                  <tr>
                    <th className="px-4 py-3 w-8 border-r">
                      <input
                        type="checkbox"
                        onChange={(e) =>
                          setSelectedIds(
                            e.target.checked ? dataList.map((d) => d.id) : [],
                          )
                        }
                        checked={
                          dataList.length > 0 &&
                          selectedIds.length === dataList.length
                        }
                        className="rounded"
                      />
                    </th>
                    <th className="px-4 py-3 font-bold text-[11px] uppercase w-12 border-r text-center">
                      No
                    </th>
                    <th className="px-4 py-3 font-bold text-[11px] uppercase">
                      Profil Daerah
                    </th>
                    <th className="px-4 py-3 font-bold text-[11px] uppercase text-right">
                      Aksi
                    </th>
                  </tr>
                </thead>
                <tbody className="divide-y divide-[#DADCE0]">
                  {dataList.length === 0 ? (
                    <tr>
                      <td colSpan={4} className="text-center py-16">
                        <IconEmpty />
                        <p className="text-slate-500">Data DPD Kosong.</p>
                      </td>
                    </tr>
                  ) : (
                    dataList.map((d, i) => (
                      <tr key={d.id} className="hover:bg-[#F8F9FA]">
                        <td className="px-4 py-3 border-r text-center">
                          <input
                            type="checkbox"
                            checked={selectedIds.includes(d.id)}
                            onChange={(e) =>
                              setSelectedIds((prev) =>
                                e.target.checked
                                  ? [...prev, d.id]
                                  : prev.filter((id) => id !== d.id),
                              )
                            }
                            className="rounded"
                          />
                        </td>
                        <td className="px-4 py-3 font-mono text-xs text-slate-400 text-center border-r">
                          {i + 1}
                        </td>
                        <td className="px-4 py-3">
                          <div className="flex items-center gap-4">
                            <img
                              src={d.fotoUrl || "/logo-dpp-ika.png"}
                              alt={d.nama}
                              style={{
                                objectPosition: d.fotoPosition || "center",
                              }}
                              className="w-12 h-12 rounded-full border object-cover bg-white"
                            />
                            <div>
                              <div className="font-medium text-[#202124] text-sm flex items-center gap-2 mb-0.5">
                                {d.nama}{" "}
                                <span
                                  className={`text-[9px] px-1.5 py-0.5 rounded border ${d.status === "Aktif" ? "bg-[#E6F4EA] text-[#1E8E3E]" : "bg-[#FCE8E6] text-[#D93025]"}`}
                                >
                                  {d.status}
                                </span>
                              </div>
                              <div className="text-xs text-[#5F6368]">
                                Ketua: {d.ketua || "-"}
                              </div>
                            </div>
                          </div>
                        </td>
                        <td className="px-4 py-3 text-right">
                          <button
                            onClick={() => {
                              setForm(d);
                              setEditId(d.id);
                              setView("form");
                            }}
                            className="text-[#1A73E8] hover:bg-[#E8F0FE] px-3 py-1.5 rounded-md font-medium transition-colors"
                          >
                            Edit
                          </button>
                        </td>
                      </tr>
                    ))
                  )}
                </tbody>
              </table>
            )}
          </div>
        </div>
      ) : (
        <form
          onSubmit={saveData}
          className="bg-white rounded-lg border border-[#DADCE0] p-6 max-w-md mx-auto shadow-sm"
        >
          <h3 className="font-medium text-lg mb-4">
            {editId ? "Edit DPD" : "Buat DPD Baru"}
          </h3>
          <div className="space-y-4">
            <div>
              <label className="block text-xs font-medium mb-1">
                Nama Daerah
              </label>
              <input
                type="text"
                name="nama"
                value={form.nama}
                onChange={handleFormChange}
                required
                placeholder="Contoh: DPD Kabupaten Sleman"
                className="w-full border px-3 py-2 rounded text-sm outline-none focus:border-[#1A73E8]"
              />
            </div>
            <div>
              <label className="block text-xs font-medium mb-1">
                Ketua DPD
              </label>
              <input
                type="text"
                name="ketua"
                value={form.ketua}
                onChange={handleFormChange}
                className="w-full border px-3 py-2 rounded text-sm outline-none focus:border-[#1A73E8]"
              />
            </div>
            <div>
              <label className="block text-xs font-medium mb-1">
                URL Foto (Opsional)
              </label>
              <input
                type="url"
                name="fotoUrl"
                value={form.fotoUrl}
                onChange={handleFormChange}
                className="w-full border px-3 py-2 rounded text-sm outline-none focus:border-[#1A73E8]"
              />
            </div>
            <div className="grid grid-cols-2 gap-4">
              <div>
                <label className="block text-xs font-medium mb-1">Status</label>
                <select
                  name="status"
                  value={form.status}
                  onChange={handleFormChange}
                  className="w-full border px-3 py-2 rounded text-sm outline-none focus:border-[#1A73E8] bg-white"
                >
                  <option value="Aktif">Aktif</option>
                  <option value="Vakum">Vakum</option>
                </select>
              </div>
              <div>
                <label className="block text-xs font-medium mb-1">
                  Fokus Foto
                </label>
                <select
                  name="fotoPosition"
                  value={form.fotoPosition}
                  onChange={handleFormChange}
                  className="w-full border px-3 py-2 rounded text-sm outline-none focus:border-[#1A73E8] bg-white"
                >
                  <option value="top">Atas</option>
                  <option value="center">Tengah</option>
                  <option value="bottom">Bawah</option>
                </select>
              </div>
            </div>
          </div>
          <div className="flex justify-end gap-3 mt-6 pt-4 border-t">
            <button
              type="button"
              onClick={() => setView("list")}
              className="px-4 py-2 text-sm font-medium border rounded hover:bg-slate-50"
            >
              Batal
            </button>
            <button
              type="submit"
              disabled={isProcessing}
              className="px-4 py-2 text-sm font-medium text-white bg-[#1A73E8] hover:bg-[#1557B0] rounded"
            >
              {isProcessing ? "Menyimpan..." : "Simpan"}
            </button>
          </div>
        </form>
      )}
    </div>
  );
}

"use client";

import { useState, useEffect, useMemo, useRef } from "react";
import { db } from "@/lib/firebase";
import { sendWaAction } from "@/app/actions/wa";
import {
  collection,
  addDoc,
  getDocs,
  getDoc,
  setDoc,
  deleteDoc,
  doc,
  updateDoc,
  query,
  orderBy,
} from "firebase/firestore";
import * as XLSX from "xlsx";
import QRCode from "react-qr-code";
import {
  IconPlus,
  IconDownload,
  IconSearch,
  IconCheck,
  IconAlert,
  IconEmpty,
  IconRefresh,
} from "./Icons";

export default function TabPengurus() {
  const [pengurusList, setPengurusList] = useState<any[]>([]);
  const [periodeList, setPeriodeList] = useState<any[]>([]);
  const [bidangList, setBidangList] = useState<any[]>([]);
  const [dpdList, setDpdList] = useState<any[]>([]);

  const [isLoading, setIsLoading] = useState(true);
  const [isProcessing, setIsProcessing] = useState(false);
  const [isSendingWA, setIsSendingWA] = useState(false);

  const [view, setView] = useState<"list" | "form">("list");
  const [editId, setEditId] = useState<string | null>(null);
  const [selectedIds, setSelectedIds] = useState<string[]>([]); // Untuk centang massal

  // Filter States
  const [search, setSearch] = useState("");
  const [filterBidang, setFilterBidang] = useState("Semua");
  const [filterPeriode, setFilterPeriode] = useState("Semua");
  const [sortMode, setSortMode] = useState("urutan");

  // Modals
  const [toast, setToast] = useState({
    isOpen: false,
    message: "",
    type: "success",
  });
  const [deleteModal, setDeleteModal] = useState({
    isOpen: false,
    id: "",
    title: "",
    type: "single",
  });
  const [detailModal, setDetailModal] = useState({
    isOpen: false,
    data: null as any,
  });
  const [isFlipped, setIsFlipped] = useState(false);

  // Form State
  const [form, setForm] = useState({
    nama: "",
    wa: "",
    email: "",
    jabatan: "Anggota",
    bidang: "",
    linkTTD: "",
    isInti: false,
    fotoUrl: "",
    fotoPosition: "center",
    linkedinUrl: "",
    instagramUrl: "",
    isTampilBeranda: false,
    noUrut: "",
    isPengurus: true,
    status_pengurus: "Aktif",
    nia: "",
    periodeId: "",
    fakultas: "",
    programStudi: "",
    angkatan: "",
    domisili: "",
  });

  const showToast = (
    message: string,
    type: "success" | "error" = "success",
  ) => {
    setToast({ isOpen: true, message, type });
    setTimeout(() => setToast((prev) => ({ ...prev, isOpen: false })), 4000);
  };

  // 🔥 FUNGSI KIRIM WHATSAPP 🔥
  const triggerWaApi = async (
    type: string,
    phone: string,
    nama: string,
    detailData: any = {},
  ) => {
    if (!phone || phone.length < 9) return false;
    try {
      const data = await sendWaAction({
        type,
        phone,
        nama,
        detail: detailData,
      });
      return data.success;
    } catch (error) {
      return false;
    }
  };

  const fetchData = async () => {
    setIsLoading(true);
    try {
      const pSnap = await getDocs(
        query(collection(db, "periode"), orderBy("tglMulai", "desc")),
      );
      const pList = pSnap.docs.map((d) => ({ id: d.id, ...d.data() }));
      setPeriodeList(pList);

      const activePeriode = pList.find((p: any) => p.status === "Aktif");
      if (activePeriode && filterPeriode === "Semua")
        setFilterPeriode(activePeriode.id);

      const bSnap = await getDocs(
        query(collection(db, "bidang"), orderBy("namaBidang", "asc")),
      );
      setBidangList(bSnap.docs.map((d) => ({ id: d.id, ...d.data() })));

      const dSnap = await getDocs(
        query(collection(db, "dpd"), orderBy("nama", "asc")),
      );
      setDpdList(dSnap.docs.map((d) => ({ id: d.id, ...d.data() })));

      const uSnap = await getDocs(
        query(collection(db, "pengurus"), orderBy("createdAt", "desc")),
      );
      const allUsers = uSnap.docs.map((d) => ({ id: d.id, ...d.data() }));
      const sah = allUsers.filter(
        (u: any) =>
          u.isPengurus ||
          u.role === "pengurus" ||
          u.status_pengurus === "Aktif" ||
          u.tampilDiWeb,
      );

      setPengurusList(sah);
    } catch (error) {
      showToast("Gagal memuat data personalia.", "error");
    } finally {
      setIsLoading(false);
      setSelectedIds([]);
    }
  };

  useEffect(() => {
    fetchData();
  }, []);

  const filteredData = useMemo(() => {
    let result = pengurusList;
    if (filterPeriode !== "Semua")
      result = result.filter((p) => p.periodeId === filterPeriode);
    if (filterBidang !== "Semua")
      result = result.filter((p) => p.bidang === filterBidang);
    if (search) {
      const q = search.toLowerCase();
      result = result.filter(
        (p) =>
          p.nama?.toLowerCase().includes(q) ||
          p.jabatan?.toLowerCase().includes(q) ||
          p.bidang?.toLowerCase().includes(q) ||
          p.domisili?.toLowerCase().includes(q),
      );
    }
    result = [...result].sort((a, b) => {
      if (sortMode === "Nama-Asc") {
        return (a.nama || "").localeCompare(b.nama || "");
      } else if (sortMode === "Nama-Desc") {
        return (b.nama || "").localeCompare(a.nama || "");
      } else if (sortMode === "Bidang-Asc") {
        return (a.bidang || "").localeCompare(b.bidang || "");
      } else if (sortMode === "Bidang-Desc") {
        return (b.bidang || "").localeCompare(a.bidang || "");
      }
      
      const urutA =
        a.noUrut !== undefined && a.noUrut !== "" ? Number(a.noUrut) : 99;
      const urutB =
        b.noUrut !== undefined && b.noUrut !== "" ? Number(b.noUrut) : 99;
      if (urutA !== urutB) return urutA - urutB;
      return (a.nama || "").localeCompare(b.nama || "");
    });
    return result;
  }, [search, filterBidang, filterPeriode, sortMode, pengurusList]);

  const handleFormChange = (e: any) => {
    const value =
      e.target.type === "checkbox" ? e.target.checked : e.target.value;
    setForm({ ...form, [e.target.name]: value });
  };

  const saveData = async (e: React.FormEvent) => {
    e.preventDefault();
    setIsProcessing(true);
    try {
      const finalData = {
        ...form,
        noUrut: form.noUrut ? Number(form.noUrut) : 99,
      };
      if (editId) {
        await updateDoc(doc(db, "pengurus", editId), {
          ...finalData,
          updatedAt: new Date().toISOString(),
        });
        showToast("Data Personalia diperbarui.", "success");
      } else {
        await addDoc(collection(db, "pengurus"), {
          ...finalData,
          createdAt: new Date().toISOString(),
        });
        showToast("Data Personalia baru ditambahkan.", "success");
      }
      setEditId(null);
      await fetchData();
      setView("list");
    } catch (error) {
      showToast("Gagal menyimpan data.", "error");
    } finally {
      setIsProcessing(false);
    }
  };

  const cabutPengurus = async (id: string, nama: string) => {
    if (!confirm(`Yakin ingin mencabut status Pengurus dari ${nama}?`)) return;
    setIsProcessing(true);
    try {
      await updateDoc(doc(db, "pengurus", id), {
        isPengurus: false,
        status_pengurus: "Nonaktif",
        role: "anggota",
        isTampilBeranda: false,
        updatedAt: new Date().toISOString(),
      });
      showToast(`Status Pengurus ${nama} dicabut.`, "success");
      await fetchData();
    } catch (error) {
      showToast("Gagal merubah status.", "error");
    } finally {
      setIsProcessing(false);
    }
  };

  const handleRegenerateNIA = async (user: any) => {
    const finalDomisili = user.domisili;
    if (!finalDomisili) {
      showToast("Gagal: Pengurus belum memiliki data Domisili. Silakan Edit terlebih dahulu.", "error");
      return;
    }
    
    if (!confirm(`Apakah Anda yakin ingin meng-generate ulang NIA untuk ${user.nama}? NIA sebelumnya akan diganti dengan yang baru.`)) return;
    
    setIsProcessing(true);
    try {
      const counterRef = doc(db, "pengaturan", "counter_nia");
      const counterSnap = await getDoc(counterRef);
      let newNumber = 89;
      if (counterSnap.exists())
        newNumber = (counterSnap.data().lastNumber || 88) + 1;
      await setDoc(counterRef, { lastNumber: newNumber }, { merge: true });

      const dateObj = new Date();
      const yearStr = dateObj.getFullYear().toString().slice(-2);
      const monthStr = String(dateObj.getMonth() + 1).padStart(2, "0");
      let kabStr = "00";
      const dom = finalDomisili.toLowerCase();
      if (dom.includes("sleman")) kabStr = "04";
      else if (dom.includes("bantul")) kabStr = "02";
      else if (dom.includes("gunung")) kabStr = "03";
      else if (dom.includes("kulon")) kabStr = "01";
      else if (dom.includes("kota") || dom.includes("yogya")) kabStr = "71";

      const urutStr = String(newNumber).padStart(4, "0");
      const finalNIA = `${yearStr}.${monthStr}.34.${kabStr}.${urutStr}`;

      await updateDoc(doc(db, "pengurus", user.id), { nia: finalNIA });
      try {
        await updateDoc(doc(db, "pendaftar", user.id), { nia: finalNIA });
      } catch (e) {}

      showToast(`NIA berhasil di-generate ulang: ${finalNIA}`, "success");
      fetchData();
    } catch (error) {
      console.error(error);
      showToast("Terjadi kesalahan saat me-generate ulang NIA.", "error");
    } finally {
      setIsProcessing(false);
    }
  };

  const executeDelete = async () => {
    setIsProcessing(true);
    try {
      if (deleteModal.type === "single" && deleteModal.id) {
        await deleteDoc(doc(db, "pengurus", deleteModal.id));
      } else if (deleteModal.type === "bulk" && selectedIds.length > 0) {
        await Promise.all(
          selectedIds.map((id) => deleteDoc(doc(db, "pengurus", id))),
        );
      }
      showToast("Data dihapus permanen.", "success");
      await fetchData();
    } catch (error) {
      showToast("Gagal menghapus data.", "error");
    } finally {
      setIsProcessing(false);
      setDeleteModal({ isOpen: false, id: "", title: "", type: "single" });
    }
  };

  const handleExportData = () => {
    if (filteredData.length === 0)
      return showToast("Tidak ada data untuk diekspor.", "error");
    const wsData = filteredData.map((d, i) => ({
      No: i + 1,
      Nama: d.nama,
      WA: d.wa,
      Email: d.email,
      Fakultas: d.fakultas || "-",
      Prodi: d.programStudi || "-",
      Angkatan: d.angkatan || "-",
      Domisili: d.domisili || "-",
      Jabatan: d.jabatan,
      Bidang: d.bidang,
      Nomor_Urut: d.noUrut || 99,
      NIA: d.nia || "Belum Terbit",
      Periode_ID: d.periodeId || "",
    }));
    const ws = XLSX.utils.json_to_sheet(wsData);
    const wb = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(wb, ws, "Pengurus");
    XLSX.writeFile(wb, `Data_PENGURUS_IKA_UII.xlsx`);
  };

  const openDetail = (user: any) => {
    setDetailModal({ isOpen: true, data: user });
    setIsFlipped(false);
  };

  const getSingkatanFakultas = (fakultas: string) => {
    if (!fakultas) return "-";
    const lower = fakultas.toLowerCase();
    if (lower.includes("teknologi industri")) return "FTI";
    if (lower.includes("matematika")) return "FMIPA";
    if (lower.includes("hukum")) return "FH";
    if (lower.includes("ekonomi")) return "FE/FBE";
    if (lower.includes("kedokteran")) return "FK";
    if (lower.includes("psikologi")) return "FPSB";
    if (lower.includes("sipil")) return "FTSP";
    if (lower.includes("agama")) return "FIAI";
    return fakultas;
  };

  // 🔥 FUNGSI CENTANG MASSAL 🔥
  const toggleSelectAll = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.checked) {
      setSelectedIds(filteredData.map((d) => d.id));
    } else {
      setSelectedIds([]);
    }
  };

  const toggleSelect = (id: string) => {
    setSelectedIds((prev) =>
      prev.includes(id) ? prev.filter((i) => i !== id) : [...prev, id],
    );
  };

  return (
    <div className="relative">
      {/* LOCAL TOAST */}
      <div
        className={`fixed top-6 right-6 z-[200] transition-all duration-300 transform ${toast.isOpen ? "translate-y-0 opacity-100" : "-translate-y-4 opacity-0 pointer-events-none"}`}
      >
        <div
          className={`flex items-center gap-3 px-5 py-4 rounded-xl shadow-lg border ${toast.type === "success" ? "bg-white border-emerald-100" : "bg-white border-red-100"}`}
        >
          <div
            className={`flex-shrink-0 w-9 h-9 rounded-full flex items-center justify-center ${toast.type === "success" ? "bg-emerald-100 text-emerald-600" : "bg-red-100 text-red-600"}`}
          >
            {toast.type === "success" ? <IconCheck /> : <IconAlert />}
          </div>
          <div>
            <p className="text-sm font-bold text-slate-800">
              {toast.type === "success" ? "Berhasil!" : "Peringatan!"}
            </p>
            <p className="text-[13px] text-slate-500 mt-0.5">{toast.message}</p>
          </div>
        </div>
      </div>

      {/* MODAL PREVIEW KTA & KIRIM WHATSAPP */}
      {detailModal.isOpen && detailModal.data && (
        <div className="fixed inset-0 z-[150] flex items-center justify-center p-4 bg-slate-900/60 backdrop-blur-sm">
          <div className="flex flex-col items-center w-full max-w-sm">
            {/* Logic Ambil Tahun Periode */}
            {(() => {
              const pData = periodeList.find(
                (p) => p.id === detailModal.data.periodeId,
              );
              const startYear = pData?.tglMulai
                ? new Date(pData.tglMulai).getFullYear()
                : "";
              const endYear = pData?.tglSelesai
                ? new Date(pData.tglSelesai).getFullYear()
                : "";
              const displayPeriodeTahun =
                startYear && endYear ? `${startYear} - ${endYear}` : "";

              return (
                <div
                  className="relative w-full max-w-[280px] aspect-[380/600] mx-auto"
                  style={{ perspective: "1000px" }}
                >
                  <div
                    className="relative w-full h-full transition-transform duration-700 cursor-pointer shadow-[0_10px_30px_rgba(0,0,0,0.15)] rounded-[16px] border border-[#DADCE0]"
                    style={{
                      transform: isFlipped
                        ? "rotateY(180deg)"
                        : "rotateY(0deg)",
                      transformStyle: "preserve-3d",
                    }}
                    onClick={() => setIsFlipped(!isFlipped)}
                  >
                    {/* DEPAN */}
                    <div
                      className="absolute inset-0 bg-white rounded-[16px] overflow-hidden flex flex-col"
                      style={{
                        backfaceVisibility: "hidden",
                        WebkitBackfaceVisibility: "hidden",
                      }}
                    >
                      <img
                        src="/logo-dpp-ika.png"
                        className="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 w-40 h-40 opacity-[0.04] grayscale pointer-events-none z-0"
                      />
                      <div className="relative pt-6 pb-4 w-full shrink-0 z-10 bg-[#0B1528] flex flex-col items-center justify-center">
                        <div className="absolute bottom-0 left-0 right-0 h-3 bg-[#224A9A]"></div>
                        <div className="flex flex-col z-10 px-4 text-center">
                          <h1 className="text-white font-black text-[14px] tracking-widest uppercase mb-1 mt-2">
                            KARTU TANDA{" "}
                            {detailModal.data.isPengurus
                              ? "PENGURUS"
                              : "ANGGOTA"}
                          </h1>
                          <h2 className="text-[#F29900] font-bold text-[8px] tracking-[0.2em] uppercase">
                            DPW IKA UII D.I.YOGYAKARTA
                          </h2>
                        </div>
                      </div>
                      <div className="h-[4px] w-full bg-[#F29900] shrink-0 z-10 relative"></div>

                      <div className="flex-grow flex flex-col items-center px-4 py-5 relative z-10 text-center">
                        <div className="w-[90px] h-[115px] bg-[#F8F9FA] rounded-lg border-[3px] border-white shadow-md overflow-hidden shrink-0 mb-3">
                          {detailModal.data.fotoUrl ? (
                            <img
                              src={detailModal.data.fotoUrl}
                              className="w-full h-full object-cover"
                              style={{
                                objectPosition:
                                  detailModal.data.fotoPosition || "center",
                              }}
                            />
                          ) : (
                            <div className="w-full h-full flex items-center justify-center text-[#9AA0A6] text-[10px]">
                              Tanpa Foto
                            </div>
                          )}
                        </div>

                        <div className="w-full space-y-2">
                          <div>
                            <p className="text-[15px] font-black text-[#0B1528] uppercase line-clamp-2 px-2 leading-tight">
                              {detailModal.data.nama}
                            </p>
                          </div>

                          <div>
                            <p className="text-[8px] font-bold text-[#9AA0A6] uppercase tracking-widest mb-0.5">
                              Nomor Induk{" "}
                              {detailModal.data.isPengurus
                                ? "Pengurus"
                                : "Anggota"}
                            </p>
                            <p className="text-[12px] font-bold text-[#0B1528] tracking-widest font-mono bg-[#F8F9FA] inline-block px-3 py-1 rounded border border-[#EBEBEB]">
                              {detailModal.data.nia || "BELUM TERBIT"}
                            </p>
                          </div>

                          <div>
                            <p className="text-[8px] font-bold text-[#9AA0A6] uppercase tracking-widest mb-0.5">
                              Program Studi / Angkatan
                            </p>
                            <p className="text-[10px] font-black text-[#224A9A] uppercase leading-tight">
                              {getSingkatanFakultas(detailModal.data.fakultas)}{" "}
                              / {detailModal.data.programStudi || "-"} /{" "}
                              {detailModal.data.angkatan || "-"}
                            </p>

                            {displayPeriodeTahun && (
                              <p className="text-[9px] font-bold text-slate-500 uppercase tracking-widest mt-1">
                                Periode {displayPeriodeTahun}
                              </p>
                            )}

                            <div className="mt-2.5">
                              <span className="inline-block text-[9px] font-bold text-white bg-[#0B1528] px-2.5 py-0.5 rounded-sm uppercase tracking-wider shadow-sm">
                                {detailModal.data.jabatan ===
                                "Koordinator Bidang"
                                  ? `Koordinator ${detailModal.data.bidang}`
                                  : detailModal.data.jabatan === "Anggota"
                                    ? `Anggota ${detailModal.data.bidang}`
                                    : detailModal.data.jabatan}
                              </span>
                            </div>
                          </div>
                        </div>
                      </div>

                      <div className="pt-2.5 pb-3 bg-[#F8FAFC] border-t border-[#EBEBEB] shrink-0 z-10 relative flex items-center justify-center">
                        <p className="text-[10px] font-black tracking-[0.2em] uppercase flex items-center gap-0.5">
                          <span className="text-[#0B1528]">IKADIY.</span>
                          <span className="text-[#224A9A]">UII</span>
                          <span className="text-[#0B1528]">.AC.ID</span>
                        </p>
                      </div>
                    </div>

                    {/* BELAKANG */}
                    <div
                      className="absolute inset-0 bg-white rounded-[16px] overflow-hidden flex flex-col"
                      style={{
                        backfaceVisibility: "hidden",
                        WebkitBackfaceVisibility: "hidden",
                        transform: "rotateY(180deg)",
                      }}
                    >
                      <div className="h-[18px] bg-[#0B1528] w-full shrink-0 z-10 flex">
                        <div className="w-[70%] bg-[#0B1528] h-full"></div>
                        <div
                          className="w-[30%] bg-[#224A9A] h-full"
                          style={{
                            clipPath:
                              "polygon(15% 0, 100% 0, 100% 100%, 0% 100%)",
                          }}
                        ></div>
                      </div>
                      <div className="h-[4px] bg-[#F29900] w-full shrink-0 z-10"></div>
                      <div className="flex-grow flex flex-col px-6 py-6 items-center z-10 relative">
                        <h3 className="text-[12px] font-black text-[#0B1528] uppercase tracking-widest mb-5 border-b-2 pb-1.5 text-center w-full border-[#EBEBEB]">
                          Ketentuan Penggunaan
                        </h3>
                        <ol className="text-[9px] text-[#5F6368] space-y-3 pl-3 list-decimal leading-relaxed text-justify w-full mb-auto font-medium">
                          <li>
                            Kartu ini diterbitkan oleh DPW IKA UII Yogyakarta
                            dan merupakan bukti keanggotaan yang sah.
                          </li>
                          <li>
                            Kartu tidak dapat dipindahtangankan dan wajib
                            ditunjukkan untuk mengakses layanan, acara, atau
                            klaim potongan harga pada mitra jaringan bisnis IKA
                            UII DIY.
                          </li>
                          <li>
                            Apabila menemukan kartu ini, harap dikembalikan
                            kepada Sekretariat DPW IKA UII DIY melalui email:
                            ika.diy@uii.ac.id.
                          </li>
                        </ol>
                        <div className="flex flex-col items-center w-full mt-6 pt-6 border-t border-[#EBEBEB]">
                          <div className="w-[100px] h-[100px] p-2 bg-white border border-[#DADCE0] rounded-xl shadow-sm mb-2.5">
                            <QRCode
                              value={`https://ikadiy.uii.ac.id/kta/${detailModal.data.id}`}
                              size={96}
                              style={{ width: "100%", height: "100%" }}
                            />
                          </div>
                          <p className="text-[9px] font-black text-[#0B1528] tracking-widest uppercase bg-[#F8F9FA] px-2 py-0.5 rounded border border-[#EBEBEB]">
                            Scan Validasi
                          </p>
                        </div>
                      </div>
                    </div>
                  </div>
                </div>
              );
            })()}

            {/* INFORMASI WHATSAPP & TOMBOL KIRIM */}
            <div className="w-full max-w-[280px] mt-4 bg-white rounded-xl p-3 shadow-md border border-[#DADCE0]">
              {(() => {
                const isComplete = Boolean(
                  detailModal.data.fotoUrl && detailModal.data.domisili
                );
                return (
                  <>
                    {!isComplete && (
                      <div className="mb-3 p-2 bg-amber-50 border border-amber-200 rounded text-center">
                        <span className="text-[10px] text-amber-700 font-bold flex items-center justify-center gap-1">
                          <IconAlert /> Profil Belum Lengkap!
                        </span>
                        <p className="text-[9px] text-amber-600 mt-1">
                          Pesan WA akan berisi "Magic Link" agar anggota melengkapi datanya.
                        </p>
                      </div>
                    )}
                    <p className="text-[11px] text-slate-500 font-medium text-center mb-2">
                      Kirim akses KTA ini melalui WhatsApp ke nomor:
                    </p>
              <div className="flex items-center justify-center gap-2 mb-3 bg-slate-50 py-1.5 rounded-lg border border-slate-100">
                <svg
                  className="w-4 h-4 text-emerald-600"
                  fill="currentColor"
                  viewBox="0 0 24 24"
                >
                  <path d="M17.472 14.382c-.297-.149-1.758-.867-2.03-.967-.273-.099-.471-.148-.67.15-.197.297-.767.966-.94 1.164-.173.199-.347.223-.644.075-.297-.15-1.255-.463-2.39-1.452-.885-.773-1.482-1.728-1.655-2.026-.173-.297-.018-.458.13-.606.134-.133.298-.347.446-.52.149-.174.198-.298.298-.497.099-.198.05-.371-.025-.52-.075-.149-.669-1.612-.916-2.207-.242-.579-.487-.5-.669-.51h-.57c-.198 0-.52.074-.792.372-.272.297-1.04 1.016-1.04 2.479 0 1.462 1.065 2.875 1.213 3.074.149.198 2.096 3.2 5.077 4.487.709.306 1.262.489 1.694.625.712.227 1.36.195 1.871.118.571-.085 1.758-.719 2.006-1.413.248-.694.248-1.289.173-1.413-.074-.124-.272-.198-.57-.347m-5.421 7.403h-.004a9.87 9.87 0 01-5.031-1.378l-.361-.214-3.741.982.998-3.648-.235-.374a9.86 9.86 0 01-1.51-5.26c.001-5.45 4.436-9.884 9.888-9.884 2.64 0 5.122 1.03 6.988 2.898a9.825 9.825 0 012.893 6.994c-.003 5.45-4.437 9.884-9.885 9.884m8.413-18.297A11.815 11.815 0 0012.05 0C5.495 0 .16 5.335.157 11.892c0 2.096.547 4.142 1.588 5.945L.057 24l6.305-1.654a11.882 11.882 0 005.683 1.448h.005c6.554 0 11.89-5.335 11.893-11.893a11.821 11.821 0 00-3.48-8.413z" />
                </svg>
                <span className="text-[13px] font-bold text-slate-800 tracking-wider font-mono">
                  {detailModal.data.wa
                    ? detailModal.data.wa
                    : "Tidak Ada Nomor"}
                </span>
              </div>

              <div className="flex gap-2">
                <button
                  onClick={() => setDetailModal({ isOpen: false, data: null })}
                  className="flex-1 bg-white text-[#5F6368] font-medium text-xs py-2 rounded-lg border border-[#DADCE0] hover:bg-slate-50 transition-colors"
                >
                  Batal
                </button>
                <button
                  disabled={isSendingWA || !detailModal.data.wa}
                  onClick={async () => {
                    setIsSendingWA(true);
                    const isComplete = Boolean(
                      detailModal.data.fotoUrl && detailModal.data.domisili
                    );
                    const success = await triggerWaApi(
                      "send_kta",
                      detailModal.data.wa,
                      detailModal.data.nama,
                      { userId: detailModal.data.id, isComplete },
                    );
                    setIsSendingWA(false);
                    if (success) {
                      showToast(
                        "Link E-KTA berhasil dikirim via WA!",
                        "success",
                      );
                      setDetailModal({ isOpen: false, data: null });
                    } else {
                      showToast("Gagal mengirim pesan WA.", "error");
                    }
                  }}
                  className={`flex-[2] text-white text-xs font-bold py-2 rounded-lg shadow-sm transition-all flex items-center justify-center gap-1.5 ${
                    Boolean(detailModal.data.fotoUrl && detailModal.data.domisili)
                      ? "bg-[#1E8E3E] hover:bg-[#156E2F]"
                      : "bg-amber-500 hover:bg-amber-600"
                  } disabled:opacity-50`}
                >
                  {isSendingWA
                    ? "Mengirim..."
                    : Boolean(detailModal.data.fotoUrl && detailModal.data.domisili)
                      ? "Kirim KTA (Selesai)"
                      : "Kirim Magic Link WA"}
                </button>
              </div>
              </>
            );
          })()}
            </div>
          </div>
        </div>
      )}

      {/* VIEW UTAMA */}
      {view === "list" ? (
        <div className="bg-white rounded-xl border border-[#DADCE0] shadow-sm overflow-hidden flex flex-col">
          <div className="p-5 border-b border-[#DADCE0] flex flex-col gap-5">
            <div className="flex flex-col md:flex-row justify-between items-start md:items-center">
              <div>
                <h3 className="font-bold text-[#202124] text-[18px]">
                  Database Personalia Sah
                </h3>
                <p className="text-[12px] text-slate-500 mt-0.5">
                  Daftar pengurus dan anggota yang memiliki akses ke E-KTA.
                </p>
              </div>
              <div className="flex gap-2 w-full md:w-auto mt-3 md:mt-0">
                <button
                  onClick={handleExportData}
                  className="w-full md:w-auto text-xs font-bold border border-[#DADCE0] text-slate-600 px-4 py-2 rounded-lg hover:bg-slate-50 flex items-center justify-center gap-2 transition-colors"
                >
                  <IconDownload /> Export Excel
                </button>
                <button
                  onClick={() => {
                    setForm({
                      nama: "",
                      wa: "",
                      email: "",
                      jabatan: "Anggota",
                      bidang: bidangList[0]?.namaBidang || "",
                      linkTTD: "",
                      isInti: false,
                      fotoUrl: "",
                      fotoPosition: "center",
                      linkedinUrl: "",
                      instagramUrl: "",
                      isTampilBeranda: false,
                      noUrut: "",
                      isPengurus: true,
                      status_pengurus: "Aktif",
                      nia: "",
                      periodeId: filterPeriode !== "Semua" ? filterPeriode : "",
                      fakultas: "",
                      programStudi: "",
                      angkatan: "",
                      domisili: "",
                    });
                    setEditId(null);
                    setView("form");
                  }}
                  className="w-full md:w-auto text-xs bg-[#1A73E8] text-white px-4 py-2 rounded-lg font-bold flex items-center justify-center gap-2 hover:bg-[#1557B0] transition-colors shadow-sm"
                >
                  <IconPlus /> Tambah Data
                </button>
              </div>
            </div>

            <div className="flex flex-col md:flex-row items-center gap-3 w-full bg-[#F8F9FA] p-3 rounded-lg border border-[#EBEBEB]">
              <div className="relative w-full md:w-auto flex-1">
                <div className="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none">
                  <IconSearch />
                </div>
                <input
                  type="text"
                  placeholder="Cari nama, jabatan, domisili..."
                  value={search}
                  onChange={(e) => setSearch(e.target.value)}
                  className="w-full pl-9 pr-4 py-2.5 border border-[#DADCE0] rounded-lg text-sm bg-white outline-none focus:border-[#1A73E8] transition-colors shadow-sm"
                />
              </div>
              <div className="flex gap-2 w-full md:w-auto">
                <select
                  value={filterPeriode}
                  onChange={(e) => setFilterPeriode(e.target.value)}
                  className="w-full md:w-auto bg-[#E8F0FE] border border-[#1A73E8]/20 text-[#1A73E8] py-2.5 px-3 rounded-lg text-xs font-bold outline-none cursor-pointer"
                >
                  <option value="Semua">Semua Periode</option>
                  {periodeList.map((p) => (
                    <option key={p.id} value={p.id}>
                      {p.namaPeriode}
                    </option>
                  ))}
                </select>
                <select
                  value={filterBidang}
                  onChange={(e) => setFilterBidang(e.target.value)}
                  className="w-full md:w-auto bg-white border border-[#DADCE0] text-slate-700 py-2.5 px-3 rounded-lg text-xs font-bold outline-none cursor-pointer shadow-sm"
                >
                  <option value="Semua">Semua Bidang</option>
                  {bidangList.map((b) => (
                    <option key={b.id} value={b.namaBidang}>
                      {b.namaBidang}
                    </option>
                  ))}
                </select>
              </div>
            </div>
          </div>

          <div className="overflow-x-auto min-h-[400px]">
            {isLoading ? (
              <div className="p-10 text-center text-slate-500 flex flex-col items-center">
                <div className="animate-spin w-8 h-8 border-4 border-[#E8F0FE] border-t-[#1A73E8] rounded-full mb-3"></div>
                Memuat data personalia...
              </div>
            ) : (
              <table className="w-full text-left text-sm whitespace-nowrap">
                <thead className="bg-[#F8F9FA] border-b border-[#DADCE0] text-slate-500 sticky top-0">
                  <tr>
                    {/* CHECKBOX MASSAL */}
                    <th className="px-4 py-4 w-10 text-center border-r border-slate-200">
                      <input
                        type="checkbox"
                        className="w-4 h-4 rounded text-[#1A73E8] cursor-pointer"
                        onChange={toggleSelectAll}
                        checked={
                          selectedIds.length === filteredData.length &&
                          filteredData.length > 0
                        }
                      />
                    </th>
                    <th 
                      className="px-4 py-4 font-bold text-[11px] uppercase tracking-wider cursor-pointer hover:bg-slate-200 transition-colors group"
                      onClick={() => setSortMode(sortMode === "Nama-Asc" ? "Nama-Desc" : "Nama-Asc")}
                    >
                      <div className="flex items-center gap-1">
                        Identitas Profil
                        <span className="text-slate-400 group-hover:text-slate-600">
                          {sortMode === "Nama-Asc" ? "↑" : sortMode === "Nama-Desc" ? "↓" : "↕"}
                        </span>
                      </div>
                    </th>
                    <th 
                      className="px-4 py-4 font-bold text-[11px] uppercase tracking-wider cursor-pointer hover:bg-slate-200 transition-colors group"
                      onClick={() => setSortMode(sortMode === "Bidang-Asc" ? "Bidang-Desc" : "Bidang-Asc")}
                    >
                      <div className="flex items-center gap-1">
                        Penempatan & Domisili
                        <span className="text-slate-400 group-hover:text-slate-600">
                          {sortMode === "Bidang-Asc" ? "↑" : sortMode === "Bidang-Desc" ? "↓" : "↕"}
                        </span>
                      </div>
                    </th>
                    <th className="px-4 py-4 font-bold text-[11px] uppercase tracking-wider">
                      Status KTA
                    </th>
                    <th className="px-4 py-4 font-bold text-[11px] uppercase tracking-wider text-right">
                      Manajemen
                    </th>
                  </tr>
                </thead>
                <tbody className="divide-y divide-[#EBEBEB]">
                  {filteredData.length === 0 ? (
                    <tr>
                      <td colSpan={5} className="text-center py-16">
                        <IconEmpty />
                        <p className="text-slate-500 font-medium">
                          Personalia tidak ditemukan.
                        </p>
                      </td>
                    </tr>
                  ) : (
                    filteredData.map((p, i) => (
                      <tr
                        key={p.id}
                        className={`transition-colors ${selectedIds.includes(p.id) ? "bg-[#E8F0FE]" : "hover:bg-[#F8F9FA]"}`}
                      >
                        <td className="px-4 py-4 text-center border-r border-slate-200">
                          <input
                            type="checkbox"
                            className="w-4 h-4 rounded text-[#1A73E8] cursor-pointer"
                            checked={selectedIds.includes(p.id)}
                            onChange={() => toggleSelect(p.id)}
                          />
                        </td>
                        <td className="px-4 py-4">
                          <div className="flex items-center gap-3">
                            <img
                              src={p.fotoUrl || "/logo-dpp-ika.png"}
                              className="w-11 h-11 rounded-full border border-[#DADCE0] object-cover bg-white shadow-sm"
                              style={{
                                objectPosition: p.fotoPosition || "center",
                              }}
                            />
                            <div>
                              <div className="font-bold text-[#202124] text-[13px] mb-1">
                                {p.nama}{" "}
                                {p.noUrut && p.noUrut !== 99 && (
                                  <span className="text-[9px] bg-slate-100 text-slate-500 border border-slate-200 px-1.5 py-0.5 ml-1 rounded font-mono">
                                    Urut: {p.noUrut}
                                  </span>
                                )}
                              </div>
                              <div className="text-[11px] font-mono text-slate-500 bg-slate-50 px-2 py-0.5 rounded border border-slate-100 w-fit">
                                NIA:{" "}
                                <strong className="text-[#1E8E3E]">
                                  {p.nia || "Belum Terbit"}
                                </strong>
                              </div>
                            </div>
                          </div>
                        </td>
                        <td className="px-4 py-4">
                          <div className="text-[13px] font-bold text-[#202124] mb-1.5">
                            {p.bidang}
                          </div>
                          <div className="flex gap-1.5">
                            <span className="text-[9px] text-[#1A73E8] bg-[#E8F0FE] px-2 py-0.5 rounded border border-[#D2E3FC] font-bold uppercase tracking-wider">
                              {p.jabatan}
                            </span>
                            {p.domisili && (
                              <span className="text-[9px] text-slate-600 bg-slate-100 px-2 py-0.5 rounded border border-slate-200 font-bold uppercase tracking-wider">
                                {p.domisili}
                              </span>
                            )}
                          </div>
                        </td>

                        {/* 🔥 STATUS KTA 🔥 */}
                        <td className="px-4 py-4">
                          <div className="flex flex-col gap-1.5">
                            <span className="inline-flex items-center gap-1 text-[10px] font-bold text-[#1E8E3E] bg-[#E6F4EA] w-fit px-2 py-0.5 rounded-md border border-[#CEEAD6]">
                              <IconCheck /> Terverifikasi
                            </span>
                            {p.wa && p.wa.length > 8 ? (
                              <span className="text-[10px] text-emerald-600 font-medium">
                                Whatsapp Terdaftar
                              </span>
                            ) : (
                              <span className="text-[10px] text-red-500 font-medium">
                                Whatsapp Belum Terdaftar
                              </span>
                            )}
                          </div>
                        </td>

                        <td className="px-4 py-4 text-right">
                          <div className="flex justify-end gap-2">
                            <button
                              onClick={() => handleRegenerateNIA(p)}
                              className="border border-amber-200 bg-amber-50 text-amber-600 p-1.5 rounded-md hover:bg-amber-100 shadow-sm transition-colors"
                              title="Reset & Generate Ulang NIA"
                            >
                              <IconRefresh />
                            </button>
                            <button
                              onClick={() => openDetail(p)}
                              className="border border-[#1A73E8] text-[#1A73E8] bg-white px-3 py-1.5 rounded-md text-xs font-bold hover:bg-[#E8F0FE] shadow-sm transition-colors flex items-center gap-1"
                            >
                              Kirim KTA
                            </button>
                            <button
                              onClick={() => cabutPengurus(p.id, p.nama)}
                              className="border border-red-200 text-red-600 px-3 py-1.5 rounded-md text-xs font-bold hover:bg-red-50 shadow-sm transition-colors"
                            >
                              Cabut
                            </button>
                            <button
                              onClick={() => {
                                setForm({
                                  ...p,
                                  fotoPosition: p.fotoPosition || "center",
                                });
                                setEditId(p.id);
                                setView("form");
                              }}
                              className="bg-[#1A73E8] text-white px-4 py-1.5 rounded-md text-xs font-bold hover:bg-[#1557B0] shadow-sm transition-colors"
                            >
                              Edit
                            </button>
                          </div>
                        </td>
                      </tr>
                    ))
                  )}
                </tbody>
              </table>
            )}
          </div>

          {/* OPSI MASSAL (MUNCUL JIKA ADA YANG DICENTANG) */}
          {selectedIds.length > 0 && (
            <div className="bg-slate-50 border-t border-[#DADCE0] p-4 flex items-center justify-between animate-in slide-in-from-bottom-2">
              <p className="text-sm font-bold text-[#202124]">
                {selectedIds.length} Data Terpilih
              </p>
              <div className="flex gap-3">
                <button
                  onClick={() => {
                    if (
                      confirm(
                        `Yakin ingin MENGHAPUS PERMANEN ${selectedIds.length} data ini?`,
                      )
                    ) {
                      setDeleteModal({
                        isOpen: true,
                        id: "",
                        title: "Hapus Massal",
                        type: "bulk",
                      });
                      executeDelete(); // Note: ini trigger langsung, pastikan aman.
                    }
                  }}
                  className="bg-white border border-red-200 text-red-600 hover:bg-red-50 text-xs font-bold px-4 py-2 rounded-lg transition-colors shadow-sm"
                >
                  Hapus Terpilih
                </button>
              </div>
            </div>
          )}
        </div>
      ) : (
        <form
          onSubmit={saveData}
          className="bg-white rounded-xl border border-[#DADCE0] p-6 sm:p-8 max-w-4xl mx-auto shadow-sm"
        >
          <div className="flex justify-between items-center mb-6 border-b border-[#EBEBEB] pb-4">
            <h3 className="font-bold text-xl text-[#202124]">
              {editId ? "Ubah Data Personalia" : "Tambah Personalia Baru"}
            </h3>
            <button
              type="button"
              onClick={() => setView("list")}
              className="text-sm font-bold text-slate-500 hover:text-slate-800 transition-colors"
            >
              Kembali
            </button>
          </div>

          <div className="space-y-6">
            {/* IDENTITAS UTAMA */}
            <div className="bg-[#F8F9FA] p-5 rounded-xl border border-[#DADCE0] space-y-4">
              <h4 className="text-xs font-black text-slate-500 uppercase tracking-widest border-b border-[#DADCE0] pb-2">
                Informasi Kontak & Diri
              </h4>
              <div className="grid sm:grid-cols-2 gap-5">
                <div className="sm:col-span-2">
                  <label className="block text-xs font-bold mb-1.5 text-[#202124]">
                    Nama Lengkap (Sesuai KTA)
                  </label>
                  <input
                    type="text"
                    name="nama"
                    value={form.nama}
                    onChange={handleFormChange}
                    required
                    className="w-full border border-[#DADCE0] px-4 py-2.5 rounded-lg text-sm outline-none focus:border-[#1A73E8] focus:ring-1 focus:ring-[#1A73E8] transition-all"
                  />
                </div>
                <div>
                  <label className="block text-xs font-bold mb-1.5 text-[#202124]">
                    No. WhatsApp (Aktif)
                  </label>
                  <input
                    type="text"
                    name="wa"
                    value={form.wa}
                    onChange={handleFormChange}
                    placeholder="Contoh: 08123456789"
                    className="w-full border border-[#DADCE0] px-4 py-2.5 rounded-lg text-sm font-mono outline-none focus:border-[#1A73E8] focus:ring-1 focus:ring-[#1A73E8] transition-all"
                  />
                </div>
                <div>
                  <label className="block text-xs font-bold mb-1.5 text-[#202124]">
                    Alamat Email
                  </label>
                  <input
                    type="email"
                    name="email"
                    value={form.email}
                    onChange={handleFormChange}
                    className="w-full border border-[#DADCE0] px-4 py-2.5 rounded-lg text-sm font-mono outline-none focus:border-[#1A73E8] focus:ring-1 focus:ring-[#1A73E8] transition-all"
                  />
                </div>
              </div>
            </div>

            {/* DATA ALUMNI */}
            <div className="bg-[#E8F0FE]/50 p-5 rounded-xl border border-[#D2E3FC] space-y-4">
              <h4 className="text-xs font-black text-[#1A73E8] uppercase tracking-widest border-b border-[#D2E3FC] pb-2">
                Data Identitas Alumni UII
              </h4>
              <div className="grid sm:grid-cols-3 gap-5">
                <div>
                  <label className="block text-xs font-bold mb-1.5 text-[#202124]">
                    Fakultas
                  </label>
                  <input
                    type="text"
                    name="fakultas"
                    placeholder="Contoh: Teknologi Industri"
                    value={form.fakultas}
                    onChange={handleFormChange}
                    className="w-full border border-[#DADCE0] px-4 py-2.5 rounded-lg text-sm outline-none focus:border-[#1A73E8] transition-all"
                  />
                </div>
                <div>
                  <label className="block text-xs font-bold mb-1.5 text-[#202124]">
                    Program Studi
                  </label>
                  <input
                    type="text"
                    name="programStudi"
                    placeholder="Contoh: Teknik Mesin"
                    value={form.programStudi}
                    onChange={handleFormChange}
                    className="w-full border border-[#DADCE0] px-4 py-2.5 rounded-lg text-sm outline-none focus:border-[#1A73E8] transition-all"
                  />
                </div>
                <div>
                  <label className="block text-xs font-bold mb-1.5 text-[#202124]">
                    Angkatan
                  </label>
                  <input
                    type="text"
                    name="angkatan"
                    placeholder="Contoh: 2005"
                    value={form.angkatan}
                    onChange={handleFormChange}
                    className="w-full border border-[#DADCE0] px-4 py-2.5 rounded-lg text-sm outline-none focus:border-[#1A73E8] transition-all"
                  />
                </div>
              </div>
            </div>

            {/* JABATAN & PENEMPATAN */}
            <div className="bg-white p-5 rounded-xl border border-[#DADCE0] space-y-4">
              <h4 className="text-xs font-black text-slate-500 uppercase tracking-widest border-b border-[#DADCE0] pb-2">
                Struktur Organisasi (SK)
              </h4>
              <div className="grid sm:grid-cols-3 gap-5">
                <div className="sm:col-span-3">
                  <label className="block text-xs font-bold mb-1.5 text-[#1A73E8]">
                    Periode Aktif Kepengurusan
                  </label>
                  <select
                    name="periodeId"
                    value={form.periodeId}
                    onChange={handleFormChange}
                    required
                    className="w-full border-2 border-[#1A73E8] bg-[#E8F0FE] text-[#1A73E8] px-4 py-2.5 rounded-lg text-sm font-bold outline-none cursor-pointer"
                  >
                    <option value="" disabled>
                      -- Tetapkan Periode --
                    </option>
                    {periodeList.map((p) => (
                      <option key={p.id} value={p.id}>
                        {p.namaPeriode}{" "}
                        {p.status === "Aktif" ? "(Aktif Saat Ini)" : ""}
                      </option>
                    ))}
                  </select>
                </div>
                <div className="sm:col-span-1">
                  <label className="block text-xs font-bold mb-1.5 text-[#202124]">
                    Titel Jabatan
                  </label>
                  <select
                    name="jabatan"
                    value={form.jabatan}
                    onChange={handleFormChange}
                    className="w-full border border-[#DADCE0] px-4 py-2.5 rounded-lg text-sm outline-none focus:border-[#1A73E8] transition-all bg-white"
                  >
                    <option value="Ketua Umum">Ketua Umum</option>
                    <option value="Ketua">Ketua</option>
                    <option value="Wakil Ketua Umum">Wakil Ketua Umum</option>
                    <option value="Wakil Ketua">Wakil Ketua</option>
                    <option value="Sekretaris Wilayah">
                      Sekretaris Wilayah
                    </option>
                    <option value="Wakil Sekretaris">Wakil Sekretaris</option>
                    <option value="Bendahara Umum">Bendahara Umum</option>
                    <option value="Wakil Bendahara">Wakil Bendahara</option>
                    <option value="Koordinator Bidang">
                      Koordinator Bidang
                    </option>
                    <option value="Anggota">Anggota Bidang</option>
                  </select>
                </div>
                <div className="sm:col-span-1">
                  <label className="block text-xs font-bold mb-1.5 text-[#202124]">
                    Bidang Penempatan
                  </label>
                  <select
                    name="bidang"
                    value={form.bidang}
                    onChange={handleFormChange}
                    className="w-full border border-[#DADCE0] px-4 py-2.5 rounded-lg text-sm outline-none focus:border-[#1A73E8] transition-all bg-white"
                  >
                    <option value="">-- Non-Bidang --</option>
                    {bidangList.map((b) => (
                      <option key={b.id} value={b.namaBidang}>
                        {b.namaBidang}
                      </option>
                    ))}
                  </select>
                </div>
                <div className="sm:col-span-1">
                  <label className="block text-xs font-bold mb-1.5 text-[#202124]">
                    Asal Wilayah (DPD)
                  </label>
                  <select
                    name="domisili"
                    value={form.domisili}
                    onChange={handleFormChange}
                    className="w-full border border-[#DADCE0] px-4 py-2.5 rounded-lg text-sm outline-none focus:border-[#1A73E8] transition-all bg-white"
                  >
                    <option value="">-- DPW (Pusat) --</option>
                    {dpdList.map((d) => (
                      <option key={d.id} value={d.nama}>
                        {d.nama}
                      </option>
                    ))}
                  </select>
                </div>
              </div>
            </div>

            {/* NIA & MEDIA */}
            <div className="grid sm:grid-cols-2 gap-5">
              <div className="bg-[#E6F4EA]/40 p-5 border border-[#CEEAD6] rounded-xl">
                <label className="block text-xs font-black mb-1.5 text-[#1E8E3E]">
                  NIA (Nomor Induk Anggota)
                </label>
                <input
                  type="text"
                  name="nia"
                  value={form.nia}
                  onChange={handleFormChange}
                  placeholder="Format: 26.05..."
                  className="w-full border border-[#A8DAB5] px-4 py-2.5 rounded-lg text-sm font-mono focus:border-[#1E8E3E] outline-none shadow-sm"
                />
              </div>
              <div className="bg-white p-5 border border-[#DADCE0] rounded-xl shadow-sm">
                <label className="block text-xs font-bold mb-1.5 text-[#202124]">
                  Urutan Tampil (Struktur Web)
                </label>
                <input
                  type="number"
                  name="noUrut"
                  value={form.noUrut}
                  onChange={handleFormChange}
                  placeholder="Contoh: 1"
                  className="w-full border border-[#DADCE0] px-4 py-2.5 rounded-lg text-sm focus:border-[#1A73E8] outline-none"
                />
              </div>
            </div>

            {/* UPLOAD FOTO */}
            <div className="bg-white p-5 border border-[#DADCE0] rounded-xl shadow-sm grid sm:grid-cols-3 gap-5">
              <div className="sm:col-span-2">
                <label className="block text-xs font-bold mb-1.5 text-[#202124]">
                  Tautan URL Foto Profil (Square/Portrait)
                </label>
                <input
                  type="url"
                  name="fotoUrl"
                  value={form.fotoUrl}
                  onChange={handleFormChange}
                  placeholder="https://contoh.com/foto.jpg"
                  className="w-full border border-[#DADCE0] px-4 py-2.5 rounded-lg text-sm outline-none focus:border-[#1A73E8] transition-all"
                />
              </div>
              <div className="sm:col-span-1">
                <label className="block text-xs font-bold mb-1.5 text-[#202124]">
                  Fokus Potongan Foto (KTA)
                </label>
                <select
                  name="fotoPosition"
                  value={form.fotoPosition}
                  onChange={handleFormChange}
                  className="w-full border border-[#DADCE0] px-4 py-2.5 rounded-lg text-sm outline-none focus:border-[#1A73E8] bg-white transition-all"
                >
                  <option value="top">Fokus Wajah (Atas)</option>
                  <option value="center">Proporsional (Tengah)</option>
                  <option value="bottom">Fokus Badan (Bawah)</option>
                </select>
              </div>
            </div>

            {/* TOGGLES PENGATURAN TAMPILAN */}
            <div className="flex gap-8 p-5 border border-[#DADCE0] rounded-xl bg-slate-50">
              <label className="flex items-center gap-2.5 text-sm font-bold cursor-pointer text-[#202124]">
                <input
                  type="checkbox"
                  name="isInti"
                  checked={form.isInti}
                  onChange={handleFormChange}
                  className="w-5 h-5 rounded border-[#DADCE0] text-[#1A73E8] cursor-pointer focus:ring-[#1A73E8]"
                />
                Termasuk Pengurus Inti
              </label>
              <label className="flex items-center gap-2.5 text-sm font-bold cursor-pointer text-[#202124]">
                <input
                  type="checkbox"
                  name="isTampilBeranda"
                  checked={form.isTampilBeranda}
                  onChange={handleFormChange}
                  className="w-5 h-5 rounded border-[#DADCE0] text-[#1A73E8] cursor-pointer focus:ring-[#1A73E8]"
                />
                Tampilkan di Website Publik
              </label>
            </div>
          </div>

          <div className="flex justify-end gap-3 mt-10 pt-6 border-t border-[#EBEBEB]">
            <button
              type="button"
              onClick={() => setView("list")}
              className="px-6 py-3 text-sm font-bold border border-[#DADCE0] text-[#5F6368] rounded-xl hover:bg-slate-100 transition-colors"
            >
              Batal
            </button>
            <button
              type="submit"
              disabled={isProcessing}
              className="px-8 py-3 text-sm font-bold text-white bg-[#1A73E8] rounded-xl hover:bg-[#1557B0] shadow-md transition-all hover:-translate-y-0.5"
            >
              {isProcessing ? "Menyimpan Data..." : "Simpan Personalia"}
            </button>
          </div>
        </form>
      )}
    </div>
  );
}

"use client";

import { useState, useEffect } from "react";
import { db } from "@/lib/firebase";
import {
  collection,
  addDoc,
  getDocs,
  deleteDoc,
  doc,
  updateDoc,
  query,
  orderBy,
} from "firebase/firestore";
import * as XLSX from "xlsx";
import {
  IconPlus,
  IconDownload,
  IconUpload,
  IconCheck,
  IconAlert,
  IconEmpty,
  IconInfo,
} from "./Icons";

export default function TabPeriode() {
  const [dataList, setDataList] = useState<any[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [isProcessing, setIsProcessing] = useState(false);

  const [view, setView] = useState<"list" | "form">("list");
  const [editId, setEditId] = useState<string | null>(null);
  const [selectedIds, setSelectedIds] = useState<string[]>([]);

  const [form, setForm] = useState({
    namaPeriode: "",
    tglMulai: "",
    tglSelesai: "",
    status: "Aktif",
    linkSK: "",
  });

  // UI States
  const [toast, setToast] = useState({
    isOpen: false,
    message: "",
    type: "success",
  });
  const [deleteModal, setDeleteModal] = useState({
    isOpen: false,
    id: "",
    title: "",
    type: "single",
  });

  const showToast = (
    message: string,
    type: "success" | "error" | "info" = "success",
  ) => {
    setToast({ isOpen: true, message, type });
    setTimeout(() => setToast((prev) => ({ ...prev, isOpen: false })), 4000);
  };

  const fetchData = async () => {
    setIsLoading(true);
    try {
      const q = query(collection(db, "periode"), orderBy("tglMulai", "desc"));
      const snap = await getDocs(q);
      setDataList(snap.docs.map((d) => ({ id: d.id, ...d.data() })));
    } catch (error) {
      showToast("Gagal load data periode.", "error");
    } finally {
      setIsLoading(false);
      setSelectedIds([]);
    }
  };

  useEffect(() => {
    fetchData();
  }, []);

  const handleFormChange = (e: any) => {
    setForm({ ...form, [e.target.name]: e.target.value });
  };

  const saveData = async (e: React.FormEvent) => {
    e.preventDefault();
    setIsProcessing(true);
    try {
      if (editId) {
        await updateDoc(doc(db, "periode", editId), {
          ...form,
          updatedAt: new Date().toISOString(),
        });

        // PIVOT: Demisioner otomatis jika status diubah ke Arsip
        if (form.status === "Arsip") {
          const snap = await getDocs(collection(db, "pengurus"));
          const updatePromises = snap.docs
            .filter((d) => {
              const data = d.data();
              return (
                data.periodeId === editId ||
                (!data.periodeId && data.isPengurus === true)
              );
            })
            .map((d) =>
              updateDoc(doc(db, "pengurus", d.id), {
                isPengurus: false,
                status_pengurus: "Demisioner",
                role: "anggota",
                isTampilBeranda: false,
                updatedAt: new Date().toISOString(),
              }),
            );
          if (updatePromises.length > 0) await Promise.all(updatePromises);
          showToast(
            `Periode diarsipkan. ${updatePromises.length} Pengurus diturunkan jadi Anggota.`,
            "success",
          );
        } else {
          showToast(`Periode berhasil diperbarui.`, "success");
        }
      } else {
        await addDoc(collection(db, "periode"), {
          ...form,
          createdAt: new Date().toISOString(),
        });
        showToast(`Periode baru berhasil ditambahkan.`, "success");
      }
      setForm({
        namaPeriode: "",
        tglMulai: "",
        tglSelesai: "",
        status: "Aktif",
        linkSK: "",
      });
      setEditId(null);
      await fetchData();
      setView("list");
    } catch (error) {
      showToast(`Gagal menyimpan data.`, "error");
    } finally {
      setIsProcessing(false);
    }
  };

  const executeDelete = async () => {
    setIsProcessing(true);
    try {
      if (deleteModal.type === "single" && deleteModal.id) {
        await deleteDoc(doc(db, "periode", deleteModal.id));
      } else if (deleteModal.type === "bulk" && selectedIds.length > 0) {
        await Promise.all(
          selectedIds.map((id) => deleteDoc(doc(db, "periode", id))),
        );
      }
      showToast(`Data berhasil dihapus permanen.`, "success");
      await fetchData();
    } catch (error) {
      showToast("Gagal menghapus data.", "error");
    } finally {
      setIsProcessing(false);
      setDeleteModal({ isOpen: false, id: "", title: "", type: "single" });
      setSelectedIds([]);
    }
  };

  // --- EXPORT & IMPORT EXCEL LOGIC ---
  const handleExportData = () => {
    if (dataList.length === 0)
      return showToast("Tidak ada data untuk diekspor.", "error");
    const formattedData = dataList.map((d) => ({
      Nama_Periode: d.namaPeriode,
      Tgl_Mulai: d.tglMulai,
      Tgl_Selesai: d.tglSelesai,
      Status: d.status,
    }));
    const ws = XLSX.utils.json_to_sheet(formattedData);
    const wb = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(wb, ws, "Data_Periode");
    XLSX.writeFile(wb, `Data_PERIODE_IKA_UII.xlsx`);
    showToast("Data berhasil diekspor ke Excel.", "success");
  };

  const downloadTemplateExcel = () => {
    const wsData = [
      {
        Nama_Periode: "Periode 2024-2029",
        Tgl_Mulai: "2024-01-01",
        Tgl_Selesai: "2029-12-31",
        Status: "Aktif",
      },
    ];
    const ws = XLSX.utils.json_to_sheet(wsData);
    const wb = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(wb, ws, "Template");
    XLSX.writeFile(wb, `Template_Import_PERIODE.xlsx`);
  };

  const handleImportExcel = async (e: any) => {
    const file = e.target.files[0];
    if (!file) return;
    setIsProcessing(true);
    const reader = new FileReader();
    reader.onload = async (evt: any) => {
      try {
        const bstr = evt.target.result;
        const wb = XLSX.read(bstr, { type: "binary" });
        const data = XLSX.utils.sheet_to_json(wb.Sheets[wb.SheetNames[0]]);
        let count = 0;
        for (const row of data as any[]) {
          if (row.Nama_Periode) {
            await addDoc(collection(db, "periode"), {
              namaPeriode: row.Nama_Periode,
              tglMulai: row.Tgl_Mulai || "",
              tglSelesai: row.Tgl_Selesai || "",
              status: row.Status || "Aktif",
              createdAt: new Date().toISOString(),
            });
            count++;
          }
        }
        showToast(`${count} Data berhasil di-import!`, "success");
        await fetchData();
      } catch (error) {
        showToast("Gagal membaca Excel.", "error");
      } finally {
        setIsProcessing(false);
        e.target.value = null;
      }
    };
    reader.readAsBinaryString(file);
  };

  return (
    <div className="relative">
      {/* LOCAL TOAST */}
      <div
        className={`fixed top-6 right-6 z-[200] transition-all duration-300 transform ${toast.isOpen ? "translate-y-0 opacity-100" : "-translate-y-4 opacity-0 pointer-events-none"}`}
      >
        <div
          className={`flex items-center gap-3 px-5 py-4 rounded-xl shadow-lg border ${toast.type === "success" ? "bg-white border-emerald-100" : "bg-white border-red-100"}`}
        >
          <div
            className={`flex-shrink-0 w-9 h-9 rounded-full flex items-center justify-center ${toast.type === "success" ? "bg-emerald-100 text-emerald-600" : "bg-red-100 text-red-600"}`}
          >
            {toast.type === "success" ? <IconCheck /> : <IconAlert />}
          </div>
          <div>
            <p className="text-sm font-bold text-slate-800">
              {toast.type === "success" ? "Berhasil!" : "Peringatan!"}
            </p>
            <p className="text-[13px] text-slate-500 mt-0.5">{toast.message}</p>
          </div>
        </div>
      </div>

      {/* DELETE MODAL */}
      {deleteModal.isOpen && (
        <div className="fixed inset-0 z-[150] flex items-center justify-center p-4 bg-slate-900/40 backdrop-blur-sm">
          <div className="bg-white rounded-xl shadow-xl p-6 max-w-sm w-full text-center border border-[#DADCE0] animate-in zoom-in-95">
            <div className="flex justify-center text-[#D93025] mb-3">
              <IconAlert />
            </div>
            <h3 className="text-lg font-medium text-[#202124] mb-1">
              Hapus Permanen?
            </h3>
            <p className="text-sm text-[#5F6368] mb-6">
              Anda yakin ingin menghapus <strong>"{deleteModal.title}"</strong>?
            </p>
            <div className="flex gap-3 justify-center">
              <button
                onClick={() =>
                  setDeleteModal({
                    isOpen: false,
                    id: "",
                    title: "",
                    type: "single",
                  })
                }
                className="px-4 py-2 rounded-lg text-sm font-medium text-[#5F6368] border hover:bg-[#F8F9FA] w-full"
              >
                Batal
              </button>
              <button
                onClick={executeDelete}
                disabled={isProcessing}
                className="px-4 py-2 rounded-lg text-sm font-medium text-white bg-[#D93025] hover:bg-[#b52a1f] w-full"
              >
                {isProcessing ? "Proses..." : "Hapus"}
              </button>
            </div>
          </div>
        </div>
      )}

      {/* KONTEN UTAMA */}
      {view === "list" ? (
        <div className="bg-white rounded-lg border border-[#DADCE0] shadow-sm overflow-hidden">
          <div className="p-4 flex flex-col xl:flex-row justify-between items-start xl:items-center gap-4 border-b border-[#DADCE0]">
            <h3 className="font-medium text-[#202124] text-base">
              Masa Kepengurusan
            </h3>
            <div className="flex flex-wrap items-center gap-2 w-full xl:w-auto">
              {selectedIds.length > 0 && (
                <button
                  onClick={() =>
                    setDeleteModal({
                      isOpen: true,
                      type: "bulk",
                      id: "",
                      title: `${selectedIds.length} Data Terpilih`,
                    })
                  }
                  className="text-xs bg-white text-[#D93025] border border-[#FCE8E6] hover:bg-[#FCE8E6] px-4 py-2.5 rounded-lg transition-colors shadow-sm font-bold"
                >
                  Hapus ({selectedIds.length})
                </button>
              )}
              <button
                onClick={handleExportData}
                className="text-xs font-bold bg-white text-slate-700 border border-[#DADCE0] px-4 py-2.5 rounded-lg hover:bg-slate-50 flex items-center gap-2 shadow-sm transition-colors"
              >
                <IconDownload /> Export
              </button>
              <button
                onClick={downloadTemplateExcel}
                className="text-xs font-bold bg-white text-slate-700 border border-[#DADCE0] px-4 py-2.5 rounded-lg hover:bg-slate-50 shadow-sm transition-colors"
              >
                Template
              </button>
              <label className="cursor-pointer text-xs font-bold bg-[#F8F9FA] text-slate-700 border border-[#DADCE0] px-4 py-2.5 rounded-lg hover:bg-slate-100 flex items-center gap-2 shadow-sm">
                <IconUpload /> Import
                <input
                  type="file"
                  accept=".xlsx, .xls"
                  onChange={handleImportExcel}
                  className="hidden"
                />
              </label>
              <button
                onClick={() => {
                  setView("form");
                  setEditId(null);
                  setForm({
                    namaPeriode: "",
                    tglMulai: "",
                    tglSelesai: "",
                    status: "Aktif",
                    linkSK: "",
                  });
                }}
                className="text-xs bg-[#1A73E8] text-white border border-[#1A73E8] hover:bg-[#1557B0] px-4 py-2.5 rounded-lg font-bold flex items-center gap-1.5 shadow-sm"
              >
                <IconPlus /> Tambah Baru
              </button>
            </div>
          </div>

          <div className="overflow-x-auto min-h-[300px]">
            {isLoading ? (
              <div className="p-10 text-center text-slate-500">
                Memuat data...
              </div>
            ) : (
              <table className="w-full text-left text-sm whitespace-nowrap">
                <thead className="bg-[#F8F9FA] border-b text-[#5F6368]">
                  <tr>
                    <th className="px-6 py-3 w-8">
                      <input
                        type="checkbox"
                        onChange={(e) =>
                          setSelectedIds(
                            e.target.checked ? dataList.map((d) => d.id) : [],
                          )
                        }
                        checked={
                          dataList.length > 0 &&
                          selectedIds.length === dataList.length
                        }
                        className="rounded cursor-pointer"
                      />
                    </th>
                    <th className="px-6 py-3 font-medium text-xs uppercase tracking-wider">
                      Periode Kepengurusan
                    </th>
                    <th className="px-6 py-3 font-medium text-xs uppercase tracking-wider text-right">
                      Aksi
                    </th>
                  </tr>
                </thead>
                <tbody className="divide-y divide-[#DADCE0]">
                  {dataList.length === 0 ? (
                    <tr>
                      <td colSpan={3} className="text-center py-16">
                        <IconEmpty />
                        <p className="text-sm text-slate-500">
                          Belum Ada Periode
                        </p>
                      </td>
                    </tr>
                  ) : (
                    dataList.map((p) => (
                      <tr key={p.id} className="hover:bg-[#F8F9FA]">
                        <td className="px-6 py-4">
                          <input
                            type="checkbox"
                            checked={selectedIds.includes(p.id)}
                            onChange={(e) =>
                              setSelectedIds((prev) =>
                                e.target.checked
                                  ? [...prev, p.id]
                                  : prev.filter((id) => id !== p.id),
                              )
                            }
                            className="rounded cursor-pointer"
                          />
                        </td>
                        <td className="px-6 py-4">
                          <div className="font-medium text-[#202124] text-sm flex items-center gap-3">
                            {p.namaPeriode}
                            <span
                              className={`text-[10px] px-2 py-0.5 rounded font-medium border ${p.status === "Aktif" ? "bg-[#E6F4EA] text-[#1E8E3E] border-[#CEEAD6]" : "bg-[#F1F3F4] text-[#5F6368] border-[#DADCE0]"}`}
                            >
                              {p.status}
                            </span>
                          </div>
                          <div className="text-xs text-[#5F6368] mt-1">
                            {p.tglMulai} s/d {p.tglSelesai}
                          </div>
                        </td>
                        <td className="px-6 py-4 text-right">
                          <button
                            onClick={() => {
                              setForm(p);
                              setEditId(p.id);
                              setView("form");
                            }}
                            className="text-sm font-medium text-[#1A73E8] hover:bg-[#E8F0FE] px-3 py-1.5 rounded-md transition-colors"
                          >
                            Edit
                          </button>
                        </td>
                      </tr>
                    ))
                  )}
                </tbody>
              </table>
            )}
          </div>
        </div>
      ) : (
        <form
          onSubmit={saveData}
          className="bg-white rounded-lg border border-[#DADCE0] p-6 sm:p-8 max-w-xl mx-auto shadow-sm"
        >
          <h3 className="font-medium mb-6 text-lg border-b pb-4">
            {editId ? "Edit Masa Periode" : "Buat Periode Baru"}
          </h3>
          <div className="space-y-4">
            <div>
              <label className="block text-xs font-medium text-[#5F6368] mb-1">
                Nama Periode
              </label>
              <input
                type="text"
                name="namaPeriode"
                value={form.namaPeriode}
                onChange={handleFormChange}
                required
                placeholder="Contoh: Kabinet Sinergi 2024-2029"
                className="w-full border px-3 py-2 rounded-md text-sm outline-none focus:border-[#1A73E8]"
              />
            </div>
            <div className="grid grid-cols-2 gap-4">
              <div>
                <label className="block text-xs font-medium mb-1">
                  Tanggal Mulai
                </label>
                <input
                  type="date"
                  name="tglMulai"
                  value={form.tglMulai}
                  onChange={handleFormChange}
                  className="w-full border px-3 py-2 rounded-md text-sm outline-none focus:border-[#1A73E8]"
                />
              </div>
              <div>
                <label className="block text-xs font-medium mb-1">
                  Tanggal Selesai
                </label>
                <input
                  type="date"
                  name="tglSelesai"
                  value={form.tglSelesai}
                  onChange={handleFormChange}
                  className="w-full border px-3 py-2 rounded-md text-sm outline-none focus:border-[#1A73E8]"
                />
              </div>
            </div>
            <div>
              <label className="block text-xs font-medium mb-1">
                Status Periode
              </label>
              <select
                name="status"
                value={form.status}
                onChange={handleFormChange}
                className="w-full border px-3 py-2 rounded-md text-sm outline-none focus:border-[#1A73E8] bg-white cursor-pointer"
              >
                <option value="Aktif">Aktif (Sedang Berjalan)</option>
                <option value="Arsip">Arsip (Demisioner)</option>
              </select>
              {form.status === "Arsip" && (
                <div className="mt-2 bg-[#FCE8E6] border border-[#FAD2CF] p-3 rounded-md flex gap-2 items-start">
                  <span className="text-[#D93025] mt-0.5">
                    <IconInfo />
                  </span>
                  <p className="text-xs text-[#C5221F] font-medium leading-relaxed">
                    Menyimpan dengan status Arsip akan merubah semua Pengurus di
                    periode ini menjadi Anggota Biasa secara permanen.
                  </p>
                </div>
              )}
            </div>
          </div>
          <div className="flex gap-3 mt-6 pt-4 border-t justify-end">
            <button
              type="button"
              onClick={() => setView("list")}
              className="px-5 py-2 text-sm font-medium border rounded-md hover:bg-slate-50"
            >
              Batal
            </button>
            <button
              type="submit"
              disabled={isProcessing}
              className="px-5 py-2 text-sm font-medium text-white bg-[#1A73E8] rounded-md hover:bg-[#1557B0]"
            >
              {isProcessing ? "Menyimpan..." : "Simpan"}
            </button>
          </div>
        </form>
      )}
    </div>
  );
}

"use client";

import { useState, useEffect } from "react";
import { toast } from "@/lib/toast";
import { useParams, useRouter } from "next/navigation";
import { db } from "@/lib/firebase";
import {
  collection,
  query,
  where,
  getDocs,
  doc,
  getDoc,
  addDoc,
  updateDoc,
  deleteDoc,
  serverTimestamp,
} from "firebase/firestore";
import Link from "next/link";

export default function ModuleManagementPage() {
  const params = useParams();
  const router = useRouter();
  const courseId = params.id as string;

  const [course, setCourse] = useState<any>(null);
  const [modules, setModules] = useState<any[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [isProcessing, setIsProcessing] = useState(false);

  // State Form
  const [viewMode, setViewMode] = useState<"list" | "form">("list");
  const [editId, setEditId] = useState<string | null>(null);

  // 🔥 STATE BARU: DITAMBAHKAN BAB, TIPE, DAN SOAL UJIAN 🔥
  const [formData, setFormData] = useState({
    urutan: "",
    bab: "",
    judul: "",
    tipe: "video", // 'video' | 'pdf' | 'ujian'
    deskripsi: "",
    videoUrl: "",
    dokumenUrl: "",
    durasiUjian: 15,
    kkm: 70,
    soalUjian: [] as any[],
  });

  useEffect(() => {
    fetchCourseAndModules();
  }, [courseId]);

  const fetchCourseAndModules = async () => {
    setIsLoading(true);
    try {
      const cDoc = await getDoc(doc(db, "masterclass_courses", courseId));
      if (!cDoc.exists()) {
        toast.error("Kelas tidak ditemukan!");
        router.push("/dashboard");
        return;
      }
      setCourse({ id: cDoc.id, ...cDoc.data() });

      const q = query(
        collection(db, "masterclass_modules"),
        where("courseId", "==", courseId),
      );
      const mSnap = await getDocs(q);

      const fetchedModules = mSnap.docs
        .map((d) => ({ id: d.id, ...d.data() }))
        .sort((a: any, b: any) => Number(a.urutan) - Number(b.urutan));

      setModules(fetchedModules);

      if (!editId && viewMode === "list") {
        setFormData((prev) => ({
          ...prev,
          urutan: String(fetchedModules.length + 1),
        }));
      }
    } catch (error) {
      console.error("Error fetching modules:", error);
    } finally {
      setIsLoading(false);
    }
  };

  const handleSave = async (e: React.FormEvent) => {
    e.preventDefault();
    setIsProcessing(true);
    try {
      // Validasi Khusus Ujian
      if (formData.tipe === "ujian" && formData.soalUjian.length === 0) {
        toast.warning("Modul Ujian minimal harus memiliki 1 Soal!");
        setIsProcessing(false);
        return;
      }

      const payload = {
        ...formData,
        urutan: Number(formData.urutan),
        courseId: courseId,
        updatedAt: serverTimestamp(),
      };

      if (editId) {
        await updateDoc(doc(db, "masterclass_modules", editId), payload);
      } else {
        await addDoc(collection(db, "masterclass_modules"), {
          ...payload,
          createdAt: serverTimestamp(),
        });
      }

      await fetchCourseAndModules();
      setViewMode("list");
      setEditId(null);
      resetForm();
    } catch (error) {
      console.error(error);
      toast.error("Gagal menyimpan modul.");
    } finally {
      setIsProcessing(false);
    }
  };

  const resetForm = () => {
    setFormData({
      urutan: String(modules.length + 1),
      bab: "",
      judul: "",
      tipe: "video",
      deskripsi: "",
      videoUrl: "",
      dokumenUrl: "",
      durasiUjian: 15,
      kkm: 70,
      soalUjian: [],
    });
  };

  // 🔥 FUNGSI BUILDER SOAL UJIAN 🔥
  const addSoal = () => {
    setFormData((prev) => ({
      ...prev,
      soalUjian: [
        ...prev.soalUjian,
        {
          pertanyaan: "",
          opsiA: "",
          opsiB: "",
          opsiC: "",
          opsiD: "",
          jawabanBenar: "A",
        },
      ],
    }));
  };

  const updateSoal = (index: number, field: string, value: string) => {
    const newSoal = [...formData.soalUjian];
    newSoal[index][field] = value;
    setFormData({ ...formData, soalUjian: newSoal });
  };

  const removeSoal = (index: number) => {
    const newSoal = formData.soalUjian.filter((_, i) => i !== index);
    setFormData({ ...formData, soalUjian: newSoal });
  };

  // 🔥 KELOMPOKKAN MODUL BERDASARKAN BAB 🔥
  const groupedModules = modules.reduce(
    (acc, mod) => {
      const namaBab = mod.bab || "Tanpa Bab";
      if (!acc[namaBab]) acc[namaBab] = [];
      acc[namaBab].push(mod);
      return acc;
    },
    {} as Record<string, any[]>,
  );

  if (isLoading) {
    return (
      <div className="min-h-screen bg-[#F5F7FA] flex flex-col items-center justify-center font-sans">
        <div className="w-10 h-10 border-4 border-slate-200 border-t-[#0056D2] rounded-full animate-spin mb-4"></div>
        <p className="font-bold text-sm text-slate-500 uppercase tracking-widest">
          Memuat Silabus...
        </p>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-[#F5F7FA] font-sans text-slate-800 p-4 sm:p-8">
      <div className="max-w-4xl mx-auto">
        {/* HEADER & KEMBALI */}
        <div className="mb-6">
          <button
            onClick={() => router.back()}
            className="flex items-center gap-2 text-sm font-bold text-slate-500 hover:text-[#0056D2] transition-colors mb-4 bg-white px-4 py-2 rounded-lg border border-slate-200 shadow-sm w-fit"
          >
            <svg
              className="w-4 h-4"
              fill="none"
              viewBox="0 0 24 24"
              stroke="currentColor"
            >
              <path
                strokeLinecap="round"
                strokeLinejoin="round"
                strokeWidth={2.5}
                d="M10 19l-7-7m0 0l7-7m-7 7h18"
              />
            </svg>
            Kembali ke Katalog
          </button>

          <div className="bg-white p-6 rounded-2xl border border-slate-200 shadow-sm flex items-start gap-4">
            <div className="w-16 h-12 bg-slate-100 rounded-lg overflow-hidden border border-slate-200 shrink-0">
              {course?.thumbnailUrl ? (
                <img
                  src={course.thumbnailUrl}
                  alt="Cover"
                  className="w-full h-full object-cover"
                />
              ) : (
                <div className="w-full h-full flex items-center justify-center text-[8px] text-slate-400">
                  No Img
                </div>
              )}
            </div>
            <div>
              <p className="text-[10px] font-bold text-[#0056D2] uppercase tracking-widest mb-1">
                Manajemen Kurikulum & Silabus
              </p>
              <h1 className="text-xl font-black text-slate-900 leading-tight">
                {course?.judul}
              </h1>
            </div>
          </div>
        </div>

        {viewMode === "list" ? (
          <div className="bg-white rounded-2xl border border-slate-200 shadow-sm overflow-hidden">
            <div className="p-5 border-b border-slate-100 flex justify-between items-center bg-slate-50/50">
              <h3 className="font-bold text-slate-800">
                Daftar Modul ({modules.length})
              </h3>
              <button
                onClick={() => {
                  setEditId(null);
                  resetForm();
                  setViewMode("form");
                }}
                className="bg-[#0056D2] hover:bg-[#00419E] text-white px-4 py-2 rounded-lg text-xs font-bold transition-colors shadow-sm"
              >
                + Tambah Modul Baru
              </button>
            </div>

            <div className="p-6">
              {modules.length === 0 ? (
                <div className="text-center py-16 text-slate-400 text-sm flex flex-col items-center">
                  <svg
                    className="w-12 h-12 mb-3 text-slate-300"
                    fill="none"
                    viewBox="0 0 24 24"
                    stroke="currentColor"
                  >
                    <path
                      strokeLinecap="round"
                      strokeLinejoin="round"
                      strokeWidth={1.5}
                      d="M19 11H5m14 0a2 2 0 012 2v6a2 2 0 01-2 2H5a2 2 0 01-2-2v-6a2 2 0 012-2m14 0V9a2 2 0 00-2-2M5 11V9a2 2 0 002-2m0 0V5a2 2 0 012-2h6a2 2 0 012 2v2M7 7h10"
                    />
                  </svg>
                  Belum ada silabus kurikulum untuk kelas ini.
                </div>
              ) : (
                <div className="space-y-6">
                  {Object.keys(groupedModules).map((babName, bIdx) => (
                    <div
                      key={bIdx}
                      className="border border-slate-200 rounded-xl overflow-hidden"
                    >
                      <div className="bg-slate-100/50 px-5 py-3 border-b border-slate-200 flex justify-between items-center">
                        <h3 className="font-black text-slate-800 uppercase tracking-wide text-sm">
                          {babName}
                        </h3>
                        <span className="text-xs font-bold text-slate-500 bg-white px-2 py-1 rounded border border-slate-200">
                          {groupedModules[babName].length} Item
                        </span>
                      </div>
                      <div className="divide-y divide-slate-100">
                        {groupedModules[babName].map((mod: any) => (
                          <div
                            key={mod.id}
                            className="p-5 hover:bg-slate-50 transition-colors flex items-start gap-4"
                          >
                            <div className="w-10 h-10 bg-blue-50 text-[#0056D2] rounded-lg border border-blue-100 flex items-center justify-center font-black shrink-0 mt-1">
                              {mod.urutan}
                            </div>
                            <div className="flex-1 min-w-0">
                              <h4 className="font-bold text-slate-900 text-base mb-1">
                                {mod.judul}
                              </h4>
                              <p className="text-xs text-slate-500 line-clamp-2 leading-relaxed mb-3">
                                {mod.deskripsi || (
                                  <span className="italic text-slate-300">
                                    Tidak ada deskripsi
                                  </span>
                                )}
                              </p>

                              <div className="flex gap-3 text-[10px] font-bold uppercase tracking-widest text-slate-400">
                                {/* Badge Tipe Konten */}
                                {mod.tipe === "ujian" ? (
                                  <span className="flex items-center gap-1 text-rose-600 bg-rose-50 px-2 py-1 rounded">
                                    📝 Ujian/Kuis ({mod.soalUjian?.length || 0}{" "}
                                    Soal)
                                  </span>
                                ) : mod.tipe === "pdf" ? (
                                  <span className="flex items-center gap-1 text-indigo-600 bg-indigo-50 px-2 py-1 rounded">
                                    📄 Dokumen PDF
                                  </span>
                                ) : (
                                  <span className="flex items-center gap-1 text-emerald-600 bg-emerald-50 px-2 py-1 rounded">
                                    ▶️ Video Belajar
                                  </span>
                                )}
                              </div>
                            </div>
                            <div className="flex items-center gap-2 shrink-0">
                              <button
                                onClick={() => {
                                  setEditId(mod.id);
                                  setFormData({
                                    ...resetForm,
                                    ...mod,
                                    tipe: mod.tipe || "video",
                                  });
                                  setViewMode("form");
                                }}
                                className="w-8 h-8 rounded-lg bg-blue-50 text-blue-600 flex items-center justify-center hover:bg-blue-100 transition-colors"
                              >
                                <svg
                                  className="w-4 h-4"
                                  fill="none"
                                  viewBox="0 0 24 24"
                                  stroke="currentColor"
                                >
                                  <path
                                    strokeLinecap="round"
                                    strokeLinejoin="round"
                                    strokeWidth={2}
                                    d="M15.232 5.232l3.536 3.536m-2.036-5.036a2.5 2.5 0 113.536 3.536L6.5 21.036H3v-3.572L16.732 3.732z"
                                  />
                                </svg>
                              </button>
                              <button
                                onClick={async () => {
                                  if (confirm(`Hapus modul "${mod.judul}"?`)) {
                                    await deleteDoc(
                                      doc(db, "masterclass_modules", mod.id),
                                    );
                                    fetchCourseAndModules();
                                  }
                                }}
                                className="w-8 h-8 rounded-lg bg-rose-50 text-rose-600 flex items-center justify-center hover:bg-rose-100 transition-colors"
                              >
                                <svg
                                  className="w-4 h-4"
                                  fill="none"
                                  viewBox="0 0 24 24"
                                  stroke="currentColor"
                                >
                                  <path
                                    strokeLinecap="round"
                                    strokeLinejoin="round"
                                    strokeWidth={2}
                                    d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16"
                                  />
                                </svg>
                              </button>
                            </div>
                          </div>
                        ))}
                      </div>
                    </div>
                  ))}
                </div>
              )}
            </div>
          </div>
        ) : (
          <form
            onSubmit={handleSave}
            className="bg-white rounded-2xl border border-slate-200 p-6 sm:p-8 shadow-sm"
          >
            <h3 className="text-lg font-black text-slate-900 mb-6 border-b border-slate-100 pb-4">
              {editId ? "Update Data Modul" : "Tambah Modul Baru"}
            </h3>

            <div className="grid grid-cols-1 md:grid-cols-4 gap-6 mb-6">
              {/* BARIS 1: URUTAN & BAB */}
              <div className="md:col-span-1">
                <label className="block text-[11px] font-bold text-slate-500 uppercase tracking-widest mb-1.5 ml-1">
                  Urutan
                </label>
                <input
                  required
                  type="number"
                  min="1"
                  value={formData.urutan}
                  onChange={(e) =>
                    setFormData({ ...formData, urutan: e.target.value })
                  }
                  className="w-full bg-slate-50 border border-slate-200 px-4 py-3 rounded-xl text-sm font-black text-[#0056D2] text-center outline-none focus:border-blue-500"
                />
              </div>
              <div className="md:col-span-3">
                <label className="block text-[11px] font-bold text-slate-500 uppercase tracking-widest mb-1.5 ml-1">
                  Kategori Bab / Topik
                </label>
                <input
                  required
                  type="text"
                  value={formData.bab}
                  onChange={(e) =>
                    setFormData({ ...formData, bab: e.target.value })
                  }
                  className="w-full bg-slate-50 border border-slate-200 px-4 py-3 rounded-xl text-sm font-bold outline-none focus:border-blue-500"
                  placeholder="Contoh: Bab 1 - Pendahuluan"
                />
              </div>

              {/* BARIS 2: JUDUL & TIPE */}
              <div className="md:col-span-3">
                <label className="block text-[11px] font-bold text-slate-500 uppercase tracking-widest mb-1.5 ml-1">
                  Judul Sesi / Modul
                </label>
                <input
                  required
                  type="text"
                  value={formData.judul}
                  onChange={(e) =>
                    setFormData({ ...formData, judul: e.target.value })
                  }
                  className="w-full bg-slate-50 border border-slate-200 px-4 py-3 rounded-xl text-sm font-bold outline-none focus:border-blue-500"
                  placeholder="Contoh: Cara Instalasi Next.js"
                />
              </div>
              <div className="md:col-span-1">
                <label className="block text-[11px] font-bold text-slate-500 uppercase tracking-widest mb-1.5 ml-1">
                  Tipe Konten
                </label>
                <select
                  value={formData.tipe}
                  onChange={(e) =>
                    setFormData({ ...formData, tipe: e.target.value })
                  }
                  className="w-full bg-slate-50 border border-slate-200 px-4 py-3 rounded-xl text-sm font-bold outline-none focus:border-blue-500 cursor-pointer"
                >
                  <option value="video">▶️ Video</option>
                  <option value="pdf">📄 PDF Dokumen</option>
                  <option value="ujian">📝 Ujian / Quiz</option>
                </select>
              </div>

              {/* BARIS 3: DESKRIPSI */}
              <div className="md:col-span-4">
                <label className="block text-[11px] font-bold text-slate-500 uppercase tracking-widest mb-1.5 ml-1">
                  Deskripsi & Catatan Modul
                </label>
                <textarea
                  rows={3}
                  value={formData.deskripsi}
                  onChange={(e) =>
                    setFormData({ ...formData, deskripsi: e.target.value })
                  }
                  className="w-full bg-slate-50 border border-slate-200 px-4 py-3 rounded-xl text-sm outline-none resize-none focus:border-blue-500"
                  placeholder="Penjelasan singkat atau instruksi pengerjaan..."
                ></textarea>
              </div>

              {/* 🔥 KONDISIONAL RENDER BERDASARKAN TIPE KONTEN 🔥 */}
              {formData.tipe === "video" && (
                <div className="md:col-span-4 bg-blue-50/50 p-5 rounded-2xl border border-blue-100">
                  <label className="block text-[11px] font-bold text-blue-600 uppercase tracking-widest mb-1.5 ml-1">
                    URL Video Pembelajaran (YouTube)
                  </label>
                  <input
                    type="url"
                    value={formData.videoUrl}
                    onChange={(e) =>
                      setFormData({ ...formData, videoUrl: e.target.value })
                    }
                    className="w-full bg-white border border-slate-200 px-4 py-3 rounded-xl text-sm outline-none focus:border-blue-500 mb-3"
                    placeholder="https://youtube.com/watch?v=..."
                  />

                  <label className="block text-[11px] font-bold text-slate-500 uppercase tracking-widest mb-1.5 ml-1">
                    URL Lampiran (Opsional)
                  </label>
                  <input
                    type="url"
                    value={formData.dokumenUrl}
                    onChange={(e) =>
                      setFormData({ ...formData, dokumenUrl: e.target.value })
                    }
                    className="w-full bg-white border border-slate-200 px-4 py-3 rounded-xl text-sm outline-none focus:border-blue-500"
                    placeholder="Link GDrive PDF..."
                  />
                </div>
              )}

              {formData.tipe === "pdf" && (
                <div className="md:col-span-4 bg-indigo-50/50 p-5 rounded-2xl border border-indigo-100">
                  <label className="block text-[11px] font-bold text-indigo-600 uppercase tracking-widest mb-1.5 ml-1">
                    URL Dokumen Utama (G-Drive / PDF Link)
                  </label>
                  <input
                    required
                    type="url"
                    value={formData.dokumenUrl}
                    onChange={(e) =>
                      setFormData({ ...formData, dokumenUrl: e.target.value })
                    }
                    className="w-full bg-white border border-slate-200 px-4 py-3 rounded-xl text-sm outline-none focus:border-indigo-500"
                    placeholder="https://drive.google.com/..."
                  />
                </div>
              )}

              {formData.tipe === "ujian" && (
                <div className="md:col-span-4 border-t border-slate-200 pt-6">
                  <div className="bg-rose-50 border border-rose-100 rounded-2xl p-6">
                    <div className="flex items-center gap-2 mb-6">
                      <span className="text-xl">📝</span>
                      <div>
                        <h3 className="font-black text-rose-900">
                          Quiz / Ujian Builder
                        </h3>
                        <p className="text-xs font-medium text-rose-700">
                          Buat soal pilihan ganda untuk modul ini.
                        </p>
                      </div>
                    </div>

                    <div className="grid grid-cols-2 gap-4 mb-8">
                      <div>
                        <label className="block text-[10px] font-bold text-rose-800 uppercase tracking-widest mb-1">
                          Waktu Ujian (Menit)
                        </label>
                        <input
                          type="number"
                          min="1"
                          value={formData.durasiUjian}
                          onChange={(e) =>
                            setFormData({
                              ...formData,
                              durasiUjian: Number(e.target.value),
                            })
                          }
                          className="w-full bg-white border border-rose-200 px-4 py-2 rounded-lg text-sm font-bold text-center outline-none focus:border-rose-500"
                        />
                      </div>
                      <div>
                        <label className="block text-[10px] font-bold text-rose-800 uppercase tracking-widest mb-1">
                          Nilai Lulus Minimal (KKM)
                        </label>
                        <input
                          type="number"
                          min="1"
                          max="100"
                          value={formData.kkm}
                          onChange={(e) =>
                            setFormData({
                              ...formData,
                              kkm: Number(e.target.value),
                            })
                          }
                          className="w-full bg-white border border-rose-200 px-4 py-2 rounded-lg text-sm font-bold text-center outline-none focus:border-rose-500"
                        />
                      </div>
                    </div>

                    {/* LIST SOAL */}
                    <div className="space-y-4">
                      {formData.soalUjian.map((soal, sIdx) => (
                        <div
                          key={sIdx}
                          className="bg-white p-5 rounded-xl border border-rose-200 shadow-sm relative"
                        >
                          <div className="absolute top-3 right-3">
                            <button
                              type="button"
                              onClick={() => removeSoal(sIdx)}
                              className="text-rose-400 hover:text-rose-600 text-xs font-bold"
                            >
                              Hapus Soal
                            </button>
                          </div>
                          <h4 className="text-xs font-black text-slate-800 mb-3 bg-slate-100 w-fit px-2 py-1 rounded">
                            SOAL #{sIdx + 1}
                          </h4>

                          <textarea
                            required
                            rows={2}
                            value={soal.pertanyaan}
                            onChange={(e) =>
                              updateSoal(sIdx, "pertanyaan", e.target.value)
                            }
                            className="w-full bg-slate-50 border border-slate-200 px-3 py-2 rounded-lg text-sm outline-none mb-4"
                            placeholder="Tulis pertanyaan di sini..."
                          ></textarea>

                          <div className="grid grid-cols-1 sm:grid-cols-2 gap-3 mb-4">
                            <div className="flex gap-2">
                              <span className="bg-slate-100 font-black text-slate-500 px-3 py-2 rounded-lg border border-slate-200">
                                A
                              </span>
                              <input
                                required
                                type="text"
                                value={soal.opsiA}
                                onChange={(e) =>
                                  updateSoal(sIdx, "opsiA", e.target.value)
                                }
                                className="flex-1 border border-slate-200 px-3 py-2 rounded-lg text-sm"
                                placeholder="Opsi A"
                              />
                            </div>
                            <div className="flex gap-2">
                              <span className="bg-slate-100 font-black text-slate-500 px-3 py-2 rounded-lg border border-slate-200">
                                B
                              </span>
                              <input
                                required
                                type="text"
                                value={soal.opsiB}
                                onChange={(e) =>
                                  updateSoal(sIdx, "opsiB", e.target.value)
                                }
                                className="flex-1 border border-slate-200 px-3 py-2 rounded-lg text-sm"
                                placeholder="Opsi B"
                              />
                            </div>
                            <div className="flex gap-2">
                              <span className="bg-slate-100 font-black text-slate-500 px-3 py-2 rounded-lg border border-slate-200">
                                C
                              </span>
                              <input
                                required
                                type="text"
                                value={soal.opsiC}
                                onChange={(e) =>
                                  updateSoal(sIdx, "opsiC", e.target.value)
                                }
                                className="flex-1 border border-slate-200 px-3 py-2 rounded-lg text-sm"
                                placeholder="Opsi C"
                              />
                            </div>
                            <div className="flex gap-2">
                              <span className="bg-slate-100 font-black text-slate-500 px-3 py-2 rounded-lg border border-slate-200">
                                D
                              </span>
                              <input
                                required
                                type="text"
                                value={soal.opsiD}
                                onChange={(e) =>
                                  updateSoal(sIdx, "opsiD", e.target.value)
                                }
                                className="flex-1 border border-slate-200 px-3 py-2 rounded-lg text-sm"
                                placeholder="Opsi D"
                              />
                            </div>
                          </div>

                          <div className="flex items-center gap-3 bg-emerald-50 p-3 rounded-lg border border-emerald-100">
                            <span className="text-xs font-black text-emerald-800">
                              KUNCI JAWABAN BENAR:
                            </span>
                            <select
                              value={soal.jawabanBenar}
                              onChange={(e) =>
                                updateSoal(sIdx, "jawabanBenar", e.target.value)
                              }
                              className="bg-white border border-emerald-200 px-3 py-1.5 rounded text-sm font-bold text-emerald-700 outline-none"
                            >
                              <option value="A">Opsi A</option>
                              <option value="B">Opsi B</option>
                              <option value="C">Opsi C</option>
                              <option value="D">Opsi D</option>
                            </select>
                          </div>
                        </div>
                      ))}
                    </div>

                    <button
                      type="button"
                      onClick={addSoal}
                      className="w-full mt-4 py-3 border-2 border-dashed border-rose-300 text-rose-600 font-black text-sm rounded-xl hover:bg-rose-100 transition-colors"
                    >
                      + Tambah Soal Pilihan Ganda
                    </button>
                  </div>
                </div>
              )}
            </div>

            <div className="flex justify-end gap-3 pt-6 border-t border-slate-100">
              <button
                type="button"
                onClick={() => setViewMode("list")}
                className="px-6 py-2.5 text-sm font-bold text-slate-500 bg-slate-50 hover:bg-slate-100 rounded-xl transition-colors"
              >
                Batal
              </button>
              <button
                disabled={isProcessing}
                type="submit"
                className="px-8 py-2.5 text-sm font-bold text-white bg-[#0056D2] hover:bg-[#00419E] rounded-xl transition-all disabled:opacity-50 flex items-center gap-2 shadow-md shadow-blue-500/20"
              >
                {isProcessing ? "Menyimpan..." : "Simpan Modul"}
              </button>
            </div>
          </form>
        )}
      </div>
    </div>
  );
}

"use client";

import { useState, useEffect } from "react";
import { toast } from "@/lib/toast";
import { db } from "@/lib/firebase";
import Link from "next/link";
import {
  collection,
  addDoc,
  getDocs,
  deleteDoc,
  doc,
  updateDoc,
  query,
  orderBy,
  serverTimestamp,
} from "firebase/firestore";

export default function TabCourses() {
  const [courses, setCourses] = useState<any[]>([]);
  const [mentors, setMentors] = useState<any[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [isProcessing, setIsProcessing] = useState(false);
  const [viewMode, setViewMode] = useState("list");
  const [editId, setEditId] = useState<string | null>(null);

  const [formData, setFormData] = useState({
    judul: "",
    tipeKelas: "Video on Demand",
    kategori: "Bisnis & Kepemimpinan",
    kategoriLainnya: "",
    tipeHarga: "Gratis",
    harga: "",
    pajak: "11",
    isTrial: false,
    trialDays: "",
    mentorId: "",
    deskripsi: "",
    thumbnailUrl: "",
    status: "Draft",
  });

  const KATEGORI_LIST = [
    "Bisnis & Kepemimpinan",
    "Teknologi & Data",
    "Pengembangan Karir",
    "Kewirausahaan",
    "Lainnya",
  ];

  useEffect(() => {
    fetchData();
  }, []);

  const fetchData = async () => {
    setIsLoading(true);
    try {
      const snapCourses = await getDocs(
        query(
          collection(db, "masterclass_courses"),
          orderBy("createdAt", "desc"),
        ),
      );
      setCourses(snapCourses.docs.map((d) => ({ id: d.id, ...d.data() })));
      const snapMentors = await getDocs(
        query(collection(db, "masterclass_mentors")),
      );
      setMentors(
        snapMentors.docs.map((d) => ({
          id: d.id,
          nama: d.data().nama,
          gelar: d.data().gelar,
        })),
      );
    } catch (error) {
      console.error(error);
    } finally {
      setIsLoading(false);
    }
  };

  const handleSave = async (e: React.FormEvent) => {
    e.preventDefault();
    setIsProcessing(true);
    try {
      const finalKategori =
        formData.kategori === "Lainnya"
          ? formData.kategoriLainnya
          : formData.kategori;
      const nominalHarga =
        formData.tipeHarga === "Gratis" ? 0 : Number(formData.harga);
      const persentasePajak =
        formData.tipeHarga === "Gratis" ? 0 : Number(formData.pajak);
      const totalHarga = nominalHarga + (nominalHarga * persentasePajak) / 100;

      const payload = {
        ...formData,
        kategori: finalKategori,
        harga: nominalHarga,
        pajak: persentasePajak,
        totalHarga: totalHarga,
        trialDays: formData.isTrial ? Number(formData.trialDays) : 0,
        updatedAt: serverTimestamp(),
      };

      if (editId)
        await updateDoc(doc(db, "masterclass_courses", editId), payload);
      else
        await addDoc(collection(db, "masterclass_courses"), {
          ...payload,
          createdAt: serverTimestamp(),
        });

      fetchData();
      setViewMode("list");
      setEditId(null);
      // Reset form
      setFormData({
        judul: "",
        tipeKelas: "Video on Demand",
        kategori: "Bisnis & Kepemimpinan",
        kategoriLainnya: "",
        tipeHarga: "Gratis",
        harga: "",
        pajak: "11",
        isTrial: false,
        trialDays: "",
        mentorId: "",
        deskripsi: "",
        thumbnailUrl: "",
        status: "Draft",
      });
    } catch (error) {
      toast.error("Gagal menyimpan data kelas");
    } finally {
      setIsProcessing(false);
    }
  };

  return (
    <div className="space-y-6">
      {viewMode === "list" ? (
        <>
          <div className="flex justify-between items-center bg-white p-5 rounded-[1.5rem] border border-slate-200 shadow-sm">
            <div>
              <h3 className="font-bold text-slate-800 text-lg tracking-tight">
                Katalog Kelas Masterclass
              </h3>
            </div>
            <button
              onClick={() => {
                setEditId(null);
                setViewMode("form");
              }}
              className="bg-[#1A73E8] hover:bg-[#1557B0] text-white px-5 py-2.5 rounded-xl text-sm font-bold shadow-sm transition-all"
            >
              + Buat Kelas Baru
            </button>
          </div>

          {/* 🔥 UBAH JADI TABEL MEMANJANG KE BAWAH 🔥 */}
          <div className="bg-white border border-slate-200 rounded-[1.5rem] overflow-hidden shadow-sm">
            <div className="overflow-x-auto">
              <table className="w-full text-left text-sm text-slate-600">
                <thead className="bg-slate-50 text-[10px] uppercase font-bold text-slate-500 tracking-widest border-b border-slate-200">
                  <tr>
                    <th className="px-6 py-4">Informasi Kelas</th>
                    <th className="px-6 py-4">Kategori & Format</th>
                    <th className="px-6 py-4">Harga / Akses</th>
                    <th className="px-6 py-4 text-center">Status</th>
                    <th className="px-6 py-4 text-center">Aksi Manajemen</th>
                  </tr>
                </thead>
                <tbody className="divide-y divide-slate-100">
                  {isLoading ? (
                    <tr>
                      <td
                        colSpan={5}
                        className="text-center py-10 text-slate-400"
                      >
                        Memuat data kelas...
                      </td>
                    </tr>
                  ) : courses.length === 0 ? (
                    <tr>
                      <td
                        colSpan={5}
                        className="text-center py-10 text-slate-400"
                      >
                        Belum ada kelas. Silakan buat kelas baru.
                      </td>
                    </tr>
                  ) : (
                    courses.map((c) => (
                      <tr
                        key={c.id}
                        className="hover:bg-slate-50/50 transition-colors"
                      >
                        <td className="px-6 py-4">
                          <div className="flex items-center gap-4 w-[300px]">
                            <div className="w-16 h-12 bg-slate-100 rounded-lg overflow-hidden shrink-0 border border-slate-200">
                              {c.thumbnailUrl ? (
                                <img
                                  src={c.thumbnailUrl}
                                  alt={c.judul}
                                  className="w-full h-full object-cover"
                                />
                              ) : (
                                <div className="w-full h-full flex items-center justify-center text-[8px] text-slate-400">
                                  No Img
                                </div>
                              )}
                            </div>
                            <div>
                              <h4
                                className="font-bold text-slate-900 leading-snug line-clamp-2"
                                title={c.judul}
                              >
                                {c.judul}
                              </h4>
                              <p className="text-[10px] text-slate-400 font-mono mt-0.5">
                                ID: {c.id.substring(0, 8)}
                              </p>
                            </div>
                          </div>
                        </td>
                        <td className="px-6 py-4">
                          <div className="font-bold text-slate-800">
                            {c.kategori}
                          </div>
                          <div className="text-[10px] text-slate-500 uppercase tracking-widest mt-0.5">
                            {c.tipeKelas}
                          </div>
                        </td>
                        <td className="px-6 py-4">
                          <div
                            className={`font-black ${c.tipeHarga === "Gratis" ? "text-emerald-600" : "text-blue-600"}`}
                          >
                            {c.tipeHarga === "Gratis"
                              ? "GRATIS"
                              : `Rp ${(c.totalHarga || 0).toLocaleString("id-ID")}`}
                          </div>
                          {c.isTrial && (
                            <span className="text-[9px] bg-indigo-50 text-indigo-600 font-bold px-1.5 py-0.5 rounded mt-1 inline-block">
                              TRIAL {c.trialDays} HARI
                            </span>
                          )}
                        </td>
                        <td className="px-6 py-4 text-center">
                          <span
                            className={`text-[10px] font-black px-2.5 py-1 rounded-md uppercase tracking-widest ${c.status === "Published" ? "bg-emerald-100 text-emerald-700" : "bg-amber-100 text-amber-700"}`}
                          >
                            {c.status}
                          </span>
                        </td>
                        <td className="px-6 py-4">
                          <div className="flex items-center justify-center gap-2">
                            {/* 🔥 UBAH BUTTON JADI LINK KE HALAMAN PUBLIK 🔥 */}
                            <Link
                              href={`/masterclass/${c.id}`}
                              target="_blank"
                              className="w-8 h-8 rounded-lg bg-slate-50 text-slate-500 hover:text-[#0056D2] hover:bg-blue-50 flex items-center justify-center border border-slate-200 transition-colors"
                              title="Preview Kelas (Buka di Tab Baru)"
                            >
                              <svg
                                className="w-4 h-4"
                                fill="none"
                                viewBox="0 0 24 24"
                                stroke="currentColor"
                              >
                                <path
                                  strokeLinecap="round"
                                  strokeLinejoin="round"
                                  strokeWidth={2}
                                  d="M15 12a3 3 0 11-6 0 3 3 0 016 0z"
                                />
                                <path
                                  strokeLinecap="round"
                                  strokeLinejoin="round"
                                  strokeWidth={2}
                                  d="M2.458 12C3.732 7.943 7.523 5 12 5c4.478 0 8.268 2.943 9.542 7-1.274 4.057-5.064 7-9.542 7-4.477 0-8.268-2.943-9.542-7z"
                                />
                              </svg>
                            </Link>

                            <Link
                              href={`/dashboard/masterclass/${c.id}/modules`}
                              className="px-3 py-1.5 bg-emerald-50 text-emerald-600 hover:bg-emerald-100 rounded-lg text-xs font-bold transition-colors border border-transparent hover:border-emerald-200"
                            >
                              Modul
                            </Link>
                            <button
                              onClick={() => {
                                setEditId(c.id);
                                setFormData(c);
                                setViewMode("form");
                              }}
                              className="px-3 py-1.5 bg-blue-50 text-blue-600 hover:bg-blue-100 rounded-lg text-xs font-bold transition-colors border border-transparent hover:border-blue-200"
                            >
                              Edit
                            </button>
                            <button
                              onClick={async () => {
                                if (
                                  confirm(
                                    "Hapus kelas ini? Tindakan ini tidak bisa dibatalkan.",
                                  )
                                ) {
                                  await deleteDoc(
                                    doc(db, "masterclass_courses", c.id),
                                  );
                                  fetchData();
                                }
                              }}
                              className="px-3 py-1.5 bg-rose-50 text-rose-600 hover:bg-rose-100 rounded-lg text-xs font-bold transition-colors"
                            >
                              X
                            </button>
                          </div>
                        </td>
                      </tr>
                    ))
                  )}
                </tbody>
              </table>
            </div>
          </div>
        </>
      ) : (
        <form
          onSubmit={handleSave}
          className="bg-white rounded-[2rem] border border-slate-200 p-8 max-w-3xl mx-auto shadow-sm"
        >
          <h3 className="text-xl font-black text-slate-900 mb-6 border-b border-slate-100 pb-4">
            {editId ? "Edit Kurikulum Kelas" : "Buat Kelas Masterclass Baru"}
          </h3>

          <div className="grid grid-cols-1 md:grid-cols-2 gap-6 mb-6">
            <div className="md:col-span-2">
              <label className="block text-[11px] font-bold text-slate-500 uppercase tracking-widest mb-1.5 ml-1">
                Judul Kelas
              </label>
              <input
                required
                type="text"
                value={formData.judul}
                onChange={(e) =>
                  setFormData({ ...formData, judul: e.target.value })
                }
                className="w-full bg-slate-50 border border-slate-200 px-4 py-3 rounded-xl text-sm font-bold outline-none focus:border-blue-500"
              />
            </div>

            <div>
              <label className="block text-[11px] font-bold text-slate-500 uppercase tracking-widest mb-1.5 ml-1">
                Kategori
              </label>
              <select
                required
                value={formData.kategori}
                onChange={(e) =>
                  setFormData({ ...formData, kategori: e.target.value })
                }
                className="w-full bg-slate-50 border border-slate-200 px-4 py-3 rounded-xl text-sm font-bold outline-none cursor-pointer mb-2"
              >
                {KATEGORI_LIST.map((k) => (
                  <option key={k} value={k}>
                    {k}
                  </option>
                ))}
              </select>
              {formData.kategori === "Lainnya" && (
                <input
                  required
                  type="text"
                  placeholder="Ketik kategori..."
                  value={formData.kategoriLainnya}
                  onChange={(e) =>
                    setFormData({
                      ...formData,
                      kategoriLainnya: e.target.value,
                    })
                  }
                  className="w-full bg-blue-50 border border-blue-200 px-4 py-2.5 rounded-xl text-sm outline-none"
                />
              )}
            </div>

            <div>
              <label className="block text-[11px] font-bold text-slate-500 uppercase tracking-widest mb-1.5 ml-1">
                Pilih Mentor Pakar
              </label>
              <select
                required
                value={formData.mentorId}
                onChange={(e) =>
                  setFormData({ ...formData, mentorId: e.target.value })
                }
                className="w-full bg-slate-50 border border-slate-200 px-4 py-3 rounded-xl text-sm font-bold outline-none cursor-pointer"
              >
                <option value="" disabled>
                  -- Pilih Mentor --
                </option>
                {mentors.map((m) => (
                  <option key={m.id} value={m.id}>
                    {m.nama}
                  </option>
                ))}
              </select>
            </div>

            <div className="md:col-span-2 bg-slate-50 p-5 rounded-2xl border border-slate-200">
              <label className="block text-[11px] font-bold text-slate-800 uppercase tracking-widest mb-3">
                Pengaturan Harga & Akses
              </label>
              <div className="grid grid-cols-1 sm:grid-cols-3 gap-4">
                <select
                  required
                  value={formData.tipeHarga}
                  onChange={(e) =>
                    setFormData({ ...formData, tipeHarga: e.target.value })
                  }
                  className="bg-white border border-slate-200 px-4 py-2.5 rounded-xl text-sm font-bold outline-none cursor-pointer"
                >
                  <option value="Gratis">Akses Gratis</option>
                  <option value="Premium">Premium Berbayar</option>
                </select>

                {formData.tipeHarga === "Premium" && (
                  <>
                    <input
                      required
                      type="number"
                      placeholder="Nominal (Rp)"
                      value={formData.harga}
                      onChange={(e) =>
                        setFormData({ ...formData, harga: e.target.value })
                      }
                      className="bg-white border-2 border-emerald-200 px-4 py-2.5 rounded-xl text-sm font-black text-emerald-700 outline-none"
                    />
                    <div className="flex items-center gap-2 bg-white border border-slate-200 px-4 py-2.5 rounded-xl">
                      <span className="text-xs font-bold text-slate-500">
                        Pajak %
                      </span>
                      <input
                        required
                        type="number"
                        value={formData.pajak}
                        onChange={(e) =>
                          setFormData({ ...formData, pajak: e.target.value })
                        }
                        className="w-full text-sm font-bold outline-none bg-transparent"
                      />
                    </div>
                  </>
                )}
              </div>

              <div className="mt-4 pt-4 border-t border-slate-200 flex items-center gap-4">
                <label className="flex items-center gap-2 cursor-pointer">
                  <input
                    type="checkbox"
                    checked={formData.isTrial}
                    onChange={(e) =>
                      setFormData({ ...formData, isTrial: e.target.checked })
                    }
                    className="w-4 h-4 rounded text-blue-600 focus:ring-blue-500"
                  />
                  <span className="text-xs font-bold text-slate-700">
                    Aktifkan Free Trial
                  </span>
                </label>
                {formData.isTrial && (
                  <div className="flex items-center gap-2">
                    <input
                      required
                      type="number"
                      placeholder="Berapa hari?"
                      value={formData.trialDays}
                      onChange={(e) =>
                        setFormData({ ...formData, trialDays: e.target.value })
                      }
                      className="w-24 bg-white border border-slate-200 px-3 py-1.5 rounded-lg text-sm outline-none"
                    />
                    <span className="text-xs font-medium text-slate-500">
                      Hari
                    </span>
                  </div>
                )}
              </div>
            </div>

            <div>
              <label className="block text-[11px] font-bold text-slate-500 uppercase tracking-widest mb-1.5 ml-1">
                Format Kelas
              </label>
              <select
                required
                value={formData.tipeKelas}
                onChange={(e) =>
                  setFormData({ ...formData, tipeKelas: e.target.value })
                }
                className="w-full bg-slate-50 border border-slate-200 px-4 py-3 rounded-xl text-sm font-bold outline-none cursor-pointer"
              >
                <option value="Video on Demand">Video on Demand</option>
                <option value="Live Webinar">Live Webinar</option>
              </select>
            </div>

            <div>
              <label className="block text-[11px] font-bold text-slate-500 uppercase tracking-widest mb-1.5 ml-1">
                Status Publikasi
              </label>
              <select
                required
                value={formData.status}
                onChange={(e) =>
                  setFormData({ ...formData, status: e.target.value })
                }
                className="w-full bg-slate-50 border border-slate-200 px-4 py-3 rounded-xl text-sm font-bold outline-none cursor-pointer"
              >
                <option value="Draft">Draft (Disembunyikan)</option>
                <option value="Published">Published (Publik)</option>
              </select>
            </div>

            <div className="md:col-span-2">
              <label className="block text-[11px] font-bold text-slate-500 uppercase tracking-widest mb-1.5 ml-1">
                URL Cover / Thumbnail
              </label>
              <input
                type="url"
                value={formData.thumbnailUrl}
                onChange={(e) =>
                  setFormData({ ...formData, thumbnailUrl: e.target.value })
                }
                className="w-full bg-slate-50 border border-slate-200 px-4 py-3 rounded-xl text-sm outline-none"
              />
            </div>

            <div className="md:col-span-2">
              <label className="block text-[11px] font-bold text-slate-500 uppercase tracking-widest mb-1.5 ml-1">
                Deskripsi Singkat
              </label>
              <textarea
                rows={3}
                required
                value={formData.deskripsi}
                onChange={(e) =>
                  setFormData({ ...formData, deskripsi: e.target.value })
                }
                className="w-full bg-slate-50 border border-slate-200 px-4 py-3 rounded-xl text-sm outline-none resize-none"
              ></textarea>
            </div>
          </div>

          <div className="flex justify-end gap-3 pt-6 border-t border-slate-100">
            <button
              type="button"
              onClick={() => setViewMode("list")}
              className="px-6 py-2.5 text-sm font-bold text-slate-500 bg-slate-50 rounded-xl"
            >
              Batal
            </button>
            <button
              disabled={isProcessing}
              type="submit"
              className="px-8 py-2.5 text-sm font-bold text-white bg-[#1A73E8] rounded-xl disabled:opacity-50"
            >
              Simpan Kelas
            </button>
          </div>
        </form>
      )}
    </div>
  );
}

"use client";

import { useState, useEffect } from "react";
import { db } from "@/lib/firebase";
import { collection, getDocs } from "firebase/firestore";

export default function TabDashboard() {
  const [stats, setStats] = useState({
    totalCourses: 0,
    totalMentors: 0,
    totalStudents: 0,
    totalRevenue: 0,
  });

  const [recentEnrollments, setRecentEnrollments] = useState<any[]>([]);
  const [recentReviews, setRecentReviews] = useState<any[]>([]);
  const [isLoading, setIsLoading] = useState(true);

  useEffect(() => {
    fetchDashboardData();
  }, []);

  const fetchDashboardData = async () => {
    setIsLoading(true);
    try {
      // 1. Ambil Semua Data Masterclass
      const [coursesSnap, mentorsSnap, enrollmentsSnap, reviewsSnap] =
        await Promise.all([
          getDocs(collection(db, "masterclass_courses")),
          getDocs(collection(db, "masterclass_mentors")),
          getDocs(collection(db, "masterclass_enrollments")),
          getDocs(collection(db, "masterclass_reviews")),
        ]);

      // 2. Olah Data Pendapatan & Peserta
      const enrollments = enrollmentsSnap.docs.map((d) => ({
        id: d.id,
        ...d.data(),
      }));
      const lunasEnrollments = enrollments.filter(
        (e: any) => e.statusAkses === "Lunas",
      );

      const totalRevenue = lunasEnrollments.reduce((acc, curr: any) => {
        return acc + (Number(curr.hargaTransaksi) || 0);
      }, 0);

      setStats({
        totalCourses: coursesSnap.size,
        totalMentors: mentorsSnap.size,
        totalStudents: lunasEnrollments.length,
        totalRevenue: totalRevenue,
      });

      // 3. Olah 5 Pendaftar Terbaru
      const sortedEnrollments = enrollments
        .sort((a: any, b: any) => {
          const timeA = a.createdAt?.toMillis ? a.createdAt.toMillis() : 0;
          const timeB = b.createdAt?.toMillis ? b.createdAt.toMillis() : 0;
          return timeB - timeA;
        })
        .slice(0, 5);

      setRecentEnrollments(sortedEnrollments);

      // 4. Olah 5 Ulasan Terbaru
      const reviews = reviewsSnap.docs.map((d) => ({ id: d.id, ...d.data() }));
      const sortedReviews = reviews
        .sort((a: any, b: any) => {
          const timeA = a.createdAt?.toMillis ? a.createdAt.toMillis() : 0;
          const timeB = b.createdAt?.toMillis ? b.createdAt.toMillis() : 0;
          return timeB - timeA;
        })
        .slice(0, 5);

      setRecentReviews(sortedReviews);
    } catch (error) {
      console.error("Gagal memuat dashboard:", error);
    } finally {
      setIsLoading(false);
    }
  };

  if (isLoading) {
    return (
      <div className="flex flex-col items-center justify-center py-32 text-slate-400 font-sans">
        <div className="w-10 h-10 border-4 border-slate-100 border-t-blue-600 rounded-full animate-spin mb-4"></div>
        <p className="font-bold text-sm tracking-widest uppercase">
          Memuat Analitik...
        </p>
      </div>
    );
  }

  return (
    <div className="space-y-4 font-sans">
      {/* SECTION 1: METRIC CARDS (KOTAK STATISTIK LEBIH COMPACT) */}
      <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4">
        {/* Card Pendapatan */}
        <div className="bg-white p-5 rounded-2xl border border-slate-200 shadow-sm relative overflow-hidden group hover:border-emerald-300 transition-colors">
          <div className="absolute -right-4 -top-4 w-20 h-20 bg-emerald-50 rounded-full group-hover:scale-150 transition-transform duration-500 ease-out z-0"></div>
          <div className="relative z-10">
            <div className="w-10 h-10 bg-emerald-100 text-emerald-600 rounded-xl flex items-center justify-center mb-3">
              <svg
                className="w-5 h-5"
                fill="none"
                viewBox="0 0 24 24"
                stroke="currentColor"
              >
                <path
                  strokeLinecap="round"
                  strokeLinejoin="round"
                  strokeWidth={2.5}
                  d="M12 8c-1.657 0-3 .895-3 2s1.343 2 3 2 3 .895 3 2-1.343 2-3 2m0-8c1.11 0 2.08.402 2.599 1M12 8V7m0 1v8m0 0v1m0-1c-1.11 0-2.08-.402-2.599-1M21 12a9 9 0 11-18 0 9 9 0 0118 0z"
                />
              </svg>
            </div>
            <p className="text-[10px] font-bold text-slate-400 uppercase tracking-widest mb-0.5">
              Total Pendapatan
            </p>
            <h3 className="text-xl font-black text-slate-800">
              Rp {stats.totalRevenue.toLocaleString("id-ID")}
            </h3>
          </div>
        </div>

        {/* Card Peserta Aktif */}
        <div className="bg-white p-5 rounded-2xl border border-slate-200 shadow-sm relative overflow-hidden group hover:border-blue-300 transition-colors">
          <div className="absolute -right-4 -top-4 w-20 h-20 bg-blue-50 rounded-full group-hover:scale-150 transition-transform duration-500 ease-out z-0"></div>
          <div className="relative z-10">
            <div className="w-10 h-10 bg-blue-100 text-blue-600 rounded-xl flex items-center justify-center mb-3">
              <svg
                className="w-5 h-5"
                fill="none"
                viewBox="0 0 24 24"
                stroke="currentColor"
              >
                <path
                  strokeLinecap="round"
                  strokeLinejoin="round"
                  strokeWidth={2.5}
                  d="M17 20h5v-2a3 3 0 00-5.356-1.857M17 20H7m10 0v-2c0-.656-.126-1.283-.356-1.857M7 20H2v-2a3 3 0 015.356-1.857M7 20v-2c0-.656.126-1.283.356-1.857m0 0a5.002 5.002 0 019.288 0M15 7a3 3 0 11-6 0 3 3 0 016 0zm6 3a2 2 0 11-4 0 2 2 0 014 0zM7 10a2 2 0 11-4 0 2 2 0 014 0z"
                />
              </svg>
            </div>
            <p className="text-[10px] font-bold text-slate-400 uppercase tracking-widest mb-0.5">
              Peserta Aktif
            </p>
            <h3 className="text-xl font-black text-slate-800">
              {stats.totalStudents} Alumni
            </h3>
          </div>
        </div>

        {/* Card Total Kelas */}
        <div className="bg-white p-5 rounded-2xl border border-slate-200 shadow-sm relative overflow-hidden group hover:border-indigo-300 transition-colors">
          <div className="absolute -right-4 -top-4 w-20 h-20 bg-indigo-50 rounded-full group-hover:scale-150 transition-transform duration-500 ease-out z-0"></div>
          <div className="relative z-10">
            <div className="w-10 h-10 bg-indigo-100 text-indigo-600 rounded-xl flex items-center justify-center mb-3">
              <svg
                className="w-5 h-5"
                fill="none"
                viewBox="0 0 24 24"
                stroke="currentColor"
              >
                <path
                  strokeLinecap="round"
                  strokeLinejoin="round"
                  strokeWidth={2.5}
                  d="M19 11H5m14 0a2 2 0 012 2v6a2 2 0 01-2 2H5a2 2 0 01-2-2v-6a2 2 0 012-2m14 0V9a2 2 0 00-2-2M5 11V9a2 2 0 002-2m0 0V5a2 2 0 012-2h6a2 2 0 012 2v2M7 7h10"
                />
              </svg>
            </div>
            <p className="text-[10px] font-bold text-slate-400 uppercase tracking-widest mb-0.5">
              Katalog Kelas
            </p>
            <h3 className="text-xl font-black text-slate-800">
              {stats.totalCourses} Modul
            </h3>
          </div>
        </div>

        {/* Card Total Mentor */}
        <div className="bg-white p-5 rounded-2xl border border-slate-200 shadow-sm relative overflow-hidden group hover:border-amber-300 transition-colors">
          <div className="absolute -right-4 -top-4 w-20 h-20 bg-amber-50 rounded-full group-hover:scale-150 transition-transform duration-500 ease-out z-0"></div>
          <div className="relative z-10">
            <div className="w-10 h-10 bg-amber-100 text-amber-600 rounded-xl flex items-center justify-center mb-3">
              <svg
                className="w-5 h-5"
                fill="none"
                viewBox="0 0 24 24"
                stroke="currentColor"
              >
                <path
                  strokeLinecap="round"
                  strokeLinejoin="round"
                  strokeWidth={2.5}
                  d="M9 12l2 2 4-4M7.835 4.697a3.42 3.42 0 001.946-.806 3.42 3.42 0 014.438 0 3.42 3.42 0 001.946.806 3.42 3.42 0 013.138 3.138 3.42 3.42 0 00.806 1.946 3.42 3.42 0 010 4.438 3.42 3.42 0 00-.806 1.946 3.42 3.42 0 01-3.138 3.138 3.42 3.42 0 00-1.946.806 3.42 3.42 0 01-4.438 0 3.42 3.42 0 00-1.946-.806 3.42 3.42 0 01-3.138-3.138 3.42 3.42 0 00-.806-1.946 3.42 3.42 0 010-4.438 3.42 3.42 0 00.806-1.946 3.42 3.42 0 013.138-3.138z"
                />
              </svg>
            </div>
            <p className="text-[10px] font-bold text-slate-400 uppercase tracking-widest mb-0.5">
              Pakar Terdaftar
            </p>
            <h3 className="text-xl font-black text-slate-800">
              {stats.totalMentors} Orang
            </h3>
          </div>
        </div>
      </div>

      {/* SECTION 2: RECENT ACTIVITIES (LEBIH COMPACT) */}
      <div className="grid grid-cols-1 lg:grid-cols-2 gap-4">
        {/* Kolom Pendaftar Terbaru */}
        <div className="bg-white rounded-2xl border border-slate-200 shadow-sm overflow-hidden flex flex-col">
          <div className="px-5 py-3.5 border-b border-slate-100 bg-slate-50/50 flex justify-between items-center">
            <h3 className="font-bold text-sm text-slate-800 tracking-tight">
              Pendaftaran Terbaru
            </h3>
          </div>
          <div className="flex-grow">
            {recentEnrollments.length === 0 ? (
              <div className="p-8 text-center text-slate-400 text-sm">
                Belum ada pendaftar masuk.
              </div>
            ) : (
              <div className="divide-y divide-slate-100">
                {recentEnrollments.map((e) => (
                  <div
                    key={e.id}
                    className="px-5 py-3 hover:bg-slate-50 transition-colors flex items-center justify-between gap-4"
                  >
                    <div className="flex items-center gap-3 overflow-hidden">
                      <div className="w-8 h-8 rounded-full bg-blue-100 text-blue-600 flex items-center justify-center text-xs font-black shrink-0">
                        {(e.namaPeserta || "A").charAt(0).toUpperCase()}
                      </div>
                      <div className="overflow-hidden">
                        <h4 className="font-bold text-xs text-slate-800 truncate">
                          {e.namaPeserta}
                        </h4>
                        <p className="text-[10px] text-slate-500 font-medium truncate mt-0.5">
                          {e.emailPeserta}
                        </p>
                      </div>
                    </div>
                    <div className="shrink-0 text-right">
                      <span
                        className={`text-[9px] font-black px-2 py-1 rounded uppercase tracking-widest ${e.statusAkses === "Lunas" ? "bg-emerald-100 text-emerald-700" : "bg-amber-100 text-amber-700"}`}
                      >
                        {e.statusAkses}
                      </span>
                    </div>
                  </div>
                ))}
              </div>
            )}
          </div>
        </div>

        {/* Kolom Ulasan Terbaru */}
        <div className="bg-white rounded-2xl border border-slate-200 shadow-sm overflow-hidden flex flex-col">
          <div className="px-5 py-3.5 border-b border-slate-100 bg-slate-50/50 flex justify-between items-center">
            <h3 className="font-bold text-sm text-slate-800 tracking-tight">
              Ulasan & Rating Terbaru
            </h3>
          </div>
          <div className="flex-grow">
            {recentReviews.length === 0 ? (
              <div className="p-8 text-center text-slate-400 text-sm">
                Belum ada ulasan dari peserta.
              </div>
            ) : (
              <div className="divide-y divide-slate-100">
                {recentReviews.map((r) => (
                  <div
                    key={r.id}
                    className="px-5 py-3 hover:bg-slate-50 transition-colors"
                  >
                    <div className="flex items-center justify-between mb-1.5">
                      <h4 className="font-bold text-xs text-slate-800">
                        {r.namaPeserta}
                      </h4>
                      <div className="flex gap-0.5">
                        {[1, 2, 3, 4, 5].map((star) => (
                          <span
                            key={star}
                            className={`text-[10px] ${star <= Number(r.rating) ? "text-yellow-400" : "text-slate-200"}`}
                          >
                            ★
                          </span>
                        ))}
                      </div>
                    </div>
                    <p className="text-[11px] text-slate-500 italic line-clamp-2">
                      "{r.ulasan}"
                    </p>
                  </div>
                ))}
              </div>
            )}
          </div>
        </div>
      </div>
    </div>
  );
}

"use client";

import { useState, useEffect } from "react";
import { toast } from "@/lib/toast";
import { db } from "@/lib/firebase";
import {
  collection,
  addDoc,
  getDocs,
  deleteDoc,
  doc,
  updateDoc,
  query,
  orderBy,
  serverTimestamp,
} from "firebase/firestore";

export default function TabMentors() {
  const [mentors, setMentors] = useState<any[]>([]);
  const [coursesCount, setCoursesCount] = useState<Record<string, number>>({});
  const [isLoading, setIsLoading] = useState(true);
  const [isProcessing, setIsProcessing] = useState(false);

  const [viewMode, setViewMode] = useState("list");
  const [editId, setEditId] = useState<string | null>(null);

  // State untuk Pop-up Preview Mentor
  const [previewMentor, setPreviewMentor] = useState<any | null>(null);

  const [formData, setFormData] = useState({
    nama: "",
    gelar: "",
    jabatan: "",
    perusahaan: "",
    bio: "",
    fotoUrl: "",
    fotoPosition: "object-center",
    linkedIn: "",
    tarif: "",
    ttdUrl: "", // 🔥 TAMBAHAN STATE UNTUK TTD 🔥
  });

  useEffect(() => {
    fetchMentorsAndStats();
  }, []);

  const fetchMentorsAndStats = async () => {
    setIsLoading(true);
    try {
      // 1. Tarik Data Mentor
      const q = query(
        collection(db, "masterclass_mentors"),
        orderBy("createdAt", "desc"),
      );
      const snap = await getDocs(q);
      const mentorData = snap.docs.map((d) => ({ id: d.id, ...d.data() }));
      setMentors(mentorData);

      // 2. Tarik Data Kelas untuk Menghitung Total Kelas Tiap Mentor
      const coursesSnap = await getDocs(collection(db, "masterclass_courses"));
      const counts: Record<string, number> = {};

      coursesSnap.forEach((doc) => {
        const data = doc.data();
        if (data.mentorId) {
          counts[data.mentorId] = (counts[data.mentorId] || 0) + 1;
        }
      });
      setCoursesCount(counts);
    } catch (error) {
      console.error(error);
    } finally {
      setIsLoading(false);
    }
  };

  const handleSave = async (e: React.FormEvent) => {
    e.preventDefault();
    setIsProcessing(true);
    try {
      const payload = { ...formData, tarif: Number(formData.tarif) || 0 };
      if (editId) {
        await updateDoc(doc(db, "masterclass_mentors", editId), {
          ...payload,
          updatedAt: serverTimestamp(),
        });
      } else {
        await addDoc(collection(db, "masterclass_mentors"), {
          ...payload,
          createdAt: serverTimestamp(),
          rating: 0,
        });
      }
      fetchMentorsAndStats();
      setViewMode("list");
      setFormData({
        nama: "",
        gelar: "",
        jabatan: "",
        perusahaan: "",
        bio: "",
        fotoUrl: "",
        fotoPosition: "object-center",
        linkedIn: "",
        tarif: "",
        ttdUrl: "", // Reset field TTD
      });
      setEditId(null);
    } catch (error) {
      toast.error("Gagal menyimpan data");
    } finally {
      setIsProcessing(false);
    }
  };

  const deleteMentor = async (id: string) => {
    if (confirm("Yakin ingin menghapus mentor ini permanen?")) {
      await deleteDoc(doc(db, "masterclass_mentors", id));
      fetchMentorsAndStats();
    }
  };

  return (
    <div className="space-y-6 font-sans relative">
      {/* 🔥 MODAL PREVIEW MENTOR 🔥 */}
      {previewMentor && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-slate-900/80 backdrop-blur-sm animate-in fade-in">
          <div className="bg-white rounded-[2rem] max-w-md w-full shadow-2xl overflow-hidden relative">
            <button
              onClick={() => setPreviewMentor(null)}
              className="absolute top-4 right-4 w-8 h-8 bg-slate-100 hover:bg-rose-100 text-slate-500 hover:text-rose-600 rounded-full flex items-center justify-center font-bold transition-colors"
            >
              ✕
            </button>

            <div className="h-32 bg-gradient-to-r from-blue-600 to-indigo-700"></div>

            <div className="px-6 pb-8 text-center -mt-12">
              <div className="w-24 h-24 mx-auto rounded-full bg-white p-1 mb-3 shadow-md relative">
                <img
                  src={
                    previewMentor.fotoUrl ||
                    `https://ui-avatars.com/api/?name=${previewMentor.nama}&background=0D8ABC&color=fff`
                  }
                  alt="Mentor"
                  className={`w-full h-full rounded-full object-cover shadow-sm ${previewMentor.fotoPosition || "object-center"}`}
                />
              </div>
              <h3 className="text-xl font-black text-slate-900">
                {previewMentor.nama}, {previewMentor.gelar}
              </h3>
              <p className="text-sm font-bold text-blue-600 mb-1">
                {previewMentor.jabatan}
              </p>
              <p className="text-xs text-slate-500 font-medium mb-4">
                {previewMentor.perusahaan}
              </p>

              <div className="bg-slate-50 p-4 rounded-2xl border border-slate-100 mb-4 text-left">
                <p className="text-xs text-slate-600 leading-relaxed italic line-clamp-4">
                  "{previewMentor.bio}"
                </p>
              </div>

              {/* 🔥 PREVIEW TANDA TANGAN 🔥 */}
              {previewMentor.ttdUrl && (
                <div className="mb-4 pt-2">
                  <p className="text-[9px] uppercase font-bold text-slate-400 tracking-widest mb-2">
                    Pratinjau Tanda Tangan (Untuk E-Certificate)
                  </p>
                  <div className="bg-slate-50 rounded-xl p-2 border border-slate-200 border-dashed inline-block">
                    <img
                      src={previewMentor.ttdUrl}
                      alt="TTD Mentor"
                      className="h-12 object-contain mix-blend-multiply"
                    />
                  </div>
                </div>
              )}

              <div className="flex justify-center gap-4 border-t border-slate-100 pt-4 mt-2">
                <div className="text-center">
                  <p className="text-xl font-black text-slate-800">
                    {coursesCount[previewMentor.id] || 0}
                  </p>
                  <p className="text-[9px] uppercase font-bold text-slate-400 tracking-widest">
                    Total Kelas
                  </p>
                </div>
                <div className="w-px bg-slate-200"></div>
                <div className="text-center">
                  <p className="text-xl font-black text-amber-500">
                    ★ {previewMentor.rating || "5.0"}
                  </p>
                  <p className="text-[9px] uppercase font-bold text-slate-400 tracking-widest">
                    Rating
                  </p>
                </div>
              </div>
            </div>
          </div>
        </div>
      )}

      {viewMode === "list" ? (
        <>
          <div className="flex justify-between items-center bg-white p-5 rounded-2xl border border-slate-200 shadow-sm">
            <div>
              <h3 className="font-bold text-slate-800 text-lg tracking-tight">
                Database Mentor
              </h3>
            </div>
            <button
              onClick={() => {
                setEditId(null);
                setFormData({
                  nama: "",
                  gelar: "",
                  jabatan: "",
                  perusahaan: "",
                  bio: "",
                  fotoUrl: "",
                  fotoPosition: "object-center",
                  linkedIn: "",
                  tarif: "",
                  ttdUrl: "",
                });
                setViewMode("form");
              }}
              className="bg-[#0056D2] hover:bg-[#00419E] text-white px-5 py-2.5 rounded-xl text-xs font-bold shadow-sm transition-all"
            >
              + Tambah Mentor
            </button>
          </div>

          {/* LIST COMPACT MENTORS */}
          <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
            {isLoading ? (
              <div className="col-span-full text-center py-10 text-slate-400">
                <div className="w-8 h-8 border-4 border-slate-200 border-t-blue-600 rounded-full animate-spin mx-auto mb-3"></div>
                Memuat data ekspert...
              </div>
            ) : (
              mentors.map((m: any) => (
                <div
                  key={m.id}
                  className="bg-white rounded-2xl border border-slate-200 p-4 flex items-center justify-between gap-4 hover:shadow-md transition-shadow group"
                >
                  {/* Foto & Info Kiri */}
                  <div className="flex items-center gap-4 overflow-hidden">
                    <div className="w-12 h-12 rounded-full bg-slate-100 shrink-0 border border-slate-200 overflow-hidden relative">
                      {m.fotoUrl ? (
                        <img
                          src={m.fotoUrl}
                          className={`w-full h-full object-cover ${m.fotoPosition || "object-center"}`}
                          alt="foto"
                        />
                      ) : (
                        <span className="absolute inset-0 flex items-center justify-center text-xs font-bold text-slate-400">
                          M
                        </span>
                      )}
                    </div>
                    <div className="overflow-hidden">
                      <h4 className="font-bold text-slate-900 text-sm truncate flex items-center gap-1.5">
                        {m.nama}{" "}
                        <span className="text-slate-400 font-medium text-xs">
                          {m.gelar}
                        </span>
                        {/* Indikator TTD sudah ada/belum */}
                        {m.ttdUrl && (
                          <svg
                            className="w-3.5 h-3.5 text-emerald-500"
                            fill="none"
                            viewBox="0 0 24 24"
                            stroke="currentColor"
                          >
                            <path
                              strokeLinecap="round"
                              strokeLinejoin="round"
                              strokeWidth={2.5}
                              d="M15.232 5.232l3.536 3.536m-2.036-5.036a2.5 2.5 0 113.536 3.536L6.5 21.036H3v-3.572L16.732 3.732z"
                            />
                          </svg>
                        )}
                      </h4>
                      <p className="text-[10px] text-slate-500 truncate mt-0.5">
                        {m.jabatan} • {m.perusahaan}
                      </p>
                      <div className="flex items-center gap-3 mt-1.5">
                        <span className="text-[10px] font-bold text-blue-600 bg-blue-50 px-1.5 py-0.5 rounded">
                          {coursesCount[m.id] || 0} Kelas
                        </span>
                        {m.linkedIn && (
                          <a
                            href={m.linkedIn}
                            target="_blank"
                            rel="noreferrer"
                            className="text-[10px] text-slate-400 hover:text-blue-600 flex items-center gap-1 font-medium transition-colors"
                          >
                            <svg
                              className="w-3 h-3"
                              fill="currentColor"
                              viewBox="0 0 24 24"
                            >
                              <path d="M19 0h-14c-2.761 0-5 2.239-5 5v14c0 2.761 2.239 5 5 5h14c2.762 0 5-2.239 5-5v-14c0-2.761-2.238-5-5-5zm-11 19h-3v-11h3v11zm-1.5-12.268c-.966 0-1.75-.79-1.75-1.764s.784-1.764 1.75-1.764 1.75.79 1.75 1.764-.783 1.764-1.75 1.764zm13.5 12.268h-3v-5.604c0-3.368-4-3.113-4 0v5.604h-3v-11h3v1.765c1.396-2.586 7-2.777 7 2.476v6.759z" />
                            </svg>
                            Profil
                          </a>
                        )}
                      </div>
                    </div>
                  </div>

                  {/* Tombol Aksi Kanan */}
                  <div className="flex items-center gap-1.5 shrink-0 opacity-100 lg:opacity-0 lg:group-hover:opacity-100 transition-opacity">
                    <button
                      onClick={() => setPreviewMentor(m)}
                      title="Preview"
                      className="w-8 h-8 rounded-lg bg-slate-50 text-slate-500 hover:text-blue-600 hover:bg-blue-50 flex items-center justify-center transition-colors"
                    >
                      <svg
                        className="w-4 h-4"
                        fill="none"
                        viewBox="0 0 24 24"
                        stroke="currentColor"
                      >
                        <path
                          strokeLinecap="round"
                          strokeLinejoin="round"
                          strokeWidth={2}
                          d="M15 12a3 3 0 11-6 0 3 3 0 016 0z"
                        />
                        <path
                          strokeLinecap="round"
                          strokeLinejoin="round"
                          strokeWidth={2}
                          d="M2.458 12C3.732 7.943 7.523 5 12 5c4.478 0 8.268 2.943 9.542 7-1.274 4.057-5.064 7-9.542 7-4.477 0-8.268-2.943-9.542-7z"
                        />
                      </svg>
                    </button>
                    <button
                      onClick={() => {
                        setEditId(m.id);
                        setFormData(m);
                        setViewMode("form");
                      }}
                      title="Edit"
                      className="w-8 h-8 rounded-lg bg-slate-50 text-slate-500 hover:text-emerald-600 hover:bg-emerald-50 flex items-center justify-center transition-colors"
                    >
                      <svg
                        className="w-4 h-4"
                        fill="none"
                        viewBox="0 0 24 24"
                        stroke="currentColor"
                      >
                        <path
                          strokeLinecap="round"
                          strokeLinejoin="round"
                          strokeWidth={2}
                          d="M11 5H6a2 2 0 00-2 2v11a2 2 0 002 2h11a2 2 0 002-2v-5m-1.414-9.414a2 2 0 112.828 2.828L11.828 15H9v-2.828l8.586-8.586z"
                        />
                      </svg>
                    </button>
                    <button
                      onClick={() => deleteMentor(m.id)}
                      title="Hapus"
                      className="w-8 h-8 rounded-lg bg-slate-50 text-slate-500 hover:text-rose-600 hover:bg-rose-50 flex items-center justify-center transition-colors"
                    >
                      <svg
                        className="w-4 h-4"
                        fill="none"
                        viewBox="0 0 24 24"
                        stroke="currentColor"
                      >
                        <path
                          strokeLinecap="round"
                          strokeLinejoin="round"
                          strokeWidth={2}
                          d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16"
                        />
                      </svg>
                    </button>
                  </div>
                </div>
              ))
            )}
          </div>
        </>
      ) : (
        <form
          onSubmit={handleSave}
          className="bg-white rounded-3xl border border-slate-200 p-6 md:p-8 max-w-3xl mx-auto shadow-sm"
        >
          <div className="flex justify-between items-center mb-6 border-b border-slate-100 pb-4">
            <h3 className="text-xl font-black text-slate-900">
              {editId ? "Update Data Mentor" : "Registrasi Mentor Baru"}
            </h3>
          </div>

          <div className="grid grid-cols-1 sm:grid-cols-2 gap-5 mb-5">
            <div className="sm:col-span-2">
              <label className="block text-[11px] font-bold text-slate-500 uppercase tracking-widest mb-1.5 ml-1">
                Nama Lengkap Tanpa Gelar
              </label>
              <input
                required
                type="text"
                value={formData.nama}
                onChange={(e) =>
                  setFormData({ ...formData, nama: e.target.value })
                }
                className="w-full bg-slate-50 border border-slate-200 px-4 py-3 rounded-xl text-sm font-bold outline-none focus:bg-white focus:border-[#0056D2] transition-all"
              />
            </div>
            <div>
              <label className="block text-[11px] font-bold text-slate-500 uppercase tracking-widest mb-1.5 ml-1">
                Gelar Profesional
              </label>
              <input
                required
                type="text"
                value={formData.gelar}
                onChange={(e) =>
                  setFormData({ ...formData, gelar: e.target.value })
                }
                className="w-full bg-slate-50 border border-slate-200 px-4 py-3 rounded-xl text-sm font-bold outline-none focus:bg-white focus:border-[#0056D2] transition-all"
              />
            </div>
            <div>
              <label className="block text-[11px] font-bold text-slate-500 uppercase tracking-widest mb-1.5 ml-1">
                Jabatan Saat Ini
              </label>
              <input
                required
                type="text"
                value={formData.jabatan}
                onChange={(e) =>
                  setFormData({ ...formData, jabatan: e.target.value })
                }
                className="w-full bg-slate-50 border border-slate-200 px-4 py-3 rounded-xl text-sm font-bold outline-none focus:bg-white focus:border-[#0056D2] transition-all"
              />
            </div>
            <div>
              <label className="block text-[11px] font-bold text-slate-500 uppercase tracking-widest mb-1.5 ml-1">
                Perusahaan / Instansi
              </label>
              <input
                required
                type="text"
                value={formData.perusahaan}
                onChange={(e) =>
                  setFormData({ ...formData, perusahaan: e.target.value })
                }
                className="w-full bg-slate-50 border border-slate-200 px-4 py-3 rounded-xl text-sm font-bold outline-none focus:bg-white focus:border-[#0056D2] transition-all"
              />
            </div>
            <div>
              <label className="block text-[11px] font-bold text-slate-500 uppercase tracking-widest mb-1.5 ml-1">
                Tarif Kesepakatan (Rp)
              </label>
              <input
                required
                type="number"
                value={formData.tarif}
                onChange={(e) =>
                  setFormData({ ...formData, tarif: e.target.value })
                }
                className="w-full bg-white border-2 border-emerald-200 px-4 py-3 rounded-xl text-sm font-bold text-emerald-700 outline-none focus:border-emerald-500 transition-all"
                placeholder="0"
              />
            </div>

            <div className="sm:col-span-2">
              <label className="block text-[11px] font-bold text-slate-500 uppercase tracking-widest mb-1.5 ml-1">
                URL Profil LinkedIn
              </label>
              <input
                type="url"
                value={formData.linkedIn}
                onChange={(e) =>
                  setFormData({ ...formData, linkedIn: e.target.value })
                }
                className="w-full bg-slate-50 border border-slate-200 px-4 py-3 rounded-xl text-sm font-medium outline-none focus:bg-white focus:border-[#0056D2] transition-all"
                placeholder="https://linkedin.com/in/..."
              />
            </div>

            <div className="sm:col-span-2">
              <label className="block text-[11px] font-bold text-slate-500 uppercase tracking-widest mb-1.5 ml-1">
                Deskripsi Singkat / Bio Mentor
              </label>
              <textarea
                required
                rows={3}
                value={formData.bio}
                onChange={(e) =>
                  setFormData({ ...formData, bio: e.target.value })
                }
                className="w-full bg-slate-50 border border-slate-200 px-4 py-3 rounded-xl text-sm font-medium outline-none focus:bg-white focus:border-[#0056D2] transition-all resize-none"
                placeholder="Tuliskan latar belakang dan keahlian mentor secara singkat..."
              />
            </div>

            <div className="sm:col-span-2 p-5 bg-slate-50 border border-slate-200 rounded-2xl">
              <h4 className="text-[11px] font-black text-slate-800 uppercase tracking-widest mb-4 flex items-center gap-2">
                <svg
                  className="w-4 h-4 text-[#0056D2]"
                  fill="none"
                  viewBox="0 0 24 24"
                  stroke="currentColor"
                >
                  <path
                    strokeLinecap="round"
                    strokeLinejoin="round"
                    strokeWidth={2}
                    d="M4 16l4.586-4.586a2 2 0 012.828 0L16 16m-2-2l1.586-1.586a2 2 0 012.828 0L20 14m-6-6h.01M6 20h12a2 2 0 002-2V6a2 2 0 00-2-2H6a2 2 0 00-2 2v12a2 2 0 002 2z"
                  />
                </svg>
                Media Profil & Sertifikat
              </h4>
              <div className="grid grid-cols-1 sm:grid-cols-3 gap-4 mb-4">
                <div className="sm:col-span-2">
                  <label className="block text-[10px] font-bold text-slate-500 uppercase tracking-widest mb-1.5 ml-1">
                    URL Foto Profil (Cloudinary)
                  </label>
                  <input
                    required
                    type="url"
                    value={formData.fotoUrl}
                    onChange={(e) =>
                      setFormData({ ...formData, fotoUrl: e.target.value })
                    }
                    className="w-full bg-white border border-slate-300 px-4 py-3 rounded-xl text-sm font-medium outline-none focus:border-[#0056D2] transition-all"
                    placeholder="https://..."
                  />
                </div>
                <div>
                  <label className="block text-[10px] font-bold text-slate-500 uppercase tracking-widest mb-1.5 ml-1">
                    Posisi Crop Foto
                  </label>
                  <select
                    required
                    value={formData.fotoPosition}
                    onChange={(e) =>
                      setFormData({ ...formData, fotoPosition: e.target.value })
                    }
                    className="w-full bg-white border border-slate-300 px-4 py-3 rounded-xl text-sm font-bold text-slate-600 outline-none focus:border-[#0056D2] transition-all cursor-pointer"
                  >
                    <option value="object-top">Atas (Kepala)</option>
                    <option value="object-center">Tengah (Default)</option>
                    <option value="object-bottom">Bawah (Badan)</option>
                  </select>
                </div>
              </div>

              {/* 🔥 KOLOM URL TANDA TANGAN 🔥 */}
              <div>
                <label className="block text-[10px] font-bold text-slate-500 uppercase tracking-widest mb-1.5 ml-1">
                  URL Tanda Tangan Basah (WAJIB: PNG Transparan)
                </label>
                <input
                  type="url"
                  value={formData.ttdUrl}
                  onChange={(e) =>
                    setFormData({ ...formData, ttdUrl: e.target.value })
                  }
                  className="w-full bg-white border border-slate-300 px-4 py-3 rounded-xl text-sm font-medium outline-none focus:border-[#0056D2] transition-all"
                  placeholder="https://res.cloudinary.com/.../ttd-mentor.png"
                />
                <p className="text-[9px] font-bold text-slate-400 mt-1 ml-1">
                  *Akan digunakan sebagai TTD di e-certificate. Pastikan format
                  PNG tanpa background warna putih.
                </p>
              </div>
            </div>
          </div>

          <div className="flex justify-end gap-3 pt-6 border-t border-slate-100">
            <button
              type="button"
              onClick={() => setViewMode("list")}
              className="px-6 py-3 text-sm font-bold text-slate-500 bg-slate-50 hover:bg-slate-100 rounded-xl transition-colors"
            >
              Batal
            </button>
            <button
              disabled={isProcessing}
              type="submit"
              className="px-8 py-3 text-sm font-bold text-white bg-[#0056D2] hover:bg-[#00419E] rounded-xl transition-all shadow-md shadow-blue-500/20 disabled:opacity-50"
            >
              Simpan Profil Mentor
            </button>
          </div>
        </form>
      )}
    </div>
  );
}

"use client";

import { useState, useEffect } from "react";
import { db } from "@/lib/firebase";
import { doc, getDoc, setDoc, serverTimestamp } from "firebase/firestore";

export default function TabPengaturanCMS() {
  const [activeSubTab, setActiveSubTab] = useState("ui"); // 'ui', 'promo', 'roles'
  const [isLoading, setIsLoading] = useState(true);
  const [isSaving, setIsSaving] = useState(false);
  const [popup, setPopup] = useState<{
    type: "success" | "error";
    text: string;
  } | null>(null);

  // --- DATA STATE CMS (MURNI TANPA PAYMENT) ---
  const [cmsData, setCmsData] = useState({
    // 1. Tampilan Landing Page
    heroTitle: "Tingkatkan Skill Ekspertis Bersama Praktisi Terbaik.",
    heroSubtitle:
      "Akses ratusan materi video pembelajaran berkualitas tinggi yang dirancang khusus untuk kebutuhan industri masa kini.",
    heroBgUrl: "",

    // 2. Promo & Ads (Announcement Bar & Kupon)
    promoActive: false,
    promoText:
      "🔥 DISKON SPESIAL: Gunakan kode KEBERSAMAAN untuk diskon 50% seluruh kelas!",
    promoLink: "/masterclass",
    promoCode: "",
    promoDiscount: 0,
  });

  useEffect(() => {
    fetchCmsSettings();
  }, []);

  const fetchCmsSettings = async () => {
    setIsLoading(true);
    try {
      const docSnap = await getDoc(doc(db, "settings", "masterclass_cms"));
      if (docSnap.exists()) {
        setCmsData((prev) => ({ ...prev, ...docSnap.data() }));
      }
    } catch (error) {
      console.error("Gagal load CMS:", error);
    } finally {
      setIsLoading(false);
    }
  };

  const handleSave = async () => {
    setIsSaving(true);
    try {
      const payload = {
        ...cmsData,
        promoDiscount: Number(cmsData.promoDiscount) || 0,
        updatedAt: serverTimestamp(),
      };

      await setDoc(doc(db, "settings", "masterclass_cms"), payload);
      setPopup({ type: "success", text: "Konfigurasi CMS Berhasil Disimpan!" });
    } catch (err) {
      setPopup({ type: "error", text: "Gagal menyimpan perubahan." });
    } finally {
      setIsSaving(false);
      setTimeout(() => setPopup(null), 3000);
    }
  };

  if (isLoading) {
    return (
      <div className="py-20 text-center text-slate-400 font-bold animate-pulse tracking-widest">
        MEMUAT KONFIGURASI CMS...
      </div>
    );
  }

  return (
    <div className="flex flex-col lg:flex-row gap-6 font-sans relative">
      {/* POPUP NOTIF */}
      {popup && (
        <div className="fixed top-6 right-6 z-[100] animate-in slide-in-from-top-4 fade-in">
          <div
            className={`${popup.type === "success" ? "bg-emerald-600" : "bg-rose-600"} text-white px-6 py-3 rounded-2xl shadow-2xl font-bold text-sm`}
          >
            {popup.text}
          </div>
        </div>
      )}

      {/* LEFT: SUB-NAVIGASI CMS */}
      <aside className="w-full lg:w-64 shrink-0">
        <div className="bg-white border border-slate-200 rounded-2xl overflow-hidden shadow-sm sticky top-5">
          <div className="p-4 border-b border-slate-100 bg-slate-50">
            <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">
              Kontrol Konten
            </p>
          </div>
          <nav className="p-2 space-y-1">
            {[
              { id: "ui", label: "Tampilan Utama", icon: "🖼️" },
              { id: "promo", label: "Promo & Kupon", icon: "🎟️" },
              { id: "roles", label: "Akses & Role", icon: "🔐" },
            ].map((t) => (
              <button
                key={t.id}
                onClick={() => setActiveSubTab(t.id)}
                className={`w-full flex items-center gap-3 px-4 py-3 rounded-xl text-sm font-bold transition-all ${activeSubTab === t.id ? "bg-[#0B1120] text-white shadow-md" : "text-slate-500 hover:bg-slate-100"}`}
              >
                <span>{t.icon}</span> {t.label}
              </button>
            ))}
          </nav>
        </div>
      </aside>

      {/* RIGHT: CONTENT FORM */}
      <div className="flex-1 bg-white border border-slate-200 rounded-3xl shadow-sm p-6 md:p-10 relative overflow-hidden">
        {/* TAB 1: UI SETTINGS */}
        {activeSubTab === "ui" && (
          <div className="space-y-6 animate-in fade-in duration-300">
            <div>
              <h3 className="text-xl font-black text-slate-900">
                Visual Homepage
              </h3>
              <p className="text-xs text-slate-500">
                Atur teks penyambutan dan banner di halaman depan Masterclass.
              </p>
            </div>
            <div className="space-y-4">
              <div>
                <label className="block text-[11px] font-bold text-slate-400 uppercase mb-1.5">
                  Hero Title (Tagline Utama)
                </label>
                <input
                  type="text"
                  value={cmsData.heroTitle}
                  onChange={(e) =>
                    setCmsData({ ...cmsData, heroTitle: e.target.value })
                  }
                  className="w-full bg-slate-50 border border-slate-200 px-4 py-3 rounded-xl focus:bg-white focus:border-blue-500 outline-none text-sm font-bold"
                />
              </div>
              <div>
                <label className="block text-[11px] font-bold text-slate-400 uppercase mb-1.5">
                  Hero Subtitle
                </label>
                <textarea
                  rows={3}
                  value={cmsData.heroSubtitle}
                  onChange={(e) =>
                    setCmsData({ ...cmsData, heroSubtitle: e.target.value })
                  }
                  className="w-full bg-slate-50 border border-slate-200 px-4 py-3 rounded-xl focus:bg-white focus:border-blue-500 outline-none text-sm leading-relaxed"
                />
              </div>
              <div>
                <label className="block text-[11px] font-bold text-slate-400 uppercase mb-1.5">
                  Background Banner URL
                </label>
                <input
                  type="text"
                  value={cmsData.heroBgUrl}
                  onChange={(e) =>
                    setCmsData({ ...cmsData, heroBgUrl: e.target.value })
                  }
                  className="w-full bg-slate-50 border border-slate-200 px-4 py-3 rounded-xl focus:bg-white focus:border-blue-500 outline-none text-sm font-mono"
                  placeholder="https://..."
                />
              </div>
            </div>
          </div>
        )}

        {/* TAB 2: PROMO & KUPON */}
        {activeSubTab === "promo" && (
          <div className="space-y-6 animate-in fade-in duration-300">
            <div className="flex justify-between items-center">
              <div>
                <h3 className="text-xl font-black text-slate-900">
                  Sistem Promo & Kupon Diskon
                </h3>
                <p className="text-xs text-slate-500">
                  Aktifkan pita pengumuman dan buat kode voucher potongan harga.
                </p>
              </div>
              <label className="relative inline-flex items-center cursor-pointer shrink-0">
                <input
                  type="checkbox"
                  checked={cmsData.promoActive}
                  onChange={(e) =>
                    setCmsData({ ...cmsData, promoActive: e.target.checked })
                  }
                  className="sr-only peer"
                />
                <div className="w-12 h-6 bg-slate-200 rounded-full peer peer-checked:after:translate-x-full peer-checked:bg-blue-600 after:content-[''] after:absolute after:top-[2px] after:left-[2px] after:bg-white after:rounded-full after:h-5 after:w-5 after:transition-all"></div>
              </label>
            </div>

            <div
              className={`transition-all ${!cmsData.promoActive ? "opacity-30 pointer-events-none" : ""}`}
            >
              {/* Bagian 1: Announcement Bar */}
              <div className="bg-slate-50 p-5 rounded-2xl border border-slate-200 mb-6 space-y-4">
                <h4 className="text-xs font-black text-slate-800 uppercase tracking-widest border-b border-slate-200 pb-2">
                  1. Pita Pengumuman (Header)
                </h4>
                <div>
                  <label className="block text-[11px] font-bold text-slate-500 uppercase mb-1.5">
                    Teks Pengumuman
                  </label>
                  <input
                    type="text"
                    value={cmsData.promoText}
                    onChange={(e) =>
                      setCmsData({ ...cmsData, promoText: e.target.value })
                    }
                    className="w-full bg-white border border-slate-200 px-4 py-3 rounded-xl focus:border-blue-500 outline-none text-sm font-bold text-blue-600"
                  />
                </div>
                <div>
                  <label className="block text-[11px] font-bold text-slate-500 uppercase mb-1.5">
                    Link Tujuan (Opsional)
                  </label>
                  <input
                    type="text"
                    value={cmsData.promoLink}
                    onChange={(e) =>
                      setCmsData({ ...cmsData, promoLink: e.target.value })
                    }
                    className="w-full bg-white border border-slate-200 px-4 py-3 rounded-xl focus:border-blue-500 outline-none text-sm"
                    placeholder="/masterclass/course-id"
                  />
                </div>
              </div>

              {/* Bagian 2: Voucher / Kupon Diskon */}
              <div className="bg-amber-50 p-5 rounded-2xl border border-amber-200 space-y-4">
                <h4 className="text-xs font-black text-amber-800 uppercase tracking-widest border-b border-amber-200/50 pb-2">
                  2. Kode Voucher Pembayaran
                </h4>
                <p className="text-xs text-amber-700 font-medium">
                  Jika diisi, peserta bisa memasukkan kode ini saat Checkout
                  untuk memotong harga.
                </p>

                <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                  <div>
                    <label className="block text-[11px] font-bold text-amber-700 uppercase mb-1.5">
                      Kode Kupon Unik
                    </label>
                    <input
                      type="text"
                      value={cmsData.promoCode}
                      onChange={(e) =>
                        setCmsData({
                          ...cmsData,
                          promoCode: e.target.value
                            .toUpperCase()
                            .replace(/\s/g, ""),
                        })
                      }
                      className="w-full bg-white border border-amber-200 px-4 py-3 rounded-xl focus:border-amber-500 outline-none text-sm font-black text-amber-700 tracking-widest placeholder-amber-200"
                      placeholder="Cth: MERDEKA50"
                    />
                  </div>
                  <div>
                    <label className="block text-[11px] font-bold text-amber-700 uppercase mb-1.5">
                      Besaran Diskon (%)
                    </label>
                    <div className="flex items-center gap-2 bg-white border border-amber-200 px-4 py-3 rounded-xl focus-within:border-amber-500">
                      <input
                        type="number"
                        min="0"
                        max="100"
                        value={cmsData.promoDiscount}
                        onChange={(e) =>
                          setCmsData({
                            ...cmsData,
                            promoDiscount: Number(e.target.value),
                          })
                        }
                        className="w-full bg-transparent outline-none text-sm font-black text-amber-700"
                        placeholder="50"
                      />
                      <span className="text-amber-500 font-black">%</span>
                    </div>
                  </div>
                </div>
              </div>
            </div>
          </div>
        )}

        {/* TAB 3: ROLES */}
        {activeSubTab === "roles" && (
          <div className="space-y-6 animate-in fade-in duration-300">
            <div>
              <h3 className="text-xl font-black text-slate-900">
                User Roles & Access
              </h3>
              <p className="text-xs text-slate-500">
                Kelola siapa saja yang bisa mengakses dashboard admin ini.
              </p>
            </div>
            <div className="flex gap-2">
              <input
                type="text"
                placeholder="Masukkan Email User..."
                className="flex-1 bg-slate-50 border border-slate-200 px-4 py-3 rounded-xl text-sm"
              />
              <button className="px-6 py-3 bg-blue-600 text-white font-bold rounded-xl text-sm">
                Cari & Atur
              </button>
            </div>
            <div className="p-8 text-center text-slate-300 italic text-sm bg-slate-50 rounded-2xl border border-dashed border-slate-200">
              Fitur pencarian user dan penetapan role sedang dihubungkan ke
              sistem inti.
            </div>
          </div>
        )}

        {/* FOOTER SAVE BUTTON */}
        <div className="mt-12 pt-6 border-t border-slate-100 flex justify-end">
          <button
            onClick={handleSave}
            disabled={isSaving}
            className="bg-[#0B1120] hover:bg-slate-800 text-white font-black px-10 py-4 rounded-2xl transition-all shadow-xl shadow-slate-900/20 disabled:opacity-50 flex items-center gap-3"
          >
            {isSaving ? "MENYIMPAN..." : "SIMPAN PERUBAHAN CMS"}
          </button>
        </div>
      </div>
    </div>
  );
}

"use client";

import { useState, useEffect } from "react";
import { toast } from "@/lib/toast";
import { db } from "@/lib/firebase";
import {
  collection,
  getDocs,
  doc,
  updateDoc,
  deleteDoc,
  query,
  orderBy,
} from "firebase/firestore";

export default function TabReviews() {
  const [reviews, setReviews] = useState<any[]>([]);
  const [courses, setCourses] = useState<any[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [searchTerm, setSearchTerm] = useState("");
  const [filterRating, setFilterRating] = useState("Semua");

  useEffect(() => {
    fetchData();
  }, []);

  const fetchData = async () => {
    setIsLoading(true);
    try {
      // 1. Ambil Data Kelas untuk mapping Nama Kelas
      const snapCourses = await getDocs(collection(db, "masterclass_courses"));
      const coursesData = snapCourses.docs.map((d) => ({
        id: d.id,
        judul: d.data().judul,
      }));
      setCourses(coursesData);

      // 2. Ambil Data Ulasan (Reviews)
      const qReviews = query(
        collection(db, "masterclass_reviews"),
        orderBy("createdAt", "desc"),
      );
      const snapReviews = await getDocs(qReviews);
      setReviews(snapReviews.docs.map((d) => ({ id: d.id, ...d.data() })));
    } catch (error) {
      console.error("Gagal memuat data ulasan:", error);
    } finally {
      setIsLoading(false);
    }
  };

  const getCourseName = (courseId: string) => {
    const course = courses.find((c) => c.id === courseId);
    return course ? course.judul : "Kelas Tidak Diketahui / Dihapus";
  };

  const handleToggleStatus = async (
    reviewId: string,
    currentStatus: string,
  ) => {
    const newStatus = currentStatus === "Sembunyi" ? "Tampil" : "Sembunyi";
    if (
      !confirm(
        `Ubah status ulasan ini menjadi "${newStatus}" di halaman publik?`,
      )
    )
      return;

    try {
      await updateDoc(doc(db, "masterclass_reviews", reviewId), {
        status: newStatus,
        updatedAt: new Date().toISOString(),
      });
      fetchData();
    } catch (error) {
      toast.error("Gagal memperbarui status ulasan.");
    }
  };

  const handleDelete = async (reviewId: string) => {
    if (!confirm("Hapus permanen ulasan ini dari database?")) return;
    try {
      await deleteDoc(doc(db, "masterclass_reviews", reviewId));
      fetchData();
    } catch (error) {
      toast.error("Gagal menghapus data.");
    }
  };

  const filteredList = reviews.filter((r) => {
    const matchSearch =
      (r.namaPeserta || "").toLowerCase().includes(searchTerm.toLowerCase()) ||
      (r.ulasan || "").toLowerCase().includes(searchTerm.toLowerCase());
    const matchRating =
      filterRating === "Semua"
        ? true
        : Number(r.rating) === Number(filterRating);
    return matchSearch && matchRating;
  });

  const renderStars = (rating: number) => {
    return (
      <div className="flex gap-0.5">
        {[1, 2, 3, 4, 5].map((star) => (
          <svg
            key={star}
            className={`w-3.5 h-3.5 ${star <= rating ? "text-yellow-400" : "text-slate-200"}`}
            fill="currentColor"
            viewBox="0 0 20 20"
          >
            <path d="M9.049 2.927c.3-.921 1.603-.921 1.902 0l1.07 3.292a1 1 0 00.95.69h3.462c.969 0 1.371 1.24.588 1.81l-2.8 2.034a1 1 0 00-.364 1.118l1.07 3.292c.3.921-.755 1.688-1.54 1.118l-2.8-2.034a1 1 0 00-1.175 0l-2.8 2.034c-.784.57-1.838-.197-1.539-1.118l1.07-3.292a1 1 0 00-.364-1.118L2.98 8.72c-.783-.57-.38-1.81.588-1.81h3.461a1 1 0 00.951-.69l1.07-3.292z" />
          </svg>
        ))}
      </div>
    );
  };

  return (
    <div className="space-y-6 font-sans">
      {/* HEADER & STATISTIK */}
      <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4 bg-white p-6 rounded-3xl border border-slate-200 shadow-sm">
        <div>
          <h3 className="font-bold text-slate-800 text-lg tracking-tight">
            Rating & Ulasan Kelas
          </h3>
          <p className="text-xs text-slate-500 font-medium mt-1">
            Moderasi testimoni dari peserta untuk menjaga kualitas platform.
          </p>
        </div>
        <div className="flex gap-3 w-full md:w-auto">
          <div className="bg-slate-50 border border-slate-100 px-5 py-2 rounded-xl text-center flex-1 md:flex-none">
            <div className="text-[10px] font-bold text-slate-400 uppercase tracking-widest">
              Total Ulasan
            </div>
            <div className="text-lg font-black text-slate-700">
              {reviews.length}
            </div>
          </div>
          <div className="bg-blue-50 border border-blue-100 px-5 py-2 rounded-xl text-center flex-1 md:flex-none">
            <div className="text-[10px] font-bold text-blue-500 uppercase tracking-widest">
              Rata-rata
            </div>
            <div className="text-lg font-black text-blue-700">
              {reviews.length > 0
                ? (
                    reviews.reduce(
                      (acc, curr) => acc + Number(curr.rating || 0),
                      0,
                    ) / reviews.length
                  ).toFixed(1)
                : "0.0"}
            </div>
          </div>
        </div>
      </div>

      {/* FILTER BAR */}
      <div className="bg-white p-5 rounded-3xl shadow-sm border border-slate-200 flex flex-col md:flex-row gap-4 items-center">
        <div className="relative w-full md:flex-1">
          <svg
            className="absolute left-4 top-1/2 -translate-y-1/2 w-4 h-4 text-slate-400"
            fill="none"
            viewBox="0 0 24 24"
            stroke="currentColor"
          >
            <path
              strokeLinecap="round"
              strokeLinejoin="round"
              strokeWidth={2.5}
              d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z"
            />
          </svg>
          <input
            type="text"
            placeholder="Cari isi ulasan atau nama peserta..."
            value={searchTerm}
            onChange={(e) => setSearchTerm(e.target.value)}
            className="w-full bg-slate-50 border border-slate-200 py-2.5 pl-11 pr-4 rounded-xl text-sm font-medium focus:border-blue-500 focus:bg-white outline-none transition-all"
          />
        </div>
        <div className="w-full md:w-48 shrink-0 relative">
          <select
            value={filterRating}
            onChange={(e) => setFilterRating(e.target.value)}
            className="w-full bg-slate-50 border border-slate-200 py-2.5 px-4 rounded-xl text-sm font-bold text-slate-600 focus:border-blue-500 focus:bg-white outline-none appearance-none cursor-pointer"
          >
            <option value="Semua">Semua Rating</option>
            <option value="5">Bintang 5</option>
            <option value="4">Bintang 4</option>
            <option value="3">Bintang 3</option>
            <option value="2">Bintang 2</option>
            <option value="1">Bintang 1</option>
          </select>
        </div>
      </div>

      {/* TABEL LIST ULASAN */}
      <div className="bg-white border border-slate-200 rounded-3xl overflow-hidden shadow-sm">
        <div className="overflow-x-auto">
          <table className="w-full text-left text-sm border-collapse">
            <thead>
              <tr className="bg-slate-50/80 text-[10px] font-black uppercase text-slate-500 tracking-widest border-b border-slate-200">
                <th className="px-6 py-5">Peserta</th>
                <th className="px-4 py-5 w-48">Kelas</th>
                <th className="px-4 py-5">Isi Ulasan & Rating</th>
                <th className="px-4 py-5 text-center">Visibilitas</th>
                <th className="px-6 py-5 text-right w-32">Aksi</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-100">
              {isLoading ? (
                <tr>
                  <td
                    colSpan={5}
                    className="py-20 text-center text-slate-400 font-bold tracking-widest"
                  >
                    MEMUAT ULASAN...
                  </td>
                </tr>
              ) : filteredList.length === 0 ? (
                <tr>
                  <td
                    colSpan={5}
                    className="py-20 text-center text-slate-400 font-medium"
                  >
                    Belum ada ulasan yang sesuai kriteria.
                  </td>
                </tr>
              ) : (
                filteredList.map((r) => (
                  <tr
                    key={r.id}
                    className={`hover:bg-slate-50/80 transition-colors ${r.status === "Sembunyi" ? "bg-amber-50/30 opacity-70" : ""}`}
                  >
                    {/* Peserta */}
                    <td className="px-6 py-5 align-top">
                      <div className="flex items-center gap-3">
                        <div className="w-10 h-10 rounded-full bg-slate-100 flex items-center justify-center text-slate-500 font-bold border border-slate-200 shrink-0">
                          {(r.namaPeserta || "A").charAt(0).toUpperCase()}
                        </div>
                        <div>
                          <h4 className="font-bold text-slate-800 text-sm">
                            {r.namaPeserta}
                          </h4>
                          <div className="text-[10px] text-slate-400 font-medium mt-0.5">
                            {r.createdAt?.seconds
                              ? new Date(
                                  r.createdAt.seconds * 1000,
                                ).toLocaleDateString("id-ID")
                              : "Baru saja"}
                          </div>
                        </div>
                      </div>
                    </td>

                    {/* Kelas */}
                    <td className="px-4 py-5 align-top">
                      <div className="text-[10px] font-bold text-blue-600 bg-blue-50 px-2 py-1 rounded inline-block line-clamp-2 border border-blue-100 leading-relaxed">
                        {getCourseName(r.courseId)}
                      </div>
                    </td>

                    {/* Ulasan & Rating */}
                    <td className="px-4 py-5 align-top max-w-sm">
                      <div className="mb-2">
                        {renderStars(Number(r.rating || 0))}
                      </div>
                      <p
                        className="text-sm text-slate-600 leading-relaxed italic line-clamp-3"
                        title={r.ulasan}
                      >
                        "{r.ulasan}"
                      </p>
                    </td>

                    {/* Visibilitas (Status) */}
                    <td className="px-4 py-5 align-top text-center">
                      <span
                        className={`text-[9px] font-black px-2.5 py-1 rounded-md uppercase tracking-wider ${r.status === "Sembunyi" ? "bg-amber-100 text-amber-700" : "bg-emerald-100 text-emerald-700"}`}
                      >
                        {r.status === "Sembunyi" ? "HIDDEN" : "TAMPIL"}
                      </span>
                    </td>

                    {/* Aksi */}
                    <td className="px-6 py-5 align-top">
                      <div className="flex items-center justify-end gap-2">
                        <button
                          onClick={() =>
                            handleToggleStatus(r.id, r.status || "Tampil")
                          }
                          title={
                            r.status === "Sembunyi"
                              ? "Tampilkan Publik"
                              : "Sembunyikan"
                          }
                          className={`p-2 rounded-lg transition-colors border ${r.status === "Sembunyi" ? "text-emerald-600 hover:bg-emerald-50 border-transparent hover:border-emerald-200" : "text-amber-600 hover:bg-amber-50 border-transparent hover:border-amber-200"}`}
                        >
                          {r.status === "Sembunyi" ? (
                            <svg
                              className="w-4 h-4"
                              fill="none"
                              viewBox="0 0 24 24"
                              stroke="currentColor"
                            >
                              <path
                                strokeLinecap="round"
                                strokeLinejoin="round"
                                strokeWidth={2}
                                d="M15 12a3 3 0 11-6 0 3 3 0 016 0z"
                              />
                              <path
                                strokeLinecap="round"
                                strokeLinejoin="round"
                                strokeWidth={2}
                                d="M2.458 12C3.732 7.943 7.523 5 12 5c4.478 0 8.268 2.943 9.542 7-1.274 4.057-5.064 7-9.542 7-4.477 0-8.268-2.943-9.542-7z"
                              />
                            </svg>
                          ) : (
                            <svg
                              className="w-4 h-4"
                              fill="none"
                              viewBox="0 0 24 24"
                              stroke="currentColor"
                            >
                              <path
                                strokeLinecap="round"
                                strokeLinejoin="round"
                                strokeWidth={2}
                                d="M13.875 18.825A10.05 10.05 0 0112 19c-4.478 0-8.268-2.943-9.543-7a9.97 9.97 0 011.563-3.029m5.858.908a3 3 0 114.243 4.243M9.878 9.878l4.242 4.242M9.88 9.88l-3.29-3.29m7.532 7.532l3.29 3.29M3 3l3.29 3.29m0 0a9.953 9.953 0 013.37-1.55m1.5-1.5a10.05 10.05 0 013.37 1.55m0 0l3.29 3.29m0 0a9.97 9.97 0 011.563 3.029c-.115.366-.245.72-.39 1.05"
                              />
                            </svg>
                          )}
                        </button>
                        <button
                          onClick={() => handleDelete(r.id)}
                          title="Hapus Ulasan"
                          className="p-2 text-slate-400 hover:text-rose-600 hover:bg-rose-50 rounded-lg transition-colors border border-transparent hover:border-rose-200"
                        >
                          <svg
                            className="w-4 h-4"
                            fill="none"
                            viewBox="0 0 24 24"
                            stroke="currentColor"
                          >
                            <path
                              strokeLinecap="round"
                              strokeLinejoin="round"
                              strokeWidth={2}
                              d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16"
                            />
                          </svg>
                        </button>
                      </div>
                    </td>
                  </tr>
                ))
              )}
            </tbody>
          </table>
        </div>
      </div>
    </div>
  );
}

"use client";

import { useState, useEffect } from "react";
import { toast } from "@/lib/toast";
import { db } from "@/lib/firebase";
import {
  collection,
  getDocs,
  doc,
  updateDoc,
  deleteDoc,
  writeBatch,
  query,
  orderBy,
  serverTimestamp,
} from "firebase/firestore";
import * as XLSX from "xlsx";

export default function TabParticipants() {
  const [data, setData] = useState<any[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [isProcessing, setIsProcessing] = useState(false);

  // 🔥 STATE MANAJEMEN TABEL 🔥
  const [selectedIds, setSelectedIds] = useState<string[]>([]);
  const [searchTerm, setSearchBar] = useState("");
  const [filterStatus, setFilterStatus] = useState("Semua");
  const [selectedBukti, setSelectedBukti] = useState<string | null>(null);

  useEffect(() => {
    fetchAllData();
  }, []);

  const fetchAllData = async () => {
    setIsLoading(true);
    try {
      // 1. Ambil Nama Kelas untuk Mapping
      const coursesSnap = await getDocs(collection(db, "masterclass_courses"));
      const courseMap: Record<string, string> = {};
      coursesSnap.forEach((d) => {
        courseMap[d.id] = d.data().judul;
      });

      // 2. Ambil Data Enrollment (Transaksi)
      const q = query(
        collection(db, "masterclass_enrollments"),
        orderBy("createdAt", "desc"),
      );
      const snap = await getDocs(q);
      const enrollments = snap.docs.map((d) => ({
        id: d.id,
        ...d.data(),
        judulKelas: courseMap[d.data().courseId] || "Kelas Terhapus",
      }));

      setData(enrollments);
    } catch (error) {
      console.error(error);
    } finally {
      setIsLoading(false);
    }
  };

  // 🔥 FUNGSI EXPORT EXCEL ASLI (.xlsx) 🔥
  const exportToExcel = () => {
    const excelData = filteredData.map((e) => ({
      "ID INVOICE": `INV-${e.id.substring(0, 8)}`.toUpperCase(),
      "NAMA LENGKAP": e.namaPeserta,
      EMAIL: e.emailPeserta,
      KELAS: e.judulKelas,
      TIPE: e.tipeHarga,
      "TOTAL BAYAR": e.hargaTransaksi,
      "STATUS AKSES": e.statusAkses,
      "TANGGAL DAFTAR": e.createdAt?.toDate
        ? e.createdAt.toDate().toLocaleString("id-ID")
        : "-",
    }));

    const worksheet = XLSX.utils.json_to_sheet(excelData);
    const workbook = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(workbook, worksheet, "Data Peserta");

    // Atur Lebar Kolom
    worksheet["!cols"] = [
      { wch: 15 },
      { wch: 25 },
      { wch: 30 },
      { wch: 45 },
      { wch: 10 },
      { wch: 15 },
      { wch: 15 },
      { wch: 25 },
    ];

    XLSX.writeFile(workbook, `Laporan_Masterclass_IKA_UII_${Date.now()}.xlsx`);
  };

  // 🔥 FUNGSI BULK ACTIONS 🔥
  const handleBulkApprove = async () => {
    if (!confirm(`Setujui akses untuk ${selectedIds.length} peserta ini?`))
      return;
    setIsProcessing(true);
    try {
      const batch = writeBatch(db);
      selectedIds.forEach((id) => {
        batch.update(doc(db, "masterclass_enrollments", id), {
          statusAkses: "Lunas",
          updatedAt: serverTimestamp(),
        });
      });
      await batch.commit();
      setSelectedIds([]);
      await fetchAllData();
    } catch (err) {
      toast.error("Gagal approve massal");
    }
    setIsProcessing(false);
  };

  const handleBulkDelete = async () => {
    if (
      !confirm(
        `HAPUS PERMANEN ${selectedIds.length} data? Tindakan ini tidak bisa dibatalkan!`,
      )
    )
      return;
    setIsProcessing(true);
    try {
      const batch = writeBatch(db);
      selectedIds.forEach((id) => {
        batch.delete(doc(db, "masterclass_enrollments", id));
      });
      await batch.commit();
      setSelectedIds([]);
      await fetchAllData();
    } catch (err) {
      toast.error("Gagal hapus massal");
    }
    setIsProcessing(false);
  };

  const toggleSelect = (id: string) => {
    setSelectedIds((prev) =>
      prev.includes(id) ? prev.filter((i) => i !== id) : [...prev, id],
    );
  };

  const filteredData = data.filter((e) => {
    const matchSearch =
      e.namaPeserta?.toLowerCase().includes(searchTerm.toLowerCase()) ||
      e.emailPeserta?.toLowerCase().includes(searchTerm.toLowerCase());
    const matchStatus =
      filterStatus === "Semua" || e.statusAkses === filterStatus;
    return matchSearch && matchStatus;
  });

  // Filter ID yang diizinkan untuk di-select all (Abaikan Midtrans Pending)
  const allowableIds = filteredData
    .filter(
      (d) =>
        !(
          d.statusAkses === "Pending" &&
          !d.buktiTransferUrl &&
          d.tipeHarga !== "Gratis"
        ),
    )
    .map((d) => d.id);

  return (
    <div className="space-y-5 font-sans">
      {/* MODAL PREVIEW BUKTI */}
      {selectedBukti && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-slate-900/90 backdrop-blur-md animate-in fade-in">
          <div className="bg-white rounded-3xl max-w-lg w-full p-6 shadow-2xl overflow-hidden">
            <div className="flex justify-between items-center mb-4">
              <h3 className="font-black text-slate-800">
                Verifikasi Bukti Transfer
              </h3>
              <button
                onClick={() => setSelectedBukti(null)}
                className="p-2 hover:bg-slate-100 rounded-full"
              >
                ✕
              </button>
            </div>
            <div className="bg-slate-100 rounded-2xl p-2 mb-6">
              <img
                src={selectedBukti}
                alt="Bukti"
                className="w-full h-auto max-h-[60vh] object-contain rounded-xl"
              />
            </div>
            <button
              onClick={() => setSelectedBukti(null)}
              className="w-full py-4 bg-[#0B1120] text-white font-bold rounded-2xl hover:bg-slate-800 transition-all"
            >
              Tutup Pratinjau
            </button>
          </div>
        </div>
      )}

      {/* TOOLBAR ATAS */}
      <div className="bg-white p-4 rounded-2xl border border-slate-200 shadow-sm flex flex-col lg:flex-row justify-between items-center gap-4">
        <div className="flex flex-wrap items-center gap-3 w-full lg:w-auto">
          <div className="relative flex-1 lg:flex-none">
            <input
              type="text"
              placeholder="Cari pendaftar..."
              value={searchTerm}
              onChange={(e) => setSearchBar(e.target.value)}
              className="pl-10 pr-4 py-2.5 bg-slate-50 border border-slate-200 rounded-xl text-sm outline-none focus:border-blue-500 w-full lg:w-64 font-medium"
            />
            <svg
              className="w-4 h-4 text-slate-400 absolute left-3.5 top-3"
              fill="none"
              viewBox="0 0 24 24"
              stroke="currentColor"
            >
              <path
                strokeLinecap="round"
                strokeLinejoin="round"
                strokeWidth={2}
                d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z"
              />
            </svg>
          </div>
          <select
            value={filterStatus}
            onChange={(e) => setFilterStatus(e.target.value)}
            className="px-4 py-2.5 bg-slate-50 border border-slate-200 rounded-xl text-sm font-bold outline-none cursor-pointer text-slate-600 focus:border-blue-500"
          >
            <option value="Semua">Semua Status</option>
            <option value="Pending">🕒 Pending</option>
            <option value="Lunas">✅ Lunas</option>
            <option value="Batal">❌ Batal</option>
          </select>
        </div>

        <div className="flex items-center gap-2 w-full lg:w-auto justify-end">
          {selectedIds.length > 0 ? (
            <div className="flex items-center gap-2 animate-in zoom-in duration-200 bg-blue-50 p-1.5 rounded-2xl border border-blue-100">
              <button
                onClick={handleBulkApprove}
                disabled={isProcessing}
                className="px-4 py-2 bg-emerald-600 text-white text-xs font-black rounded-xl shadow-md hover:bg-emerald-700 transition-all disabled:opacity-50"
              >
                APPROVE ({selectedIds.length})
              </button>
              <button
                onClick={handleBulkDelete}
                disabled={isProcessing}
                className="px-4 py-2 bg-rose-600 text-white text-xs font-black rounded-xl shadow-md hover:bg-rose-700 transition-all disabled:opacity-50"
              >
                HAPUS PERMANEN
              </button>
              <button
                onClick={() => setSelectedIds([])}
                className="p-2 text-slate-400 hover:text-slate-600"
              >
                ✕
              </button>
            </div>
          ) : (
            <button
              onClick={exportToExcel}
              className="px-5 py-2.5 bg-white border border-slate-200 text-slate-700 text-xs font-black rounded-xl hover:bg-slate-50 flex items-center gap-2 transition-all shadow-sm border-b-4 active:border-b-0 active:translate-y-1"
            >
              <svg
                className="w-4 h-4 text-emerald-600"
                fill="none"
                viewBox="0 0 24 24"
                stroke="currentColor"
              >
                <path
                  strokeLinecap="round"
                  strokeLinejoin="round"
                  strokeWidth={2}
                  d="M12 10v6m0 0l-3-3m3 3l3-3m2 8H7a2 2 0 01-2-2V5a2 2 0 012-2h5.586a1 1 0 01.707.293l5.414 5.414a1 1 0 01.293.707V19a2 2 0 01-2 2z"
                />
              </svg>
              EKSPORT EXCEL (.XLSX)
            </button>
          )}
        </div>
      </div>

      {/* TABEL DATA */}
      <div className="bg-white border border-slate-200 rounded-2xl overflow-hidden shadow-sm">
        <div className="overflow-x-auto">
          <table className="w-full text-left text-sm border-collapse">
            <thead>
              <tr className="bg-slate-50/80 text-[10px] font-black uppercase text-slate-500 tracking-[0.1em] border-b border-slate-200">
                <th className="px-6 py-5 w-10">
                  <input
                    type="checkbox"
                    onChange={(e) =>
                      setSelectedIds(e.target.checked ? allowableIds : [])
                    }
                    checked={
                      selectedIds.length > 0 &&
                      selectedIds.length === allowableIds.length
                    }
                    className="w-4 h-4 accent-blue-600 cursor-pointer rounded"
                  />
                </th>
                <th className="px-4 py-5">Peserta & Kontak</th>
                <th className="px-4 py-5">Kelas & Invoice</th>
                <th className="px-4 py-5 text-center">Status Akses</th>
                <th className="px-6 py-5 text-right">Aksi</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-100">
              {isLoading ? (
                <tr>
                  <td
                    colSpan={5}
                    className="py-24 text-center text-slate-400 font-bold tracking-widest"
                  >
                    MEMUAT DATA...
                  </td>
                </tr>
              ) : filteredData.length === 0 ? (
                <tr>
                  <td
                    colSpan={5}
                    className="py-24 text-center text-slate-400 font-medium"
                  >
                    Data tidak ditemukan.
                  </td>
                </tr>
              ) : (
                filteredData.map((e) => {
                  // LOGIKA PEMISAH MIDTRANS VS MANUAL
                  const isManual = !!e.buktiTransferUrl;
                  const isFree = e.tipeHarga === "Gratis";
                  const isMidtransPending =
                    e.statusAkses === "Pending" && !isManual && !isFree;

                  return (
                    <tr
                      key={e.id}
                      className={`hover:bg-slate-50/80 transition-colors ${selectedIds.includes(e.id) ? "bg-blue-50/40" : ""}`}
                    >
                      <td className="px-6 py-4">
                        <input
                          type="checkbox"
                          disabled={isMidtransPending}
                          checked={selectedIds.includes(e.id)}
                          onChange={() => toggleSelect(e.id)}
                          title={
                            isMidtransPending
                              ? "Menunggu validasi otomatis Midtrans"
                              : "Pilih untuk aksi"
                          }
                          className="w-4 h-4 accent-blue-600 cursor-pointer rounded disabled:opacity-30 disabled:cursor-not-allowed"
                        />
                      </td>
                      <td className="px-4 py-4">
                        <div className="font-black text-slate-900">
                          {e.namaPeserta}
                        </div>
                        <div className="text-[11px] text-slate-500 font-bold">
                          {e.emailPeserta}
                        </div>
                      </td>
                      <td className="px-4 py-4">
                        <div className="font-bold text-slate-700 line-clamp-1">
                          {e.judulKelas}
                        </div>
                        <div className="text-[10px] font-mono text-slate-400 uppercase mt-0.5 font-bold">
                          INV-{e.id.substring(0, 8)} •{" "}
                          <span className="text-blue-600">
                            Rp{" "}
                            {Number(e.hargaTransaksi).toLocaleString("id-ID")}
                          </span>
                        </div>
                      </td>
                      <td className="px-4 py-4 text-center">
                        <div className="flex flex-col items-center gap-1.5">
                          {e.statusAkses === "Lunas" ? (
                            <span className="text-[9px] font-black px-2.5 py-1 rounded-md uppercase tracking-wider bg-emerald-100 text-emerald-700">
                              ✅ LUNAS
                            </span>
                          ) : e.statusAkses === "Pending" ? (
                            isMidtransPending ? (
                              <span
                                className="text-[9px] font-black px-2.5 py-1 rounded-md uppercase tracking-wider bg-indigo-100 text-indigo-700 animate-pulse cursor-help"
                                title="Menunggu pembayaran via Gateway Midtrans"
                              >
                                🤖 SISTEM MIDTRANS
                              </span>
                            ) : (
                              <span className="text-[9px] font-black px-2.5 py-1 rounded-md uppercase tracking-wider bg-amber-100 text-amber-700 animate-pulse">
                                🕒 PENDING MANUAL
                              </span>
                            )
                          ) : (
                            <span className="text-[9px] font-black px-2.5 py-1 rounded-md uppercase tracking-wider bg-rose-100 text-rose-700">
                              ❌ {e.statusAkses}
                            </span>
                          )}

                          {isManual && (
                            <button
                              onClick={() =>
                                setSelectedBukti(e.buktiTransferUrl)
                              }
                              className="text-[10px] font-black text-blue-600 hover:text-blue-800 flex items-center gap-1 mt-1"
                            >
                              <svg
                                className="w-3 h-3"
                                fill="none"
                                viewBox="0 0 24 24"
                                stroke="currentColor"
                              >
                                <path
                                  strokeLinecap="round"
                                  strokeLinejoin="round"
                                  strokeWidth={2}
                                  d="M15 12a3 3 0 11-6 0 3 3 0 016 0z"
                                />
                                <path
                                  strokeLinecap="round"
                                  strokeLinejoin="round"
                                  strokeWidth={2}
                                  d="M2.458 12C3.732 7.943 7.523 5 12 5c4.478 0 8.268 2.943 9.542 7-1.274 4.057-5.064 7-9.542 7-4.477 0-8.268-2.943-9.542-7z"
                                />
                              </svg>
                              CEK STRUK
                            </button>
                          )}
                        </div>
                      </td>
                      <td className="px-6 py-4">
                        <div className="flex items-center justify-end gap-1.5">
                          {/* Email Notif */}
                          <a
                            href={`mailto:${e.emailPeserta}?subject=Update Pembayaran Masterclass: ${e.judulKelas}&body=Halo ${e.namaPeserta}, status pendaftaran Anda saat ini: ${e.statusAkses}.`}
                            title="Kirim Email"
                            className="p-2 text-slate-400 hover:text-blue-600 hover:bg-white hover:shadow-sm rounded-lg transition-all border border-transparent hover:border-slate-200"
                          >
                            <svg
                              className="w-4 h-4"
                              fill="none"
                              viewBox="0 0 24 24"
                              stroke="currentColor"
                            >
                              <path
                                strokeLinecap="round"
                                strokeLinejoin="round"
                                strokeWidth={2}
                                d="M3 8l7.89 5.26a2 2 0 002.22 0L21 8M5 19h14a2 2 0 002-2V7a2 2 0 00-2-2H5a2 2 0 00-2 2v10a2 2 0 002 2z"
                              />
                            </svg>
                          </a>

                          {/* Edit */}
                          <button
                            onClick={() =>
                              toast.info("Gunakan Modal Edit jika diperlukan")
                            }
                            title="Edit"
                            className="p-2 text-slate-400 hover:text-emerald-600 hover:bg-white hover:shadow-sm rounded-lg transition-all border border-transparent hover:border-slate-200"
                          >
                            <svg
                              className="w-4 h-4"
                              fill="none"
                              viewBox="0 0 24 24"
                              stroke="currentColor"
                            >
                              <path
                                strokeLinecap="round"
                                strokeLinejoin="round"
                                strokeWidth={2}
                                d="M11 5H6a2 2 0 00-2 2v11a2 2 0 002 2h11a2 2 0 002-2v-5m-1.414-9.414a2 2 0 112.828 2.828L11.828 15H9v-2.828l8.586-8.586z"
                              />
                            </svg>
                          </button>

                          {/* Hapus */}
                          <button
                            onClick={async () => {
                              if (confirm("Hapus pendaftar ini?")) {
                                await deleteDoc(
                                  doc(db, "masterclass_enrollments", e.id),
                                );
                                fetchAllData();
                              }
                            }}
                            title="Hapus"
                            className="p-2 text-slate-400 hover:text-rose-600 hover:bg-white hover:shadow-sm rounded-lg transition-all border border-transparent hover:border-slate-200"
                          >
                            <svg
                              className="w-4 h-4"
                              fill="none"
                              viewBox="0 0 24 24"
                              stroke="currentColor"
                            >
                              <path
                                strokeLinecap="round"
                                strokeLinejoin="round"
                                strokeWidth={2}
                                d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16"
                              />
                            </svg>
                          </button>
                        </div>
                      </td>
                    </tr>
                  );
                })
              )}
            </tbody>
          </table>
        </div>
      </div>
    </div>
  );
}

