                  const isSelected = selectedIds.includes(p.id);
                  return (
                    <tr
                      key={p.id}
                      className={`hover:bg-blue-50/30 transition-colors text-sm text-slate-700 ${isSelected ? "bg-blue-50/50" : ""}`}
