  _ttdName?: string; // Hanya dipakai untuk render PDF (Tidak masuk DB Proker)
  [key: string]: any;
}

// --- UTILS ---
const formatDateToID = (dateStr: string) => {
  if (!dateStr) return "";
  try {
    const d = new Date(dateStr);
    if (isNaN(d.getTime())) return dateStr;
    return d.toLocaleDateString("id-ID", {
      day: "numeric",
      month: "long",
      year: "numeric",
    });
  } catch {
    return dateStr;
  }
};

