              <button
                key={agenda.id}
                onClick={() => setSelectedAgenda(agenda)}
                className="text-left bg-white p-5 md:p-6 rounded-2xl border border-slate-200 shadow-sm hover:border-blue-500 hover:shadow-lg transition-all flex flex-col h-full"
