                  </div>
                  <span className="bg-slate-100 text-slate-500 text-[9px] md:text-[10px] font-bold px-3 py-1.5 rounded-full uppercase">
                    Pilih Gate
                  </span>
                </div>
                <h3 className="font-bold text-blue-950 leading-snug mb-1">
                  {agenda.judul}
                </h3>
              </button>
