          setHtmlContent(docSnap.data().content);
        } else {
          // Jika belum ada, gunakan template default
          setHtmlContent(
            activeTemplate === "surat-tugas"
              ? defaultSuratTugasHTML.trim()
              : "<p>Ketik HTML di sini...</p>",
