          Koordinator: <strong>Sugeng Utomo, S.E.</strong><br/>
          Anggota:<ol style="margin:0; padding-left: 20px;"><li>Budi Wibowo, S.T.</li></ol>
        </td></tr>
      </table>
    `,
    );
    return preview;
  };

  return (
    <div className="max-w-[1600px] mx-auto pb-12 animate-in fade-in duration-500">
