            {/* SIMULASI KERTAS A4 */}
            <div
              className="bg-white shadow-2xl shrink-0"
              style={{
                width: "210mm",
                minHeight: "297mm",
                padding: "20mm",
                fontFamily: '"Times New Roman", Times, serif',
                color: "black",
              }}
              dangerouslySetInnerHTML={{ __html: getPreviewHTML() }}
            />
          </div>
