export default function ValidasiAdminPage() {
  const [dokumenList, setDokumenList] = useState<any[]>([]);
  const [suratList, setSuratList] = useState<any[]>([]); // Ganti dari prokerList ke suratList (Koneksi ke E-Office)
  const [pengurusList, setPengurusList] = useState<any[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [isSubmitting, setIsSubmitting] = useState(false);

  // Pagination State
  const [itemsPerPage, setItemsPerPage] = useState<number | "all">(5);
  const [currentPage, setCurrentPage] = useState(1);

  const [formData, setFormData] = useState({
    nomorSurat: "",
    perihal: "",
    penandatangan: "",
    jabatan: "",
    tanggal: "",
  });

  const [dialog, setDialog] = useState<{
    isOpen: boolean;
    type: "alert" | "confirm";
    title: string;
    message: string;
    onConfirm?: () => void;
  }>({
    isOpen: false,
    type: "alert",
    title: "",
    message: "",
  });

  const closeDialog = () => setDialog({ ...dialog, isOpen: false });
  const showAlert = (title: string, message: string) =>
    setDialog({ isOpen: true, type: "alert", title, message });
  const showConfirm = (title: string, message: string, onConfirm: () => void) =>
    setDialog({ isOpen: true, type: "confirm", title, message, onConfirm });

  const fetchAllData = async () => {
    setIsLoading(true);
    try {
      // 1. Fetch Semua QR Code Validasi
      const qQR = query(
        collection(db, "validasi_ttd"),
        orderBy("createdAt", "desc"),
      );
      const snapQR = await getDocs(qQR);
      const rawDataQR = snapQR.docs.map((d) => ({ id: d.id, ...d.data() }));

      // 2. Fetch Semua Nomor Surat dari E-Office (Ganti dari proker ke nomor_surat)
      const qSuratAll = query(collection(db, "nomor_surat"));
      const snapSuratAll = await getDocs(qSuratAll);
      const allSurat = snapSuratAll.docs.map((d) => ({
        id: d.id,
        ...d.data(),
      }));

      // 3. Cari tau QR mana saja yang sudah nempel di Surat E-Office (isAttached)
      const attachedValidasiIds = allSurat
        .filter(
          (s: any) =>
            s.qrValidationUrl && s.qrValidationUrl.includes("/verifttd/"),
        )
        .map((s: any) => {
          const parts = s.qrValidationUrl.split("/");
          return parts[parts.length - 1];
        });

      // 4. Map final data QR dengan flag isAttached
      const finalDataQR = rawDataQR.map((qr) => ({
        ...qr,
        isAttached: attachedValidasiIds.includes(qr.id),
      }));
      setDokumenList(finalDataQR);

      // 5. Filter daftar Surat di dropdown (Hanya yang belum punya QR sama sekali)
      const nomorSuratSudahAdaQR = finalDataQR.map((qr: any) => qr.nomorSurat);
      const filteredSurat = allSurat
        .filter((s: any) => s.nomor && !nomorSuratSudahAdaQR.includes(s.nomor))
        .sort((a: any, b: any) => {
          const timeA = a.createdAt ? new Date(a.createdAt).getTime() : 0;
          const timeB = b.createdAt ? new Date(b.createdAt).getTime() : 0;
          return timeB - timeA;
        });
      setSuratList(filteredSurat);

      // 6. Fetch Pengurus
      const snapPengurus = await getDocs(collection(db, "pengurus"));
      setPengurusList(
        snapPengurus.docs.map((d) => ({ id: d.id, ...d.data() })),
      );
    } catch (error) {
      console.error(error);
    } finally {
      setIsLoading(false);
    }
  };

  useEffect(() => {
    fetchAllData();
  }, []);

  // Reset pagination if data length changes drastically
  useEffect(() => {
    setCurrentPage(1);
  }, [itemsPerPage]);

  const handlePilihSurat = (e: React.ChangeEvent<HTMLSelectElement>) => {
    const nomor = e.target.value;
    const surat = suratList.find((s) => s.nomor === nomor);
    
    // Auto-fill Penandatangan based on pembuat
    const pembuat = surat?.pembuat || "";
    const jabatanPembuat = surat?.jabatanPembuat || "";
    
    setFormData({
      ...formData,
      nomorSurat: nomor,
      perihal: surat ? surat.perihal : "", // Ambil 'perihal' dari E-Office
      penandatangan: pembuat,
      jabatan: jabatanPembuat,
    });
  };

  const handlePilihPengurus = (e: React.ChangeEvent<HTMLSelectElement>) => {
    const nama = e.target.value;
    const pengurus = pengurusList.find((p) => p.nama === nama);
    setFormData({
      ...formData,
      penandatangan: nama,
      jabatan: pengurus ? pengurus.jabatan || "" : "",
    });
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setIsSubmitting(true);
    try {
      await addDoc(collection(db, "validasi_ttd"), {
        ...formData,
        createdAt: serverTimestamp(),
        status: "Valid",
      });
      setFormData({
        nomorSurat: "",
        perihal: "",
        penandatangan: "",
        jabatan: "",
        tanggal: "",
      });
      fetchAllData();
      setTimeout(
        () =>
          showAlert(
            "Berhasil",
            "QR Code berhasil dibuat dan masuk ke dalam sistem!",
          ),
        300,
      );
    } catch (error) {
      setTimeout(
        () => showAlert("Gagal", "Gagal membuat QR Code. Silakan coba lagi."),
        300,
      );
    } finally {
      setIsSubmitting(false);
    }
  };

  const downloadQR = (id: string, nomor: string) => {
    const canvas = document.getElementById(`qr-${id}`) as HTMLCanvasElement;
    if (!canvas) return;
    const pngUrl = canvas
      .toDataURL("image/png")
      .replace("image/png", "image/octet-stream");
    const link = document.createElement("a");
    link.href = pngUrl;
    link.download = `QR_TTD_${nomor.replace(/[^a-zA-Z0-9]/g, "_")}.png`;
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  const baseUrl =
    typeof window !== "undefined"
      ? window.location.origin
      : "http://localhost:3000";

  // 🔥 FUNGSI BUBUHKAN KE E-OFFICE 🔥
  const handleBubuhkanQR = async (docData: any) => {
    try {
      const qSurat = query(
        collection(db, "nomor_surat"),
        where("nomor", "==", docData.nomorSurat),
      );
      const snap = await getDocs(qSurat);

      if (snap.empty) {
        showAlert(
          "Peringatan",
          `Surat dengan nomor ${docData.nomorSurat} tidak ditemukan di database E-Office.`,
        );
        return;
      }

      const suratId = snap.docs[0].id;
      const validationUrl = `${baseUrl}/verifttd/${docData.id}`;

      await updateDoc(doc(db, "nomor_surat", suratId), {
        qrValidationUrl: validationUrl,
      });

      showAlert(
        "Berhasil",
        "QR Code telah ditautkan dan dibubuhkan secara elektronik ke Dokumen E-Office.",
      );
      fetchAllData();
    } catch (error) {
      console.error(error);
      showAlert("Gagal", "Terjadi kesalahan sistem saat membubuhkan QR.");
    }
  };

  // 🔥 FUNGSI CABUT VALIDASI DARI E-OFFICE 🔥
  const handleCabutValidasi = async (docData: any) => {
    showConfirm(
      "Cabut Validasi",
      `Yakin ingin mencabut bubuhan QR Code dari surat nomor: ${docData.nomorSurat}?\n\nQR ini tidak akan terhapus dan dapat digunakan kembali nantinya.`,
      async () => {
        closeDialog();
        try {
          const qSurat = query(
            collection(db, "nomor_surat"),
            where("nomor", "==", docData.nomorSurat),
          );
          const snap = await getDocs(qSurat);

          if (!snap.empty) {
            const suratId = snap.docs[0].id;
            await updateDoc(doc(db, "nomor_surat", suratId), {
              qrValidationUrl: "",
            });
          }

          setTimeout(
            () =>
              showAlert(
                "Berhasil",
                "Validasi berhasil dicabut. QR Code dapat dibubuhkan kembali.",
              ),
            300,
          );
          fetchAllData();
        } catch (error) {
          console.error("Gagal mencabut QR:", error);
          setTimeout(
            () =>
              showAlert(
                "Gagal",
                "Terjadi kesalahan saat mencabut validasi QR Code.",
              ),
            300,
          );
        }
      },
    );
  };

  // 🔥 FUNGSI HAPUS PERMANEN 🔥
  const handleDeleteQR = async (qrId: string, nomorSurat: string) => {
    showConfirm(
      "Hapus Permanen",
      `Yakin ingin menghapus data QR Code untuk surat nomor: ${nomorSurat}? Data tidak dapat dikembalikan.`,
      async () => {
        closeDialog();
        try {
          await deleteDoc(doc(db, "validasi_ttd", qrId));
          setTimeout(
            () =>
              showAlert(
                "Berhasil",
                "Data QR Code berhasil dihapus secara permanen.",
              ),
            300,
          );
          fetchAllData();
        } catch (error) {
          console.error("Gagal menghapus QR:", error);
          setTimeout(
            () =>
              showAlert("Gagal", "Terjadi kesalahan saat menghapus QR Code."),
            300,
          );
        }
      },
    );
  };

  // Paginasi Logic
  const totalItems = dokumenList.length;
  const totalPages =
    itemsPerPage === "all" ? 1 : Math.ceil(totalItems / itemsPerPage);
  const displayedDokumen =
    itemsPerPage === "all"
      ? dokumenList
      : dokumenList.slice(
          (currentPage - 1) * itemsPerPage,
          currentPage * itemsPerPage,
        );

  return (
    <div className="min-h-screen pb-12 font-sans text-slate-800">
      {/* CUSTOM DIALOG */}
      {dialog.isOpen && (
        <div className="fixed inset-0 z-[200] flex items-center justify-center p-4 bg-slate-900/40 backdrop-blur-sm animate-in fade-in duration-200 print:hidden">
          <div className="bg-white/95 rounded-2xl w-full max-w-sm shadow-2xl flex flex-col overflow-hidden border border-slate-200 animate-in zoom-in-95">
            <div className="px-6 py-5">
              <h2
                className={`text-xl font-bold mb-2 ${dialog.title.includes("Gagal") || dialog.title.includes("Cabut") || dialog.title.includes("Hapus") || dialog.title.includes("Peringatan") ? "text-red-600" : "text-blue-700"}`}
              >
                {dialog.title}
              </h2>
              <p className="text-sm text-slate-600 leading-relaxed whitespace-pre-wrap">
                {dialog.message}
              </p>
            </div>
            <div className="px-6 py-4 bg-slate-50/80 border-t border-slate-200 flex justify-end gap-2">
              {dialog.type === "confirm" && (
                <button
                  onClick={closeDialog}
                  className="px-4 py-2 text-sm font-semibold text-slate-600 hover:bg-slate-200 rounded-xl transition-all"
                >
                  Batal
                </button>
              )}
              <button
                onClick={() => {
                  if (dialog.type === "confirm" && dialog.onConfirm) {
                    dialog.onConfirm();
                  } else {
                    closeDialog();
                  }
                }}
                className={`px-4 py-2 text-sm font-semibold text-white rounded-xl transition-all shadow-md ${dialog.title.includes("Cabut") || dialog.title.includes("Hapus") ? "bg-red-600 hover:bg-red-700" : "bg-gradient-to-r from-blue-600 to-indigo-600 hover:from-blue-700 hover:to-indigo-700"}`}
              >
                {dialog.type === "confirm" ? "Lanjutkan" : "Mengerti"}
              </button>
            </div>
          </div>
        </div>
      )}

      <div className="max-w-7xl mx-auto animate-in fade-in duration-500">
        {/* --- HEADER PREMIUM --- */}
        <div className="mb-6 mt-4 border-b border-slate-200 pb-5">
          <div className="inline-flex items-center gap-1.5 bg-blue-50 text-blue-700 text-xs font-bold px-3 py-1 rounded-full mb-3 uppercase tracking-widest border border-blue-200 shadow-sm">
            <IconQR /> Tanda Tangan Elektronik
          </div>
          <h2 className="text-2xl font-medium text-slate-900 mb-1 tracking-tight">
            Validasi & Otorisasi
          </h2>
          <p className="text-slate-500 text-sm max-w-2xl">
            Buat, bubuhkan, dan kelola QR Code validasi keaslian dokumen untuk
            surat-surat dari sistem E-Office.
          </p>
        </div>

        <div className="grid lg:grid-cols-12 gap-6 items-start">
          {/* KOLOM KIRI (Form) */}
          <div className="lg:col-span-4 space-y-6">
            <div className="bg-white/90 backdrop-blur-md p-6 rounded-2xl shadow-sm border border-slate-200">
              <h3 className="font-semibold text-slate-800 mb-5 flex items-center gap-2">
                Buat Segel QR Baru
              </h3>

              <form onSubmit={handleSubmit} className="space-y-4">
                <div>
                  <label className="block text-xs font-semibold text-slate-600 mb-1">
                    Pilih Surat dari E-Office{" "}
                    <span className="text-red-500">*</span>
                  </label>
                  <select
                    required
                    value={formData.nomorSurat}
                    onChange={handlePilihSurat}
                    className="w-full bg-white border border-slate-200 px-3 py-2.5 rounded-xl text-sm outline-none focus:ring-2 focus:ring-blue-100 focus:border-blue-500 text-slate-800 transition-all"
                  >
                    <option value="">-- Pilih dari database E-Office --</option>
                    {suratList.map((s) => (
                      <option key={s.id} value={s.nomor}>
                        {s.nomor} ({s.perihal.substring(0, 20)}...)
                      </option>
                    ))}
                    {suratList.length === 0 && !isLoading && (
                      <option value="" disabled>
                        Semua surat telah diotentikasi
                      </option>
                    )}
                  </select>
                </div>

                <div>
                  <label className="block text-xs font-semibold text-slate-600 mb-1">
                    Subjek / Perihal Surat
                  </label>
                  <input
                    required
                    type="text"
                    value={formData.perihal}
                    readOnly
                    className="w-full bg-slate-50 border border-slate-200 px-3 py-2.5 rounded-xl text-sm outline-none text-slate-500 cursor-not-allowed"
                  />
                </div>

                <div>
                  <label className="block text-xs font-semibold text-slate-600 mb-1">
                    Otoritas Penandatangan{" "}
                    <span className="text-red-500">*</span>
                  </label>
                  <select
                    required
                    value={formData.penandatangan}
                    onChange={handlePilihPengurus}
                    className="w-full bg-white border border-slate-200 px-3 py-2.5 rounded-xl text-sm outline-none focus:ring-2 focus:ring-blue-100 focus:border-blue-500 text-slate-800 transition-all"
                  >
                    <option value="">-- Pilih Pengurus Berwenang --</option>
                    {/* Fallback jika ada dari E-Office tapi tidak ada di list */}
                    {formData.penandatangan && !pengurusList.some(p => p.nama === formData.penandatangan) && (
                      <option value={formData.penandatangan}>{formData.penandatangan}</option>
                    )}
                    {pengurusList
                      .filter((p) => p.nama)
                      .map((p) => (
                        <option key={p.id} value={p.nama}>
                          {p.nama}
                        </option>
                      ))}
                  </select>
                </div>

                <div className="grid grid-cols-2 gap-4">
                  <div>
                    <label className="block text-xs font-semibold text-slate-600 mb-1">
                      Jabatan
                    </label>
                    <input
                      required
                      type="text"
                      value={formData.jabatan}
                      readOnly
                      className="w-full bg-slate-50 border border-slate-200 px-3 py-2.5 rounded-xl text-sm outline-none text-slate-500 cursor-not-allowed"
                    />
                  </div>
                  <div>
                    <label className="block text-xs font-semibold text-slate-600 mb-1">
                      Tanggal Sah <span className="text-red-500">*</span>
                    </label>
                    <input
                      required
                      type="date"
                      value={formData.tanggal}
                      onChange={(e) =>
                        setFormData({ ...formData, tanggal: e.target.value })
                      }
                      className="w-full bg-white border border-slate-200 px-3 py-2.5 rounded-xl text-sm outline-none focus:ring-2 focus:ring-blue-100 focus:border-blue-500 transition-all"
                    />
                  </div>
                </div>

                <button
                  disabled={isSubmitting || suratList.length === 0}
                  type="submit"
                  className="w-full bg-gradient-to-r from-blue-600 to-indigo-600 hover:from-blue-700 hover:to-indigo-700 text-white font-semibold py-2.5 rounded-xl transition-all mt-4 shadow-md disabled:opacity-50 disabled:cursor-not-allowed flex items-center justify-center gap-2 text-sm"
                >
                  {isSubmitting ? (
                    <div className="w-4 h-4 border-2 border-white/30 border-t-white rounded-full animate-spin"></div>
                  ) : (
                    <>
                      <IconPlus /> Generate TTE System
                    </>
                  )}
                </button>
              </form>
            </div>
          </div>

          {/* KOLOM KANAN (Daftar Dokumen QR) */}
          <div className="lg:col-span-8">
            <div className="bg-white/90 backdrop-blur-md rounded-2xl shadow-sm border border-slate-200 overflow-hidden flex flex-col min-h-[500px]">
              {/* Toolbar & Pagination */}
              <div className="flex flex-col sm:flex-row justify-between items-center bg-slate-50/50 px-5 py-4 border-b border-slate-200 gap-3">
                <div className="flex items-center gap-2 text-sm text-slate-500 font-medium">
                  <span>Tampilkan:</span>
                  <select
                    value={itemsPerPage}
                    onChange={(e) => {
                      setItemsPerPage(
                        e.target.value === "all"
                          ? "all"
                          : Number(e.target.value),
                      );
                    }}
                    className="border border-slate-200 rounded-lg px-3 py-1.5 outline-none focus:border-blue-500 bg-white cursor-pointer"
                  >
                    <option value={5}>5 Baris</option>
                    <option value={10}>10 Baris</option>
                    <option value="all">Semua Data</option>
                  </select>
                </div>

                {dokumenList.length > 0 && (
                  <div className="flex items-center gap-4 text-sm text-slate-500 font-medium">
                    <span>
                      {itemsPerPage === "all"
                        ? `1-${totalItems}`
                        : `${(currentPage - 1) * (itemsPerPage as number) + 1}-${Math.min(currentPage * (itemsPerPage as number), totalItems)}`}{" "}
                      dari {totalItems} Dokumen
                    </span>
                    {itemsPerPage !== "all" && (
                      <div className="flex items-center gap-1">
                        <button
                          onClick={() =>
                            setCurrentPage((p) => Math.max(1, p - 1))
                          }
                          disabled={currentPage === 1}
                          className="p-1 hover:bg-slate-200 disabled:opacity-30 rounded text-slate-500 transition-colors"
                        >
                          <IconPrev />
                        </button>
                        <button
                          onClick={() =>
                            setCurrentPage((p) => Math.min(totalPages, p + 1))
                          }
                          disabled={currentPage === totalPages}
                          className="p-1 hover:bg-slate-200 disabled:opacity-30 rounded text-slate-500 transition-colors"
                        >
                          <IconNext />
                        </button>
                      </div>
                    )}
                  </div>
                )}
              </div>

              {isLoading ? (
                <div className="flex-1 flex justify-center items-center p-20">
                  <div className="w-8 h-8 border-4 border-slate-200 border-t-blue-600 rounded-full animate-spin"></div>
                </div>
              ) : dokumenList.length === 0 ? (
                <div className="flex-1 flex flex-col items-center justify-center p-20 opacity-60">
                  <div className="w-16 h-16 bg-slate-100 text-slate-400 rounded-full flex items-center justify-center mb-4">
                    <IconQR />
                  </div>
                  <h3 className="font-medium text-slate-800 text-lg">
                    Repositori Kosong
                  </h3>
                  <p className="text-sm text-slate-500 mt-1 text-center max-w-xs">
                    Gunakan formulir untuk membuat QR pertama Anda.
                  </p>
                </div>
              ) : (
                <div className="overflow-x-auto flex-1 bg-white">
                  <table className="w-full text-left border-collapse whitespace-nowrap">
                    <thead>
                      <tr className="bg-slate-50/80 border-b border-slate-200 text-slate-500 text-xs font-semibold uppercase tracking-wider">
                        <th className="px-6 py-4 w-28">Visual QR</th>
                        <th className="px-6 py-4">Informasi Dokumen</th>
                        <th className="px-6 py-4 text-center">Status</th>
                        <th className="px-6 py-4 text-right">Tindakan</th>
                      </tr>
                    </thead>
                    <tbody className="divide-y divide-slate-100">
                      {displayedDokumen.map((doc) => {
                        const validationUrl = `${baseUrl}/verifttd/${doc.id}`;
                        return (
                          <tr
                            key={doc.id}
                            className="hover:bg-slate-50 transition-colors group"
                          >
                            <td className="px-6 py-5 align-top">
                              <div className="bg-white p-2 border border-slate-200 rounded-xl inline-block shadow-sm group-hover:shadow-md transition-all">
                                <QRCodeCanvas
                                  id={`qr-${doc.id}`}
                                  value={validationUrl}
                                  size={64}
                                  level={"H"}
                                  includeMargin={true}
                                />
                              </div>
                            </td>
                            <td className="px-6 py-5 align-top">
                              <div className="font-semibold text-blue-700 text-sm mb-1">
                                {doc.nomorSurat}
                              </div>
                              <div className="text-sm text-slate-800 mb-2 truncate max-w-xs md:max-w-sm">
                                {doc.perihal}
                              </div>
                              <div className="text-xs text-slate-500 bg-slate-50 p-2 rounded-lg border border-slate-100">
                                <span className="font-semibold text-slate-700">Otoritas:</span>{" "}
                                {doc.penandatangan} <br />
                                <span className="font-semibold text-slate-700 mt-1 inline-block">
                                  Disahkan:
                                </span>{" "}
                                {doc.tanggal}
                              </div>
                            </td>
                            <td className="px-6 py-5 align-top text-center">
                              {doc.isAttached ? (
                                <span className="inline-flex items-center gap-1.5 px-2.5 py-1 rounded-full bg-emerald-50 text-emerald-700 border border-emerald-200 text-[10px] font-bold uppercase tracking-widest shadow-sm">
                                  Telah Dibubuhkan
                                </span>
                              ) : (
                                <span className="inline-flex items-center gap-1.5 px-2.5 py-1 rounded-full bg-amber-50 text-amber-700 border border-amber-200 text-[10px] font-bold uppercase tracking-widest shadow-sm">
                                  Belum Dibubuhkan
                                </span>
                              )}
                            </td>
                            <td className="px-6 py-5 align-top text-right">
                              <div className="flex flex-col gap-2 items-end">
                                <div className="flex gap-2">
                                  {!doc.isAttached ? (
                                    <button
                                      onClick={() => handleBubuhkanQR(doc)}
                                      title="Bubuhkan ke Surat E-Office"
                                      className="p-2 text-emerald-600 bg-emerald-50 hover:bg-emerald-100 rounded-lg transition-colors border border-emerald-100 flex items-center gap-2 text-xs font-semibold shadow-sm"
                                    >
                                      <IconAttach /> Pasang
                                    </button>
                                  ) : (
                                    <button
                                      onClick={() => handleCabutValidasi(doc)}
                                      title="Cabut Validasi"
                                      className="p-2 text-amber-600 bg-amber-50 hover:bg-amber-100 rounded-lg transition-colors border border-amber-100 flex items-center gap-2 text-xs font-semibold shadow-sm"
                                    >
                                      <IconDetach /> Cabut
                                    </button>
                                  )}
                                </div>
                                <div className="flex gap-2 mt-1">
                                  <button
                                    onClick={() =>
                                      downloadQR(doc.id, doc.nomorSurat)
                                    }
                                    title="Download Gambar QR"
                                    className="p-2 text-blue-600 bg-blue-50 hover:bg-blue-100 border border-blue-100 rounded-lg transition-colors flex items-center gap-2 text-xs font-semibold shadow-sm"
                                  >
                                    <IconDownload /> Unduh
                                  </button>
                                  {!doc.isAttached && (
                                    <button
                                      onClick={() =>
                                        handleDeleteQR(doc.id, doc.nomorSurat)
                                      }
                                      title="Hapus Permanen QR"
                                      className="p-2 text-red-500 bg-red-50 hover:bg-red-100 border border-red-100 rounded-lg transition-colors flex items-center gap-2 text-xs font-semibold shadow-sm"
                                    >
                                      <IconTrash /> Hapus
                                    </button>
                                  )}
                                </div>
                              </div>
                            </td>
                          </tr>
                        );
                      })}
                    </tbody>
                  </table>
                </div>
              )}
            </div>
          </div>
        </div>
      </div>
    </div>
  );
}

"use client";

import { useState, useEffect, useMemo } from "react";
import { db } from "@/lib/firebase";
import {
  collection,
  getDocs,
  doc,
  getDoc,
  updateDoc,
  setDoc,
  deleteDoc,
  query,
  orderBy,
} from "firebase/firestore";
import * as XLSX from "xlsx";
import QRCode from "react-qr-code";
import { sendEmailAction } from "@/app/actions/email";


export default function VerifikasiAnggotaPage() {
  const [pendaftarList, setPendaftarList] = useState<any[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [isProcessing, setIsProcessing] = useState(false);

  // 🔥 FILTERS 🔥
  const [filterStatus, setFilterStatus] = useState("Dalam Proses");
  const [searchQuery, setSearchQuery] = useState("");
  const [filterFakultas, setFilterFakultas] = useState("");
  const [filterAngkatan, setFilterAngkatan] = useState("");
  const [filterDomisili, setFilterDomisili] = useState("");

  const [itemsPerPage, setItemsPerPage] = useState<number | "Semua">(10);
  const [currentPage, setCurrentPage] = useState(1);
  const [sortOrder, setSortOrder] = useState("Terbaru");

  const [selectedIds, setSelectedIds] = useState<string[]>([]);
  const [selectedUser, setSelectedUser] = useState<any>(null);
  const [isDetailModalOpen, setIsDetailModalOpen] = useState(false);
  const [isFlipped, setIsFlipped] = useState(false);

  // 🔥 STATE TOAST NOTIFICATION 🔥
  const [toast, setToast] = useState({
    isOpen: false,
    message: "",
    type: "success",
  });

  // 🔥 STATE MODALS 🔥
  const [approveModal, setApproveModal] = useState({
    isOpen: false,
    user: null as any,
  });
  const [rejectModal, setRejectModal] = useState({
    isOpen: false,
    user: null as any,
    reason: "",
  });
  const [deleteModal, setDeleteModal] = useState({
    isOpen: false,
    type: "single",
    id: "",
    title: "",
  });

  const [exportModalOpen, setExportModalOpen] = useState(false);
  const [exportTarget, setExportTarget] = useState("filtered"); // "filtered" | "all"

  const [importPreview, setImportPreview] = useState({
    isOpen: false,
    data: [] as any[],
    successCount: 0,
    failedCount: 0,
    isUploading: false,
    progress: 0,
    currentItem: "",
  });

  const showToast = (
    message: string,
    type: "success" | "error" | "info" = "success",
  ) => {
    setToast({ isOpen: true, message, type });
    setTimeout(() => setToast((prev) => ({ ...prev, isOpen: false })), 4000);
  };

  const fetchPendaftar = async () => {
    setIsLoading(true);
    try {
      const q = query(
        collection(db, "pendaftar"),
        orderBy("tanggalDaftar", "desc"),
      );
      const querySnapshot = await getDocs(q);
      const data = querySnapshot.docs.map((doc) => ({
        id: doc.id,
        ...(doc.data() as any),
      }));
      // Filter out Disetujui so they don't show up if there are any lingering ones
      setPendaftarList(data.filter((p: any) => p.status?.toLowerCase() !== "disetujui"));
    } catch (error) {
      console.error("Error fetching data: ", error);
      showToast("Gagal mengambil data dari server.", "error");
    } finally {
      setIsLoading(false);
      setSelectedIds([]);
    }
  };

  useEffect(() => {
    fetchPendaftar();
  }, []);

  // 🔥 GENERATE UNIQUE FILTER OPTIONS DARI DATA 🔥
  const optionFakultas = useMemo(
    () =>
      Array.from(
        new Set(pendaftarList.map((p) => p.fakultas).filter(Boolean)),
      ).sort(),
    [pendaftarList],
  );
  const optionAngkatan = useMemo(
    () =>
      Array.from(
        new Set(
          pendaftarList.map((p) => p.angkatan || p.tahunLulus).filter(Boolean),
        ),
      ).sort(),
    [pendaftarList],
  );
  const optionDomisili = useMemo(
    () =>
      Array.from(
        new Set(pendaftarList.map((p) => p.domisili).filter(Boolean)),
      ).sort(),
    [pendaftarList],
  );

  // 🔥 LOGIC FILTERING GANDA & SORTING 🔥
  const filteredList = useMemo(() => {
    const result = pendaftarList.filter((p) => {
      const matchStatus = p.status === filterStatus;
      const lowerSearch = searchQuery.toLowerCase();
      const matchSearch =
        !searchQuery ||
        (p.namaLengkap && p.namaLengkap.toLowerCase().includes(lowerSearch)) ||
        (p.nim && p.nim.toLowerCase().includes(lowerSearch));

      const matchFakultas = !filterFakultas || p.fakultas === filterFakultas;
      const matchAngkatan =
        !filterAngkatan || (p.angkatan || p.tahunLulus) === filterAngkatan;
      const matchDomisili = !filterDomisili || p.domisili === filterDomisili;

      return (
        matchStatus &&
        matchSearch &&
        matchFakultas &&
        matchAngkatan &&
        matchDomisili
      );
    });

    result.sort((a, b) => {
      let valA, valB;

      if (sortOrder === "Terbaru") {
        return new Date(b.tanggalDaftar).getTime() - new Date(a.tanggalDaftar).getTime();
      }
      if (sortOrder === "Terlama") {
        return new Date(a.tanggalDaftar).getTime() - new Date(b.tanggalDaftar).getTime();
      }

      if (sortOrder === "Nama-Asc") {
        return (a.namaLengkap || "").localeCompare(b.namaLengkap || "");
      }
      if (sortOrder === "Nama-Desc") {
        return (b.namaLengkap || "").localeCompare(a.namaLengkap || "");
      }
      
      if (sortOrder === "Fakultas-Asc") {
        return (a.fakultas || "").localeCompare(b.fakultas || "");
      }
      if (sortOrder === "Fakultas-Desc") {
        return (b.fakultas || "").localeCompare(a.fakultas || "");
      }
      
      if (sortOrder === "Domisili-Asc") {
        return (a.domisili || "").localeCompare(b.domisili || "");
      }
      if (sortOrder === "Domisili-Desc") {
        return (b.domisili || "").localeCompare(a.domisili || "");
      }
      
      if (sortOrder === "Status-Asc") {
        return (a.status || "").localeCompare(b.status || "");
      }
      if (sortOrder === "Status-Desc") {
        return (b.status || "").localeCompare(a.status || "");
      }

      return 0;
    });

    return result;
  }, [
    pendaftarList,
    filterStatus,
    searchQuery,
    filterFakultas,
    filterAngkatan,
    filterDomisili,
    sortOrder,
  ]);

  useEffect(() => {
    setCurrentPage(1);
  }, [
    searchQuery,
    filterStatus,
    itemsPerPage,
    filterFakultas,
    filterAngkatan,
    filterDomisili,
    sortOrder,
  ]);

  const totalPages =
    itemsPerPage === "Semua"
      ? 1
      : Math.ceil(filteredList.length / itemsPerPage);
  const currentData = useMemo(() => {
    if (itemsPerPage === "Semua") return filteredList;
    const start = (currentPage - 1) * itemsPerPage;
    return filteredList.slice(start, start + itemsPerPage);
  }, [filteredList, currentPage, itemsPerPage]);

  const handleSelectAll = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.checked) setSelectedIds(currentData.map((item) => item.id));
    else setSelectedIds([]);
  };

  const handleSelectOne = (
    e: React.ChangeEvent<HTMLInputElement>,
    id: string,
  ) => {
    e.stopPropagation();
    if (e.target.checked) setSelectedIds((prev) => [...prev, id]);
    else setSelectedIds((prev) => prev.filter((item) => item !== id));
  };

  const triggerEmailApi = async (
    type: string,
    email: string,
    nama: string,
    niaValue?: string,
    alasanDetail?: string,
  ) => {
    try {
      const res = await sendEmailAction({
          type,
          email,
          nama,
          detail: { nia: niaValue, alasan: alasanDetail },
        });
      return res.success;
    } catch (error) {
      console.error(`Gagal trigger API Email ${type}:`, error);
      return false;
    }
  };

  // 🔥 HELPER: Mengecek kelengkapan profil dasar (Foto & Domisili wajib untuk E-KTA dan format NIA)
  const isProfileComplete = (user: any) => {
    return Boolean(user.fotoUrl && user.domisili);
  };

  // --- 🔥 EKSEKUSI APPROVE & REJECT ---
  const executeApprove = async () => {
    const user = approveModal.user;
    if (!user) return;
    setIsProcessing(true);

    try {
      const pendaftarRef = doc(db, "pendaftar", user.id);
      const pengurusRef = doc(db, "pengurus", user.id);

      const isComplete = isProfileComplete(user);

      // Selalu generate NIA saat masuk menjadi Anggota Sah
      const counterRef = doc(db, "pengaturan", "counter_nia");
      const counterSnap = await getDoc(counterRef);
      let newNumber = 89;
      if (counterSnap.exists())
        newNumber = (counterSnap.data().lastNumber || 88) + 1;
      await setDoc(counterRef, { lastNumber: newNumber }, { merge: true });

      const dateObj = new Date();
      const yearStr = dateObj.getFullYear().toString().slice(-2);
      const monthStr = String(dateObj.getMonth() + 1).padStart(2, "0");
      let kabStr = "00";
      const dom = (user.domisili || "").toLowerCase();
      if (dom.includes("sleman")) kabStr = "04";
      else if (dom.includes("bantul")) kabStr = "02";
      else if (dom.includes("gunung")) kabStr = "03";
      else if (dom.includes("kulon")) kabStr = "01";
      else if (dom.includes("kota") || dom.includes("yogya")) kabStr = "71";

      const urutStr = String(newNumber).padStart(4, "0");
      const finalNIA = `${yearStr}.${monthStr}.34.${kabStr}.${urutStr}`;

      await deleteDoc(pendaftarRef);

      await setDoc(pengurusRef, {
        ...user,
        nia: finalNIA,
        nama: user.namaLengkap,
        wa: user.noWA,
        email: user.email,
        jabatan: "Anggota",
        bidang: user.keahlian || "Belum Ditentukan",
        fotoUrl: user.fotoUrl || "",
        linkTTD: "",
        isInti: false,
        isTampilBeranda: false,
        linkedinUrl: "",
        instagramUrl: "",
        createdAt: dateObj.toISOString(),
        status: "Disetujui",
      });

      // Kirim email penerbitan E-KTA
      await triggerEmailApi(
        "member_verified",
        user.email,
        user.namaLengkap,
        finalNIA,
      );
      if (isComplete) {
        showToast(`Anggota disetujui. NIA tercetak: ${finalNIA}`, "success");
      } else {
        showToast(
          `Anggota disetujui, NIA (${finalNIA}) tercetak (Profil belum lengkap)`,
          "info",
        );
      }

      setApproveModal({ isOpen: false, user: null });
      setIsDetailModalOpen(false);
      fetchPendaftar();
    } catch (error) {
      console.error("Gagal menyetujui: ", error);
      showToast("Gagal memproses persetujuan sistem.", "error");
    } finally {
      setIsProcessing(false);
    }
  };

  const executeReject = async (e: React.FormEvent) => {
    e.preventDefault();
    const user = rejectModal.user;
    if (!user || !rejectModal.reason.trim()) return;

    setIsProcessing(true);
    try {
      await updateDoc(doc(db, "pendaftar", user.id), {
        status: "Ditolak",
        alasanPenolakan: rejectModal.reason,
      });
      await triggerEmailApi(
        "reject_anggota",
        user.email,
        user.namaLengkap,
        "",
        rejectModal.reason,
      );
      setRejectModal({ isOpen: false, user: null, reason: "" });
      setIsDetailModalOpen(false);
      fetchPendaftar();
      showToast("Pendaftar berhasil ditolak.", "success");
    } catch (error) {
      console.error("Gagal menolak: ", error);
      showToast("Terjadi kesalahan saat menolak.", "error");
    } finally {
      setIsProcessing(false);
    }
  };

  const executeDelete = async () => {
    setIsProcessing(true);
    try {
      if (deleteModal.type === "single" && deleteModal.id) {
        await deleteDoc(doc(db, "pendaftar", deleteModal.id));
        await deleteDoc(doc(db, "pengurus", deleteModal.id));
      } else if (deleteModal.type === "bulk" && selectedIds.length > 0) {
        await Promise.all(
          selectedIds.map(async (id) => {
            await deleteDoc(doc(db, "pendaftar", id));
            await deleteDoc(doc(db, "pengurus", id));
          }),
        );
      }
      setDeleteModal({ isOpen: false, type: "single", id: "", title: "" });
      fetchPendaftar();
      showToast("Data berhasil dihapus permanen.", "success");
    } catch (error) {
      console.error("Gagal menghapus: ", error);
      showToast("Terjadi kesalahan saat menghapus data.", "error");
    } finally {
      setIsProcessing(false);
    }
  };

  // --- 🔥 EKSEKUSI KIRIM ULANG & TERBITKAN NIA (JIKA SEBELUMNYA DALAM PROSES) ---
  const resendApprovedEmail = async (user: any) => {
    setIsProcessing(true);
    try {
      let currentNia = user.nia;
      const isComplete = isProfileComplete(user);

      // Jika NIA masih "Dalam Proses", kita generate NIA baru saat tombol ini diklik
      if (currentNia === "Dalam Proses" || !currentNia) {
        if (!isComplete) {
          showToast(
            "Profil belum lengkap (Foto/Domisili kosong). Tidak bisa menerbitkan E-KTA.",
            "error",
          );
          setIsProcessing(false);
          return;
        }

        const counterRef = doc(db, "pengaturan", "counter_nia");
        const counterSnap = await getDoc(counterRef);
        let newNumber = 89;
        if (counterSnap.exists())
          newNumber = (counterSnap.data().lastNumber || 88) + 1;
        await setDoc(counterRef, { lastNumber: newNumber }, { merge: true });

        const dateObj = new Date();
        const yearStr = dateObj.getFullYear().toString().slice(-2);
        const monthStr = String(dateObj.getMonth() + 1).padStart(2, "0");
        let kabStr = "00";
        const dom = (user.domisili || "").toLowerCase();
        if (dom.includes("sleman")) kabStr = "04";
        else if (dom.includes("bantul")) kabStr = "02";
        else if (dom.includes("gunung")) kabStr = "03";
        else if (dom.includes("kulon")) kabStr = "01";
        else if (dom.includes("kota") || dom.includes("yogya")) kabStr = "71";

        const urutStr = String(newNumber).padStart(4, "0");
        currentNia = `${yearStr}.${monthStr}.34.${kabStr}.${urutStr}`;

        // Simpan NIA yang baru ter-generate ke database
        await updateDoc(doc(db, "pendaftar", user.id), {
          nia: currentNia,
          emailSent: true,
        });
        await updateDoc(doc(db, "pengurus", user.id), { nia: currentNia });
      } else {
        await updateDoc(doc(db, "pendaftar", user.id), { emailSent: true });
      }

      const isSuccess = await triggerEmailApi(
        "member_verified",
        user.email,
        user.namaLengkap,
        currentNia,
      );

      if (isSuccess) {
        showToast("Email E-KTA berhasil dikirim!", "success");
      } else {
        showToast("Gagal mengirim email E-KTA.", "error");
      }

      setIsDetailModalOpen(false);
      fetchPendaftar();
    } catch (error) {
      console.error("Error resending email:", error);
      showToast("Terjadi kesalahan sistem saat mengirim email.", "error");
    } finally {
      setIsProcessing(false);
    }
  };

  const handleBulkEmailSend = async () => {
    if (selectedIds.length === 0) return;
    setIsProcessing(true);
    let successCount = 0;

    try {
      for (const id of selectedIds) {
        const user = pendaftarList.find((p) => p.id === id);
        if (!user) continue;

        // Jangan kirim email massal jika profilnya belum lengkap (NIA masih 'Dalam Proses')
        if (user.nia === "Dalam Proses" && !isProfileComplete(user)) {
          continue;
        }

        let currentNia = user.nia;

        // Generate massal jika profil lengkap tapi belum punya NIA
        if (currentNia === "Dalam Proses") {
          const counterRef = doc(db, "pengaturan", "counter_nia");
          const counterSnap = await getDoc(counterRef);
          let newNumber = 89;
          if (counterSnap.exists())
            newNumber = (counterSnap.data().lastNumber || 88) + 1;
          await setDoc(counterRef, { lastNumber: newNumber }, { merge: true });

          const dateObj = new Date();
          const yearStr = dateObj.getFullYear().toString().slice(-2);
          const monthStr = String(dateObj.getMonth() + 1).padStart(2, "0");
          let kabStr = "00";
          const dom = (user.domisili || "").toLowerCase();
          if (dom.includes("sleman")) kabStr = "04";
          else if (dom.includes("bantul")) kabStr = "02";
          else if (dom.includes("gunung")) kabStr = "03";
          else if (dom.includes("kulon")) kabStr = "01";
          else if (dom.includes("kota") || dom.includes("yogya")) kabStr = "71";

          const urutStr = String(newNumber).padStart(4, "0");
          currentNia = `${yearStr}.${monthStr}.34.${kabStr}.${urutStr}`;

          await updateDoc(doc(db, "pendaftar", user.id), {
            nia: currentNia,
            emailSent: true,
          });
          await updateDoc(doc(db, "pengurus", user.id), { nia: currentNia });
        } else {
          await updateDoc(doc(db, "pendaftar", user.id), { emailSent: true });
        }

        const isSuccess = await triggerEmailApi(
          "member_verified",
          user.email,
          user.namaLengkap,
          currentNia,
        );
        if (isSuccess) successCount++;

        await new Promise((resolve) => setTimeout(resolve, 300)); // Delay agar tidak spam API
      }

      showToast(
        `Berhasil memproses & mengirim ${successCount} email!`,
        "success",
      );
      fetchPendaftar();
    } catch (error) {
      console.error("Bulk email error:", error);
      showToast("Terjadi kesalahan saat memproses email massal.", "error");
    } finally {
      setIsProcessing(false);
      setSelectedIds([]);
    }
  };

  // --- 🔥 ALUR EXPORT BARU 🔥 ---
  const handleDownloadTemplate = () => {
    const ws = XLSX.utils.json_to_sheet([
      {
        email: "",
        namaLengkap: "",
        noWA: "",
        nim: "",
        tahunLulus: "",
        fakultas: "",
        programStudi: "",
        domisili: "",
        alamatLengkap: "",
        pekerjaan: "",
        keahlian: "",
        motto: "",
      },
    ]);
    const wb = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(wb, ws, "Template_Import");
    XLSX.writeFile(wb, "Template_Import_Anggota_IKA_UII.xlsx");
    showToast("Template berhasil diunduh.", "success");
  };

  const executeExport = () => {
    const dataToExport =
      exportTarget === "filtered" ? filteredList : pendaftarList;
    if (dataToExport.length === 0) {
      showToast("Tidak ada data untuk diekspor.", "error");
      return;
    }

    const formattedData = dataToExport.map((d, index) => ({
      No: index + 1,
      "Tanggal Daftar":
        new Date(d.tanggalDaftar).toLocaleDateString("id-ID", {
          day: "2-digit",
          month: "long",
          year: "numeric",
          hour: "2-digit",
          minute: "2-digit",
        }) + " WIB",
      Status: d.status,
      "Status Notifikasi": d.emailSent ? "Terkirim" : "Belum Dikirim",
      NIA: d.nia || "Belum Terbit",
      "Nama Lengkap": d.namaLengkap,
      "Nomor WA": d.noWA,
      Email: d.email,
      Fakultas: d.fakultas,
      "Program Studi": d.programStudi,
      NIM: d.nim,
      "Tahun Masuk / Angkatan": d.angkatan || d.tahunLulus || "-",
      Domisili: d.domisili,
      "Alamat Lengkap": d.alamatLengkap || "-",
      Pekerjaan: d.pekerjaan,
      "Bidang Keahlian": d.keahlian || d.bidang,
      "Motivasi / Motto": d.motto,
      "Alasan Penolakan": d.alasanPenolakan || "-",
    }));

    const ws = XLSX.utils.json_to_sheet(formattedData);
    const wb = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(wb, ws, `Data_Anggota`);
    XLSX.writeFile(
      wb,
      `Ekspor_Anggota_IKA_UII_${exportTarget === "all" ? "Semua" : filterStatus.replace(/\s+/g, "_")}.xlsx`,
    );

    setExportModalOpen(false);
    showToast("Data berhasil diekspor ke Excel.", "success");
  };

  // --- 🔥 ALUR IMPORT BARU (TIPE B) 🔥 ---
  const handleFileSelect = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    const reader = new FileReader();
    reader.onload = async (event) => {
      try {
        setIsLoading(true); // Optional: show loading while fetching
        const pengurusSnapshot = await getDocs(collection(db, "pengurus"));
        const pengurusList = pengurusSnapshot.docs.map(doc => doc.data());
        setIsLoading(false);

        const data = new Uint8Array(event.target?.result as ArrayBuffer);
        const workbook = XLSX.read(data, { type: "array" });
        const sheetName = workbook.SheetNames[0];
        const rawData = XLSX.utils.sheet_to_json(workbook.Sheets[sheetName]);

        const previewList = rawData.map((item: any) => {
          const emailTrim = (item.email || "").trim().toLowerCase();
          const nimTrim = String(item.nim || "").trim();

          const isEmailEmpty = !emailTrim;
          const isRegisteredPendaftar = pendaftarList.some(
            (p) =>
              (p.email && p.email.toLowerCase() === emailTrim) ||
              (p.nim && p.nim === nimTrim),
          );
          const isRegisteredPengurus = pengurusList.some(
            (p) =>
              (p.email && p.email.toLowerCase() === emailTrim) ||
              (p.nim && p.nim === nimTrim),
          );
          const isRegistered = isRegisteredPendaftar || isRegisteredPengurus;

          let isValid = true;
          let statusPesan = "Siap Import";

          if (isEmailEmpty) {
            isValid = false;
            statusPesan = "Email Kosong";
          } else if (isRegistered) {
            isValid = false;
            statusPesan = "Data Duplikat";
          }

          return { ...item, isValid, statusPesan };
        });

        const successCount = previewList.filter((i) => i.isValid).length;
        const failedCount = previewList.length - successCount;

        setImportPreview({
          isOpen: true,
          data: previewList,
          successCount,
          failedCount,
          isUploading: false,
          progress: 0,
          currentItem: "",
        });
      } catch (error) {
        console.error(error);
        showToast(
          "Gagal membaca file Excel. Pastikan format sesuai template.",
          "error",
        );
      }
    };
    reader.readAsArrayBuffer(file);
    e.target.value = ""; // reset input
  };

  const executeImportProgress = async () => {
    const validData = importPreview.data.filter((item) => item.isValid);
    if (validData.length === 0) return;

    setImportPreview((prev) => ({ ...prev, isUploading: true }));

    try {
      for (let i = 0; i < validData.length; i++) {
        const user = validData[i];
        setImportPreview((prev) => ({
          ...prev,
          progress: i + 1,
          currentItem: user.namaLengkap || user.email,
        }));

        const docId = `import_${Date.now()}_${i}`; // Generate ID unik
        const pendaftarRef = doc(db, "pendaftar", docId);

        const dataFinal = {
          namaLengkap: user.namaLengkap || "",
          noWA: String(user.noWA || ""),
          email: String(user.email || "")
            .trim()
            .toLowerCase(),
          nim: String(user.nim || ""),
          fakultas: user.fakultas || "",
          programStudi: user.programStudi || "",
          angkatan: String(user.tahunLulus || user.angkatan || ""),
          domisili: user.domisili || "",
          pekerjaan: user.pekerjaan || "",
          keahlian: user.keahlian || user.bidang || "Belum Ditentukan",
          motto: user.motto || "-",
          alamatLengkap: user.alamatLengkap || "-",
          status: "Dalam Proses", // 🔥 TIPE B: Masuk Dalam Proses dulu 🔥
          emailSent: false,
          createdAt: new Date().toISOString(),
          tanggalDaftar: new Date().toISOString(),
        };

        await setDoc(pendaftarRef, dataFinal);

        // Animasi progress pelan-pelan (0.2 detik per data)
        await new Promise((resolve) => setTimeout(resolve, 200));
      }

      showToast(
        `Import ${validData.length} data ke "Dalam Proses" berhasil!`,
        "success",
      );
      setImportPreview({
        isOpen: false,
        data: [],
        successCount: 0,
        failedCount: 0,
        isUploading: false,
        progress: 0,
        currentItem: "",
      });
      setFilterStatus("Dalam Proses");
      fetchPendaftar();
    } catch (error) {
      console.error("Gagal import massal:", error);
      showToast("Terjadi kesalahan saat memproses data.", "error");
      setImportPreview((prev) => ({ ...prev, isUploading: false }));
    }
  };

  const openDetail = (user: any) => {
    setSelectedUser(user);
    setIsFlipped(false);
    setIsDetailModalOpen(true);
  };
  const getPreviewNIA = (user: any) => {
    return user.nia || "XXXX.XX.34.XX.XXXX";
  };
  const getSingkatanFakultas = (fakultas: string) => {
    return fakultas || "-";
  };

  return (
    <div className="max-w-7xl mx-auto animate-in fade-in duration-500 pb-12 font-sans text-slate-800 relative">
      {/* 🔥 TOAST NOTIFICATION 🔥 */}
      <div
        className={`fixed top-6 right-6 z-[200] transition-all duration-300 transform ${toast.isOpen ? "translate-y-0 opacity-100" : "-translate-y-4 opacity-0 pointer-events-none"}`}
      >
        <div
          className={`flex items-center gap-3 px-5 py-4 rounded-xl shadow-lg border ${toast.type === "success" ? "bg-white border-emerald-100" : toast.type === "error" ? "bg-white border-red-100" : "bg-white border-blue-100"}`}
        >
          <div
            className={`flex-shrink-0 w-9 h-9 rounded-full flex items-center justify-center shadow-sm ${toast.type === "success" ? "bg-emerald-100 text-emerald-600" : toast.type === "error" ? "bg-red-100 text-red-600" : "bg-blue-100 text-blue-600"}`}
          >
            {toast.type === "success" && (
              <svg
                className="w-5 h-5"
                fill="none"
                viewBox="0 0 24 24"
                stroke="currentColor"
              >
                <path
                  strokeLinecap="round"
                  strokeLinejoin="round"
                  strokeWidth={3}
                  d="M5 13l4 4L19 7"
                />
              </svg>
            )}
            {toast.type === "error" && (
              <svg
                className="w-5 h-5"
                fill="none"
                viewBox="0 0 24 24"
                stroke="currentColor"
              >
                <path
                  strokeLinecap="round"
                  strokeLinejoin="round"
                  strokeWidth={3}
                  d="M6 18L18 6M6 6l12 12"
                />
              </svg>
            )}
          </div>
          <div>
            <p className="text-sm font-bold text-slate-800">
              {toast.type === "success"
                ? "Berhasil!"
                : toast.type === "error"
                  ? "Peringatan!"
                  : "Informasi"}
            </p>
            <p className="text-[13px] text-slate-500 mt-0.5">{toast.message}</p>
          </div>
        </div>
      </div>

      {/* HEADER SECTION */}
      <div className="mb-6 flex flex-col md:flex-row md:items-end justify-between gap-4">
        <div>
          <h2 className="text-2xl font-medium text-slate-900 mb-1 tracking-tight">
            Verifikasi Anggota Baru
          </h2>
          <p className="text-slate-500 text-sm">
            Kelola persetujuan pendaftaran & Kirim notifikasi E-KTA.
          </p>
        </div>
        <div className="flex flex-wrap items-center gap-2">
          <label className="cursor-pointer text-xs font-bold bg-[#F8F9FA] text-slate-700 border border-[#DADCE0] px-4 py-2.5 rounded-lg hover:bg-slate-100 flex items-center gap-2 shadow-sm transition-colors">
            <svg
              className="w-4 h-4 text-slate-500"
              fill="none"
              viewBox="0 0 24 24"
              stroke="currentColor"
            >
              <path
                strokeLinecap="round"
                strokeLinejoin="round"
                strokeWidth={2}
                d="M4 16v1a3 3 0 003 3h10a3 3 0 003-3v-1m-4-8l-4-4m0 0L8 8m4-4v12"
              />
            </svg>
            Import Excel
            <input
              type="file"
              accept=".xlsx, .xls, .csv"
              onChange={handleFileSelect}
              className="hidden"
            />
          </label>
          <button
            onClick={() => setExportModalOpen(true)}
            className="text-xs font-bold bg-white text-slate-700 border border-[#DADCE0] px-4 py-2.5 rounded-lg hover:bg-slate-50 flex items-center gap-2 shadow-sm transition-colors"
          >
            <svg
              className="w-4 h-4 text-slate-500"
              fill="none"
              viewBox="0 0 24 24"
              stroke="currentColor"
            >
              <path
                strokeLinecap="round"
                strokeLinejoin="round"
                strokeWidth={2}
                d="M12 10v6m0 0l-3-3m3 3l3-3m2 8H7a2 2 0 01-2-2V5a2 2 0 012-2h5.586a1 1 0 01.707.293l5.414 5.414a1 1 0 01.293.707V19a2 2 0 01-2 2z"
              />
            </svg>
            Export Excel
          </button>

          {selectedIds.length > 0 && filterStatus === "Disetujui" && (
            <button
              onClick={handleBulkEmailSend}
              disabled={isProcessing}
              className="text-xs bg-[#1A73E8] text-white border border-[#1A73E8] hover:bg-[#1557B0] px-4 py-2.5 rounded-lg transition-colors shadow-sm font-bold flex items-center gap-1.5 ml-2"
            >
              Kirim Email E-KTA ({selectedIds.length})
            </button>
          )}
          {selectedIds.length > 0 && (
            <button
              onClick={() =>
                setDeleteModal({
                  isOpen: true,
                  type: "bulk",
                  id: "",
                  title: `${selectedIds.length} Data Terpilih`,
                })
              }
              className="text-xs bg-white text-[#D93025] border border-[#FCE8E6] hover:bg-[#FCE8E6] px-4 py-2.5 rounded-lg transition-colors shadow-sm font-bold flex items-center gap-1.5 ml-2"
            >
              Hapus ({selectedIds.length})
            </button>
          )}
        </div>
      </div>

      {/* FILTER TABS & SEARCH (GOOGLE WORKSPACE STYLE) */}
      <div className="bg-white rounded-xl border border-[#DADCE0] shadow-sm mb-6 flex flex-col p-2 gap-3">
        <div className="flex flex-col md:flex-row justify-between items-center gap-3">
          {/* TABS */}
          <div className="flex w-full md:w-auto overflow-x-auto no-scrollbar">
            {["Dalam Proses", "Ditolak"].map((tab) => (
              <button
                key={tab}
                onClick={() => {
                  setFilterStatus(tab);
                  setSelectedIds([]);
                }}
                className={`px-5 py-2.5 text-sm font-medium transition-all rounded-lg whitespace-nowrap ${filterStatus === tab ? "bg-[#E8F0FE] text-[#1A73E8] border border-[#1A73E8]/20" : "bg-transparent border-transparent text-slate-600 hover:bg-[#F8F9FA]"}`}
              >
                {tab}{" "}
                <span
                  className={`ml-2 px-2 py-0.5 rounded-md text-[10px] font-bold ${filterStatus === tab ? "bg-[#1A73E8] text-white" : "bg-slate-100 text-slate-500 border border-[#DADCE0]"}`}
                >
                  {pendaftarList.filter((p) => p.status === tab).length}
                </span>
              </button>
            ))}
          </div>

          <div className="flex items-center gap-3 w-full md:w-auto px-2 md:px-0">
            {/* SEARCH BAR */}
            <div className="relative w-full sm:w-64 shrink-0">
              <div className="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none">
                <svg
                  className="h-4 w-4 text-slate-400"
                  fill="none"
                  viewBox="0 0 24 24"
                  stroke="currentColor"
                >
                  <path
                    strokeLinecap="round"
                    strokeLinejoin="round"
                    strokeWidth={2}
                    d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z"
                  />
                </svg>
              </div>
              <input
                type="text"
                placeholder="Cari nama atau NIM..."
                value={searchQuery}
                onChange={(e) => setSearchQuery(e.target.value)}
                className="w-full pl-9 pr-4 py-2 border border-[#DADCE0] rounded-lg text-sm bg-[#F8F9FA] focus:bg-white placeholder-slate-400 focus:outline-none focus:border-[#1A73E8] transition-colors"
              />
            </div>
          </div>
        </div>

        {/* 🔥 CHIP FILTERS (BARU) 🔥 */}
        <div className="flex flex-wrap items-center gap-2 px-2 pb-1 border-t border-slate-100 pt-3 mt-1">
          <svg
            className="w-4 h-4 text-slate-400 mr-1"
            fill="none"
            viewBox="0 0 24 24"
            stroke="currentColor"
          >
            <path
              strokeLinecap="round"
              strokeLinejoin="round"
              strokeWidth={2}
              d="M3 4a1 1 0 011-1h16a1 1 0 011 1v2.586a1 1 0 01-.293.707l-6.414 6.414a1 1 0 00-.293.707V17l-4 4v-6.586a1 1 0 00-.293-.707L3.293 7.293A1 1 0 013 6.586V4z"
            />
          </svg>
          <span className="text-xs font-bold text-slate-500 uppercase tracking-widest mr-2">
            Filter:
          </span>

          <select
            value={filterFakultas}
            onChange={(e) => setFilterFakultas(e.target.value)}
            className="bg-white border border-[#DADCE0] text-slate-600 py-1.5 px-3 rounded-full text-xs font-medium focus:border-[#1A73E8] outline-none cursor-pointer hover:bg-slate-50 transition-colors shadow-sm"
          >
            <option value="">Semua Fakultas</option>
            {optionFakultas.map((opt) => (
              <option key={opt} value={opt}>
                {opt}
              </option>
            ))}
          </select>

          <select
            value={filterAngkatan}
            onChange={(e) => setFilterAngkatan(e.target.value)}
            className="bg-white border border-[#DADCE0] text-slate-600 py-1.5 px-3 rounded-full text-xs font-medium focus:border-[#1A73E8] outline-none cursor-pointer hover:bg-slate-50 transition-colors shadow-sm"
          >
            <option value="">Semua Angkatan</option>
            {optionAngkatan.map((opt) => (
              <option key={opt} value={opt}>
                {opt}
              </option>
            ))}
          </select>

          <select
            value={filterDomisili}
            onChange={(e) => setFilterDomisili(e.target.value)}
            className="bg-white border border-[#DADCE0] text-slate-600 py-1.5 px-3 rounded-full text-xs font-medium focus:border-[#1A73E8] outline-none cursor-pointer hover:bg-slate-50 transition-colors shadow-sm"
          >
            <option value="">Semua Domisili</option>
            {optionDomisili.map((opt) => (
              <option key={opt} value={opt}>
                {opt}
              </option>
            ))}
          </select>

          {(filterFakultas ||
            filterAngkatan ||
            filterDomisili ||
            searchQuery) && (
            <button
              onClick={() => {
                setFilterFakultas("");
                setFilterAngkatan("");
                setFilterDomisili("");
                setSearchQuery("");
              }}
              className="text-xs font-medium text-[#1A73E8] hover:underline ml-2"
            >
              Reset Filter
            </button>
          )}
        </div>
      </div>

      {/* TABLE CONTENT */}
      <div className="bg-white rounded-xl border border-[#DADCE0] shadow-sm overflow-hidden">
        <div className="overflow-x-auto min-h-[400px]">
          {isLoading ? (
            <div className="flex flex-col items-center justify-center py-20">
              <div className="w-10 h-10 border-4 border-[#E8F0FE] border-t-[#1A73E8] rounded-full animate-spin"></div>
              <p className="text-sm text-[#1A73E8] mt-4 font-medium">
                Memuat data...
              </p>
            </div>
          ) : currentData.length === 0 ? (
            <div className="text-center py-20">
              <svg
                className="w-16 h-16 text-slate-300 mx-auto mb-4"
                fill="none"
                viewBox="0 0 24 24"
                stroke="currentColor"
              >
                <path
                  strokeLinecap="round"
                  strokeLinejoin="round"
                  strokeWidth={1.5}
                  d="M12 4.354a4 4 0 110 5.292M15 21H3v-1a6 6 0 0112 0v1zm0 0h6v-1a6 6 0 00-9-5.197M13 7a4 4 0 11-8 0 4 4 0 018 0z"
                />
              </svg>
              <h3 className="font-medium text-slate-800 text-lg mb-1">
                Data Tidak Ditemukan
              </h3>
              <p className="text-slate-500 text-sm">
                Coba sesuaikan filter atau kata kunci pencarian Anda.
              </p>
            </div>
          ) : (
            <table className="w-full text-left text-sm whitespace-nowrap">
              <thead className="bg-[#F8F9FA] border-b border-[#DADCE0] text-slate-500">
                <tr>
                  <th className="px-4 py-4 w-8 text-center border-r border-slate-100">
                    <input
                      type="checkbox"
                      onChange={handleSelectAll}
                      checked={
                        currentData.length > 0 &&
                        selectedIds.length === currentData.length
                      }
                      className="rounded border-slate-300 text-[#1A73E8] focus:ring-[#1A73E8] cursor-pointer"
                    />
                  </th>
                  <th className="px-4 py-4 font-bold text-[11px] uppercase tracking-wider text-center w-12 border-r border-slate-100">
                    No
                  </th>
                  <th 
                    className="px-4 py-4 font-bold text-[11px] uppercase tracking-wider cursor-pointer hover:bg-slate-100 transition-colors group"
                    onClick={() => setSortOrder(sortOrder === "Nama-Asc" ? "Nama-Desc" : "Nama-Asc")}
                  >
                    <div className="flex items-center gap-1">
                      Identitas & Kontak
                      <span className="text-slate-400 group-hover:text-slate-600">
                        {sortOrder === "Nama-Asc" ? "↑" : sortOrder === "Nama-Desc" ? "↓" : "↕"}
                      </span>
                    </div>
                  </th>
                  <th 
                    className="px-4 py-4 font-bold text-[11px] uppercase tracking-wider cursor-pointer hover:bg-slate-100 transition-colors group"
                    onClick={() => setSortOrder(sortOrder === "Fakultas-Asc" ? "Fakultas-Desc" : "Fakultas-Asc")}
                  >
                    <div className="flex items-center gap-1">
                      Latar Belakang UII
                      <span className="text-slate-400 group-hover:text-slate-600">
                        {sortOrder === "Fakultas-Asc" ? "↑" : sortOrder === "Fakultas-Desc" ? "↓" : "↕"}
                      </span>
                    </div>
                  </th>
                  <th 
                    className="px-4 py-4 font-bold text-[11px] uppercase tracking-wider cursor-pointer hover:bg-slate-100 transition-colors group"
                    onClick={() => setSortOrder(sortOrder === "Domisili-Asc" ? "Domisili-Desc" : "Domisili-Asc")}
                  >
                    <div className="flex items-center gap-1">
                      Profesi & Domisili
                      <span className="text-slate-400 group-hover:text-slate-600">
                        {sortOrder === "Domisili-Asc" ? "↑" : sortOrder === "Domisili-Desc" ? "↓" : "↕"}
                      </span>
                    </div>
                  </th>
                  <th 
                    className="px-4 py-4 font-bold text-[11px] uppercase tracking-wider text-center cursor-pointer hover:bg-slate-100 transition-colors group"
                    onClick={() => setSortOrder(sortOrder === "Status-Asc" ? "Status-Desc" : "Status-Asc")}
                  >
                    <div className="flex items-center justify-center gap-1">
                      Status Dokumen
                      <span className="text-slate-400 group-hover:text-slate-600">
                        {sortOrder === "Status-Asc" ? "↑" : sortOrder === "Status-Desc" ? "↓" : "↕"}
                      </span>
                    </div>
                  </th>
                  <th className="px-4 py-4 font-bold text-[11px] uppercase tracking-wider text-right">
                    Aksi
                  </th>
                </tr>
              </thead>
              <tbody className="divide-y divide-[#DADCE0]">
                {currentData.map((user, index) => {
                  const noUrut =
                    itemsPerPage === "Semua"
                      ? index + 1
                      : (currentPage - 1) * (itemsPerPage as number) +
                        index +
                        1;
                  const profileComplete = isProfileComplete(user);

                  return (
                    <tr
                      key={user.id}
                      onClick={() => openDetail(user)}
                      className="hover:bg-[#F8F9FA] transition-colors cursor-pointer group"
                    >
                      <td
                        className="px-4 py-4 text-center border-r border-slate-50"
                        onClick={(e) => e.stopPropagation()}
                      >
                        <input
                          type="checkbox"
                          checked={selectedIds.includes(user.id)}
                          onChange={(e) => handleSelectOne(e, user.id)}
                          className="rounded border-slate-300 text-[#1A73E8] focus:ring-[#1A73E8] cursor-pointer"
                        />
                      </td>
                      <td className="px-4 py-4 text-center font-mono text-xs text-slate-400 border-r border-slate-50">
                        {noUrut}
                      </td>
                      <td className="px-4 py-4">
                        <div className="font-bold text-slate-800 group-hover:text-[#1A73E8] transition-colors">
                          {user.namaLengkap}
                        </div>
                        <div className="text-[11px] text-slate-500 mt-1 font-mono">
                          {user.noWA} • {user.email}
                        </div>
                      </td>
                      <td className="px-4 py-4">
                        <div className="text-sm font-semibold text-slate-700">
                          {user.fakultas}
                        </div>
                        <div className="text-[11px] text-slate-500 mt-0.5">
                          NIM: {user.nim} | Angkatan:{" "}
                          {user.angkatan || user.tahunLulus || "-"}
                        </div>
                      </td>
                      <td className="px-4 py-4">
                        <div className="text-sm font-medium text-slate-700 truncate max-w-[200px]">
                          {user.pekerjaan}
                        </div>
                        <div className="text-[11px] text-slate-400 mt-0.5 truncate max-w-[200px]">
                          Domisili: {user.domisili}
                        </div>
                      </td>
                      <td className="px-4 py-4 text-center">
                        <div className="flex flex-col items-center gap-1.5">
                          <span
                            className={`px-2.5 py-1 rounded border text-[9px] font-bold uppercase tracking-wider ${user.status === "Dalam Proses" ? "bg-[#FEF7E0] text-[#B06000] border-[#FCE8B2]" : user.status === "Disetujui" ? "bg-[#E6F4EA] text-[#1E8E3E] border-[#CEEAD6]" : "bg-[#FCE8E6] text-[#D93025] border-[#FAD2CF]"}`}
                          >
                            {user.status}
                          </span>

                          {/* 🔥 INDIKATOR KELENGKAPAN PROFIL 🔥 */}
                          <span
                            className={`text-[9px] font-bold flex items-center gap-1 ${profileComplete ? "text-emerald-600" : "text-amber-600"}`}
                          >
                            {profileComplete ? (
                              <>✔ Profil Lengkap</>
                            ) : (
                              <>⚠️ Belum Lengkap</>
                            )}
                          </span>

                          {user.status === "Disetujui" && (
                            <span
                              className={`text-[9px] font-bold flex items-center gap-1 ${user.emailSent ? "text-emerald-600" : "text-slate-400"}`}
                            >
                              <svg
                                className="w-3 h-3"
                                fill="none"
                                viewBox="0 0 24 24"
                                stroke="currentColor"
                              >
                                <path
                                  strokeLinecap="round"
                                  strokeLinejoin="round"
                                  strokeWidth={2}
                                  d="M3 8l7.89 5.26a2 2 0 002.22 0L21 8M5 19h14a2 2 0 002-2V7a2 2 0 00-2-2H5a2 2 0 00-2 2v10a2 2 0 002 2z"
                                />
                              </svg>
                              {user.emailSent ? "Terkirim" : "Belum Dikirim"}
                            </span>
                          )}
                        </div>
                      </td>
                      <td
                        className="px-4 py-4 text-right space-x-2"
                        onClick={(e) => e.stopPropagation()}
                      >
                        <button
                          onClick={() => openDetail(user)}
                          className="bg-white hover:bg-slate-50 text-slate-600 font-medium px-3 py-1.5 rounded transition-colors text-xs border border-[#DADCE0] shadow-sm"
                        >
                          Detail
                        </button>
                        <button
                          onClick={() =>
                            setDeleteModal({
                              isOpen: true,
                              type: "single",
                              id: user.id,
                              title: user.namaLengkap,
                            })
                          }
                          className="bg-white hover:bg-[#FCE8E6] text-[#D93025] font-medium p-1.5 rounded transition-colors text-xs border border-[#DADCE0] shadow-sm"
                          title="Hapus Data"
                        >
                          <svg
                            className="w-4 h-4"
                            fill="none"
                            viewBox="0 0 24 24"
                            stroke="currentColor"
                          >
                            <path
                              strokeLinecap="round"
                              strokeLinejoin="round"
                              strokeWidth={2}
                              d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16"
                            />
                          </svg>
                        </button>
                      </td>
                    </tr>
                  );
                })}
              </tbody>
            </table>
          )}
        </div>

        {/* PAGINATION */}
        {itemsPerPage !== "Semua" && totalPages > 1 && (
          <div className="flex items-center justify-between px-6 py-4 border-t border-[#DADCE0] bg-[#F8F9FA]">
            <div className="flex items-center gap-2">
              <span className="text-[11px] font-bold text-slate-500 uppercase tracking-widest whitespace-nowrap">
                Tampilkan:
              </span>
              <select
                value={itemsPerPage}
                onChange={(e) =>
                  setItemsPerPage(
                    e.target.value === "Semua"
                      ? "Semua"
                      : Number(e.target.value),
                  )
                }
                className="bg-white border border-[#DADCE0] py-1 px-2 rounded text-xs font-medium focus:border-[#1A73E8] outline-none cursor-pointer shadow-sm"
              >
                <option value={5}>5</option>
                <option value={10}>10</option>
                <option value={25}>25</option>
                <option value="Semua">Semua</option>
              </select>
            </div>
            <div className="text-xs font-medium text-slate-500">
              {(currentPage - 1) * (itemsPerPage as number) + 1} -{" "}
              {Math.min(
                currentPage * (itemsPerPage as number),
                filteredList.length,
              )}{" "}
              dari {filteredList.length}
            </div>
            <div className="flex items-center gap-1">
              <button
                onClick={() => setCurrentPage((p) => Math.max(1, p - 1))}
                disabled={currentPage === 1}
                className="px-3 py-1.5 border border-[#DADCE0] rounded bg-white text-slate-500 hover:bg-slate-50 disabled:opacity-50 transition-colors shadow-sm text-xs font-bold"
              >
                Prev
              </button>
              <div className="flex items-center gap-1 px-2">
                {Array.from({ length: totalPages }).map((_, i) => (
                  <button
                    key={i}
                    onClick={() => setCurrentPage(i + 1)}
                    className={`w-8 h-8 flex items-center justify-center rounded text-xs font-bold transition-colors shadow-sm ${currentPage === i + 1 ? "bg-[#1A73E8] text-white border border-[#1A73E8]" : "border border-[#DADCE0] bg-white text-slate-600 hover:bg-slate-50"}`}
                  >
                    {i + 1}
                  </button>
                ))}
              </div>
              <button
                onClick={() =>
                  setCurrentPage((p) => Math.min(totalPages, p + 1))
                }
                disabled={currentPage === totalPages}
                className="px-3 py-1.5 border border-[#DADCE0] rounded bg-white text-slate-500 hover:bg-slate-50 disabled:opacity-50 transition-colors shadow-sm text-xs font-bold"
              >
                Next
              </button>
            </div>
          </div>
        )}
      </div>

      {/* ========================================================================= */}
      {/* MODAL EXPORT EXCEL (BARU) */}
      {/* ========================================================================= */}
      {exportModalOpen && (
        <div className="fixed inset-0 z-[60] flex items-center justify-center p-4 bg-slate-900/50 backdrop-blur-sm animate-in fade-in duration-200">
          <div className="bg-white rounded-xl shadow-2xl w-full max-w-md border border-[#DADCE0] overflow-hidden">
            <div className="px-6 py-4 border-b border-[#DADCE0] bg-[#F8F9FA] flex justify-between items-center">
              <h3 className="font-medium text-lg text-slate-800 flex items-center gap-2">
                <svg
                  className="w-5 h-5 text-emerald-600"
                  fill="none"
                  viewBox="0 0 24 24"
                  stroke="currentColor"
                >
                  <path
                    strokeLinecap="round"
                    strokeLinejoin="round"
                    strokeWidth={2}
                    d="M12 10v6m0 0l-3-3m3 3l3-3m2 8H7a2 2 0 01-2-2V5a2 2 0 012-2h5.586a1 1 0 01.707.293l5.414 5.414a1 1 0 01.293.707V19a2 2 0 01-2 2z"
                  />
                </svg>
                Pusat Ekspor Data
              </h3>
              <button
                onClick={() => setExportModalOpen(false)}
                className="text-slate-400 hover:text-[#D93025] hover:bg-[#FCE8E6] p-1 rounded-full transition-colors"
              >
                <svg
                  className="w-5 h-5"
                  fill="none"
                  viewBox="0 0 24 24"
                  stroke="currentColor"
                >
                  <path
                    strokeLinecap="round"
                    strokeLinejoin="round"
                    strokeWidth={2}
                    d="M6 18L18 6M6 6l12 12"
                  />
                </svg>
              </button>
            </div>

            <div className="p-6 space-y-4">
              <div>
                <label className="block text-sm font-bold text-slate-700 mb-3">
                  Pilih Data yang Diekspor:
                </label>
                <div className="space-y-2">
                  <label
                    className={`flex items-center gap-3 p-3 border rounded-lg cursor-pointer transition-colors ${exportTarget === "filtered" ? "border-[#1A73E8] bg-[#E8F0FE]" : "border-[#DADCE0] hover:bg-slate-50"}`}
                  >
                    <input
                      type="radio"
                      name="exportTarget"
                      value="filtered"
                      checked={exportTarget === "filtered"}
                      onChange={(e) => setExportTarget(e.target.value)}
                      className="w-4 h-4 text-[#1A73E8]"
                    />
                    <div>
                      <div className="text-sm font-bold text-slate-800">
                        Sesuai Filter & Pencarian Saat Ini
                      </div>
                      <div className="text-[11px] text-slate-500 mt-0.5">
                        Ekspor {filteredList.length} data yang tampil di tabel
                        sekarang.
                      </div>
                    </div>
                  </label>
                  <label
                    className={`flex items-center gap-3 p-3 border rounded-lg cursor-pointer transition-colors ${exportTarget === "all" ? "border-[#1A73E8] bg-[#E8F0FE]" : "border-[#DADCE0] hover:bg-slate-50"}`}
                  >
                    <input
                      type="radio"
                      name="exportTarget"
                      value="all"
                      checked={exportTarget === "all"}
                      onChange={(e) => setExportTarget(e.target.value)}
                      className="w-4 h-4 text-[#1A73E8]"
                    />
                    <div>
                      <div className="text-sm font-bold text-slate-800">
                        Semua Master Data
                      </div>
                      <div className="text-[11px] text-slate-500 mt-0.5">
                        Ekspor seluruh {pendaftarList.length} data dari semua
                        status dan angkatan.
                      </div>
                    </div>
                  </label>
                </div>
              </div>
            </div>

            <div className="px-6 py-4 border-t border-[#DADCE0] bg-[#F8F9FA] flex justify-between items-center">
              <button
                onClick={handleDownloadTemplate}
                className="text-[11px] font-bold text-slate-600 hover:text-[#1A73E8] underline flex items-center gap-1"
              >
                Unduh Template Import Excel
              </button>
              <div className="flex gap-2">
                <button
                  onClick={() => setExportModalOpen(false)}
                  className="px-4 py-2 border border-[#DADCE0] rounded text-sm font-medium text-slate-600 hover:bg-slate-50 transition-colors shadow-sm"
                >
                  Batal
                </button>
                <button
                  onClick={executeExport}
                  className="px-4 py-2 bg-[#1A73E8] hover:bg-[#1557B0] text-white rounded text-sm font-medium transition-colors shadow-sm flex items-center gap-1.5"
                >
                  Ekspor Sekarang
                </button>
              </div>
            </div>
          </div>
        </div>
      )}

      {/* ========================================================================= */}
      {/* MODAL IMPORT PREVIEW (TIPE B - PROGRESS BAR) */}
      {/* ========================================================================= */}
      {importPreview.isOpen && (
        <div className="fixed inset-0 z-[70] flex items-center justify-center p-4 bg-slate-900/60 backdrop-blur-sm animate-in fade-in duration-200">
          <div className="bg-white rounded-2xl shadow-2xl max-w-4xl w-full flex flex-col border border-[#DADCE0] overflow-hidden">
            <div className="flex justify-between items-center px-6 py-4 border-b border-slate-200 bg-[#F8F9FA]">
              <div>
                <h3 className="font-medium text-lg text-slate-800">
                  Pratinjau Data Import (Mode Aman)
                </h3>
                <p className="text-xs text-slate-500 mt-0.5">
                  Total baris:{" "}
                  <span className="font-bold text-slate-700">
                    {importPreview.data.length}
                  </span>{" "}
                  |
                  <span className="text-emerald-600 font-bold ml-2">
                    {" "}
                    {importPreview.successCount} Aman
                  </span>{" "}
                  |
                  <span className="text-red-600 font-bold ml-2">
                    {" "}
                    {importPreview.failedCount} Gagal/Duplikat
                  </span>
                </p>
              </div>
              {!importPreview.isUploading && (
                <button
                  onClick={() =>
                    setImportPreview({
                      isOpen: false,
                      data: [],
                      successCount: 0,
                      failedCount: 0,
                      isUploading: false,
                      progress: 0,
                      currentItem: "",
                    })
                  }
                  className="text-slate-400 hover:text-[#D93025] hover:bg-[#FCE8E6] p-1.5 rounded-full transition-colors"
                >
                  <svg
                    className="w-5 h-5"
                    fill="none"
                    viewBox="0 0 24 24"
                    stroke="currentColor"
                  >
                    <path
                      strokeLinecap="round"
                      strokeLinejoin="round"
                      strokeWidth={2}
                      d="M6 18L18 6M6 6l12 12"
                    />
                  </svg>
                </button>
              )}
            </div>

            {/* PROGRESS BAR OVERLAY JIKA UPLOADING */}
            {importPreview.isUploading ? (
              <div className="p-10 flex flex-col items-center justify-center min-h-[300px] bg-white">
                <div className="w-full max-w-md bg-slate-100 rounded-full h-3 mb-4 overflow-hidden border border-[#DADCE0] relative">
                  <div
                    className="bg-[#1A73E8] h-full transition-all duration-300 ease-out relative"
                    style={{
                      width: `${(importPreview.progress / importPreview.successCount) * 100}%`,
                    }}
                  >
                    <div className="absolute top-0 left-0 right-0 bottom-0 bg-white/20 w-full animate-[shimmer_1s_infinite]"></div>
                  </div>
                </div>
                <h4 className="text-lg font-bold text-slate-800 mb-1">
                  {Math.round(
                    (importPreview.progress / importPreview.successCount) * 100,
                  )}
                  % Selesai
                </h4>
                <p className="text-sm font-medium text-slate-500 mb-2">
                  Memproses {importPreview.progress} dari{" "}
                  {importPreview.successCount} data aman...
                </p>
                <p className="text-[11px] font-mono text-[#1A73E8] bg-blue-50 px-3 py-1 rounded border border-blue-100 truncate max-w-sm">
                  Mendaftarkan: {importPreview.currentItem}
                </p>
                <p className="text-[10px] text-slate-400 mt-6 italic">
                  Harap jangan menutup jendela ini hingga proses selesai.
                </p>
              </div>
            ) : (
              <div className="p-6 overflow-y-auto bg-slate-50">
                <div className="border border-[#DADCE0] rounded-xl overflow-hidden bg-white max-h-[50vh] overflow-y-auto custom-scrollbar">
                  <table className="w-full text-left text-xs whitespace-nowrap">
                    <thead className="bg-[#F8F9FA] text-slate-500 font-bold sticky top-0 border-b border-[#DADCE0] shadow-sm z-10">
                      <tr>
                        <th className="p-3 w-10 text-center">No</th>
                        <th className="p-3">Nama Lengkap</th>
                        <th className="p-3">Email & No WA</th>
                        <th className="p-3">NIM / Angkatan</th>
                        <th className="p-3 text-center">Status Pengecekan</th>
                      </tr>
                    </thead>
                    <tbody className="divide-y divide-[#DADCE0]">
                      {importPreview.data.map((row, index) => (
                        <tr
                          key={index}
                          className={
                            row.isValid
                              ? "hover:bg-slate-50"
                              : "bg-[#FCE8E6]/50"
                          }
                        >
                          <td className="p-3 text-center text-slate-400 font-mono">
                            {index + 1}
                          </td>
                          <td className="p-3 font-semibold text-slate-800">
                            {row.namaLengkap || "-"}
                          </td>
                          <td className="p-3">
                            <div className="font-mono text-slate-700">
                              {row.email || "-"}
                            </div>
                            <div className="text-[10px] text-slate-400">
                              {row.noWA || "-"}
                            </div>
                          </td>
                          <td className="p-3 font-mono">
                            {row.nim || "-"} / {row.tahunLulus || "-"}
                          </td>
                          <td className="p-3 text-center">
                            <span
                              className={`px-2.5 py-1 rounded text-[9px] font-bold uppercase tracking-wider ${row.isValid ? "bg-[#E6F4EA] text-[#1E8E3E] border border-[#CEEAD6]" : "bg-white text-[#D93025] border border-[#FAD2CF]"}`}
                            >
                              {row.statusPesan}
                            </span>
                          </td>
                        </tr>
                      ))}
                    </tbody>
                  </table>
                </div>
                <div className="mt-4 bg-blue-50 border border-blue-100 p-3 rounded-lg text-[11px] text-blue-800 leading-relaxed font-medium">
                  <strong className="text-blue-900 block mb-1">
                    💡 Preview Data:
                  </strong>
                  Data yang aman (Hijau) akan dimasukkan ke tabel{" "}
                  <span className="bg-white border border-blue-200 px-1.5 py-0.5 rounded">
                    Dalam Proses
                  </span>
                  . Sistem <strong>TIDAK</strong> akan mencetak NIA dan{" "}
                  <strong>TIDAK</strong> membuatkan akun login secara otomatis.
                  Anda dapat mereview dan menyetujuinya satu per satu (atau
                  massal) nanti.
                </div>
              </div>
            )}

            {!importPreview.isUploading && (
              <div className="px-6 py-4 border-t border-[#DADCE0] bg-[#F8F9FA] flex justify-end gap-3 shrink-0">
                <button
                  onClick={() =>
                    setImportPreview({
                      isOpen: false,
                      data: [],
                      successCount: 0,
                      failedCount: 0,
                      isUploading: false,
                      progress: 0,
                      currentItem: "",
                    })
                  }
                  className="px-4 py-2 border border-[#DADCE0] rounded text-sm text-slate-600 bg-white hover:bg-slate-50 transition-colors shadow-sm font-medium"
                >
                  Batal
                </button>
                <button
                  onClick={executeImportProgress}
                  disabled={importPreview.successCount === 0}
                  className="px-5 py-2 bg-[#1A73E8] hover:bg-[#1557B0] text-white rounded text-sm font-bold transition-colors shadow-sm disabled:opacity-50 flex items-center gap-2"
                >
                  <svg
                    className="w-4 h-4"
                    fill="none"
                    viewBox="0 0 24 24"
                    stroke="currentColor"
                  >
                    <path
                      strokeLinecap="round"
                      strokeLinejoin="round"
                      strokeWidth={2}
                      d="M7 16a4 4 0 01-.88-7.903A5 5 0 1115.9 6L16 6a5 5 0 011 9.9M15 13l-3-3m0 0l-3 3m3-3v12"
                    />
                  </svg>
                  Mulai Import {importPreview.successCount} Data Aman
                </button>
              </div>
            )}
          </div>
        </div>
      )}

      {/* ========================================================================= */}
      {/* MODAL DETAIL & ACTION (TIDAK BERUBAH) */}
      {/* ========================================================================= */}

      {/* 1. MODAL DETAIL USER */}
      {isDetailModalOpen && selectedUser && (
        <div className="fixed inset-0 z-40 flex items-center justify-center p-4 sm:p-6 bg-slate-900/60 backdrop-blur-sm animate-in fade-in duration-200">
          <div className="bg-white rounded-2xl shadow-2xl max-w-2xl w-full max-h-[90vh] flex flex-col overflow-hidden border border-[#DADCE0] animate-in zoom-in-95">
            <div className="flex justify-between items-center px-6 py-5 border-b border-[#DADCE0] bg-[#F8F9FA] shrink-0">
              <h3 className="font-medium text-lg text-slate-800">
                Detail Pendaftar
              </h3>
              <button
                onClick={() => setIsDetailModalOpen(false)}
                className="text-slate-400 hover:text-[#D93025] hover:bg-[#FCE8E6] p-1.5 rounded-full transition-colors"
              >
                <svg
                  className="w-5 h-5"
                  fill="none"
                  viewBox="0 0 24 24"
                  stroke="currentColor"
                >
                  <path
                    strokeLinecap="round"
                    strokeLinejoin="round"
                    strokeWidth={2}
                    d="M6 18L18 6M6 6l12 12"
                  />
                </svg>
              </button>
            </div>

            <div className="px-6 py-6 overflow-y-auto flex-grow custom-scrollbar space-y-6 bg-white">
              {/* 🔥 PREVIEW E-KTA PORTRAIT (HANYA JIKA DISETUJUI & PROFIL LENGKAP ATAU SUDAH PUNYA NIA) 🔥 */}
              {selectedUser.status === "Disetujui" &&
                selectedUser.nia !== "Dalam Proses" && (
                  <div className="mb-8 border-b border-slate-100 pb-8 flex flex-col items-center">
                    <h4 className="text-[10px] font-bold text-slate-500 uppercase tracking-widest mb-4 text-center">
                      Preview Desain E-KTA (2 Sisi)
                    </h4>

                    {/* Container Scaled KTA Portrait dengan 3D Prespective */}
                    <div className="relative w-full max-w-[280px] aspect-[380/600] perspective-1000">
                      <div
                        className="relative w-full h-full transition-transform duration-700 transform-style-3d cursor-pointer shadow-[0_10px_30px_rgba(0,0,0,0.15)] rounded-[16px] border border-slate-200"
                        style={{
                          transform: isFlipped
                            ? "rotateY(180deg)"
                            : "rotateY(0deg)",
                        }}
                        onClick={() => setIsFlipped(!isFlipped)}
                      >
                        {/* --- BAGIAN DEPAN (PORTRAIT) --- */}
                        <div className="absolute inset-0 backface-hidden bg-white rounded-[16px] overflow-hidden flex flex-col">
                          <div className="absolute inset-0 bg-slate-50 opacity-50 bg-[url('https://www.transparenttextures.com/patterns/clean-textile.png')] z-0"></div>
                          <img
                            src="/logo-dpp-ika.png"
                            className="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 w-40 h-40 opacity-[0.03] grayscale pointer-events-none z-0"
                          />

                          {/* Header KTA */}
                          <div className="relative pt-6 pb-4 w-full shrink-0 z-10 bg-[#0B1528] flex flex-col items-center justify-center">
                            <div className="absolute bottom-0 left-0 right-0 h-3 bg-[#224A9A]"></div>
                            <div className="bg-white p-1 rounded-full w-[48px] h-[48px] flex items-center justify-center shadow-md border-[2px] border-white/20 mb-2 relative z-10">
                              <img
                                src="/logo-dpp-ika.png"
                                alt="Logo"
                                className="w-full h-full object-contain"
                              />
                            </div>
                            <div className="flex flex-col z-10 px-4 text-center">
                              <h1 className="text-white font-black text-[14px] tracking-widest uppercase leading-none mb-1">
                                KARTU TANDA ANGGOTA
                              </h1>
                              <h2 className="text-[#F29900] font-bold text-[8px] tracking-[0.2em] uppercase">
                                DPW IKA UII D.I.YOGYAKARTA
                              </h2>
                            </div>
                          </div>
                          <div className="h-[4px] w-full bg-[#F29900] shrink-0 z-10 relative"></div>

                          {/* Body KTA */}
                          <div className="flex-grow flex flex-col items-center px-4 py-6 relative z-10 text-center">
                            <div className="w-[100px] h-[130px] bg-[#F8F9FA] rounded-lg border-[3px] border-white shadow-md overflow-hidden shrink-0 mb-4">
                              {selectedUser.fotoUrl ? (
                                <img
                                  src={selectedUser.fotoUrl}
                                  className="w-full h-full object-cover object-top"
                                />
                              ) : (
                                <div className="w-full h-full flex flex-col items-center justify-center text-[#9AA0A6] text-[10px] font-medium bg-[#E8EAED]">
                                  <span>Tanpa Foto</span>
                                </div>
                              )}
                            </div>

                            <div className="w-full space-y-3">
                              <div>
                                <p className="text-[15px] font-black text-[#0B1528] uppercase leading-tight line-clamp-2 px-2">
                                  {selectedUser.namaLengkap}
                                </p>
                              </div>
                              <div>
                                <p className="text-[8px] font-bold text-[#9AA0A6] uppercase tracking-widest mb-0.5">
                                  Nomor Induk Anggota
                                </p>
                                <p className="text-[12px] font-bold text-[#0B1528] tracking-widest leading-none font-mono bg-[#F8F9FA] inline-block px-3 py-1 rounded border border-[#EBEBEB]">
                                  {getPreviewNIA(selectedUser)}
                                </p>
                              </div>
                              <div>
                                <p className="text-[8px] font-bold text-[#9AA0A6] uppercase tracking-widest mb-0.5">
                                  Fakultas / Jurusan / Angkatan
                                </p>
                                <p className="text-[10px] font-black text-[#224A9A] uppercase leading-tight">
                                  {getSingkatanFakultas(selectedUser.fakultas)}{" "}
                                  / {selectedUser.programStudi || "-"} /{" "}
                                  {selectedUser.angkatan ||
                                    selectedUser.tahunLulus ||
                                    "-"}
                                </p>
                              </div>
                            </div>
                          </div>

                          {/* Footer KTA */}
                          <div className="py-3 bg-[#F8FAFC] border-t border-[#EBEBEB] shrink-0 z-10 flex flex-col items-center justify-center">
                            <p className="text-[9px] font-black text-[#0B1528] tracking-[0.2em] uppercase">
                              IKADIY.UII.AC.ID
                            </p>
                          </div>
                        </div>

                        {/* --- BAGIAN BELAKANG (PORTRAIT) --- */}
                        <div
                          className="absolute inset-0 backface-hidden bg-white rounded-[16px] overflow-hidden flex flex-col"
                          style={{ transform: "rotateY(180deg)" }}
                        >
                          <div className="absolute inset-0 bg-slate-50 opacity-50 bg-[url('https://www.transparenttextures.com/patterns/clean-textile.png')] z-0"></div>
                          <img
                            src="/logo-dpp-ika.png"
                            className="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 w-32 h-32 opacity-[0.03] grayscale pointer-events-none z-0"
                          />

                          <div className="h-[18px] bg-[#0B1528] w-full shrink-0 z-10 flex">
                            <div className="w-[70%] bg-[#0B1528] h-full"></div>
                            <div
                              className="w-[30%] bg-[#224A9A] h-full"
                              style={{
                                clipPath:
                                  "polygon(15% 0, 100% 0, 100% 100%, 0% 100%)",
                              }}
                            ></div>
                          </div>
                          <div className="h-[4px] bg-[#F29900] w-full shrink-0 z-10"></div>

                          <div className="flex-grow flex flex-col px-6 py-6 items-center z-10 relative">
                            <h3 className="text-[12px] font-black text-[#0B1528] uppercase tracking-widest mb-5 border-b-2 border-[#EBEBEB] pb-1.5 text-center w-full">
                              Ketentuan Penggunaan
                            </h3>

                            <ol className="text-[9px] text-[#5F6368] space-y-3 pl-3 list-decimal leading-relaxed text-justify w-full font-medium mb-auto">
                              <li>
                                Kartu ini diterbitkan oleh DPW IKA UII
                                Yogyakarta dan merupakan bukti keanggotaan yang
                                sah.
                              </li>
                              <li>
                                Kartu tidak dapat dipindahtangankan dan wajib
                                ditunjukkan untuk mengakses layanan, acara, atau
                                klaim potongan harga pada mitra.
                              </li>
                              <li>
                                Apabila menemukan kartu ini, harap dikembalikan
                                kepada Sekretariat DPW IKA UII DIY melalui
                                email: <strong>ika.diy@uii.ac.id</strong>.
                              </li>
                            </ol>

                            <div className="flex flex-col items-center w-full mt-6 pt-6 border-t border-[#EBEBEB]">
                              <div className="w-[100px] h-[100px] p-2 bg-white border border-[#DADCE0] rounded-xl shadow-sm mb-2.5 relative z-10">
                                <QRCode
                                  value={`https://ikadiy.uii.ac.id/kta/${selectedUser.id}`}
                                  size={96}
                                  style={{ width: "100%", height: "100%" }}
                                  level="M"
                                />
                              </div>
                              <p className="text-[9px] font-black text-[#0B1528] tracking-widest uppercase bg-[#F8F9FA] px-3 py-1 rounded border border-[#EBEBEB]">
                                Scan Validasi
                              </p>
                            </div>
                          </div>
                        </div>
                      </div>
                    </div>

                    <button
                      onClick={() => setIsFlipped(!isFlipped)}
                      className="mt-5 text-[10px] font-bold text-[#1A73E8] bg-blue-50 border border-blue-100 px-4 py-2 rounded-full hover:bg-blue-100 flex items-center gap-1.5 transition-transform hover:scale-105"
                    >
                      <svg
                        className="w-3.5 h-3.5"
                        fill="none"
                        viewBox="0 0 24 24"
                        stroke="currentColor"
                      >
                        <path
                          strokeLinecap="round"
                          strokeLinejoin="round"
                          strokeWidth={2}
                          d="M4 4v5h.582m15.356 2A8.001 8.001 0 004.582 9m0 0H9m11 11v-5h-.581m0 0a8.003 8.003 0 01-15.357-2m15.357 2H15"
                        />
                      </svg>
                      Putar Kartu (Klik Disini)
                    </button>
                  </div>
                )}

              {/* 🔥 WARNING BOX JIKA PROFIL BELUM LENGKAP 🔥 */}
              {!isProfileComplete(selectedUser) && (
                <div className="bg-amber-50 border border-amber-200 text-amber-700 p-4 rounded-xl text-sm font-medium mb-4 flex gap-3 items-start shadow-sm">
                  <span className="text-xl leading-none shrink-0 mt-0.5">
                    ⚠️
                  </span>
                  <div>
                    <h4 className="font-bold mb-1">Profil Belum Lengkap!</h4>
                    <p className="opacity-90 leading-relaxed text-xs">
                      Pendaftar ini belum mengunggah foto profil resmi atau
                      belum melengkapi domisili. <br />
                      Jika disetujui, NIA akan berstatus <b>
                        "Dalam Proses"
                      </b>{" "}
                      dan E-KTA <b>tidak akan diterbitkan</b> sampai data
                      dilengkapi.
                    </p>
                  </div>
                </div>
              )}

              {selectedUser.status === "Ditolak" &&
                selectedUser.alasanPenolakan && (
                  <div className="bg-[#FCE8E6] border border-[#FAD2CF] p-4 rounded-xl flex gap-3">
                    <svg
                      className="w-5 h-5 text-[#D93025] shrink-0 mt-0.5"
                      fill="none"
                      viewBox="0 0 24 24"
                      stroke="currentColor"
                    >
                      <path
                        strokeLinecap="round"
                        strokeLinejoin="round"
                        strokeWidth={2.5}
                        d="M12 9v2m0 4h.01m-6.938 4h13.856c1.54 0 2.502-1.667 1.732-3L13.732 4c-.77-1.333-2.694-1.333-3.464 0L3.34 16c-.77 1.333.192 3 1.732 3z"
                      />
                    </svg>
                    <div>
                      <h4 className="text-xs font-bold text-[#D93025] mb-1">
                        Alasan Penolakan:
                      </h4>
                      <p className="text-sm font-medium text-[#D93025]">
                        {selectedUser.alasanPenolakan}
                      </p>
                    </div>
                  </div>
                )}

              <div className="grid sm:grid-cols-2 gap-6">
                <div>
                  <h4 className="text-[10px] font-bold text-slate-500 uppercase tracking-widest mb-1">
                    Nama Lengkap
                  </h4>
                  <p className="font-medium text-slate-800 text-lg">
                    {selectedUser.namaLengkap}
                  </p>
                </div>
                <div>
                  <h4 className="text-[10px] font-bold text-slate-500 uppercase tracking-widest mb-1">
                    Waktu Pendaftaran
                  </h4>
                  <p className="font-medium text-slate-700">
                    {new Date(selectedUser.tanggalDaftar).toLocaleDateString(
                      "id-ID",
                      {
                        day: "numeric",
                        month: "long",
                        year: "numeric",
                        hour: "2-digit",
                        minute: "2-digit",
                      },
                    )}{" "}
                    WIB
                  </p>
                </div>
              </div>

              <div className="bg-[#F8F9FA] p-5 rounded-xl border border-[#DADCE0] grid sm:grid-cols-2 gap-5">
                <div>
                  <h4 className="text-[10px] font-bold text-[#1A73E8] uppercase tracking-widest mb-1">
                    Fakultas & Prodi
                  </h4>
                  <p className="font-bold text-slate-800 text-sm mb-0.5">
                    {selectedUser.fakultas}
                  </p>
                  <p className="font-medium text-slate-600 text-xs">
                    {selectedUser.programStudi}
                  </p>
                </div>
                <div>
                  <h4 className="text-[10px] font-bold text-[#1A73E8] uppercase tracking-widest mb-1">
                    NIM & Angkatan
                  </h4>
                  <p className="font-bold text-slate-800 text-sm mb-0.5">
                    NIM: {selectedUser.nim}
                  </p>
                  <p className="font-medium text-slate-600 text-xs">
                    Angkatan:{" "}
                    {selectedUser.angkatan || selectedUser.tahunLulus || "-"}
                  </p>
                </div>
              </div>

              <div className="grid sm:grid-cols-2 gap-6 border-t border-slate-100 pt-6">
                <div>
                  <h4 className="text-[10px] font-bold text-slate-500 uppercase tracking-widest mb-1">
                    Kontak
                  </h4>
                  <p className="font-mono text-sm font-medium text-[#1E8E3E] flex items-center gap-1.5 mb-1.5">
                    <svg
                      className="w-4 h-4"
                      fill="none"
                      viewBox="0 0 24 24"
                      stroke="currentColor"
                    >
                      <path
                        strokeLinecap="round"
                        strokeLinejoin="round"
                        strokeWidth={2}
                        d="M3 5a2 2 0 012-2h3.28a1 1 0 01.948.684l1.498 4.493a1 1 0 01-.502 1.21l-2.257 1.13a11.042 11.042 0 005.516 5.516l1.13-2.257a1 1 0 011.21-.502l4.493 1.498a1 1 0 01.684.949V19a2 2 0 01-2 2h-1C9.716 21 3 14.284 3 6V5z"
                      />
                    </svg>
                    {selectedUser.noWA}
                  </p>
                  <p className="font-mono text-sm font-medium text-[#1A73E8] flex items-center gap-1.5">
                    <svg
                      className="w-4 h-4"
                      fill="none"
                      viewBox="0 0 24 24"
                      stroke="currentColor"
                    >
                      <path
                        strokeLinecap="round"
                        strokeLinejoin="round"
                        strokeWidth={2}
                        d="M3 8l7.89 5.26a2 2 0 002.22 0L21 8M5 19h14a2 2 0 002-2V7a2 2 0 00-2-2H5a2 2 0 00-2 2v10a2 2 0 002 2z"
                      />
                    </svg>
                    {selectedUser.email}
                  </p>
                </div>
                <div>
                  <h4 className="text-[10px] font-bold text-slate-500 uppercase tracking-widest mb-1">
                    Domisili & Pekerjaan
                  </h4>
                  <p className="font-medium text-slate-800 text-sm mb-1.5 flex items-center gap-1.5">
                    <svg
                      className="w-4 h-4 text-slate-400"
                      fill="none"
                      viewBox="0 0 24 24"
                      stroke="currentColor"
                    >
                      <path
                        strokeLinecap="round"
                        strokeLinejoin="round"
                        strokeWidth={2}
                        d="M17.657 16.657L13.414 20.9a1.998 1.998 0 01-2.827 0l-4.244-4.243a8 8 0 1111.314 0z"
                      />
                      <path
                        strokeLinecap="round"
                        strokeLinejoin="round"
                        strokeWidth={2}
                        d="M15 11a3 3 0 11-6 0 3 3 0 016 0z"
                      />
                    </svg>
                    {selectedUser.domisili}
                  </p>

                  <p className="font-medium text-slate-600 text-[11px] mb-1.5 pl-5 italic leading-relaxed">
                    {selectedUser.alamatLengkap || "Alamat lengkap belum diisi"}
                  </p>

                  <p className="font-medium text-slate-800 text-sm flex items-center gap-1.5">
                    <svg
                      className="w-4 h-4 text-slate-400"
                      fill="none"
                      viewBox="0 0 24 24"
                      stroke="currentColor"
                    >
                      <path
                        strokeLinecap="round"
                        strokeLinejoin="round"
                        strokeWidth={2}
                        d="M21 13.255A23.931 23.931 0 0112 15c-3.183 0-6.22-.62-9-1.745M16 6V4a2 2 0 00-2-2h-4a2 2 0 00-2 2v2m4 6h.01M5 20h14a2 2 0 002-2V8a2 2 0 00-2-2H5a2 2 0 00-2 2v10a2 2 0 002 2z"
                      />
                    </svg>
                    {selectedUser.pekerjaan}
                  </p>
                </div>
              </div>

              <div className="border-t border-slate-100 pt-6 space-y-5">
                <div>
                  <h4 className="text-[10px] font-bold text-slate-500 uppercase tracking-widest mb-2">
                    Bidang Keahlian
                  </h4>
                  <p className="font-medium text-slate-700 bg-slate-50 p-3.5 rounded-lg border border-[#DADCE0] text-sm leading-relaxed">
                    {selectedUser.keahlian || selectedUser.bidang || "-"}
                  </p>
                </div>
                <div>
                  <h4 className="text-[10px] font-bold text-slate-500 uppercase tracking-widest mb-2">
                    Motivasi & Harapan
                  </h4>
                  <p className="font-medium text-slate-700 bg-[#E8F0FE] p-3.5 rounded-lg border border-[#1A73E8]/20 text-sm leading-relaxed italic">
                    "{selectedUser.motto}"
                  </p>
                </div>
              </div>
            </div>

            <div className="px-6 py-4 border-t border-[#DADCE0] bg-[#F8F9FA] shrink-0 flex gap-3 justify-end items-center">
              {/* 🔥 TOMBOL KIRIM ULANG EMAIL (HANYA MUNCUL JIKA STATUS DISETUJUI) 🔥 */}
              {selectedUser.status === "Disetujui" ? (
                <button
                  onClick={() => resendApprovedEmail(selectedUser)}
                  disabled={isProcessing}
                  className="px-5 py-2.5 bg-emerald-600 hover:bg-emerald-700 text-white font-medium rounded text-sm transition-colors shadow-sm flex items-center gap-2 mr-auto"
                >
                  <svg
                    className="w-4 h-4"
                    fill="none"
                    viewBox="0 0 24 24"
                    stroke="currentColor"
                  >
                    <path
                      strokeLinecap="round"
                      strokeLinejoin="round"
                      strokeWidth={2}
                      d="M3 8l7.89 5.26a2 2 0 002.22 0L21 8M5 19h14a2 2 0 002-2V7a2 2 0 00-2-2H5a2 2 0 00-2 2v10a2 2 0 002 2z"
                    />
                  </svg>
                  {selectedUser.nia === "Dalam Proses"
                    ? "Terbitkan E-KTA Sekarang"
                    : "Kirim Ulang Email E-KTA"}
                </button>
              ) : null}

              {selectedUser.status === "Dalam Proses" ? (
                <>
                  <button
                    onClick={() =>
                      setRejectModal({
                        isOpen: true,
                        user: selectedUser,
                        reason: "",
                      })
                    }
                    className="px-5 py-2.5 bg-white border border-[#DADCE0] hover:bg-[#FCE8E6] text-slate-600 hover:text-[#D93025] hover:border-[#FAD2CF] font-medium rounded text-sm transition-colors shadow-sm"
                  >
                    Tolak
                  </button>
                  <button
                    onClick={() =>
                      setApproveModal({ isOpen: true, user: selectedUser })
                    }
                    className="px-5 py-2.5 bg-[#1A73E8] hover:bg-[#1557B0] text-white font-medium rounded text-sm transition-colors shadow-sm flex items-center gap-2"
                  >
                    Setujui Menjadi Anggota
                  </button>
                </>
              ) : (
                <button
                  onClick={() => setIsDetailModalOpen(false)}
                  className="px-6 py-2.5 bg-white border border-[#DADCE0] text-slate-600 hover:bg-slate-50 font-medium rounded text-sm transition-colors shadow-sm"
                >
                  Tutup
                </button>
              )}
            </div>
          </div>
        </div>
      )}

      {/* 2. MODAL KONFIRMASI APPROVE */}
      {approveModal.isOpen && approveModal.user && (
        <div className="fixed inset-0 z-[60] flex items-center justify-center p-4 bg-slate-900/50 backdrop-blur-sm animate-in fade-in duration-200">
          <div className="bg-white rounded-xl shadow-2xl p-6 max-w-sm w-full text-center border border-[#DADCE0]">
            <div className="w-14 h-14 bg-[#E6F4EA] text-[#1E8E3E] rounded-full flex items-center justify-center mx-auto mb-4">
              <svg
                className="w-7 h-7"
                fill="none"
                viewBox="0 0 24 24"
                stroke="currentColor"
              >
                <path
                  strokeLinecap="round"
                  strokeLinejoin="round"
                  strokeWidth={3}
                  d="M5 13l4 4L19 7"
                />
              </svg>
            </div>
            <h3 className="text-lg font-medium text-slate-800 mb-2">
              Setujui Anggota Baru
            </h3>

            {isProfileComplete(approveModal.user) ? (
              <p className="text-sm text-slate-500 mb-6 leading-relaxed">
                Data <strong>{approveModal.user.namaLengkap}</strong> akan
                disetujui. Sistem otomatis <strong>mencetak NIA</strong> dan{" "}
                <strong>mengirim E-KTA</strong> ke emailnya.
              </p>
            ) : (
              <div className="mb-5 mt-2 bg-amber-50 p-3 rounded-lg border border-amber-200 text-amber-700 text-xs font-medium text-left">
                ⚠️ Pendaftar ini belum melengkapi foto/domisili. <br />
                <br />
                Data akan disetujui dan masuk tab Disetujui, namun NIA akan
                berstatus <b>"Dalam Proses"</b> dan E-KTA tidak akan dikirim
                otomatis.
              </div>
            )}

            <div className="flex gap-3 justify-center border-t border-[#DADCE0] pt-5 mt-2">
              <button
                onClick={() => setApproveModal({ isOpen: false, user: null })}
                disabled={isProcessing}
                className="px-4 py-2 rounded text-sm font-medium text-slate-600 hover:bg-slate-100 transition-colors w-full"
              >
                Batal
              </button>
              <button
                onClick={executeApprove}
                disabled={isProcessing}
                className="px-4 py-2 rounded text-sm font-medium text-white bg-[#1A73E8] hover:bg-[#1557B0] transition-colors w-full shadow-sm flex items-center justify-center gap-2 disabled:opacity-70"
              >
                {isProcessing ? "Memproses..." : "Ya, Setujui"}
              </button>
            </div>
          </div>
        </div>
      )}

      {/* 3. MODAL KONFIRMASI REJECT */}
      {rejectModal.isOpen && rejectModal.user && (
        <div className="fixed inset-0 z-[60] flex items-center justify-center p-4 bg-slate-900/50 backdrop-blur-sm animate-in fade-in duration-200">
          <div className="bg-white rounded-xl shadow-2xl p-6 max-w-md w-full border border-[#DADCE0]">
            <div className="flex items-center gap-3 mb-4">
              <div className="w-10 h-10 bg-[#FCE8E6] text-[#D93025] rounded-full flex items-center justify-center shrink-0">
                <svg
                  className="w-5 h-5"
                  fill="none"
                  viewBox="0 0 24 24"
                  stroke="currentColor"
                >
                  <path
                    strokeLinecap="round"
                    strokeLinejoin="round"
                    strokeWidth={2.5}
                    d="M6 18L18 6M6 6l12 12"
                  />
                </svg>
              </div>
              <div>
                <h3 className="text-lg font-medium text-slate-800 leading-tight">
                  Tolak Pendaftaran
                </h3>
                <p className="text-xs text-slate-500 mt-0.5">
                  {rejectModal.user.namaLengkap}
                </p>
              </div>
            </div>
            <form onSubmit={executeReject}>
              <div className="mb-6 mt-4">
                <label className="block text-xs font-bold text-slate-600 mb-2 uppercase tracking-wider">
                  Alasan Penolakan <span className="text-[#D93025]">*</span>
                </label>
                <textarea
                  required
                  rows={3}
                  placeholder="Cth: NIM tidak valid / Bukan alumni UII..."
                  value={rejectModal.reason}
                  onChange={(e) =>
                    setRejectModal({ ...rejectModal, reason: e.target.value })
                  }
                  className="w-full px-3 py-2 border border-[#DADCE0] rounded focus:border-[#D93025] focus:ring-1 focus:ring-[#D93025]/30 outline-none text-sm resize-none"
                />
                <p className="text-[10px] text-slate-400 mt-1.5 italic">
                  Alasan ini akan dilampirkan secara otomatis ke dalam Email
                  pemberitahuan pendaftar.
                </p>
              </div>
              <div className="flex gap-3 justify-end border-t border-[#DADCE0] pt-4">
                <button
                  type="button"
                  onClick={() =>
                    setRejectModal({ isOpen: false, user: null, reason: "" })
                  }
                  disabled={isProcessing}
                  className="px-4 py-2 rounded text-sm font-medium text-slate-600 hover:bg-slate-100 transition-colors"
                >
                  Batal
                </button>
                <button
                  type="submit"
                  disabled={isProcessing || !rejectModal.reason.trim()}
                  className="px-5 py-2 rounded text-sm font-medium text-white bg-[#D93025] hover:bg-[#b52a1f] transition-colors shadow-sm disabled:opacity-50 flex items-center gap-2"
                >
                  {isProcessing ? "Memproses..." : "Tolak Pendaftar"}
                </button>
              </div>
            </form>
          </div>
        </div>
      )}

      {/* 4. MODAL KONFIRMASI HAPUS (Single/Bulk) */}
      {deleteModal.isOpen && (
        <div className="fixed inset-0 z-[60] flex items-center justify-center p-4 bg-slate-900/50 backdrop-blur-sm animate-in fade-in duration-200">
          <div className="bg-white rounded-xl shadow-2xl p-6 max-w-sm w-full text-center border border-[#DADCE0]">
            <div className="w-14 h-14 bg-[#FCE8E6] text-[#D93025] rounded-full flex items-center justify-center mx-auto mb-4">
              <svg
                className="w-7 h-7"
                fill="none"
                viewBox="0 0 24 24"
                stroke="currentColor"
              >
                <path
                  strokeLinecap="round"
                  strokeLinejoin="round"
                  strokeWidth={2}
                  d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16"
                />
              </svg>
            </div>
            <h3 className="text-lg font-medium text-slate-800 mb-2">
              Hapus Permanen?
            </h3>
            <p className="text-sm text-slate-500 mb-6">
              Yakin ingin menghapus <strong>{deleteModal.title}</strong>? Data
              yang dihapus tidak dapat dikembalikan.
            </p>
            <div className="flex gap-3 justify-center border-t border-[#DADCE0] pt-5 mt-2">
              <button
                onClick={() =>
                  setDeleteModal({
                    isOpen: false,
                    type: "single",
                    id: "",
                    title: "",
                  })
                }
                disabled={isProcessing}
                className="px-4 py-2 rounded text-sm font-medium text-slate-600 hover:bg-slate-100 transition-colors w-full"
              >
                Batal
              </button>
              <button
                onClick={executeDelete}
                disabled={isProcessing}
                className="px-4 py-2 rounded text-sm font-medium text-white bg-[#D93025] hover:bg-[#b52a1f] transition-colors w-full shadow-sm"
              >
                {isProcessing ? "Proses..." : "Ya, Hapus"}
              </button>
            </div>
          </div>
        </div>
      )}

      {/* Global Style */}
      <style
        dangerouslySetInnerHTML={{
          __html: `
        .perspective-1000 { perspective: 1000px; }
        .transform-style-3d { transform-style: preserve-3d; }
        .backface-hidden { backface-visibility: hidden; }
        @keyframes shimmer { 0% { transform: translateX(-100%); } 100% { transform: translateX(100%); } }
      `,
        }}
      />
    </div>
  );
}

"use client";

import { useEffect, useState, useRef } from "react";
import { toast } from "@/lib/toast";
import { db } from "@/lib/firebase";
import {
  doc,
  getDoc,
  collection,
  addDoc,
  query,
  where,
  getDocs,
} from "firebase/firestore";
import FooterPublic from "@/components/layout/FooterPublic";
import { sendEmailAction } from "@/app/actions/email";

export default function DetailAgendaPage({ id }: { id: string }) {

  const [agenda, setAgenda] = useState<any>(null);
  const [isLoading, setIsLoading] = useState(true);

  // State Form Registrasi
  const [formData, setFormData] = useState({
    nama: "",
    email: "",
    whatsapp: "",
    fakultas: "",
    angkatan: "",
    instansi: "",
    tipeDaftar: "Individu",
    jumlahTiket: 1,
    namaAnggota: "",
  });

  const [isSubmitting, setIsSubmitting] = useState(false);
  const [isSuccess, setIsSuccess] = useState(false);
  const [registeredId, setRegisteredId] = useState("");

  const [duplicateInfo, setDuplicateInfo] = useState<{
    type: string;
    id: string;
  } | null>(null);

  // ==========================================
  // STATE & LOGIKA TWIBBON (DINAMIS 9:16 & 4:5) + ZOOM & DRAG
  // ==========================================
  const [isTwibbonModalOpen, setIsTwibbonModalOpen] = useState(false);
  const [twibbonName, setTwibbonName] = useState("");
  const [userPhoto, setUserPhoto] = useState<string | null>(null);
  const [imageObj, setImageObj] = useState<HTMLImageElement | null>(null);

  const [twibbonSuccess, setTwibbonSuccess] = useState(false);

  const [frameType, setFrameType] = useState<"story" | "post">("story");
  const frameConfig = {
    story: { width: 1080, height: 1920, aspectClass: "aspect-[9/16]" },
    post: { width: 1080, height: 1350, aspectClass: "aspect-[4/5]" },
  };
  const currentFrame = frameConfig[frameType];

  const [scale, setScale] = useState(1);
  const [position, setPosition] = useState({ x: 0, y: 0 });
  const [isDragging, setIsDragging] = useState(false);
  const [dragStart, setDragStart] = useState({ x: 0, y: 0 });

  const canvasRef = useRef<HTMLCanvasElement>(null);

  const resetTwibbonState = () => {
    setIsTwibbonModalOpen(false);
    setUserPhoto(null);
    setImageObj(null);
    setTwibbonName("");
    setScale(1);
    setPosition({ x: 0, y: 0 });
    setFrameType("story");
    setTwibbonSuccess(false);
  };

  const handlePhotoUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onload = (event) => {
        const result = event.target?.result as string;
        setUserPhoto(result);

        const img = new Image();
        img.onload = () => {
          setImageObj(img);
          setScale(1);
          setPosition({ x: 0, y: 0 });
        };
        img.src = result;
      };
      reader.readAsDataURL(file);
    }
  };

  const handlePointerDown = (e: React.MouseEvent | React.TouchEvent) => {
    if (!userPhoto) return;
    setIsDragging(true);
    // @ts-ignore
    const clientX = e.touches ? e.touches[0].clientX : e.clientX;
    // @ts-ignore
    const clientY = e.touches ? e.touches[0].clientY : e.clientY;
    setDragStart({ x: clientX, y: clientY });
  };

  const handlePointerMove = (e: React.MouseEvent | React.TouchEvent) => {
    if (!isDragging || !canvasRef.current) return;
    e.preventDefault();

    // @ts-ignore
    const clientX = e.touches ? e.touches[0].clientX : e.clientX;
    // @ts-ignore
    const clientY = e.touches ? e.touches[0].clientY : e.clientY;

    const rect = canvasRef.current.getBoundingClientRect();
    const scaleX = currentFrame.width / rect.width;
    const scaleY = currentFrame.height / rect.height;

    const dx = (clientX - dragStart.x) * scaleX;
    const dy = (clientY - dragStart.y) * scaleY;

    setPosition((prev) => ({ x: prev.x + dx, y: prev.y + dy }));
    setDragStart({ x: clientX, y: clientY });
  };

  const handlePointerUp = () => {
    setIsDragging(false);
  };

  useEffect(() => {
    if (imageObj && agenda?.twibbonUrl && canvasRef.current) {
      const canvas = canvasRef.current;
      const ctx = canvas.getContext("2d");
      if (!ctx) return;

      canvas.width = currentFrame.width;
      canvas.height = currentFrame.height;
      ctx.clearRect(0, 0, canvas.width, canvas.height);

      const baseScale = Math.max(
        currentFrame.width / imageObj.width,
        currentFrame.height / imageObj.height,
      );
      const finalScale = baseScale * scale;

      const drawWidth = imageObj.width * finalScale;
      const drawHeight = imageObj.height * finalScale;

      const defaultX = (currentFrame.width - drawWidth) / 2;
      const defaultY = (currentFrame.height - drawHeight) / 2;

      ctx.drawImage(
        imageObj,
        defaultX + position.x,
        defaultY + position.y,
        drawWidth,
        drawHeight,
      );

      const imgTemplate = new Image();
      imgTemplate.crossOrigin = "anonymous";
      imgTemplate.onload = () => {
        ctx.drawImage(
          imgTemplate,
          0,
          0,
          currentFrame.width,
          currentFrame.height,
        );
      };

      imgTemplate.src =
        frameType === "post" && agenda.twibbonUrlSquare
          ? agenda.twibbonUrlSquare
          : agenda.twibbonUrl;
    }
  }, [
    imageObj,
    agenda?.twibbonUrl,
    agenda?.twibbonUrlSquare,
    scale,
    position,
    frameType,
    currentFrame.width,
    currentFrame.height,
  ]);

  const handleDownloadTwibbon = async () => {
    if (!twibbonName) { toast.warning("Silakan isi nama Anda terlebih dahulu!"); return; }
    if (!userPhoto) { toast.warning("Silakan pilih foto Anda terlebih dahulu!"); return; }
    if (!canvasRef.current) return;

    canvasRef.current.toBlob(
      async (blob) => {
        if (!blob) {
          toast.error("Terjadi kesalahan saat merender gambar.");
          return;
        }

        const url = window.URL.createObjectURL(blob);
        const link = document.createElement("a");
        link.style.display = "none";
        link.href = url;
        link.download = `Twibbon-${frameType}-${twibbonName.replace(/\s+/g, "-")}.png`;

        document.body.appendChild(link);
        link.click();

        setTimeout(() => {
          document.body.removeChild(link);
          window.URL.revokeObjectURL(url);
        }, 100);

        try {
          await addDoc(collection(db, "twibbon_logs"), {
            nama: twibbonName,
            agendaId: agenda?.id || "unknown",
            tipe: frameType,
            downloadedAt: new Date().toISOString(),
          });
        } catch (error) {
          console.error("Gagal menyimpan riwayat twibbon:", error);
        }

        setTimeout(() => {
          setTwibbonSuccess(true);
        }, 500);
      },
      "image/png",
      1.0,
    );
  };

  // ==========================================
  // STATE & LOGIKA DONASI
  // ==========================================
  const [isDonasiModalOpen, setIsDonasiModalOpen] = useState(false);
  const [donasiStep, setDonasiStep] = useState(1);
  const [isSubmittingDonasi, setIsSubmittingDonasi] = useState(false);
  const [donasiData, setDonasiData] = useState({
    nama: "",
    isAnonim: false,
    jenis: "Uang",
    nominal: "",
    deskripsiBarang: "",
  });

  const [totalDanaTerkumpul, setTotalDanaTerkumpul] = useState(0);
  const [listDonatur, setListDonatur] = useState<any[]>([]);

  useEffect(() => {
    if (!agenda) return;
    const fetchDonasi = async () => {
      try {
        const q = query(
          collection(db, "agenda_donasi"),
          where("agendaId", "==", agenda.id),
          where("status", "==", "Terverifikasi"),
        );
        const snapshot = await getDocs(q);
        let total = 0;
        const riwayat: any[] = [];

        snapshot.forEach((doc) => {
          const data = doc.data();
          if (data.jenis === "Uang") total += Number(data.nominal || 0);
          riwayat.push({ id: doc.id, ...data });
        });

        riwayat.sort(
          (a, b) => new Date(b.waktu).getTime() - new Date(a.waktu).getTime(),
        );
        setTotalDanaTerkumpul(total);
        setListDonatur(riwayat);
      } catch (error) {
        console.error("Gagal mengambil data donasi:", error);
      }
    };
    fetchDonasi();
  }, [agenda]);

  const handleDonasiSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setIsSubmittingDonasi(true);
    try {
      await addDoc(collection(db, "agenda_donasi"), {
        agendaId: agenda.id,
        agendaJudul: agenda.judul,
        nama: donasiData.isAnonim ? "Hamba Allah" : donasiData.nama,
        jenis: donasiData.jenis,
        nominal: donasiData.jenis === "Uang" ? Number(donasiData.nominal) : 0,
        deskripsiBarang:
          donasiData.jenis === "Barang" ? donasiData.deskripsiBarang : "",
        status: "Menunggu Verifikasi",
        waktu: new Date().toISOString(),
      });
      setDonasiStep(2);
    } catch (error) {
      toast.error("Terjadi kesalahan, silakan coba lagi.");
    } finally {
      setIsSubmittingDonasi(false);
    }
  };

  const closeDonasiModal = () => {
    setIsDonasiModalOpen(false);
    setTimeout(() => {
      setDonasiStep(1);
      setDonasiData({
        nama: "",
        isAnonim: false,
        jenis: "Uang",
        nominal: "",
        deskripsiBarang: "",
      });
    }, 300);
  };

  // ==========================================
  // FETCH DETAIL AGENDA
  // ==========================================
  useEffect(() => {
    const fetchAgendaDetail = async () => {
      try {
        const safeId = decodeURIComponent(id || "");

        let docRef = doc(db, "agenda", safeId);
        let docSnap = await getDoc(docRef);

        if (!docSnap.exists() && safeId.includes("-")) {
          const firestoreId = safeId.split("-").pop() || "";
          docRef = doc(db, "agenda", firestoreId);
          docSnap = await getDoc(docRef);
        }

        if (docSnap.exists()) {
          setAgenda({ id: docSnap.id, ...docSnap.data() });
        } else {
          console.log("Agenda tidak ditemukan di database!");
        }
      } catch (error) {
        console.error("Gagal mengambil detail agenda:", error);
      } finally {
        setIsLoading(false);
      }
    };
    fetchAgendaDetail();
  }, [id]);

  const handleChange = (e: any) =>
    setFormData({ ...formData, [e.target.name]: e.target.value });

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setIsSubmitting(true);
    try {
      const qEmail = query(
        collection(db, "agenda_peserta"),
        where("agendaId", "==", agenda.id),
        where("email", "==", formData.email),
      );
      const snapEmail = await getDocs(qEmail);
      if (!snapEmail.empty) {
        setDuplicateInfo({ type: "Alamat Email", id: snapEmail.docs[0].id });
        return setIsSubmitting(false);
      }

      const qWA = query(
        collection(db, "agenda_peserta"),
        where("agendaId", "==", agenda.id),
        where("whatsapp", "==", formData.whatsapp),
      );
      const snapWA = await getDocs(qWA);
      if (!snapWA.empty) {
        setDuplicateInfo({ type: "No. WhatsApp", id: snapWA.docs[0].id });
        return setIsSubmitting(false);
      }

      const docRef = await addDoc(collection(db, "agenda_peserta"), {
        agendaId: agenda.id,
        agendaJudul: agenda.judul,
        ...formData,
        statusCheckIn: false,
        waktuDaftar: new Date().toISOString(),
      });

      setRegisteredId(docRef.id);
      setIsSuccess(true);
      window.scrollTo({ top: 0, behavior: "smooth" });

      // 📧 Kirim email konfirmasi pendaftaran agenda secara background menggunakan Server Action
      sendEmailAction({
        type: "agenda_registration",
        email: formData.email,
        nama: formData.nama,
        detail: {
          judulAgenda: agenda.judul,
          tanggal: agenda.tanggal,
          waktu: agenda.waktu,
          format: agenda.format,
          tipeDaftar: formData.tipeDaftar,
          registeredId: docRef.id,
        },
      }).catch((err) => console.warn("Email notifikasi gagal:", err));

    } catch (error) {
      toast.error("Terjadi kesalahan sistem. Silakan coba lagi.");
    } finally {
      setIsSubmitting(false);
    }
  };

  if (isLoading) {
    return (
      <div className="min-h-screen flex items-center justify-center bg-slate-50">
        <div className="w-12 h-12 border-4 border-slate-200 border-t-yellow-500 rounded-full animate-spin"></div>
      </div>
    );
  }

  if (!agenda) {
    return (
      <div className="min-h-screen flex items-center justify-center bg-slate-50 flex-col gap-4">
        <h2 className="text-2xl font-black text-blue-950">
          Agenda Tidak Ditemukan
        </h2>
        <a href="/#agenda" className="text-blue-600 font-bold hover:underline">
          &larr; Kembali ke Beranda
        </a>
      </div>
    );
  }

  let isPastEvent = false;
  if (agenda.tanggal && !agenda.isComingSoon) {
    const eventDateTimeString = `${agenda.tanggal}T${agenda.waktu || "23:59"}:00`;
    if (new Date() > new Date(eventDateTimeString)) isPastEvent = true;
  }

  return (
    <div className="min-h-screen bg-slate-50 flex flex-col font-sans relative">
      {/* ========================================== */}
      {/* MODAL TWIBBON (TERMASUK STATE SUKSES)      */}
      {/* ========================================== */}
      {isTwibbonModalOpen && (
        <div className="fixed inset-0 bg-blue-950/90 backdrop-blur-sm z-[100] flex items-center justify-center p-4 sm:p-6 overflow-y-auto">
          <div
            className={`bg-white rounded-[2rem] p-6 md:p-8 w-full shadow-2xl relative transition-all duration-300 animate-in zoom-in-95 ${twibbonSuccess ? "max-w-md" : "max-w-4xl flex flex-col md:flex-row gap-8"}`}
          >
            <button
              onClick={resetTwibbonState}
              className="absolute top-4 right-4 p-2 bg-slate-100 rounded-full text-slate-500 hover:bg-red-100 hover:text-red-500 transition-colors z-10"
            >
              ✕
            </button>

            {twibbonSuccess ? (
              <div className="flex flex-col items-center justify-center text-center py-8 animate-in fade-in duration-500">
                <div className="w-20 h-20 bg-green-500 text-white rounded-full flex items-center justify-center text-4xl mb-6 shadow-lg shadow-green-200">
                  ✓
                </div>
                <h3 className="text-2xl font-black text-blue-950 mb-3">
                  Yeay, Berhasil! 🎉
                </h3>
                <p className="text-sm text-slate-600 mb-8 leading-relaxed px-4">
                  Foto Twibbon kamu sudah tersimpan ke galeri/perangkat. Terima
                  kasih <b>{twibbonName}</b> sudah berpartisipasi meramaikan
                  acara ini. Jangan lupa <i>share</i> ke media sosial kamu, ya!
                </p>
                <button
                  onClick={resetTwibbonState}
                  className="w-full bg-slate-100 hover:bg-slate-200 text-slate-700 font-bold py-3.5 rounded-xl transition-all"
                >
                  Tutup & Kembali
                </button>
              </div>
            ) : (
              <>
                {/* Kolom Kiri: Input */}
                <div className="flex-1 space-y-5">
                  <div>
                    <h3 className="text-3xl font-black text-blue-950 mb-2">
                      Pasang Twibbon
                    </h3>
                    <p className="text-sm text-slate-600">
                      Pilih foto terbaikmu, atur posisi dan ukurannya, lalu
                      bagikan di Story/Reels!
                    </p>
                  </div>

                  <div>
                    <label className="block text-xs font-bold text-slate-700 uppercase tracking-wider mb-1.5">
                      Nama Anda (Untuk Riwayat)
                    </label>
                    <input
                      type="text"
                      value={twibbonName}
                      onChange={(e) => setTwibbonName(e.target.value)}
                      placeholder="Contoh: Budi Santoso"
                      className="w-full px-4 py-3 bg-slate-50 border border-slate-200 rounded-xl focus:ring-2 focus:ring-blue-900 outline-none transition-all"
                    />
                  </div>

                  <div>
                    <label className="block text-xs font-bold text-slate-700 uppercase tracking-wider mb-1.5">
                      Pilih Format Bingkai
                    </label>
                    <div className="flex bg-slate-100 p-1.5 rounded-xl gap-1">
                      <button
                        onClick={() => setFrameType("story")}
                        className={`flex-1 py-2.5 rounded-lg text-sm font-bold transition-all ${
                          frameType === "story"
                            ? "bg-white text-blue-700 shadow-sm"
                            : "text-slate-500 hover:text-slate-700"
                        }`}
                      >
                        IG Story (9:16)
                      </button>
                      <button
                        onClick={() => setFrameType("post")}
                        className={`flex-1 py-2.5 rounded-lg text-sm font-bold transition-all ${
                          frameType === "post"
                            ? "bg-white text-blue-700 shadow-sm"
                            : "text-slate-500 hover:text-slate-700"
                        }`}
                      >
                        IG Post (4:5)
                      </button>
                    </div>
                  </div>

                  <div>
                    <label className="block text-xs font-bold text-slate-700 uppercase tracking-wider mb-1.5">
                      Pilih Foto Anda
                    </label>
                    <div className="border-2 border-dashed border-slate-300 rounded-xl p-4 bg-slate-50 hover:bg-blue-50 transition-colors">
                      <input
                        type="file"
                        accept="image/*"
                        onChange={handlePhotoUpload}
                        className="w-full text-sm text-slate-600 file:mr-4 file:py-2.5 file:px-4 file:rounded-xl file:border-0 file:text-sm file:font-bold file:bg-blue-950 file:text-white hover:file:bg-blue-800 file:cursor-pointer cursor-pointer"
                      />
                    </div>
                  </div>

                  {/* Slider Zoom */}
                  {userPhoto && (
                    <div className="bg-slate-50 p-4 rounded-xl border border-slate-200">
                      <label className="block text-xs font-bold text-slate-700 uppercase tracking-wider mb-2">
                        🔍 Perbesar / Perkecil Foto
                      </label>
                      <input
                        type="range"
                        min="0.5"
                        max="3"
                        step="0.05"
                        value={scale}
                        onChange={(e) => setScale(parseFloat(e.target.value))}
                        className="w-full accent-blue-900"
                      />
                      <p className="text-[10px] text-slate-500 mt-2 text-center">
                        Tahan dan geser gambar pada kotak preview untuk
                        memindahkan posisi.
                      </p>
                    </div>
                  )}

                  <button
                    onClick={handleDownloadTwibbon}
                    className="w-full bg-yellow-500 hover:bg-yellow-400 text-blue-950 font-black py-4 rounded-xl transition-all shadow-md mt-4 flex items-center justify-center gap-2"
                  >
                    <svg
                      className="w-5 h-5"
                      fill="none"
                      viewBox="0 0 24 24"
                      stroke="currentColor"
                    >
                      <path
                        strokeLinecap="round"
                        strokeLinejoin="round"
                        strokeWidth={2}
                        d="M4 16v1a3 3 0 003 3h10a3 3 0 003-3v-1m-4-4l-4 4m0 0l-4-4m4 4V4"
                      />
                    </svg>
                    Download Twibbon
                  </button>
                </div>

                {/* Kolom Kanan: Preview Canvas */}
                <div className="flex-1 flex flex-col items-center justify-center bg-slate-100 rounded-2xl p-4 border border-slate-200 relative min-h-[300px] transition-all">
                  {!userPhoto ? (
                    <div className="text-center opacity-40">
                      <span className="text-6xl block mb-4">🖼️</span>
                      <p className="text-lg font-black text-slate-700">
                        Preview Area ({frameType === "story" ? "9:16" : "4:5"})
                      </p>
                      <p className="text-sm">
                        Pilih foto dari perangkatmu <br />
                        untuk melihat hasil.
                      </p>
                    </div>
                  ) : (
                    <div
                      className={`w-full max-w-[280px] ${currentFrame.aspectClass} bg-white rounded-xl shadow-lg border border-slate-200 overflow-hidden relative cursor-move touch-none transition-all duration-300 mx-auto`}
                      onMouseDown={handlePointerDown}
                      onMouseMove={handlePointerMove}
                      onMouseUp={handlePointerUp}
                      onMouseLeave={handlePointerUp}
                      onTouchStart={handlePointerDown}
                      onTouchMove={handlePointerMove}
                      onTouchEnd={handlePointerUp}
                    >
                      <canvas
                        ref={canvasRef}
                        className="w-full h-full object-cover pointer-events-none"
                      ></canvas>
                    </div>
                  )}
                </div>
              </>
            )}
          </div>
        </div>
      )}

      {/* ========================================== */}
      {/* MODAL DONASI */}
      {/* ========================================== */}
      {isDonasiModalOpen && (
        <div className="fixed inset-0 bg-blue-950/90 backdrop-blur-sm z-[100] flex items-center justify-center p-4 sm:p-6 overflow-y-auto">
          <div className="bg-white rounded-[2rem] p-6 md:p-8 max-w-lg w-full shadow-2xl relative animate-in zoom-in-95">
            <button
              onClick={closeDonasiModal}
              className="absolute top-4 right-4 p-2 bg-slate-100 rounded-full text-slate-500 hover:bg-red-100 hover:text-red-500 transition-colors z-10"
            >
              ✕
            </button>

            {donasiStep === 1 ? (
              <>
                <h3 className="text-2xl font-black text-blue-950 mb-2">
                  Formulir Donasi
                </h3>
                <p className="text-sm text-slate-600 mb-6 whitespace-pre-wrap">
                  {agenda.deskripsiDonasi ||
                    "Dukungan Anda sangat berarti untuk kesuksesan acara kita bersama."}
                </p>

                <form onSubmit={handleDonasiSubmit} className="space-y-4">
                  <div>
                    <label className="block text-xs font-bold text-slate-700 uppercase tracking-wider mb-1.5">
                      Nama Donatur
                    </label>
                    <input
                      type="text"
                      required={!donasiData.isAnonim}
                      disabled={donasiData.isAnonim}
                      value={
                        donasiData.isAnonim ? "Hamba Allah" : donasiData.nama
                      }
                      onChange={(e) =>
                        setDonasiData({ ...donasiData, nama: e.target.value })
                      }
                      placeholder="Masukkan nama Anda"
                      className="w-full px-4 py-3 bg-slate-50 border border-slate-200 rounded-xl focus:ring-2 focus:ring-blue-900 outline-none transition-all disabled:opacity-50"
                    />
                    <label className="flex items-center gap-2 mt-2 cursor-pointer">
                      <input
                        type="checkbox"
                        checked={donasiData.isAnonim}
                        onChange={(e) =>
                          setDonasiData({
                            ...donasiData,
                            isAnonim: e.target.checked,
                          })
                        }
                        className="w-4 h-4 text-blue-600 rounded"
                      />
                      <span className="text-sm text-slate-600 font-medium">
                        Sembunyikan nama (Hamba Allah)
                      </span>
                    </label>
                  </div>

                  <div className="flex bg-slate-100 p-1.5 rounded-xl">
                    <button
                      type="button"
                      onClick={() =>
                        setDonasiData({ ...donasiData, jenis: "Uang" })
                      }
                      className={`flex-1 py-2.5 font-bold text-sm rounded-lg transition-all ${donasiData.jenis === "Uang" ? "bg-white shadow-sm text-blue-900" : "text-slate-400 hover:text-slate-600"}`}
                    >
                      Donasi Uang
                    </button>
                    <button
                      type="button"
                      onClick={() =>
                        setDonasiData({ ...donasiData, jenis: "Barang" })
                      }
                      className={`flex-1 py-2.5 font-bold text-sm rounded-lg transition-all ${donasiData.jenis === "Barang" ? "bg-white shadow-sm text-blue-900" : "text-slate-400 hover:text-slate-600"}`}
                    >
                      Doorprice / Barang
                    </button>
                  </div>

                  {donasiData.jenis === "Uang" ? (
                    <div>
                      <label className="block text-xs font-bold text-slate-700 uppercase tracking-wider mb-1.5">
                        Nominal (Rp)
                      </label>
                      <input
                        type="number"
                        min="10000"
                        required
                        value={donasiData.nominal}
                        onChange={(e) =>
                          setDonasiData({
                            ...donasiData,
                            nominal: e.target.value,
                          })
                        }
                        placeholder="Contoh: 100000"
                        className="w-full px-4 py-3 bg-slate-50 border border-slate-200 rounded-xl focus:ring-2 focus:ring-blue-900 outline-none transition-all font-bold text-blue-900"
                      />
                    </div>
                  ) : (
                    <div>
                      <label className="block text-xs font-bold text-slate-700 uppercase tracking-wider mb-1.5">
                        Detail Barang / Doorprice
                      </label>
                      <textarea
                        required
                        rows={3}
                        value={donasiData.deskripsiBarang}
                        onChange={(e) =>
                          setDonasiData({
                            ...donasiData,
                            deskripsiBarang: e.target.value,
                          })
                        }
                        placeholder="Contoh: 2 Buah Sepeda Lipat, Voucher Belanja 500rb..."
                        className="w-full px-4 py-3 bg-slate-50 border border-slate-200 rounded-xl focus:ring-2 focus:ring-blue-900 outline-none transition-all text-sm"
                      ></textarea>
                    </div>
                  )}

                  <button
                    type="submit"
                    disabled={isSubmittingDonasi}
                    className="w-full bg-blue-950 hover:bg-blue-900 text-white font-bold py-4 rounded-xl shadow-lg transition-all flex items-center justify-center gap-2 mt-4"
                  >
                    {isSubmittingDonasi ? "Memproses..." : "Lanjut Konfirmasi"}
                  </button>
                </form>
              </>
            ) : (
              <div className="text-center">
                <div className="w-16 h-16 bg-yellow-100 text-yellow-600 rounded-full flex items-center justify-center text-3xl mx-auto mb-4">
                  🙏
                </div>
                <h3 className="text-2xl font-black text-blue-950 mb-2">
                  Terima Kasih!
                </h3>
                <p className="text-sm text-slate-600 mb-6">
                  Niat baik Anda telah kami catat. Silakan lanjutkan proses
                  donasi sesuai petunjuk di bawah.
                </p>

                <div className="bg-slate-50 border border-slate-200 rounded-2xl p-4 mb-6 text-left">
                  {donasiData.jenis === "Uang" ? (
                    <>
                      <p className="text-xs font-bold text-slate-500 uppercase tracking-wider mb-2">
                        Transfer Ke Rekening:
                      </p>
                      <p className="font-black text-blue-950 text-xl">
                        {agenda.bankDonasi || "Bank"}{" "}
                        {agenda.rekeningDonasi || "-"}
                      </p>
                      <p className="text-sm text-slate-700 mb-4">
                        a.n. {agenda.atasNamaDonasi || "-"}
                      </p>
                      <p className="text-xs font-bold text-slate-500 uppercase tracking-wider mb-1">
                        Nominal:
                      </p>
                      <p className="font-bold text-yellow-600">
                        {new Intl.NumberFormat("id-ID", {
                          style: "currency",
                          currency: "IDR",
                        }).format(Number(donasiData.nominal))}
                      </p>
                    </>
                  ) : (
                    <>
                      <p className="text-xs font-bold text-slate-500 uppercase tracking-wider mb-2">
                        Kirim Barang Ke Alamat:
                      </p>
                      <p className="font-bold text-blue-950 text-sm whitespace-pre-wrap mb-4">
                        {agenda.alamatDonasi ||
                          "Sekretariat DPW IKA UII\n(Silakan hubungi admin via WhatsApp untuk alamat lengkap pengiriman)"}
                      </p>
                      <p className="text-xs font-bold text-slate-500 uppercase tracking-wider mb-1">
                        Barang Donasi:
                      </p>
                      <p className="font-bold text-blue-900">
                        {donasiData.deskripsiBarang}
                      </p>
                    </>
                  )}
                </div>

                <a
                  href={`https://wa.me/${agenda.waDonasi || "6281234567890"}?text=Halo Admin, saya ${donasiData.isAnonim ? "Hamba Allah" : donasiData.nama} ingin konfirmasi donasi ${donasiData.jenis} untuk acara ${agenda.judul}.`}
                  target="_blank"
                  rel="noopener noreferrer"
                  className="w-full bg-green-500 hover:bg-green-600 text-white font-bold py-4 rounded-xl shadow-lg transition-all flex items-center justify-center gap-2 mb-3"
                  onClick={closeDonasiModal}
                >
                  <svg
                    className="w-5 h-5"
                    fill="currentColor"
                    viewBox="0 0 24 24"
                  >
                    <path d="M17.472 14.382c-.297-.149-1.758-.867-2.03-.967-.273-.099-.471-.148-.67.15-.197.297-.767.966-.94 1.164-.173.199-.347.223-.644.075-.297-.15-1.255-.463-2.39-1.475-.883-.788-1.48-1.761-1.653-2.059-.173-.297-.018-.458.13-.606.134-.133.298-.347.446-.52.149-.174.198-.298.298-.497.099-.198.05-.371-.025-.52-.075-.149-.669-1.612-.916-2.207-.242-.579-.487-.5-.669-.51a12.8 12.8 0 00-.57-.01c-.198 0-.52.074-.792.372-.272.297-1.04 1.016-1.04 2.479 0 1.462 1.065 2.875 1.213 3.074.149.198 2.096 3.2 5.077 4.487.709.306 1.262.489 1.694.625.712.227 1.36.195 1.871.118.571-.085 1.758-.719 2.006-1.413.248-.694.248-1.289.173-1.413-.074-.124-.272-.198-.57-.347z" />
                  </svg>
                  Konfirmasi via WhatsApp
                </a>
                <p className="text-xs text-slate-400">
                  Penting: Admin akan memverifikasi dana/barang sebelum
                  memunculkannya di halaman utama.
                </p>
              </div>
            )}
          </div>
        </div>
      )}

      {/* MODAL DUPLIKAT */}
      {duplicateInfo && (
        <div className="fixed inset-0 bg-blue-950/80 backdrop-blur-sm z-[110] flex items-center justify-center p-4 animate-in fade-in">
          <div className="bg-white rounded-[2rem] p-8 max-w-sm w-full shadow-2xl relative text-center animate-in zoom-in-95">
            <button
              onClick={() => setDuplicateInfo(null)}
              className="absolute top-4 right-4 p-2 bg-slate-100 rounded-full text-slate-500 hover:bg-red-100 hover:text-red-500 transition-colors"
            >
              ✕
            </button>
            <div className="w-16 h-16 bg-yellow-100 text-yellow-600 rounded-full flex items-center justify-center text-3xl mx-auto mb-4 shadow-inner">
              ⚠️
            </div>
            <h3 className="text-2xl font-black text-blue-950 mb-2">
              Sudah Terdaftar!
            </h3>
            <p className="text-sm text-slate-600 mb-6 leading-relaxed">
              Data dengan <b>{duplicateInfo.type}</b> tersebut sudah tercatat.
              Berikut adalah QR Code tiket Anda sebelumnya:
            </p>
            <div className="bg-slate-50 border-2 border-dashed border-slate-300 rounded-2xl p-6 mx-auto inline-block w-full max-w-[200px] mb-6 shadow-sm">
              <img
                src={`https://api.qrserver.com/v1/create-qr-code/?size=200x200&data=${duplicateInfo.id}`}
                alt="QR Code Tiket"
                className="w-full aspect-square mix-blend-multiply"
              />
            </div>
            <button
              onClick={() => setDuplicateInfo(null)}
              className="w-full bg-blue-950 hover:bg-blue-900 text-white font-bold py-3.5 rounded-xl transition-all shadow-md"
            >
              Tutup & Kembali
            </button>
          </div>
        </div>
      )}

      {/* HEADER AGENDA */}
      <div className="bg-blue-950 pt-32 pb-12">
        <div className="max-w-7xl mx-auto px-6">
          <a
            href="/#agenda"
            className="text-yellow-400 text-sm font-bold flex items-center gap-2 mb-6 hover:text-yellow-300 w-fit transition-colors"
          >
            &larr; Kembali ke Daftar Agenda
          </a>
          <h1 className="text-3xl md:text-5xl font-black text-white leading-tight mb-4">
            {agenda.judul}
          </h1>
          <div className="flex flex-wrap items-center gap-4 text-sm font-medium text-blue-200">
            <span className="flex items-center gap-2 bg-blue-900 px-3 py-1 rounded-lg">
              📅{" "}
              {agenda.tanggal
                ? new Date(agenda.tanggal).toLocaleDateString("id-ID", {
                    day: "numeric",
                    month: "long",
                    year: "numeric",
                  })
                : "Segera Hadir"}
            </span>
            <span className="flex items-center gap-2 bg-blue-900 px-3 py-1 rounded-lg">
              ⏰ {agenda.waktu || "00:00"} WIB
            </span>
            <span className="flex items-center gap-2 bg-blue-900 px-3 py-1 rounded-lg">
              📍 {agenda.format}
            </span>
            {isPastEvent && (
              <span className="flex items-center gap-2 bg-red-500 text-white px-3 py-1 rounded-lg font-bold shadow-sm border border-red-400">
                🔒 Acara Telah Berlalu
              </span>
            )}
          </div>
        </div>
      </div>

      <main className="flex-grow max-w-7xl mx-auto px-6 py-12 w-full">
        <div className="flex flex-col lg:flex-row gap-10 items-start">
          {/* KOLOM KIRI: POSTER & DESKRIPSI */}
          <div className="w-full lg:w-3/5 space-y-8">
            <div className="bg-white p-4 rounded-3xl shadow-sm border border-slate-100 flex justify-center relative">
              <div className="aspect-[4/5] w-full max-w-lg rounded-2xl overflow-hidden bg-slate-50 relative border border-slate-100 shadow-inner">
                {agenda.imgUrl || agenda.posterUrl ? (
                  <img
                    src={agenda.imgUrl || agenda.posterUrl}
                    alt="Poster Agenda"
                    className={`w-full h-full object-cover transition-all ${isPastEvent ? "grayscale" : ""}`}
                  />
                ) : (
                  <div className="w-full h-full flex flex-col items-center justify-center opacity-30">
                    <img
                      src="/logo-dpp-ika.png"
                      className="w-24 md:w-32 object-contain"
                      alt="logo"
                    />
                    <p className="mt-4 font-black tracking-widest text-slate-600">
                      DPW IKA UII
                    </p>
                  </div>
                )}
                {isPastEvent && (
                  <div className="absolute inset-0 bg-black/60 flex items-center justify-center backdrop-blur-sm">
                    <div className="bg-red-600 text-white px-6 py-3 rounded-xl font-black text-xl tracking-widest uppercase transform -rotate-12 border-4 border-white shadow-2xl">
                      Telah Berakhir
                    </div>
                  </div>
                )}
              </div>
            </div>

            <div className="bg-white p-8 rounded-3xl shadow-sm border border-slate-100">
              <h3 className="text-xl font-black text-blue-950 mb-4 border-b border-slate-100 pb-4">
                Informasi Kegiatan
              </h3>
              <p className="text-slate-600 leading-relaxed whitespace-pre-wrap">
                {agenda.deskripsi}
              </p>
              <div className="mt-8 grid grid-cols-2 gap-4">
                <div className="bg-slate-50 p-4 rounded-xl border border-slate-100">
                  <p className="text-xs text-slate-500 font-bold uppercase tracking-wider mb-1">
                    Penyelenggara
                  </p>
                  <p className="font-bold text-blue-950">{agenda.bidang}</p>
                </div>
                <div className="bg-slate-50 p-4 rounded-xl border border-slate-100">
                  <p className="text-xs text-slate-500 font-bold uppercase tracking-wider mb-1">
                    Koordinator / PIC
                  </p>
                  <p className="font-bold text-blue-950">
                    {agenda.koordinator}
                  </p>
                </div>
                <div
                  className={`bg-slate-50 p-4 rounded-xl border border-slate-100 ${agenda.link ? "" : "col-span-2"}`}
                >
                  <p className="text-xs text-slate-500 font-bold uppercase tracking-wider mb-1">
                    Jenis Tiket
                  </p>
                  <p className="font-bold text-yellow-600">{agenda.tiket}</p>
                </div>
                {agenda.link && (
                  <div className="bg-slate-50 p-4 rounded-xl border border-slate-100">
                    <p className="text-xs text-slate-500 font-bold uppercase tracking-wider mb-1">
                      Lokasi Acara
                    </p>
                    <a
                      href={
                        agenda.link.startsWith("http")
                          ? agenda.link
                          : `https://${agenda.link}`
                      }
                      target="_blank"
                      rel="noopener noreferrer"
                      className="font-bold text-blue-600 hover:text-blue-800 hover:underline flex items-center gap-1.5 transition-colors"
                    >
                      {agenda.format === "Online Event"
                        ? "🔗 Buka Link Zoom"
                        : "📍 Buka Google Maps"}
                    </a>
                  </div>
                )}
              </div>

              {/* CONDITIONAL RENDER: TWIBBON */}
              {agenda.isTwibbonActive && (
                <div className="mt-8 bg-gradient-to-r from-blue-900 to-blue-950 rounded-2xl p-6 flex flex-col sm:flex-row items-center justify-between gap-6 shadow-lg border border-blue-800">
                  <div className="text-left">
                    <h4 className="text-lg font-black text-white mb-1">
                      🎉 Mari Ramaikan Acara Ini!
                    </h4>
                    <p className="text-sm text-blue-200">
                      Gunakan twibbon resmi kami, pasang fotomu, dan bagikan
                      keseruannya di media sosial.
                    </p>
                  </div>
                  <button
                    onClick={() => setIsTwibbonModalOpen(true)}
                    className="shrink-0 bg-yellow-500 hover:bg-yellow-400 text-blue-950 font-black py-3 px-6 rounded-xl transition-all shadow-md flex items-center gap-2 hover:-translate-y-1"
                  >
                    Pasang Twibbon
                  </button>
                </div>
              )}

              {/* CONDITIONAL RENDER: DONASI */}
              {agenda.isDonasiActive && (
                <div className="mt-8 bg-white border border-slate-200 rounded-2xl overflow-hidden shadow-sm">
                  <div className="bg-slate-50 p-6 border-b border-slate-200 flex flex-col sm:flex-row items-center justify-between gap-4">
                    <div>
                      <h4 className="font-black text-blue-950 text-xl flex items-center gap-2">
                        🤝 Donasi & Dukungan
                      </h4>
                      <p className="text-sm text-slate-500 mt-1">
                        Bantu sukseskan acara reuni kita tercinta.
                      </p>
                    </div>
                    <button
                      onClick={() => setIsDonasiModalOpen(true)}
                      className="w-full sm:w-auto bg-blue-600 hover:bg-blue-700 text-white font-bold py-3 px-6 rounded-xl transition-colors shadow-md"
                    >
                      Mulai Donasi
                    </button>
                  </div>

                  <div className="p-6">
                    <div className="bg-green-50 rounded-xl p-4 border border-green-100 mb-6 flex flex-col items-center justify-center text-center">
                      <p className="text-xs font-bold text-green-700 uppercase tracking-widest mb-1">
                        Dana Terkumpul
                      </p>
                      <p className="text-3xl font-black text-green-600">
                        {new Intl.NumberFormat("id-ID", {
                          style: "currency",
                          currency: "IDR",
                          maximumFractionDigits: 0,
                        }).format(totalDanaTerkumpul)}
                      </p>
                    </div>

                    <h5 className="text-sm font-bold text-slate-700 mb-4 flex items-center gap-2">
                      <svg
                        className="w-4 h-4 text-slate-400"
                        fill="none"
                        viewBox="0 0 24 24"
                        stroke="currentColor"
                      >
                        <path
                          strokeLinecap="round"
                          strokeLinejoin="round"
                          strokeWidth={2}
                          d="M12 8v4l3 3m6-3a9 9 0 11-18 0 9 9 0 0118 0z"
                        />
                      </svg>
                      Riwayat Donatur ({listDonatur.length})
                    </h5>

                    <div className="space-y-3 max-h-[300px] overflow-y-auto pr-2 custom-scrollbar">
                      {listDonatur.length === 0 ? (
                        <p className="text-sm text-slate-400 italic text-center py-4">
                          Belum ada donasi terverifikasi. Jadilah yang pertama!
                        </p>
                      ) : (
                        listDonatur.map((donatur) => (
                          <div
                            key={donatur.id}
                            className="flex items-center gap-4 p-3 bg-slate-50 rounded-xl border border-slate-100"
                          >
                            <div className="w-10 h-10 bg-blue-100 text-blue-600 rounded-full flex items-center justify-center font-bold text-lg shrink-0">
                              {donatur.nama.charAt(0).toUpperCase()}
                            </div>
                            <div className="flex-1 min-w-0">
                              <p className="font-bold text-blue-950 truncate">
                                {donatur.nama}
                              </p>
                              <p className="text-xs text-slate-500">
                                {new Date(donatur.waktu).toLocaleDateString(
                                  "id-ID",
                                  { day: "numeric", month: "short" },
                                )}{" "}
                                • {donatur.jenis}
                              </p>
                            </div>
                            <div className="text-right shrink-0">
                              <p className="font-black text-slate-700">
                                {donatur.jenis === "Uang"
                                  ? new Intl.NumberFormat("id-ID", {
                                      style: "currency",
                                      currency: "IDR",
                                      maximumFractionDigits: 0,
                                    }).format(donatur.nominal)
                                  : "🎁 Barang"}
                              </p>
                            </div>
                          </div>
                        ))
                      )}
                    </div>
                  </div>
                </div>
              )}
            </div>
          </div>

          {/* KOLOM KANAN: FORM REGISTRASI / STATUS */}
          <div className="w-full lg:w-2/5 lg:sticky lg:top-28">
            <div className="bg-white rounded-3xl p-8 shadow-xl border border-slate-100 relative overflow-hidden">
              <div className="absolute top-0 right-0 w-32 h-32 bg-yellow-400/10 rounded-bl-full -z-0 pointer-events-none"></div>

              {/* 🌟 LOGIKA BARU: CEK LINK EKSTERNAL / VIRTUAL RUN 🌟 */}
              {agenda.linkEksternal ? (
                <>
                  <h3 className="text-2xl font-black text-blue-950 mb-4 relative z-10">
                    Pendaftaran Khusus
                  </h3>
                  <div className="bg-blue-50 border border-blue-200 rounded-2xl p-8 text-center relative z-10 flex flex-col items-center justify-center gap-5 shadow-sm">
                    <div className="w-20 h-20 bg-white rounded-full flex items-center justify-center shadow-md">
                      <span className="text-4xl">🏃‍♂️</span>
                    </div>
                    <div>
                      <h4 className="font-black text-blue-900 text-lg mb-2">
                        Pendaftaran via Portal Khusus
                      </h4>
                      <p className="text-sm text-slate-600 leading-relaxed">
                        Registrasi dan pengelolaan aktivitas untuk kegiatan ini
                        dilakukan melalui website / portal khusus yang telah
                        kami sediakan.
                      </p>
                    </div>
                    <a
                      href={
                        agenda.linkEksternal.startsWith("http")
                          ? agenda.linkEksternal
                          : `https://${agenda.linkEksternal}`
                      }
                      target="_blank"
                      rel="noopener noreferrer"
                      className="w-full bg-blue-600 hover:bg-blue-700 text-white font-black py-4 rounded-xl shadow-lg hover:shadow-xl transition-all hover:-translate-y-1 flex items-center justify-center gap-2"
                    >
                      Kunjungi Website Pendaftaran &rarr;
                    </a>
                  </div>
                </>
              ) : agenda.isComingSoon ? (
                <>
                  <h3 className="text-2xl font-black text-blue-950 mb-6 relative z-10">
                    Form Registrasi
                  </h3>
                  <div className="bg-yellow-50 border border-yellow-200 rounded-2xl p-6 text-center relative z-10">
                    <span className="text-4xl block mb-3">⏳</span>
                    <h4 className="font-black text-yellow-800 text-lg mb-1">
                      Pendaftaran Belum Dibuka
                    </h4>
                  </div>
                </>
              ) : isPastEvent ? (
                // TAMPILAN JIKA ACARA SUDAH LEWAT
                <>
                  <h3 className="text-2xl font-black text-blue-950 mb-6 relative z-10">
                    Status Pendaftaran
                  </h3>
                  <div className="bg-red-50 border border-red-200 rounded-2xl p-8 text-center relative z-10 shadow-sm">
                    <span className="text-5xl block mb-4">🔒</span>
                    <h4 className="font-black text-red-800 text-xl mb-2">
                      Pendaftaran Ditutup
                    </h4>
                    <p className="text-red-600 font-medium text-sm px-4">
                      Terima kasih atas antusiasme Anda. Registrasi telah
                      ditutup karena waktu acara telah berlalu.
                    </p>
                  </div>
                </>
              ) : isSuccess ? (
                <div className="text-center animate-in zoom-in duration-300 relative z-10">
                  <div className="w-12 h-12 bg-green-500 text-white rounded-full flex items-center justify-center text-2xl mx-auto mb-3 shadow-lg shadow-green-200">
                    ✓
                  </div>
                  <h4 className="font-black text-blue-950 text-2xl mb-2">
                    Pendaftaran Berhasil!
                  </h4>
                  <div className="bg-slate-50 border-2 border-dashed border-slate-300 rounded-2xl p-6 mb-6 inline-block w-full max-w-[250px] shadow-sm relative overflow-hidden">
                    <img
                      src={`https://api.qrserver.com/v1/create-qr-code/?size=200x200&data=${registeredId}`}
                      alt="QR Code"
                      className="w-full aspect-square mix-blend-multiply"
                    />
                  </div>
                  <button
                    onClick={() => {
                      setIsSuccess(false);
                      setFormData({
                        ...formData,
                        nama: "",
                        email: "",
                        whatsapp: "",
                      });
                    }}
                    className="w-full bg-slate-100 hover:bg-slate-200 font-bold py-3.5 rounded-xl transition-all"
                  >
                    Daftarkan Peserta Lain
                  </button>
                </div>
              ) : (
                <>
                  <h3 className="text-2xl font-black text-blue-950 mb-4 relative z-10">
                    Form Registrasi
                  </h3>

                  <div className="flex bg-slate-100 p-1.5 rounded-xl mb-6 relative z-10">
                    <button
                      type="button"
                      onClick={() =>
                        setFormData({
                          ...formData,
                          tipeDaftar: "Individu",
                          jumlahTiket: 1,
                          namaAnggota: "",
                        })
                      }
                      className={`flex-1 py-2.5 font-bold text-sm rounded-lg transition-all ${formData.tipeDaftar === "Individu" ? "bg-white shadow-sm text-blue-900" : "text-slate-400 hover:text-slate-600"}`}
                    >
                      👤 Individu
                    </button>
                    <button
                      type="button"
                      onClick={() =>
                        setFormData({
                          ...formData,
                          tipeDaftar: "Kelompok",
                          jumlahTiket: 2,
                        })
                      }
                      className={`flex-1 py-2.5 font-bold text-sm rounded-lg transition-all ${formData.tipeDaftar === "Kelompok" ? "bg-white shadow-sm text-blue-900" : "text-slate-400 hover:text-slate-600"}`}
                    >
                      👥 Rombongan
                    </button>
                  </div>

                  <form
                    onSubmit={handleSubmit}
                    className="space-y-4 relative z-10"
                  >
                    {formData.tipeDaftar === "Kelompok" && (
                      <div className="bg-blue-50/50 p-4 rounded-xl border border-blue-100 mb-6 space-y-4">
                        <div>
                          <label className="block text-xs font-bold text-blue-900 uppercase tracking-wider mb-1.5">
                            Jumlah Orang (Termasuk Anda)
                          </label>
                          <input
                            type="number"
                            name="jumlahTiket"
                            min="2"
                            max="50"
                            value={formData.jumlahTiket}
                            onChange={handleChange}
                            required
                            className="w-full px-4 py-3 bg-white border border-blue-200 rounded-xl focus:ring-2 focus:ring-blue-500 outline-none transition-all font-bold text-blue-900"
                            placeholder="Min. 2 Orang"
                          />
                        </div>
                        <div>
                          <label className="block text-xs font-bold text-blue-900 uppercase tracking-wider mb-1.5">
                            Nama Anggota Rombongan
                          </label>
                          <textarea
                            name="namaAnggota"
                            value={formData.namaAnggota}
                            onChange={handleChange}
                            required
                            rows={3}
                            className="w-full px-4 py-3 bg-white border border-blue-200 rounded-xl focus:ring-2 focus:ring-blue-500 outline-none transition-all text-sm"
                            placeholder="Contoh: Budi (FTI 2018), Siti (FE 2018), dst..."
                          ></textarea>
                          <p className="text-[10px] text-blue-600 mt-1 font-medium">
                            Satu QR Code akan digunakan bersama untuk seluruh
                            anggota rombongan ini.
                          </p>
                        </div>
                      </div>
                    )}

                    <div>
                      <label className="block text-xs font-bold text-slate-700 uppercase tracking-wider mb-1.5">
                        {formData.tipeDaftar === "Kelompok"
                          ? "Nama Ketua Rombongan"
                          : "Nama Lengkap & Gelar"}
                      </label>
                      <input
                        type="text"
                        name="nama"
                        value={formData.nama}
                        onChange={handleChange}
                        required
                        className="w-full px-4 py-3 bg-slate-50 border border-slate-200 rounded-xl focus:ring-2 focus:ring-blue-900 outline-none transition-all"
                        placeholder="Contoh: Fulan, S.T., M.Eng."
                      />
                    </div>

                    <div>
                      <label className="block text-xs font-bold text-slate-700 uppercase tracking-wider mb-1.5">
                        Alamat Email
                      </label>
                      <input
                        type="email"
                        name="email"
                        value={formData.email}
                        onChange={handleChange}
                        required
                        className="w-full px-4 py-3 bg-slate-50 border border-slate-200 rounded-xl focus:ring-2 focus:ring-blue-900 outline-none transition-all"
                        placeholder="Contoh: alumni@gmail.com"
                      />
                    </div>

                    <div>
                      <label className="block text-xs font-bold text-slate-700 uppercase tracking-wider mb-1.5">
                        No. WhatsApp (Aktif)
                      </label>
                      <input
                        type="tel"
                        name="whatsapp"
                        value={formData.whatsapp}
                        onChange={handleChange}
                        required
                        className="w-full px-4 py-3 bg-slate-50 border border-slate-200 rounded-xl focus:ring-2 focus:ring-blue-900 outline-none transition-all"
                        placeholder="Contoh: 08123456789"
                      />
                    </div>
                    <div className="grid grid-cols-2 gap-4">
                      <div>
                        <label className="block text-xs font-bold text-slate-700 uppercase tracking-wider mb-1.5">
                          Asal Fakultas
                        </label>
                        <input
                          type="text"
                          name="fakultas"
                          value={formData.fakultas}
                          onChange={handleChange}
                          required
                          className="w-full px-4 py-3 bg-slate-50 border border-slate-200 rounded-xl focus:ring-2 focus:ring-blue-900 outline-none transition-all"
                          placeholder="Contoh: FTI"
                        />
                      </div>
                      <div>
                        <label className="block text-xs font-bold text-slate-700 uppercase tracking-wider mb-1.5">
                          Angkatan
                        </label>
                        <input
                          type="number"
                          name="angkatan"
                          value={formData.angkatan}
                          onChange={handleChange}
                          required
                          className="w-full px-4 py-3 bg-slate-50 border border-slate-200 rounded-xl focus:ring-2 focus:ring-blue-900 outline-none transition-all"
                          placeholder="Contoh: 2018"
                        />
                      </div>
                    </div>
                    <div>
                      <label className="block text-xs font-bold text-slate-700 uppercase tracking-wider mb-1.5">
                        Instansi / Pekerjaan
                      </label>
                      <input
                        type="text"
                        name="instansi"
                        value={formData.instansi}
                        onChange={handleChange}
                        required
                        className="w-full px-4 py-3 bg-slate-50 border border-slate-200 rounded-xl focus:ring-2 focus:ring-blue-900 outline-none transition-all"
                        placeholder="Contoh: PT. Inovasi Bangsa / Dosen"
                      />
                    </div>

                    <div className="pt-4">
                      <button
                        type="submit"
                        disabled={isSubmitting}
                        className="w-full bg-yellow-500 hover:bg-yellow-400 text-blue-950 font-black py-4 rounded-xl shadow-lg hover:shadow-xl transition-all hover:-translate-y-0.5 flex items-center justify-center gap-2 disabled:opacity-70 disabled:hover:translate-y-0"
                      >
                        {isSubmitting ? (
                          "Memproses Verifikasi Data..."
                        ) : (
                          <>
                            <svg
                              className="w-5 h-5"
                              fill="none"
                              viewBox="0 0 24 24"
                              stroke="currentColor"
                            >
                              <path
                                strokeLinecap="round"
                                strokeLinejoin="round"
                                strokeWidth={2}
                                d="M9 12l2 2 4-4m6 2a9 9 0 11-18 0 9 9 0 0118 0z"
                              />
                            </svg>
                            Kirim Pendaftaran
                          </>
                        )}
                      </button>

                      {agenda.linkGForm && (
                        <div className="mt-6 text-center animate-in fade-in duration-700 delay-300">
                          <p className="text-xs text-slate-500 mb-1.5">
                            Sistem sibuk atau ada kendala error di HP Anda?
                          </p>
                          <a
                            href={agenda.linkGForm}
                            target="_blank"
                            rel="noopener noreferrer"
                            className="inline-flex items-center gap-1.5 text-sm font-bold text-blue-600 hover:text-blue-800 hover:underline bg-blue-50 px-4 py-2 rounded-lg transition-colors border border-blue-100"
                          >
                            <svg
                              className="w-4 h-4"
                              fill="none"
                              viewBox="0 0 24 24"
                              stroke="currentColor"
                            >
                              <path
                                strokeLinecap="round"
                                strokeLinejoin="round"
                                strokeWidth={2}
                                d="M10 6H6a2 2 0 00-2 2v10a2 2 0 002 2h10a2 2 0 002-2v-4M14 4h6m0 0v6m0-6L10 14"
                              />
                            </svg>
                            Daftar via Alternatif Form
                          </a>
                        </div>
                      )}
                    </div>
                  </form>
                </>
              )}
            </div>
          </div>
        </div>
      </main>

      <FooterPublic />
    </div>
  );
}

"use client";

import { useEffect, useState, useMemo } from "react";
import { db } from "@/lib/firebase";
import {
  collection,
  getDocs,
  doc,
  getDoc,
  query,
  orderBy,
} from "firebase/firestore";
//import NavbarPublic from "@/components/layout/NavbarPublic";
import FooterPublic from "@/components/layout/FooterPublic";
import Link from "next/link";

// --- FUNGSI FORMAT RUPIAH ---
const formatRupiah = (angka: number) => {
  return new Intl.NumberFormat("id-ID", {
    style: "currency",
    currency: "IDR",
    maximumFractionDigits: 0,
  }).format(angka);
};

// --- WIDGET DONASI SIDEBAR (DINAMIS DARI PROPS) ---
const SidebarDonationWidget = ({ donasiData }: { donasiData: any }) => (
  <div className="bg-gradient-to-b from-green-800 to-emerald-950 rounded-2xl p-6 text-white shadow-xl border border-green-700 relative overflow-hidden sticky top-[160px]">
    <div className="absolute -top-10 -right-10 w-32 h-32 bg-white/10 rounded-full blur-2xl pointer-events-none"></div>
    <div className="absolute -bottom-10 -left-10 w-32 h-32 bg-yellow-400/10 rounded-full blur-2xl pointer-events-none"></div>

    <div className="relative z-10">
      <h3 className="text-xl font-black mb-2 text-yellow-400 border-b border-green-600/50 pb-3">
        Program Jum'at Berkah
      </h3>

      <div className="mt-4 bg-black/20 rounded-xl p-4 border border-white/10 text-center">
        <p className="text-[10px] text-green-200 uppercase tracking-widest mb-1">
          Salurkan Donasi Melalui
        </p>
        <p className="font-bold text-xl tracking-wider">
          BSI <span className="text-yellow-400">7335717788</span>
        </p>
        <p className="text-[10px] text-green-100 uppercase mt-1">
          a.n SYAIFULLOH YUSUF
        </p>
      </div>

      <div className="mt-5 space-y-3">
        {/* TOTAL MASUK DINAMIS */}
        <div className="bg-white/10 rounded-lg p-3 border border-white/5">
          <p className="text-[10px] text-green-200 uppercase font-bold tracking-wider">
            Total Donasi Masuk
          </p>
          <p className="font-black text-xl text-white mt-1">
            {formatRupiah(donasiData?.totalMasuk || 0)}
          </p>
        </div>

        {/* TOTAL KELUAR DINAMIS */}
        <div className="bg-black/30 rounded-lg p-3 border border-black/20">
          <p className="text-[10px] text-yellow-300 uppercase font-bold tracking-wider">
            Telah Disalurkan
          </p>
          <p className="font-black text-xl text-yellow-400 mt-1">
            {formatRupiah(donasiData?.totalKeluar || 0)}
          </p>

          {/* DETAIL PENGGUNAAN DINAMIS */}
          <div className="mt-2 pt-2 border-t border-white/10">
            <p className="text-[10px] text-green-100 italic whitespace-pre-wrap">
              {donasiData?.detailPenggunaan || "Belum ada rincian penyaluran."}
            </p>
          </div>
        </div>
      </div>
    </div>
  </div>
);

export default function BeritaPage() {
  const [beritaList, setBeritaList] = useState<any[]>([]);
  const [donasiStat, setDonasiStat] = useState<any>({}); // State baru untuk data donasi
  const [isLoading, setIsLoading] = useState(true);
  const [searchTerm, setSearchTerm] = useState("");
  const [activeCategory, setActiveCategory] = useState("Semua");

  useEffect(() => {
    const fetchData = async () => {
      try {
        // 1. Ambil Data Berita
        const q = query(collection(db, "berita"), orderBy("createdAt", "desc"));
        const snapBerita = await getDocs(q);
        setBeritaList(
          snapBerita.docs.map((doc) => ({ id: doc.id, ...doc.data() })),
        );
      } catch (error) {
        console.error("Gagal memuat data Berita (Cek Rules/Index):", error);
      }

      try {
        // 2. Ambil Data Transparansi Donasi
        const docDonasi = await getDoc(doc(db, "pengaturan", "donasi_jumat"));
        if (docDonasi.exists()) {
          setDonasiStat(docDonasi.data());
        }
      } catch (error) {
        console.error("Gagal memuat data Pengaturan donasi_jumat:", error);
      }

      setIsLoading(false);
    };
    fetchData();
  }, []);

  const categories = useMemo(() => {
    const cats = new Set(beritaList.map((b) => b.kategori || "Umum"));
    cats.add("Jum'at Berkah");
    return ["Semua", ...Array.from(cats)];
  }, [beritaList]);

  const filteredBerita = useMemo(() => {
    return beritaList.filter((b) => {
      const matchesSearch = b.judul
        ?.toLowerCase()
        .includes(searchTerm.toLowerCase());
      const matchesCategory =
        activeCategory === "Semua" || b.kategori === activeCategory;
      return matchesSearch && matchesCategory;
    });
  }, [beritaList, searchTerm, activeCategory]);

  if (isLoading) {
    return (
      <div className="min-h-screen flex items-center justify-center bg-slate-50">
        <div className="w-10 h-10 border-4 border-slate-200 border-t-blue-900 rounded-full animate-spin"></div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-slate-50 flex flex-col">
      <section className="pt-32 pb-12 bg-blue-950 relative overflow-hidden">
        <div className="max-w-7xl mx-auto px-6 relative z-10">
          <h1 className="text-3xl md:text-4xl font-black text-white mb-4">
            Berita & <span className="text-yellow-400">Publikasi</span>
          </h1>
          <p className="text-slate-300 max-w-2xl text-sm md:text-base">
            Informasi terbaru mengenai kegiatan, agenda sosial, dan perkembangan
            organisasi DPW IKA UII DIY.
          </p>
        </div>
      </section>

      <section className="top-[88px] z-30 bg-white border-b border-slate-200 py-4 shadow-sm">
        <div className="max-w-7xl mx-auto px-6 flex flex-col md:flex-row gap-4 justify-between items-center">
          <div className="flex gap-2 overflow-x-auto pb-2 md:pb-0 w-full md:w-auto no-scrollbar">
            {categories.map((cat) => (
              <button
                key={cat}
                onClick={() => setActiveCategory(cat)}
                className={`px-4 py-1.5 rounded-full text-xs font-bold transition-all whitespace-nowrap border ${
                  activeCategory === cat
                    ? "bg-blue-900 text-white border-blue-900 shadow-md"
                    : "bg-slate-50 text-slate-600 border-slate-200 hover:border-blue-300"
                }`}
              >
                {cat}
              </button>
            ))}
          </div>
          <div className="relative w-full md:w-72 shrink-0">
            <input
              type="text"
              placeholder="Cari berita..."
              value={searchTerm}
              onChange={(e) => setSearchTerm(e.target.value)}
              className="w-full pl-10 pr-4 py-2 bg-slate-100 border-none rounded-xl text-sm focus:ring-2 focus:ring-blue-900 outline-none"
            />
          </div>
        </div>
      </section>

      <main className="flex-grow max-w-7xl mx-auto px-6 py-12 w-full flex flex-col lg:flex-row gap-8 items-start">
        <div className="flex-1 w-full">
          {filteredBerita.length === 0 ? (
            <div className="text-center py-20 bg-white rounded-2xl border border-slate-100">
              <p className="text-slate-500 font-medium">
                Belum ada berita yang diterbitkan di kategori ini.
              </p>
            </div>
          ) : (
            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
              {filteredBerita.map((berita) => (
                <Link
                  key={berita.id}
                  href={`/berita/${berita.id}`}
                  className="group bg-white rounded-2xl overflow-hidden shadow-sm border border-slate-100 hover:shadow-xl transition-all duration-300 flex flex-col"
                >
                  <div className="relative aspect-video overflow-hidden bg-slate-200">
                    <img
                      src={berita.thumbnail || "/logo-dpp-ika.png"}
                      alt={berita.judul}
                      className="w-full h-full object-cover group-hover:scale-110 transition-transform duration-500"
                    />
                    <div className="absolute top-4 left-4">
                      <span
                        className={`backdrop-blur-md text-white text-[10px] font-bold px-3 py-1 rounded-full uppercase tracking-wider ${berita.kategori === "Jum'at Berkah" ? "bg-green-700/90" : "bg-blue-900/90"}`}
                      >
                        {berita.kategori || "Umum"}
                      </span>
                    </div>
                  </div>
                  <div className="p-6 flex flex-col flex-grow">
                    <p className="text-slate-400 text-[10px] font-bold uppercase tracking-widest mb-2">
                      {new Date(berita.createdAt).toLocaleDateString("id-ID", {
                        day: "numeric",
                        month: "long",
                        year: "numeric",
                      })}
                    </p>
                    <h3 className="text-lg font-bold text-blue-950 group-hover:text-blue-700 transition-colors line-clamp-2 mb-3">
                      {berita.judul}
                    </h3>
                    <p className="text-slate-600 text-sm line-clamp-3 mb-6 flex-grow">
                      {berita.ringkasan ||
                        berita.isi?.replace(/<[^>]*>/g, "").substring(0, 120) +
                          "..."}
                    </p>
                    <div className="flex items-center text-blue-900 font-bold text-xs group-hover:gap-2 transition-all">
                      BACA SELENGKAPNYA <span>→</span>
                    </div>
                  </div>
                </Link>
              ))}
            </div>
          )}
        </div>

        {/* WIDGET KANAN: Mengirim data yang diambil dari Firebase sebagai props */}
        <aside className="w-full lg:w-[350px] shrink-0">
          <SidebarDonationWidget donasiData={donasiStat} />
        </aside>
      </main>

      <FooterPublic />
    </div>
  );
}

"use client";

import { useState, useEffect, useMemo, useRef } from "react";
import NavbarPublic from "@/components/layout/NavbarPublic";
import FooterPublic from "@/components/layout/FooterPublic";
import { db } from "@/lib/firebase";
import {
  collection,
  query,
  orderBy,
  getDocs,
  addDoc,
  serverTimestamp,
} from "firebase/firestore";
import Link from "next/link";

const KATEGORI_LIST = [
  "Semua",
  "Kuliner",
  "Teknologi",
  "Jasa",
  "Retail",
  "Kesehatan",
  "Pendidikan",
  "Properti",
  "Lainnya",
];

export default function DirektoriBisnisPage() {
  const [bisnisList, setBisnisList] = useState<any[]>([]);
  const [iklanList, setIklanList] = useState<any[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [searchTerm, setSearchTerm] = useState("");
  const [selectedKategori, setSelectedKategori] = useState("Semua");

  // STATE PAGINASI
  const [itemsPerPage, setItemsPerPage] = useState<string>("12");
  const [currentPage, setCurrentPage] = useState(1);

  // STATE MODAL DETAIL & FORM
  const [selectedBisnis, setSelectedBisnis] = useState<any>(null);
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [uploadProgress, setUploadProgress] = useState("");

  // 🔥 STATE & REF UNTUK SLIDER IKLAN 🔥
  const carouselRef = useRef<HTMLDivElement>(null);
  const [isHovered, setIsHovered] = useState(false);
  const [currentAdIndex, setCurrentAdIndex] = useState(0);

  // CUSTOM DIALOG STATE
  const [dialog, setDialog] = useState<{
    isOpen: boolean;
    type: "success" | "error" | "info";
    title: string;
    message: string;
  }>({
    isOpen: false,
    type: "info",
    title: "",
    message: "",
  });

  const [formData, setFormData] = useState({
    namaAlumni: "",
    emailPemilik: "",
    fakultasAngkatan: "",
    prodi: "",
    namaBisnis: "",
    kategori: "Kuliner",
    kategoriLainnya: "",
    alamatUsaha: "",
    fasilitas: "",
    deskripsi: "",
    noWA: "",
    linkBisnis: "",
    fotoUrl: "",
  });

  const closeDialog = () => setDialog({ ...dialog, isOpen: false });
  const showDialog = (
    type: "success" | "error" | "info",
    title: string,
    message: string,
  ) => {
    setDialog({ isOpen: true, type, title, message });
  };

  // Fetch Data Bisnis & Iklan
  useEffect(() => {
    const fetchData = async () => {
      try {
        const qBisnis = query(
          collection(db, "direktori_bisnis"),
          orderBy("createdAt", "desc"),
        );
        const snapBisnis = await getDocs(qBisnis);
        const dataBisnis = snapBisnis.docs
          .map((doc) => ({ id: doc.id, ...doc.data() }))
          .filter((b: any) => b.status !== "Pending" && b.status !== "Ditolak");
        setBisnisList(dataBisnis);

        const qIklan = query(
          collection(db, "iklan_direktori"),
          orderBy("createdAt", "desc"),
        );
        const snapIklan = await getDocs(qIklan);

        const activeAds = snapIklan.docs
          .map((doc) => ({ id: doc.id, ...doc.data() }))
          .filter((iklan: any) => iklan.isActive !== false);

        setIklanList(activeAds);
      } catch (error) {
        console.error("Gagal memuat data:", error);
      } finally {
        setIsLoading(false);
      }
    };
    fetchData();
  }, []);

  // 🔥 LOGIKA AUTO-SLIDE BANNER & INDIKATOR 🔥
  useEffect(() => {
    if (iklanList.length <= 1 || isHovered) return;

    const interval = setInterval(() => {
      if (carouselRef.current) {
        const { scrollLeft, clientWidth } = carouselRef.current;
        let nextIndex = Math.round(scrollLeft / clientWidth) + 1;

        // Reset ke gambar pertama jika sudah mencapai akhir
        if (nextIndex >= iklanList.length) nextIndex = 0;

        carouselRef.current.scrollTo({
          left: nextIndex * clientWidth,
          behavior: "smooth",
        });
      }
    }, 5000);

    return () => clearInterval(interval);
  }, [iklanList.length, isHovered]);

  const handleCarouselScroll = () => {
    if (carouselRef.current) {
      const index = Math.round(
        carouselRef.current.scrollLeft / carouselRef.current.clientWidth,
      );
      setCurrentAdIndex(index);
    }
  };

  const scrollToAd = (index: number) => {
    if (carouselRef.current) {
      carouselRef.current.scrollTo({
        left: index * carouselRef.current.clientWidth,
        behavior: "smooth",
      });
    }
  };

  // Logika Buka Modal Detail via URL Params
  useEffect(() => {
    const params = new URLSearchParams(window.location.search);
    const idParam = params.get("id");
    if (idParam && bisnisList.length > 0) {
      const found = bisnisList.find((b) => b.id === idParam);
      if (found) setSelectedBisnis(found);
    }
  }, [bisnisList]);

  const openDetail = (bisnis: any) => {
    setSelectedBisnis(bisnis);
    window.history.pushState({}, "", `?id=${bisnis.id}`);
  };

  const closeDetail = () => {
    setSelectedBisnis(null);
    window.history.pushState({}, "", window.location.pathname);
  };

  const handleImageUpload = async (e: any) => {
    const file = e.target.files[0];
    if (!file) return;

    setUploadProgress("Mengunggah gambar...");
    const data = new FormData();
    data.append("file", file);
    data.append("upload_preset", "bisnis");
    data.append("cloud_name", "dp8hmxuix");

    try {
      const res = await fetch(
        `https://api.cloudinary.com/v1_1/dp8hmxuix/image/upload`,
        {
          method: "POST",
          body: data,
        },
      );
      const json = await res.json();
      setFormData({ ...formData, fotoUrl: json.secure_url });
      setUploadProgress("Gambar berhasil diunggah!");
    } catch (error) {
      console.error("Gagal upload gambar:", error);
      setUploadProgress("Gagal mengunggah gambar. Coba lagi.");
    }
  };

  const checkDuplicateRegistration = async (
    email: string,
    namaBisnis: string,
  ) => {
    try {
      const qPending = query(collection(db, "pendaftaran_bisnis"));
      const snapPending = await getDocs(qPending);
      const isDuplicatePending = snapPending.docs.some((doc) => {
        const data = doc.data();
        return (
          (data.emailPemilik?.toLowerCase() === email.toLowerCase() ||
            data.email?.toLowerCase() === email.toLowerCase()) &&
          (data.namaBisnis?.toLowerCase() === namaBisnis.toLowerCase() ||
            data.nama?.toLowerCase() === namaBisnis.toLowerCase())
        );
      });

      if (isDuplicatePending) return true;

      const qMaster = query(collection(db, "direktori_bisnis"));
      const snapMaster = await getDocs(qMaster);
      const isDuplicateMaster = snapMaster.docs.some((doc) => {
        const data = doc.data();
        return (
          (data.emailPemilik?.toLowerCase() === email.toLowerCase() ||
            data.email?.toLowerCase() === email.toLowerCase()) &&
          (data.namaBisnis?.toLowerCase() === namaBisnis.toLowerCase() ||
            data.nama?.toLowerCase() === namaBisnis.toLowerCase())
        );
      });

      return isDuplicateMaster;
    } catch (error) {
      console.error("Gagal mengecek duplikasi:", error);
      return false;
    }
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setIsSubmitting(true);

    const isDuplicate = await checkDuplicateRegistration(
      formData.emailPemilik,
      formData.namaBisnis,
    );

    if (isDuplicate) {
      showDialog(
        "error",
        "Pendaftaran Ditolak",
        `Alamat email "${formData.emailPemilik}" sudah pernah mendaftarkan bisnis dengan nama "${formData.namaBisnis}" sebelumnya. Tim Admin sedang meninjaunya atau bisnis tersebut sudah tayang.`,
      );
      setIsSubmitting(false);
      return;
    }

    const finalKategori =
      formData.kategori === "Lainnya"
        ? formData.kategoriLainnya
        : formData.kategori;

    try {
      await addDoc(collection(db, "pendaftaran_bisnis"), {
        ...formData,
        kategori: finalKategori,
        status: "Pending",
        createdAt: serverTimestamp(),
      });

      showDialog(
        "success",
        "Pendaftaran Berhasil",
        "Data Anda telah masuk ke sistem. Tim kami akan melakukan verifikasi sebelum bisnis ditayangkan di direktori publik.",
      );
      setIsModalOpen(false);
      setFormData({
        namaAlumni: "",
        emailPemilik: "",
        fakultasAngkatan: "",
        prodi: "",
        namaBisnis: "",
        kategori: "Kuliner",
        kategoriLainnya: "",
        alamatUsaha: "",
        fasilitas: "",
        deskripsi: "",
        noWA: "",
        linkBisnis: "",
        fotoUrl: "",
      });
      setUploadProgress("");
    } catch (error) {
      showDialog(
        "error",
        "Kesalahan Sistem",
        "Terjadi kesalahan saat memproses pendaftaran. Silakan coba lagi.",
      );
    } finally {
      setIsSubmitting(false);
    }
  };

  const filteredBisnis = useMemo(() => {
    return bisnisList.filter((bisnis) => {
      const namaBisnis = bisnis.namaBisnis || bisnis.nama || "";
      const owner = bisnis.owner || bisnis.namaAlumni || "";
      const kat = bisnis.kategori || "";

      const matchSearch =
        namaBisnis.toLowerCase().includes(searchTerm.toLowerCase()) ||
        owner.toLowerCase().includes(searchTerm.toLowerCase());
      const matchKategori =
        selectedKategori === "Semua" || kat === selectedKategori;

      return matchSearch && matchKategori;
    });
  }, [bisnisList, searchTerm, selectedKategori]);

  useEffect(() => {
    setCurrentPage(1);
  }, [searchTerm, selectedKategori, itemsPerPage]);

  const parsedItemsPerPage =
    itemsPerPage === "Semua" ? "Semua" : parseInt(itemsPerPage);

  const totalPages =
    parsedItemsPerPage === "Semua"
      ? 1
      : Math.ceil(filteredBisnis.length / parsedItemsPerPage);

  const currentData = useMemo(() => {
    if (parsedItemsPerPage === "Semua") return filteredBisnis;
    const start = (currentPage - 1) * parsedItemsPerPage;
    return filteredBisnis.slice(start, start + parsedItemsPerPage);
  }, [filteredBisnis, currentPage, parsedItemsPerPage]);

  const handleCopyLink = () => {
    navigator.clipboard.writeText(window.location.href);
    showDialog(
      "info",
      "Tautan Tersalin",
      "Tautan profil bisnis ini telah disalin ke clipboard Anda.",
    );
  };

  return (
    <div
      suppressHydrationWarning
      className="bg-[#F8F9FA] min-h-screen flex flex-col font-sans text-[#202124]"
    >
      <NavbarPublic />
      <main className="flex-grow pt-28 pb-20">
        {/* CUSTOM DIALOG */}
        {dialog.isOpen && (
          <div className="fixed inset-0 z-[200] flex items-center justify-center p-4 bg-slate-900/40 backdrop-blur-sm animate-in fade-in duration-200">
            <div className="bg-white rounded-lg w-full max-w-sm shadow-2xl flex flex-col overflow-hidden border border-[#DADCE0] animate-in zoom-in-95">
              <div className="px-6 py-5">
                <div className="flex items-center gap-3 mb-2">
                  {dialog.type === "success" && (
                    <svg
                      className="w-6 h-6 text-[#1E8E3E]"
                      fill="none"
                      viewBox="0 0 24 24"
                      stroke="currentColor"
                    >
                      <path
                        strokeLinecap="round"
                        strokeLinejoin="round"
                        strokeWidth={2.5}
                        d="M9 12l2 2 4-4m6 2a9 9 0 11-18 0 9 9 0 0118 0z"
                      />
                    </svg>
                  )}
                  {dialog.type === "error" && (
                    <svg
                      className="w-6 h-6 text-[#D93025]"
                      fill="none"
                      viewBox="0 0 24 24"
                      stroke="currentColor"
                    >
                      <path
                        strokeLinecap="round"
                        strokeLinejoin="round"
                        strokeWidth={2.5}
                        d="M12 9v2m0 4h.01m-6.938 4h13.856c1.54 0 2.502-1.667 1.732-3L13.732 4c-.77-1.333-2.694-1.333-3.464 0L3.34 16c-.77 1.333.192 3 1.732 3z"
                      />
                    </svg>
                  )}
                  {dialog.type === "info" && (
                    <svg
                      className="w-6 h-6 text-[#1A73E8]"
                      fill="none"
                      viewBox="0 0 24 24"
                      stroke="currentColor"
                    >
                      <path
                        strokeLinecap="round"
                        strokeLinejoin="round"
                        strokeWidth={2.5}
                        d="M13 16h-1v-4h-1m1-4h.01M21 12a9 9 0 11-18 0 9 9 0 0118 0z"
                      />
                    </svg>
                  )}
                  <h2
                    className={`text-lg font-medium ${dialog.type === "error" ? "text-[#D93025]" : dialog.type === "success" ? "text-[#1E8E3E]" : "text-[#1A73E8]"}`}
                  >
                    {dialog.title}
                  </h2>
                </div>
                <p className="text-sm text-[#5F6368] leading-relaxed">
                  {dialog.message}
                </p>
              </div>
              <div className="px-6 py-4 bg-[#F8F9FA] border-t border-[#DADCE0] flex justify-end">
                <button
                  onClick={closeDialog}
                  className={`px-5 py-2 text-sm font-medium text-white rounded transition-colors shadow-sm ${dialog.type === "error" ? "bg-[#D93025] hover:bg-[#b52a1f]" : dialog.type === "success" ? "bg-[#1E8E3E] hover:bg-[#137333]" : "bg-[#1A73E8] hover:bg-[#1557B0]"}`}
                >
                  Mengerti
                </button>
              </div>
            </div>
          </div>
        )}

        {/* MODAL FORM DAFTAR BISNIS */}
        {isModalOpen && (
          <div className="fixed inset-0 bg-slate-900/60 backdrop-blur-sm z-[100] flex items-center justify-center p-4 animate-in fade-in duration-200">
            <div className="bg-white rounded-2xl p-6 md:p-8 max-w-2xl w-full shadow-2xl relative max-h-[90vh] overflow-y-auto border border-[#DADCE0] animate-in zoom-in-95">
              <button
                onClick={() => setIsModalOpen(false)}
                className="absolute top-5 right-5 p-2 bg-slate-50 rounded-full text-slate-500 hover:bg-[#FCE8E6] hover:text-[#D93025] transition-colors z-10"
              >
                <svg
                  className="w-5 h-5"
                  fill="none"
                  viewBox="0 0 24 24"
                  stroke="currentColor"
                >
                  <path
                    strokeLinecap="round"
                    strokeLinejoin="round"
                    strokeWidth={2.5}
                    d="M6 18L18 6M6 6l12 12"
                  />
                </svg>
              </button>

              <div className="mb-6 mt-1 border-b border-[#DADCE0] pb-5 flex items-center gap-3">
                <div className="w-12 h-12 bg-[#E8F0FE] text-[#1A73E8] rounded-xl flex items-center justify-center shrink-0">
                  <svg
                    className="w-6 h-6"
                    fill="none"
                    viewBox="0 0 24 24"
                    stroke="currentColor"
                  >
                    <path
                      strokeLinecap="round"
                      strokeLinejoin="round"
                      strokeWidth={2}
                      d="M19 21V5a2 2 0 00-2-2H7a2 2 0 00-2 2v16m14 0h2m-2 0h-5m-9 0H3m2 0h5M9 7h1m-1 4h1m4-4h1m-1 4h1m-5 10v-5a1 1 0 011-1h2a1 1 0 011 1v5m-4 0h4"
                    />
                  </svg>
                </div>
                <div>
                  <h3 className="text-xl font-bold text-[#202124] leading-tight">
                    Daftarkan Bisnis
                  </h3>
                  <p className="text-xs text-[#5F6368] mt-0.5">
                    Isi data lengkap. Admin akan memverifikasi sebelum
                    ditayangkan.
                  </p>
                </div>
              </div>

              <form onSubmit={handleSubmit} className="space-y-4">
                <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                  <div>
                    <label className="block text-[11px] font-bold text-[#5F6368] uppercase tracking-widest mb-1.5">
                      Nama Lengkap Alumni
                    </label>
                    <input
                      required
                      type="text"
                      value={formData.namaAlumni}
                      onChange={(e) =>
                        setFormData({ ...formData, namaAlumni: e.target.value })
                      }
                      placeholder="Sesuai Ijazah"
                      className="w-full px-3.5 py-2.5 bg-[#F8F9FA] border border-[#DADCE0] rounded-xl focus:border-[#1A73E8] focus:bg-white outline-none text-sm transition-colors"
                    />
                  </div>
                  <div>
                    <label className="block text-[11px] font-bold text-[#5F6368] uppercase tracking-widest mb-1.5">
                      Email Aktif
                    </label>
                    <input
                      required
                      type="email"
                      value={formData.emailPemilik}
                      onChange={(e) =>
                        setFormData({
                          ...formData,
                          emailPemilik: e.target.value,
                        })
                      }
                      placeholder="contoh@email.com"
                      className="w-full px-3.5 py-2.5 bg-[#F8F9FA] border border-[#DADCE0] rounded-xl focus:border-[#1A73E8] focus:bg-white outline-none text-sm transition-colors"
                    />
                  </div>
                </div>

                <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                  <div>
                    <label className="block text-[11px] font-bold text-[#5F6368] uppercase tracking-widest mb-1.5">
                      Fakultas / Angkatan
                    </label>
                    <input
                      required
                      type="text"
                      value={formData.fakultasAngkatan}
                      onChange={(e) =>
                        setFormData({
                          ...formData,
                          fakultasAngkatan: e.target.value,
                        })
                      }
                      placeholder="Cth: FTI 2012"
                      className="w-full px-3.5 py-2.5 bg-[#F8F9FA] border border-[#DADCE0] rounded-xl focus:border-[#1A73E8] focus:bg-white outline-none text-sm transition-colors"
                    />
                  </div>
                  <div>
                    <label className="block text-[11px] font-bold text-[#5F6368] uppercase tracking-widest mb-1.5">
                      Program Studi
                    </label>
                    <input
                      required
                      type="text"
                      value={formData.prodi}
                      onChange={(e) =>
                        setFormData({ ...formData, prodi: e.target.value })
                      }
                      placeholder="Cth: Teknik Industri"
                      className="w-full px-3.5 py-2.5 bg-[#F8F9FA] border border-[#DADCE0] rounded-xl focus:border-[#1A73E8] focus:bg-white outline-none text-sm transition-colors"
                    />
                  </div>
                </div>

                <div className="border-t border-[#DADCE0] pt-4 mt-2">
                  <div className="grid grid-cols-1 sm:grid-cols-2 gap-4 items-start">
                    <div>
                      <label className="block text-[11px] font-bold text-[#5F6368] uppercase tracking-widest mb-1.5">
                        Nama Usaha / Bisnis
                      </label>
                      <input
                        required
                        type="text"
                        value={formData.namaBisnis}
                        onChange={(e) =>
                          setFormData({
                            ...formData,
                            namaBisnis: e.target.value,
                          })
                        }
                        placeholder="Cth: Kopi Kenangan"
                        className="w-full px-3.5 py-2.5 bg-[#F8F9FA] border border-[#DADCE0] rounded-xl focus:border-[#1A73E8] focus:bg-white outline-none text-sm font-bold text-[#202124] transition-colors"
                      />
                    </div>
                    <div>
                      <label className="block text-[11px] font-bold text-[#5F6368] uppercase tracking-widest mb-1.5">
                        Kategori Usaha
                      </label>
                      <select
                        required
                        value={formData.kategori}
                        onChange={(e) =>
                          setFormData({ ...formData, kategori: e.target.value })
                        }
                        className={`w-full px-3.5 py-2.5 bg-[#F8F9FA] border border-[#DADCE0] rounded-xl outline-none text-sm transition-colors cursor-pointer ${formData.kategori === "Lainnya" ? "mb-2" : ""}`}
                      >
                        {KATEGORI_LIST.filter((k) => k !== "Semua").map(
                          (kat) => (
                            <option key={kat} value={kat}>
                              {kat}
                            </option>
                          ),
                        )}
                      </select>
                      {formData.kategori === "Lainnya" && (
                        <input
                          required
                          type="text"
                          value={formData.kategoriLainnya}
                          onChange={(e) =>
                            setFormData({
                              ...formData,
                              kategoriLainnya: e.target.value,
                            })
                          }
                          placeholder="Ketik kategori..."
                          className="w-full px-3.5 py-2 bg-[#E8F0FE] border border-[#1A73E8]/30 rounded-lg focus:border-[#1A73E8] outline-none text-sm transition-colors animate-in fade-in"
                        />
                      )}
                    </div>
                  </div>
                </div>

                <div>
                  <label className="block text-[11px] font-bold text-[#5F6368] uppercase tracking-widest mb-1.5">
                    Alamat Lengkap Usaha
                  </label>
                  <textarea
                    required
                    rows={2}
                    value={formData.alamatUsaha}
                    onChange={(e) =>
                      setFormData({ ...formData, alamatUsaha: e.target.value })
                    }
                    placeholder="Jalan, Kelurahan, Kecamatan, Kota..."
                    className="w-full px-3.5 py-2.5 bg-[#F8F9FA] border border-[#DADCE0] rounded-xl focus:border-[#1A73E8] focus:bg-white outline-none text-sm resize-none transition-colors"
                  ></textarea>
                </div>

                <div>
                  <label className="block text-[11px] font-bold text-[#5F6368] uppercase tracking-widest mb-1.5">
                    Fasilitas Bisnis (Pisahkan dengan koma)
                  </label>
                  <input
                    required
                    type="text"
                    value={formData.fasilitas}
                    onChange={(e) =>
                      setFormData({ ...formData, fasilitas: e.target.value })
                    }
                    placeholder="Cth: WiFi Cepat, Parkir Luas, Ruang AC, Delivery"
                    className="w-full px-3.5 py-2.5 bg-[#F8F9FA] border border-[#DADCE0] rounded-xl focus:border-[#1A73E8] focus:bg-white outline-none text-sm transition-colors"
                  />
                </div>

                <div>
                  <label className="block text-[11px] font-bold text-[#5F6368] uppercase tracking-widest mb-1.5">
