        {/* MODAL DETAIL BISNIS (FULL SCREEN) */}
        {selectedBisnis && (
          <div className="fixed inset-0 bg-slate-900/80 backdrop-blur-sm z-[150] flex items-center justify-center p-4 md:p-6 animate-in fade-in duration-200">
