                      <h2 className="text-3xl font-black text-[#202124] mb-2 leading-tight">
                        {selectedBisnis.namaBisnis || selectedBisnis.nama}
                      </h2>
                      <div className="flex items-center gap-2 text-sm text-[#5F6368]">
                        <svg
                          className="w-4 h-4"
                          fill="none"
                          viewBox="0 0 24 24"
                          stroke="currentColor"
                        >
                          <path
                            strokeLinecap="round"
                            strokeLinejoin="round"
                            strokeWidth={2}
                            d="M16 7a4 4 0 11-8 0 4 4 0 018 0zM12 14a7 7 0 00-7 7h14a7 7 0 00-7-7z"
                          />
                        </svg>
                        Oleh:{" "}
                        <span className="font-bold text-[#202124]">
                          {selectedBisnis.owner || selectedBisnis.namaAlumni}
                        </span>
                      </div>
                    </div>

                    <div className="bg-[#F8F9FA] rounded-2xl p-5 border border-[#DADCE0]">
                      <h3 className="text-xs font-bold text-[#1A73E8] uppercase tracking-widest mb-2 border-b border-[#DADCE0] pb-2">
                        Informasi Produk / Jasa
                      </h3>
                      <p className="text-[#202124] text-sm leading-relaxed whitespace-pre-wrap">
                        {selectedBisnis.deskripsi}
                      </p>
                    </div>

                    {selectedBisnis.fasilitas && (
                      <div>
                        <h3 className="text-xs font-bold text-[#5F6368] uppercase tracking-widest mb-2">
                          Fasilitas Bisnis
                        </h3>
                        <div className="flex flex-wrap gap-2">
                          {selectedBisnis.fasilitas
                            .split(",")
                            .map((fas: string, i: number) => (
                              <span
                                key={i}
                                className="bg-white border border-[#DADCE0] text-[#5F6368] px-3 py-1.5 rounded-lg text-xs font-bold shadow-sm"
                              >
                                ✓ {fas.trim()}
                              </span>
                            ))}
                        </div>
                      </div>
                    )}

                    {(selectedBisnis.alamatUsaha || selectedBisnis.alamat) && (
                      <div>
                        <h3 className="text-xs font-bold text-[#5F6368] uppercase tracking-widest mb-1.5 flex items-center gap-1.5">
                          <svg
                            className="w-4 h-4"
                            fill="none"
                            viewBox="0 0 24 24"
                            stroke="currentColor"
                          >
                            <path
                              strokeLinecap="round"
                              strokeLinejoin="round"
                              strokeWidth={2}
                              d="M17.657 16.657L13.414 20.9a1.998 1.998 0 01-2.827 0l-4.244-4.243a8 8 0 1111.314 0z"
                            />
                            <path
                              strokeLinecap="round"
                              strokeLinejoin="round"
                              strokeWidth={2}
                              d="M15 11a3 3 0 11-6 0 3 3 0 016 0z"
                            />
                          </svg>
                          Lokasi Usaha
                        </h3>
                        <p className="text-[#202124] text-sm bg-white border border-[#DADCE0] p-3.5 rounded-xl leading-relaxed">
                          {selectedBisnis.alamatUsaha || selectedBisnis.alamat}
                        </p>
                      </div>
                    )}
                  </div>

                  <div className="w-full md:w-72 shrink-0 space-y-5">
                    <div className="bg-[#E8F0FE] border border-[#1A73E8]/20 rounded-2xl p-5">
                      <h3 className="text-[10px] font-bold text-[#1A73E8] uppercase tracking-widest mb-3">
                        Latar Belakang Alumni
                      </h3>
                      <div className="space-y-3">
                        <div>
                          <p className="text-[10px] text-[#5F6368] uppercase tracking-wider">
                            Fakultas / Angkatan
                          </p>
                          <p className="text-sm font-bold text-[#202124]">
                            {selectedBisnis.fakultasAngkatan || "-"}
                          </p>
                        </div>
                        {selectedBisnis.prodi && (
                          <div>
                            <p className="text-[10px] text-[#5F6368] uppercase tracking-wider">
                              Program Studi
                            </p>
                            <p className="text-sm font-bold text-[#202124]">
                              {selectedBisnis.prodi}
                            </p>
                          </div>
                        )}
                      </div>
                    </div>

                    <div className="space-y-3 pt-2 border-t border-[#DADCE0]">
                      <a
                        href={`https://wa.me/${(selectedBisnis.noWA || selectedBisnis.waBisnis || selectedBisnis.wa || "").replace(/^0/, "62")}?text=${encodeURIComponent(`Halo admin ${selectedBisnis.namaBisnis || selectedBisnis.nama}, saya melihat bisnis Anda pada web IKA UII DIY. Saya ingin bertanya lebih lanjut tentang ${selectedBisnis.namaBisnis || selectedBisnis.nama} Anda.`)}`}
                        target="_blank"
                        rel="noreferrer"
                        className="w-full flex items-center justify-center gap-2 bg-[#1E8E3E] hover:bg-[#137333] text-white py-3.5 rounded-xl font-bold text-sm transition-all shadow-sm"
                      >
                        <svg
                          className="w-5 h-5"
                          fill="currentColor"
                          viewBox="0 0 24 24"
                        >
                          <path d="M17.472 14.382c-.297-.149-1.758-.867-2.03-.967-.273-.099-.471-.148-.67.15-.197.297-.767.966-.94 1.164-.173.199-.347.223-.644.075-.297-.15-1.255-.463-2.39-1.405-.883-.733-1.48-1.638-1.653-1.935-.173-.297-.018-.458.13-.606.134-.133.298-.347.446-.52.149-.174.198-.298.298-.497.099-.198.05-.371-.025-.52-.075-.149-.669-1.612-.916-2.207-.242-.579-.487-.5-.669-.51a12.8 12.8 0 0 0-.57-.01c-.198 0-.52.074-.792.372-.272.297-1.04 1.016-1.04 2.479 0 1.462 1.065 2.875 1.213 3.074.149.198 2.096 3.2 5.077 4.487.709.306 1.262.489 1.694.625.712.227 1.36.195 1.871.118.571-.085 1.758-.719 2.006-1.413.248-.694.248-1.289.173-1.413-.074-.124-.272-.198-.57-.347m-5.421 7.403h-.004a9.87 9.87 0 0 1-5.031-1.378l-.361-.214-3.741.982.998-3.648-.235-.374a9.86 9.86 0 0 1-1.51-5.26c.001-5.45 4.436-9.884 9.888-9.884 2.64 0 5.122 1.03 6.988 2.898a9.825 9.825 0 0 1 2.893 6.994c-.003 5.45-4.437 9.884-9.885 9.884m8.413-18.297A11.815 11.815 0 0 0 12.05 0C5.495 0 .16 5.335.157 11.892c0 2.096.547 4.142 1.588 5.945L.057 24l6.305-1.654a11.882 11.882 0 0 0 5.683 1.448h.005c6.554 0 11.89-5.335 11.893-11.893a11.821 11.821 0 0 0-3.48-8.413z" />
                        </svg>
                        Chat WhatsApp
                      </a>
                      {selectedBisnis.linkBisnis && (
                        <a
                          href={
                            selectedBisnis.linkBisnis.startsWith("http")
                              ? selectedBisnis.linkBisnis
                              : `https://${selectedBisnis.linkBisnis}`
                          }
                          target="_blank"
                          rel="noreferrer"
                          className="w-full flex items-center justify-center gap-2 bg-white hover:bg-[#F8F9FA] text-[#1A73E8] border border-[#DADCE0] py-3.5 rounded-xl font-bold text-sm transition-all shadow-sm"
                        >
                          <svg
                            className="w-5 h-5"
                            fill="none"
                            viewBox="0 0 24 24"
                            stroke="currentColor"
                          >
                            <path
                              strokeLinecap="round"
                              strokeLinejoin="round"
                              strokeWidth={2}
                              d="M10 6H6a2 2 0 00-2 2v10a2 2 0 002 2h10a2 2 0 002-2v-4M14 4h6m0 0v6m0-6L10 14"
                            />
                          </svg>
                          Kunjungi Sosial Media
                        </a>
                      )}
                      <button
                        onClick={handleCopyLink}
                        className="w-full flex items-center justify-center gap-2 bg-[#F8F9FA] hover:bg-[#E8F0FE] text-[#5F6368] hover:text-[#1A73E8] border border-[#DADCE0] py-3.5 rounded-xl font-bold text-sm transition-all shadow-sm"
                      >
                        <svg
                          className="w-5 h-5"
                          fill="none"
                          viewBox="0 0 24 24"
                          stroke="currentColor"
                        >
                          <path
                            strokeLinecap="round"
                            strokeLinejoin="round"
                            strokeWidth={2}
                            d="M8 16H6a2 2 0 01-2-2V6a2 2 0 012-2h8a2 2 0 012 2v2m-6 12h8a2 2 0 002-2v-8a2 2 0 00-2-2h-8a2 2 0 00-2 2v8a2 2 0 002 2z"
                          />
                        </svg>
                        Salin Tautan Bisnis
                      </button>
                    </div>
                  </div>
                </div>
              </div>
            </div>
          </div>
        )}

        {/* HEADER SECTION & HERO CTA */}
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 mb-8 text-center animate-in fade-in slide-in-from-bottom-8 duration-700">
          <h4 className="text-yellow-600 font-bold tracking-widest uppercase text-[10px] md:text-xs mb-3 flex items-center justify-center gap-3">
            <span className="w-6 md:w-8 h-px bg-yellow-500"></span>
            Katalog Bisnis Alumni
            <span className="w-6 md:w-8 h-px bg-yellow-500"></span>
          </h4>
          <h1 className="text-3xl md:text-4xl lg:text-5xl font-black text-[#202124] mb-4 md:mb-5 tracking-tight">
            Jaringan Bisnis IKA UII DIY
          </h1>
          <p className="text-[#5F6368] text-sm md:text-base max-w-2xl mx-auto leading-relaxed px-2 mb-8">
            <strong>Baru merintis usaha? Jangan ragu!</strong> Direktori ini
            adalah tempat terbaik untuk saling mendukung dan memperkenalkan
            bisnis Anda kepada jaringan keluarga besar alumni.
          </p>

          <div className="flex flex-col sm:flex-row items-center justify-center gap-4">
            <button
              onClick={() => setIsModalOpen(true)}
              className="w-full sm:w-auto inline-flex items-center justify-center gap-2 px-8 py-3.5 bg-[#1A73E8] hover:bg-[#1557B0] text-white rounded-xl text-sm font-bold transition-all shadow-md hover:-translate-y-0.5"
            >
              Daftarkan Bisnis Anda
              <svg
                className="w-5 h-5"
                fill="none"
                viewBox="0 0 24 24"
                stroke="currentColor"
              >
                <path
                  strokeLinecap="round"
                  strokeLinejoin="round"
                  strokeWidth={2.5}
                  d="M12 4v16m8-8H4"
                />
              </svg>
            </button>
            <Link
              href="/pasang-iklan"
              className="w-full sm:w-auto inline-flex items-center justify-center gap-2 px-8 py-3.5 bg-white hover:bg-[#F8F9FA] text-[#5F6368] border border-[#DADCE0] rounded-xl text-sm font-bold transition-all shadow-sm hover:-translate-y-0.5"
            >
              <svg
                className="w-5 h-5 text-[#5F6368]"
                fill="none"
                viewBox="0 0 24 24"
                stroke="currentColor"
              >
                <path
                  strokeLinecap="round"
                  strokeLinejoin="round"
                  strokeWidth={2.5}
                  d="M11 5.882V19.24a1.76 1.76 0 01-3.417.592l-2.147-6.15M18 13a3 3 0 100-6M5.436 13.683A4.001 4.001 0 017 6h1.832c4.1 0 7.625-1.234 9.168-3v14c-1.543-1.766-5.067-3-9.168-3H7a3.988 3.988 0 01-1.564-.317z"
                />
              </svg>
              Pasang Iklan Banner
            </Link>
          </div>
        </div>

        {/* 🔥 CAROUSEL BANNER IKLAN DENGAN DOTS SLIDER 🔥 */}
        {/* 🔥 CAROUSEL BANNER IKLAN DENGAN DOTS SLIDER 🔥 */}
        {iklanList.length > 0 && (
          <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 mb-12 relative group">
            <div
              ref={carouselRef}
              onMouseEnter={() => setIsHovered(true)}
              onMouseLeave={() => setIsHovered(false)}
              onTouchStart={() => setIsHovered(true)}
              onTouchEnd={() => setIsHovered(false)}
              onScroll={handleCarouselScroll}
              className="flex overflow-x-auto no-scrollbar snap-x snap-mandatory scroll-smooth rounded-xl sm:rounded-2xl shadow-lg border border-slate-200/60 bg-white"
            >
              {iklanList.map((iklan) => (
                <a
                  key={iklan.id}
                  href={iklan.linkTujuan || "#"}
                  target="_blank"
                  rel="noreferrer"
                  className="shrink-0 w-full aspect-[16/9] sm:aspect-[21/9] lg:aspect-[3/1] overflow-hidden block snap-center relative cursor-pointer"
                >
                  {/* Subtle Gradient Overlay */}
                  <div className="absolute inset-0 bg-gradient-to-t from-black/40 via-transparent to-transparent opacity-0 group-hover:opacity-100 transition-opacity duration-500 z-10 pointer-events-none" />
                  
                  <img
                    src={iklan.fotoUrl}
                    alt="Banner Promo"
                    className="w-full h-full object-cover group-hover:scale-[1.02] transition-transform duration-700 ease-out"
                    loading="lazy"
                  />
                </a>
              ))}
            </div>

            {/* Navigation Arrows (Prev / Next) - Visible on Hover & Desktop */}
            {iklanList.length > 1 && (
              <>
                <button
                  onClick={() => scrollToAd(currentAdIndex - 1 >= 0 ? currentAdIndex - 1 : iklanList.length - 1)}
                  className="absolute left-6 lg:left-12 top-1/2 -translate-y-1/2 z-20 bg-white/90 hover:bg-white text-slate-800 p-2 sm:p-3 rounded-full shadow-lg opacity-0 group-hover:opacity-100 transition-all duration-300 backdrop-blur-sm transform hover:scale-110 hidden sm:flex items-center justify-center border border-slate-200/50"
                  aria-label="Previous slide"
                >
                  <svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M15 19l-7-7 7-7" />
                  </svg>
                </button>
                <button
                  onClick={() => scrollToAd(currentAdIndex + 1 < iklanList.length ? currentAdIndex + 1 : 0)}
                  className="absolute right-6 lg:right-12 top-1/2 -translate-y-1/2 z-20 bg-white/90 hover:bg-white text-slate-800 p-2 sm:p-3 rounded-full shadow-lg opacity-0 group-hover:opacity-100 transition-all duration-300 backdrop-blur-sm transform hover:scale-110 hidden sm:flex items-center justify-center border border-slate-200/50"
                  aria-label="Next slide"
                >
                  <svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M9 5l7 7-7 7" />
                  </svg>
                </button>
              </>
            )}

            {/* Indikator Slider (Dots) - Overlaid on Banner Bottom */}
            {iklanList.length > 1 && (
              <div className="absolute bottom-3 sm:bottom-5 left-1/2 -translate-x-1/2 z-20 flex justify-center items-center gap-2 bg-black/20 backdrop-blur-md px-3 py-2 rounded-full">
                {iklanList.map((_, idx) => (
                  <button
                    key={idx}
                    onClick={() => scrollToAd(idx)}
                    className={`h-2 rounded-full transition-all duration-300 ${
                      currentAdIndex === idx
                        ? "w-6 bg-white shadow-sm"
                        : "w-2 bg-white/50 hover:bg-white/90"
                    }`}
                    aria-label={`Go to slide ${idx + 1}`}
                  />
                ))}
              </div>
            )}
          </div>
        )}

        {/* FILTER & SEARCH BAR */}
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 mb-8 md:mb-10">
          <div className="bg-white rounded-2xl p-4 md:p-5 shadow-sm border border-[#DADCE0] flex flex-col md:flex-row gap-4 items-center animate-in fade-in slide-in-from-bottom-8 duration-700 delay-100">
            <div className="relative w-full md:flex-1">
              <svg
                className="absolute left-4 md:left-5 top-1/2 -translate-y-1/2 w-4 h-4 md:w-5 md:h-5 text-[#9AA0A6]"
                fill="none"
                viewBox="0 0 24 24"
                stroke="currentColor"
              >
                <path
                  strokeLinecap="round"
                  strokeLinejoin="round"
                  strokeWidth={2.5}
                  d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z"
                />
              </svg>
              <input
                type="text"
                placeholder="Cari nama bisnis atau alumni..."
                value={searchTerm}
                onChange={(e) => setSearchTerm(e.target.value)}
                className="w-full bg-[#F8F9FA] border border-[#DADCE0] py-3 pl-10 md:pl-12 pr-4 rounded-xl text-sm font-medium focus:border-[#1A73E8] focus:bg-white outline-none transition-all text-[#202124]"
              />
            </div>

            <div className="flex w-full md:w-auto gap-3">
              <div className="flex-1 md:w-48 shrink-0 relative">
                <select
                  value={selectedKategori}
                  onChange={(e) => setSelectedKategori(e.target.value)}
                  className="w-full bg-[#F8F9FA] border border-[#DADCE0] py-3 px-4 rounded-xl text-sm font-bold text-[#5F6368] focus:border-[#1A73E8] focus:bg-white outline-none appearance-none cursor-pointer transition-colors"
                >
                  {KATEGORI_LIST.map((kat) => (
                    <option key={kat} value={kat}>
                      {kat}
                    </option>
                  ))}
                </select>
                <svg
                  className="absolute right-4 top-1/2 -translate-y-1/2 w-4 h-4 text-[#9AA0A6] pointer-events-none"
                  fill="none"
                  viewBox="0 0 24 24"
                  stroke="currentColor"
                >
                  <path
                    strokeLinecap="round"
                    strokeLinejoin="round"
                    strokeWidth={2}
                    d="M19 9l-7 7-7-7"
                  />
                </svg>
              </div>

              <div className="w-24 shrink-0 relative">
                <select
                  value={itemsPerPage}
                  onChange={(e) => setItemsPerPage(e.target.value)}
                  className="w-full bg-[#F8F9FA] border border-[#DADCE0] py-3 px-4 rounded-xl text-sm font-bold text-[#5F6368] focus:border-[#1A73E8] focus:bg-white outline-none appearance-none cursor-pointer text-center transition-colors"
                >
                  <option value="12">12</option>
                  <option value="24">24</option>
                  <option value="Semua">All</option>
                </select>
              </div>
            </div>
          </div>
        </div>

        {/* KATALOG BISNIS GRID */}
        <section className="max-w-7xl mx-auto px-3 sm:px-6 lg:px-8 min-h-[400px]">
          {isLoading ? (
            <div className="bg-white rounded-2xl py-24 text-center border border-[#DADCE0] shadow-sm flex flex-col items-center mx-1">
              <div className="w-8 h-8 border-4 border-[#E8F0FE] border-t-[#1A73E8] rounded-full animate-spin mb-4"></div>
            </div>
          ) : currentData.length === 0 ? (
            <div className="bg-white rounded-2xl py-16 md:py-24 text-center border border-[#DADCE0] shadow-sm flex flex-col items-center mx-1">
              <span className="text-4xl mb-3 opacity-50">🏪</span>
              <h3 className="font-bold text-[#202124] text-lg md:text-xl mb-1">
                Tidak Ada Hasil
              </h3>
              <p className="text-[#5F6368] text-xs md:text-sm px-4">
                Coba sesuaikan kata kunci pencarian Anda.
              </p>
            </div>
          ) : (
            <>
              <div className="grid grid-cols-2 md:grid-cols-3 lg:grid-cols-4 gap-3 sm:gap-6">
                {currentData.map((bisnis, idx) => (
                  <div
                    key={bisnis.id}
                    onClick={() => openDetail(bisnis)}
                    className="bg-white rounded-2xl overflow-hidden shadow-sm border border-[#DADCE0] hover:shadow-md hover:-translate-y-1 transition-all duration-300 group flex flex-col cursor-pointer animate-in fade-in slide-in-from-bottom-4"
                    style={{ animationDelay: `${(idx % 12) * 50}ms` }}
                  >
                    <div className="h-28 sm:h-40 bg-[#F8F9FA] relative overflow-hidden border-b border-[#DADCE0] flex items-center justify-center shrink-0">
                      {bisnis.fotoUrl || bisnis.foto ? (
                        <img
                          src={bisnis.fotoUrl || bisnis.foto}
                          alt={bisnis.namaBisnis}
                          className="w-full h-full object-cover group-hover:scale-105 transition-transform duration-500"
                        />
                      ) : (
                        <div className="text-[#9AA0A6] flex flex-col items-center">
                          <svg
                            className="w-8 h-8 sm:w-10 sm:h-10 mb-1"
                            fill="none"
                            viewBox="0 0 24 24"
                            stroke="currentColor"
                          >
                            <path
                              strokeLinecap="round"
                              strokeLinejoin="round"
                              strokeWidth={1.5}
                              d="M19 21V5a2 2 0 00-2-2H7a2 2 0 00-2 2v16m14 0h2m-2 0h-5m-9 0H3m2 0h5M9 7h1m-1 4h1m4-4h1m-1 4h1m-5 10v-5a1 1 0 011-1h2a1 1 0 011 1v5m-4 0h4"
                            />
                          </svg>
                        </div>
                      )}
                      <div className="absolute top-2 right-2 sm:top-3 sm:right-3 bg-white/90 backdrop-blur text-[#1A73E8] text-[9px] sm:text-[10px] font-black px-2 py-1 rounded shadow-sm uppercase tracking-widest border border-blue-100">
                        {bisnis.kategori}
                      </div>
                    </div>

                    <div className="p-3 sm:p-5 flex-grow flex flex-col">
                      <h3
                        className="text-sm sm:text-base font-bold text-[#202124] mb-1 line-clamp-2 leading-tight"
                        title={bisnis.namaBisnis || bisnis.nama}
                      >
                        {bisnis.namaBisnis || bisnis.nama}
                      </h3>

                      <p className="text-[#5F6368] text-[10px] sm:text-xs mb-2 sm:mb-3 font-medium line-clamp-1">
                        By {bisnis.owner || bisnis.namaAlumni}
                      </p>

                      <p className="text-[#5F6368] text-[10px] sm:text-sm leading-relaxed line-clamp-2 sm:line-clamp-3 flex-grow mb-3 sm:mb-5">
                        {bisnis.deskripsi}
                      </p>

                      <div className="pt-3 border-t border-[#DADCE0] mt-auto">
                        <button className="w-full bg-[#F8F9FA] group-hover:bg-[#E8F0FE] border border-[#DADCE0] group-hover:border-[#1A73E8]/30 group-hover:text-[#1A73E8] text-[#5F6368] py-2 sm:py-2.5 rounded-lg font-bold text-[10px] sm:text-sm transition-colors text-center">
                          Lihat Detail
                        </button>
                      </div>
                    </div>
                  </div>
                ))}
              </div>

              {parsedItemsPerPage !== "Semua" && totalPages > 1 && (
                <div className="flex items-center justify-center gap-1 sm:gap-2 mt-10 sm:mt-16">
                  <button
                    onClick={() => setCurrentPage((p) => Math.max(1, p - 1))}
                    disabled={currentPage === 1}
                    className="p-2 sm:p-2.5 border border-[#DADCE0] rounded-lg bg-white text-[#5F6368] hover:bg-[#F8F9FA] disabled:opacity-50 transition-colors shadow-sm"
                  >
                    <svg
                      className="w-4 h-4 sm:w-5 sm:h-5"
                      fill="none"
                      viewBox="0 0 24 24"
                      stroke="currentColor"
                    >
                      <path
                        strokeLinecap="round"
                        strokeLinejoin="round"
                        strokeWidth={2.5}
                        d="M15 19l-7-7 7-7"
                      />
                    </svg>
                  </button>

                  <div className="flex items-center gap-1">
                    {Array.from({ length: totalPages }).map((_, i) => (
                      <button
                        key={i}
                        onClick={() => setCurrentPage(i + 1)}
                        className={`w-8 h-8 sm:w-10 sm:h-10 flex items-center justify-center rounded-lg text-xs sm:text-sm font-bold transition-colors shadow-sm ${currentPage === i + 1 ? "bg-[#1A73E8] text-white border border-[#1A73E8]" : "border border-[#DADCE0] bg-white text-[#5F6368] hover:bg-[#F8F9FA]"}`}
                      >
                        {i + 1}
                      </button>
                    ))}
                  </div>

                  <button
                    onClick={() =>
                      setCurrentPage((p) => Math.min(totalPages, p + 1))
                    }
                    disabled={currentPage === totalPages}
                    className="p-2 sm:p-2.5 border border-[#DADCE0] rounded-lg bg-white text-[#5F6368] hover:bg-[#F8F9FA] disabled:opacity-50 transition-colors shadow-sm"
                  >
                    <svg
                      className="w-4 h-4 sm:w-5 sm:h-5"
                      fill="none"
                      viewBox="0 0 24 24"
                      stroke="currentColor"
                    >
                      <path
                        strokeLinecap="round"
                        strokeLinejoin="round"
                        strokeWidth={2.5}
                        d="M9 5l7 7-7-7"
                      />
                    </svg>
                  </button>
                </div>
              )}
            </>
          )}
        </section>
      </main>
      <FooterPublic />
    </div>
  );
}

"use client";

import { useEffect, useState, useRef } from "react";
import { db } from "@/lib/firebase";
import {
  doc,
  getDoc,
  collection,
  getDocs,
  query,
  orderBy,
  limit,
} from "firebase/firestore";
import Link from "next/link";
import FooterPublic from "@/components/layout/FooterPublic";

export default function LandingPage() {
  // --- STATE DATA FIREBASE ---
  const [cms, setCms] = useState({
    heroTitle: "Sinergi Alumni untuk",
    heroHighlight: "KEMAJUAN NEGERI",
    heroDesc:
      "Dewan Pimpinan Wilayah Ikatan Keluarga Alumni Universitas Islam Indonesia (DPW IKA UII) Daerah Istimewa Yogyakarta. Hadir sebagai wadah kolaborasi, inovasi, dan kontribusi nyata bagi almamater dan masyarakat luas.",
    heroBgUrl:
      "https://images.unsplash.com/photo-1596404748151-51f7d4323af2?q=80&w=2000&auto=format&fit=crop",
    profilImgUrl:
      "https://images.unsplash.com/photo-1523580494863-6f3031224c94?q=80&w=800&auto=format&fit=crop",
  });

  const [beritaList, setBeritaList] = useState<any[]>([]);
  const [agendaList, setAgendaList] = useState<any[]>([]);
  const [pengurusList, setPengurusList] = useState<any[]>([]);
  const [galeriList, setGaleriList] = useState<any[]>([]);
  const [feedbackList, setFeedbackList] = useState<any[]>([]); // 🔥 STATE BARU UNTUK ULASAN
  const [isLoading, setIsLoading] = useState(true);

  // --- STATE & REF UNTUK SLIDER ULASAN 🔥 ---
  const feedbackCarouselRef = useRef<HTMLDivElement>(null);
  const [isFeedbackHovered, setIsFeedbackHovered] = useState(false);

  // --- FUNGSI YOUTUBE EXTRACTOR ---
  const getYouTubeEmbedUrl = (url: string) => {
    if (!url) return null;
    const regExp =
      /^.*(youtu.be\/|v\/|u\/\w\/|embed\/|watch\?v=|&v=)([^#&?]*).*/;
    const match = url.match(regExp);
    return match && match[2].length === 11
      ? `https://www.youtube.com/embed/${match[2]}?autoplay=0&rel=0`
      : null;
  };
  const ytEmbedUrl = getYouTubeEmbedUrl(cms.profilImgUrl);

  // --- LOGIKA AUTO-SLIDE ULASAN (4 DETIK & PAUSE ON HOVER) 🔥 ---
  useEffect(() => {
    if (feedbackList.length <= 1 || isFeedbackHovered) return;

    const interval = setInterval(() => {
      if (feedbackCarouselRef.current) {
        const { scrollLeft, scrollWidth, clientWidth } =
          feedbackCarouselRef.current;

        if (Math.ceil(scrollLeft + clientWidth) >= scrollWidth - 10) {
          feedbackCarouselRef.current.scrollTo({ left: 0, behavior: "smooth" });
        } else {
          // Geser sejauh 1 card (sekitar 340px)
          feedbackCarouselRef.current.scrollBy({
            left: 340,
            behavior: "smooth",
          });
        }
      }
    }, 4000);

    return () => clearInterval(interval);
  }, [feedbackList.length, isFeedbackHovered]);

  // --- FETCH DATA FIREBASE (DENGAN SESSION STORAGE CACHE) 🔥 ---
  useEffect(() => {
    const fetchAllData = async () => {
      // 1. CEK CACHE DI SESSION STORAGE DULU
      if (typeof window !== "undefined") {
        const cachedData = sessionStorage.getItem("ika_public_home_cache");
        if (cachedData) {
          try {
            const parsedData = JSON.parse(cachedData);
            setCms(parsedData.cms);
            setBeritaList(parsedData.beritaList);
            setAgendaList(parsedData.agendaList);
            setPengurusList(parsedData.pengurusList);
            setGaleriList(parsedData.galeriList);
            setFeedbackList(parsedData.feedbackList || []); // Ambil cache ulasan
            setIsLoading(false);
            return; // EXIT FUNGSI, JANGAN FETCH KE FIREBASE LAGI!
          } catch (e) {
            console.log("Cache corrupted, re-fetching...");
          }
        }
      }

      // 2. JIKA TIDAK ADA CACHE, BARU FETCH KE FIREBASE
      try {
        let finalCms = { ...cms };
        const docSnap = await getDoc(doc(db, "settings", "landing_page"));
        if (docSnap.exists()) {
          finalCms = { ...finalCms, ...docSnap.data() };
          setCms(finalCms);
        }

        const qBerita = query(
          collection(db, "berita"),
          orderBy("createdAt", "desc"),
          limit(6),
        );
        const snapBerita = await getDocs(qBerita);
        const finalBeritaList = snapBerita.docs.map((d) => ({
          id: d.id,
          ...d.data(),
        }));
        setBeritaList(finalBeritaList);

        const qAgenda = query(
          collection(db, "agenda"),
          orderBy("createdAt", "desc"),
          limit(6),
        );
        const snapAgenda = await getDocs(qAgenda);
        const finalAgendaList = snapAgenda.docs.map((d) => ({
          id: d.id,
          ...d.data(),
        }));
        setAgendaList(finalAgendaList);

        const snapPengurus = await getDocs(collection(db, "pengurus"));
        const allPengurus = snapPengurus.docs.map((d) => ({
          id: d.id,
          ...d.data(),
        }));

        let pengurusBeranda = allPengurus.filter(
          (p: any) => p.isTampilBeranda === true,
        );

        if (pengurusBeranda.length === 0) {
          const getRank = (jabatan: string, bidang: string) => {
            const j = (jabatan || "").toLowerCase();
            const b = (bidang || "").toLowerCase();

            if (j.includes("ketua umum")) return 100;
            if (j.includes("sekretaris umum") || j.includes("sekum")) return 90;
            if (j.includes("bendahara umum") || j.includes("bendum")) return 80;
            if (
              j.includes("ketua") &&
              (b.includes("pembina") ||
                b.includes("pakar") ||
                b.includes("penasihat") ||
                b.includes("penasehat"))
            )
              return 70;
            if (j.includes("wakil ketua")) return 60;
            if (j.includes("sekretaris") && !j.includes("bidang")) return 50;
            if (j.includes("bendahara") && !j.includes("bidang")) return 40;
            if (b.includes("harian") && !j.includes("anggota")) return 30;
            return 0;
          };

          pengurusBeranda = allPengurus
            .sort(
              (a: any, b: any) =>
                getRank(b.jabatan, b.bidang) - getRank(a.jabatan, a.bidang),
            )
            .filter((p: any) => getRank(p.jabatan, p.bidang) > 0)
            .slice(0, 3);
        }

        setPengurusList(pengurusBeranda);

        const qGaleri = query(
          collection(db, "galeri"),
          orderBy("createdAt", "desc"),
          limit(6),
        );
        const snapGaleri = await getDocs(qGaleri);
        const finalGaleriList = snapGaleri.docs.map((d) => ({
          id: d.id,
          ...d.data(),
        }));
        setGaleriList(finalGaleriList);

        // 🔥 FETCH ULASAN PUBLIK 🔥
        const snapFeedbacks = await getDocs(collection(db, "feedbacks"));
        const finalFeedbackList = snapFeedbacks.docs
          .map((d) => ({ id: d.id, ...d.data() }))
          .filter((f: any) => f.status === "Tayang") // Hanya ambil yang Tayang
          .sort((a: any, b: any) => {
            const dateA = a.createdAt?.toMillis ? a.createdAt.toMillis() : 0;
            const dateB = b.createdAt?.toMillis ? b.createdAt.toMillis() : 0;
            return dateB - dateA;
          });
        setFeedbackList(finalFeedbackList);

        // 3. SIMPAN SEMUA DATA KE SESSION CACHE
        if (typeof window !== "undefined") {
          try {
            const getCircularReplacer = () => {
              const seen = new WeakSet();
              return (key: string, value: any) => {
                if (typeof value === "object" && value !== null) {
                  // Handle Firestore references (avoid circular structure)
                  if (value.firestore || value.converter) return undefined;
                  // Handle Firestore timestamps
                  if (typeof value.toMillis === "function") return value.toMillis();
                  
                  if (seen.has(value)) {
                    return;
                  }
                  seen.add(value);
                }
                return value;
              };
            };

            sessionStorage.setItem(
              "ika_public_home_cache",
              JSON.stringify(
                {
                  cms: finalCms,
                  beritaList: finalBeritaList,
                  agendaList: finalAgendaList,
                  pengurusList: pengurusBeranda,
                  galeriList: finalGaleriList,
                  feedbackList: finalFeedbackList,
                },
                getCircularReplacer()
              )
            );
          } catch (cacheError) {
            console.warn("Gagal menyimpan cache home:", cacheError);
          }
        }
      } catch (error) {
        console.error("Gagal mengambil data:", error);
      } finally {
        setIsLoading(false);
      }
    };
    fetchAllData();
  }, []); // Eslint-warning untuk array kosong diabaikan karena ini murni fetch data sekali.

  if (isLoading) {
    return (
      <div className="min-h-screen flex flex-col items-center justify-center bg-slate-50">
        <div className="w-16 h-16 border-4 border-slate-200 border-t-blue-900 rounded-full animate-spin mb-4 shadow-md"></div>
        <p className="text-blue-950 font-bold tracking-widest uppercase text-sm animate-pulse">
          Memuat Sistem Informasi...
        </p>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-slate-50 font-sans selection:bg-yellow-400 selection:text-blue-950">
      {/* 1. HERO SECTION (PREMIUM SPLIT LAYOUT) */}
      <section
        id="beranda"
        className="relative pt-32 pb-20 lg:pt-40 lg:pb-32 flex items-center min-h-[90vh] md:min-h-screen overflow-hidden"
      >
        {/* --- Background & Gradient Overlay --- */}
        <div className="absolute inset-0 z-0">
          <img
            src={cms.heroBgUrl}
            alt="Hero Background"
            className="w-full h-full object-cover object-center scale-105 animate-[pulse_20s_ease-in-out_infinite]"
          />
          {/* Gradasi elegan: Gelap pekat di kiri untuk teks, memudar di kanan */}
          <div className="absolute inset-0 bg-gradient-to-r from-[#0a152d] via-[#0a152d]/95 to-[#0a152d]/40"></div>
          {/* Tambahan vignette atas bawah biar makin sinematik */}
          <div className="absolute inset-0 bg-gradient-to-b from-[#0a152d]/80 via-transparent to-[#0a152d]"></div>
        </div>

        <div className="relative z-10 w-full max-w-7xl mx-auto px-5 sm:px-6 lg:px-8 grid grid-cols-1 lg:grid-cols-12 gap-12 lg:gap-8 items-center mt-10">
          {/* --- LEFT COLUMN: KONTEN UTAMA --- */}
          <div className="lg:col-span-7 flex flex-col items-center lg:items-start text-center lg:text-left animate-in fade-in slide-in-from-bottom-8 duration-700">
            {/* Badge Premium */}
            <div className="inline-flex items-center gap-3 border border-yellow-400/30 bg-yellow-400/10 backdrop-blur-md text-yellow-400 font-bold px-5 py-2.5 rounded-full text-xs md:text-sm mb-8 uppercase tracking-[0.2em] shadow-lg">
              <span className="relative flex h-2 w-2">
                <span className="animate-ping absolute inline-flex h-full w-full rounded-full bg-yellow-400 opacity-75"></span>
                <span className="relative inline-flex rounded-full h-2 w-2 bg-yellow-500"></span>
              </span>
              Official Portal IKA UII DIY
            </div>

            {/* Title dengan efek Typografi Modern */}
            <h1 className="text-4xl sm:text-5xl md:text-6xl lg:text-[72px] font-black text-white mb-6 leading-[1.1] md:leading-[1.1] tracking-tight drop-shadow-lg">
              {cms.heroTitle} <br />
              <span className="text-transparent bg-clip-text bg-gradient-to-r from-yellow-400 to-yellow-600">
                {cms.heroHighlight}
              </span>
            </h1>

            <p className="text-base sm:text-lg md:text-xl text-slate-300 mb-10 leading-relaxed max-w-2xl font-medium drop-shadow-md">
              {cms.heroDesc}
            </p>

            {/* Buttons Group */}
            <div className="flex flex-col sm:flex-row justify-center lg:justify-start gap-4 w-full sm:w-auto mb-12">
              <a
                href="#profil"
                className="bg-gradient-to-r from-yellow-500 to-yellow-400 hover:from-yellow-400 hover:to-yellow-300 text-blue-950 px-8 py-4 rounded-full font-extrabold transition-all duration-300 flex items-center justify-center gap-3 text-base md:text-lg shadow-[0_4px_20px_rgba(234,179,8,0.3)] hover:shadow-[0_4px_25px_rgba(234,179,8,0.5)] transform hover:-translate-y-1"
              >
                Jelajahi Profil
                <svg
                  className="w-5 h-5"
                  fill="none"
                  stroke="currentColor"
                  viewBox="0 0 24 24"
                >
                  <path
                    strokeLinecap="round"
                    strokeLinejoin="round"
                    strokeWidth="2.5"
                    d="M17 8l4 4m0 0l-4 4m4-4H3"
                  ></path>
                </svg>
              </a>
              <a
                href="#agenda"
                className="bg-white/5 backdrop-blur-sm border border-white/20 hover:bg-white/10 text-white px-8 py-4 rounded-full font-bold transition-all duration-300 flex items-center justify-center gap-3 text-base md:text-lg shadow-lg hover:shadow-xl transform hover:-translate-y-1"
              >
                Lihat Agenda
              </a>
            </div>

            {/* 🔥 SOCIAL PROOF (INISIAL ELEGAN) 🔥 */}
            <div className="flex items-center gap-4 pt-6 border-t border-white/10 w-full lg:w-fit justify-center lg:justify-start">
              <div className="flex -space-x-3">
                {/* Avatar 1 */}
                <div className="w-12 h-12 rounded-full border-[3px] border-[#0a152d] bg-gradient-to-br from-blue-400 to-blue-600 text-white flex items-center justify-center text-sm font-bold relative z-30 shadow-sm">
                  AR
                </div>
                {/* Avatar 2 */}
                <div className="w-12 h-12 rounded-full border-[3px] border-[#0a152d] bg-gradient-to-br from-emerald-400 to-emerald-600 text-white flex items-center justify-center text-sm font-bold relative z-20 shadow-sm">
                  MD
                </div>
                {/* Avatar 3 */}
                <div className="w-12 h-12 rounded-full border-[3px] border-[#0a152d] bg-gradient-to-br from-amber-400 to-amber-600 text-white flex items-center justify-center text-sm font-bold relative z-10 shadow-sm">
                  ST
                </div>
                {/* Badge +5k */}
                <div className="w-12 h-12 rounded-full border-[3px] border-[#0a152d] bg-[#1d4ed8] text-white flex items-center justify-center text-sm font-black relative z-0 shadow-sm">
                  +5k
                </div>
              </div>
              <div className="text-left flex flex-col justify-center">
                <div className="flex items-center gap-1 text-[#fbbf24] mb-1">
                  {[...Array(5)].map((_, i) => (
                    <svg
                      key={i}
                      className="w-4 h-4"
                      fill="currentColor"
                      viewBox="0 0 20 20"
                    >
                      <path d="M9.049 2.927c.3-.921 1.603-.921 1.902 0l1.07 3.292a1 1 0 00.95.69h3.462c.969 0 1.371 1.24.588 1.81l-2.8 2.034a1 1 0 00-.364 1.118l1.07 3.292c.3.921-.755 1.688-1.54 1.118l-2.8-2.034a1 1 0 00-1.175 0l-2.8 2.034c-.784.57-1.838-.197-1.539-1.118l1.07-3.292a1 1 0 00-.364-1.118L2.98 8.72c-.783-.57-.38-1.81.588-1.81h3.461a1 1 0 00.951-.69l1.07-3.292z" />
                    </svg>
                  ))}
                </div>
                <p className="text-[13px] sm:text-sm text-slate-300 font-medium">
                  Telah terhubung dalam jaringan alumni DIY.
                </p>
              </div>
            </div>
          </div>

          {/* --- RIGHT COLUMN: FLOATING GLASS CARD --- */}
          <div className="lg:col-span-5 hidden lg:flex justify-end items-center relative animate-in fade-in slide-in-from-right-8 duration-700 delay-300">
            {/* Glow Effect di balik Card */}
            <div className="absolute top-1/2 left-1/2 transform -translate-x-1/2 -translate-y-1/2 w-72 h-72 bg-blue-600/30 blur-[80px] rounded-full pointer-events-none"></div>

            <div className="bg-white/10 backdrop-blur-xl border border-white/20 rounded-[2rem] p-8 shadow-[0_8px_32px_rgba(0,0,0,0.4)] w-full max-w-sm relative z-10 transform hover:scale-105 transition-transform duration-500">
