// --- TYPE DEFINITIONS ---
interface RolePosition {
  id: string;
  nama: string;
  kuota: number;
  linkWa: string;
  deskripsi?: string;
}

interface DivisionGroup {
  id: string;
  title: string;
  roles: RolePosition[];
}

interface EventRecruitment {
  id: string;
  title: string;
  requirements: string;
  isActive: boolean;
  linkGrupBesar: string;
  linkSertifikat?: string;
  order?: number;
  groups: DivisionGroup[];
  allowedTipe?: string[];
}

interface CrewMember {
  id: string;
  eventId: string;
  roleId: string;
  divisiId?: string;
  nama: string;
  jenisKelamin?: string;
  tempatLahir?: string;
  tanggalLahir?: string;
  email: string;
  whatsapp: string;
  instagram?: string;
  riwayatPenyakit?: string;
  ukuranJersey?: string;
  fotoIdCard?: string;
  tipe: string;
  status: "pending" | "accepted" | "rejected";
  waktuDaftar: string;
  fakultas?: string;
  angkatan?: string | number;
  instansi?: string;
  jabatan?: string;
  domisili?: string;
  motivasi?: string;
  pengalaman?: string;
  alasanDivisi?: string;
  bersediaPindahDivisi?: string;
  kendaraan?: string;
  bersediaPelatihan?: string;
  emailStatus?: "sent" | "failed" | null;
  certEmailStatus?: "sent" | "failed" | null;
  emailError?: string;
  sourceDb: "crew_volunteers" | "oprec_pelamar";
  alasanTolak?: string;
}

export default function CrewManagementPage() {
  const [activeTab, setActiveTab] = useState<
    "pengaturan" | "pendaftar" | "timInti" | "ditolak"
  >("pengaturan");
  const [isLoading, setIsLoading] = useState(true);
  const [isSaving, setIsSaving] = useState(false);
  const [popup, setPopup] = useState<{
    type: "success" | "error";
    text: string;
  } | null>(null);

  // Data State
  const [events, setEvents] = useState<EventRecruitment[]>([]);
  const [pendaftarNew, setPendaftarNew] = useState<CrewMember[]>([]);
  const [pendaftarOld, setPendaftarOld] = useState<CrewMember[]>([]);
  const initialLoadDone = useRef(false);

  // Menggabungkan data lama dan baru
  const pendaftar = [...pendaftarNew, ...pendaftarOld].sort(
    (a, b) =>
      new Date(b.waktuDaftar).getTime() - new Date(a.waktuDaftar).getTime(),
  );

  // UI State
  const [selectedCrew, setSelectedCrew] = useState<CrewMember | null>(null);
  const [isDetailOpen, setIsDetailOpen] = useState(false);
  const [newAssignedRoleId, setNewAssignedRoleId] = useState("");
  const [expandedEvents, setExpandedEvents] = useState<Record<string, boolean>>(
    {},
  );
  const [expandedGroups, setExpandedGroups] = useState<Record<string, boolean>>(
    {},
  );

  const [filterEvent, setFilterEvent] = useState<string>("all");
  const [filterTipe, setFilterTipe] = useState<string>("all");
  const [filterGender, setFilterGender] = useState<string>("all");
  const [filterDivisi, setFilterDivisi] = useState<string>("all");
  const [itemsPerPage, setItemsPerPage] = useState<number>(10);
  const [currentPage, setCurrentPage] = useState<number>(1);
  const [selectedPending, setSelectedPending] = useState<string[]>([]);
  const [selectedAccepted, setSelectedAccepted] = useState<string[]>([]);
  const [selectedRejected, setSelectedRejected] = useState<string[]>([]);

  // STATE UNTUK MODE EDIT DATA
  const [isEditingData, setIsEditingData] = useState(false);
  const [editFormData, setEditFormData] = useState<any>({});

  // STATE UNTUK MODAL PENOLAKAN
  const [rejectModalOpen, setRejectModalOpen] = useState(false);
  const [pendingRejectAction, setPendingRejectAction] = useState<{type: "single" | "mass", id?: string, ids?: string[]}|null>(null);
  const [rejectReasonInput, setRejectReasonInput] = useState("");

  // STATE UNTUK MODAL KONFIRMASI GENERIC
  const [genericConfirm, setGenericConfirm] = useState<{
    isOpen: boolean;
    title: string;
    message: string;
    onConfirm: () => void;
  }>({ isOpen: false, title: "", message: "", onConfirm: () => {} });

  // Email State
  const [isSendingMail, setIsSendingMail] = useState(false);
  const [emailProgress, setEmailProgress] = useState<{
    total: number;
    sent: number;
    failed: number;
    isSending: boolean;
    type: "welcome" | "cert";
  } | null>(null);

  useEffect(() => {
    // 1. AMBIL SETTING OPREC
    const unsubSettings = onSnapshot(collection(db, "oprec_master"), (snap) => {
      const loadedEvents = snap.docs
        .map(
          (doc) =>
            ({ id: doc.id, order: 0, ...doc.data() }) as EventRecruitment,
        )
        .sort((a, b) => (a.order || 0) - (b.order || 0));

      setEvents(loadedEvents);

      if (!initialLoadDone.current) {
        initialLoadDone.current = true;
      }
    });

    // 2. AMBIL DATA PELAMAR BARU (oprec_pelamar)
    const qNew = query(
      collection(db, "oprec_pelamar"),
      orderBy("waktuDaftar", "desc"),
    );
    const unsubNew = onSnapshot(qNew, (snap) => {
      const data = snap.docs.map(
        (d) =>
          ({ id: d.id, sourceDb: "oprec_pelamar", ...d.data() }) as CrewMember,
      );
      setPendaftarNew(data);
    });

    // 3. AMBIL DATA PELAMAR LAMA (crew_volunteers)
    const qOld = query(
      collection(db, "crew_volunteers"),
      orderBy("waktuDaftar", "desc"),
    );
    const unsubOld = onSnapshot(qOld, (snap) => {
      const data = snap.docs.map(
        (d) =>
          ({
            id: d.id,
            sourceDb: "crew_volunteers",
            ...d.data(),
          }) as CrewMember,
      );
      setPendaftarOld(data);
      setIsLoading(false);
    });

    return () => {
      unsubSettings();
      unsubNew();
      unsubOld();
    };
  }, []);

  // Sync selectedCrew ketika data berubah agar modal update realtime
  useEffect(() => {
    if (selectedCrew && !isEditingData) {
      const updatedSelected = pendaftar.find((c) => c.id === selectedCrew.id);
      if (updatedSelected) setSelectedCrew(updatedSelected);
    }
  }, [pendaftar, selectedCrew, isEditingData]);

  const showNotif = (type: "success" | "error", text: string) => {
    setPopup({ type, text });
    setTimeout(() => setPopup(null), 4000);
  };

  const getRoleFilledCount = (roleId: string) => {
    return pendaftar.filter(
      (c) =>
        c.status === "accepted" &&
        (c.roleId === roleId || c.divisiId === roleId),
    ).length;
  };

  // ========================================================
  // LOGIKA PENGATURAN EVENT & REORDER
  // ========================================================
  const toggleEventCard = (id: string) =>
    setExpandedEvents((prev) => ({ ...prev, [id]: !prev[id] }));
  const toggleGroupCard = (id: string) =>
    setExpandedGroups((prev) => ({ ...prev, [id]: !prev[id] }));

  const moveEvent = (index: number, direction: "up" | "down") => {
    if (direction === "up" && index === 0) return;
    if (direction === "down" && index === events.length - 1) return;
    const newEvents = [...events];
    const targetIndex = direction === "up" ? index - 1 : index + 1;
    [newEvents[index], newEvents[targetIndex]] = [
      newEvents[targetIndex],
      newEvents[index],
    ];
    setEvents(newEvents);
  };

  const moveGroup = (
    eventId: string,
    groupIndex: number,
    direction: "up" | "down",
  ) => {
    setEvents(
      events.map((ev) => {
        if (ev.id !== eventId) return ev;
        const newGroups = [...(ev.groups || [])];
        if (direction === "up" && groupIndex === 0) return ev;
        if (direction === "down" && groupIndex === newGroups.length - 1)
          return ev;
        const targetIndex =
          direction === "up" ? groupIndex - 1 : groupIndex + 1;
        [newGroups[groupIndex], newGroups[targetIndex]] = [
          newGroups[targetIndex],
          newGroups[groupIndex],
        ];
        return { ...ev, groups: newGroups };
      }),
    );
  };

  const moveRole = (
    eventId: string,
    groupId: string,
    roleIndex: number,
    direction: "up" | "down",
  ) => {
    setEvents(
      events.map((ev) => {
        if (ev.id !== eventId) return ev;
        const newGroups = (ev.groups || []).map((g) => {
          if (g.id !== groupId) return g;
          const newRoles = [...(g.roles || [])];
          if (direction === "up" && roleIndex === 0) return g;
          if (direction === "down" && roleIndex === newRoles.length - 1)
            return g;
          const targetIndex =
            direction === "up" ? roleIndex - 1 : roleIndex + 1;
          [newRoles[roleIndex], newRoles[targetIndex]] = [
            newRoles[targetIndex],
            newRoles[roleIndex],
          ];
          return { ...g, roles: newRoles };
        });
        return { ...ev, groups: newGroups };
      }),
    );
  };

  const handleAddEvent = () => {
    const newId = Date.now().toString();
    setEvents([
      ...events,
      {
        id: newId,
        title: "",
        requirements: "",
        isActive: true,
        linkGrupBesar: "",
        linkSertifikat: "",
        groups: [],
        order: events.length,
        allowedTipe: ["mahasiswa", "alumni", "umum"],
      },
    ]);
    setExpandedEvents((prev) => ({ ...prev, [newId]: true }));
  };

  const handleRemoveEvent = async (id: string) => {
    if (!confirm("Hapus event kepanitiaan ini secara permanen?")) return;
    try {
      await deleteDoc(doc(db, "oprec_master", id));
      setEvents(events.filter((e) => e.id !== id));
      showNotif("success", "Event berhasil dihapus.");
    } catch (e) {
      showNotif("error", "Gagal menghapus event.");
    }
  };

  const handleChangeEvent = (id: string, field: string, value: any) => {
    setEvents(events.map((e) => (e.id === id ? { ...e, [field]: value } : e)));
  };

  const handleAddGroup = (eventId: string) => {
    const newId = Date.now().toString();
    setEvents(
      events.map((e) =>
        e.id === eventId
          ? {
              ...e,
              groups: [
                ...(e.groups || []),
                { id: newId, title: "", roles: [] },
              ],
            }
          : e,
      ),
    );
    setExpandedGroups((prev) => ({ ...prev, [newId]: true }));
  };

  const handleChangeGroup = (
    eventId: string,
    groupId: string,
    newTitle: string,
  ) => {
    setEvents(
      events.map((e) =>
        e.id === eventId
          ? {
              ...e,
              groups: (e.groups || []).map((g) =>
                g.id === groupId ? { ...g, title: newTitle } : g,
              ),
            }
          : e,
      ),
    );
  };

  const handleRemoveGroup = async (eventId: string, groupId: string) => {
    if (!confirm("Hapus kelompok divisi ini?")) return;
    setEvents(
      events.map((e) =>
        e.id === eventId
          ? { ...e, groups: (e.groups || []).filter((g) => g.id !== groupId) }
          : e,
      ),
    );
  };

  const handleAddRole = (eventId: string, groupId: string) => {
    setEvents(
      events.map((e) =>
        e.id === eventId
          ? {
              ...e,
              groups: (e.groups || []).map((g) =>
                g.id === groupId
                  ? {
                      ...g,
                      roles: [
                        ...(g.roles || []),
                        {
                          id: Date.now().toString(),
                          nama: "",
                          kuota: 5,
                          linkWa: "",
                          deskripsi: "",
                        },
                      ],
                    }
                  : g,
              ),
            }
          : e,
      ),
    );
  };

  const handleChangeRole = (
    eventId: string,
    groupId: string,
    roleId: string,
    field: string,
    value: any,
  ) => {
    setEvents(
      events.map((e) =>
        e.id === eventId
          ? {
              ...e,
              groups: (e.groups || []).map((g) =>
                g.id === groupId
                  ? {
                      ...g,
                      roles: (g.roles || []).map((r) =>
                        r.id === roleId ? { ...r, [field]: value } : r,
                      ),
                    }
                  : g,
              ),
            }
          : e,
      ),
    );
  };

  const handleRemoveRole = async (
    eventId: string,
    groupId: string,
    roleId: string,
  ) => {
    setEvents(
      events.map((e) =>
        e.id === eventId
          ? {
              ...e,
              groups: (e.groups || []).map((g) =>
                g.id === groupId
                  ? {
                      ...g,
                      roles: (g.roles || []).filter((r) => r.id !== roleId),
                    }
                  : g,
              ),
            }
          : e,
      ),
    );
  };

  const saveSettings = async () => {
    setIsSaving(true);
    try {
      const batch = writeBatch(db);
      events.forEach((ev, index) => {
        const docRef = doc(db, "oprec_master", ev.id);
        batch.set(docRef, { ...ev, order: index });
      });
      await batch.commit();
      showNotif("success", "Pengaturan kepanitiaan berhasil disimpan.");
    } catch (error) {
      showNotif("error", "Gagal menyimpan pengaturan.");
    } finally {
      setIsSaving(false);
    }
  };

  // ========================================================
  // LOGIKA REVIEW & EDIT DATA PELAMAR
  // ========================================================
  const getRoleInfo = (eventId: string, targetRoleId: string) => {
    const parentEvent = events.find((e) => e.id === eventId);
    let roleName = "Data Lama / Tidak Spesifik";
    let roleLink = "";
    (parentEvent?.groups || []).forEach((g) => {
      const r = (g.roles || []).find((ro) => ro.id === targetRoleId);
      if (r) {
        roleName = r.nama;
        roleLink = r.linkWa;
      }
    });
    return { parentEvent, roleName, roleLink };
  };

  const openDetail = (crew: CrewMember) => {
    setSelectedCrew(crew);
    setNewAssignedRoleId(crew.roleId || crew.divisiId || "");
    setIsEditingData(false);
    setEditFormData(crew);
    setIsDetailOpen(true);
  };

  const findEventIdByRoleId = (roleId: string, fallbackEventId: string) => {
    if (!roleId) return fallbackEventId;
    for (const e of events) {
      for (const g of e.groups || []) {
        if ((g.roles || []).some((r) => r.id === roleId)) return e.id;
      }
    }
    return fallbackEventId;
  };

  const handleDecision = async (
    status: "accepted" | "rejected" | "pending",
  ) => {
    if (!selectedCrew) return;
    const actionText =
      status === "accepted"
        ? "TERIMA"
        : status === "rejected"
          ? "TOLAK"
          : "PULIHKAN";

    if (status === "rejected") {
      setPendingRejectAction({ type: "single", id: selectedCrew.id });
      setRejectReasonInput("");
      setRejectModalOpen(true);
      return;
    }

    setGenericConfirm({
      isOpen: true,
      title: "Konfirmasi Tindakan",
      message: `Konfirmasi: ${actionText} pelamar ini?`,
      onConfirm: async () => {
        setGenericConfirm({ ...genericConfirm, isOpen: false });
        const updatedEventId = findEventIdByRoleId(
          newAssignedRoleId,
          selectedCrew.eventId,
        );

        try {
          const updateData: any = {
            status,
            roleId: newAssignedRoleId,
            eventId: updatedEventId,
          };
          if (status === "accepted") {
            updateData.emailStatus = "";
          }
          await setDoc(
            doc(db, selectedCrew.sourceDb, selectedCrew.id),
            updateData,
            { merge: true },
          );
          showNotif("success", "Status dan Posisi berhasil diperbarui.");
          setIsDetailOpen(false);

          setSelectedPending(
            selectedPending.filter((id) => id !== selectedCrew.id),
          );
          setSelectedRejected(
            selectedRejected.filter((id) => id !== selectedCrew.id),
          );
        } catch (e) {
          showNotif("error", "Gagal memperbarui status.");
        }
      },
    });
  };

  const handleUpdateRoleOnly = async () => {
    if (!selectedCrew) return;
    const updatedEventId = findEventIdByRoleId(
      newAssignedRoleId,
      selectedCrew.eventId,
    );
    try {
      await setDoc(
        doc(db, selectedCrew.sourceDb, selectedCrew.id),
        { roleId: newAssignedRoleId, eventId: updatedEventId },
        { merge: true },
      );
      showNotif("success", "Posisi divisi berhasil diperbarui.");
      setIsDetailOpen(false);
    } catch (e) {
      showNotif("error", "Gagal memperbarui posisi.");
    }
  };

  const saveEditedData = async () => {
    if (!selectedCrew) return;
    try {
      await setDoc(
        doc(db, selectedCrew.sourceDb, selectedCrew.id),
        editFormData,
        { merge: true },
      );
      showNotif("success", "Data pelamar berhasil diperbarui!");
      setSelectedCrew({ ...selectedCrew, ...editFormData });
      setIsEditingData(false);
    } catch (e) {
      showNotif("error", "Gagal menyimpan perubahan data.");
    }
  };

  const handleEditChange = (
    e: React.ChangeEvent<
      HTMLInputElement | HTMLTextAreaElement | HTMLSelectElement
    >,
  ) => {
    setEditFormData({ ...editFormData, [e.target.name]: e.target.value });
  };

  // ========================================================
  // MASS ACTIONS & EXPORT
  // ========================================================
  const handleMassUpdateStatus = async (
    ids: string[],
    newStatus: "accepted" | "rejected" | "pending",
  ) => {
    const actionText =
      newStatus === "accepted"
        ? "Diterima"
        : newStatus === "rejected"
          ? "Ditolak"
          : "Dipulihkan (Pending)";

    if (newStatus === "rejected") {
      setPendingRejectAction({ type: "mass", ids });
      setRejectReasonInput("");
      setRejectModalOpen(true);
      return;
    }

    setGenericConfirm({
      isOpen: true,
      title: "Pembaruan Status Massal",
      message: `Ubah status ${ids.length} pelamar menjadi ${actionText}?`,
      onConfirm: async () => {
        setGenericConfirm({ ...genericConfirm, isOpen: false });
        try {
          const batch = writeBatch(db);
          ids.forEach((id) => {
            const crew = pendaftar.find((c) => c.id === id);
            if (crew) {
              const updateData: any = { status: newStatus };
              if (newStatus === "accepted") {
                updateData.emailStatus = "";
              }
              batch.update(doc(db, crew.sourceDb, id), updateData);
            }
          });
          await batch.commit();
          setSelectedPending([]);
          setSelectedRejected([]);
          showNotif("success", "Status massal diperbarui.");
        } catch (err) {
          showNotif("error", "Gagal memproses pembaruan massal.");
        }
      },
    });
  };

  const executeReject = async () => {
    if (!pendingRejectAction) return;
    const finalReason = rejectReasonInput.trim() || "Maaf, kuota telah terpenuhi atau kualifikasi belum sesuai.";
    
    try {
      if (pendingRejectAction.type === "single" && pendingRejectAction.id) {
        const crew = pendaftar.find((c) => c.id === pendingRejectAction.id);
        if (!crew) return;
        
        const updatedEventId = findEventIdByRoleId(
          newAssignedRoleId,
          crew.eventId,
        );
        
        await setDoc(
          doc(db, crew.sourceDb, crew.id),
          { 
            status: "rejected", 
            roleId: newAssignedRoleId, 
            eventId: updatedEventId,
            alasanTolak: finalReason,
            emailStatus: ""
          },
          { merge: true },
        );
        showNotif("success", "Pelamar ditolak dan alasan disimpan.");
        setIsDetailOpen(false);
        setSelectedPending(selectedPending.filter((id) => id !== crew.id));
        setSelectedRejected(selectedRejected.filter((id) => id !== crew.id));
      } else if (pendingRejectAction.type === "mass" && pendingRejectAction.ids) {
        const batch = writeBatch(db);
        pendingRejectAction.ids.forEach((id) => {
          const crew = pendaftar.find((c) => c.id === id);
          if (crew) {
            batch.update(doc(db, crew.sourceDb, id), { 
              status: "rejected", 
              alasanTolak: finalReason,
              emailStatus: ""
            });
          }
        });
        await batch.commit();
        setSelectedPending([]);
        setSelectedRejected([]);
        showNotif("success", "Pelamar terpilih berhasil ditolak.");
      }
    } catch (e) {
      showNotif("error", "Gagal menyimpan penolakan.");
    } finally {
      setRejectModalOpen(false);
      setPendingRejectAction(null);
    }
  };

  const handleMassDelete = async (
    ids: string[],
    tabSource: "pending" | "accepted" | "rejected",
  ) => {
    if (!confirm(`Hapus permanen ${ids.length} data terpilih dari sistem?`))
      return;
    try {
      const batch = writeBatch(db);
      ids.forEach((id) => {
        const crew = pendaftar.find((c) => c.id === id);
        if (crew) {
          batch.delete(doc(db, crew.sourceDb, id));
        }
      });
      await batch.commit();

      if (tabSource === "pending") setSelectedPending([]);
      else if (tabSource === "accepted") setSelectedAccepted([]);
      else setSelectedRejected([]);

      showNotif("success", "Data dihapus secara permanen.");
    } catch (err) {
      showNotif("error", "Gagal menghapus data.");
    }
  };

  // --- EMAIL FUNCTIONS ---
  const handleSendWelcomeEmail = async (crew: CrewMember) => {
    const { parentEvent, roleName, roleLink } = getRoleInfo(
      crew.eventId,
      crew.roleId || crew.divisiId || "",
    );
    const targetLinkBesar = parentEvent?.linkGrupBesar || "";
    if (!targetLinkBesar && !roleLink)
      if (
        !confirm(
          "Belum ada Link WA yang diatur di event ini. Tetap kirim email?",
        )
      )
        return;

    setIsSendingMail(true);
    try {
      const { sendEmailAction } = await import("@/app/actions/email");
      const res = await sendEmailAction({
        type: "crew_accepted",
        email: crew.email,
        nama: crew.nama,
        detail: {
          event: parentEvent?.title || "Kepanitiaan",
          divisi: roleName,
          linkGrupBesar: targetLinkBesar,
          linkGrupDivisi: roleLink,
        },
      });

      if (res.success) {
        await setDoc(
          doc(db, crew.sourceDb, crew.id),
          { emailStatus: "sent", emailError: "" },
          { merge: true },
        );
        showNotif("success", `Undangan terkirim ke ${crew.nama}`);
      } else {
        showNotif("error", "Gagal mengirim undangan.");
      }
    } catch (e: any) {
      showNotif("error", "Error sistem.");
    } finally {
      setIsSendingMail(false);
    }
  };

  const handleSendRejectEmail = async (crew: CrewMember) => {
    const { parentEvent } = getRoleInfo(crew.eventId, crew.roleId || crew.divisiId || "");
    setIsSendingMail(true);
    try {
      const { sendEmailAction } = await import("@/app/actions/email");
      const res = await sendEmailAction({
        type: "crew_rejected",
        email: crew.email,
        nama: crew.nama,
        detail: {
          event: parentEvent?.title || "Kepanitiaan",
          alasanTolak: crew.alasanTolak || "Kualifikasi belum memenuhi kebutuhan panitia.",
        },
      });

      if (res.success) {
        await setDoc(
          doc(db, crew.sourceDb, crew.id),
          { emailStatus: "sent", emailError: "" },
          { merge: true },
        );
        showNotif("success", `Notifikasi penolakan terkirim ke ${crew.nama}`);
      } else {
        showNotif("error", "Gagal mengirim notifikasi.");
      }
    } catch (e: any) {
      showNotif("error", "Error sistem.");
    } finally {
      setIsSendingMail(false);
    }
  };

  const handleResendEmail = async () => {
    if (!selectedCrew) return;
    if (selectedCrew.status === "accepted") {
      await handleSendWelcomeEmail(selectedCrew);
    } else if (selectedCrew.status === "rejected") {
      await handleSendRejectEmail(selectedCrew);
    } else {
      showNotif("error", "Hanya untuk pelamar Diterima / Ditolak.");
    }
  };

  const handleSendCertEmail = async (crew: CrewMember) => {
    const { parentEvent } = getRoleInfo(
      crew.eventId,
      crew.roleId || crew.divisiId || "",
    );
    const certLink = parentEvent?.linkSertifikat || "";
    if (!certLink) {
      toast.warning("Link E-Sertifikat belum diatur!");
      return;
    }

    setIsSendingMail(true);
    try {
      const { sendEmailAction } = await import("@/app/actions/email");
      const res = await sendEmailAction({
        type: "certificate_crew",
        email: crew.email,
        nama: crew.nama,
        detail: {
          event: parentEvent?.title || "Kepanitiaan",
          linkSertifikat: certLink,
        },
      });

      if (res.success) {
        await setDoc(
          doc(db, crew.sourceDb, crew.id),
          { certEmailStatus: "sent", emailError: "" },
          { merge: true },
        );
        showNotif("success", `Sertifikat terkirim ke ${crew.nama}`);
      } else {
        showNotif("error", "Gagal mengirim sertifikat.");
      }
    } catch (e: any) {
      showNotif("error", "Error sistem.");
    } finally {
      setIsSendingMail(false);
    }
  };

  const handleMassEmail = async (type: "welcome" | "cert" | "rejected") => {
    const targetList = type === "rejected" ? selectedRejected : selectedAccepted;
    if (targetList.length === 0) return;
    
    const actionName = type === "cert" ? "Sertifikat" : type === "rejected" ? "Email Penolakan" : "Undangan WA";

    setGenericConfirm({
      isOpen: true,
      title: `Kirim ${actionName}`,
      message: `Kirim ${actionName} ke ${targetList.length} kandidat?`,
      onConfirm: async () => {
        setGenericConfirm({ ...genericConfirm, isOpen: false });
        
        setEmailProgress({
          total: targetList.length,
          sent: 0,
          failed: 0,
          isSending: true,
          type: type as any,
        });
        
        let sentCount = 0;
        let failCount = 0;

        for (const crewId of targetList) {
          const crew = pendaftar.find((c) => c.id === crewId);
          if (!crew) {
            failCount++;
            continue;
          }

          const { parentEvent, roleName, roleLink } = getRoleInfo(
            crew.eventId,
            crew.roleId || crew.divisiId || "",
          );
          if (type === "cert" && (!parentEvent || !parentEvent.linkSertifikat)) {
            failCount++;
            continue;
          }

          try {
            const { sendEmailAction } = await import("@/app/actions/email");
            const res = await sendEmailAction({
              type: type === "cert" ? "certificate_crew" : type === "rejected" ? "crew_rejected" : "crew_accepted",
              email: crew.email,
              nama: crew.nama,
              detail: type === "cert"
                ? {
                    event: parentEvent?.title || "Kepanitiaan",
                    linkSertifikat: parentEvent?.linkSertifikat,
                  }
                : type === "rejected"
                ? {
                    event: parentEvent?.title || "Kepanitiaan",
                    divisi: roleName,
                    alasanTolak: crew.alasanTolak || "Kualifikasi belum sesuai dengan kebutuhan saat ini.",
                  }
                : {
                    event: parentEvent?.title || "Kepanitiaan",
                    divisi: roleName,
                    linkGrupBesar: parentEvent?.linkGrupBesar || "",
                    linkGrupDivisi: roleLink,
                  },
            });

            if (res.success) {
              await setDoc(
                doc(db, crew.sourceDb, crew.id),
                type === "cert"
                  ? { certEmailStatus: "sent" }
                  : { emailStatus: "sent", emailError: "" },
                { merge: true },
              );
              sentCount++;
            } else {
              failCount++;
            }
          } catch (e: any) {
            failCount++;
          }
          setEmailProgress((prev) =>
            prev ? { ...prev, sent: sentCount, failed: failCount } : null,
          );
        }
        setEmailProgress((prev) => (prev ? { ...prev, isSending: false } : null));
        showNotif(
          "success",
          `Selesai. Berhasil: ${sentCount}, Gagal: ${failCount}`,
        );
        if (type === "rejected") setSelectedRejected([]);
        else setSelectedAccepted([]);
      },
    });
  };

  const exportToExcel = (data: CrewMember[], filename: string) => {
    const formattedData = data.map((c, index) => {
      const { parentEvent, roleName } = getRoleInfo(
        c.eventId,
        c.roleId || c.divisiId || "",
      );
      return {
        No: index + 1,
        "Tanggal Daftar": new Date(c.waktuDaftar).toLocaleString("id-ID"),
        "Event Target": parentEvent?.title || "Data Lama",
        "Penempatan Posisi": roleName,
        "Nama Lengkap": c.nama,
        "Jenis Kelamin": c.jenisKelamin || "-",
        "Tempat & Tgl Lahir": c.tempatLahir
          ? `${c.tempatLahir}, ${c.tanggalLahir}`
          : "-",
        Kategori: c.tipe.toUpperCase(),
        Email: c.email,
        WhatsApp: c.whatsapp,
        Instagram: c.instagram || "-",
        "Riwayat Penyakit": c.riwayatPenyakit || "-",
        "Ukuran Jersey": c.ukuranJersey || "-",
        Kendaraan: c.kendaraan || "-",
        "Bersedia Pindah Divisi": c.bersediaPindahDivisi || "-",
        "Bersedia Pelatihan": c.bersediaPelatihan || "-",
        "Instansi/UKM": c.instansi || "-",
        Jabatan: c.jabatan || "-",
        "Fakultas / Jurusan": c.fakultas || "-",
        Angkatan: c.angkatan || "-",
        Domisili: c.domisili || "-",
        "Alasan Pilih Divisi": c.alasanDivisi || "-",
        Motivasi: c.motivasi || "-",
        Pengalaman: c.pengalaman || "-",
        "Link Foto ID": c.fotoIdCard || "-",
        "Status Terkini":
          c.status === "accepted"
            ? "Diterima"
            : c.status === "pending"
              ? "Menunggu"
              : "Ditolak",
      };
    });
    const worksheet = XLSX.utils.json_to_sheet(formattedData);
    const workbook = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(workbook, worksheet, `Data_${activeTab}`);
    XLSX.writeFile(workbook, `${filename}.xlsx`);
  };

  const currentTabList = pendaftar.filter(
    (c) =>
      (activeTab === "pendaftar"
        ? c.status === "pending"
        : activeTab === "timInti"
          ? c.status === "accepted"
          : activeTab === "ditolak"
            ? c.status === "rejected"
            : false) &&
      (filterEvent === "all" || c.eventId === filterEvent) &&
      (filterTipe === "all" || c.tipe === filterTipe) &&
      (filterGender === "all" || c.jenisKelamin === filterGender) &&
      (filterDivisi === "all" || c.roleId === filterDivisi || c.divisiId === filterDivisi),
  );

  const totalPages =
    itemsPerPage === 0 ? 1 : Math.ceil(currentTabList.length / itemsPerPage);
  const pagedData =
    itemsPerPage === 0
      ? currentTabList
      : currentTabList.slice(
          (currentPage - 1) * itemsPerPage,
          currentPage * itemsPerPage,
        );

  if (isLoading)
    return (
      <div className="h-screen flex items-center justify-center text-[#1A73E8]">
        <div className="w-8 h-8 border-4 border-blue-100 border-t-[#1A73E8] rounded-full animate-spin"></div>
      </div>
    );

  return (
    <div className="max-w-7xl mx-auto pb-32 font-sans p-4 sm:p-8 bg-[#F8F9FA] min-h-screen">
      {popup && (
        <div className="fixed top-6 right-6 z-[9999] min-w-[280px] bg-white border border-[#DADCE0] px-4 py-3 rounded-lg shadow-xl flex items-center gap-3 animate-in slide-in-from-right-8 fade-in duration-300">
          {popup.type === "success" ? <IconCheckCircle /> : <IconErrorCircle />}
          <span className="text-sm font-medium text-slate-700">
            {popup.text}
          </span>
        </div>
      )}

      {/* HEADER */}
      <div className="mb-6 border-b border-[#DADCE0] pb-4">
        <h1 className="text-2xl font-medium text-slate-800 tracking-tight">
          Manajemen Kru & Relawan
        </h1>
        <p className="text-sm text-slate-500 mt-1">
          Konfigurasi struktur rekrutmen, peninjauan pelamar, dan pengiriman
          notifikasi.
        </p>
      </div>

      {/* MATERIAL TABS */}
      <div className="flex gap-3 mb-8 overflow-x-auto hide-scrollbar pb-2">
        {[
          { id: "pengaturan", label: "Setup Lowongan", icon: <IconSettings /> },
          { id: "pendaftar", label: "Menunggu Review", icon: <IconPending /> },
          { id: "timInti", label: "Diterima", icon: <IconCheckBadge /> },
          { id: "ditolak", label: "Ditolak", icon: <IconErrorCircle /> },
        ].map((tab) => (
          <button
            key={tab.id}
            onClick={() => {
              setActiveTab(tab.id as any);
              setCurrentPage(1);
            }}
            className={`px-5 py-2.5 rounded-full text-sm font-medium transition-all flex items-center gap-2 border whitespace-nowrap ${activeTab === tab.id ? "bg-[#E8F0FE] text-[#1A73E8] border-[#1A73E8]/30 shadow-sm" : "bg-white text-slate-600 hover:bg-slate-50 border-[#DADCE0]"}`}
          >
            {tab.icon} {tab.label}
            {tab.id === "pendaftar" &&
              pendaftar.filter((c) => c.status === "pending").length > 0 && (
                <span className="bg-[#D93025] text-white text-[10px] px-2 py-0.5 rounded-full font-bold ml-1">
                  {pendaftar.filter((c) => c.status === "pending").length}
                </span>
              )}
            {tab.id === "timInti" &&
              pendaftar.filter((c) => c.status === "accepted").length > 0 && (
                <span className="bg-[#1E8E3E] text-white text-[10px] px-2 py-0.5 rounded-full font-bold ml-1">
                  {pendaftar.filter((c) => c.status === "accepted").length}
                </span>
              )}
            {tab.id === "ditolak" &&
              pendaftar.filter((c) => c.status === "rejected").length > 0 && (
                <span className="bg-slate-500 text-white text-[10px] px-2 py-0.5 rounded-full font-bold ml-1">
                  {pendaftar.filter((c) => c.status === "rejected").length}
                </span>
              )}
          </button>
        ))}
      </div>

      {/* TAB 1: PENGATURAN */}
      {activeTab === "pengaturan" && (
        <div className="space-y-6 animate-in fade-in duration-300">
          <div className="flex flex-col sm:flex-row justify-between sm:items-center gap-4 mb-4">
            <h2 className="text-base font-medium text-slate-800">
              Daftar Event Kepanitiaan (OPREC)
            </h2>
            <button
              onClick={handleAddEvent}
              className="bg-white border border-[#DADCE0] text-[#1A73E8] hover:bg-[#F8F9FA] px-4 py-2 rounded-lg text-sm font-medium transition-colors flex items-center justify-center gap-2 shadow-sm"
            >
              + Tambah Event Baru
            </button>
          </div>

          {events.length === 0 ? (
            <div className="bg-white border border-dashed border-[#DADCE0] rounded-2xl p-16 text-center shadow-sm">
              <p className="text-slate-500 font-medium text-sm">
                Belum ada event kepanitiaan. Klik tombol di atas untuk memulai.
              </p>
            </div>
          ) : (
            events.map((event, eventIdx) => {
              const isEventExpanded = expandedEvents[event.id] === true;
              return (
                <div
                  key={event.id}
                  className={`bg-white rounded-2xl border transition-all overflow-hidden ${event.isActive ? "border-[#DADCE0] shadow-sm" : "border-[#DADCE0] opacity-70"}`}
                >
                  <div
                    className={`p-4 sm:p-5 flex flex-col xl:flex-row gap-4 xl:gap-5 items-start xl:items-center hover:bg-[#F8F9FA] transition-colors cursor-pointer ${isEventExpanded ? "border-b border-[#DADCE0] bg-[#F8F9FA]" : ""}`}
                    onClick={() => toggleEventCard(event.id)}
                  >
                    <div
                      className="flex xl:flex-col gap-1 items-center bg-white border border-[#DADCE0] rounded-lg p-1 mr-2"
                      onClick={(e) => e.stopPropagation()}
                    >
                      <button
                        onClick={() => moveEvent(eventIdx, "up")}
                        disabled={eventIdx === 0}
                        className="p-1 text-slate-400 hover:text-[#1A73E8] hover:bg-blue-50 rounded disabled:opacity-30"
                      >
                        <IconArrowUp />
                      </button>
                      <button
                        onClick={() => moveEvent(eventIdx, "down")}
                        disabled={eventIdx === events.length - 1}
                        className="p-1 text-slate-400 hover:text-[#1A73E8] hover:bg-blue-50 rounded disabled:opacity-30"
                      >
                        <IconArrowDown />
                      </button>
                    </div>

                    <div
                      className="flex items-center gap-3 flex-1 w-full"
                      onClick={(e) => e.stopPropagation()}
                    >
                      <span
                        className={`text-slate-400 transition-transform ${isEventExpanded ? "rotate-180" : ""}`}
                        onClick={() => toggleEventCard(event.id)}
                      >
                        ▼
                      </span>
                      <input
                        type="text"
                        value={event.title}
                        onChange={(e) =>
                          handleChangeEvent(event.id, "title", e.target.value)
                        }
                        placeholder="Nama Event (Cth: IKA UII RUN 2026)"
                        className="flex-1 bg-transparent border-b border-transparent hover:border-[#DADCE0] focus:border-[#1A73E8] outline-none text-base font-bold text-[#0F2147] py-0.5 transition-colors"
                      />
                    </div>
                    <div
                      className="flex items-center gap-4 ml-8 xl:ml-0"
                      onClick={(e) => e.stopPropagation()}
                    >
                      <label className="flex items-center cursor-pointer mr-2">
                        <div className="relative">
                          <input
                            type="checkbox"
                            className="sr-only"
                            checked={event.isActive}
                            onChange={(e) =>
                              handleChangeEvent(
                                event.id,
                                "isActive",
                                e.target.checked,
                              )
                            }
                          />
                          <div
                            className={`block w-10 h-6 rounded-full transition-colors ${event.isActive ? "bg-[#1A73E8]" : "bg-[#DADCE0]"}`}
                          ></div>
                          <div
                            className={`dot absolute left-[2px] top-[2px] bg-white w-4 h-4 rounded-full transition-transform ${event.isActive ? "transform translate-x-4" : ""}`}
                          ></div>
                        </div>
                        <span className="ml-2 text-xs font-bold text-slate-600 hidden sm:block">
                          {event.isActive ? "Dibuka" : "Ditutup"}
                        </span>
                      </label>
                      <button
                        onClick={() => handleRemoveEvent(event.id)}
                        className="p-2 text-slate-400 hover:text-[#D93025] hover:bg-red-50 rounded-lg transition-colors"
                        title="Hapus Event"
                      >
                        ✕
                      </button>
                    </div>
                  </div>

                  {isEventExpanded && (
                    <div className="p-5 sm:p-6 bg-white animate-in slide-in-from-top-2 duration-200">
                      <div className="grid grid-cols-1 md:grid-cols-3 gap-6 mb-6">
                        <div className="md:col-span-1">
                          <label className="block text-xs font-medium text-slate-600 mb-1.5">
                            Deskripsi / Persyaratan Umum
                          </label>
                          <textarea
                            value={event.requirements || ""}
                            onChange={(e) =>
                              handleChangeEvent(
                                event.id,
                                "requirements",
                                e.target.value,
                              )
                            }
                            rows={4}
                            className="w-full p-3 border border-[#DADCE0] rounded-lg focus:border-[#1A73E8] outline-none text-sm text-slate-800 resize-none shadow-sm"
                            placeholder="Persyaratan..."
                          ></textarea>
                        </div>
                        <div className="md:col-span-2 flex flex-col gap-4">
                          <div>
                            <label className="block text-xs font-medium text-slate-600 mb-1.5">
                              Link WhatsApp Grup Utama (Opsional)
                            </label>
                            <input
                              type="url"
                              value={event.linkGrupBesar || ""}
                              onChange={(e) =>
                                handleChangeEvent(
                                  event.id,
                                  "linkGrupBesar",
                                  e.target.value,
                                )
                              }
                              className="w-full p-3 border border-[#DADCE0] rounded-lg focus:border-[#1A73E8] outline-none text-sm text-slate-800 shadow-sm"
                              placeholder="https://chat.whatsapp..."
                            />
                          </div>
                          <div>
                            <label className="block text-xs font-medium text-slate-600 mb-1.5">
                              Link E-Sertifikat Kepanitiaan (G-Drive)
                            </label>
                            <input
                              type="url"
                              value={event.linkSertifikat || ""}
                              onChange={(e) =>
                                handleChangeEvent(
                                  event.id,
                                  "linkSertifikat",
                                  e.target.value,
                                )
                              }
                              className="w-full p-3 border border-[#DADCE0] rounded-lg focus:border-[#1A73E8] outline-none text-sm text-slate-800 shadow-sm"
                              placeholder="https://drive.google.com/..."
                            />
                          </div>
                        </div>
                      </div>

                      {/* CHECKBOX TARGET PENDAFTAR */}
                      <div className="mb-6 bg-[#F8F9FA] p-4 rounded-lg border border-[#DADCE0]">
                        <label className="block text-xs font-medium text-slate-600 mb-3">
                          Target Kategori Pendaftar (Yang Diizinkan)
                        </label>
                        <div className="flex flex-wrap gap-4">
                          {["mahasiswa", "alumni", "umum"].map((tipe) => (
                            <label key={tipe} className="flex items-center gap-2 cursor-pointer">
                              <input
                                type="checkbox"
                                checked={(event.allowedTipe || ["mahasiswa", "alumni", "umum"]).includes(tipe)}
                                onChange={(e) => {
                                  const current = event.allowedTipe || ["mahasiswa", "alumni", "umum"];
                                  const next = e.target.checked
                                    ? [...current, tipe]
                                    : current.filter((t) => t !== tipe);
                                  handleChangeEvent(event.id, "allowedTipe", next);
                                }}
                                className="w-4 h-4 text-[#1A73E8] border-slate-300 rounded focus:ring-[#1A73E8]"
                              />
                              <span className="text-sm font-medium text-slate-700 capitalize">
                                {tipe}
                              </span>
                            </label>
                          ))}
                        </div>
                      </div>

                      <div className="space-y-4 border-t border-[#DADCE0] pt-5">
                        <div className="flex items-center justify-between mb-2">
                          <h4 className="text-sm font-medium text-slate-800">
                            Struktur Divisi & Posisi
                          </h4>
                          <button
                            onClick={() => handleAddGroup(event.id)}
                            className="text-[#1A73E8] text-sm font-medium hover:bg-[#F8F9FA] px-3 py-1.5 rounded-lg transition-colors border border-[#DADCE0] shadow-sm"
                          >
                            + Tambah Kelompok
                          </button>
                        </div>
                        {(event.groups || []).map((group, groupIdx) => {
                          const isGroupExpanded =
                            expandedGroups[group.id] === true;
                          return (
                            <div
                              key={group.id}
                              className="border border-[#DADCE0] rounded-xl p-3 bg-[#F8F9FA]"
                            >
                              <div className="flex flex-col sm:flex-row items-start sm:items-center justify-between gap-3 mb-2">
                                <div className="flex items-center gap-2 w-full sm:w-auto">
                                  <div className="flex gap-1 items-center bg-white border border-[#DADCE0] rounded-md px-1 mr-1">
                                    <button
                                      onClick={() =>
                                        moveGroup(event.id, groupIdx, "up")
                                      }
                                      disabled={groupIdx === 0}
                                      className="p-1 text-slate-400 hover:text-[#1A73E8] hover:bg-blue-50 rounded disabled:opacity-30"
                                    >
                                      <IconArrowUp />
                                    </button>
                                    <button
                                      onClick={() =>
                                        moveGroup(event.id, groupIdx, "down")
                                      }
                                      disabled={
                                        groupIdx ===
                                        (event.groups || []).length - 1
                                      }
                                      className="p-1 text-slate-400 hover:text-[#1A73E8] hover:bg-blue-50 rounded disabled:opacity-30"
                                    >
                                      <IconArrowDown />
                                    </button>
                                  </div>
                                  <button
                                    onClick={() => toggleGroupCard(group.id)}
                                    className="text-slate-400 p-1 hover:bg-[#E8EAED] rounded transition-colors"
                                  >
                                    <span
                                      className={`inline-block transition-transform ${isGroupExpanded ? "rotate-180" : ""}`}
                                    >
                                      ▼
                                    </span>
                                  </button>
                                  <input
                                    type="text"
                                    value={group.title}
                                    onChange={(e) =>
                                      handleChangeGroup(
                                        event.id,
                                        group.id,
                                        e.target.value,
                                      )
                                    }
                                    placeholder="Nama Kelompok Divisi"
                                    className="bg-transparent border-b border-[#DADCE0] focus:border-[#1A73E8] outline-none text-sm font-bold text-[#0F2147] w-full sm:w-64 pb-0.5"
                                  />
                                </div>
                                <div className="flex items-center gap-2 w-full sm:w-auto justify-end ml-7 sm:ml-0">
                                  <button
                                    onClick={() =>
                                      handleRemoveGroup(event.id, group.id)
                                    }
                                    className="text-xs font-bold text-[#D93025] hover:bg-red-50 px-3 py-1.5 rounded transition-colors"
                                  >
                                    Hapus Grup
                                  </button>
                                  <button
                                    onClick={() =>
                                      handleAddRole(event.id, group.id)
                                    }
                                    className="text-xs font-bold bg-white border border-[#DADCE0] text-slate-600 px-3 py-1.5 rounded hover:bg-[#E8EAED] shadow-sm transition-colors"
                                  >
                                    + Tambah Posisi
                                  </button>
                                </div>
                              </div>

                              {isGroupExpanded && (
                                <div className="space-y-3 mt-3 sm:ml-12 border-l-2 border-[#1A73E8]/20 pl-4 py-1">
                                  {(!group.roles ||
                                    group.roles.length === 0) && (
                                    <p className="text-xs text-slate-400 italic">
                                      Belum ada posisi.
                                    </p>
                                  )}
                                  {(group.roles || []).map((role, roleIdx) => {
                                    const filledCount = getRoleFilledCount(
                                      role.id,
                                    );
                                    return (
                                      <div
                                        key={role.id}
                                        className="flex flex-col gap-2 bg-white p-3 border border-[#DADCE0] rounded-lg shadow-sm"
                                      >
                                        <div className="flex flex-col lg:flex-row items-start lg:items-center gap-2 w-full">
                                          <div className="flex lg:flex-col gap-1 items-center bg-[#F8F9FA] border border-[#DADCE0] rounded-md px-1 mr-1">
                                            <button
                                              onClick={() =>
                                                moveRole(
                                                  event.id,
                                                  group.id,
                                                  roleIdx,
                                                  "up",
                                                )
                                              }
                                              disabled={roleIdx === 0}
                                              className="p-0.5 text-slate-400 hover:text-[#1A73E8] hover:bg-blue-50 rounded disabled:opacity-30"
                                            >
                                              <IconArrowUp />
                                            </button>
                                            <button
                                              onClick={() =>
                                                moveRole(
                                                  event.id,
                                                  group.id,
                                                  roleIdx,
                                                  "down",
                                                )
                                              }
                                              disabled={
                                                roleIdx ===
                                                (group.roles || []).length - 1
                                              }
                                              className="p-0.5 text-slate-400 hover:text-[#1A73E8] hover:bg-blue-50 rounded disabled:opacity-30"
                                            >
                                              <IconArrowDown />
                                            </button>
                                          </div>
                                          <input
                                            type="text"
                                            value={role.nama}
                                            onChange={(e) =>
                                              handleChangeRole(
                                                event.id,
                                                group.id,
                                                role.id,
                                                "nama",
                                                e.target.value,
                                              )
                                            }
                                            placeholder="Nama Posisi"
                                            className="w-full lg:w-1/3 p-2 border border-[#DADCE0] rounded text-xs font-bold text-slate-700 outline-none focus:border-[#1A73E8]"
                                          />
                                          <div className="w-full lg:w-24 flex flex-col">
                                            <input
                                              type="number"
                                              value={role.kuota}
                                              onChange={(e) =>
                                                handleChangeRole(
                                                  event.id,
                                                  group.id,
                                                  role.id,
                                                  "kuota",
                                                  Number(e.target.value),
                                                )
                                              }
                                              placeholder="Kuota"
                                              className="p-2 border border-[#DADCE0] rounded text-xs text-center outline-none focus:border-[#1A73E8]"
                                            />
                                            <span className="text-[9px] font-bold text-slate-400 text-center mt-1">
                                              TERISI: {filledCount}/{role.kuota}
                                            </span>
                                          </div>
                                          <input
                                            type="url"
                                            value={role.linkWa}
                                            onChange={(e) =>
                                              handleChangeRole(
                                                event.id,
                                                group.id,
                                                role.id,
                                                "linkWa",
                                                e.target.value,
                                              )
                                            }
                                            placeholder="Link WA Posisi Khusus"
                                            className="w-full lg:flex-1 p-2 border border-[#DADCE0] rounded text-xs outline-none focus:border-[#1A73E8]"
                                          />
                                          <button
                                            onClick={() =>
                                              handleRemoveRole(
                                                event.id,
                                                group.id,
                                                role.id,
                                              )
                                            }
                                            className="p-2 text-slate-400 hover:text-[#D93025] hover:bg-red-50 rounded transition-colors text-xs font-bold w-full lg:w-auto text-right lg:text-center"
                                          >
                                            ✕ Hapus
                                          </button>
                                        </div>
                                        <div className="w-full border-t border-slate-100 pt-2 ml-7 lg:ml-0 pr-7 lg:pr-0">
                                          <textarea
                                            value={role.deskripsi || ""}
                                            onChange={(e) =>
                                              handleChangeRole(
                                                event.id,
                                                group.id,
                                                role.id,
                                                "deskripsi",
                                                e.target.value,
                                              )
                                            }
                                            placeholder="Tuliskan SOP atau Job Description singkat untuk posisi ini..."
                                            className="w-full p-2.5 bg-slate-50 border border-[#DADCE0] rounded-md text-xs outline-none focus:border-[#1A73E8] resize-none"
                                            rows={2}
                                          ></textarea>
                                        </div>
                                      </div>
                                    );
                                  })}
                                </div>
                              )}
                            </div>
                          );
                        })}
                      </div>
                    </div>
                  )}
                </div>
              );
            })
          )}
          <div className="pt-2 sticky bottom-4 z-50 bg-[#F8F9FA] py-4 border-t border-[#DADCE0] sm:border-none sm:py-0">
            <button
              onClick={saveSettings}
              disabled={isSaving}
              className="w-full sm:w-auto bg-[#1A73E8] hover:bg-[#1557B0] text-white text-sm font-bold px-8 py-3 rounded-xl shadow-md transition-all active:scale-95 disabled:opacity-50 flex items-center justify-center gap-2 mx-auto"
            >
              {isSaving ? "Menyimpan..." : "Simpan Semua Pengaturan"}
            </button>
          </div>
        </div>
      )}

      {/* TAB 2, 3, & 4: TABEL PELAMAR */}
      {activeTab !== "pengaturan" && (
        <div className="bg-white border border-[#DADCE0] rounded-2xl overflow-hidden shadow-sm animate-in fade-in duration-300">
          <div className="p-4 border-b border-[#DADCE0] flex flex-col lg:flex-row justify-between items-start lg:items-center gap-4 bg-[#F8F9FA]">
            <div className="flex flex-wrap items-center gap-3 w-full lg:w-auto">
              <select
                value={filterEvent}
                onChange={(e) => {
                  setFilterEvent(e.target.value);
                  setFilterDivisi("all");
                  setCurrentPage(1);
                }}
                className="bg-white border border-[#DADCE0] text-slate-800 text-sm rounded-lg px-4 py-2 outline-none focus:border-[#1A73E8] shadow-sm flex-1 lg:flex-auto cursor-pointer font-medium"
              >
                <option value="all">Semua Event</option>
                {events.map((e) => (
                  <option key={e.id} value={e.id}>
                    {e.title}
                  </option>
                ))}
              </select>

              <select
                value={filterDivisi}
                onChange={(e) => {
                  setFilterDivisi(e.target.value);
                  setCurrentPage(1);
                }}
                className="bg-white border border-[#DADCE0] text-slate-800 text-sm rounded-lg px-4 py-2 outline-none focus:border-[#1A73E8] shadow-sm flex-1 lg:flex-auto cursor-pointer font-medium"
              >
                <option value="all">Semua Divisi</option>
                {filterEvent !== "all" &&
                  events
                    .find((e) => e.id === filterEvent)
                    ?.groups?.flatMap((g) => g.roles || [])
                    .map((r) => (
                      <option key={r.id} value={r.id}>
                        {r.nama}
                      </option>
                    ))}
              </select>

              <select
                value={filterTipe}
                onChange={(e) => {
                  setFilterTipe(e.target.value);
                  setCurrentPage(1);
                }}
                className="bg-white border border-[#DADCE0] text-slate-800 text-sm rounded-lg px-4 py-2 outline-none focus:border-[#1A73E8] shadow-sm flex-1 lg:flex-auto cursor-pointer font-medium"
              >
                <option value="all">Semua Tipe</option>
                <option value="mahasiswa">Mahasiswa</option>
                <option value="alumni">Alumni</option>
                <option value="himpunan">Himpunan</option>
                <option value="ukm">UKM</option>
                <option value="umum">Umum</option>
              </select>

              <select
                value={filterGender}
                onChange={(e) => {
                  setFilterGender(e.target.value);
                  setCurrentPage(1);
                }}
                className="bg-white border border-[#DADCE0] text-slate-800 text-sm rounded-lg px-4 py-2 outline-none focus:border-[#1A73E8] shadow-sm flex-1 lg:flex-auto cursor-pointer font-medium"
              >
                <option value="all">Semua Gender</option>
                <option value="Laki-laki">Laki-laki</option>
                <option value="Perempuan">Perempuan</option>
              </select>
              <button
                onClick={() =>
                  exportToExcel(currentTabList, `Data_Pelamar_${activeTab}`)
                }
                className="bg-emerald-600 border border-emerald-700 text-white hover:bg-emerald-700 px-4 py-2 rounded-lg text-sm font-bold shadow-sm transition-colors flex items-center gap-2"
              >
                <svg
                  className="w-4 h-4"
                  fill="none"
                  viewBox="0 0 24 24"
                  stroke="currentColor"
                >
                  <path
                    strokeLinecap="round"
                    strokeLinejoin="round"
                    strokeWidth={2}
                    d="M4 16v1a3 3 0 003 3h10a3 3 0 003-3v-1m-4-4l-4 4m0 0l-4-4m4 4V4"
                  />
                </svg>
                Ekspor Excel ({activeTab})
              </button>
            </div>

            {/* AKSI MASSAL */}
            {((activeTab === "pendaftar" && selectedPending.length > 0) ||
              (activeTab === "timInti" && selectedAccepted.length > 0) ||
              (activeTab === "ditolak" && selectedRejected.length > 0)) && (
              <div className="flex flex-wrap items-center gap-2 w-full lg:w-auto bg-[#E8F0FE] p-1.5 rounded-xl border border-[#1A73E8]/30">
                <span className="text-sm text-[#1A73E8] font-bold ml-3 mr-3">
                  {activeTab === "pendaftar"
                    ? selectedPending.length
                    : activeTab === "timInti"
                      ? selectedAccepted.length
                      : selectedRejected.length}{" "}
                  dipilih
                </span>

                {activeTab === "pendaftar" && (
                  <>
                    <button
                      onClick={() =>
                        handleMassDelete(selectedPending, "pending")
                      }
                      className="text-[#D93025] bg-white border border-[#DADCE0] hover:bg-red-50 px-4 py-1.5 rounded-lg text-sm font-bold shadow-sm transition-colors"
                    >
                      Hapus
                    </button>
                    <button
                      onClick={() =>
                        handleMassUpdateStatus(selectedPending, "rejected")
                      }
                      className="text-slate-700 bg-white border border-[#DADCE0] hover:bg-slate-50 px-4 py-1.5 rounded-lg text-sm font-bold shadow-sm transition-colors"
                    >
                      Tolak
                    </button>
                    <button
                      onClick={() =>
                        handleMassUpdateStatus(selectedPending, "accepted")
                      }
                      className="bg-[#1A73E8] hover:bg-[#1557B0] text-white px-4 py-1.5 rounded-lg text-sm font-bold shadow-sm transition-colors"
                    >
                      Terima Semua
                    </button>
                  </>
                )}

                {activeTab === "timInti" && (
                  <>
                    <button
                      onClick={() =>
                        handleMassDelete(selectedAccepted, "accepted")
                      }
                      className="text-[#D93025] bg-white border border-[#DADCE0] hover:bg-red-50 px-4 py-1.5 rounded-lg text-sm font-bold shadow-sm transition-colors"
                    >
                      Hapus Permanen
                    </button>
                    <button
                      onClick={() => handleMassEmail("welcome")}
                      className="bg-white text-slate-700 border border-[#DADCE0] hover:bg-slate-50 px-4 py-1.5 rounded-lg text-sm font-bold flex items-center gap-2 shadow-sm transition-colors"
                    >
                      <IconMail /> Email
                    </button>
                    <button
                      onClick={() => handleMassEmail("cert")}
                      className="bg-[#1A73E8] hover:bg-[#1557B0] text-white px-4 py-1.5 rounded-lg text-sm font-bold flex items-center gap-2 shadow-sm transition-colors"
                    >
                      <IconCertificate /> Kirim E-Sertifikat
                    </button>
                  </>
                )}

                {activeTab === "ditolak" && (
                  <>
                    <button
                      onClick={() =>
                        handleMassDelete(selectedRejected, "rejected")
                      }
                      className="text-[#D93025] bg-white border border-[#DADCE0] hover:bg-red-50 px-4 py-1.5 rounded-lg text-sm font-bold shadow-sm transition-colors"
                    >
                      Hapus Permanen
                    </button>
                    <button
                      onClick={() =>
                        handleMassUpdateStatus(selectedRejected, "pending")
                      }
                      className="bg-amber-500 hover:bg-amber-600 text-white px-4 py-1.5 rounded-lg text-sm font-bold shadow-sm transition-colors"
                    >
                      Pulihkan (Pending)
                    </button>
                    <button
                      onClick={() => handleMassEmail("rejected")}
                      className="bg-white text-slate-700 border border-[#DADCE0] hover:bg-slate-50 px-4 py-1.5 rounded-lg text-sm font-bold flex items-center gap-2 shadow-sm transition-colors"
                    >
                      <IconMail /> Email Penolakan
                    </button>
                  </>
                )}
              </div>
            )}
          </div>

          <div className="overflow-y-auto custom-scrollbar max-h-[500px]">
            <table className="w-full text-left border-collapse">
              <thead>
                <tr className="border-b border-[#DADCE0] bg-[#F8F9FA] sticky top-0 z-10 shadow-sm">
                  <th className="px-5 py-4 w-10">
                    <input
                      type="checkbox"
                      checked={
                        pagedData.length > 0 &&
                        (activeTab === "pendaftar"
                          ? selectedPending.length === pagedData.length
                          : activeTab === "timInti"
                            ? selectedAccepted.length === pagedData.length
                            : selectedRejected.length === pagedData.length)
                      }
                      onChange={(e) => {
                        const ids = pagedData.map((c) => c.id);
                        if (activeTab === "pendaftar")
                          setSelectedPending(e.target.checked ? ids : []);
                        else if (activeTab === "timInti")
                          setSelectedAccepted(e.target.checked ? ids : []);
                        else setSelectedRejected(e.target.checked ? ids : []);
                      }}
                      className="w-4 h-4 border-[#DADCE0] rounded cursor-pointer accent-[#1A73E8]"
                    />
                  </th>
                  <th className="px-4 py-4 font-bold text-slate-500 text-xs uppercase tracking-wider">
                    NAMA KANDIDAT
                  </th>
                  <th className="px-4 py-4 font-bold text-slate-500 text-xs uppercase tracking-wider">
                    EVENT & POSISI
                  </th>
                  {(activeTab === "timInti" || activeTab === "ditolak") && (
                    <th className="px-4 py-4 font-bold text-slate-500 text-xs uppercase tracking-wider text-center">
                      STATUS EMAIL
                    </th>
                  )}
                  <th className="px-5 py-4 font-bold text-slate-500 text-xs uppercase tracking-wider text-right">
                    AKSI
                  </th>
                </tr>
              </thead>
              <tbody className="divide-y divide-[#DADCE0]">
                {pagedData.length === 0 ? (
                  <tr>
                    <td
                      colSpan={5}
                      className="py-16 text-center text-slate-500 text-sm font-medium"
                    >
                      Tidak ada data untuk ditampilkan di tab ini.
                    </td>
                  </tr>
                ) : (
                  pagedData.map((crew) => {
                    const { parentEvent, roleName } = getRoleInfo(
                      crew.eventId,
                      crew.roleId || crew.divisiId || "",
                    );
                    const isChecked =
                      activeTab === "pendaftar"
                        ? selectedPending.includes(crew.id)
                        : activeTab === "timInti"
                          ? selectedAccepted.includes(crew.id)
                          : selectedRejected.includes(crew.id);
                    return (
                      <tr
                        key={crew.id}
                        className={`hover:bg-[#F8F9FA] transition-colors ${isChecked ? "bg-[#E8F0FE]" : ""}`}
                      >
                        <td className="px-5 py-3">
                          <input
                            type="checkbox"
                            checked={isChecked}
                            onChange={(e) => {
                              if (activeTab === "pendaftar")
                                setSelectedPending(
                                  e.target.checked
                                    ? [...selectedPending, crew.id]
                                    : selectedPending.filter(
                                        (id) => id !== crew.id,
                                      ),
                                );
                              else if (activeTab === "timInti")
                                setSelectedAccepted(
                                  e.target.checked
                                    ? [...selectedAccepted, crew.id]
                                    : selectedAccepted.filter(
                                        (id) => id !== crew.id,
                                      ),
                                );
                              else
                                setSelectedRejected(
                                  e.target.checked
                                    ? [...selectedRejected, crew.id]
                                    : selectedRejected.filter(
                                        (id) => id !== crew.id,
                                      ),
                                );
                            }}
                            className="w-4 h-4 border-[#DADCE0] rounded cursor-pointer accent-[#1A73E8]"
                          />
                        </td>
                        <td className="px-4 py-3 flex items-center gap-3">
                          {crew.fotoIdCard ? (
                            <img
                              src={crew.fotoIdCard}
                              alt="Foto"
                              className="w-10 h-10 rounded-full object-cover border border-slate-200 shadow-sm shrink-0"
                            />
                          ) : (
                            <div className="w-10 h-10 rounded-full bg-slate-200 border border-slate-300 flex items-center justify-center shrink-0">
                              <IconSettings />
                            </div>
                          )}
                          <div>
                            <p className="text-sm font-bold text-slate-800">
                              {crew.nama}
                            </p>
                            <div className="flex gap-1.5 mt-1">
                              <p className="text-[9px] font-bold text-slate-500 uppercase tracking-wider bg-[#F1F3F4] px-1.5 py-0.5 rounded inline-block">
                                {crew.tipe}
                              </p>
                              {crew.sourceDb === "crew_volunteers" && (
                                <p className="text-[9px] font-bold text-amber-600 uppercase tracking-wider bg-amber-50 border border-amber-200 px-1.5 py-0.5 rounded inline-block">
                                  Data Lama
                                </p>
                              )}
                            </div>
                          </div>
                        </td>
                        <td className="px-4 py-3">
                          <p className="text-sm text-[#1A73E8] font-bold">
                            {parentEvent?.title || "Data Lama"}
                          </p>
                          <p className="text-xs font-medium text-slate-500">
                            {roleName}
                          </p>
                        </td>

                        {(activeTab === "timInti" || activeTab === "ditolak") && (
                          <td className="px-4 py-3 text-center">
                            <div className="flex flex-col items-center gap-1.5">
                              {crew.emailStatus === "sent" ? (
                                <span className="bg-emerald-50 text-emerald-700 text-[10px] px-2 py-1 rounded font-bold border border-emerald-200">
                                  {activeTab === "ditolak" ? "Pemberitahuan: Sukses" : "Undangan: Sukses"}
                                </span>
                              ) : (
                                <span className="bg-slate-100 text-slate-500 text-[10px] px-2 py-1 rounded font-medium border border-slate-200">
                                  {activeTab === "ditolak" ? "Pemberitahuan: -" : "Undangan: -"}
                                </span>
                              )}
                              {activeTab === "timInti" && (
                                <>
                                  {crew.certEmailStatus === "sent" ? (
                                    <span className="bg-blue-50 text-blue-700 text-[10px] px-2 py-1 rounded font-bold border border-blue-200">
                                      Sertifikat: Sukses
                                    </span>
                                  ) : (
                                    <span className="bg-slate-100 text-slate-500 text-[10px] px-2 py-1 rounded font-medium border border-slate-200">
                                      Sertifikat: -
                                    </span>
                                  )}
                                </>
                              )}
                            </div>
                          </td>
                        )}

                        <td className="px-5 py-3 text-right">
                          <div className="flex items-center justify-end gap-2">
                            <button
                              onClick={() => openDetail(crew)}
                              className="text-slate-600 bg-white border border-[#DADCE0] hover:bg-[#F8F9FA] hover:text-[#1A73E8] px-3 py-1.5 rounded-lg text-xs font-bold transition-colors shadow-sm flex items-center gap-1"
                            >
                              <IconDetail /> Detail
                            </button>

                            {activeTab === "timInti" && (
                              <div className="flex gap-2 border-l border-slate-200 pl-3 ml-1">
                                <button
                                  onClick={() => handleSendWelcomeEmail(crew)}
                                  disabled={isSendingMail}
                                  className="text-slate-700 border border-[#DADCE0] bg-white px-3 py-1.5 rounded-lg text-xs font-bold hover:bg-slate-50 transition-colors disabled:opacity-50 flex items-center gap-1"
                                  title="Kirim Email Undangan"
                                >
                                  <IconMail /> Email
                                </button>
                                <button
                                  onClick={() => handleSendCertEmail(crew)}
                                  disabled={isSendingMail}
                                  className="text-[#1A73E8] border border-[#1A73E8] bg-blue-50 px-3 py-1.5 rounded-lg text-xs font-bold hover:bg-[#1A73E8] hover:text-white transition-colors disabled:opacity-50 flex items-center gap-1"
                                  title="Kirim E-Sertifikat"
                                >
                                  <IconCertificate /> E-Sertifikat
                                </button>
                              </div>
                            )}
                          </div>
                        </td>
                      </tr>
                    );
                  })
                )}
              </tbody>
            </table>
          </div>

          <div className="p-4 border-t border-[#DADCE0] flex flex-col md:flex-row justify-between items-center bg-white gap-3">
            <div className="flex items-center gap-2">
              <span className="text-xs font-medium text-slate-500 hidden sm:block">
                Baris per halaman:
              </span>
              <select
                value={itemsPerPage}
                onChange={(e) => {
                  setItemsPerPage(Number(e.target.value));
                  setCurrentPage(1);
                }}
                className="text-xs font-bold text-slate-800 outline-none bg-transparent border border-[#DADCE0] rounded-lg p-1.5 focus:border-[#1A73E8]"
              >
                <option value={10}>10</option>
                <option value={20}>20</option>
                <option value={50}>50</option>
                <option value={0}>Semua</option>
              </select>
            </div>
            <div className="flex items-center gap-4 text-xs font-medium text-slate-500">
              <span>
                {currentPage} dari {totalPages}
              </span>
              <div className="flex gap-1.5">
                <button
                  onClick={() => setCurrentPage((p) => Math.max(1, p - 1))}
                  disabled={currentPage === 1}
                  className="p-1.5 font-bold bg-white border border-[#DADCE0] hover:bg-[#F8F9FA] rounded-lg disabled:opacity-30 shadow-sm"
                >
                  Sebelumnya
                </button>
                <button
                  onClick={() =>
                    setCurrentPage((p) => Math.min(totalPages, p + 1))
                  }
                  disabled={currentPage === totalPages}
                  className="p-1.5 font-bold bg-white border border-[#DADCE0] hover:bg-[#F8F9FA] rounded-lg disabled:opacity-30 shadow-sm"
                >
                  Selanjutnya
                </button>
              </div>
            </div>
          </div>
        </div>
      )}

      {/* MODAL DETAIL DENGAN FITUR EDIT */}
      {isDetailOpen && selectedCrew && (
        <div className="fixed inset-0 z-[200] flex items-center justify-center p-4 bg-slate-900/40 backdrop-blur-sm animate-in fade-in duration-200">
          <div className="bg-white rounded-2xl w-full max-w-xl shadow-2xl flex flex-col max-h-[90vh] overflow-hidden">
            <div className="px-6 py-4 border-b border-[#DADCE0] flex justify-between items-center bg-white">
              <h2 className="text-lg font-bold text-slate-800">
                {isEditingData ? "Edit Data Pelamar" : "Profil Lengkap Pelamar"}
              </h2>
              <div className="flex gap-3 items-center">
                {!isEditingData && (
                  <button
                    onClick={() => setIsEditingData(true)}
                    className="text-xs font-bold text-[#1A73E8] bg-blue-50 hover:bg-blue-100 px-3 py-1.5 rounded-lg transition-colors border border-blue-200"
                  >
                    ✏️ Edit Data
                  </button>
                )}
                <button
                  onClick={() => setIsDetailOpen(false)}
                  className="text-slate-400 hover:text-slate-600 bg-slate-50 hover:bg-slate-100 p-1.5 rounded-full transition-colors font-bold"
                >
                  ✕
                </button>
              </div>
            </div>

            <div className="flex-1 overflow-y-auto px-6 py-5 custom-scrollbar text-sm text-slate-800 space-y-6">
              {/* HEADER PROFIL */}
              <div className="flex flex-col sm:flex-row items-center sm:items-start gap-5">
                {selectedCrew.fotoIdCard ? (
                  <img
                    src={selectedCrew.fotoIdCard}
                    alt="Pas Foto"
                    className="w-24 h-32 object-cover rounded-xl border border-[#DADCE0] shadow-sm shrink-0"
                  />
                ) : (
                  <div className="w-24 h-32 bg-slate-100 border border-[#DADCE0] rounded-xl flex items-center justify-center text-slate-400 shrink-0 text-xs text-center p-2 font-medium">
                    Tanpa Foto
                  </div>
                )}

                <div className="flex-1 text-center sm:text-left w-full">
                  {isEditingData ? (
                    <div className="space-y-2">
                      <input
                        type="text"
                        name="nama"
                        value={editFormData.nama || ""}
                        onChange={handleEditChange}
                        className="w-full text-lg font-bold p-2 border border-[#1A73E8] rounded-lg outline-none"
                        placeholder="Nama Lengkap"
                      />
                      <div className="flex gap-2">
                        <select
                          name="jenisKelamin"
                          value={editFormData.jenisKelamin || ""}
                          onChange={handleEditChange}
                          className="flex-1 p-2 border border-[#1A73E8] rounded-lg text-xs outline-none font-medium"
                        >
                          <option value="Laki-laki">Laki-laki</option>
                          <option value="Perempuan">Perempuan</option>
                        </select>
                        <select
                          name="tipe"
                          value={editFormData.tipe || ""}
                          onChange={handleEditChange}
                          className="flex-1 p-2 border border-[#1A73E8] rounded-lg text-xs outline-none uppercase font-medium"
                        >
                          <option value="mahasiswa">Mahasiswa</option>
                          <option value="alumni">Alumni</option>
                          <option value="ukm">UKM</option>
                          <option value="himpunan">Himpunan</option>
                          <option value="umum">Umum</option>
                        </select>
                      </div>
                      <div className="flex gap-2">
                        <input
                          type="text"
                          name="tempatLahir"
                          value={editFormData.tempatLahir || ""}
                          onChange={handleEditChange}
                          className="flex-1 p-2 border border-[#1A73E8] rounded-lg text-xs outline-none font-medium"
                          placeholder="Tempat Lahir"
                        />
                        <input
                          type="date"
                          name="tanggalLahir"
                          value={editFormData.tanggalLahir || ""}
                          onChange={handleEditChange}
                          className="flex-1 p-2 border border-[#1A73E8] rounded-lg text-xs outline-none font-medium"
                        />
                      </div>
                    </div>
                  ) : (
                    <>
                      <h3 className="text-2xl font-black mb-1 text-[#1A73E8]">
                        {selectedCrew.nama}
                      </h3>
                      <div className="flex flex-wrap items-center justify-center sm:justify-start gap-2 mt-1">
                        <span className="text-slate-600 uppercase text-[10px] font-bold tracking-widest bg-slate-100 border border-[#DADCE0] px-2 py-0.5 rounded">
                          {selectedCrew.tipe}
                        </span>
                        <span className="text-slate-500 text-xs font-bold">
                          Terdaftar:{" "}
                          {new Date(
                            selectedCrew.waktuDaftar,
                          ).toLocaleDateString("id-ID")}
                        </span>
                      </div>
                      <div className="mt-4 grid grid-cols-2 gap-3 text-left bg-[#F8F9FA] p-3 rounded-lg border border-[#DADCE0]">
                        <div>
                          <p className="text-[10px] text-slate-500 font-bold uppercase tracking-wider">
                            Jenis Kelamin
                          </p>
                          <p className="text-xs font-bold">
                            {selectedCrew.jenisKelamin || "-"}
                          </p>
                        </div>
                        <div>
                          <p className="text-[10px] text-slate-500 font-bold uppercase tracking-wider">
                            Tempat, Tgl Lahir
                          </p>
                          <p className="text-xs font-bold">
                            {selectedCrew.tempatLahir
                              ? `${selectedCrew.tempatLahir}, ${selectedCrew.tanggalLahir}`
                              : "-"}
                          </p>
                        </div>
                      </div>
                    </>
                  )}
                </div>
              </div>

              <div className="grid grid-cols-1 md:grid-cols-2 gap-x-6 gap-y-3 py-4 border-y border-[#DADCE0] text-sm">
                <div className="flex flex-col">
                  <span className="text-slate-500 font-bold text-xs">
                    WhatsApp
                  </span>
                  {isEditingData ? (
                    <input
                      type="text"
                      name="whatsapp"
                      value={editFormData.whatsapp || ""}
                      onChange={handleEditChange}
                      className="p-1.5 border border-[#1A73E8] rounded mt-1 text-sm outline-none font-medium"
                    />
                  ) : (
                    <span className="font-bold">{selectedCrew.whatsapp}</span>
                  )}
                </div>
                <div className="flex flex-col">
                  <span className="text-slate-500 font-bold text-xs">
                    Email
                  </span>
                  {isEditingData ? (
                    <input
                      type="email"
                      name="email"
                      value={editFormData.email || ""}
                      onChange={handleEditChange}
                      className="p-1.5 border border-[#1A73E8] rounded mt-1 text-sm outline-none font-medium"
                    />
                  ) : (
                    <span className="font-bold truncate">
                      {selectedCrew.email}
                    </span>
                  )}
                </div>
                <div className="flex flex-col">
                  <span className="text-slate-500 font-bold text-xs">
                    Instagram
                  </span>
                  {isEditingData ? (
                    <input
                      type="text"
                      name="instagram"
                      value={editFormData.instagram || ""}
                      onChange={handleEditChange}
                      className="p-1.5 border border-[#1A73E8] rounded mt-1 text-sm outline-none font-medium"
                    />
                  ) : (
                    <a
                      href={`https://instagram.com/${(selectedCrew.instagram || "").replace("@", "")}`}
                      target="_blank"
                      className="font-bold text-[#1A73E8] hover:underline"
                    >
                      {selectedCrew.instagram || "-"}
                    </a>
                  )}
                </div>
                <div className="flex flex-col">
                  <span className="text-slate-500 font-bold text-xs">
                    Ukuran Jersey
                  </span>
                  {isEditingData ? (
                    <select
                      name="ukuranJersey"
                      value={editFormData.ukuranJersey || ""}
                      onChange={handleEditChange}
                      className="p-1.5 border border-[#1A73E8] rounded mt-1 text-sm outline-none font-medium"
                    >
                      <option value="S">S</option>
                      <option value="M">M</option>
                      <option value="L">L</option>
                      <option value="XL">XL</option>
                      <option value="XXL">XXL</option>
                    </select>
                  ) : (
                    <span className="font-bold">
                      {selectedCrew.ukuranJersey || "-"}
                    </span>
                  )}
                </div>
                <div className="flex flex-col md:col-span-2 bg-rose-50 border border-rose-100 p-2.5 rounded-lg mt-1">
                  <span className="text-rose-600 font-black text-[10px] uppercase tracking-wider mb-0.5">
                    Riwayat Penyakit Khusus
                  </span>
                  {isEditingData ? (
                    <input
                      type="text"
                      name="riwayatPenyakit"
                      value={editFormData.riwayatPenyakit || ""}
                      onChange={handleEditChange}
                      className="p-1.5 border border-[#1A73E8] rounded mt-1 text-sm outline-none text-rose-800 font-bold"
                    />
                  ) : (
                    <span className="font-bold text-rose-800 text-xs">
                      {selectedCrew.riwayatPenyakit || "-"}
                    </span>
                  )}
                </div>
              </div>

              <div className="space-y-3 py-2 text-sm">
                <div className="flex flex-col border-b border-slate-100 pb-2">
                  <span className="text-slate-500 font-bold text-xs mb-1">
                    Akademik / Jurusan / Angkatan
                  </span>
                  {isEditingData ? (
                    <div className="flex gap-2">
                      <input
                        type="text"
                        name="fakultas"
                        value={editFormData.fakultas || ""}
                        onChange={handleEditChange}
                        placeholder="Fakultas/Jurusan"
                        className="flex-1 p-1.5 border border-[#1A73E8] rounded text-sm outline-none font-medium"
                      />
                      <input
                        type="number"
                        name="angkatan"
                        value={editFormData.angkatan || ""}
                        onChange={handleEditChange}
                        placeholder="Tahun"
                        className="w-24 p-1.5 border border-[#1A73E8] rounded text-sm outline-none font-medium"
                      />
                    </div>
                  ) : (
                    <span className="font-bold text-left">
                      {selectedCrew.fakultas || "-"} (Angkatan '
                      {selectedCrew.angkatan || "-"})
                    </span>
                  )}
                </div>

                <div className="flex flex-col border-b border-slate-100 pb-2">
                  <span className="text-slate-500 font-bold text-xs mb-1 whitespace-nowrap">
                    {isEditingData
                      ? "Instansi & Jabatan"
                      : selectedCrew.tipe === "alumni" ||
                          selectedCrew.tipe === "umum"
                        ? "Pekerjaan / Instansi"
                        : "Organisasi"}
                  </span>
                  {isEditingData ? (
                    <div className="flex gap-2">
                      <input
                        type="text"
                        name="instansi"
                        value={editFormData.instansi || ""}
                        onChange={handleEditChange}
                        placeholder="Instansi/Organisasi"
                        className="flex-1 p-1.5 border border-[#1A73E8] rounded text-sm outline-none font-medium"
                      />
                      <input
                        type="text"
                        name="jabatan"
                        value={editFormData.jabatan || ""}
                        onChange={handleEditChange}
                        placeholder="Jabatan"
                        className="flex-1 p-1.5 border border-[#1A73E8] rounded text-sm outline-none font-medium"
                      />
                    </div>
                  ) : (
                    <span className="font-bold text-left break-words">
                      {selectedCrew.instansi || "-"}{" "}
                      {selectedCrew.jabatan ? `— ${selectedCrew.jabatan}` : ""}
                    </span>
                  )}
                </div>

                <div className="flex flex-col border-b border-slate-100 pb-2">
                  <span className="text-slate-500 font-bold text-xs mb-1">
                    Alamat Domisili
                  </span>
                  {isEditingData ? (
                    <textarea
                      name="domisili"
                      value={editFormData.domisili || ""}
                      onChange={handleEditChange}
                      rows={2}
                      className="w-full p-2 border border-[#1A73E8] rounded text-sm outline-none resize-none font-medium"
                    />
                  ) : (
                    <span className="font-bold text-left break-words">
                      {selectedCrew.domisili || "-"}
                    </span>
                  )}
                </div>
              </div>

              {!isEditingData && (
                <div className="space-y-4">
                  <div className="grid grid-cols-1 sm:grid-cols-2 gap-3 bg-[#E8F0FE]/50 p-4 rounded-xl border border-[#1A73E8]/20 mt-4">
                    <div className="flex flex-col gap-1">
                      <span className="text-[10px] font-bold text-blue-800 uppercase tracking-wider">
                        Kendaraan Pribadi
                      </span>
                      <span className="text-xs font-bold text-slate-700">
                        {selectedCrew.kendaraan || "-"}
                      </span>
                    </div>
                    <div className="flex flex-col gap-1">
                      <span className="text-[10px] font-bold text-blue-800 uppercase tracking-wider">
                        Bersedia Pindah Divisi?
                      </span>
                      <span className="text-xs font-bold text-slate-700">
                        {selectedCrew.bersediaPindahDivisi || "-"}
                      </span>
                    </div>
                    <div className="flex flex-col gap-1 sm:col-span-2">
                      <span className="text-[10px] font-bold text-blue-800 uppercase tracking-wider">
                        Komitmen Pelatihan & Briefing
                      </span>
                      <span className="text-xs font-bold text-slate-700">
                        {selectedCrew.bersediaPelatihan || "-"}
                      </span>
                    </div>
                  </div>

                  {selectedCrew.status === "rejected" && selectedCrew.alasanTolak && (
                    <div className="bg-red-50 border-l-4 border-[#D93025] p-4 rounded-r-xl mt-4">
                      <span className="text-xs font-black text-[#D93025] uppercase tracking-widest block mb-1">
                        Alasan Penolakan
                      </span>
                      <p className="text-sm font-medium text-red-900 leading-relaxed">
                        {selectedCrew.alasanTolak}
                      </p>
                    </div>
                  )}

                  <div>
                    <span className="text-xs font-bold text-slate-600 block mb-1.5 uppercase tracking-widest">
                      Riwayat Penyakit Khusus
                    </span>
                    <div className="bg-[#F8F9FA] p-4 rounded-xl border border-[#DADCE0] whitespace-pre-wrap leading-relaxed text-[13px] shadow-inner text-slate-700 font-medium">
                      {selectedCrew.riwayatPenyakit || "-"}
                    </div>
                  </div>

                  <div>
                    <span className="text-xs font-bold text-slate-600 block mb-1.5 uppercase tracking-widest">
                      Alasan Memilih Divisi
                    </span>
                    <div className="bg-[#F8F9FA] p-4 rounded-xl border border-[#DADCE0] whitespace-pre-wrap leading-relaxed text-[13px] shadow-inner text-slate-700 font-medium">
                      {selectedCrew.alasanDivisi || "-"}
                    </div>
                  </div>
                  <div>
                    <span className="text-xs font-bold text-slate-600 block mb-1.5 uppercase tracking-widest">
                      Motivasi Bergabung
                    </span>
                    <div className="bg-[#F8F9FA] p-4 rounded-xl border border-[#DADCE0] whitespace-pre-wrap leading-relaxed text-[13px] shadow-inner text-slate-700 font-medium">
                      {selectedCrew.motivasi || "-"}
                    </div>
                  </div>
                  <div>
                    <span className="text-xs font-bold text-slate-600 block mb-1.5 uppercase tracking-widest">
                      Pengalaman Terkait
                    </span>
                    <div className="bg-[#F8F9FA] p-4 rounded-xl border border-[#DADCE0] whitespace-pre-wrap leading-relaxed text-[13px] shadow-inner text-slate-700 font-medium">
                      {selectedCrew.pengalaman || "-"}
                    </div>
                  </div>
                </div>
              )}

              {!isEditingData && selectedCrew.status !== "rejected" && (
                <div className="pt-3">
                  <label className="text-xs font-black text-[#1A73E8] block mb-2">
                    Ubah Penempatan (Admin):
                  </label>
                  <select
                    value={newAssignedRoleId}
                    onChange={(e) => setNewAssignedRoleId(e.target.value)}
                    className="w-full p-3 bg-white border border-[#1A73E8] rounded-xl text-sm font-bold text-slate-800 outline-none focus:ring-2 focus:ring-[#1A73E8]/20 shadow-sm cursor-pointer"
                  >
                    <option value="">-- Pindah Posisi / Data Lama --</option>
                    {events.map((e) =>
                      (e.groups || []).map((g) => (
                        <optgroup key={g.id} label={`${e.title} - ${g.title}`}>
                          {(g.roles || []).map((r) => {
                            const filledCount = getRoleFilledCount(r.id);
                            return (
                              <option key={r.id} value={r.id}>
                                {r.nama} (Terisi: {filledCount}/{r.kuota})
                              </option>
                            );
                          })}
                        </optgroup>
                      )),
                    )}
                  </select>
                </div>
              )}
            </div>

            <div className="px-6 py-4 border-t border-[#DADCE0] flex justify-end gap-3 bg-[#F8F9FA]">
              {isEditingData ? (
                <>
                  <button
                    onClick={() => setIsEditingData(false)}
                    className="text-slate-600 bg-white border border-slate-300 hover:bg-slate-50 px-5 py-2.5 rounded-xl text-sm font-bold transition-colors shadow-sm"
                  >
                    Batal
                  </button>
                  <button
                    onClick={saveEditedData}
                    className="bg-[#1A73E8] hover:bg-[#1557B0] text-white px-6 py-2.5 rounded-xl text-sm font-bold transition-colors shadow-md"
                  >
                    💾 Simpan Data
                  </button>
                </>
              ) : (
                <>
                  <button
                    onClick={() => setIsDetailOpen(false)}
                    className="text-slate-600 bg-white border border-slate-300 hover:bg-slate-50 px-5 py-2.5 rounded-xl text-sm font-bold transition-colors shadow-sm"
                  >
                    Tutup
                  </button>

                  {selectedCrew.status === "rejected" && (
                    <>
                      <button
                        onClick={handleResendEmail}
                        disabled={isSendingMail}
                        className="bg-white border border-slate-300 text-slate-700 hover:bg-slate-50 px-4 py-2.5 rounded-xl text-sm font-bold transition-colors shadow-sm flex items-center gap-2"
                      >
                        {isSendingMail ? "Memproses..." : "✉️ Kirim Ulang Penolakan"}
                      </button>
                      <button
                        onClick={() => handleDecision("pending")}
                        className="bg-amber-500 hover:bg-amber-600 text-white px-6 py-2.5 rounded-xl text-sm font-bold transition-colors shadow-md"
                      >
                        Pulihkan ke Menunggu
                      </button>
                    </>
                  )}

                  {selectedCrew.status !== "accepted" &&
                    selectedCrew.status !== "rejected" && (
                      <>
                        <button
                          onClick={() => handleDecision("rejected")}
                          className="text-[#D93025] bg-white border border-rose-200 hover:bg-red-50 px-5 py-2.5 rounded-xl text-sm font-bold transition-colors shadow-sm"
                        >
                          Tolak
                        </button>
                        <button
                          onClick={() => handleDecision("accepted")}
                          className="bg-[#1A73E8] hover:bg-[#1557B0] text-white px-6 py-2.5 rounded-xl text-sm font-bold transition-colors shadow-md"
                        >
                          Terima Relawan
                        </button>
                      </>
                    )}
                  {selectedCrew.status === "accepted" && (
                    <>
                      <button
                        onClick={handleResendEmail}
                        disabled={isSendingMail}
                        className="bg-white border border-slate-300 text-slate-700 hover:bg-slate-50 px-4 py-2.5 rounded-xl text-sm font-bold transition-colors shadow-sm flex items-center gap-2"
                      >
                        {isSendingMail ? "Memproses..." : "✉️ Kirim Ulang Undangan"}
                      </button>
                      <button
                        onClick={() => handleDecision("rejected")}
                        className="text-[#D93025] bg-white border border-rose-200 hover:bg-red-50 px-5 py-2.5 rounded-xl text-sm font-bold transition-colors shadow-sm"
                      >
                        Keluarkan
                      </button>
                      <button
                        onClick={handleUpdateRoleOnly}
                        className="bg-[#1A73E8] hover:bg-[#1557B0] text-white px-6 py-2.5 rounded-xl text-sm font-bold transition-colors shadow-md"
                      >
                        Simpan Perubahan
                      </button>
                    </>
                  )}
                </>
              )}
            </div>
          </div>
        </div>
      )}
      {/* MODAL GENERIC CONFIRM */}
      {genericConfirm.isOpen && (
        <div className="fixed inset-0 z-[9999] flex items-center justify-center p-4 bg-slate-900/50 backdrop-blur-sm animate-in fade-in duration-200">
          <div className="bg-white rounded-2xl w-full max-w-sm overflow-hidden shadow-2xl flex flex-col animate-in zoom-in-95 duration-300">
            <div className="p-6 text-center">
              <div className="w-16 h-16 bg-blue-50 text-blue-500 rounded-full flex items-center justify-center mx-auto mb-4 border border-blue-100">
                <svg className="w-8 h-8" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={2}>
                  <path strokeLinecap="round" strokeLinejoin="round" d="M13 16h-1v-4h-1m1-4h.01M21 12a9 9 0 11-18 0 9 9 0 0118 0z" />
                </svg>
              </div>
              <h2 className="text-xl font-black text-slate-800 tracking-tight mb-2">
                {genericConfirm.title}
              </h2>
              <p className="text-sm font-medium text-slate-600">
                {genericConfirm.message}
              </p>
            </div>
            <div className="px-6 py-4 border-t border-[#DADCE0] flex justify-end gap-3 bg-[#F8F9FA]">
              <button
                onClick={() => setGenericConfirm({ ...genericConfirm, isOpen: false })}
                className="text-slate-600 bg-white border border-slate-300 hover:bg-slate-50 px-5 py-2.5 rounded-xl text-sm font-bold transition-colors shadow-sm w-full"
              >
                Batal
              </button>
              <button
                onClick={genericConfirm.onConfirm}
                className="bg-[#1A73E8] hover:bg-[#1557B0] text-white px-6 py-2.5 rounded-xl text-sm font-bold transition-colors shadow-md w-full"
              >
                Konfirmasi
              </button>
            </div>
          </div>
        </div>
      )}

      {/* MODAL ALASAN PENOLAKAN */}
      {rejectModalOpen && (
        <div className="fixed inset-0 z-[9999] flex items-center justify-center p-4 bg-slate-900/50 backdrop-blur-sm animate-in fade-in duration-200">
          <div className="bg-white rounded-2xl w-full max-w-lg overflow-hidden shadow-2xl flex flex-col animate-in zoom-in-95 duration-300">
            <div className="px-6 py-5 border-b border-[#DADCE0] bg-[#F8F9FA] flex justify-between items-center">
              <h2 className="text-xl font-black text-slate-800 tracking-tight flex items-center gap-2">
                <span className="text-[#D93025]">Alasan Penolakan</span>
              </h2>
              <button
                onClick={() => {
                  setRejectModalOpen(false);
                  setPendingRejectAction(null);
                }}
                className="text-slate-400 hover:text-slate-600 transition-colors"
              >
                ✕
              </button>
            </div>
            <div className="p-6">
              <p className="text-sm font-medium text-slate-600 mb-4">
                Masukkan alasan mengapa kandidat ini ditolak. Alasan ini akan dikirimkan langsung ke email kandidat.
              </p>
              <textarea
                value={rejectReasonInput}
                onChange={(e) => setRejectReasonInput(e.target.value)}
                placeholder="Contoh: Kualifikasi yang dibutuhkan belum sesuai dengan posisi ini..."
                className="w-full p-4 border border-[#DADCE0] rounded-xl text-sm font-medium outline-none focus:border-[#D93025] focus:ring-4 focus:ring-red-50 transition-all resize-none h-32 text-slate-800 placeholder:text-slate-400"
              />
            </div>
            <div className="px-6 py-4 border-t border-[#DADCE0] flex justify-end gap-3 bg-[#F8F9FA]">
              <button
                onClick={() => {
                  setRejectModalOpen(false);
                  setPendingRejectAction(null);
                }}
                className="text-slate-600 bg-white border border-slate-300 hover:bg-slate-50 px-5 py-2.5 rounded-xl text-sm font-bold transition-colors shadow-sm"
              >
                Batal
              </button>
              <button
                onClick={executeReject}
                className="bg-[#D93025] hover:bg-[#B3261E] text-white px-6 py-2.5 rounded-xl text-sm font-bold transition-colors shadow-md flex items-center gap-2"
              >
                Konfirmasi Penolakan
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

"use client";

import { useState, useEffect } from "react";
import { auth, db } from "@/lib/firebase";
import { onAuthStateChanged, signInWithEmailAndPassword, GoogleAuthProvider, signInWithPopup } from "firebase/auth";
import { doc, getDoc } from "firebase/firestore";
import { usePathname } from "next/navigation";

import { Shield } from "lucide-react";
import Sidebar from "@/components/admin-vr/Sidebar";
import Header from "@/components/admin-vr/Header";

const ADMIN_ROLES = ["admin", "super_admin", "superadmin"];

export default function AdminVRLayout({
  children,
}: {
  children: React.ReactNode;
}) {
  const [user, setUser] = useState<any>(null);
  const [emailLogin, setEmailLogin] = useState("");
  const [passwordLogin, setPasswordLogin] = useState("");
  const [isLoggingIn, setIsLoggingIn] = useState(false);
  const [isAuthChecking, setIsAuthChecking] = useState(true);
  const [errorMsg, setErrorMsg] = useState("");
  const [isVerifiedAdmin, setIsVerifiedAdmin] = useState(false);

  // 🔥 STATE KHUSUS UNTUK HAMBURGER MENU (MOBILE) 🔥
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);

  const pathname = usePathname();
  const isDisplayControl = pathname === "/admin-vr/race-display";

  useEffect(() => {
    const unsubscribe = onAuthStateChanged(auth, async (currentUser) => {
      setUser(currentUser);
      if (currentUser) {
        // Verifikasi role admin dari Firestore
        try {
          const userDoc = await getDoc(doc(db, "users", currentUser.uid));
          if (userDoc.exists()) {
            const role = String(userDoc.data()?.role || "").toLowerCase();
            if (ADMIN_ROLES.includes(role)) {
              setIsVerifiedAdmin(true);
            } else {
              setErrorMsg("Akun Anda tidak memiliki hak akses Admin.");
              setUser(null); // Paksa ke login screen
            }
          } else {
            // Cek admin_emails sebagai fallback (self-healing dari server)
            const emailKey = currentUser.email?.toLowerCase() || "";
            const adminEmailDoc = await getDoc(doc(db, "admin_emails", emailKey));
            if (adminEmailDoc.exists() && adminEmailDoc.data()?.active) {
              setIsVerifiedAdmin(true);
            } else {
              setErrorMsg("Akun Anda tidak memiliki hak akses Admin.");
              setUser(null);
            }
          }
        } catch {
          // Jika Firestore gagal, tetap izinkan — backend API route tetap memvalidasi
          setIsVerifiedAdmin(true);
        }
      } else {
        setIsVerifiedAdmin(false);
      }
      setIsAuthChecking(false);
    });
    return () => unsubscribe();
  }, []);

  const handleLogin = async (e: React.FormEvent) => {
    e.preventDefault();
    setIsLoggingIn(true);
    setErrorMsg("");
    try {
      await signInWithEmailAndPassword(auth, emailLogin, passwordLogin);
    } catch (error: any) {
      setErrorMsg("Email atau Password salah. Akses ditolak.");
    } finally {
      setIsLoggingIn(false);
    }
  };

  const handleGoogleLogin = async () => {
    setIsLoggingIn(true);
    setErrorMsg("");
    try {
      const provider = new GoogleAuthProvider();
      await signInWithPopup(auth, provider);
    } catch (error: any) {
      if (error.code !== "auth/popup-closed-by-user") {
        setErrorMsg("Gagal masuk dengan Google. Akses ditolak.");
      }
    } finally {
      setIsLoggingIn(false);
    }
  };

  if (isAuthChecking) {
    return (
      <div className="min-h-screen bg-slate-50 flex items-center justify-center font-bold text-slate-500 uppercase tracking-widest text-sm animate-pulse">
        Memeriksa Otorisasi...
      </div>
    );
  }

  // Jika belum login, tampilkan form login
  if (!user) {
    return (
      <div className="min-h-screen w-full flex flex-col lg:flex-row font-sans bg-white">
        {/* SISI KIRI: BRANDING */}
        <div className="hidden lg:flex w-full lg:w-5/12 bg-gradient-to-br from-[#0B1528] to-[#1A73E8] p-12 lg:p-20 flex-col justify-between relative overflow-hidden shrink-0 min-h-screen">
          <div className="absolute top-0 right-0 w-80 h-80 bg-white opacity-5 rounded-full blur-3xl -translate-y-1/2 translate-x-1/3 pointer-events-none"></div>
          <div className="absolute bottom-0 left-0 w-64 h-64 bg-blue-400 opacity-20 rounded-full blur-3xl translate-y-1/2 -translate-x-1/4 pointer-events-none"></div>

          <div className="relative z-10 flex flex-col justify-center h-full">
            <div className="w-20 h-20 bg-white/10 backdrop-blur-md rounded-[1.2rem] p-3 mb-10 shadow-xl border border-white/20 transform -rotate-3 flex items-center justify-center">
              <Shield className="w-10 h-10 text-white" />
            </div>

            <h1 className="text-4xl lg:text-5xl font-black text-white tracking-tight mb-4 leading-tight">
              Control Room <br />
              <span className="text-yellow-400">Virtual Run</span>
            </h1>
            <div className="w-12 h-1.5 bg-yellow-500 rounded-full mb-8"></div>
            <p className="text-blue-100/90 font-medium text-base leading-relaxed max-w-sm">
              Sistem manajemen pusat untuk mengontrol dan memantau jalannya acara Virtual Run. Autentikasi diperlukan.
            </p>
          </div>

          <div className="relative z-10">
            <p className="text-blue-300/50 text-[10px] font-mono tracking-widest uppercase">
              &copy; {new Date().getFullYear()} SIM DPW IKA UII DIY • Security
            </p>
          </div>
        </div>

        {/* SISI KANAN: FORM */}
        <div className="w-full lg:w-7/12 min-h-screen p-8 sm:p-16 lg:p-24 flex flex-col justify-center bg-white relative z-20 overflow-y-auto">
          <div className="max-w-[420px] w-full mx-auto">
            {/* Header Mobile */}
            <div className="lg:hidden flex flex-col items-center text-center mb-10 animate-in fade-in slide-in-from-top-4 duration-500">
              <div className="w-16 h-16 bg-blue-50 rounded-2xl shadow-sm border border-blue-100 flex items-center justify-center mb-4 p-2 transform -rotate-3">
                <Shield className="w-8 h-8 text-blue-600" />
              </div>
              <h1 className="text-3xl font-black text-blue-950 tracking-tight leading-none mb-1.5">
                Control Room
              </h1>
              <p className="text-xs font-bold text-yellow-600 tracking-[0.2em] uppercase">Virtual Run</p>
            </div>

            <div className="mb-10 lg:mb-12 text-center lg:text-left transition-all duration-300">
              <h2 className="text-3xl lg:text-4xl font-black text-slate-800 tracking-tight mb-2.5">Admin Security</h2>
              <p className="text-slate-500 text-sm lg:text-base font-medium">
                Silakan login untuk mengakses Control Room.
              </p>
            </div>

            <form onSubmit={handleLogin} className="space-y-5 lg:space-y-6">
              {errorMsg && (
                <div className="bg-red-50 border border-red-100 text-red-600 text-xs sm:text-sm font-bold p-4 rounded-xl flex items-center gap-2">
                  <svg className="w-5 h-5 shrink-0" fill="currentColor" viewBox="0 0 20 20">
                    <path fillRule="evenodd" d="M18 10a8 8 0 11-16 0 8 8 0 0116 0zm-7 4a1 1 0 11-2 0 1 1 0 012 0zm-1-9a1 1 0 00-1 1v4a1 1 0 102 0V6a1 1 0 00-1-1z" clipRule="evenodd" />
                  </svg>
                  {errorMsg}
                </div>
              )}

              {/* TOMBOL GOOGLE */}
              <button
                type="button"
                onClick={handleGoogleLogin}
                disabled={isLoggingIn}
                className="w-full bg-white border border-slate-200 hover:bg-slate-50 text-slate-700 font-bold py-4 rounded-xl transition-all flex items-center justify-center gap-3 shadow-sm hover:shadow disabled:opacity-70 disabled:pointer-events-none"
              >
                {isLoggingIn ? (
                  <svg className="w-5 h-5 animate-spin" fill="none" viewBox="0 0 24 24">
                    <circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4"></circle>
                    <path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4z"></path>
                  </svg>
                ) : (
                  <>
                    <svg className="w-5 h-5" viewBox="0 0 24 24">
                      <path fill="#4285F4" d="M22.56 12.25c0-.78-.07-1.53-.2-2.25H12v4.26h5.92c-.26 1.37-1.04 2.53-2.21 3.31v2.77h3.57c2.08-1.92 3.28-4.74 3.28-8.09z"/>
                      <path fill="#34A853" d="M12 23c2.97 0 5.46-.98 7.28-2.66l-3.57-2.77c-.98.66-2.23 1.06-3.71 1.06-2.86 0-5.29-1.93-6.16-4.53H2.18v2.84C3.99 20.53 7.7 23 12 23z"/>
                      <path fill="#FBBC05" d="M5.84 14.09c-.22-.66-.35-1.36-.35-2.09s.13-1.43.35-2.09V7.07H2.18C1.43 8.55 1 10.22 1 12s.43 3.45 1.18 4.93l2.85-2.22.81-.62z"/>
                      <path fill="#EA4335" d="M12 5.38c1.62 0 3.06.56 4.21 1.64l3.15-3.15C17.45 2.09 14.97 1 12 1 7.7 1 3.99 3.47 2.18 7.07l3.66 2.84c.87-2.6 3.3-4.53 6.16-4.53z"/>
                    </svg>
                    Masuk dengan Google
                  </>
                )}
              </button>

              <div className="flex items-center gap-4 my-2">
                <div className="flex-1 h-px bg-slate-200"></div>
                <span className="text-xs font-medium text-slate-400 uppercase tracking-widest">ATAU</span>
                <div className="flex-1 h-px bg-slate-200"></div>
              </div>

              <div>
                <label className="block text-xs font-bold text-slate-500 uppercase tracking-widest mb-2 pl-1">Email Admin</label>
                <input
                  type="email"
                  required
                  value={emailLogin}
                  onChange={(e) => setEmailLogin(e.target.value)}
                  className="w-full bg-slate-50 border border-slate-200 px-5 py-4 lg:py-4.5 rounded-xl outline-none focus:border-blue-500 focus:ring-2 focus:ring-blue-500/20 transition-all text-slate-800 text-sm font-semibold"
                  placeholder="admin@ikadiy.uii.ac.id"
                />
              </div>
              <div>
                <label className="block text-xs font-bold text-slate-500 uppercase tracking-widest mb-2 pl-1">Kata Sandi</label>
                <input
                  type="password"
                  required
                  value={passwordLogin}
                  onChange={(e) => setPasswordLogin(e.target.value)}
                  className="w-full bg-slate-50 border border-slate-200 px-5 py-4 lg:py-4.5 rounded-xl outline-none focus:border-blue-500 focus:ring-2 focus:ring-blue-500/20 transition-all text-slate-800 text-sm font-semibold"
                  placeholder="••••••••"
                />
              </div>

              <button
                type="submit"
                disabled={isLoggingIn}
                className="w-full bg-[#1A73E8] hover:bg-blue-700 text-white font-black py-4 lg:py-4.5 rounded-xl transition-all shadow-lg shadow-blue-500/30 hover:shadow-blue-600/40 flex items-center justify-center text-sm uppercase tracking-widest mt-6 disabled:opacity-50"
              >
                {isLoggingIn ? "Memeriksa..." : "Login System"}
              </button>
            </form>
          </div>
        </div>
      </div>
    );
  }

  // Jika sudah login, tampilkan layout admin (Menu Kiri + Header Atas + Isi Halaman)
  return (
    <div className="flex h-screen bg-[#F4F7FB] font-sans selection:bg-blue-100 selection:text-blue-900 overflow-hidden relative">
      {/* Memanggil Komponen Sidebar DENGAN Props Mobile */}
      {!isDisplayControl && (
        <Sidebar isOpen={isSidebarOpen} setIsOpen={setIsSidebarOpen} />
      )}

      {/* Area Kanan */}
      <div className="flex-1 flex flex-col h-screen overflow-hidden w-full">
        {/* 🔥 HEADER HAMBURGER KHUSUS MOBILE (Muncul jika layar kecil) 🔥 */}
        {!isDisplayControl && (
          <div className="lg:hidden bg-white border-b border-slate-200 px-4 py-3 flex items-center justify-between z-30 shrink-0">
            <div className="flex items-center gap-3">
              <img
                src="/logo-dpp-ika.png"
                alt="Logo"
                className="w-8 h-8 object-contain"
              />
              <span className="font-black text-slate-800 text-sm">
                Admin Panel
              </span>
            </div>
            <button
              onClick={() => setIsSidebarOpen(true)}
              className="p-2 text-slate-600 bg-slate-100 hover:bg-slate-200 transition-colors rounded-lg"
            >
              {/* Ikon Hamburger */}
              <svg
                className="w-6 h-6"
                fill="none"
                stroke="currentColor"
                viewBox="0 0 24 24"
              >
                <path
                  strokeLinecap="round"
                  strokeLinejoin="round"
                  strokeWidth={2}
                  d="M4 6h16M4 12h16M4 18h16"
                />
              </svg>
            </button>
          </div>
        )}

        {/* Memanggil Komponen Header Asli Anda (Bisa disembunyikan di mobile jika perlu, atau dibiarkan) */}
        {!isDisplayControl && (
          <div className="hidden lg:block">
            <Header userEmail={user.email || "Admin"} />
          </div>
        )}

        {/* Isi Perut (page.tsx akan masuk ke {children} ini) */}
        <main className={`flex-1 overflow-y-auto custom-scrollbar relative ${isDisplayControl ? '' : 'p-4 md:p-6'}`}>
          {children}
        </main>
      </div>
    </div>
  );
}

"use client";

import { useState, useEffect } from "react";
import { db } from "@/lib/firebase";
import { doc, getDoc, setDoc } from "firebase/firestore";
import Link from "next/link";

export default function AdminLegalPage() {
  const [settings, setSettings] = useState<any>(null);
  const [isLoading, setIsLoading] = useState(true);
  const [isSaving, setIsSaving] = useState(false);
  const [popup, setPopup] = useState<{
    type: "success" | "error";
    text: string;
  } | null>(null);

  useEffect(() => {
    const fetchSettings = async () => {
      try {
        const docSnap = await getDoc(doc(db, "settings", "virtual_run"));
        if (docSnap.exists()) {
          setSettings(docSnap.data());
        }
      } catch (error) {
        console.error("Gagal load pengaturan:", error);
      } finally {
        setIsLoading(false);
      }
    };
    fetchSettings();
  }, []);

  const handleChange = (e: any) => {
    const { name, value } = e.target;
    setSettings({ ...settings, [name]: value });
  };

  const handleSave = async (e: React.FormEvent) => {
    e.preventDefault();
    setIsSaving(true);
    try {
      await setDoc(doc(db, "settings", "virtual_run"), settings, {
        merge: true,
      });
      setPopup({
        type: "success",
        text: "Data legal dan asuransi berhasil disimpan.",
      });
    } catch (error) {
      setPopup({ type: "error", text: "Gagal menyimpan perubahan." });
    } finally {
      setIsSaving(false);
      setTimeout(() => setPopup(null), 3000);
    }
  };

  if (isLoading) {
    return (
      <div className="h-screen flex flex-col items-center justify-center text-[#1A73E8] font-medium text-sm">
        <div className="w-8 h-8 border-4 border-blue-100 border-t-[#1A73E8] rounded-full animate-spin mb-4"></div>
        MEMUAT DATA...
      </div>
    );
  }

  return (
    <div className="max-w-4xl mx-auto pb-24 p-4 sm:p-8 font-sans animate-in fade-in duration-300">
      {/* POPUP NOTIFIKASI (Google Style) */}
      {popup && (
        <div className="fixed top-6 right-6 z-[100] animate-in slide-in-from-top-4 fade-in">
          <div className="bg-white rounded-xl shadow-lg border border-slate-200 p-4 flex items-center gap-4 min-w-[300px]">
            <div
              className={`w-8 h-8 rounded-full flex items-center justify-center shrink-0 ${
                popup.type === "success"
                  ? "bg-[#E6F4EA] text-[#1E8E3E]"
                  : "bg-[#FCE8E6] text-[#D93025]"
              }`}
            >
              {popup.type === "success" ? (
                <svg
                  className="w-5 h-5"
                  fill="currentColor"
                  viewBox="0 0 24 24"
                >
                  <path d="M9 16.2L4.8 12l-1.4 1.4L9 19 21 7l-1.4-1.4L9 16.2z" />
                </svg>
              ) : (
                <svg
                  className="w-5 h-5"
                  fill="currentColor"
                  viewBox="0 0 24 24"
                >
                  <path d="M12 2C6.48 2 2 6.48 2 12s4.48 10 10 10 10-4.48 10-10S17.52 2 12 2zm1 15h-2v-2h2v2zm0-4h-2V7h2v6z" />
                </svg>
              )}
            </div>
            <div className="flex-grow">
              <p className="text-sm font-bold text-slate-800">
                {popup.type === "success" ? "Berhasil" : "Gagal"}
              </p>
              <p className="text-xs text-slate-500 font-medium">{popup.text}</p>
            </div>
          </div>
        </div>
      )}

      {/* HEADER */}
      <div className="flex flex-col md:flex-row justify-between md:items-end gap-4 mb-8">
        <div>
          <h1 className="text-[28px] font-bold text-slate-800 tracking-tight">
            Legalitas & Persetujuan
          </h1>
          <p className="text-sm text-slate-500 mt-1">
            Kelola teks Syarat & Ketentuan (T&C) serta Asuransi Peserta.
          </p>
        </div>
        <div className="flex gap-2">
          <Link
            href="/admin-vr"
            className="bg-white border border-slate-200 text-slate-700 font-bold px-5 py-2.5 rounded-lg text-sm hover:bg-slate-50 transition-all shadow-sm"
          >
            Kembali
          </Link>
          <button
            onClick={handleSave}
            disabled={isSaving}
            className="bg-[#1A73E8] hover:bg-[#1557B0] text-white font-bold px-6 py-2.5 rounded-lg text-sm transition-colors shadow-sm disabled:opacity-50"
          >
            {isSaving ? "Menyimpan..." : "Simpan Dokumen Legal"}
          </button>
        </div>
      </div>

      <form onSubmit={handleSave} className="space-y-6">
        {/* TAMPILKAN JIKA OFFLINE AKTIF */}
        {settings?.isOfflineRunEnabled && (
          <div className="bg-white rounded-xl shadow-sm border border-slate-200 overflow-hidden">
            <div className="border-b border-slate-100 px-6 py-4 flex items-center gap-3 bg-white">
              <svg
                className="w-5 h-5 text-slate-500"
                fill="currentColor"
                viewBox="0 0 24 24"
              >
                <path d="M14 2H6c-1.1 0-1.99.9-1.99 2L4 20c0 1.1.89 2 1.99 2H18c1.1 0 2-.9 2-2V8l-6-6zm2 16H8v-2h8v2zm0-4H8v-2h8v2zm-3-5V3.5L18.5 9H13z" />
              </svg>
              <h2 className="font-bold text-slate-800 text-[15px]">
                Dokumen Offline Run
              </h2>
            </div>
            <div className="p-6 space-y-6 bg-[#F8F9FA]">
              <div>
                <label className="block text-xs font-bold text-slate-500 uppercase tracking-wide mb-2">
                  Syarat & Ketentuan (Offline)
                </label>
                <textarea
                  name="tncOffline"
                  value={settings.tncOffline || ""}
                  onChange={handleChange}
                  rows={6}
                  placeholder="Ketikkan syarat dan ketentuan untuk Offline Run di sini..."
                  className="w-full p-4 bg-white border border-slate-300 rounded-lg focus:border-[#1A73E8] focus:ring-1 focus:ring-[#1A73E8] outline-none text-sm transition-all text-slate-700"
                />
              </div>
              <div>
                <label className="block text-xs font-bold text-slate-500 uppercase tracking-wide mb-2">
                  Informasi Asuransi (Offline)
                </label>
                <textarea
                  name="insOffline"
                  value={settings.insOffline || ""}
                  onChange={handleChange}
                  rows={6}
                  placeholder="Ketikkan rincian pertanggungan asuransi untuk Offline Run di sini..."
                  className="w-full p-4 bg-white border border-slate-300 rounded-lg focus:border-[#1A73E8] focus:ring-1 focus:ring-[#1A73E8] outline-none text-sm transition-all text-slate-700"
                />
              </div>
            </div>
          </div>
        )}

        {/* TAMPILKAN JIKA VIRTUAL AKTIF */}
        {settings?.isVirtualRunEnabled && (
          <div className="bg-white rounded-xl shadow-sm border border-slate-200 overflow-hidden">
            <div className="border-b border-slate-100 px-6 py-4 flex items-center gap-3 bg-white">
              <svg
                className="w-5 h-5 text-slate-500"
                fill="currentColor"
                viewBox="0 0 24 24"
              >
                <path d="M19 3H5c-1.1 0-2 .9-2 2v14c0 1.1.9 2 2 2h14c1.1 0 2-.9 2-2V5c0-1.1-.9-2-2-2zm-5 14H7v-2h7v2zm3-4H7v-2h10v2zm0-4H7V7h10v2z" />
              </svg>
              <h2 className="font-bold text-slate-800 text-[15px]">
                Dokumen Virtual Run
              </h2>
            </div>
            <div className="p-6 space-y-6 bg-[#F8F9FA]">
              <div>
                <label className="block text-xs font-bold text-slate-500 uppercase tracking-wide mb-2">
                  Syarat & Ketentuan (Virtual)
                </label>
                <textarea
                  name="tncVirtual"
                  value={settings.tncVirtual || ""}
                  onChange={handleChange}
                  rows={6}
                  placeholder="Ketikkan syarat dan ketentuan untuk Virtual Run di sini..."
                  className="w-full p-4 bg-white border border-slate-300 rounded-lg focus:border-[#1A73E8] focus:ring-1 focus:ring-[#1A73E8] outline-none text-sm transition-all text-slate-700"
                />
              </div>
              <div>
                <label className="block text-xs font-bold text-slate-500 uppercase tracking-wide mb-2">
                  Informasi Asuransi (Virtual)
                </label>
                <textarea
                  name="insVirtual"
                  value={settings.insVirtual || ""}
                  onChange={handleChange}
                  rows={6}
                  placeholder="Ketikkan rincian pertanggungan asuransi untuk Virtual Run di sini..."
                  className="w-full p-4 bg-white border border-slate-300 rounded-lg focus:border-[#1A73E8] focus:ring-1 focus:ring-[#1A73E8] outline-none text-sm transition-all text-slate-700"
                />
              </div>
            </div>
          </div>
        )}
      </form>

    </div>
  );
}

"use client";

import { useEffect, useState, useRef } from "react";
import { db, auth } from "@/lib/firebase";
import {
  collection,
  onSnapshot,
  doc,
  updateDoc,
  writeBatch,
  addDoc,
  runTransaction,
  query,
} from "firebase/firestore";
import { onAuthStateChanged } from "firebase/auth";
import * as XLSX from "xlsx";
import { sendEmailAction } from "@/app/actions/email";


export default function AdminOfflineRunPage() {
  const [participants, setParticipants] = useState<any[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [filterStatus, setFilterStatus] = useState("Semua");
  const [searchQuery, setSearchQuery] = useState("");
  const [adminUser, setAdminUser] = useState<any>(null);

  // UI State
  const [selectedIds, setSelectedIds] = useState<string[]>([]);
  const [detailParticipant, setDetailParticipant] = useState<any>(null);
  const [selectedImage, setSelectedImage] = useState<string | null>(null);
  const [actionLoading, setActionLoading] = useState<string | null>(null);
  const [isBroadcasting, setIsBroadcasting] = useState(false);

  // --- 🔥 STATE TOAST NOTIFICATION (BUKTI BARU) 🔥 ---
  const [showToast, setShowToast] = useState(false);
  const previousPendingCount = useRef<number>(0);

  // --- 🔥 STATE CUSTOM MODALS (MENGGANTIKAN ALERT BAWAAN BROWSER) 🔥 ---
  const [alertModal, setAlertModal] = useState({
    isOpen: false,
    type: "success", // "success" | "error" | "warning"
    title: "",
    message: "",
  });

  const [confirmModal, setConfirmModal] = useState<{
    isOpen: boolean;
    title: string;
    message: string;
    onConfirm: () => void;
  }>({
    isOpen: false,
    title: "",
    message: "",
    onConfirm: () => {},
  });

  const [approveProcess, setApproveProcess] = useState<{
    isOpen: boolean;
    participant: any;
    step: "confirm" | "processing" | "success" | "error";
    message: string;
  }>({ isOpen: false, participant: null, step: "confirm", message: "" });

  // --- STATE PAGINATION, SORTING & LIMIT ---
  const [sortConfig, setSortConfig] = useState<{
    key: string;
    direction: "asc" | "desc";
  }>({ key: "waktuDaftar", direction: "desc" });

  const [itemsPerPage, setItemsPerPage] = useState<number | "All">(10);
  const [currentPage, setCurrentPage] = useState(1);

  useEffect(() => {
    const unsubscribe = onAuthStateChanged(auth, (user) => {
      setAdminUser(user);
    });
    return () => unsubscribe();
  }, []);

  // --- MENGAMBIL DATA & MEMANTAU BUKTI BARU ---
  useEffect(() => {
    const q = query(collection(db, "offline_participants"));
    const unsubscribe = onSnapshot(q, (snapshot) => {
      const data = snapshot.docs.map((doc) => ({ id: doc.id, ...doc.data() }));
      setParticipants(data);
      setIsLoading(false);

      // Logika Pemantau Bukti Baru (Pending)
      const currentPendingCount = data.filter(
        (p: any) => p.statusPembayaran === "Pending",
      ).length;

      // Jika jumlah pending bertambah (ada upload baru) dan ini bukan render pertama
      if (
        currentPendingCount > previousPendingCount.current &&
        previousPendingCount.current !== 0
      ) {
        setShowToast(true);
        // Toast hilang otomatis setelah 5 detik
        setTimeout(() => setShowToast(false), 5000);
      }

      // Update nilai referensi
      previousPendingCount.current = currentPendingCount;
    });
    return () => unsubscribe();
  }, []);

  // --- LOGIKA FILTER, SEARCH, SORTING & PAGINATION ---
  const filteredData = participants.filter((p) => {
    const matchStatus =
      filterStatus === "Semua" || p.statusPembayaran === filterStatus;
    const matchSearch =
      p.namaLengkap?.toLowerCase().includes(searchQuery.toLowerCase()) ||
      p.nomorBIB?.includes(searchQuery) ||
      p.nik?.includes(searchQuery) ||
      p.namaBib?.toLowerCase().includes(searchQuery.toLowerCase()) ||
      p.kodePromoDipakai?.toLowerCase().includes(searchQuery.toLowerCase());

    return matchStatus && matchSearch;
  });

  const sortedData = [...filteredData].sort((a, b) => {
    let valA = a[sortConfig.key] || "";
    let valB = b[sortConfig.key] || "";

    if (typeof valA === "string") valA = valA.toLowerCase();
    if (typeof valB === "string") valB = valB.toLowerCase();

    if (valA < valB) return sortConfig.direction === "asc" ? -1 : 1;
    if (valA > valB) return sortConfig.direction === "asc" ? 1 : -1;
    return 0;
  });

  const totalPages =
    itemsPerPage === "All" ? 1 : Math.ceil(sortedData.length / itemsPerPage);

  const paginatedData =
    itemsPerPage === "All"
      ? sortedData
      : sortedData.slice(
          (currentPage - 1) * (itemsPerPage as number),
          currentPage * (itemsPerPage as number),
        );

  // --- REKAP STATISTIK ---
  const totalLunas = participants.filter(
    (p) => p.statusPembayaran === "Lunas",
  ).length;
  const totalPending = participants.filter(
    (p) => p.statusPembayaran === "Pending",
  ).length;
  const totalUangLunas = participants
    .filter((p) => p.statusPembayaran === "Lunas")
    .reduce((acc, curr) => acc + (Number(curr.totalTagihan) || 0), 0);

  // --- SELECTION LOGIC ---
  const toggleSelect = (id: string) => {
    setSelectedIds((prev) =>
      prev.includes(id) ? prev.filter((i) => i !== id) : [...prev, id],
    );
  };

  const toggleSelectAllVisible = () => {
    if (
      selectedIds.length === paginatedData.length &&
      paginatedData.length > 0
    ) {
      setSelectedIds([]);
    } else {
      setSelectedIds(paginatedData.map((p) => p.id));
    }
  };

  // --- FITUR EKSPOR EXCEL ---
  const handleExportExcel = () => {
    const excelData = sortedData.map((p) => {
      let durasi = "-";
      if (p.netTimeMs) {
        const hrs = Math.floor(p.netTimeMs / 3600000);
        const mins = Math.floor((p.netTimeMs % 3600000) / 60000);
        const secs = Math.floor((p.netTimeMs % 60000) / 1000);
        durasi = `${hrs.toString().padStart(2, "0")}:${mins.toString().padStart(2, "0")}:${secs.toString().padStart(2, "0")}`;
      }

      return {
        "Waktu Daftar": p.waktuDaftar
          ? new Date(p.waktuDaftar).toLocaleString("id-ID")
          : "-",
        "Status Pembayaran": p.statusPembayaran || "Belum Bayar",
        "Waktu Lunas": p.waktuLunas
          ? new Date(p.waktuLunas).toLocaleString("id-ID")
          : "-",
        "Nomor BIB": p.nomorBIB || "-",
        "Kategori Jarak": p.jarak || "-",
        "Paket Dipilih": p.paketNama || "-",
        "Nama di BIB": p.namaBib || "-",
        "Nama Lengkap": p.namaLengkap || "-",
        "Kategori Peserta": p.kategoriPeserta || "-",
        "Jenis Identitas": p.jenisIdentitas || "KTP",
        "Nomor Identitas (NIK/NIS)": p.nik || "-",
        "Jenis Kelamin": p.jenisKelamin || "-",
        "Tanggal Lahir": p.tanggalLahir || "-",
        "No. WhatsApp": p.noWA || "-",
        Email: p.email || "-",
        Komunitas: p.komunitas || "-",
        "Ukuran Jersey": p.ukuranJersey || "-",
        "Golongan Darah": p.golonganDarah || "-",
        "Riwayat Penyakit": p.riwayatPenyakit || "-",
        "Nama Kontak Darurat": p.namaDarurat || "-",
        "Hubungan Darurat": p.hubunganDarurat || "-",
        "No WA Darurat": p.waDarurat || "-",
        "Harga Asli": p.hargaAsli || p.totalTagihan || 0,
        "Kode Promo Dipakai": p.kodePromoDipakai || "-",
        "Total Diskon": p.totalDiskon || 0,
        "Total Tagihan (Nett)": p.totalTagihan || 0,
        "Logistik (Racepack)": p.isRacepackTaken ? "SUDAH DIAMBIL" : "BELUM",
        "Diserahkan Oleh Admin": p.adminHandler || "-",
        "Waktu Ambil Racepack": p.waktuAmbilRacepack
          ? new Date(p.waktuAmbilRacepack).toLocaleString("id-ID")
          : "-",
      };
    });

    const worksheet = XLSX.utils.json_to_sheet(excelData);
    const workbook = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(workbook, worksheet, "Data_Offline_Full");
    XLSX.writeFile(workbook, `REKAP_FULL_OFFLINE_${new Date().getTime()}.xlsx`);
  };

  // --- 🔥 FITUR BROADCAST REMINDER RACEPACK (INDIVIDU) 🔥 ---
  const handleBroadcastReminderClick = () => {
    const targetParticipants = participants.filter(
      (p) => p.statusPembayaran === "Lunas" && !p.isRacepackTaken,
    );

    if (targetParticipants.length === 0) {
      setAlertModal({
        isOpen: true,
        type: "warning",
        title: "Target Kosong",
        message:
          "Tidak ada Peserta Individu yang memenuhi syarat (Lunas & Belum Ambil Racepack).",
      });
      return;
    }

    setConfirmModal({
      isOpen: true,
      title: "Konfirmasi Broadcast",
      message: `Anda akan mengirim Email Reminder Pengambilan Racepack kepada ${targetParticipants.length} Peserta Individu. Lanjutkan?`,
      onConfirm: () => executeBroadcastReminder(targetParticipants),
    });
  };

  const executeBroadcastReminder = async (targetParticipants: any[]) => {
    setIsBroadcasting(true);
    let successCount = 0;
    let failCount = 0;

    for (const p of targetParticipants) {
      try {
        const res = await sendEmailAction({
            type: "reminder_racepack_individu",
            email: p.email,
            nama: p.namaLengkap,
            detail: {
              id: p.id,
              nik: p.nik || "-",
              jarak: p.jarak || "-",
              ukuranJersey: p.ukuranJersey || "-",
              namaBib: p.namaBib || "-",
              bib: p.nomorBIB || p.bib || "-",
            },
          });

        if (res.success) successCount++;
        else failCount++;
      } catch (error) {
        failCount++;
      }
      await new Promise((resolve) => setTimeout(resolve, 1000));
    }

    setIsBroadcasting(false);
    setAlertModal({
      isOpen: true,
      type: "success",
      title: "Broadcast Selesai",
      message: `Berhasil terkirim: ${successCount} Peserta\nGagal terkirim: ${failCount} Peserta\n\nPastikan koneksi internet stabil jika ada pengiriman yang gagal.`,
    });
  };

  // --- 🔥 AKSI PEMBAYARAN BARU DENGAN POPUP PROGRESS 🔥 ---
  const triggerApprove = (p: any) => {
    setApproveProcess({
      isOpen: true,
      participant: p,
      step: "confirm",
      message: "",
    });
  };

  const executeApproveProcess = async () => {
    const p = approveProcess.participant;
    if (!p) return;

    setApproveProcess((prev) => ({
      ...prev,
      step: "processing",
      message: "Mengupdate database & mengirim E-Ticket...",
    }));

    try {
      let finalBib = p.nomorBIB || "";

      if (!finalBib) {
        setApproveProcess((prev) => ({
          ...prev,
          message: "Men-generate Nomor BIB...",
        }));

        await runTransaction(db, async (transaction) => {
          const counterDocRef = doc(db, "settings", "bib_counter");
          const participantRef = doc(db, "offline_participants", p.id);

          let promoRef = null;
          if (p.idPromoDipakai) {
            promoRef = doc(db, "promo_codes", p.idPromoDipakai);
          }

          const counterDoc = await transaction.get(counterDocRef);
          let promoDoc = null;
          if (promoRef) promoDoc = await transaction.get(promoRef);

          let current5K = counterDoc.exists()
            ? counterDoc.data().lastBib5K || 0
            : 0;
          let current10K = counterDoc.exists()
            ? counterDoc.data().lastBib10K || 0
            : 0;

          const jarakAngka = (p.jarak || "9").replace(/\D/g, "") || "9";
          let newCounter = 0;

          if (jarakAngka === "5") {
            current5K++;
            newCounter = current5K;
            finalBib = `5${String(newCounter).padStart(3, "0")}`;
          } else if (jarakAngka === "10") {
            current10K++;
            newCounter = current10K;
            finalBib = `10${String(newCounter).padStart(3, "0")}`;
          } else {
            newCounter = Math.floor(1000 + Math.random() * 8000);
            finalBib = `${jarakAngka}${newCounter}`;
          }

          transaction.set(
            counterDocRef,
            { lastBib5K: current5K, lastBib10K: current10K },
            { merge: true },
          );
          transaction.update(participantRef, {
            statusPembayaran: "Lunas",
            waktuLunas: new Date().toISOString(),
            nomorBIB: finalBib,
          });

          if (promoRef && promoDoc && promoDoc.exists()) {
            const kuotaTerpakaiSekarang = promoDoc.data().kuotaTerpakai || 0;
            transaction.update(promoRef, {
              kuotaTerpakai: kuotaTerpakaiSekarang + 1,
            });
          }
        });
      } else {
        await updateDoc(doc(db, "offline_participants", p.id), {
          statusPembayaran: "Lunas",
          waktuLunas: new Date().toISOString(),
        });
      }

      const res = await sendEmailAction({
          type: "payment_success_offline",
          email: p.email,
          nama: p.namaLengkap,
          detail: {
            id: p.id,
            nik: p.nik || "-",
            jarak: p.jarak || "-",
            ukuranJersey: p.ukuranJersey || "-",
            namaBib: p.namaBib || "-",
            bib: finalBib || "-",
          },
        });

      if (!res.success)
        throw new Error("Gagal mengirim email E-Ticket dari server.");

      await addDoc(collection(db, "vr_logs"), {
        type: "bayar",
        action: `menyetujui pembayaran offline (BIB: ${finalBib}) untuk`,
        targetName: p.namaLengkap,
        adminEmail: adminUser?.email || "Admin",
        timestamp: Date.now(),
      });

      if (detailParticipant?.id === p.id) {
        setDetailParticipant((prev: any) => ({
          ...prev,
          statusPembayaran: "Lunas",
          nomorBIB: finalBib,
        }));
      }

      setApproveProcess((prev) => ({
        ...prev,
        step: "success",
        message: `Berhasil! Pembayaran lunas, BIB tercetak (${finalBib}), dan Email E-Ticket telah terkirim.`,
      }));
    } catch (e: any) {
      setApproveProcess((prev) => ({
        ...prev,
        step: "error",
        message: e.message || "Terjadi kesalahan jaringan atau server.",
      }));
    }
  };

  const closeApproveProcess = () => {
    setApproveProcess({
      isOpen: false,
      participant: null,
      step: "confirm",
      message: "",
    });
  };

  // --- AKSI PENYERAHAN LOGISTIK ---
  const handleHandoverClick = (id: string, participantName: string) => {
    setConfirmModal({
      isOpen: true,
      title: "Penyerahan Racepack",
      message: `Konfirmasi penyerahan atribut (Racepack & Jersey) untuk ${participantName}?`,
      onConfirm: () => executeHandover(id, participantName),
    });
  };

  const executeHandover = async (id: string, participantName: string) => {
    const adminEmail = auth.currentUser?.email || "Admin Lapangan";
    setActionLoading(id);
    try {
      const dataUpdate = {
        isRacepackTaken: true,
        waktuAmbilRacepack: new Date().toISOString(),
        adminHandler: adminEmail,
      };

      await updateDoc(doc(db, "offline_participants", id), dataUpdate);
      if (detailParticipant?.id === id) {
        setDetailParticipant({ ...detailParticipant, ...dataUpdate });
      }

      await addDoc(collection(db, "vr_logs"), {
        type: "resi",
        action: "menyerahkan racepack offline untuk",
        targetName: participantName,
        adminEmail: adminEmail,
        timestamp: Date.now(),
      });

      setAlertModal({
        isOpen: true,
        type: "success",
        title: "Racepack Diserahkan",
        message: `Berhasil mencatat penyerahan racepack untuk ${participantName}.`,
      });
    } catch (e) {
      setAlertModal({
        isOpen: true,
        type: "error",
        title: "Gagal",
        message: "Gagal memproses penyerahan racepack.",
      });
    }
    setActionLoading(null);
  };

  // --- AKSI BULK DELETE ---
  const handleBulkDeleteClick = () => {
    setConfirmModal({
      isOpen: true,
      title: "Konfirmasi Hapus",
      message: `Hapus ${selectedIds.length} data pendaftar ini secara permanen? Tindakan ini tidak dapat dibatalkan.`,
      onConfirm: async () => {
        const batch = writeBatch(db);
        selectedIds.forEach((id) =>
          batch.delete(doc(db, "offline_participants", id)),
        );
        await batch.commit();
        setSelectedIds([]);
        setAlertModal({
          isOpen: true,
          type: "success",
          title: "Berhasil",
          message: "Data peserta berhasil dihapus.",
        });
      },
    });
  };

  if (isLoading)
    return (
      <div className="h-screen flex flex-col items-center justify-center text-[#1A73E8] font-medium text-sm">
        <div className="w-8 h-8 border-4 border-blue-100 border-t-[#1A73E8] rounded-full animate-spin mb-4"></div>
        MEMUAT DATA...
      </div>
    );

  return (
    <div className="animate-in fade-in duration-300 flex flex-col h-[calc(100vh-2rem)] max-w-7xl mx-auto font-sans relative">
      {/* --- 🔥 TOAST NOTIFICATION (DI POJOK KANAN ATAS) 🔥 --- */}
      {showToast && (
        <div
          className="fixed top-6 right-6 z-[9999] animate-in slide-in-from-right slide-in-from-top duration-300 fade-in cursor-pointer"
          onClick={() => setShowToast(false)}
        >
          <div className="bg-rose-500 text-white px-6 py-4 rounded-2xl shadow-[0_10px_40px_-10px_rgba(225,29,72,0.5)] border border-rose-400 flex items-center gap-4 hover:scale-105 transition-transform">
            <div className="bg-white/20 p-2 rounded-full animate-pulse">
              <svg
                className="w-6 h-6 text-white"
                fill="none"
                viewBox="0 0 24 24"
                stroke="currentColor"
              >
                <path
                  strokeLinecap="round"
                  strokeLinejoin="round"
                  strokeWidth={2.5}
                  d="M15 17h5l-1.405-1.405A2.032 2.032 0 0118 14.158V11a6.002 6.002 0 00-4-5.659V5a2 2 0 10-4 0v.341C7.67 6.165 6 8.388 6 11v3.159c0 .538-.214 1.055-.595 1.436L4 17h5m6 0v1a3 3 0 11-6 0v-1m6 0H9"
                />
              </svg>
            </div>
            <div>
              <p className="font-black text-base drop-shadow-sm uppercase tracking-wider">
                Bukti Bayar Baru!
              </p>
              <p className="text-xs text-rose-100 font-medium">
                Ada peserta yang baru saja upload struk.
              </p>
            </div>
          </div>
        </div>
      )}

      {/* --- 🔥 KUMPULAN MODAL (MENGGANTIKAN ALERT BAWAAN) 🔥 --- */}

      {/* 1. Modal Alert (Success/Error/Warning) */}
      {alertModal.isOpen && (
        <div className="fixed inset-0 z-[500] flex items-center justify-center bg-slate-900/60 backdrop-blur-sm p-4 animate-in fade-in duration-200">
          <div className="bg-white rounded-3xl shadow-2xl w-full max-w-sm overflow-hidden animate-in zoom-in-95 duration-200">
            <div
              className={`p-8 text-center ${alertModal.type === "error" ? "bg-rose-50" : alertModal.type === "success" ? "bg-emerald-50" : "bg-amber-50"}`}
            >
              <div
                className={`w-16 h-16 mx-auto rounded-full flex items-center justify-center mb-4 text-3xl shadow-sm ${alertModal.type === "error" ? "bg-rose-100 text-rose-600" : alertModal.type === "success" ? "bg-emerald-100 text-emerald-600" : "bg-amber-100 text-amber-600"}`}
              >
                {alertModal.type === "error" ? (
                  <svg
                    className="w-8 h-8"
                    fill="none"
                    viewBox="0 0 24 24"
                    stroke="currentColor"
                  >
                    <path
                      strokeLinecap="round"
                      strokeLinejoin="round"
                      strokeWidth={2.5}
                      d="M6 18L18 6M6 6l12 12"
                    />
                  </svg>
                ) : alertModal.type === "success" ? (
                  <svg
                    className="w-8 h-8"
                    fill="none"
                    viewBox="0 0 24 24"
                    stroke="currentColor"
                  >
                    <path
                      strokeLinecap="round"
                      strokeLinejoin="round"
                      strokeWidth={2.5}
                      d="M5 13l4 4L19 7"
                    />
                  </svg>
                ) : (
                  <svg
                    className="w-8 h-8"
                    fill="none"
                    viewBox="0 0 24 24"
                    stroke="currentColor"
                  >
                    <path
                      strokeLinecap="round"
                      strokeLinejoin="round"
                      strokeWidth={2.5}
                      d="M12 9v2m0 4h.01m-6.938 4h13.856c1.54 0 2.502-1.667 1.732-3L13.732 4c-.77-1.333-2.694-1.333-3.464 0L3.34 16c-.77 1.333.192 3 1.732 3z"
                    />
                  </svg>
                )}
              </div>
              <h3 className="text-xl font-black text-slate-800 tracking-tight">
                {alertModal.title}
              </h3>
            </div>
            <div className="p-6 text-center">
              <p className="text-sm text-slate-600 leading-relaxed mb-6 whitespace-pre-wrap">
                {alertModal.message}
              </p>
              <button
                onClick={() => setAlertModal({ ...alertModal, isOpen: false })}
                className="w-full bg-slate-800 hover:bg-slate-900 text-white font-bold py-3.5 rounded-xl transition-colors shadow-md"
              >
                Mengerti
              </button>
            </div>
          </div>
        </div>
      )}

      {/* 2. Modal Confirm (Yes/No) */}
      {confirmModal.isOpen && (
        <div className="fixed inset-0 z-[500] flex items-center justify-center bg-slate-900/60 backdrop-blur-sm p-4 animate-in fade-in duration-200">
          <div className="bg-white rounded-3xl shadow-2xl w-full max-w-sm overflow-hidden animate-in zoom-in-95 duration-200">
            <div className="p-8 text-center bg-blue-50">
              <div className="w-16 h-16 mx-auto rounded-full flex items-center justify-center mb-4 bg-blue-100 text-blue-600 shadow-sm">
                <svg
                  className="w-8 h-8"
                  fill="none"
                  viewBox="0 0 24 24"
                  stroke="currentColor"
                >
                  <path
                    strokeLinecap="round"
                    strokeLinejoin="round"
                    strokeWidth={2.5}
                    d="M8 16H6a2 2 0 01-2-2V6a2 2 0 012-2h8a2 2 0 012 2v2m-6 12h8a2 2 0 002-2v-8a2 2 0 00-2-2h-8a2 2 0 00-2 2v8a2 2 0 002 2z"
                  />
                </svg>
              </div>
              <h3 className="text-xl font-black text-slate-800 tracking-tight">
                {confirmModal.title}
              </h3>
            </div>
            <div className="p-6 text-center">
              <p className="text-sm text-slate-600 leading-relaxed mb-6 whitespace-pre-wrap">
                {confirmModal.message}
              </p>
              <div className="flex gap-3">
                <button
                  onClick={() =>
                    setConfirmModal({ ...confirmModal, isOpen: false })
                  }
                  className="w-full bg-slate-100 hover:bg-slate-200 text-slate-700 font-bold py-3 rounded-xl transition-colors"
                >
                  Batal
                </button>
                <button
                  onClick={() => {
                    setConfirmModal({ ...confirmModal, isOpen: false });
                    confirmModal.onConfirm();
                  }}
                  className="w-full bg-[#1A73E8] hover:bg-[#1557B0] text-white font-bold py-3 rounded-xl transition-colors shadow-md"
                >
                  Ya, Lanjutkan
                </button>
              </div>
            </div>
          </div>
        </div>
      )}

      {/* 3. Modal Approve Progress (Untuk Generate BIB & Email) */}
      {approveProcess.isOpen && approveProcess.participant && (
        <div className="fixed inset-0 z-[500] flex items-center justify-center bg-slate-900/60 backdrop-blur-sm p-4">
          <div className="bg-white rounded-2xl shadow-2xl w-full max-w-sm overflow-hidden animate-in zoom-in-95 duration-200">
            <div className="p-6">
              {approveProcess.step === "confirm" && (
                <div className="text-center">
                  <div className="w-16 h-16 bg-blue-50 text-[#1A73E8] rounded-full flex items-center justify-center mx-auto mb-4">
                    <svg
                      className="w-8 h-8"
                      fill="none"
                      viewBox="0 0 24 24"
                      stroke="currentColor"
                    >
                      <path
                        strokeLinecap="round"
                        strokeLinejoin="round"
                        strokeWidth={2}
                        d="M9 12l2 2 4-4m6 2a9 9 0 11-18 0 9 9 0 0118 0z"
                      />
                    </svg>
                  </div>
                  <h3 className="text-lg font-bold text-slate-800 mb-2">
                    Verifikasi Pembayaran Manual
                  </h3>
                  <p className="text-sm text-slate-600 mb-6">
                    Anda akan menyetujui status LUNAS untuk{" "}
                    <strong>{approveProcess.participant.namaLengkap}</strong>.
                    <br />
                    Sistem akan otomatis me-generate <b>Nomor BIB baru</b> dan
                    mengirimkan email E-Ticket.
                  </p>
                  <div className="flex gap-3 justify-center">
                    <button
                      onClick={closeApproveProcess}
                      className="px-5 py-2.5 text-sm font-bold text-slate-600 hover:bg-slate-100 rounded-lg transition-colors w-full"
                    >
                      Batal
                    </button>
                    <button
                      onClick={executeApproveProcess}
                      className="px-5 py-2.5 text-sm font-bold bg-[#1A73E8] text-white rounded-lg hover:bg-[#1557B0] transition-colors shadow-sm w-full"
                    >
                      Terima & Kirim
                    </button>
                  </div>
                </div>
              )}

              {approveProcess.step === "processing" && (
                <div className="text-center py-6">
                  <div className="w-12 h-12 border-4 border-blue-100 border-t-[#1A73E8] rounded-full animate-spin mx-auto mb-4"></div>
                  <h3 className="text-base font-bold text-slate-800 mb-1">
                    Harap Tunggu...
                  </h3>
                  <p className="text-xs text-slate-500 animate-pulse">
                    {approveProcess.message}
                  </p>
                </div>
              )}

              {approveProcess.step === "success" && (
                <div className="text-center py-4">
                  <div className="w-16 h-16 bg-[#E6F4EA] text-[#1E8E3E] rounded-full flex items-center justify-center mx-auto mb-4">
                    <svg
                      className="w-8 h-8"
                      fill="none"
                      viewBox="0 0 24 24"
                      stroke="currentColor"
                    >
                      <path
                        strokeLinecap="round"
                        strokeLinejoin="round"
                        strokeWidth={3}
                        d="M5 13l4 4L19 7"
                      />
                    </svg>
                  </div>
                  <h3 className="text-lg font-bold text-slate-800 mb-2">
                    Selesai!
                  </h3>
                  <p className="text-sm text-slate-600 mb-6">
                    {approveProcess.message}
                  </p>
                  <button
                    onClick={closeApproveProcess}
                    className="w-full bg-slate-100 text-slate-700 hover:bg-slate-200 py-3 rounded-xl font-bold transition-colors"
                  >
                    Tutup
                  </button>
                </div>
              )}

              {approveProcess.step === "error" && (
                <div className="text-center py-4">
                  <div className="w-16 h-16 bg-[#FCE8E6] text-[#D93025] rounded-full flex items-center justify-center mx-auto mb-4">
                    <svg
                      className="w-8 h-8"
                      fill="none"
                      viewBox="0 0 24 24"
                      stroke="currentColor"
                    >
                      <path
                        strokeLinecap="round"
                        strokeLinejoin="round"
                        strokeWidth={3}
                        d="M6 18L18 6M6 6l12 12"
                      />
                    </svg>
                  </div>
                  <h3 className="text-lg font-bold text-slate-800 mb-2">
                    Gagal
                  </h3>
                  <p className="text-sm text-slate-600 mb-6">
                    {approveProcess.message}
                  </p>
                  <button
                    onClick={closeApproveProcess}
                    className="w-full bg-slate-100 text-slate-700 hover:bg-slate-200 py-3 rounded-xl font-bold transition-colors"
                  >
                    Tutup
                  </button>
                </div>
              )}
            </div>
          </div>
        </div>
      )}

      {/* --- BAGIAN ATAS: TITLE & EXPORT --- */}
      <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4 mb-4 shrink-0 px-1">
        <div>
          <h1 className="text-2xl font-black text-slate-800 tracking-tight">
            Pendaftar Offline Run
          </h1>
          <p className="text-sm text-slate-500 font-medium">
            Verifikasi pembayaran dan manajemen logistik racepack
          </p>
        </div>
        <div className="flex items-center gap-3 w-full md:w-auto">
          {selectedIds.length > 0 && (
            <button
              onClick={handleBulkDeleteClick}
              className="bg-[#FCE8E6] text-[#D93025] hover:bg-red-100 px-4 py-2 rounded-xl text-sm font-bold border border-red-200 transition-colors w-full md:w-auto shadow-sm"
            >
              Hapus ({selectedIds.length})
            </button>
          )}
          <button
            onClick={handleBroadcastReminderClick}
            disabled={isBroadcasting}
            className="px-4 py-2 bg-[#FCD116] text-[#0B2239] rounded-xl text-sm font-bold hover:bg-yellow-500 transition-colors flex items-center gap-2 shadow-sm disabled:opacity-50"
          >
            {isBroadcasting ? (
              <div className="w-4 h-4 border-2 border-[#0B2239] border-t-transparent rounded-full animate-spin"></div>
            ) : (
              <svg
                className="w-4 h-4"
                fill="none"
                viewBox="0 0 24 24"
                stroke="currentColor"
              >
                <path
                  strokeLinecap="round"
                  strokeLinejoin="round"
                  strokeWidth={2}
                  d="M11 5.882V19.24a1.76 1.76 0 01-3.417.592l-2.147-6.15M18 13a3 3 0 100-6M5.436 13.683A4.001 4.001 0 017 6h1.832c4.1 0 7.625-1.234 9.168-3v14c-1.543-1.766-5.067-3-9.168-3H7a3.988 3.988 0 01-1.564-.317z"
                />
              </svg>
            )}
            {isBroadcasting ? "Mengirim..." : "Kirim Reminder (RPC)"}
          </button>
          <button
            onClick={handleExportExcel}
            className="bg-[#0B2239] text-[#FCD116] px-5 py-2.5 rounded-xl text-sm font-bold shadow-sm hover:bg-slate-800 transition-colors w-full md:w-auto"
          >
            Ekspor Excel
          </button>
        </div>
      </div>

      {/* --- STATISTIK --- */}
      <div className="grid grid-cols-2 md:grid-cols-4 gap-3 md:gap-4 mb-4 shrink-0">
        <div className="bg-white p-4 rounded-2xl shadow-sm border border-slate-100">
          <p className="text-xs font-bold text-slate-500 mb-1 uppercase tracking-wider">
            Total Peserta
          </p>
          <p className="text-2xl font-black text-slate-800">
            {participants.length}
          </p>
        </div>
        <div className="bg-white p-4 rounded-2xl shadow-sm border border-slate-100">
          <p className="text-xs font-bold text-slate-500 mb-1 uppercase tracking-wider">
            Lunas (Verified)
          </p>
          <p className="text-2xl font-black text-[#1E8E3E]">{totalLunas}</p>
        </div>
        <div className="bg-white p-4 rounded-2xl shadow-sm border border-slate-100">
          <p className="text-xs font-bold text-slate-500 mb-1 uppercase tracking-wider">
            Pending / Tunggu
          </p>
          <p className="text-2xl font-black text-[#F9AB00]">{totalPending}</p>
        </div>
        <div className="bg-white p-4 rounded-2xl shadow-sm border border-slate-100">
          <p className="text-xs font-bold text-slate-500 mb-1 uppercase tracking-wider">
            Dana Masuk
          </p>
          <p className="text-lg md:text-xl font-black text-[#1A73E8] truncate">
            Rp {totalUangLunas.toLocaleString("id-ID")}
          </p>
        </div>
      </div>

      {/* --- TOOLBAR: SEARCH & FILTER --- */}
      <div className="bg-white p-4 rounded-t-2xl shadow-sm border border-slate-100 flex flex-col md:flex-row gap-3 justify-between items-center shrink-0">
        <div className="relative w-full md:w-96">
          <svg
            className="w-5 h-5 absolute left-3 top-1/2 -translate-y-1/2 text-slate-400"
            fill="none"
            viewBox="0 0 24 24"
            stroke="currentColor"
          >
            <path
              strokeLinecap="round"
              strokeLinejoin="round"
              strokeWidth={2}
              d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z"
            />
          </svg>
          <input
            type="text"
            placeholder="Cari nama, NIK, Kode Promo..."
            value={searchQuery}
            onChange={(e) => setSearchQuery(e.target.value)}
            className="pl-10 pr-4 py-2.5 bg-slate-50 border border-slate-200 rounded-xl text-sm focus:outline-none focus:ring-2 focus:ring-[#1A73E8] w-full"
          />
        </div>
        <div className="flex gap-3 w-full md:w-auto">
          <select
            value={filterStatus}
            onChange={(e) => setFilterStatus(e.target.value)}
            className="px-4 py-2.5 bg-slate-50 border border-slate-200 rounded-xl text-sm font-bold focus:outline-none focus:ring-2 focus:ring-[#1A73E8] w-full md:w-auto"
          >
            <option value="Semua">Semua Status</option>
            <option value="Lunas">Lunas</option>
            <option value="Pending">Pending</option>
          </select>
          <select
            value={itemsPerPage}
            onChange={(e) =>
              setItemsPerPage(
                e.target.value === "All" ? "All" : Number(e.target.value),
              )
            }
            className="px-4 py-2.5 bg-slate-50 border border-slate-200 rounded-xl text-sm font-bold focus:outline-none focus:ring-2 focus:ring-[#1A73E8] w-full md:w-auto hidden md:block"
          >
            <option value={10}>10 Baris</option>
            <option value={50}>50 Baris</option>
            <option value={100}>100 Baris</option>
            <option value="All">Semua</option>
          </select>
        </div>
      </div>

      {/* --- TABLE --- */}
      <div className="bg-white border-x border-slate-100 flex-grow overflow-auto relative">
        <table className="w-full text-left border-collapse text-sm whitespace-nowrap">
          <thead className="bg-slate-50 text-slate-500 sticky top-0 z-10 shadow-sm">
            <tr>
              <th className="p-4 border-b border-slate-200 w-10">
                <input
                  type="checkbox"
                  checked={
                    selectedIds.length === paginatedData.length &&
                    paginatedData.length > 0
                  }
                  onChange={toggleSelectAllVisible}
                  className="rounded text-[#1A73E8] focus:ring-[#1A73E8] w-4 h-4 cursor-pointer"
                />
              </th>
              <th className="p-4 border-b border-slate-200 font-bold">BIB</th>
              <th className="p-4 border-b border-slate-200 font-bold">
                Nama Pendaftar
              </th>
              <th className="p-4 border-b border-slate-200 font-bold">
                Kategori & Size
              </th>
              <th className="p-4 border-b border-slate-200 font-bold">
                Tagihan
              </th>
              <th className="p-4 border-b border-slate-200 font-bold">
                Status
              </th>
              <th className="p-4 border-b border-slate-200 font-bold text-right">
                Aksi
              </th>
            </tr>
          </thead>
          <tbody className="divide-y divide-slate-100">
            {paginatedData.length === 0 ? (
              <tr>
                <td colSpan={7} className="p-8 text-center text-slate-400">
                  Tidak ada data yang sesuai dengan pencarian atau filter.
                </td>
              </tr>
            ) : (
              paginatedData.map((p) => (
                <tr
                  key={p.id}
                  className={`hover:bg-blue-50/50 transition-colors ${p.statusPembayaran === "Pending" ? "bg-amber-50/30" : ""}`}
                >
                  <td className="p-4">
                    <input
                      type="checkbox"
                      checked={selectedIds.includes(p.id)}
                      onChange={() => toggleSelect(p.id)}
                      className="rounded text-[#1A73E8] focus:ring-[#1A73E8] w-4 h-4 cursor-pointer"
                    />
                  </td>
                  <td className="p-4">
                    <span className="font-mono font-black text-[#1A73E8] bg-blue-50 px-2 py-1 rounded">
                      {p.nomorBIB || "-"}
                    </span>
                  </td>
                  <td className="p-4">
                    <p className="font-bold text-slate-800">{p.namaLengkap}</p>
                    <p className="text-xs text-slate-500 mt-0.5">{p.noWA}</p>
                  </td>
                  <td className="p-4">
                    <p className="font-bold text-slate-700">{p.jarak}</p>
                    <p className="text-xs text-slate-500 mt-0.5">
                      Jersey:{" "}
                      <span className="font-bold">{p.ukuranJersey}</span>
                    </p>
                  </td>
                  <td className="p-4 font-bold text-slate-800">
                    Rp {p.totalTagihan?.toLocaleString("id-ID")}
                  </td>
                  <td className="p-4">
                    <span
                      className={`px-3 py-1 text-[10px] uppercase tracking-wider font-bold rounded-full border ${p.statusPembayaran === "Lunas" ? "bg-[#E6F4EA] text-[#1E8E3E] border-[#1E8E3E]/20" : "bg-[#FEF7E0] text-[#B08D00] border-[#F9AB00]/20"}`}
                    >
                      {p.statusPembayaran}
                    </span>
                  </td>
                  <td className="p-4 text-right">
                    <button
                      onClick={() => setDetailParticipant(p)}
                      className="bg-white border border-slate-200 text-slate-600 px-4 py-1.5 rounded-lg text-xs font-bold shadow-sm hover:bg-slate-50 transition-colors"
                    >
                      Detail
                    </button>
                  </td>
                </tr>
              ))
            )}
          </tbody>
        </table>
      </div>

      {/* --- PAGINATION BAWAH --- */}
      <div className="bg-white p-4 rounded-b-2xl shadow-sm border border-slate-100 flex justify-between items-center shrink-0">
        <p className="text-sm text-slate-500 hidden md:block">
          Menampilkan baris{" "}
          <span className="font-bold text-slate-800">
            {(currentPage - 1) *
              (itemsPerPage === "All" ? sortedData.length : itemsPerPage) +
              1}
          </span>{" "}
          -{" "}
          <span className="font-bold text-slate-800">
            {Math.min(
              currentPage *
                (itemsPerPage === "All" ? sortedData.length : itemsPerPage),
              sortedData.length,
            )}
          </span>{" "}
          dari{" "}
          <span className="font-bold text-slate-800">{sortedData.length}</span>{" "}
          data
        </p>
        <div className="flex gap-2 w-full md:w-auto justify-between md:justify-end">
          <button
            onClick={() => setCurrentPage((p) => Math.max(1, p - 1))}
            disabled={currentPage === 1}
            className="px-4 py-2 rounded-xl border border-slate-200 text-sm font-bold text-slate-600 hover:bg-slate-50 disabled:opacity-50 transition-colors"
          >
            Sebelumnya
          </button>
          <button
            onClick={() => setCurrentPage((p) => Math.min(totalPages, p + 1))}
            disabled={currentPage === totalPages}
            className="px-4 py-2 rounded-xl border border-slate-200 text-sm font-bold text-slate-600 hover:bg-slate-50 disabled:opacity-50 transition-colors"
          >
            Selanjutnya
          </button>
        </div>
      </div>

      {/* --- 🔥 MODAL DETAIL PESERTA 🔥 --- */}
      {detailParticipant && (
        <div className="fixed inset-0 z-[200] flex items-center justify-center bg-slate-900/50 backdrop-blur-sm p-4 animate-in fade-in duration-200">
          <div className="bg-white rounded-3xl shadow-2xl w-full max-w-4xl max-h-[90vh] overflow-hidden flex flex-col animate-in zoom-in-95 duration-200">
            <div className="px-6 py-5 border-b border-slate-100 flex justify-between items-center bg-slate-50 shrink-0">
              <div>
                <h2 className="text-lg font-black text-slate-800 uppercase tracking-tight">
                  {detailParticipant.namaLengkap}
                </h2>
                <p className="text-xs text-slate-500 font-mono mt-0.5">
                  ID: {detailParticipant.id}
                </p>
              </div>
              <div className="flex flex-col items-end">
                <span
                  className={`px-3 py-1 text-[10px] uppercase tracking-wider font-black rounded-full border ${detailParticipant.statusPembayaran === "Lunas" ? "bg-[#E6F4EA] text-[#1E8E3E] border-[#1E8E3E]/20" : "bg-[#FEF7E0] text-[#B08D00] border-[#F9AB00]/20"}`}
                >
                  {detailParticipant.statusPembayaran}
                </span>
              </div>
            </div>

            <div className="flex-grow overflow-y-auto p-6 bg-white flex flex-col md:flex-row gap-8">
              <div className="flex-1 space-y-6">
                <div>
                  <h3 className="text-xs font-black text-slate-400 uppercase tracking-widest border-b border-slate-100 pb-2 mb-3">
                    Informasi Tiket
                  </h3>
                  <div className="grid grid-cols-2 gap-4">
                    <div>
                      <p className="text-[10px] text-slate-500 font-bold uppercase">
                        Nomor BIB
                      </p>
                      <p className="text-xl font-black font-mono text-[#1A73E8]">
                        {detailParticipant.nomorBIB || "Menunggu"}
                      </p>
                    </div>
                    <div>
                      <p className="text-[10px] text-slate-500 font-bold uppercase">
                        Kategori Jarak
                      </p>
                      <p className="text-base font-bold text-slate-800">
                        {detailParticipant.jarak}
                      </p>
                    </div>
                    <div>
                      <p className="text-[10px] text-slate-500 font-bold uppercase">
                        Nama di BIB
                      </p>
                      <p className="text-sm font-bold text-slate-800">
                        {detailParticipant.namaBib || "-"}
                      </p>
                    </div>
                    <div>
                      <p className="text-[10px] text-slate-500 font-bold uppercase">
                        Ukuran Jersey
                      </p>
                      <p className="text-sm font-black text-slate-800">
                        {detailParticipant.ukuranJersey || "-"}
                      </p>
                    </div>
                  </div>
                </div>

                <div>
                  <h3 className="text-xs font-black text-slate-400 uppercase tracking-widest border-b border-slate-100 pb-2 mb-3">
                    Data Pribadi
                  </h3>
                  <div className="grid grid-cols-2 gap-y-3 gap-x-4 text-sm">
                    <div>
                      <p className="text-[10px] text-slate-500 font-bold uppercase">
                        No Identitas (NIK)
                      </p>
                      <p className="font-medium text-slate-800">
                        {detailParticipant.nik || "-"}
                      </p>
                    </div>
                    <div>
                      <p className="text-[10px] text-slate-500 font-bold uppercase">
                        Gender / Darah
                      </p>
                      <p className="font-medium text-slate-800">
                        {detailParticipant.jenisKelamin || "-"} /{" "}
                        {detailParticipant.golonganDarah || "-"}
                      </p>
                    </div>
                    <div>
                      <p className="text-[10px] text-slate-500 font-bold uppercase">
                        WhatsApp
                      </p>
                      <p className="font-medium text-slate-800">
                        {detailParticipant.noWA || "-"}
                      </p>
                    </div>
                    <div>
                      <p className="text-[10px] text-slate-500 font-bold uppercase">
                        Email
                      </p>
                      <p className="font-medium text-slate-800 truncate">
                        {detailParticipant.email || "-"}
                      </p>
                    </div>
                    <div className="col-span-2">
                      <p className="text-[10px] text-slate-500 font-bold uppercase">
                        Riwayat Penyakit
                      </p>
                      <p className="font-medium text-rose-600">
                        {detailParticipant.riwayatPenyakit || "-"}
                      </p>
                    </div>
                  </div>
                </div>

                {detailParticipant.isRacepackTaken && (
                  <div className="bg-emerald-50 border border-emerald-100 rounded-xl p-4">
                    <div className="flex items-center gap-2 text-emerald-700 mb-2">
                      <svg
                        className="w-5 h-5"
                        fill="none"
                        viewBox="0 0 24 24"
                        stroke="currentColor"
                      >
                        <path
                          strokeLinecap="round"
                          strokeLinejoin="round"
                          strokeWidth={2}
                          d="M9 12l2 2 4-4m6 2a9 9 0 11-18 0 9 9 0 0118 0z"
                        />
                      </svg>
                      <p className="text-xs font-black uppercase tracking-wider">
                        Racepack Diserahkan
                      </p>
                    </div>
                    <div className="grid grid-cols-2 gap-2 text-xs">
                      <div>
                        <span className="text-slate-500">Waktu:</span>
                        <br />
                        <span className="font-bold text-emerald-800">
                          {new Date(
                            detailParticipant.waktuAmbilRacepack,
                          ).toLocaleString("id-ID")}
                        </span>
                      </div>
                      <div>
                        <span className="text-slate-500">Admin:</span>
                        <br />
                        <span className="font-bold text-emerald-800">
                          {detailParticipant.adminHandler || "-"}
                        </span>
                      </div>
                    </div>
                  </div>
                )}
              </div>

              <div className="md:w-72 shrink-0 flex flex-col">
                <h3 className="text-xs font-black text-slate-400 uppercase tracking-widest border-b border-slate-100 pb-2 mb-3">
                  Bukti Transfer
                </h3>
                <div className="bg-slate-50 border-2 border-dashed border-slate-200 rounded-2xl flex-grow flex items-center justify-center p-2 relative overflow-hidden group min-h-[200px]">
                  {detailParticipant.buktiBayarUrl ? (
                    <>
                      <img
                        src={detailParticipant.buktiBayarUrl}
                        alt="Bukti Transfer"
                        className="w-full h-full object-cover rounded-xl cursor-zoom-in"
                        onClick={() =>
                          setSelectedImage(detailParticipant.buktiBayarUrl)
                        }
                      />
                      <div className="absolute inset-0 bg-black/40 opacity-0 group-hover:opacity-100 transition-opacity pointer-events-none flex items-center justify-center">
                        <span className="text-white text-xs font-bold px-3 py-1 bg-black/50 rounded-full">
                          Perbesar Gambar
                        </span>
                      </div>
                    </>
                  ) : (
                    <div className="text-center">
                      <svg
                        className="w-10 h-10 text-slate-300 mx-auto mb-2"
                        fill="none"
                        viewBox="0 0 24 24"
                        stroke="currentColor"
                      >
                        <path
                          strokeLinecap="round"
                          strokeLinejoin="round"
                          strokeWidth={2}
                          d="M4 16l4.586-4.586a2 2 0 012.828 0L16 16m-2-2l1.586-1.586a2 2 0 012.828 0L20 14m-6-6h.01M6 20h12a2 2 0 002-2V6a2 2 0 00-2-2H6a2 2 0 00-2 2v12a2 2 0 002 2z"
                        />
                      </svg>
                      <p className="text-xs font-bold text-slate-400 uppercase">
                        Belum Upload
                      </p>
                    </div>
                  )}
                </div>

                <div className="mt-4 bg-blue-50 text-[#1A73E8] p-4 rounded-2xl flex flex-col justify-center min-h-[100px]">
                  {detailParticipant.kodePromoDipakai && (
                    <div className="mb-3 text-left text-xs space-y-1.5 border-b border-blue-200/50 pb-3">
                      <div className="flex justify-between text-slate-500 font-medium">
                        <span>Harga Asli:</span>
                        <span>
                          Rp{" "}
                          {detailParticipant.hargaAsli?.toLocaleString("id-ID")}
                        </span>
                      </div>
                      <div className="flex justify-between text-emerald-600 font-bold bg-emerald-50 px-2 py-1 rounded">
                        <span>
                          Promo ({detailParticipant.kodePromoDipakai}):
                        </span>
                        <span>
                          - Rp{" "}
                          {detailParticipant.totalDiskon?.toLocaleString(
                            "id-ID",
                          )}
                        </span>
                      </div>
                    </div>
                  )}
                  <div className="text-center">
                    <p className="text-[10px] font-bold uppercase tracking-widest mb-1 opacity-70">
                      Total Dibayar{" "}
                      {detailParticipant.kodePromoDipakai ? "(Nett)" : ""}
                    </p>
                    <p className="text-2xl font-black">
                      Rp{" "}
                      {detailParticipant.totalTagihan?.toLocaleString("id-ID")}
                    </p>
                  </div>
                </div>
              </div>
            </div>

            <div className="px-6 py-4 border-t border-slate-100 bg-slate-50 flex flex-col md:flex-row justify-end gap-3 shrink-0">
              {detailParticipant.statusPembayaran === "Pending" && (
                <button
                  onClick={() => {
                    triggerApprove(detailParticipant);
                    setDetailParticipant(null);
                  }}
                  className="bg-[#1A73E8] text-white text-sm font-bold px-6 py-2.5 rounded-lg shadow-sm hover:bg-[#1557B0] transition-colors order-1 md:order-2 flex items-center justify-center gap-2"
                >
                  <svg
                    className="w-4 h-4"
                    fill="none"
                    viewBox="0 0 24 24"
                    stroke="currentColor"
                  >
                    <path
                      strokeLinecap="round"
                      strokeLinejoin="round"
                      strokeWidth={2}
                      d="M9 12l2 2 4-4m6 2a9 9 0 11-18 0 9 9 0 0118 0z"
                    />
                  </svg>
                  Terima & Generate BIB
                </button>
              )}

              {detailParticipant.statusPembayaran === "Lunas" &&
                !detailParticipant.isRacepackTaken && (
                  <button
                    onClick={() =>
                      handleHandoverClick(
                        detailParticipant.id,
                        detailParticipant.namaLengkap,
                      )
                    }
                    disabled={actionLoading === detailParticipant.id}
                    className="bg-[#1E8E3E] text-white text-sm font-bold px-6 py-2.5 rounded-lg shadow-sm hover:bg-[#188038] transition-colors order-1 md:order-2 flex items-center justify-center gap-2 disabled:opacity-50"
                  >
                    {actionLoading === detailParticipant.id ? (
                      <div className="w-4 h-4 border-2 border-white/30 border-t-white rounded-full animate-spin"></div>
                    ) : (
                      <svg
                        className="w-4 h-4"
                        fill="none"
                        viewBox="0 0 24 24"
                        stroke="currentColor"
                      >
                        <path
                          strokeLinecap="round"
                          strokeLinejoin="round"
                          strokeWidth={2}
                          d="M5 13l4 4L19 7"
                        />
                      </svg>
                    )}
                    Serahkan Racepack
                  </button>
                )}

              <button
                onClick={() => setDetailParticipant(null)}
                className="bg-slate-100 border border-slate-200 text-slate-600 text-xs font-bold px-6 py-2.5 rounded-lg hover:bg-slate-200 transition-colors order-2 md:order-1 w-full md:w-auto"
              >
                Tutup
              </button>
            </div>
          </div>
        </div>
      )}

      {/* FULL PREVIEW STRUK */}
      {selectedImage && (
        <div
          className="fixed inset-0 z-[400] bg-black/90 flex items-center justify-center p-4 cursor-zoom-out animate-in fade-in duration-200"
          onClick={() => setSelectedImage(null)}
        >
          <img
            src={selectedImage}
            alt="Struk Zoom"
            className="max-w-full max-h-[95vh] object-contain rounded"
          />
          <div className="absolute top-4 right-4 text-white/50 text-sm font-bold bg-black/50 px-3 py-1 rounded-full">
            Klik dimana saja untuk tutup
          </div>
        </div>
      )}
    </div>
  );
}

"use client";

import { useEffect, useState } from "react";
import { db, auth } from "@/lib/firebase";
import {
  collection,
  onSnapshot,
  doc,
  updateDoc,
  writeBatch,
  addDoc,
  runTransaction,
  query,
} from "firebase/firestore";
import { onAuthStateChanged } from "firebase/auth";
import * as XLSX from "xlsx";
import { sendEmailAction } from "@/app/actions/email";


export default function AdminKomunitasPage() {
  const [groups, setGroups] = useState<any[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [filterStatus, setFilterStatus] = useState("Semua");
  const [searchQuery, setSearchQuery] = useState("");
  const [adminUser, setAdminUser] = useState<any>(null);

  // UI State
  const [selectedIds, setSelectedIds] = useState<string[]>([]);
  const [detailGroup, setDetailGroup] = useState<any>(null);
  const [selectedImage, setSelectedImage] = useState<string | null>(null);
  const [actionLoading, setActionLoading] = useState<string | null>(null);
  const [isBroadcasting, setIsBroadcasting] = useState(false);

  // --- 🔥 STATE CUSTOM MODALS (MENGGANTIKAN ALERT BAWAAN BROWSER) 🔥 ---
  const [alertModal, setAlertModal] = useState({
    isOpen: false,
    type: "success",
    title: "",
    message: "",
  });

  const [confirmModal, setConfirmModal] = useState<{
    isOpen: boolean;
    title: string;
    message: string;
    onConfirm: () => void;
  }>({
    isOpen: false,
    title: "",
    message: "",
    onConfirm: () => {},
  });

  // Modal Khusus Handover Komunitas
  const [handoverModal, setHandoverModal] = useState({
    isOpen: false,
    id: "",
    groupName: "",
    kaptenName: "",
    namaPengambil: "",
    metodeVerifikasi: "KTP",
  });

  const [approveProcess, setApproveProcess] = useState<{
    isOpen: boolean;
    group: any;
    step: "confirm" | "processing" | "success" | "error";
    message: string;
  }>({ isOpen: false, group: null, step: "confirm", message: "" });

  // --- STATE PAGINATION, SORTING & LIMIT ---
  const [sortConfig, setSortConfig] = useState<{
    key: string;
    direction: "asc" | "desc";
  }>({ key: "createdAt", direction: "desc" });
  const [itemsPerPage, setItemsPerPage] = useState<number | "All">(10);
  const [currentPage, setCurrentPage] = useState(1);

  useEffect(() => {
    const unsubscribe = onAuthStateChanged(auth, (user) => {
      setAdminUser(user);
    });
    return () => unsubscribe();
  }, []);

  useEffect(() => {
    const q = query(collection(db, "pendaftaran_komunitas"));
    const unsubscribe = onSnapshot(q, (snapshot) => {
      const data = snapshot.docs.map((doc) => ({ id: doc.id, ...doc.data() }));
      setGroups(data);
      setIsLoading(false);
    });
    return () => unsubscribe();
  }, []);

  const getJerseySummary = (participants: any[]) => {
    if (!participants) return {};
    return participants.reduce((acc: any, p: any) => {
      const size = p.ukuranJersey || "Tanpa Ukuran";
      acc[size] = (acc[size] || 0) + 1;
      return acc;
    }, {});
  };

  // --- LOGIKA FILTER, SEARCH, SORTING & PAGINATION ---
  const filteredData = groups.filter((g) => {
    const matchStatus =
      filterStatus === "Semua" || g.statusPembayaran === filterStatus;
    const matchSearch =
      g.kapten?.nama?.toLowerCase().includes(searchQuery.toLowerCase()) ||
      g.kapten?.komunitas?.toLowerCase().includes(searchQuery.toLowerCase()) ||
      g.kapten?.email?.toLowerCase().includes(searchQuery.toLowerCase()) ||
      g.kapten?.wa?.includes(searchQuery) ||
      g.id?.includes(searchQuery);

    return matchStatus && matchSearch;
  });

  const sortedData = [...filteredData].sort((a, b) => {
    let valA = a[sortConfig.key] || "";
    let valB = b[sortConfig.key] || "";

    if (sortConfig.key === "komunitas") {
      valA = a.kapten?.komunitas || "";
      valB = b.kapten?.komunitas || "";
    }
    if (sortConfig.key === "namaKapten") {
      valA = a.kapten?.nama || "";
      valB = b.kapten?.nama || "";
    }

    if (typeof valA === "string") valA = valA.toLowerCase();
    if (typeof valB === "string") valB = valB.toLowerCase();

    if (valA < valB) return sortConfig.direction === "asc" ? -1 : 1;
    if (valA > valB) return sortConfig.direction === "asc" ? 1 : -1;
    return 0;
  });

  const handleSort = (key: string) => {
    let direction: "asc" | "desc" = "asc";
    if (sortConfig.key === key && sortConfig.direction === "asc")
      direction = "desc";
    setSortConfig({ key, direction });
  };

  const totalPages =
    itemsPerPage === "All" ? 1 : Math.ceil(sortedData.length / itemsPerPage);

  const paginatedData =
    itemsPerPage === "All"
      ? sortedData
      : sortedData.slice(
          (currentPage - 1) * (itemsPerPage as number),
          currentPage * (itemsPerPage as number),
        );

  // --- REKAP STATISTIK ---
  const totalLunas = groups.filter(
    (g) => g.statusPembayaran === "Lunas",
  ).length;
  const totalPending = groups.filter(
    (g) => g.statusPembayaran !== "Lunas",
  ).length;
  const totalUangLunas = groups
    .filter((g) => g.statusPembayaran === "Lunas")
    .reduce((acc, curr) => acc + (Number(curr.totalBiaya) || 0), 0);
  const totalPesertaGrup = groups.reduce(
    (acc, curr) => acc + (curr.participants?.length || 0),
    0,
  );

  // --- SELECTION LOGIC ---
  const toggleSelect = (id: string) => {
    setSelectedIds((prev) =>
      prev.includes(id) ? prev.filter((i) => i !== id) : [...prev, id],
    );
  };

  const toggleSelectAllVisible = () => {
    if (
      selectedIds.length === paginatedData.length &&
      paginatedData.length > 0
    ) {
      setSelectedIds([]);
    } else {
      setSelectedIds(paginatedData.map((g) => g.id));
    }
  };

  // --- FITUR EKSPOR EXCEL ---
  const handleExportExcel = () => {
    const excelData: any[] = [];

    sortedData.forEach((g) => {
      let dateDaftar = "-";
      if (g.createdAt) {
        if (g.createdAt.seconds)
          dateDaftar = new Date(g.createdAt.seconds * 1000).toLocaleString(
            "id-ID",
          );
        else dateDaftar = new Date(g.createdAt).toLocaleString("id-ID");
      }

      if (g.participants && g.participants.length > 0) {
        g.participants.forEach((p: any) => {
          excelData.push({
            "ID Grup / Verifikasi": g.id,
            "Nama Komunitas": g.kapten?.komunitas || "-",
            "Nama Kapten (PJ)": g.kapten?.nama || "-",
            "Waktu Daftar": dateDaftar,
            "Status Pembayaran": g.statusPembayaran || "Belum Bayar",
            "Waktu Lunas": g.waktuLunas
              ? new Date(g.waktuLunas).toLocaleString("id-ID")
              : "-",
            "Nama Peserta": p.namaLengkap || "-",
            NIK: p.nik || "-",
            Kategori: p.kategori || "-",
            "Nomor BIB": p.nomorBIB || p.bib || "-",
            "Jenis Kelamin": p.gender || "-",
            "Golongan Darah": p.golDarah || "-",
            "Ukuran Jersey": p.ukuranJersey || "-",
            "No Darurat": p.waDarurat || "-",
            "Nama Darurat": p.kontakDarurat || "-",
            "Riwayat Penyakit": p.riwayatPenyakit || "-",
            "Status Racepack": g.isRacepackTaken ? "SUDAH DIAMBIL" : "BELUM",
            "Diserahkan Kepada": g.namaPengambilAtribut || "-",
            "Verifikasi RPC": g.metodeVerifikasiRPC || "-",
            "Admin Lapangan": g.adminHandler || "-",
          });
        });
      } else {
        excelData.push({
          "ID Grup / Verifikasi": g.id,
          "Nama Komunitas": g.kapten?.komunitas || "-",
          "Nama Kapten (PJ)": g.kapten?.nama || "-",
          "Waktu Daftar": dateDaftar,
          "Status Pembayaran": g.statusPembayaran || "Belum Bayar",
          "Waktu Lunas": g.waktuLunas
            ? new Date(g.waktuLunas).toLocaleString("id-ID")
            : "-",
          "Nama Peserta": "KOSONG",
          "Status Racepack": g.isRacepackTaken ? "SUDAH DIAMBIL" : "BELUM",
        });
      }
    });

    const worksheet = XLSX.utils.json_to_sheet(excelData);
    const workbook = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(
      workbook,
      worksheet,
      "Detail_Peserta_Komunitas",
    );
    XLSX.writeFile(
      workbook,
      `REKAP_FULL_KOMUNITAS_${new Date().getTime()}.xlsx`,
    );
  };

  // --- 🔥 FITUR BROADCAST REMINDER RACEPACK (KOMUNITAS) 🔥 ---
  const handleBroadcastReminderClick = () => {
    const targetGroups = groups.filter(
      (g) => g.statusPembayaran === "Lunas" && !g.isRacepackTaken,
    );

    if (targetGroups.length === 0) {
      setAlertModal({
        isOpen: true,
        type: "warning",
        title: "Target Kosong",
        message:
          "Tidak ada Grup/Komunitas yang memenuhi syarat (Lunas & Belum Ambil Racepack).",
      });
      return;
    }

    setConfirmModal({
      isOpen: true,
      title: "Konfirmasi Broadcast",
      message: `Anda akan mengirim Email Reminder Pengambilan Racepack Kolektif kepada Kapten dari ${targetGroups.length} Grup/Komunitas. Lanjutkan?`,
      onConfirm: () => executeBroadcastReminder(targetGroups),
    });
  };

  const executeBroadcastReminder = async (targetGroups: any[]) => {
    setIsBroadcasting(true);
    let successCount = 0;
    let failCount = 0;

    for (const group of targetGroups) {
      try {
        const res = await sendEmailAction({
            type: "reminder_racepack_komunitas",
            email: group.kapten?.email,
            nama: group.kapten?.nama,
            detail: {
              id: group.id,
              komunitas: group.kapten?.komunitas || "-",
              totalPeserta: group.participants?.length || 0,
              totalBiaya: group.totalBiaya || 0,
              participants: group.participants || [],
            },
          });

        if (res.success) successCount++;
        else failCount++;
      } catch (error) {
        failCount++;
      }
      await new Promise((resolve) => setTimeout(resolve, 1000));
    }

    setIsBroadcasting(false);
    setAlertModal({
      isOpen: true,
      type: "success",
      title: "Broadcast Selesai",
      message: `Berhasil terkirim: ${successCount} Kapten Tim\nGagal terkirim: ${failCount} Kapten Tim\n\nPastikan koneksi internet stabil jika ada pengiriman yang gagal.`,
    });
  };

  // --- 🔥 AKSI PEMBAYARAN & GENERATE BIB KOMUNITAS DENGAN GLOBAL COUNTER 🔥 ---
  const triggerApprove = (g: any) => {
    setApproveProcess({
      isOpen: true,
      group: g,
      step: "confirm",
      message: "",
    });
  };

  const executeApproveProcess = async () => {
    const g = approveProcess.group;
    if (!g) return;

    setApproveProcess((prev) => ({
      ...prev,
      step: "processing",
      message: "Menerbitkan Nomor BIB Komunitas (Format K-)...",
    }));

    try {
      let finalParticipants: any[] = [];

      await runTransaction(db, async (transaction) => {
        const counterDocRef = doc(db, "settings", "bib_counter");
        const groupRef = doc(db, "pendaftaran_komunitas", g.id);

        const counterDoc = await transaction.get(counterDocRef);
        let current5K = counterDoc.exists()
          ? counterDoc.data().lastBib5K || 0
          : 0;
        let current10K = counterDoc.exists()
          ? counterDoc.data().lastBib10K || 0
          : 0;

        finalParticipants = (g.participants || []).map((member: any) => {
          if (member.nomorBIB || member.bib) return member;

          const jarakAngka = (member.kategori || "9").replace(/\D/g, "") || "9";
          let newCounter = 0;
          let generatedBib = "";

          if (jarakAngka === "5") {
            current5K++;
            newCounter = current5K;
            generatedBib = `K-5${String(newCounter).padStart(3, "0")}`;
          } else if (jarakAngka === "10") {
            current10K++;
            newCounter = current10K;
            generatedBib = `K-10${String(newCounter).padStart(3, "0")}`;
          } else {
            newCounter = Math.floor(1000 + Math.random() * 8000);
            generatedBib = `K-${jarakAngka}${newCounter}`;
          }

          return { ...member, nomorBIB: generatedBib, bib: generatedBib };
        });

        transaction.set(
          counterDocRef,
          { lastBib5K: current5K, lastBib10K: current10K },
          { merge: true },
        );
        transaction.update(groupRef, {
          statusPembayaran: "Lunas",
          waktuLunas: new Date().toISOString(),
          participants: finalParticipants,
        });
      });

      setApproveProcess((prev) => ({
        ...prev,
        message: "Mengirim E-Ticket Kolektif ke email Kapten...",
      }));

      const res = await sendEmailAction({
          type: "payment_success_komunitas",
          email: g.kapten?.email,
          nama: g.kapten?.nama,
          detail: {
            id: g.id,
            komunitas: g.kapten?.komunitas || "-",
            totalPeserta: finalParticipants.length || 0,
            totalBiaya: g.totalBiaya || 0,
            participants: finalParticipants,
          },
        });

      if (!res.success)
        console.warn("Gagal mengirim email E-Ticket komunitas dari server.");

      await addDoc(collection(db, "vr_logs"), {
        type: "bayar",
        action: `menyetujui pembayaran komunitas (Generate BIB K-)`,
        targetName: g.kapten?.komunitas,
        adminEmail: adminUser?.email || "Admin",
        timestamp: Date.now(),
      });

      if (detailGroup?.id === g.id) {
        setDetailGroup((prev: any) => ({
          ...prev,
          statusPembayaran: "Lunas",
          participants: finalParticipants,
        }));
      }

      setApproveProcess((prev) => ({
        ...prev,
        step: "success",
        message: `Selesai! BIB Komunitas berhasil diterbitkan dengan prefix 'K-' dan Email E-Ticket telah dikirim.`,
      }));
    } catch (e: any) {
      setApproveProcess((prev) => ({
        ...prev,
        step: "error",
        message: e.message || "Terjadi kesalahan jaringan atau server.",
      }));
    }
  };

  const closeApproveProcess = () => {
    setApproveProcess({
      isOpen: false,
      group: null,
      step: "confirm",
      message: "",
    });
  };

  // --- 🔥 AKSI PENYERAHAN LOGISTIK KOLEKTIF DENGAN VERIFIKASI KEAMANAN 🔥 ---
  const openHandoverKomunitas = (
    id: string,
    groupName: string,
    kaptenName: string,
  ) => {
    setHandoverModal({
      isOpen: true,
      id,
      groupName,
      kaptenName,
      namaPengambil: kaptenName,
      metodeVerifikasi: "KTP",
    });
  };

  const executeHandoverKomunitas = async () => {
    const { id, groupName, namaPengambil, metodeVerifikasi } = handoverModal;
    const adminEmail = auth.currentUser?.email || "Admin Lapangan";

    if (!namaPengambil.trim() || !metodeVerifikasi.trim()) {
      setAlertModal({
        isOpen: true,
        type: "warning",
        title: "Data Tidak Lengkap",
        message: "Nama Pengambil dan Metode Verifikasi wajib diisi!",
      });
      return;
    }

    setActionLoading(id);

    try {
      const dataUpdate = {
        isRacepackTaken: true,
        waktuAmbilRacepack: new Date().toISOString(),
        adminHandler: adminEmail,
        namaPengambilAtribut: namaPengambil,
        metodeVerifikasiRPC: metodeVerifikasi,
      };

      await updateDoc(doc(db, "pendaftaran_komunitas", id), dataUpdate);

      if (detailGroup?.id === id) {
        setDetailGroup({ ...detailGroup, ...dataUpdate });
      }

      await addDoc(collection(db, "vr_logs"), {
        type: "resi",
        action: `menyerahkan racepack komunitas kolektif kepada ${namaPengambil} (Verifikasi via ${metodeVerifikasi})`,
        targetName: groupName,
        adminEmail: adminEmail,
        timestamp: Date.now(),
      });

      setAlertModal({
        isOpen: true,
        type: "success",
        title: "Racepack Diserahkan",
        message: `Sukses! Racepack Komunitas ${groupName} berhasil diserahkan kepada ${namaPengambil}.`,
      });
    } catch (e) {
      setAlertModal({
        isOpen: true,
        type: "error",
        title: "Gagal",
        message: "Terjadi kesalahan. Gagal memproses penyerahan.",
      });
    }

    setActionLoading(null);
  };

  const handleBulkDeleteClick = () => {
    setConfirmModal({
      isOpen: true,
      title: "Konfirmasi Hapus",
      message: `Hapus ${selectedIds.length} data komunitas ini beserta seluruh pesertanya secara permanen? Tindakan ini tidak dapat dibatalkan.`,
      onConfirm: async () => {
        const batch = writeBatch(db);
        selectedIds.forEach((id) =>
          batch.delete(doc(db, "pendaftaran_komunitas", id)),
        );
        await batch.commit();
        setSelectedIds([]);
        setAlertModal({
          isOpen: true,
          type: "success",
          title: "Berhasil",
          message: "Data komunitas berhasil dihapus.",
        });
      },
    });
  };

  if (isLoading)
    return (
      <div className="h-screen flex flex-col items-center justify-center text-[#1A73E8] font-medium text-sm">
        <div className="w-8 h-8 border-4 border-blue-100 border-t-[#1A73E8] rounded-full animate-spin mb-4"></div>
        MEMUAT DATA...
      </div>
    );

  return (
    <div className="animate-in fade-in duration-300 flex flex-col h-[calc(100vh-2rem)] max-w-7xl mx-auto font-sans relative">
      {/* --- 🔥 KUMPULAN MODAL (MENGGANTIKAN ALERT & PROMPT BAWAAN) 🔥 --- */}

      {/* 1. Modal Alert (Success/Error/Warning) */}
      {alertModal.isOpen && (
        <div className="fixed inset-0 z-[500] flex items-center justify-center bg-slate-900/60 backdrop-blur-sm p-4 animate-in fade-in duration-200">
          <div className="bg-white rounded-3xl shadow-2xl w-full max-w-sm overflow-hidden animate-in zoom-in-95 duration-200">
            <div
              className={`p-8 text-center ${alertModal.type === "error" ? "bg-rose-50" : alertModal.type === "success" ? "bg-emerald-50" : "bg-amber-50"}`}
            >
              <div
                className={`w-16 h-16 mx-auto rounded-full flex items-center justify-center mb-4 text-3xl shadow-sm ${alertModal.type === "error" ? "bg-rose-100 text-rose-600" : alertModal.type === "success" ? "bg-emerald-100 text-emerald-600" : "bg-amber-100 text-amber-600"}`}
              >
                {alertModal.type === "error" ? (
                  <svg
                    className="w-8 h-8"
                    fill="none"
                    viewBox="0 0 24 24"
                    stroke="currentColor"
                  >
                    <path
                      strokeLinecap="round"
                      strokeLinejoin="round"
                      strokeWidth={2.5}
                      d="M6 18L18 6M6 6l12 12"
                    />
                  </svg>
                ) : alertModal.type === "success" ? (
                  <svg
                    className="w-8 h-8"
                    fill="none"
                    viewBox="0 0 24 24"
                    stroke="currentColor"
                  >
                    <path
                      strokeLinecap="round"
                      strokeLinejoin="round"
                      strokeWidth={2.5}
                      d="M5 13l4 4L19 7"
                    />
                  </svg>
                ) : (
                  <svg
                    className="w-8 h-8"
                    fill="none"
                    viewBox="0 0 24 24"
                    stroke="currentColor"
                  >
                    <path
                      strokeLinecap="round"
                      strokeLinejoin="round"
                      strokeWidth={2.5}
                      d="M12 9v2m0 4h.01m-6.938 4h13.856c1.54 0 2.502-1.667 1.732-3L13.732 4c-.77-1.333-2.694-1.333-3.464 0L3.34 16c-.77 1.333.192 3 1.732 3z"
                    />
                  </svg>
                )}
              </div>
              <h3 className="text-xl font-black text-slate-800 tracking-tight">
                {alertModal.title}
              </h3>
            </div>
            <div className="p-6 text-center">
              <p className="text-sm text-slate-600 leading-relaxed mb-6 whitespace-pre-wrap">
                {alertModal.message}
              </p>
              <button
                onClick={() => setAlertModal({ ...alertModal, isOpen: false })}
                className="w-full bg-slate-800 hover:bg-slate-900 text-white font-bold py-3.5 rounded-xl transition-colors shadow-md"
              >
                Mengerti
              </button>
            </div>
          </div>
        </div>
      )}

      {/* 2. Modal Confirm (Yes/No) */}
      {confirmModal.isOpen && (
        <div className="fixed inset-0 z-[500] flex items-center justify-center bg-slate-900/60 backdrop-blur-sm p-4 animate-in fade-in duration-200">
          <div className="bg-white rounded-3xl shadow-2xl w-full max-w-sm overflow-hidden animate-in zoom-in-95 duration-200">
            <div className="p-8 text-center bg-blue-50">
              <div className="w-16 h-16 mx-auto rounded-full flex items-center justify-center mb-4 bg-blue-100 text-blue-600 shadow-sm">
                <svg
                  className="w-8 h-8"
                  fill="none"
                  viewBox="0 0 24 24"
                  stroke="currentColor"
                >
                  <path
                    strokeLinecap="round"
                    strokeLinejoin="round"
                    strokeWidth={2.5}
                    d="M8 16H6a2 2 0 01-2-2V6a2 2 0 012-2h8a2 2 0 012 2v2m-6 12h8a2 2 0 002-2v-8a2 2 0 00-2-2h-8a2 2 0 00-2 2v8a2 2 0 002 2z"
                  />
                </svg>
              </div>
              <h3 className="text-xl font-black text-slate-800 tracking-tight">
                {confirmModal.title}
              </h3>
            </div>
            <div className="p-6 text-center">
              <p className="text-sm text-slate-600 leading-relaxed mb-6 whitespace-pre-wrap">
                {confirmModal.message}
              </p>
              <div className="flex gap-3">
                <button
                  onClick={() =>
                    setConfirmModal({ ...confirmModal, isOpen: false })
                  }
                  className="w-full bg-slate-100 hover:bg-slate-200 text-slate-700 font-bold py-3 rounded-xl transition-colors"
                >
                  Batal
                </button>
                <button
                  onClick={() => {
                    setConfirmModal({ ...confirmModal, isOpen: false });
                    confirmModal.onConfirm();
                  }}
                  className="w-full bg-[#1A73E8] hover:bg-[#1557B0] text-white font-bold py-3 rounded-xl transition-colors shadow-md"
                >
                  Ya, Lanjutkan
                </button>
              </div>
            </div>
          </div>
        </div>
      )}

      {/* 3. Modal Handover RPC Komunitas (Menggantikan 2x Prompt) */}
      {handoverModal.isOpen && (
        <div className="fixed inset-0 z-[500] flex items-center justify-center bg-slate-900/60 backdrop-blur-sm p-4 animate-in fade-in duration-200">
          <div className="bg-white rounded-3xl shadow-2xl w-full max-w-md overflow-hidden animate-in zoom-in-95 duration-200">
            <div className="px-6 py-5 border-b border-slate-100 bg-slate-50">
              <h3 className="text-lg font-black text-slate-800">
                Verifikasi Pengambilan Racepack
              </h3>
              <p className="text-xs text-slate-500 mt-1">
                Tim {handoverModal.groupName}
              </p>
            </div>
            <div className="p-6 space-y-5">
              <div>
                <label className="block text-xs font-bold text-slate-600 uppercase tracking-wide mb-1.5">
                  Nama Pengambil Atribut
                </label>
                <input
                  type="text"
                  value={handoverModal.namaPengambil}
                  onChange={(e) =>
                    setHandoverModal({
                      ...handoverModal,
                      namaPengambil: e.target.value,
                    })
                  }
                  className="w-full px-4 py-3 bg-white border border-slate-200 rounded-xl text-sm font-bold text-slate-800 outline-none focus:border-[#1A73E8] transition-colors shadow-sm"
                  placeholder="Nama Penanggung Jawab di Lokasi"
                />
                <p className="text-[10px] text-slate-400 mt-1.5 leading-relaxed">
                  Ubah nama di atas jika atribut diambil oleh perwakilan (selain
                  kapten: {handoverModal.kaptenName}).
                </p>
              </div>
              <div>
                <label className="block text-xs font-bold text-slate-600 uppercase tracking-wide mb-1.5">
                  Metode Bukti Verifikasi
                </label>
                <select
                  value={handoverModal.metodeVerifikasi}
                  onChange={(e) =>
                    setHandoverModal({
                      ...handoverModal,
                      metodeVerifikasi: e.target.value,
                    })
                  }
                  className="w-full px-4 py-3 bg-white border border-slate-200 rounded-xl text-sm font-bold text-slate-800 outline-none focus:border-[#1A73E8] transition-colors shadow-sm cursor-pointer"
                >
                  <option value="KTP">KTP Asli / Identitas Lainnya</option>
                  <option value="E-TICKET">Scan QR E-Ticket</option>
                  <option value="WHATSAPP">Bukti Chat WhatsApp</option>
                  <option value="SURAT KUASA">Surat Kuasa Resmi</option>
                </select>
              </div>
            </div>
            <div className="px-6 py-4 border-t border-slate-100 bg-slate-50 flex gap-3 justify-end">
              <button
                onClick={() =>
                  setHandoverModal({ ...handoverModal, isOpen: false })
                }
                className="px-5 py-2.5 rounded-xl text-sm font-bold text-slate-600 hover:bg-slate-200 transition-colors"
              >
                Batal
              </button>
              <button
                onClick={() => {
                  setHandoverModal({ ...handoverModal, isOpen: false });
                  executeHandoverKomunitas();
                }}
                className="px-5 py-2.5 rounded-xl text-sm font-bold bg-[#1E8E3E] text-white hover:bg-[#188038] shadow-md transition-colors flex items-center gap-2"
              >
                <svg
                  className="w-4 h-4"
                  fill="none"
                  viewBox="0 0 24 24"
                  stroke="currentColor"
                >
                  <path
                    strokeLinecap="round"
                    strokeLinejoin="round"
                    strokeWidth={2}
                    d="M5 13l4 4L19 7"
                  />
                </svg>
                Konfirmasi Penyerahan
              </button>
            </div>
          </div>
        </div>
      )}

      {/* 4. Modal Approve Progress (Untuk Generate BIB & Email) */}
      {approveProcess.isOpen && approveProcess.group && (
        <div className="fixed inset-0 z-[500] flex items-center justify-center bg-slate-900/50 backdrop-blur-sm p-4">
          <div className="bg-white rounded-2xl shadow-2xl w-full max-w-sm overflow-hidden animate-in zoom-in-95 duration-200">
            <div className="p-6">
              {approveProcess.step === "confirm" && (
                <div className="text-center">
                  <div className="w-16 h-16 bg-blue-50 text-[#1A73E8] rounded-full flex items-center justify-center mx-auto mb-4">
                    <svg
                      className="w-8 h-8"
                      fill="none"
                      viewBox="0 0 24 24"
                      stroke="currentColor"
                    >
                      <path
                        strokeLinecap="round"
                        strokeLinejoin="round"
                        strokeWidth={2}
                        d="M9 12l2 2 4-4m6 2a9 9 0 11-18 0 9 9 0 0118 0z"
                      />
                    </svg>
                  </div>
                  <h3 className="text-lg font-bold text-slate-800 mb-2">
                    Verifikasi Pembayaran Komunitas
                  </h3>
                  <p className="text-sm text-slate-600 mb-6">
                    Anda akan menyetujui status LUNAS untuk grup{" "}
                    <strong>{approveProcess.group.kapten?.komunitas}</strong>.
                    <br />
                    Sistem akan mengirimkan email E-Ticket Kolektif ke Kapten.
                  </p>
                  <div className="flex gap-3 justify-center">
                    <button
                      onClick={closeApproveProcess}
                      className="px-5 py-2.5 text-sm font-bold text-slate-600 hover:bg-slate-100 rounded-lg transition-colors w-full"
                    >
                      Batal
                    </button>
                    <button
                      onClick={executeApproveProcess}
                      className="px-5 py-2.5 text-sm font-bold bg-[#1A73E8] text-white rounded-lg hover:bg-[#1557B0] transition-colors shadow-sm w-full"
                    >
                      Terima & Kirim
                    </button>
                  </div>
                </div>
              )}

              {approveProcess.step === "processing" && (
                <div className="text-center py-6">
                  <div className="w-12 h-12 border-4 border-blue-100 border-t-[#1A73E8] rounded-full animate-spin mx-auto mb-4"></div>
                  <h3 className="text-base font-bold text-slate-800 mb-1">
                    Harap Tunggu...
                  </h3>
                  <p className="text-xs text-slate-500 animate-pulse">
                    {approveProcess.message}
                  </p>
                </div>
              )}

              {approveProcess.step === "success" && (
                <div className="text-center py-4">
                  <div className="w-16 h-16 bg-[#E6F4EA] text-[#1E8E3E] rounded-full flex items-center justify-center mx-auto mb-4">
                    <svg
                      className="w-8 h-8"
                      fill="none"
                      viewBox="0 0 24 24"
                      stroke="currentColor"
                    >
                      <path
                        strokeLinecap="round"
                        strokeLinejoin="round"
                        strokeWidth={3}
                        d="M5 13l4 4L19 7"
                      />
                    </svg>
                  </div>
                  <h3 className="text-lg font-bold text-slate-800 mb-2">
                    Selesai!
                  </h3>
                  <p className="text-sm text-slate-600 mb-6">
                    {approveProcess.message}
                  </p>
                  <button
                    onClick={closeApproveProcess}
                    className="w-full bg-slate-100 text-slate-700 hover:bg-slate-200 py-3 rounded-xl font-bold transition-colors"
                  >
                    Tutup
                  </button>
                </div>
              )}

              {approveProcess.step === "error" && (
                <div className="text-center py-4">
                  <div className="w-16 h-16 bg-[#FCE8E6] text-[#D93025] rounded-full flex items-center justify-center mx-auto mb-4">
                    <svg
                      className="w-8 h-8"
                      fill="none"
                      viewBox="0 0 24 24"
                      stroke="currentColor"
                    >
                      <path
                        strokeLinecap="round"
                        strokeLinejoin="round"
                        strokeWidth={3}
                        d="M6 18L18 6M6 6l12 12"
                      />
                    </svg>
                  </div>
                  <h3 className="text-lg font-bold text-slate-800 mb-2">
                    Gagal
                  </h3>
                  <p className="text-sm text-slate-600 mb-6">
                    {approveProcess.message}
                  </p>
                  <button
                    onClick={closeApproveProcess}
                    className="w-full bg-slate-100 text-slate-700 hover:bg-slate-200 py-3 rounded-xl font-bold transition-colors"
                  >
                    Tutup
                  </button>
                </div>
              )}
            </div>
          </div>
        </div>
      )}

      {/* --- BAGIAN ATAS: TITLE & EXPORT --- */}
      <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4 mb-4 shrink-0 px-1">
        <div>
          <h1 className="text-2xl font-black text-slate-800 tracking-tight">
            Pendaftar Offline Run
          </h1>
          <p className="text-sm text-slate-500 font-medium">
            Verifikasi pembayaran dan manajemen logistik racepack
          </p>
        </div>
        <div className="flex items-center gap-3 w-full md:w-auto">
          {selectedIds.length > 0 && (
            <button
              onClick={handleBulkDeleteClick}
              className="bg-[#FCE8E6] text-[#D93025] hover:bg-red-100 px-4 py-2 rounded-xl text-sm font-bold border border-red-200 transition-colors w-full md:w-auto shadow-sm"
            >
              Hapus ({selectedIds.length})
            </button>
          )}

          {/* TOMBOL BROADCAST REMINDER */}
          <button
            onClick={handleBroadcastReminderClick}
            disabled={isBroadcasting}
            className="px-4 py-2 bg-[#FCD116] text-[#0B2239] rounded-xl text-sm font-bold hover:bg-yellow-500 transition-colors flex items-center gap-2 shadow-sm disabled:opacity-50"
          >
            {isBroadcasting ? (
              <div className="w-4 h-4 border-2 border-[#0B2239] border-t-transparent rounded-full animate-spin"></div>
            ) : (
              <svg
                className="w-4 h-4"
                fill="none"
                viewBox="0 0 24 24"
                stroke="currentColor"
              >
                <path
                  strokeLinecap="round"
                  strokeLinejoin="round"
                  strokeWidth={2}
                  d="M11 5.882V19.24a1.76 1.76 0 01-3.417.592l-2.147-6.15M18 13a3 3 0 100-6M5.436 13.683A4.001 4.001 0 017 6h1.832c4.1 0 7.625-1.234 9.168-3v14c-1.543-1.766-5.067-3-9.168-3H7a3.988 3.988 0 01-1.564-.317z"
                />
              </svg>
            )}
            {isBroadcasting ? "Mengirim..." : "Kirim Reminder (RPC)"}
          </button>

          <button
            onClick={handleExportExcel}
            className="bg-[#0B2239] text-[#FCD116] px-5 py-2.5 rounded-xl text-sm font-bold shadow-sm hover:bg-slate-800 transition-colors w-full md:w-auto"
          >
            Ekspor Excel
          </button>
        </div>
      </div>

      {/* --- STATISTIK --- */}
      <div className="grid grid-cols-1 md:grid-cols-4 gap-4 mb-6 shrink-0">
        <div className="bg-white p-5 rounded-2xl shadow-sm border border-slate-100 flex items-center justify-between">
          <div>
            <p className="text-sm font-medium text-slate-500 mb-1">
              Total Grup
            </p>
            <p className="text-2xl font-black text-slate-800">
              {groups.length}
            </p>
          </div>
          <div className="w-12 h-12 bg-blue-50 text-blue-600 rounded-full flex items-center justify-center">
            <svg
              className="w-6 h-6"
              fill="none"
              viewBox="0 0 24 24"
              stroke="currentColor"
            >
              <path
                strokeLinecap="round"
                strokeLinejoin="round"
                strokeWidth={2}
                d="M17 20h5v-2a3 3 0 00-5.356-1.857M17 20H7m10 0v-2c0-.656-.126-1.283-.356-1.857M7 20H2v-2a3 3 0 015.356-1.857M7 20v-2c0-.656.126-1.283.356-1.857m0 0a5.002 5.002 0 019.288 0M15 7a3 3 0 11-6 0 3 3 0 016 0zm6 3a2 2 0 11-4 0 2 2 0 014 0zM7 10a2 2 0 11-4 0 2 2 0 014 0z"
              />
            </svg>
          </div>
        </div>

        <div className="bg-white p-5 rounded-2xl shadow-sm border border-slate-100 flex items-center justify-between">
          <div>
            <p className="text-sm font-medium text-slate-500 mb-1">
              Total Peserta
            </p>
            <p className="text-2xl font-black text-slate-800">
              {totalPesertaGrup}
            </p>
          </div>
          <div className="w-12 h-12 bg-indigo-50 text-indigo-600 rounded-full flex items-center justify-center">
            <svg
              className="w-6 h-6"
              fill="none"
              viewBox="0 0 24 24"
              stroke="currentColor"
            >
              <path
                strokeLinecap="round"
                strokeLinejoin="round"
                strokeWidth={2}
                d="M12 4.354a4 4 0 110 5.292M15 21H3v-1a6 6 0 0112 0v1zm0 0h6v-1a6 6 0 00-9-5.197M13 7a4 4 0 11-8 0 4 4 0 018 0z"
              />
            </svg>
          </div>
        </div>

        <div className="bg-white p-5 rounded-2xl shadow-sm border border-slate-100 flex items-center justify-between">
          <div>
            <p className="text-sm font-medium text-slate-500 mb-1">
              Grup Lunas
            </p>
            <p className="text-2xl font-black text-emerald-600">{totalLunas}</p>
          </div>
          <div className="w-12 h-12 bg-emerald-50 text-emerald-600 rounded-full flex items-center justify-center">
            <svg
              className="w-6 h-6"
              fill="none"
              viewBox="0 0 24 24"
              stroke="currentColor"
            >
              <path
                strokeLinecap="round"
                strokeLinejoin="round"
                strokeWidth={2}
                d="M9 12l2 2 4-4m6 2a9 9 0 11-18 0 9 9 0 0118 0z"
              />
            </svg>
          </div>
        </div>

        <div className="bg-white p-5 rounded-2xl shadow-sm border border-slate-100 flex items-center justify-between">
          <div>
            <p className="text-sm font-medium text-slate-500 mb-1">
              Dana Masuk
            </p>
            <p className="text-xl font-black text-[#0B2239]">
              Rp {totalUangLunas.toLocaleString("id-ID")}
            </p>
          </div>
          <div className="w-12 h-12 bg-yellow-50 text-yellow-600 rounded-full flex items-center justify-center">
            <svg
              className="w-6 h-6"
              fill="none"
              viewBox="0 0 24 24"
              stroke="currentColor"
            >
              <path
                strokeLinecap="round"
                strokeLinejoin="round"
                strokeWidth={2}
                d="M12 8c-1.657 0-3 .895-3 2s1.343 2 3 2 3 .895 3 2-1.343 2-3 2m0-8c1.11 0 2.08.402 2.599 1M12 8V7m0 1v8m0 0v1m0-1c-1.11 0-2.08-.402-2.599-1M21 12a9 9 0 11-18 0 9 9 0 0118 0z"
              />
            </svg>
          </div>
        </div>
      </div>

      {/* --- TOOLBAR --- */}
      <div className="bg-white p-4 rounded-t-2xl shadow-sm border border-slate-100 flex flex-col md:flex-row gap-4 justify-between items-center shrink-0">
        <div className="flex flex-col md:flex-row gap-3 w-full md:w-auto">
          <div className="relative">
            <svg
              className="w-5 h-5 absolute left-3 top-1/2 -translate-y-1/2 text-slate-400"
              fill="none"
              viewBox="0 0 24 24"
              stroke="currentColor"
            >
              <path
                strokeLinecap="round"
                strokeLinejoin="round"
                strokeWidth={2}
                d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z"
              />
            </svg>
            <input
              type="text"
              placeholder="Cari Kapten / Komunitas / ID Grup..."
              value={searchQuery}
              onChange={(e) => setSearchQuery(e.target.value)}
              className="pl-10 pr-4 py-2 bg-slate-50 border border-slate-200 rounded-xl text-sm focus:outline-none focus:ring-2 focus:ring-[#1A73E8] w-full md:w-72"
            />
          </div>

          <select
            value={filterStatus}
            onChange={(e) => setFilterStatus(e.target.value)}
            className="px-4 py-2 bg-slate-50 border border-slate-200 rounded-xl text-sm font-medium focus:outline-none focus:ring-2 focus:ring-[#1A73E8]"
          >
            <option value="Semua">Semua Status</option>
            <option value="Lunas">Lunas</option>
            <option value="Menunggu Verifikasi">Menunggu Verifikasi</option>
            <option value="Pending">Pending (Belum Upload)</option>
          </select>

          <select
            value={itemsPerPage}
            onChange={(e) =>
              setItemsPerPage(
                e.target.value === "All" ? "All" : Number(e.target.value),
              )
            }
            className="px-4 py-2 bg-slate-50 border border-slate-200 rounded-xl text-sm font-medium focus:outline-none focus:ring-2 focus:ring-[#1A73E8]"
          >
            <option value={10}>10 Baris</option>
            <option value={50}>50 Baris</option>
            <option value={100}>100 Baris</option>
            <option value="All">Semua</option>
          </select>
        </div>
      </div>

      {/* --- TABLE --- */}
      <div className="bg-white border-x border-slate-100 flex-grow overflow-auto relative">
        <table className="w-full text-left border-collapse text-sm whitespace-nowrap">
          <thead className="bg-slate-50 text-slate-500 sticky top-0 z-10 shadow-sm">
            <tr>
              <th className="p-4 border-b border-slate-200 w-10">
                <input
                  type="checkbox"
                  checked={
                    selectedIds.length === paginatedData.length &&
                    paginatedData.length > 0
                  }
                  onChange={toggleSelectAllVisible}
                  className="rounded text-[#1A73E8] focus:ring-[#1A73E8] w-4 h-4"
                />
              </th>
              <th
                className="p-4 border-b border-slate-200 font-bold cursor-pointer hover:bg-slate-100"
                onClick={() => handleSort("createdAt")}
              >
                Waktu Daftar
              </th>
              <th
                className="p-4 border-b border-slate-200 font-bold cursor-pointer hover:bg-slate-100"
                onClick={() => handleSort("komunitas")}
              >
                Komunitas
              </th>
              <th
                className="p-4 border-b border-slate-200 font-bold cursor-pointer hover:bg-slate-100"
                onClick={() => handleSort("namaKapten")}
              >
                Kapten (PJ)
              </th>
              <th className="p-4 border-b border-slate-200 font-bold">
                Peserta
              </th>
              <th
                className="p-4 border-b border-slate-200 font-bold cursor-pointer hover:bg-slate-100"
                onClick={() => handleSort("totalBiaya")}
              >
                Tagihan
              </th>
              <th
                className="p-4 border-b border-slate-200 font-bold cursor-pointer hover:bg-slate-100"
                onClick={() => handleSort("statusPembayaran")}
              >
                Status
              </th>
              <th className="p-4 border-b border-slate-200 font-bold text-center">
                Aksi
              </th>
            </tr>
          </thead>
          <tbody className="divide-y divide-slate-100">
            {paginatedData.length === 0 ? (
              <tr>
                <td colSpan={8} className="p-8 text-center text-slate-400">
                  Tidak ada data pendaftaran komunitas yang sesuai.
                </td>
              </tr>
            ) : (
              paginatedData.map((g) => {
                let displayDate = "-";
                if (g.createdAt) {
                  displayDate = new Date(
                    g.createdAt.seconds
                      ? g.createdAt.seconds * 1000
                      : g.createdAt,
                  ).toLocaleString("id-ID", {
                    dateStyle: "medium",
                    timeStyle: "short",
                  });
                }

                return (
                  <tr
                    key={g.id}
                    className="hover:bg-slate-50/50 transition-colors"
                  >
                    <td className="p-4">
                      <input
                        type="checkbox"
                        checked={selectedIds.includes(g.id)}
                        onChange={() => toggleSelect(g.id)}
                        className="rounded text-[#1A73E8] focus:ring-[#1A73E8] w-4 h-4"
                      />
                    </td>
                    <td className="p-4 text-slate-600">
                      {displayDate}
                      <div className="text-[10px] font-mono text-slate-400 mt-1">
                        ID: {g.id}
                      </div>
                    </td>
                    <td className="p-4 font-bold text-slate-800">
                      {g.kapten?.komunitas || "-"}
                    </td>
                    <td className="p-4 text-slate-600">
                      <div className="font-medium">{g.kapten?.nama}</div>
                      <div className="text-xs text-slate-400">
                        {g.kapten?.wa}
                      </div>
                    </td>
                    <td className="p-4 font-medium text-slate-600">
                      {g.participants?.length || 0} Orang
                    </td>
                    <td className="p-4 font-bold text-slate-800">
                      Rp {g.totalBiaya?.toLocaleString("id-ID")}
                    </td>
                    <td className="p-4">
                      <span
                        className={`px-3 py-1 text-xs font-bold rounded-full ${g.statusPembayaran === "Lunas" ? "bg-emerald-100 text-emerald-700 border border-emerald-200" : g.statusPembayaran === "Menunggu Verifikasi" ? "bg-amber-100 text-amber-700 border border-amber-200" : "bg-slate-100 text-slate-600 border border-slate-200"}`}
                      >
                        {g.statusPembayaran || "Pending"}
                      </span>
                    </td>
                    <td className="p-4 text-center">
                      <button
                        onClick={() => setDetailGroup(g)}
                        className="px-4 py-1.5 bg-blue-50 text-[#1A73E8] hover:bg-blue-100 font-bold rounded-lg transition-colors text-xs"
                      >
                        Detail
                      </button>
                    </td>
                  </tr>
                );
              })
            )}
          </tbody>
        </table>
      </div>

      {/* --- PAGINATION --- */}
      <div className="bg-white p-4 rounded-b-2xl shadow-sm border border-slate-100 flex justify-between items-center shrink-0">
        <p className="text-sm text-slate-500">
          Menampilkan baris{" "}
          <span className="font-bold text-slate-800">
            {(currentPage - 1) *
              (itemsPerPage === "All" ? sortedData.length : itemsPerPage) +
              1}
          </span>{" "}
          -{" "}
          <span className="font-bold text-slate-800">
            {Math.min(
              currentPage *
                (itemsPerPage === "All" ? sortedData.length : itemsPerPage),
              sortedData.length,
            )}
          </span>{" "}
          dari{" "}
          <span className="font-bold text-slate-800">{sortedData.length}</span>{" "}
          data
        </p>
        <div className="flex gap-2">
          <button
            onClick={() => setCurrentPage((p) => Math.max(1, p - 1))}
            disabled={currentPage === 1}
            className="px-3 py-1.5 rounded-lg border border-slate-200 text-sm font-medium hover:bg-slate-50 disabled:opacity-50"
          >
            Prev
          </button>
          <button
            onClick={() => setCurrentPage((p) => Math.min(totalPages, p + 1))}
            disabled={currentPage === totalPages}
            className="px-3 py-1.5 rounded-lg border border-slate-200 text-sm font-medium hover:bg-slate-50 disabled:opacity-50"
          >
            Next
          </button>
        </div>
      </div>

      {/* --- 🔥 MODAL DETAIL PENDAFTAR GRUP 🔥 --- */}
      {detailGroup && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center bg-slate-900/60 backdrop-blur-sm p-4 animate-in fade-in duration-200">
          <div className="bg-white rounded-3xl w-full max-w-6xl max-h-[90vh] overflow-hidden shadow-2xl flex flex-col">
            <div className="p-6 border-b border-slate-100 flex justify-between items-center bg-slate-50 shrink-0">
              <div>
                <h2 className="text-xl font-black text-slate-800 leading-tight">
                  Tim {detailGroup.kapten?.komunitas}
                </h2>
                <p className="text-sm text-slate-500 mt-1">
                  ID Sistem: {detailGroup.id}
                </p>
              </div>
              <button
                onClick={() => setDetailGroup(null)}
                className="w-8 h-8 flex items-center justify-center rounded-full bg-slate-200 text-slate-600 hover:bg-slate-300"
              >
                <svg
                  className="w-4 h-4"
                  fill="none"
                  viewBox="0 0 24 24"
                  stroke="currentColor"
                >
                  <path
                    strokeLinecap="round"
                    strokeLinejoin="round"
                    strokeWidth={2}
                    d="M6 18L18 6M6 6l12 12"
                  />
                </svg>
              </button>
            </div>

            <div className="p-6 overflow-y-auto flex-grow grid grid-cols-1 lg:grid-cols-12 gap-6 bg-white">
              {/* === KOLOM KIRI (INFO KAPTEN & PEMBAYARAN) === */}
              <div className="lg:col-span-4 space-y-5">
                <div className="bg-amber-50 border border-amber-200 rounded-2xl p-4">
                  <p className="text-xs font-bold text-amber-600 uppercase tracking-wider mb-1">
                    KODE VERIFIKASI / ID GRUP
                  </p>
                  <p className="text-xl font-mono font-black text-slate-800 tracking-wider">
                    {detailGroup.id}
                  </p>
                  <p className="text-xs text-slate-500 mt-1">
                    *Gunakan kode ini sebagai pencocokan saat RPC.
                  </p>
                </div>

                <div className="bg-slate-50 border border-slate-100 rounded-2xl p-4">
                  <p className="text-xs font-bold text-slate-400 uppercase tracking-wider mb-2">
                    Kapten / PJ Komunitas
                  </p>
                  <p className="text-lg font-bold text-slate-800">
                    {detailGroup.kapten?.nama}
                  </p>
                  <p className="text-sm text-slate-600 mt-1 flex items-center gap-2">
                    <svg
                      className="w-4 h-4 text-slate-400"
                      fill="none"
                      viewBox="0 0 24 24"
                      stroke="currentColor"
                    >
                      <path
                        strokeLinecap="round"
                        strokeLinejoin="round"
                        strokeWidth={2}
                        d="M3 5a2 2 0 012-2h3.28a1 1 0 01.948.684l1.498 4.493a1 1 0 01-.502 1.21l-2.257 1.13a11.042 11.042 0 005.516 5.516l1.13-2.257a1 1 0 011.21-.502l4.493 1.498a1 1 0 01.684.949V19a2 2 0 01-2 2h-1C9.716 21 3 14.284 3 6V5z"
                      />
                    </svg>
                    {detailGroup.kapten?.wa}
                  </p>
                  <p className="text-sm text-slate-600 flex items-center gap-2 mt-1">
                    <svg
                      className="w-4 h-4 text-slate-400"
                      fill="none"
                      viewBox="0 0 24 24"
                      stroke="currentColor"
                    >
                      <path
                        strokeLinecap="round"
                        strokeLinejoin="round"
                        strokeWidth={2}
                        d="M3 8l7.89 5.26a2 2 0 002.22 0L21 8M5 19h14a2 2 0 002-2V7a2 2 0 00-2-2H5a2 2 0 00-2 2v10a2 2 0 002 2z"
                      />
                    </svg>
                    {detailGroup.kapten?.email}
                  </p>

                  {(detailGroup.ktpUrl || detailGroup.logoUrl) && (
                    <div className="mt-4 border-t border-slate-200 pt-4 flex gap-2">
                      {detailGroup.ktpUrl && (
                        <div
                          onClick={() =>
                            detailGroup.ktpUrl.startsWith("http")
                              ? window.open(detailGroup.ktpUrl, "_blank")
                              : setAlertModal({
                                  isOpen: true,
                                  type: "warning",
                                  title: "File Tidak Ditemukan",
                                  message:
                                    "Berkas KTP sudah diupload oleh peserta, namun URL file aslinya tidak ditemukan di database.",
                                })
                          }
                          className="cursor-pointer text-xs bg-white border border-slate-200 text-blue-600 font-bold px-3 py-1.5 rounded-lg hover:bg-blue-50 transition-colors flex items-center gap-1 flex-1 justify-center"
                        >
                          <svg
                            className="w-4 h-4"
                            fill="none"
                            viewBox="0 0 24 24"
                            stroke="currentColor"
                          >
                            <path
                              strokeLinecap="round"
                              strokeLinejoin="round"
                              strokeWidth={2}
                              d="M15 12a3 3 0 11-6 0 3 3 0 016 0z"
                            />
                            <path
                              strokeLinecap="round"
                              strokeLinejoin="round"
                              strokeWidth={2}
                              d="M2.458 12C3.732 7.943 7.523 5 12 5c4.478 0 8.268 2.943 9.542 7-1.274 4.057-5.064 7-9.542 7-4.477 0-8.268-2.943-9.542-7z"
                            />
                          </svg>{" "}
                          KTP
                        </div>
                      )}
                      {detailGroup.logoUrl && (
                        <div
                          onClick={() =>
                            detailGroup.logoUrl.startsWith("http")
                              ? window.open(detailGroup.logoUrl, "_blank")
                              : setAlertModal({
                                  isOpen: true,
                                  type: "warning",
                                  title: "File Tidak Ditemukan",
                                  message:
                                    "Berkas Logo sudah diupload oleh peserta, namun URL file aslinya tidak ditemukan di database.",
                                })
                          }
                          className="cursor-pointer text-xs bg-white border border-slate-200 text-purple-600 font-bold px-3 py-1.5 rounded-lg hover:bg-purple-50 transition-colors flex items-center gap-1 flex-1 justify-center"
                        >
                          <svg
                            className="w-4 h-4"
                            fill="none"
                            viewBox="0 0 24 24"
                            stroke="currentColor"
                          >
                            <path
                              strokeLinecap="round"
                              strokeLinejoin="round"
                              strokeWidth={2}
                              d="M4 16l4.586-4.586a2 2 0 012.828 0L16 16m-2-2l1.586-1.586a2 2 0 012.828 0L20 14m-6-6h.01M6 20h12a2 2 0 002-2V6a2 2 0 00-2-2H6a2 2 0 00-2 2v12a2 2 0 002 2z"
                            />
                          </svg>{" "}
                          Logo
                        </div>
                      )}
                    </div>
                  )}
                </div>

                <div className="bg-blue-50 border border-blue-100 rounded-2xl p-4 flex flex-col justify-center">
                  <p className="text-xs font-bold text-blue-400 uppercase tracking-wider mb-1">
                    Total Tagihan ({detailGroup.participants?.length || 0}{" "}
                    Peserta)
                  </p>
                  <p className="text-3xl font-black text-blue-700">
                    Rp {detailGroup.totalBiaya?.toLocaleString("id-ID")}
                  </p>
                </div>

                <div className="bg-slate-50 border border-slate-100 rounded-2xl p-4">
                  <p className="text-xs font-bold text-slate-400 uppercase tracking-wider mb-2">
                    TOTAL KEBUTUHAN JERSEY TIM
                  </p>
                  <div className="grid grid-cols-3 gap-2 text-center text-xs">
                    {Object.entries(
                      getJerseySummary(detailGroup.participants),
                    ).map(([size, qty]: any) => (
                      <div
                        key={size}
                        className="bg-white border border-slate-200 rounded-xl p-2 font-bold shadow-sm"
                      >
                        <div className="text-slate-400 text-[10px] mb-0.5">
                          {size}
                        </div>
                        <div className="text-base text-slate-800">
                          {qty} Pcs
                        </div>
                      </div>
                    ))}
                  </div>
                </div>

                <div className="bg-slate-50 border border-slate-100 rounded-2xl p-4 space-y-4">
                  <div>
                    <p className="text-[10px] font-bold text-slate-400 uppercase tracking-wider mb-1">
                      Status Pembayaran
                    </p>
                    <span
                      className={`px-2 py-1.5 rounded text-xs font-bold block text-center ${detailGroup.statusPembayaran === "Lunas" ? "bg-emerald-100 text-emerald-700" : "bg-amber-100 text-amber-700"}`}
                    >
                      {detailGroup.statusPembayaran || "Belum Bayar"}
                    </span>
                  </div>

                  <div>
                    <p className="text-[10px] font-bold text-slate-400 uppercase tracking-wider mb-1">
                      Status Logistik Racepack
                    </p>
                    <span
                      className={`px-2 py-1.5 rounded text-xs font-bold block text-center ${detailGroup.isRacepackTaken ? "bg-purple-100 text-purple-700 border border-purple-200" : "bg-slate-200 text-slate-700"}`}
                    >
                      {detailGroup.isRacepackTaken
                        ? "SUDAH DIAMBIL"
                        : "BELUM DIAMBIL"}
                    </span>
                  </div>

                  {detailGroup.isRacepackTaken && (
                    <div className="text-xs bg-white p-3 rounded-xl border border-slate-200 space-y-1.5 text-slate-600 shadow-sm mt-3">
                      <div>
                        <span className="font-medium text-slate-400 block mb-0.5">
                          Diserahkan Kepada:
                        </span>{" "}
                        <span className="font-bold text-slate-800">
                          {detailGroup.namaPengambilAtribut ||
                            detailGroup.kapten?.nama}
                        </span>
                      </div>
                      <div>
                        <span className="font-medium text-slate-400 block mb-0.5">
                          Metode Verifikasi:
                        </span>{" "}
                        <span className="font-bold text-[#1A73E8]">
                          {detailGroup.metodeVerifikasiRPC || "KTP"}
                        </span>
                      </div>
                      <div>
                        <span className="font-medium text-slate-400 block mb-0.5">
                          Waktu Pengambilan:
                        </span>{" "}
                        <span className="font-bold text-slate-700">
                          {new Date(
                            detailGroup.waktuAmbilRacepack,
                          ).toLocaleString("id-ID")}
                        </span>
                      </div>
                      <div className="pt-1 mt-1 border-t border-slate-100">
                        <span className="font-medium text-slate-400 block mb-0.5">
                          Admin Penanggung Jawab:
                        </span>{" "}
                        <span className="font-bold text-slate-700">
                          {detailGroup.adminHandler || "-"}
                        </span>
                      </div>
                    </div>
                  )}
                </div>

                {detailGroup.buktiBayarUrl && (
                  <div className="bg-white border border-slate-100 rounded-2xl p-4">
                    <h3 className="text-xs font-bold text-slate-400 uppercase tracking-wider mb-3">
                      Bukti Transfer
                    </h3>
                    <div
                      className="w-full h-48 rounded-xl border-2 border-dashed border-slate-300 overflow-hidden cursor-zoom-in group relative"
                      onClick={() =>
                        setSelectedImage(detailGroup.buktiBayarUrl)
                      }
                    >
                      <img
                        src={detailGroup.buktiBayarUrl}
                        alt="Bukti Bayar"
                        className="w-full h-full object-cover group-hover:scale-105 transition-transform"
                      />
                      <div className="absolute inset-0 bg-black/40 opacity-0 group-hover:opacity-100 flex items-center justify-center transition-opacity">
                        <svg
                          className="w-8 h-8 text-white"
                          fill="none"
                          viewBox="0 0 24 24"
                          stroke="currentColor"
                        >
                          <path
                            strokeLinecap="round"
                            strokeLinejoin="round"
                            strokeWidth={2}
                            d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0zM10 7v3m0 0v3m0-3h3m-3 0H7"
                          />
                        </svg>
                      </div>
                    </div>
                  </div>
                )}
              </div>

              {/* === KOLOM KANAN (TABEL DAFTAR PESERTA) === */}
              <div className="lg:col-span-8 flex flex-col">
                <div className="flex justify-between items-end mb-3 border-b border-slate-100 pb-2">
                  <h3 className="text-sm font-bold text-slate-800">
                    Daftar Anggota / Peserta
                  </h3>
                  <span className="text-xs font-medium text-slate-500 bg-slate-100 px-2 py-1 rounded">
                    Total: {detailGroup.participants?.length || 0} Orang
                  </span>
                </div>

                <div className="bg-white border border-slate-200 rounded-xl overflow-x-auto flex-grow h-[400px]">
                  <table className="w-full text-left text-sm whitespace-nowrap">
                    <thead className="bg-slate-50 text-slate-500 border-b border-slate-200 sticky top-0 z-10">
                      <tr>
                        <th className="p-3 font-bold">No</th>
                        <th className="p-3 font-bold text-[#1A73E8]">
                          Nomor BIB
                        </th>
                        <th className="p-3 font-bold">Nama Lengkap & NIK</th>
                        <th className="p-3 font-bold">Kategori</th>
                        <th className="p-3 font-bold">Gender</th>
                        <th className="p-3 font-bold">Darah</th>
                        <th className="p-3 font-bold">Size Jersey</th>
                        <th className="p-3 font-bold">Riwayat Penyakit</th>
                        <th className="p-3 font-bold">Kontak Darurat</th>
                      </tr>
                    </thead>
                    <tbody className="divide-y divide-slate-100">
                      {detailGroup.participants?.length > 0 ? (
                        detailGroup.participants.map((p: any, idx: number) => (
                          <tr key={idx} className="hover:bg-slate-50">
                            <td className="p-3 text-slate-500 text-center">
                              {idx + 1}
                            </td>
                            <td className="p-3 font-mono font-black text-[#1A73E8] bg-blue-50/30">
                              {p.nomorBIB || p.bib || "-"}
                            </td>
                            <td className="p-3">
                              <span className="font-bold text-slate-800 block">
                                {p.namaLengkap || "-"}
                              </span>
                              <span className="text-[10px] text-slate-400 font-mono">
                                {p.nik || "-"}
                              </span>
                            </td>
                            <td className="p-3 text-slate-600">
