        type === "checkbox"
          ? checked
          : type === "number"
            ? Number(value)
            : value,
    });
  };
  const handleCategoryToggle = (category: string) => {
    setVrSettings((prev: any) => {
      const currentCats = prev.allowedCategories || ["Umum"];
      let newCats = currentCats.includes(category)
        ? currentCats.filter((c: string) => c !== category)
        : [...currentCats, category];
      if (newCats.length === 0) newCats = ["Umum"];
      return { ...prev, allowedCategories: newCats };
    });
  };
  const selectPaymentMethod = (method: string) =>
    setVrSettings({ ...vrSettings, metodePembayaran: method });
  const handlePackageChange = (
    type: "virtual" | "offline",
    id: string,
    field: string,
    value: any,
  ) => {
    const target = type === "virtual" ? "virtualPackages" : "offlinePackages";
    setVrSettings({
      ...vrSettings,
      [target]: vrSettings[target].map((pkg: any) =>
        pkg.id === id ? { ...pkg, [field]: value } : pkg,
      ),
    });
  };
  const addPackage = (type: "virtual" | "offline") => {
    const target = type === "virtual" ? "virtualPackages" : "offlinePackages";
    const newPkg =
      type === "virtual"
        ? {
            id: Date.now().toString(),
            nama: "",
            jarak: "",
            harga: 0,
            benefit: "",
          }
        : {
            id: Date.now().toString(),
            nama: "",
            jarak: "",
            kuota: 0,
            harga: 0,
            benefit: "",
            urlMap: "",
            polyline: "", // 🔥 Reset saat bikin paket baru
            waypoints: [], // 🔥 Reset saat bikin paket baru
          };
    setVrSettings({ ...vrSettings, [target]: [...vrSettings[target], newPkg] });
  };
  const removePackage = (type: "virtual" | "offline", id: string) => {
    const target = type === "virtual" ? "virtualPackages" : "offlinePackages";
    setVrSettings({
      ...vrSettings,
      [target]: vrSettings[target].filter((pkg: any) => pkg.id !== id),
    });
  };
  const saveSettings = async (e: React.FormEvent) => {
    e.preventDefault();
    setIsSavingSettings(true);
    try {
      await callVrAdminApi("save-settings", { settings: vrSettings });
      setPopup({ type: "success", text: "Pengaturan berhasil disimpan." });
    } catch (error: any) {
      console.error("[pengaturan] save error:", error);
      setPopup({
        type: "error",
        text: `Gagal menyimpan: ${error?.message || "terjadi kesalahan"}`,
      });
    } finally {
      setIsSavingSettings(false);
      setTimeout(() => setPopup(null), 3000);
    }
  };

  // PROMO HANDLERS
  const handleAddPromo = async () => {
    if (
      !newPromo.kode.trim() ||
      newPromo.nilaiDiskon <= 0 ||
      !newPromo.tanggalKedaluwarsa
    )
      return setPopup({ type: "warning", text: "Isi data dengan lengkap!" });
    setIsSavingPromo(true);
    try {
      const promoData = {
        ...newPromo,
        kode: newPromo.kode.toUpperCase().trim().replace(/\s/g, ""),
      };
      const { id } = await callVrAdminApi("add-promo", { promo: promoData });
      setPromoCodes([
        ...promoCodes,
        {
          id,
          ...promoData,
          kuotaTerpakai: 0,
          createdAt: new Date().toISOString(),
        },
      ]);
      setNewPromo({ ...newPromo, kode: "", nilaiDiskon: 0 });
      setPopup({
        type: "success",
        text: `Promo ${promoData.kode} ditambahkan.`,
      });
    } catch (error: any) {
      console.error("[pengaturan] add promo error:", error);
      setPopup({
        type: "error",
        text: `Gagal menambah promo: ${error?.message || "terjadi kesalahan"}`,
      });
    } finally {
      setIsSavingPromo(false);
      setTimeout(() => setPopup(null), 3000);
    }
  };
  const handleTogglePromoStatus = async (id: string, status: boolean) => {
    try {
      await callVrAdminApi("toggle-promo", { id, isActive: !status });
      setPromoCodes(
        promoCodes.map((p) => (p.id === id ? { ...p, isActive: !status } : p)),
      );
    } catch (error: any) {
      console.error("[pengaturan] toggle promo error:", error);
      setPopup({
        type: "error",
        text: `Gagal ubah status promo: ${error?.message || "terjadi kesalahan"}`,
      });
      setTimeout(() => setPopup(null), 3000);
    }
  };
  const handleDeletePromo = async (id: string, kode: string) => {
    if (!confirm(`Hapus promo ${kode}?`)) return;
    try {
      await callVrAdminApi("delete-promo", { id });
      setPromoCodes(promoCodes.filter((p) => p.id !== id));
    } catch (error: any) {
      console.error("[pengaturan] delete promo error:", error);
      setPopup({
        type: "error",
        text: `Gagal hapus promo: ${error?.message || "terjadi kesalahan"}`,
      });
      setTimeout(() => setPopup(null), 3000);
    }
  };

  if (isLoading)
    return (
      <div className="h-screen flex items-center justify-center text-blue-500 font-bold animate-pulse">
        MEMUAT SISTEM...
      </div>
    );

  return (
    <div className="animate-in fade-in max-w-5xl mx-auto pb-24 relative p-4 sm:p-8 font-sans">
      {popup && (
        <div className="fixed top-6 right-6 z-[100] bg-white p-4 rounded-xl shadow-lg border border-slate-200">
          <strong>{popup.type}</strong>: {popup.text}
        </div>
      )}

      <div className="flex flex-col md:flex-row justify-between md:items-end gap-4 mb-8">
        <div>
          <h1 className="text-[28px] font-bold text-slate-800 tracking-tight">
            Pengaturan Sistem
          </h1>
          <p className="text-sm text-slate-500 mt-1">
            Kelola konfigurasi event, jadwal, mode offline, dan gerbang
            pembayaran.
          </p>
        </div>
        <button
          onClick={saveSettings}
          disabled={isSavingSettings}
          className="bg-blue-600 hover:bg-blue-700 text-white font-bold px-8 py-2.5 rounded-lg disabled:opacity-50 shadow-sm transition-colors"
        >
          {isSavingSettings ? "Menyimpan..." : "Simpan Pengaturan Utama"}
        </button>
      </div>

      <div className="flex overflow-x-auto gap-1 mb-8 border-b border-slate-200">
        {/* 🔥 TAMBAH TAB "RUTE" DISINI 🔥 */}
        {["virtual", "offline", "rute", "charity", "pembayaran"].map((tab) => (
          <button
            key={tab}
            onClick={() => setActiveTab(tab)}
            className={`px-6 py-3 text-sm font-bold uppercase ${activeTab === tab ? "border-b-2 border-blue-600 text-blue-600" : "text-slate-500"}`}
          >
            {tab}
          </button>
        ))}
      </div>

      <form onSubmit={saveSettings}>
        {activeTab === "virtual" && (
          <TabVirtual
            vrSettings={vrSettings}
            handleSettingChange={handleSettingChange}
            handlePackageChange={handlePackageChange}
            addPackage={addPackage}
            removePackage={removePackage}
          />
        )}
        {activeTab === "offline" && (
          <TabOffline
            vrSettings={vrSettings}
            handleSettingChange={handleSettingChange}
            handleCategoryToggle={handleCategoryToggle}
            handlePackageChange={handlePackageChange}
            addPackage={addPackage}
            removePackage={removePackage}
          />
        )}

        {/* 🔥 RENDER TAB BARU KITA DISINI 🔥 */}
        {activeTab === "rute" && (
          <TabRoutes
            vrSettings={vrSettings}
            handlePackageChange={handlePackageChange}
          />
        )}

        {activeTab === "charity" && (
          <TabCharity
            vrSettings={vrSettings}
            handleSettingChange={handleSettingChange}
          />
        )}
        {activeTab === "pembayaran" && (
          <TabPembayaran
            vrSettings={vrSettings}
            selectPaymentMethod={selectPaymentMethod}
            handleSettingChange={handleSettingChange}
            promoCodes={promoCodes}
            newPromo={newPromo}
            setNewPromo={setNewPromo}
            handleAddPromo={handleAddPromo}
            handleTogglePromoStatus={handleTogglePromoStatus}
            handleDeletePromo={handleDeletePromo}
            isSavingPromo={isSavingPromo}
          />
        )}
      </form>


    </div>
  );
}

import React, { useRef } from "react";
import { toast } from "@/lib/toast";

// 🔥 MESIN RAHASIA: ENCODER KOORDINAT KE POLYLINE
const encodePolyline = (coordinates: [number, number][]) => {
  let result = "";
  let prevLat = 0;
  let prevLng = 0;

  for (let i = 0; i < coordinates.length; i++) {
    const lat = Math.round(coordinates[i][0] * 1e5);
    const lng = Math.round(coordinates[i][1] * 1e5);

    const dLat = lat - prevLat;
    const dLng = lng - prevLng;

    prevLat = lat;
    prevLng = lng;

    const encodeNumber = (num: number) => {
      let sgnNum = num << 1;
      if (num < 0) sgnNum = ~sgnNum;
      let encoded = "";
      while (sgnNum >= 0x20) {
        encoded += String.fromCharCode((0x20 | (sgnNum & 0x1f)) + 63);
        sgnNum >>= 5;
      }
      encoded += String.fromCharCode(sgnNum + 63);
      return encoded;
    };

    result += encodeNumber(dLat) + encodeNumber(dLng);
  }
  return result;
};

export default function TabRoutes({ vrSettings, handlePackageChange }: any) {
  // 🔥 FUNGSI SAKTI: BACA FILE GPX LALU JADIKAN POLYLINE
  const handleGpxUpload = (
    e: React.ChangeEvent<HTMLInputElement>,
    pkgId: string,
  ) => {
    const file = e.target.files?.[0];
    if (!file) return;

    const reader = new FileReader();
    reader.onload = (event) => {
      try {
        const text = event.target?.result as string;
        const parser = new DOMParser();
        const xmlDoc = parser.parseFromString(text, "text/xml");

        // Cari tag <trkpt> (Track Point) di file GPX
        const trkpts = xmlDoc.getElementsByTagName("trkpt");
        const coords: [number, number][] = [];

        for (let i = 0; i < trkpts.length; i++) {
          const lat = parseFloat(trkpts[i].getAttribute("lat") || "0");
          const lon = parseFloat(trkpts[i].getAttribute("lon") || "0");
          coords.push([lat, lon]);
        }

        if (coords.length > 0) {
          const encodedStr = encodePolyline(coords);
          // Langsung tembak ke inputan polyline
          handlePackageChange("offline", pkgId, "polyline", encodedStr);
          toast.success(`Berhasil! ${coords.length} titik koordinat diekstrak dari GPX.`);
        } else {
          toast.error("Gagal: Tidak ada data rute/track point dalam file GPX ini.");
        }
      } catch (error) {
        console.error(error);
        toast.error("File GPX rusak atau format tidak sesuai.");
      }
    };
    reader.readAsText(file);
    // Reset input file biar bisa upload file yang sama lagi kalau error
    e.target.value = "";
  };

  const addWaypoint = (pkgId: string, currentWaypoints: any[] = []) => {
    const newWp = {
      id: Date.now().toString(),
      type: "water_station",
      label: "",
      lat: "",
      lng: "",
    };
    handlePackageChange("offline", pkgId, "waypoints", [
      ...currentWaypoints,
      newWp,
    ]);
  };

  const updateWaypoint = (
    pkgId: string,
    currentWaypoints: any[],
    wpId: string,
    field: string,
    value: string,
  ) => {
    const updated = currentWaypoints.map((wp) =>
      wp.id === wpId ? { ...wp, [field]: value } : wp,
    );
    handlePackageChange("offline", pkgId, "waypoints", updated);
  };

  const removeWaypoint = (
    pkgId: string,
    currentWaypoints: any[],
    wpId: string,
  ) => {
    const updated = currentWaypoints.filter((wp) => wp.id !== wpId);
    handlePackageChange("offline", pkgId, "waypoints", updated);
  };

  const WaypointIcons: Record<string, string> = {
    start: "🏁",
    finish: "🏁",
    water_station: "💧",
    medic: "🚑",
    cheering: "📣",
    camera: "📸",
    checkpoint: "📍",
  };

  return (
    <div className="grid grid-cols-1 lg:grid-cols-12 gap-8 border-slate-200 animate-in fade-in slide-in-from-bottom-4 duration-300">
      <div className="lg:col-span-4">
        <h3 className="text-sm font-bold text-slate-800 flex items-center gap-2">
          <svg
            className="w-5 h-5 text-indigo-500"
            fill="none"
            viewBox="0 0 24 24"
            stroke="currentColor"
          >
            <path
              strokeLinecap="round"
              strokeLinejoin="round"
              strokeWidth={2}
              d="M9 20l-5.447-2.724A1 1 0 013 16.382V5.618a1 1 0 011.447-.894L9 7m0 13l6-3m-6 3V7m6 10l4.553 2.276A1 1 0 0021 18.382V7.618a1 1 0 00-.553-.894L15 4m0 13V4m0 0L9 7"
            />
          </svg>
          Custom Maps & Rute
        </h3>
        <p className="text-xs text-slate-500 mt-2 leading-relaxed">
          Atur jalur lari (Polyline GPS) dan titik lokasi penting (Water
          Station, Medis) untuk setiap kategori jarak secara interaktif.
        </p>
      </div>

      <div className="lg:col-span-8 space-y-6">
        {!vrSettings.offlinePackages ||
        vrSettings.offlinePackages.length === 0 ? (
          <div className="bg-white p-10 rounded-xl border border-slate-200 text-center shadow-sm">
            <div className="text-4xl mb-3">🚷</div>
            <h3 className="font-bold text-slate-700 text-sm">
              Belum Ada Kategori Tiket
            </h3>
            <p className="text-xs text-slate-500 mt-1">
              Silakan buat opsi paket offline di tab "Setup Offline Run"
              terlebih dahulu.
            </p>
          </div>
        ) : (
          vrSettings.offlinePackages.map((pkg: any) => (
            <div
              key={pkg.id}
              className="bg-white rounded-xl border border-slate-200 shadow-sm overflow-hidden transition-all hover:shadow-md"
            >
              <div className="bg-slate-50 px-5 py-4 border-b border-slate-200 flex items-center justify-between">
                <div>
                  <span className="text-[10px] font-black uppercase tracking-widest text-indigo-600 bg-indigo-100 px-2.5 py-1 rounded-md mb-1.5 inline-block">
                    Kategori {pkg.jarak}
                  </span>
                  <h4 className="font-bold text-slate-800 text-sm">
                    {pkg.nama || "Tanpa Nama"}
                  </h4>
                </div>
              </div>

              <div className="p-5 space-y-6">
                {/* 🔥 UPLOAD GPX & POLYLINE 🔥 */}
                <div>
                  <div className="flex items-center justify-between mb-2">
                    <label className="block text-[11px] font-bold text-slate-600 uppercase tracking-wide">
                      Sandi Rute (Polyline)
                    </label>

                    {/* TOMBOL AUTO CONVERT GPX */}
                    <label className="text-[10px] font-bold bg-indigo-600 hover:bg-indigo-700 text-white px-3 py-1.5 rounded-lg cursor-pointer transition-colors shadow-sm flex items-center gap-1.5">
                      <svg
                        className="w-3 h-3"
                        fill="none"
                        viewBox="0 0 24 24"
                        stroke="currentColor"
                      >
                        <path
                          strokeLinecap="round"
                          strokeLinejoin="round"
                          strokeWidth={2}
                          d="M4 16v1a3 3 0 003 3h10a3 3 0 003-3v-1m-4-8l-4-4m0 0L8 8m4-4v12"
                        />
                      </svg>
                      Auto-Generate dari File GPX
                      <input
                        type="file"
                        accept=".gpx"
                        className="hidden"
                        onChange={(e) => handleGpxUpload(e, pkg.id)}
                      />
                    </label>
                  </div>
                  <textarea
                    rows={3}
                    value={pkg.polyline || ""}
                    onChange={(e) =>
                      handlePackageChange(
                        "offline",
                        pkg.id,
                        "polyline",
                        e.target.value,
                      )
                    }
                    placeholder="Contoh: _p~iF~ps|U_ulLnnqC_mqNvxq`@"
                    className="w-full px-3 py-2.5 bg-slate-50 border border-slate-300 rounded-lg text-xs font-mono outline-none focus:border-indigo-500 focus:ring-1 focus:ring-indigo-500 transition-all resize-none text-slate-600"
                  ></textarea>
                </div>

                {/* 🔥 DAFTAR TITIK LOKASI (WAYPOINTS) 🔥 */}
                <div className="pt-5 border-t border-slate-100">
