                    >
                      <span>+</span> Tambah Titik
                    </button>
                  </div>

                  {!pkg.waypoints || pkg.waypoints.length === 0 ? (
                    <div className="text-center py-6 border border-dashed border-slate-200 rounded-xl bg-slate-50">
                      <p className="text-xs text-slate-400 font-medium">
