export default function RaceManagementPage() {
  const [activeTab, setActiveTab] = useState("timing");
  const [currentTime, setCurrentTime] = useState(new Date());

  // State Data & Settings
  const [settings, setSettings] = useState<any>({});
  const [offlineParticipants, setOfflineParticipants] = useState<any[]>([]);
  const [vrParticipants, setVrParticipants] = useState<any[]>([]);
  const [finishers, setFinishers] = useState<any[]>([]);
  const [winners, setWinners] = useState<any[]>([]);
  const [prizeList, setPrizeList] = useState<any[]>([]);

  // State Jarak Dinamis
  const [distances, setDistances] = useState<string[]>([]);
  const [cotInputs, setCotInputs] = useState<Record<string, string>>({});

  // State Peserta Manual (Untuk Doorprize)
  const [manualParticipants, setManualParticipants] = useState<any[]>([]);
  const [manualInput, setManualInput] = useState({
    nama: "",
    bib: "",
    kategori: "Umum",
  });

  // State Form & UI
  const [bibInput, setBibInput] = useState("");
  const [selectedPrizeId, setSelectedPrizeId] = useState("");
  const [filterDoorprize, setFilterDoorprize] = useState("all");
  const [spinDuration, setSpinDuration] = useState<number>(5);
  const [manualPrize, setManualPrize] = useState({
    namaHadiah: "",
    kategori: "Umum",
    jumlah: 1,
  });
  const [isSpinning, setIsSpinning] = useState(false);

  const [message, setMessage] = useState({ type: "", text: "" });
  const [isProcessing, setIsProcessing] = useState(false);
  const bibInputRef = useRef<HTMLInputElement>(null);

  // State Identitas Event
  const [identityForm, setIdentityForm] = useState({
    eventName: "IKA UII DIY RUN 2026",
    eventSubtext: "Official Timing System",
    eventLogo: "/logo-dpp-ika.png",
  });

  // 🔥 CUSTOM CONFIRMATION MODAL STATE 🔥
  const [confirmDialog, setConfirmDialog] = useState({
    isOpen: false,
    title: "",
    message: "",
    type: "info",
    onConfirm: () => {},
    confirmText: "Ya, Lanjutkan",
  });

  // Live Clock Ticker
  useEffect(() => {
    const timer = setInterval(() => setCurrentTime(new Date()), 1000);
    return () => clearInterval(timer);
  }, []);

  const formatJam = currentTime.toLocaleTimeString("id-ID", {
    hour: "2-digit",
    minute: "2-digit",
    second: "2-digit",
  });

  const showMsg = (type: "success" | "error", text: string) => {
    setMessage({ type, text });
    setTimeout(() => setMessage({ type: "", text: "" }), 3500);
  };

  // 🔥 PERBAIKAN 1: Query Firestore yang lebih robust untuk mendeteksi finisher
  useEffect(() => {
    // Ubah dari != null menjadi > 0 agar index firestore lebih akurat menarik data baru
    const q = query(
      collection(db, "offline_participants"),
      where("waktuFinish", ">", 0),
    );
    const unsub = onSnapshot(q, (snapshot) => {
      const liveFinishers = snapshot.docs.map((doc) => ({
        id: doc.id,
        ...doc.data(),
      }));
      liveFinishers.sort((a: any, b: any) => b.waktuFinish - a.waktuFinish);
      setFinishers(liveFinishers);
    });
    return () => unsub();
  }, []);

  // --- 🔥 SINKRONISASI SETTING & JARAK DINAMIS 🔥 ---
  useEffect(() => {
    const unsub = onSnapshot(doc(db, "settings", "virtual_run"), (docSnap) => {
      if (docSnap.exists()) {
        const data = docSnap.data();
        setSettings(data);
        if (data.distances) {
          setDistances(data.distances);
        }
        
        // Sync local identity form if not actively typing
        setIdentityForm((prev) => ({
          ...prev,
          eventName: data.eventName || "IKA UII DIY RUN 2026",
          eventSubtext: data.eventSubtext || "Official Timing System",
          eventLogo: data.eventLogo || "/logo-dpp-ika.png",
        }));

        let availDistances: string[] = [];
        if (data.offlinePackages && data.offlinePackages.length > 0) {
          availDistances = Array.from(
            new Set(data.offlinePackages.map((p: any) => p.jarak)),
          ) as string[];
        } else if (data.virtualPackages && data.virtualPackages.length > 0) {
          availDistances = Array.from(
            new Set(data.virtualPackages.map((p: any) => p.jarak)),
          ) as string[];
        }
        setDistances(availDistances);

        setCotInputs((prev) => {
          const newCot = { ...prev };
          availDistances.forEach((dist) => {
            const safeDistKey = dist.replace(/\./g, "_");
            if (!newCot[dist])
              newCot[dist] = data[`cot${safeDistKey}`] || "120";
          });
          return newCot;
        });
      }
    });
    return () => unsub();
  }, []);

  const syncPeserta = async () => {
    setIsProcessing(true);
    try {
      const snapOffline = await getDocs(collection(db, "offline_participants"));
      const allOffline = snapOffline.docs.map((d) => ({
        id: d.id,
        source: "offline",
        ...d.data(),
      }));
      const lunasOffline = allOffline.filter((p: any) => {
        const status = (
          p.statusPembayaran ||
          p.statusBayar ||
          p.status ||
          ""
        ).toLowerCase();
        return (
          status === "lunas" || status === "sukses" || status === "success"
        );
      });
      setOfflineParticipants(lunasOffline);

      const snapVR = await getDocs(collection(db, "vr_participants"));
      const allVR = snapVR.docs.map((d) => ({
        id: d.id,
        source: "vr",
        ...d.data(),
      }));
      const lunasVR = allVR.filter((p: any) => {
        const status = (
          p.statusPembayaran ||
          p.statusBayar ||
          p.status ||
          ""
        ).toLowerCase();
        return (
          status === "lunas" || status === "sukses" || status === "success"
        );
      });
      setVrParticipants(lunasVR);
      showMsg("success", "Sinkronisasi data kolam berhasil.");
    } catch (error) {
      showMsg("error", "Gagal menarik data dari database.");
    } finally {
      setIsProcessing(false);
    }
  };

  useEffect(() => {
    syncPeserta();
  }, []);

  useEffect(() => {
    const allWon = [
      ...offlineParticipants,
      ...vrParticipants,
      ...manualParticipants,
    ]
      .filter((p) => p.doorprizeWon)
      .sort((a, b) => b.waktuMenang - a.waktuMenang);
    setWinners(allWon);
  }, [offlineParticipants, vrParticipants, manualParticipants]);

  const candidates = useMemo(() => {
    const allCandidates = [
      ...offlineParticipants,
      ...vrParticipants,
      ...manualParticipants,
    ].filter((p) => !p.doorprizeWon);
    switch (filterDoorprize) {
      case "vr":
        return allCandidates.filter((p) => p.source === "vr");
      case "offline":
        return allCandidates.filter(
          (p) => p.source === "offline" || p.source === "manual",
        );
      case "finish":
        return allCandidates.filter(
          (p) =>
            (p.source === "offline" && p.waktuFinish) || p.source === "manual",
        );
      case "alumni":
        return allCandidates.filter(
          (p) =>
            (
              p.tipePeserta ||
              p.kategoriPeserta ||
              p.kategori ||
              ""
            ).toLowerCase() === "alumni",
        );
      case "umum":
        return allCandidates.filter(
          (p) =>
            (
              p.tipePeserta ||
              p.kategoriPeserta ||
              p.kategori ||
              ""
            ).toLowerCase() !== "alumni",
        );
      default:
        return allCandidates;
    }
  }, [
    filterDoorprize,
    offlineParticipants,
    vrParticipants,
    manualParticipants,
  ]);

  useEffect(() => {
    const unsub = onSnapshot(collection(db, "doorprize_items"), (snapshot) => {
      const data = snapshot.docs.map((d) => ({ id: d.id, ...d.data() }));
      data.sort((a: any, b: any) => a.createdAt - b.createdAt);
      setPrizeList(data);
    });
    return () => unsub();
  }, []);

  const downloadPrizeTemplate = () => {
    const ws = XLSX.utils.json_to_sheet([
      { Nama_Hadiah: "Sepeda Listrik", Kategori: "Hadiah Utama", Jumlah: 2 },
    ]);
    const wb = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(wb, ws, "Hadiah");
    XLSX.writeFile(wb, "Template_Hadiah_Doorprize.xlsx");
  };

  const handleImportPrizes = async (e: any) => {
    const file = e.target.files[0];
    if (!file) return;
    setIsProcessing(true);
    const reader = new FileReader();
    reader.onload = async (evt: any) => {
      try {
        const bstr = evt.target.result;
        const wb = XLSX.read(bstr, { type: "binary" });
        const data = XLSX.utils.sheet_to_json(wb.Sheets[wb.SheetNames[0]]);
        let count = 0;
        for (const row of data as any[]) {
          if (row.Nama_Hadiah && row.Jumlah) {
            await addDoc(collection(db, "doorprize_items"), {
              namaHadiah: row.Nama_Hadiah,
              kategori: row.Kategori || "Umum",
              jumlah: Number(row.Jumlah),
              terundi: 0,
              createdAt: Date.now(),
            });
            count++;
          }
        }
        showMsg("success", `${count} Hadiah diimport.`);
      } catch (err) {
        showMsg("error", "Gagal import Excel.");
      } finally {
        setIsProcessing(false);
        e.target.value = null;
      }
    };
    reader.readAsBinaryString(file);
  };

  const handleAddManualPrize = async () => {
    if (!manualPrize.namaHadiah || manualPrize.jumlah < 1) {
      showMsg("error", "Nama hadiah/jumlah tidak valid.");
      return;
    }
    setIsProcessing(true);
    try {
      await addDoc(collection(db, "doorprize_items"), {
        namaHadiah: manualPrize.namaHadiah,
        kategori: manualPrize.kategori,
        jumlah: Number(manualPrize.jumlah),
        terundi: 0,
        createdAt: Date.now(),
      });
      showMsg("success", "Hadiah manual ditambahkan.");
      setManualPrize({ namaHadiah: "", kategori: "Umum", jumlah: 1 });
    } catch (e) {
      showMsg("error", "Gagal menambahkan hadiah.");
    }
    setIsProcessing(false);
  };

  const handleClearPrizes = () => {
    setConfirmDialog({
      isOpen: true,
      title: "Hapus Semua Hadiah?",
      message:
        "Tindakan ini akan mengosongkan seluruh database hadiah doorprize. Lanjutkan?",
      type: "danger",
      confirmText: "Ya, Kosongkan",
      onConfirm: async () => {
        setConfirmDialog({ ...confirmDialog, isOpen: false });
        setIsProcessing(true);
        try {
          await Promise.all(
            prizeList.map((p) => deleteDoc(doc(db, "doorprize_items", p.id))),
          );
          setSelectedPrizeId("");
          showMsg("success", "Database hadiah dikosongkan.");
        } catch (e) {
          showMsg("error", "Gagal menghapus hadiah.");
        }
        setIsProcessing(false);
      },
    });
  };

  const handleAddManualParticipant = () => {
    if (!manualInput.nama) {
      showMsg("error", "Nama wajib diisi!");
      return;
    }
    const newParticipant = {
      id: `manual_${Date.now()}`,
      source: "manual",
      namaLengkap: manualInput.nama,
      nomorBIB: manualInput.bib || "TAMU",
      kategoriPeserta: manualInput.kategori,
      doorprizeWon: null,
    };
    setManualParticipants([...manualParticipants, newParticipant]);
    setManualInput({ nama: "", bib: "", kategori: "Umum" });
    showMsg("success", `${manualInput.nama} masuk ke Kolam Undian!`);
  };

  const handleStartRace = (dist: string, withCountdown: boolean = false) => {
    const safeDistKey = dist.replace(/\./g, "_");
    setConfirmDialog({
      isOpen: true,
      title: `Start Race ${dist}?`,
      message: withCountdown 
        ? `Kategori ${dist} akan dimulai dalam 10 DETIK (Countdown di layar publik). Lanjutkan?` 
        : `Timer untuk kategori jarak ${dist} akan mulai secara instan. Lanjutkan?`,
      type: "info",
      confirmText: "Ya, Start!",
      onConfirm: async () => {
        setConfirmDialog({ ...confirmDialog, isOpen: false });
        try {
          await updateDoc(doc(db, "settings", "virtual_run"), {
            [`gunTime${safeDistKey}`]: withCountdown ? Date.now() + 10000 : Date.now(),
          });
          showMsg("success", `RACE ${dist} DIMULAI!`);
        } catch (error) {
          showMsg("error", "Gagal memulai race.");
        }
      },
    });
  };

  const handleResetGunTime = (dist: string) => {
    const safeDistKey = dist.replace(/\./g, "_");
    setConfirmDialog({
      isOpen: true,
      title: `Reset Timer ${dist}?`,
      message: `Ini akan menghentikan dan mereset waktu berjalan untuk kategori ${dist}. Lanjutkan?`,
      type: "danger",
      confirmText: "Ya, Reset",
      onConfirm: async () => {
        setConfirmDialog({ ...confirmDialog, isOpen: false });
        try {
          await updateDoc(doc(db, "settings", "virtual_run"), {
            [`gunTime${safeDistKey}`]: null,
          });
          showMsg("success", `Timer ${dist} direset.`);
        } catch (error) {
          showMsg("error", "Gagal mereset timer.");
        }
      },
    });
  };

  const handleUpdateCOT = async (dist: string) => {
    const safeDistKey = dist.replace(/\./g, "_");
    try {
      await updateDoc(doc(db, "settings", "virtual_run"), {
        [`cot${safeDistKey}`]: Number(cotInputs[dist]),
      });
      showMsg("success", `COT ${dist} disimpan.`);
    } catch (error) {}
  };

  const handleSaveIdentity = async (e: React.FormEvent) => {
    e.preventDefault();
    setIsProcessing(true);
    try {
      await updateDoc(doc(db, "settings", "virtual_run"), {
        eventName: identityForm.eventName,
        eventSubtext: identityForm.eventSubtext,
        eventLogo: identityForm.eventLogo,
      });
      showMsg("success", "Identitas Event Berhasil Disimpan!");
    } catch (error) {
      showMsg("error", "Gagal menyimpan identitas event.");
    }
    setIsProcessing(false);
  };

  const handleSubmitFinish = async (e: React.FormEvent) => {
    e.preventDefault();
    const cleanBib = bibInput.trim().toUpperCase();
    if (!cleanBib) return;
    setIsProcessing(true);

    try {
      // 🔥 PERBAIKAN: Gunakan Query Spesifik agar tidak menarik seluruh data (Hemat Ribuan Read)
      let peserta: any = null;

      // 1. Coba cari berdasarkan nomorBIB (String)
      let qBib = query(
        collection(db, "offline_participants"),
        where("nomorBIB", "==", cleanBib)
      );
      let snapBib = await getDocs(qBib);

      // 2. Coba cari berdasarkan nomorBIB (Number) jika gagal
      if (snapBib.empty && !isNaN(Number(cleanBib))) {
        qBib = query(
          collection(db, "offline_participants"),
          where("nomorBIB", "==", Number(cleanBib))
        );
        snapBib = await getDocs(qBib);
      }

      // 3. Coba cari berdasarkan namaBib jika masih gagal
      if (snapBib.empty) {
        qBib = query(
          collection(db, "offline_participants"),
          where("namaBib", "==", cleanBib)
        );
        snapBib = await getDocs(qBib);
      }

      if (!snapBib.empty) {
        peserta = { id: snapBib.docs[0].id, ...snapBib.docs[0].data() };
      }

      if (!peserta) {
        showMsg(
          "error",
          `BIB ${cleanBib} tidak valid / belum terdaftar lunas!`,
        );
        setIsProcessing(false);
        setBibInput("");
        return;
      }
      if (peserta.waktuFinish) {
        showMsg("error", `BIB ${cleanBib} sudah terdaftar finish sebelumnya!`);
        setIsProcessing(false);
        setBibInput("");
        return;
      }

      const safeDistKey = peserta.jarak.replace(/\./g, "_");
      const gunTime = settings[`gunTime${safeDistKey}`];

      if (!gunTime) {
        showMsg(
          "error",
          `Race ${peserta.jarak} belum dimulai! Tekan tombol START dulu.`,
        );
        setIsProcessing(false);
        setBibInput("");
        return;
      }

      const nowTimestamp = Date.now();
      const calculatedDurationMs = nowTimestamp - gunTime;

      const cotLimitMinutes = settings[`cot${safeDistKey}`] || 120;
      const calculatedDurationMinutes = calculatedDurationMs / 60000;
      const overCOT = calculatedDurationMinutes > cotLimitMinutes;

      // Hitung rank berdasarkan data realtime finishers (Zero Read Cost)
      const sameCategoryFinishers = finishers.filter(
        (p: any) => p.jarak === peserta.jarak,
      );
      const rankKategori = sameCategoryFinishers.length + 1;

      await updateDoc(doc(db, "offline_participants", peserta.id), {
        waktuFinish: nowTimestamp,
        netTimeMs: calculatedDurationMs,
        isOverCOT: overCOT,
        rankKategori: rankKategori,
        activeBibCheck: "",
      });

      await updateDoc(doc(db, "settings", "virtual_run"), {
        activeBibCheck: cleanBib,
      });

      showMsg(
        "success",
        `BERHASIL FINISH: P peringkat ${rankKategori} [${peserta.jarak}] - BIB ${cleanBib}`,
      );
    } catch (error) {
      showMsg("error", "Gagal menyimpan detail waktu finish.");
    } finally {
      setBibInput("");
      setIsProcessing(false);
      setTimeout(() => bibInputRef.current?.focus(), 100);
    }
  };

  const handleResetLeaderboard = () => {
    setConfirmDialog({
      isOpen: true,
      title: "KOSONGKAN SELURUH LEADERBOARD?",
      message:
        "Tindakan ini akan menghapus data Waktu Finish, Durasi Net Time, dan Rangking seluruh pelari secara permanen dari database. Data pendaftaran peserta tidak akan terhapus. Lanjutkan?",
      type: "danger",
      confirmText: "Ya, Hapus Semua Catatan",
      onConfirm: async () => {
        setConfirmDialog({ ...confirmDialog, isOpen: false });
        setIsProcessing(true);
        try {
          const snap = await getDocs(collection(db, "offline_participants"));
          const batch = writeBatch(db);
          let count = 0;

          snap.docs.forEach((document) => {
            const data = document.data();
            if (
              data.waktuFinish !== undefined ||
              data.netTimeMs !== undefined
            ) {
              const docRef = doc(db, "offline_participants", document.id);
              batch.update(docRef, {
                waktuFinish: null,
                netTimeMs: null,
                isOverCOT: null,
                rankKategori: null,
              });
              count++;
            }
          });

          if (count > 0) {
            await batch.commit();
          }

          await updateDoc(doc(db, "settings", "virtual_run"), {
            activeBibCheck: "",
          });

          setFinishers([]);
          showMsg(
            "success",
            `Leaderboard berhasil dibersihkan! ${count} Catatan pelari direset.`,
          );
        } catch (error) {
          showMsg("error", "Gagal mereset database klasemen.");
        } finally {
          setIsProcessing(false);
        }
      },
    });
  };

  // 🔥 PERBAIKAN 2: Logic formatter waktu yang kebal falsy values
  const formatDuration = (start: number, end: number) => {
    if (
      start === null ||
      start === undefined ||
      end === null ||
      end === undefined
    )
      return "--:--:--";
    const diffMs = end - start;
    if (diffMs < 0) return "00:00:00";
    const hrs = Math.floor(diffMs / 3600000);
    const mins = Math.floor((diffMs % 3600000) / 60000);
    const secs = Math.floor((diffMs % 60000) / 1000);
    return `${hrs.toString().padStart(2, "0")}:${mins.toString().padStart(2, "0")}:${secs.toString().padStart(2, "0")}`;
  };

  const handleRemoteDoorprize = async (action: "idle" | "spin" | "stop") => {
    if (action === "idle") {
      await updateDoc(doc(db, "settings", "virtual_run"), {
        doorprizeSignal: {
          action: "idle",
          prize: "",
          winnerName: "",
          winnerBib: "",
        },
      });
      return;
    }
    const selectedPrize = prizeList.find((p) => p.id === selectedPrizeId);
    if (action === "spin" && !selectedPrize) {
      showMsg("error", "Pilih Hadiah dari Dropdown!");
      return;
    }
    try {
      if (candidates.length === 0) {
        showMsg("error", "Tidak ada kandidat tersisa!");
        return;
      }
      if ((selectedPrize.terundi || 0) >= selectedPrize.jumlah) {
        showMsg("error", "Kuota hadiah habis!");
        return;
      }
      if (action === "spin") {
        setIsSpinning(true);
        await updateDoc(doc(db, "settings", "virtual_run"), {
          doorprizeSignal: {
            action: "spin",
            prize: selectedPrize.namaHadiah,
            winnerName: "",
            winnerBib: "",
          },
        });
      } else if (action === "stop") {
        const winnerIndex = Math.floor(Math.random() * candidates.length);
        const selectedWinner = candidates[winnerIndex];

        if (selectedWinner.source === "manual") {
          setManualParticipants((prev) =>
            prev.map((p) =>
              p.id === selectedWinner.id
                ? {
                    ...p,
                    doorprizeWon: selectedPrize.namaHadiah,
                    waktuMenang: Date.now(),
                  }
                : p,
            ),
          );
        } else {
          const collectionName =
            selectedWinner.source === "offline"
              ? "offline_participants"
              : "vr_participants";
          await updateDoc(doc(db, collectionName, selectedWinner.id), {
            doorprizeWon: selectedPrize.namaHadiah,
            waktuMenang: Date.now(),
          });
        }

        await updateDoc(doc(db, "doorprize_items", selectedPrize.id), {
          terundi: (selectedPrize.terundi || 0) + 1,
        });

        const namaTampil = selectedWinner.namaLengkap || selectedWinner.nama;
        const bibTampil =
          selectedWinner.nomorBIB ||
          selectedWinner.namaBib ||
          selectedWinner.bib ||
          "-";

        await updateDoc(doc(db, "settings", "virtual_run"), {
          doorprizeSignal: {
            action: "winner",
            winnerName: namaTampil,
            winnerBib: bibTampil,
            prize: selectedPrize.namaHadiah,
          },
        });

        showMsg("success", `Pemenang: ${namaTampil}`);
        if ((selectedPrize.terundi || 0) + 1 >= selectedPrize.jumlah)
          setSelectedPrizeId("");
        setIsSpinning(false);
      }
    } catch (error) {
      showMsg("error", "Gagal memproses undian.");
      setIsSpinning(false);
    }
  };

  const handleCancelWinner = (peserta: any) => {
    setConfirmDialog({
      isOpen: true,
      title: "Batalkan Pemenang?",
      message: `Apakah Anda yakin ingin membatalkan kemenangan ${peserta.namaLengkap || peserta.nama}? Status hadiah akan dikembalikan.`,
      type: "danger",
      confirmText: "Ya, Batalkan",
      onConfirm: async () => {
        setConfirmDialog({ ...confirmDialog, isOpen: false });
        try {
          if (peserta.source === "manual") {
            setManualParticipants((prev) =>
              prev.map((p) =>
                p.id === peserta.id
                  ? { ...p, doorprizeWon: null, waktuMenang: null }
                  : p,
              ),
            );
          } else {
            const collectionName =
              peserta.source === "offline"
                ? "offline_participants"
                : "vr_participants";
            await updateDoc(doc(db, collectionName, peserta.id), {
              doorprizeWon: null,
              waktuMenang: null,
            });
          }
          const prize = prizeList.find(
            (pr) => pr.namaHadiah === peserta.doorprizeWon,
          );
          if (prize && prize.terundi > 0) {
            await updateDoc(doc(db, "doorprize_items", prize.id), {
              terundi: prize.terundi - 1,
            });
          }
          showMsg("success", "Kemenangan dibatalkan.");
        } catch (error) {
          showMsg("error", "Gagal membatalkan.");
        }
      },
    });
  };

  const handleUpdateSetting = async (key: string, value: any) => {
    await updateDoc(doc(db, "settings", "virtual_run"), { [key]: value });
  };

  return (
    <div className="min-h-screen bg-slate-50 text-slate-800 font-sans flex flex-col selection:bg-blue-100">
      {/* 🔥 CUSTOM MODAL KONFIRMASI (Bisa Dipakai Di Semua Fitur) 🔥 */}
      {confirmDialog.isOpen && (
        <div className="fixed inset-0 z-[150] flex items-center justify-center p-4 bg-slate-900/60 backdrop-blur-sm animate-in fade-in duration-200">
          <div className="bg-white rounded-3xl shadow-2xl w-full max-w-sm overflow-hidden animate-in zoom-in-95 duration-200">
            <div
              className={`p-6 text-center border-b border-slate-100 ${confirmDialog.type === "danger" ? "bg-rose-50" : "bg-blue-50"}`}
            >
              <div
                className={`w-14 h-14 mx-auto rounded-full flex items-center justify-center mb-3 shadow-sm border bg-white ${confirmDialog.type === "danger" ? "text-rose-500 border-rose-200" : "text-[#1A73E8] border-blue-200"}`}
              >
                {confirmDialog.type === "danger" ? (
                  <IconTrash />
                ) : (
                  <IconTimer />
                )}
              </div>
              <h3 className="text-lg font-black text-slate-800 tracking-tight">
                {confirmDialog.title}
              </h3>
            </div>
            <div className="p-6 text-center">
              <p className="text-sm text-slate-600 leading-relaxed mb-6 font-medium">
                {confirmDialog.message}
              </p>
              <div className="flex gap-3">
                <button
                  onClick={() =>
                    setConfirmDialog({ ...confirmDialog, isOpen: false })
                  }
                  className="w-full bg-slate-100 hover:bg-slate-200 text-slate-600 font-bold py-3 rounded-xl transition-colors text-sm"
                >
                  Batal
                </button>
                <button
                  onClick={confirmDialog.onConfirm}
                  className={`w-full font-bold py-3 rounded-xl transition-colors text-white shadow-md text-sm ${confirmDialog.type === "danger" ? "bg-rose-500 hover:bg-rose-600" : "bg-[#1A73E8] hover:bg-[#1557b0]"}`}
                >
                  {confirmDialog.confirmText}
                </button>
              </div>
            </div>
          </div>
        </div>
      )}

      {/* HEADER BAR */}
      <header className="bg-white/90 backdrop-blur-xl border-b border-slate-200 px-8 py-5 flex justify-between items-center shrink-0 z-20 sticky top-0 shadow-sm">
        <div className="flex items-center gap-4">
          <div className="w-3 h-3 rounded-full bg-[#1A73E8] shadow-[0_0_10px_rgba(26,115,232,0.5)] animate-pulse"></div>
          <h1 className="text-xl font-black text-[#152B5B] tracking-widest uppercase">
            Live Control Room
          </h1>
        </div>
        <div className="font-mono text-sm font-bold tracking-widest text-[#152B5B] bg-slate-100 px-4 py-2 rounded-lg border border-slate-200">
          {formatJam}
        </div>
      </header>

      {/* TABS NAVIGATION */}
      <nav className="flex gap-2 px-8 pt-6 shrink-0 border-b border-slate-200 bg-white">
        {[
          { id: "timing", icon: <IconTimer />, label: "Finish Line & COT" },
          { id: "doorprize", icon: <IconGift />, label: "Studio Doorprize" },
          { id: "broadcast", icon: <IconBroadcast />, label: "Broadcasting" },
          { id: "identity", icon: <IconIdentity />, label: "Identitas Event" },
        ].map((tab) => (
          <button
            key={tab.id}
            onClick={() => setActiveTab(tab.id)}
            className={`flex items-center gap-2 px-6 py-3.5 text-sm font-bold uppercase tracking-wider transition-all border-b-[3px] ${activeTab === tab.id ? "border-[#1A73E8] text-[#1A73E8] bg-blue-50/50" : "border-transparent text-slate-500 hover:text-slate-800 hover:bg-slate-50"}`}
          >
            {tab.icon} {tab.label}
          </button>
        ))}
      </nav>

      {/* TABS CONTENT */}
      <main className="flex-grow p-8 overflow-hidden flex flex-col">
        {/* ============================================================== */}
        {/* TAB 4: IDENTITAS EVENT */}
        {/* ============================================================== */}
        {activeTab === "identity" && (
          <div className="max-w-4xl mx-auto w-full">
            <div className="bg-white rounded-2xl shadow-sm border border-slate-200 p-8">
              <h2 className="text-xl font-black text-[#152B5B] uppercase tracking-widest border-b border-slate-100 pb-4 mb-6 flex items-center gap-2">
                <IconIdentity /> Identitas Tampilan Publik
              </h2>
              <form onSubmit={handleSaveIdentity} className="space-y-6">
                <div>
                  <label className="block text-sm font-bold text-slate-700 mb-2 uppercase tracking-wider">
                    Nama Event (Judul Utama)
                  </label>
                  <input
                    type="text"
                    value={identityForm.eventName}
                    onChange={(e) => setIdentityForm({...identityForm, eventName: e.target.value})}
                    placeholder="Contoh: IKA UII DIY RUN 2026"
                    className="w-full bg-slate-50 border border-slate-200 rounded-xl px-4 py-3 text-sm font-bold text-slate-800 focus:outline-none focus:border-[#1A73E8] transition-colors"
                  />
                  <p className="text-xs text-slate-500 mt-1">Tampil paling besar di bagian atas Race Clock.</p>
                </div>
                
                <div>
                  <label className="block text-sm font-bold text-slate-700 mb-2 uppercase tracking-wider">
                    Subteks (Deskripsi Kecil)
                  </label>
                  <input
                    type="text"
                    value={identityForm.eventSubtext}
                    onChange={(e) => setIdentityForm({...identityForm, eventSubtext: e.target.value})}
                    placeholder="Contoh: Official Timing System"
                    className="w-full bg-slate-50 border border-slate-200 rounded-xl px-4 py-3 text-sm font-bold text-slate-800 focus:outline-none focus:border-[#1A73E8] transition-colors"
                  />
                  <p className="text-xs text-slate-500 mt-1">Tulisan kecil di bawah judul utama.</p>
                </div>

                <div>
                  <label className="block text-sm font-bold text-slate-700 mb-2 uppercase tracking-wider">
                    URL Logo Event (Image URL / Path)
                  </label>
                  <input
                    type="text"
                    value={identityForm.eventLogo}
                    onChange={(e) => setIdentityForm({...identityForm, eventLogo: e.target.value})}
                    placeholder="Contoh: https://link-ke-foto.com/logo.png"
                    className="w-full bg-slate-50 border border-slate-200 rounded-xl px-4 py-3 text-sm font-bold text-slate-800 focus:outline-none focus:border-[#1A73E8] transition-colors"
                  />
                  <p className="text-xs text-slate-500 mt-1">Bisa berupa link URL langsung dari Cloudinary/Hosting Anda, atau biarkan <code>/logo-dpp-ika.png</code> untuk logo bawaan.</p>
                </div>

                <div className="pt-4">
                  <button
                    type="submit"
                    disabled={isProcessing}
                    className="bg-[#1A73E8] hover:bg-[#1557b0] text-white font-black px-8 py-4 rounded-xl uppercase tracking-widest shadow-md transition-colors disabled:opacity-50"
                  >
                    {isProcessing ? "Menyimpan..." : "Simpan Identitas Event"}
                  </button>
                </div>
              </form>
            </div>
          </div>
        )}

        {/* ============================================================== */}
        {/* TAB 1: TIMING & FINISH LINE */}
        {/* ============================================================== */}
        {activeTab === "timing" && (
          <div className="h-full flex flex-col gap-8">
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6 shrink-0">
              {distances.map((dist, index) => {
                const theme = colorThemes[index % colorThemes.length];
                const safeDistKey = dist.replace(/\./g, "_");
                const gunTime = settings[`gunTime${safeDistKey}`];
                const cotValue =
                  cotInputs[dist] || settings[`cot${safeDistKey}`] || "120";

                return (
                  <div
                    key={dist}
                    className={`bg-white border ${theme.border} rounded-2xl p-6 flex flex-col gap-5 shadow-sm relative overflow-hidden group hover:shadow-md transition-all`}
                  >
                    <div
                      className={`absolute top-0 right-0 w-32 h-32 ${theme.bgBlur} rounded-full blur-2xl transition-all ${theme.hoverBgBlur}`}
                    ></div>
                    <div className="flex justify-between items-start relative z-10">
                      <div className="flex-grow">
                        <h3 className="text-[11px] font-bold text-slate-500 uppercase tracking-widest">
                          KATEGORI {dist}
                        </h3>
                        {gunTime ? (
                          <>
                            <div
                              className={`text-4xl md:text-5xl font-black font-mono ${theme.textMain} mt-2 tracking-tight`}
                            >
                              {formatDuration(gunTime, currentTime.getTime())}
                            </div>
                            <div
                              className={`text-xs font-bold ${theme.textSub} mt-1`}
                            >
                              Start:{" "}
                              {new Date(gunTime).toLocaleTimeString("id-ID")}
                            </div>
                          </>
                        ) : (
                          <div
                            className={`text-sm font-bold ${theme.textSub} mt-2 py-3`}
                          >
                            Menunggu Start...
                          </div>
                        )}
                      </div>
                      <div className="shrink-0">
                        {gunTime ? (
                          <button
                            onClick={() => handleResetGunTime(dist)}
                            className="text-[10px] font-bold text-rose-500 hover:text-white bg-rose-50 hover:bg-rose-600 border border-rose-200 px-4 py-2 rounded-lg transition-colors uppercase tracking-widest shadow-sm"
                          >
                            Reset
                          </button>
                        ) : (
                          <div className="flex gap-2">
                            <button
                              onClick={() => handleStartRace(dist, true)}
                              className={`px-3 py-3 ${theme.btnBg} ${theme.btnHover} text-white text-xs font-black uppercase tracking-wider rounded-xl shadow-md transition-all`}
                            >
                              START 10S
                            </button>
                            <button
                              onClick={() => handleStartRace(dist, false)}
                              className={`px-3 py-3 bg-slate-800 hover:bg-slate-900 text-white text-xs font-black uppercase tracking-wider rounded-xl shadow-md transition-all`}
                            >
                              START NOW
                            </button>
                          </div>
                        )}
                      </div>
                    </div>

                    <div className="flex items-center justify-between pt-4 border-t border-slate-100 relative z-10 mt-auto">
                      <label className="text-[11px] font-bold text-slate-500 uppercase tracking-widest">
                        Batas COT:
                      </label>
                      <div className="flex items-center gap-2 bg-slate-50 p-1.5 rounded-lg border border-slate-200">
                        <input
                          type="number"
                          value={cotValue}
                          onChange={(e) =>
                            setCotInputs({
                              ...cotInputs,
                              [dist]: e.target.value,
                            })
                          }
                          className={`w-14 bg-white border border-slate-200 rounded text-center text-sm font-bold text-slate-800 focus:outline-none ${theme.inputFocus}`}
                        />
                        <span className="text-[10px] text-slate-500 font-medium uppercase tracking-widest">
                          menit
                        </span>
                        <button
                          onClick={() => handleUpdateCOT(dist)}
                          className="text-[9px] bg-slate-200 font-bold px-3 py-1.5 rounded text-slate-600 hover:bg-slate-300 transition-colors uppercase"
                        >
                          Set
                        </button>
                      </div>
                    </div>
                  </div>
                );
              })}
            </div>

            <div className="flex-grow grid grid-cols-1 xl:grid-cols-3 gap-8 min-h-0">
              {/* KOLOM LOGGING SCANNER */}
              <div className="xl:col-span-1 bg-white border border-slate-200 rounded-2xl p-8 flex flex-col shadow-sm text-center">
                <div className="w-16 h-16 bg-slate-50 border border-slate-200 rounded-full flex items-center justify-center text-3xl mx-auto mb-4">
                  🏁
                </div>
                <h2 className="text-base font-black text-[#152B5B] mb-2 uppercase tracking-widest">
                  Scanner Finish
                </h2>
                <p className="text-xs text-slate-500 mb-6 leading-relaxed">
                  Ketik nomor BIB pelari lalu tekan <b>Enter</b>.
                </p>

                <form onSubmit={handleSubmitFinish} className="my-auto">
                  <input
                    ref={bibInputRef}
                    type="text"
                    autoFocus
                    value={bibInput}
                    onChange={(e) => setBibInput(e.target.value)}
                    disabled={isProcessing}
                    className="w-full bg-slate-50 border border-slate-200 text-slate-800 text-center text-4xl font-black py-8 rounded-2xl focus:outline-none focus:border-[#1A73E8] focus:shadow-[0_0_20px_rgba(26,115,232,0.15)] uppercase tracking-widest transition-all placeholder:text-slate-200 shadow-inner"
                    placeholder="000"
                  />
                  <button
                    type="submit"
                    disabled={isProcessing || !bibInput}
                    className="w-full mt-6 bg-[#1A73E8] hover:bg-[#1557b0] text-white text-sm font-black py-4 rounded-xl disabled:opacity-50 transition-all uppercase tracking-widest shadow-md"
                  >
                    {isProcessing ? "Menyimpan..." : "Catat Finisher"}
                  </button>
                </form>
              </div>

              {/* TABEL LIVE RIWAYAT FINISH DETAIL */}
              <div className="xl:col-span-2 bg-white border border-slate-200 rounded-2xl flex flex-col min-h-0 overflow-hidden shadow-sm">
                <div className="p-5 border-b border-slate-100 flex justify-between items-center shrink-0 bg-slate-50">
                  <h3 className="font-bold text-slate-700 text-xs uppercase tracking-widest flex items-center gap-2">
                    <span className="w-2 h-2 rounded-full bg-emerald-500 animate-pulse"></span>{" "}
                    Riwayat Finisher Terkini
                  </h3>
                  <span className="text-[10px] font-bold uppercase tracking-widest text-[#152B5B] bg-blue-50 border border-blue-100 px-3 py-1.5 rounded-lg">
                    {finishers.length} Terdata
                  </span>
                </div>
                <div className="flex-grow overflow-y-auto p-2 custom-scrollbar">
                  <table className="w-full text-left whitespace-nowrap">
                    <thead className="text-slate-400 text-[10px] uppercase tracking-widest sticky top-0 bg-white z-10 border-b border-slate-100">
                      <tr>
                        <th className="px-5 py-4 font-bold">Peringkat</th>
                        <th className="px-5 py-4 font-bold">BIB</th>
                        <th className="px-5 py-4 font-bold">Nama Pelari</th>
                        <th className="px-4 py-4 font-bold">Kategori</th>
                        <th className="px-5 py-4 font-bold text-center">
                          Status COT
                        </th>
                        <th className="px-5 py-4 font-bold text-right">
                          Waktu Finish
                        </th>
                      </tr>
                    </thead>
                    <tbody className="divide-y divide-slate-100">
                      {finishers.length === 0 && (
                        <tr>
                          <td
                            colSpan={6}
                            className="text-center py-12 text-slate-400 text-xs italic"
                          >
                            Belum ada aktivitas di garis finish.
                          </td>
                        </tr>
                      )}
                      {finishers.map((p) => (
                        <tr
                          key={p.id}
                          className="hover:bg-blue-50/40 transition-colors"
                        >
                          <td className="px-5 py-4 font-black text-[#152B5B] text-center">
                            #{p.rankKategori || "-"}
                          </td>
                          <td className="px-5 py-4 font-mono font-black text-slate-800 text-base">
                            {p.nomorBIB || "-"}
                          </td>
                          <td className="px-5 py-4 text-xs font-bold text-slate-700 max-w-[180px] truncate">
                            {p.namaLengkap}
                          </td>
                          <td className="px-4 py-4">
                            <span className="text-[9px] font-black px-2 py-1 rounded bg-slate-100 border border-slate-200 text-slate-500 uppercase">
                              {p.jarak}
                            </span>
                          </td>
                          <td className="px-5 py-4 text-center">
                            {p.isOverCOT ? (
                              <span className="text-[9px] font-black px-2 py-0.5 bg-rose-50 text-rose-600 rounded border border-rose-200 uppercase">
                                Over COT
                              </span>
                            ) : (
                              <span className="text-[9px] font-black px-2 py-0.5 bg-emerald-50 text-emerald-600 rounded border border-emerald-200 uppercase">
                                Safe
                              </span>
                            )}
                          </td>
                          <td className="px-5 py-4 text-right">
                            <div className="font-mono font-black text-slate-800 text-sm">
                              {/* 🔥 SINTAKS FORMAT WAKTU YANG SUDAH KEBALL BUG Falsy 0 🔥 */}
                              {p.netTimeMs
                                ? formatDuration(0, p.netTimeMs)
                                : "--:--:--"}
                            </div>
                            {/* Tambahan Info Jam Aktual */}
                            {p.waktuFinish && (
                              <div className="text-[9px] text-slate-400 font-bold uppercase mt-0.5 tracking-widest">
                                Jam:{" "}
                                {new Date(p.waktuFinish).toLocaleTimeString(
                                  "id-ID",
                                )}
                              </div>
                            )}
                          </td>
                        </tr>
                      ))}
                    </tbody>
                  </table>
                </div>
              </div>
            </div>
          </div>
        )}

        {/* ============================================================== */}
        {/* TAB 2: STUDIO DOORPRIZE */}
        {/* ============================================================== */}
        {activeTab === "doorprize" && (
          <div className="h-full grid grid-cols-1 lg:grid-cols-12 gap-8 min-h-0">
            <div className="lg:col-span-4 flex flex-col overflow-y-auto pr-2 custom-scrollbar gap-6">
              <div className="bg-white border border-slate-200 rounded-2xl p-6 shadow-sm shrink-0">
                <div className="flex justify-between items-center mb-4 pb-4 border-b border-slate-100">
                  <h2 className="text-xs font-black text-[#152B5B] uppercase tracking-widest flex items-center gap-2">
                    <IconBox /> Database Hadiah
                  </h2>
                  <div className="flex gap-2">
                    <button
                      onClick={downloadPrizeTemplate}
                      className="text-[9px] font-bold uppercase tracking-widest bg-slate-100 hover:bg-slate-200 text-slate-600 px-3 py-1.5 rounded border border-slate-200 transition-colors"
                    >
                      Template
                    </button>
                    <label className="text-[9px] font-bold uppercase tracking-widest bg-[#1A73E8] hover:bg-[#1557b0] text-white px-3 py-1.5 rounded cursor-pointer transition-colors shadow-sm">
                      Import Excel
                      <input
                        type="file"
                        accept=".xlsx, .xls"
                        onChange={handleImportPrizes}
                        className="hidden"
                        disabled={isProcessing}
                      />
                    </label>
                  </div>
                </div>

                <div className="mb-4">
                  <select
                    value={selectedPrizeId}
                    onChange={(e) => setSelectedPrizeId(e.target.value)}
                    className="w-full bg-slate-50 border border-slate-300 rounded-xl px-4 py-3 text-sm font-medium text-slate-800 focus:outline-none focus:border-[#D4AF37] shadow-inner"
                  >
                    <option value="">-- Pilih Hadiah Undian --</option>
                    {prizeList.map((p) => {
                      const sisa = p.jumlah - (p.terundi || 0);
                      return (
                        <option key={p.id} value={p.id} disabled={sisa <= 0}>
                          {p.namaHadiah} ({p.kategori}) - Sisa: {sisa}/
                          {p.jumlah}
                        </option>
                      );
                    })}
                  </select>
                </div>

                <div className="mt-4 pt-4 border-t border-slate-100 flex gap-2">
                  <input
                    type="text"
                    placeholder="Nama Hadiah"
                    value={manualPrize.namaHadiah}
                    onChange={(e) =>
                      setManualPrize({
                        ...manualPrize,
                        namaHadiah: e.target.value,
                      })
                    }
                    className="flex-grow bg-slate-50 border border-slate-300 rounded px-3 py-2 text-xs text-slate-800 focus:outline-none focus:border-[#1A73E8]"
                  />
                  <input
                    type="number"
                    placeholder="Qty"
                    min="1"
                    value={manualPrize.jumlah}
                    onChange={(e) =>
                      setManualPrize({
                        ...manualPrize,
                        jumlah: parseInt(e.target.value),
                      })
                    }
                    className="w-12 bg-slate-50 border border-slate-300 rounded px-2 py-2 text-xs text-center text-slate-800 focus:outline-none"
                  />
                  <button
                    onClick={handleAddManualPrize}
                    disabled={isProcessing}
                    className="bg-slate-800 text-white font-bold px-3 py-2 rounded text-[10px] uppercase"
                  >
                    Add
                  </button>
                </div>

                <div className="flex justify-between items-center mt-3 pt-4 border-t border-slate-100">
                  <span className="text-[10px] text-slate-400 font-medium">
                    Tercatat {prizeList.length} macam barang
                  </span>
                  {prizeList.length > 0 && (
                    <button
                      onClick={handleClearPrizes}
                      className="text-[10px] font-bold text-rose-500 hover:text-rose-700 uppercase"
                    >
                      Clear All
                    </button>
                  )}
                </div>
              </div>

              <div className="bg-white border border-slate-200 rounded-2xl p-6 shadow-sm shrink-0">
                <h2 className="text-xs font-black text-[#152B5B] mb-4 uppercase tracking-widest flex items-center justify-between">
                  <span className="flex items-center gap-2">
                    <IconBroadcast /> Live Draw Screen
                  </span>
                  <a
                    href="/doorprize-screen"
                    target="_blank"
                    className="text-[9px] text-[#D4AF37] hover:bg-amber-50 border border-amber-200 px-2.5 py-1 rounded flex items-center gap-1"
                  >
                    <IconExternal /> Buka Layar
                  </a>
                </h2>

                <div className="space-y-4">
                  <button
                    onClick={syncPeserta}
                    className="w-full bg-blue-50 text-blue-600 font-bold py-2 rounded-lg text-[10px] uppercase tracking-widest border border-blue-200"
                  >
                    Re-sync Pool Peserta
                  </button>
                  <div>
                    <label className="block text-[10px] font-bold text-slate-500 uppercase tracking-widest mb-1">
                      Filter Kolam Undian
                    </label>
                    <select
                      value={filterDoorprize}
                      onChange={(e) => setFilterDoorprize(e.target.value)}
                      className="w-full bg-slate-50 border border-slate-300 rounded-xl px-4 py-2.5 text-xs font-bold text-slate-800 focus:outline-none"
                    >
                      <option value="all">
                        Semua Peserta Lunas (VR & Offline)
                      </option>
                      <option value="vr">Khusus Virtual Run Saja</option>
                      <option value="offline">Khusus Offline Run Saja</option>
                      <option value="finish">
                        Peserta Offline yang Sudah Finish
                      </option>
                    </select>
                  </div>
                  {!isSpinning ? (
                    <button
                      onClick={() => handleRemoteDoorprize("spin")}
                      className="w-full bg-[#0B2239] hover:bg-blue-950 text-white font-black py-3.5 rounded-xl uppercase text-xs tracking-widest shadow-md transition-colors"
                    >
                      Mulai Undi
                    </button>
                  ) : (
                    <button
                      onClick={() => handleRemoteDoorprize("stop")}
                      className="w-full bg-rose-600 hover:bg-rose-700 text-white font-black py-3.5 rounded-xl uppercase text-xs tracking-widest shadow-md transition-colors animate-pulse"
                    >
                      STOP! (Dapatkan Pemenang)
                    </button>
                  )}
                  <button
                    onClick={() => handleRemoteDoorprize("idle")}
                    className="w-full bg-slate-100 border border-slate-200 text-slate-500 text-[9px] font-bold py-2.5 rounded-xl uppercase"
                  >
                    Reset Layar Panggung
                  </button>
                </div>
              </div>
            </div>

            <div className="lg:col-span-8 grid grid-cols-1 xl:grid-cols-2 gap-6 min-h-0">
              {/* KOLAM KANDIDAT UNDIAN */}
              <div className="bg-white border border-slate-200 rounded-2xl flex flex-col min-h-0 overflow-hidden shadow-sm">
                <div className="p-4 border-b border-slate-100 flex justify-between items-center shrink-0 bg-slate-50">
                  <h3 className="font-bold text-slate-700 text-xs uppercase tracking-widest flex items-center gap-2">
                    <IconUsers /> Kandidat Doorprize
                  </h3>
                  <span className="text-[10px] font-bold bg-blue-50 border border-blue-100 px-2 py-1 rounded text-blue-700">
                    {candidates.length} Slot
                  </span>
                </div>
                <div className="p-2 bg-slate-50 flex gap-1 border-b border-slate-100">
                  <input
                    type="text"
                    placeholder="Nama"
                    value={manualInput.nama}
                    onChange={(e) =>
                      setManualInput({ ...manualInput, nama: e.target.value })
                    }
                    className="w-full bg-white border border-slate-300 rounded px-2 py-1 text-xs"
                  />
                  <input
                    type="text"
                    placeholder="BIB"
                    value={manualInput.bib}
                    onChange={(e) =>
                      setManualInput({ ...manualInput, bib: e.target.value })
                    }
                    className="w-16 bg-white border border-slate-300 rounded px-2 py-1 text-xs text-center"
                  />
                  <button
                    onClick={handleAddManualParticipant}
                    className="bg-white hover:bg-slate-100 border border-slate-300 px-3 rounded text-[9px] font-bold uppercase"
                  >
                    Tambah
                  </button>
                </div>
                <div className="flex-grow overflow-y-auto p-2 custom-scrollbar">
                  <table className="w-full text-left whitespace-nowrap">
                    <tbody className="divide-y divide-slate-100 text-xs">
                      {candidates.map((c) => (
                        <tr key={c.id} className="hover:bg-slate-50">
                          <td className="px-4 py-2.5 font-bold text-slate-400 uppercase tracking-tighter w-20">
                            [{c.source}]
                          </td>
                          <td className="px-4 py-2.5 font-black text-slate-800 font-mono">
                            {c.nomorBIB || "-"}
                          </td>
                          <td className="px-4 py-2.5 text-slate-700 font-medium truncate max-w-[150px]">
                            {c.namaLengkap || c.nama}
                          </td>
                        </tr>
                      ))}
                    </tbody>
                  </table>
                </div>
              </div>

              {/* TABEL LIVE DAFTAR PEMENANG */}
              <div className="bg-white border border-slate-200 rounded-2xl flex flex-col min-h-0 overflow-hidden shadow-sm">
                <div className="p-4 border-b border-slate-100 flex justify-between items-center shrink-0 bg-slate-50">
                  <h3 className="font-bold text-slate-700 text-xs uppercase tracking-widest flex items-center gap-2">
                    <IconTrophy /> Log Pemenang
                  </h3>
                  <span className="text-[10px] font-bold bg-amber-50 border border-amber-200 px-2 py-1 rounded text-amber-700">
                    {winners.length} Winner
                  </span>
                </div>
                <div className="flex-grow overflow-y-auto p-2 custom-scrollbar">
                  <table className="w-full text-left whitespace-nowrap text-xs">
                    <tbody className="divide-y divide-slate-100">
                      {winners.map((p) => (
                        <tr key={p.id} className="hover:bg-amber-50/40">
                          <td className="px-4 py-3 font-bold text-slate-800">
                            <div>
                              {p.namaLengkap || p.nama}{" "}
                              <span className="font-mono text-[10px] text-slate-400">
                                ({p.nomorBIB})
                              </span>
                            </div>
                            <div className="text-[10px] text-[#D4AF37] font-black uppercase mt-1 flex items-center gap-1">
                              <IconGift /> {p.doorprizeWon}
                            </div>
                          </td>
                          <td className="px-4 py-3 text-right">
                            <button
                              onClick={() => handleCancelWinner(p)}
                              className="text-[9px] font-bold text-rose-500 bg-rose-50 hover:bg-rose-500 hover:text-white px-2 py-1 rounded transition-colors border border-rose-200 uppercase"
                            >
                              Diskualifikasi
                            </button>
                          </td>
                        </tr>
                      ))}
                    </tbody>
                  </table>
                </div>
              </div>
            </div>
          </div>
        )}

        {/* ============================================================== */}
        {/* TAB 3: BROADCASTING & RESET CLASSIFICATION */}
        {/* ============================================================== */}
        {activeTab === "broadcast" && (
          <div className="max-w-2xl mx-auto w-full flex flex-col gap-6 mt-6 animate-in fade-in duration-300">
            <div className="bg-white border border-slate-200 rounded-2xl p-6 shadow-sm">
              <h2 className="text-xs font-black text-[#152B5B] mb-4 uppercase tracking-widest border-b border-slate-100 pb-3 flex items-center gap-2">
                <IconLink /> Tautan Video Call Pemenang
              </h2>
              <input
                type="url"
                value={settings.zoomLink || ""}
                onChange={(e) =>
                  handleUpdateSetting("zoomLink", e.target.value)
                }
                placeholder="https://zoom.us/j/..."
                className="w-full bg-slate-50 border border-slate-300 rounded-xl px-4 py-3 text-sm font-medium focus:outline-none focus:border-[#1A73E8]"
              />
            </div>

            <div className="bg-white border border-slate-200 rounded-2xl p-6 shadow-sm">
              <h2 className="text-xs font-black text-[#152B5B] mb-4 uppercase tracking-widest border-b border-slate-100 pb-3 flex items-center gap-2">
                <span className="w-2.5 h-2.5 bg-rose-500 rounded-full animate-ping"></span>{" "}
                YouTube Live Streaming
              </h2>
              <input
                type="url"
                value={settings.liveStreamLink || ""}
                onChange={(e) =>
                  handleUpdateSetting("liveStreamLink", e.target.value)
                }
                placeholder="https://youtube.com/live/..."
                className="w-full bg-slate-50 border border-slate-300 rounded-xl px-4 py-3 text-sm font-medium focus:outline-none focus:border-rose-500"
              />
            </div>

            <div className="bg-white border border-slate-200 rounded-2xl p-5 flex justify-between items-center shadow-sm">
              <div>
                <h2 className="text-xs font-black text-[#152B5B] uppercase tracking-widest mb-1">
                  Publikasi Leaderboard
                </h2>
                <p className="text-[10px] text-slate-500 font-medium">
                  Izinkan publik memantau klasemen langsung di halaman depan.
                </p>
              </div>
              <label className="relative inline-flex items-center cursor-pointer">
                <input
                  type="checkbox"
                  className="sr-only peer"
                  checked={settings.showLeaderboard || false}
                  onChange={(e) =>
                    handleUpdateSetting("showLeaderboard", e.target.checked)
                  }
                />
                <div className="w-12 h-6 bg-slate-200 rounded-full peer peer-checked:after:translate-x-full after:content-[''] after:absolute after:top-[2px] after:left-[2px] after:bg-white after:rounded-full after:h-5 after:w-5 after:transition-all peer-checked:bg-emerald-500"></div>
              </label>
            </div>

            {/* ========================================================= */}
            {/* 🔥 2. PERBAIKAN UTAMA: TOMBOL RESET DATABASE CLASSEMET LEADERBOARD 🔥 */}
            {/* ========================================================= */}
            <div className="bg-rose-50/50 border border-rose-200 rounded-2xl p-6 shadow-sm mt-4">
              <h2 className="text-xs font-black text-rose-800 uppercase tracking-widest mb-2 flex items-center gap-2">
                ⚠️ Danger Zone (Area Krusial)
              </h2>
              <p className="text-[11px] text-slate-500 leading-relaxed mb-4 font-medium">
                Gunakan fitur ini hanya saat ingin melakukan simulasi ulang
                balapan atau membersihkan catatan kotor pasca uji coba alat
                sebelum hari-H. Seluruh peringkat akan kembali kosong.
              </p>
              <button
                onClick={handleResetLeaderboard}
                disabled={isProcessing}
                className="w-full bg-rose-600 hover:bg-rose-700 text-white font-black text-xs uppercase tracking-widest py-3.5 rounded-xl transition-all shadow-md disabled:opacity-40 flex items-center justify-center gap-2"
              >
                <IconTrash /> Reset Seluruh Klasemen Balapan
              </button>
            </div>
          </div>
        )}
      </main>
    </div>
  );
}

"use client";

import { useState, useEffect } from "react";
import { db } from "@/lib/firebase";
import { doc, getDoc, setDoc, updateDoc } from "firebase/firestore";

export default function SponsorManagementPage() {
  const [sponsorGroups, setSponsorGroups] = useState<any[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [isSaving, setIsSaving] = useState(false);
  const [popup, setPopup] = useState<{
    type: "success" | "error";
    text: string;
  } | null>(null);

  // --- 🔥 STATE CUSTOM MODALS (MENGGANTIKAN ALERT BAWAAN BROWSER) 🔥 ---
  const [confirmModal, setConfirmModal] = useState<{
    isOpen: boolean;
    title: string;
    message: string;
    onConfirm: () => void;
  }>({
    isOpen: false,
    title: "",
    message: "",
    onConfirm: () => {},
  });

  // State untuk Live Preview
  const [showPreview, setShowPreview] = useState(false);

  // State lokal untuk melacak kategori mana yang di-minimize/maximize
  const [expandedGroups, setExpandedGroups] = useState<Record<string, boolean>>(
    {},
  );

  useEffect(() => {
    const fetchSponsors = async () => {
      try {
        const docRef = doc(db, "settings", "virtual_run");
        const docSnap = await getDoc(docRef);
        if (docSnap.exists()) {
          const data = docSnap.data();
          const groups = data.sponsorGroups || [];
          setSponsorGroups(groups);

          // Default: Buka semua kategori saat pertama kali load
          const initialExpandedState: Record<string, boolean> = {};
          groups.forEach((g: any) => {
            initialExpandedState[g.id] = true;
          });
          setExpandedGroups(initialExpandedState);
        }
      } catch (error) {
        console.error("Gagal memuat data sponsor:", error);
      } finally {
        setIsLoading(false);
      }
    };
    fetchSponsors();
  }, []);

  const toggleGroup = (groupId: string) => {
    setExpandedGroups((prev) => ({
      ...prev,
      [groupId]: !prev[groupId],
    }));
  };

  const handleAddGroup = () => {
    const newId = Date.now().toString();
    setSponsorGroups([
      ...sponsorGroups,
      { id: newId, title: "", size: "medium", logos: [] },
    ]);
    // Otomatis buka kategori yang baru ditambah
    setExpandedGroups((prev) => ({ ...prev, [newId]: true }));
  };

  // 🔥 FUNGSI BARU: GESER KE ATAS 🔥
  const moveGroupUp = (index: number) => {
    if (index === 0) return; // Sudah paling atas
    const newGroups = [...sponsorGroups];
    // Tukar posisi dengan elemen di atasnya
    [newGroups[index - 1], newGroups[index]] = [
      newGroups[index],
      newGroups[index - 1],
    ];
    setSponsorGroups(newGroups);
  };

  // 🔥 FUNGSI BARU: GESER KE BAWAH 🔥
  const moveGroupDown = (index: number) => {
    if (index === sponsorGroups.length - 1) return; // Sudah paling bawah
    const newGroups = [...sponsorGroups];
    // Tukar posisi dengan elemen di bawahnya
    [newGroups[index + 1], newGroups[index]] = [
      newGroups[index],
      newGroups[index + 1],
    ];
    setSponsorGroups(newGroups);
  };

  const handleRemoveGroup = (groupId: string) => {
    setConfirmModal({
      isOpen: true,
      title: "Hapus Kategori?",
      message: "Apakah Anda yakin ingin menghapus kategori ini beserta seluruh logonya? Tindakan ini tidak dapat dibatalkan.",
      onConfirm: () => {
        setSponsorGroups(sponsorGroups.filter((g) => g.id !== groupId));
        setConfirmModal((prev) => ({ ...prev, isOpen: false }));
      },
    });
  };

  const handleUpdateGroup = (groupId: string, field: string, value: string) => {
    setSponsorGroups(
      sponsorGroups.map((g) =>
        g.id === groupId ? { ...g, [field]: value } : g,
      ),
    );
  };

  const handleAddLogo = (groupId: string) => {
    setSponsorGroups(
      sponsorGroups.map((g) => {
        if (g.id === groupId) {
          const currentLogos = g.logos || [];
          return {
            ...g,
            logos: [
              ...currentLogos,
              { id: Date.now().toString(), name: "", url: "", isHidden: false },
            ],
          };
        }
        return g;
      }),
    );
    // Pastikan grup terbuka saat tambah logo
    setExpandedGroups((prev) => ({ ...prev, [groupId]: true }));
  };

  const handleUpdateLogo = (
    groupId: string,
    logoId: string,
    field: string,
    value: any,
  ) => {
    setSponsorGroups(
      sponsorGroups.map((g) => {
        if (g.id === groupId) {
          return {
            ...g,
            logos: g.logos.map((l: any) =>
              l.id === logoId ? { ...l, [field]: value } : l,
            ),
          };
        }
        return g;
      }),
    );
  };

  const handleRemoveLogo = (groupId: string, logoId: string) => {
    setConfirmModal({
      isOpen: true,
      title: "Hapus Logo?",
      message: "Apakah Anda yakin ingin menghapus logo ini?",
      onConfirm: () => {
        setSponsorGroups(
          sponsorGroups.map((g) => {
            if (g.id === groupId) {
              return { ...g, logos: g.logos.filter((l: any) => l.id !== logoId) };
            }
            return g;
          }),
        );
        setConfirmModal((prev) => ({ ...prev, isOpen: false }));
      },
    });
  };

  const handleSave = async (e: React.FormEvent) => {
    e.preventDefault();
    setIsSaving(true);
    try {
      // Menggunakan setDoc + merge untuk menghindari error jika document belum ada
      // JSON.parse(JSON.stringify) digunakan untuk membersihkan properti "undefined" yang ditolak Firebase
      await setDoc(doc(db, "settings", "virtual_run"), {
        sponsorGroups: JSON.parse(JSON.stringify(sponsorGroups)),
      }, { merge: true });
      setPopup({
        type: "success",
        text: "Hierarki sponsor berhasil diperbarui.",
      });
    } catch (error: any) {
      console.error("Firebase Save Error:", error);
      setPopup({
        type: "error",
        text: `Gagal menyimpan: ${error?.message || "Kesalahan tak dikenal"}`,
      });
    } finally {
      setIsSaving(false);
      setTimeout(() => setPopup(null), 3000);
    }
  };

  if (isLoading) {
    return (
      <div className="h-screen flex flex-col items-center justify-center text-[#1A73E8] font-medium text-sm">
        <div className="w-8 h-8 border-4 border-blue-100 border-t-[#1A73E8] rounded-full animate-spin mb-4"></div>
        MEMUAT DATA SPONSOR...
      </div>
    );
  }

  return (
    <div className="animate-in fade-in duration-300 max-w-6xl mx-auto pb-24 relative p-4 sm:p-8 font-sans">
      {/* Notifikasi Popup */}
      {popup && (
        <div className="fixed top-6 right-6 z-[100] animate-in slide-in-from-top-4 fade-in">
          <div className="bg-white rounded-xl shadow-lg border border-slate-200 p-4 flex items-center gap-4 min-w-[300px]">
            <div
              className={`w-8 h-8 rounded-full flex items-center justify-center shrink-0 ${popup.type === "success" ? "bg-[#E6F4EA] text-[#1E8E3E]" : "bg-[#FCE8E6] text-[#D93025]"}`}
            >
              {popup.type === "success" ? (
                <svg
                  className="w-5 h-5"
                  fill="currentColor"
                  viewBox="0 0 24 24"
                >
                  <path d="M9 16.2L4.8 12l-1.4 1.4L9 19 21 7l-1.4-1.4L9 16.2z" />
                </svg>
              ) : (
                <svg
                  className="w-5 h-5"
                  fill="currentColor"
                  viewBox="0 0 24 24"
                >
                  <path d="M12 2C6.48 2 2 6.48 2 12s4.48 10 10 10 10-4.48 10-10S17.52 2 12 2zm1 15h-2v-2h2v2zm0-4h-2V7h2v6z" />
                </svg>
              )}
            </div>
            <div className="flex-grow">
              <p className="text-sm font-bold text-slate-800">
                {popup.type === "success" ? "Berhasil" : "Gagal"}
              </p>
              <p className="text-xs text-slate-500">{popup.text}</p>
            </div>
            <button
              onClick={() => setPopup(null)}
              className="text-slate-400 hover:text-slate-600 px-2 py-1"
            >
              <svg className="w-4 h-4" fill="currentColor" viewBox="0 0 24 24">
                <path d="M19 6.41L17.59 5 12 10.59 6.41 5 5 6.41 10.59 12 5 17.59 6.41 19 12 13.41 17.59 19 19 17.59 13.41 12z" />
              </svg>
            </button>
          </div>
        </div>
      )}

      {/* Modal Konfirmasi Generic */}
      <GenericConfirm
        isOpen={confirmModal.isOpen}
        title={confirmModal.title}
        message={confirmModal.message}
        onConfirm={confirmModal.onConfirm}
        onCancel={() => setConfirmModal((prev) => ({ ...prev, isOpen: false }))}
      />

      {/* Header Halaman */}
      <div className="flex flex-col md:flex-row justify-between md:items-end gap-4 mb-8 border-b border-slate-200 pb-6">
        <div>
          <h1 className="text-[28px] font-bold text-slate-800 tracking-tight">
            Manajemen Sponsor & Mitra
          </h1>
          <p className="text-sm text-slate-500 mt-1">
            Kelola hierarki logo sponsor dan media partner yang akan ditampilkan
            pada halaman utama publik. Urutan di bawah ini akan sama persis dengan
            urutan di website.
          </p>
        </div>
        <button
          onClick={handleSave}
          disabled={isSaving}
          className="bg-[#1A73E8] hover:bg-[#1557B0] text-white font-bold px-8 py-2.5 rounded-lg transition-colors shadow-sm disabled:opacity-50 flex items-center justify-center gap-2 text-sm whitespace-nowrap"
        >
          {isSaving ? (
            <>
              <span className="w-4 h-4 border-2 border-white/30 border-t-white rounded-full animate-spin"></span>
              Menyimpan...
            </>
          ) : (
            "Simpan Pengaturan"
          )}
        </button>
      </div>

      <form onSubmit={handleSave} className="space-y-6">
        {sponsorGroups.length === 0 ? (
          <div className="bg-slate-50 border border-dashed border-slate-300 rounded-2xl p-12 text-center flex flex-col items-center justify-center">
            <svg
              className="w-12 h-12 text-slate-300 mb-4"
              fill="none"
              viewBox="0 0 24 24"
              stroke="currentColor"
            >
              <path
                strokeLinecap="round"
                strokeLinejoin="round"
                strokeWidth={1.5}
                d="M19 11H5m14 0a2 2 0 012 2v6a2 2 0 01-2 2H5a2 2 0 01-2-2v-6a2 2 0 012-2m14 0V9a2 2 0 00-2-2M5 11V9a2 2 0 012-2m0 0V5a2 2 0 012-2h6a2 2 0 012 2v2M7 7h10"
              />
            </svg>
            <p className="text-slate-500 font-medium text-sm">
              Belum ada kategori sponsor yang ditambahkan.
            </p>
          </div>
        ) : (
          sponsorGroups.map((group, gIdx) => {
            const isExpanded = expandedGroups[group.id] !== false;

            return (
              <div
                key={group.id}
                className="bg-white rounded-2xl border border-slate-200 shadow-sm overflow-hidden transition-all group/card hover:border-[#1A73E8]/30 relative"
              >
                {/* Nomor Urut (Visual Hint) */}
                <div className="absolute top-0 left-0 bg-slate-100 text-slate-400 text-[9px] font-bold px-2 py-0.5 rounded-br-lg z-10 pointer-events-none">
                  #{gIdx + 1}
                </div>

                {/* 🌟 HEADER GRUP (KLIK UNTUK MINIMIZE) 🌟 */}
                <div
                  className={`px-5 pt-5 pb-4 flex flex-col sm:flex-row sm:items-center justify-between gap-4 cursor-pointer hover:bg-slate-50 transition-colors relative overflow-hidden ${isExpanded ? "border-b border-slate-200" : ""} ${
                    group.size === "large" ? "bg-amber-50/50" : group.size === "medium" ? "bg-blue-50/30" : "bg-slate-50/50"
                  }`}
                  onClick={() => toggleGroup(group.id)}
                >
                  {/* Warna Aksen Kiri berdasarkan Size */}
                  <div className={`absolute top-0 bottom-0 left-0 w-1 ${
                    group.size === "large" ? "bg-amber-400" : group.size === "medium" ? "bg-[#1A73E8]" : "bg-slate-300"
                  }`}></div>

                  <div
                    className="flex-1 flex flex-col sm:flex-row gap-4 w-full ml-2"
                    onClick={(e) => e.stopPropagation()}
                  >
                    <div className="w-full sm:w-2/3">
                      <label className="block text-[9px] font-bold text-slate-500 uppercase tracking-widest mb-1">
                        Nama Kategori
                      </label>
                      <input
                        type="text"
                        value={group.title}
                        onChange={(e) =>
                          handleUpdateGroup(group.id, "title", e.target.value)
                        }
                        placeholder="Cth: Presented By / Supported By"
                        className="w-full px-3 py-2 bg-white border border-slate-300 rounded focus:border-[#1A73E8] outline-none text-xs font-bold text-slate-800"
                        required
                      />
                    </div>
                    <div className="w-full sm:w-1/3">
                      <label className="block text-[9px] font-bold text-slate-500 uppercase tracking-widest mb-1">
                        Ukuran di Web
                      </label>
                      <select
                        value={group.size || "medium"}
                        onChange={(e) =>
                          handleUpdateGroup(group.id, "size", e.target.value)
                        }
                        className="w-full px-3 py-2 bg-white border border-slate-300 rounded focus:border-[#1A73E8] outline-none text-xs text-slate-700 cursor-pointer"
                      >
                        <option value="large">Besar (Sponsor Utama)</option>
                        <option value="medium">Sedang (Partner)</option>
                        <option value="small">Kecil (Pendukung)</option>
                      </select>
                    </div>
                  </div>

                  <div className="flex items-end shrink-0 gap-2 mt-2 sm:mt-0">
                    {/* 🔥 TOMBOL PINDAH POSISI 🔥 */}
                    <div
                      className="flex bg-white border border-slate-200 rounded p-0.5 shadow-sm mr-2"
                      onClick={(e) => e.stopPropagation()}
                    >
                      <button
                        type="button"
                        disabled={gIdx === 0}
                        onClick={() => moveGroupUp(gIdx)}
                        className="p-1.5 text-slate-400 hover:text-[#1A73E8] hover:bg-blue-50 disabled:opacity-30 disabled:hover:bg-transparent rounded transition-colors"
                        title="Geser ke Atas"
                      >
                        <svg
                          className="w-4 h-4"
                          fill="none"
                          viewBox="0 0 24 24"
                          stroke="currentColor"
                        >
                          <path
                            strokeLinecap="round"
                            strokeLinejoin="round"
                            strokeWidth={2}
                            d="M5 15l7-7 7 7"
                          />
                        </svg>
                      </button>
                      <div className="w-px bg-slate-200 mx-0.5"></div>
                      <button
                        type="button"
                        disabled={gIdx === sponsorGroups.length - 1}
                        onClick={() => moveGroupDown(gIdx)}
                        className="p-1.5 text-slate-400 hover:text-[#1A73E8] hover:bg-blue-50 disabled:opacity-30 disabled:hover:bg-transparent rounded transition-colors"
                        title="Geser ke Bawah"
                      >
                        <svg
                          className="w-4 h-4"
                          fill="none"
                          viewBox="0 0 24 24"
                          stroke="currentColor"
                        >
                          <path
                            strokeLinecap="round"
                            strokeLinejoin="round"
                            strokeWidth={2}
                            d="M19 9l-7 7-7-7"
                          />
                        </svg>
                      </button>
                    </div>

                    <button
                      type="button"
                      onClick={(e) => {
                        e.stopPropagation();
                        handleAddLogo(group.id);
                      }}
                      className="bg-blue-50 text-[#1A73E8] border border-blue-200 hover:bg-blue-100 px-3 py-1.5 rounded text-[10px] font-bold uppercase flex items-center gap-1 transition-colors h-[34px]"
                    >
                      <svg
                        className="w-3 h-3"
                        fill="none"
                        viewBox="0 0 24 24"
                        stroke="currentColor"
                      >
                        <path
                          strokeLinecap="round"
                          strokeLinejoin="round"
                          strokeWidth={2}
                          d="M12 4v16m8-8H4"
                        />
                      </svg>{" "}
                      Logo
                    </button>
                    <button
                      type="button"
                      onClick={(e) => {
                        e.stopPropagation();
                        handleRemoveGroup(group.id);
                      }}
                      className="bg-rose-50 text-rose-600 border border-rose-200 hover:bg-rose-100 px-3 py-1.5 rounded text-[10px] font-bold uppercase flex items-center gap-1 transition-colors h-[34px]"
                      title="Hapus Kategori"
                    >
                      <svg
                        className="w-3 h-3"
                        fill="none"
                        viewBox="0 0 24 24"
                        stroke="currentColor"
                      >
                        <path
                          strokeLinecap="round"
                          strokeLinejoin="round"
                          strokeWidth={2}
                          d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16"
                        />
                      </svg>
                    </button>
                    <button
                      type="button"
                      className="bg-slate-200 text-slate-500 border border-slate-300 hover:bg-slate-300 px-2 py-1.5 rounded flex items-center justify-center transition-colors h-[34px]"
                      title={isExpanded ? "Tutup Kategori" : "Buka Kategori"}
                    >
                      {isExpanded ? (
                        <svg
                          className="w-4 h-4"
                          fill="none"
                          viewBox="0 0 24 24"
                          stroke="currentColor"
                        >
                          <path
                            strokeLinecap="round"
                            strokeLinejoin="round"
                            strokeWidth={2}
                            d="M5 15l7-7 7 7"
                          />
                        </svg>
                      ) : (
                        <svg
                          className="w-4 h-4"
                          fill="none"
                          viewBox="0 0 24 24"
                          stroke="currentColor"
                        >
                          <path
                            strokeLinecap="round"
                            strokeLinejoin="round"
                            strokeWidth={2}
                            d="M19 9l-7 7-7-7"
                          />
                        </svg>
                      )}
                    </button>
                  </div>
                </div>

                {/* 🌟 BODY GRUP (GRID LOGO) 🌟 */}
                {isExpanded && (
                  <div className="p-5 bg-slate-50/50">
                    {(!group.logos || group.logos.length === 0) && (
                      <div className="text-center text-slate-400 text-[11px] font-medium py-8 bg-white rounded-xl border border-dashed border-slate-300">
                        Belum ada logo di kategori ini. <br/> Klik tombol <span className="text-[#1A73E8] font-bold">"+ LOGO"</span> di kanan atas untuk menambahkan.
                      </div>
                    )}

                    {/* 🔥 MEDIA GALLERY GRID 🔥 */}
                    <div className="grid grid-cols-2 md:grid-cols-3 lg:grid-cols-4 gap-4">
                      {(group.logos || []).map((logo: any) => (
                        <div
                          key={logo.id}
                          className={`group/logo flex flex-col bg-white rounded-xl border overflow-hidden transition-all duration-300 relative ${logo.isHidden ? "border-slate-200 opacity-60 grayscale" : "border-slate-200 shadow-sm hover:shadow-md hover:border-[#1A73E8]/50 hover:-translate-y-1"}`}
                        >
                          {/* Label Hidden */}
                          {logo.isHidden && (
                            <div className="absolute top-2 left-2 bg-slate-800/80 text-white text-[9px] font-bold px-2 py-0.5 rounded backdrop-blur-sm z-10">
                              SEMBUNYI
                            </div>
                          )}

                          {/* Image Preview Area */}
                          <div className="aspect-video bg-slate-100 flex items-center justify-center p-4 relative overflow-hidden group-hover/logo:bg-slate-50 transition-colors">
                            {logo.url ? (
                              <img
                                src={logo.url}
                                alt="preview"
                                className="w-full h-full object-contain transition-transform duration-300 group-hover/logo:scale-105"
                                onError={(e) => {
                                  // Fallback jika error
                                  (e.target as HTMLImageElement).src = 'data:image/svg+xml;utf8,<svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" stroke="%2394a3b8"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="1.5" d="M4 16l4.586-4.586a2 2 0 012.828 0L16 16m-2-2l1.586-1.586a2 2 0 012.828 0L20 14m-6-6h.01M6 20h12a2 2 0 002-2V6a2 2 0 00-2-2H6a2 2 0 00-2 2v12a2 2 0 002 2z"/></svg>';
                                }}
                              />
                            ) : (
                              <svg
                                className="w-8 h-8 text-slate-300"
                                fill="none"
                                viewBox="0 0 24 24"
                                stroke="currentColor"
                              >
                                <path
                                  strokeLinecap="round"
                                  strokeLinejoin="round"
                                  strokeWidth={1.5}
                                  d="M4 16l4.586-4.586a2 2 0 012.828 0L16 16m-2-2l1.586-1.586a2 2 0 012.828 0L20 14m-6-6h.01M6 20h12a2 2 0 002-2V6a2 2 0 00-2-2H6a2 2 0 00-2 2v12a2 2 0 002 2z"
                                />
                              </svg>
                            )}

                          </div>

                          {/* Info Edit Area (Input & Action Buttons) */}
                          <div className="p-3 bg-white border-t border-slate-100 flex flex-col gap-3">
                            <div className="flex flex-col gap-2">
                              <input
                                type="text"
                                value={logo.name}
                                onChange={(e) =>
                                  handleUpdateLogo(group.id, logo.id, "name", e.target.value)
                                }
                                placeholder="Nama Brand (Opsional)"
                                className="w-full bg-transparent border-b border-transparent hover:border-slate-300 focus:border-[#1A73E8] focus:outline-none transition-colors text-xs font-bold text-slate-800 placeholder:font-normal pb-1"
                              />
                              <input
                                type="url"
                                value={logo.url}
                                onChange={(e) =>
                                  handleUpdateLogo(group.id, logo.id, "url", e.target.value)
                                }
                                placeholder="Link Gambar URL..."
                                className="w-full bg-slate-50 border border-slate-200 focus:border-[#1A73E8] focus:bg-white outline-none rounded p-1.5 text-[10px] font-mono text-slate-600 transition-colors"
                                required
                              />
                            </div>

                            {/* Tombol Aksi (Selalu Muncul) */}
                            <div className="flex items-center justify-between pt-2 border-t border-slate-100">
                              <button
                                type="button"
                                title={logo.isHidden ? "Tampilkan di Web" : "Sembunyikan dari Web"}
                                onClick={() =>
                                  handleUpdateLogo(group.id, logo.id, "isHidden", !logo.isHidden)
                                }
                                className={`flex items-center gap-1.5 px-2 py-1 rounded text-[10px] font-bold uppercase transition-colors ${logo.isHidden ? "bg-slate-100 text-slate-500 hover:bg-slate-200" : "bg-emerald-50 text-emerald-600 hover:bg-emerald-100"}`}
                              >
                                {logo.isHidden ? (
                                  <>
                                    <svg className="w-3.5 h-3.5" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                                      <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M13.875 18.825A10.05 10.05 0 0112 19c-4.478 0-8.268-2.943-9.543-7a9.97 9.97 0 011.563-3.029m5.858.908a3 3 0 114.243 4.243M9.878 9.878l4.242 4.242M9.88 9.88l-3.29-3.29m7.532 7.532l3.29 3.29M3 3l3.59 3.59m0 0A9.953 9.953 0 0112 5c4.478 0 8.268 2.943 9.543 7a10.025 10.025 0 01-4.132 5.411m0 0L21 21" />
                                    </svg>
                                    Tersembunyi
                                  </>
                                ) : (
                                  <>
                                    <svg className="w-3.5 h-3.5" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                                      <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15 12a3 3 0 11-6 0 3 3 0 016 0z" />
                                      <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M2.458 12C3.732 7.943 7.523 5 12 5c4.478 0 8.268 2.943 9.542 7-1.274 4.057-5.064 7-9.542 7-4.477 0-8.268-2.943-9.542-7z" />
                                    </svg>
                                    Tampil
                                  </>
                                )}
                              </button>
                              
                              <button
                                type="button"
                                title="Hapus Logo"
                                onClick={() => handleRemoveLogo(group.id, logo.id)}
                                className="flex items-center gap-1.5 px-2 py-1 rounded text-[10px] font-bold uppercase bg-rose-50 text-rose-600 hover:bg-rose-100 transition-colors"
                              >
                                <svg className="w-3.5 h-3.5" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16" />
                                </svg>
                                Hapus
                              </button>
                            </div>
                          </div>
                        </div>
                      ))}
                    </div>
                  </div>
                )}
              </div>
            );
          })
        )}

        <button
          type="button"
          onClick={handleAddGroup}
          className="w-full py-4 border-2 border-dashed border-slate-300 text-slate-500 rounded-2xl text-sm font-bold hover:bg-slate-50 hover:border-[#1A73E8] hover:text-[#1A73E8] transition-colors flex items-center justify-center gap-2 uppercase tracking-widest"
        >
          <svg
            className="w-5 h-5"
            fill="none"
            viewBox="0 0 24 24"
            stroke="currentColor"
          >
            <path
              strokeLinecap="round"
              strokeLinejoin="round"
              strokeWidth={2}
              d="M12 4v16m8-8H4"
            />
          </svg>
          Tambah Kategori Sponsor Baru
        </button>
      </form>

      {/* Live Preview Button */}
      <div className="fixed bottom-6 right-6 z-50">
        <button
          onClick={() => setShowPreview(true)}
          className="bg-slate-800 text-white shadow-xl hover:bg-slate-900 px-5 py-3 rounded-full flex items-center gap-2 font-bold transition-transform hover:scale-105 group"
        >
          <svg className="w-5 h-5 text-slate-300 group-hover:text-white transition-colors" fill="none" viewBox="0 0 24 24" stroke="currentColor">
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15 12a3 3 0 11-6 0 3 3 0 016 0z" />
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M2.458 12C3.732 7.943 7.523 5 12 5c4.478 0 8.268 2.943 9.542 7-1.274 4.057-5.064 7-9.542 7-4.477 0-8.268-2.943-9.542-7z" />
          </svg>
          Live Preview
        </button>
      </div>

      {/* Modal Live Preview */}
      {showPreview && (
        <div className="fixed inset-0 z-[600] flex items-center justify-center p-4 sm:p-6 bg-slate-900/60 backdrop-blur-sm animate-in fade-in duration-200">
          <div className="bg-white w-full max-w-5xl rounded-2xl shadow-2xl flex flex-col max-h-full overflow-hidden animate-in zoom-in-95 duration-200">
            {/* Header Preview */}
            <div className="flex items-center justify-between p-4 sm:p-6 border-b border-slate-100 bg-slate-50 shrink-0">
              <div className="flex items-center gap-3">
                <div className="w-10 h-10 bg-[#1A73E8]/10 rounded-full flex items-center justify-center">
                  <svg className="w-5 h-5 text-[#1A73E8]" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9.75 17L9 20l-1 1h8l-1-1-.75-3M3 13h18M5 17h14a2 2 0 002-2V5a2 2 0 00-2-2H5a2 2 0 00-2 2v10a2 2 0 002 2z" />
                  </svg>
                </div>
                <div>
                  <h3 className="font-bold text-slate-800 text-lg">Preview Publik</h3>
                  <p className="text-xs text-slate-500">Tampilan logo sponsor di halaman utama event</p>
                </div>
              </div>
              <button
                onClick={() => setShowPreview(false)}
                className="w-10 h-10 flex items-center justify-center bg-white border border-slate-200 rounded-full text-slate-500 hover:bg-slate-100 hover:text-slate-800 transition-colors"
              >
                <svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" />
                </svg>
              </button>
            </div>

            {/* Konten Preview */}
            <div className="p-4 sm:p-10 overflow-y-auto bg-[#F8F9FA] flex-grow">
              <div className="bg-white rounded-2xl p-6 sm:p-12 shadow-sm border border-slate-100">
                <div className="max-w-4xl mx-auto space-y-16">
                  {sponsorGroups.length === 0 ? (
                    <div className="text-center text-slate-400 py-10">Belum ada kategori sponsor yang diatur.</div>
                  ) : (
                    sponsorGroups.map((group, idx) => {
                      const visibleLogos = (group.logos || []).filter((l: any) => !l.isHidden);
                      if (visibleLogos.length === 0 && !group.title) return null;

                      // Mapping ukuran
                      let maxH = "max-h-24";
                      let imgH = "h-12 md:h-16";
                      if (group.size === "large") {
                        maxH = "max-h-32 md:max-h-40";
                        imgH = "h-20 md:h-28";
                      } else if (group.size === "small") {
                        maxH = "max-h-16 md:max-h-20";
                        imgH = "h-8 md:h-12";
                      }

                      return (
                        <div key={idx} className="text-center">
                          {group.title && (
                            <h3 className="text-sm font-bold text-slate-400 uppercase tracking-[0.2em] mb-6">
                              {group.title}
                            </h3>
                          )}
                          {visibleLogos.length > 0 ? (
                            <div className="flex flex-wrap justify-center items-center gap-6 md:gap-10">
                              {visibleLogos.map((logo: any) => (
                                <div key={logo.id} className={`relative flex items-center justify-center p-2 transition-transform hover:scale-105 bg-white ${maxH}`}>
                                  {logo.url ? (
                                    <img
                                      src={logo.url}
                                      alt={logo.name || "Sponsor"}
                                      className={`w-auto object-contain grayscale hover:grayscale-0 transition-all duration-500 ${imgH}`}
                                      crossOrigin="anonymous"
                                    />
                                  ) : (
                                    <div className={`w-32 bg-slate-100 flex items-center justify-center rounded text-slate-400 text-xs italic border border-dashed border-slate-200 ${imgH}`}>Logo Kosong</div>
                                  )}
                                </div>
                              ))}
                            </div>
                          ) : (
                            <div className="text-xs text-slate-300 italic">Tidak ada logo aktif</div>
                          )}
                        </div>
                      );
                    })
                  )}
                </div>
              </div>
            </div>
            
            {/* Footer Preview */}
            <div className="p-4 bg-white border-t border-slate-100 flex justify-end shrink-0">
              <button
                onClick={() => {
                  setShowPreview(false);
                  handleSave({ preventDefault: () => {} } as any);
                }}
                className="bg-[#1A73E8] hover:bg-[#1557B0] text-white font-bold px-8 py-2.5 rounded-lg transition-colors shadow-sm"
              >
                Tutup & Simpan Pengaturan
              </button>
            </div>
          </div>
        </div>
      )}

    </div>
  );
}

// Komponen Modal Konfirmasi Generic
function GenericConfirm({
  isOpen,
  title,
  message,
  onConfirm,
  onCancel,
}: {
  isOpen: boolean;
  title: string;
  message: string;
  onConfirm: () => void;
  onCancel: () => void;
}) {
  if (!isOpen) return null;

  return (
    <div className="fixed inset-0 z-[500] flex items-center justify-center p-4 bg-slate-900/40 backdrop-blur-sm animate-in fade-in duration-200">
      <div className="bg-white rounded-2xl shadow-2xl max-w-sm w-full overflow-hidden animate-in zoom-in-95 duration-200">
        <div className="p-6 text-center">
          <div className="w-16 h-16 bg-rose-50 rounded-full flex items-center justify-center mx-auto mb-4">
            <svg
              className="w-8 h-8 text-rose-500"
              fill="none"
              viewBox="0 0 24 24"
              stroke="currentColor"
            >
              <path
                strokeLinecap="round"
                strokeLinejoin="round"
                strokeWidth={2}
                d="M12 9v2m0 4h.01m-6.938 4h13.856c1.54 0 2.502-1.667 1.732-3L13.732 4c-.77-1.333-2.694-1.333-3.464 0L3.34 16c-.77 1.333.192 3 1.732 3z"
              />
            </svg>
          </div>
          <h3 className="text-lg font-bold text-slate-800 mb-2">{title}</h3>
          <p className="text-sm text-slate-500 leading-relaxed">{message}</p>
        </div>
        <div className="bg-slate-50 px-6 py-4 flex gap-3">
          <button
            onClick={onCancel}
            className="flex-1 bg-white border border-slate-200 text-slate-600 font-bold py-2.5 rounded-lg hover:bg-slate-50 transition-colors"
          >
            Batal
          </button>
          <button
            onClick={onConfirm}
            className="flex-1 bg-rose-500 text-white font-bold py-2.5 rounded-lg hover:bg-rose-600 transition-colors shadow-sm shadow-rose-500/20"
          >
            Hapus
          </button>
        </div>
      </div>
    </div>
  );
}

"use client";

import { useState, useEffect } from "react";
import { toast } from "@/lib/toast";
import { db, auth } from "@/lib/firebase";
import {
  collection,
  query,
  onSnapshot,
  orderBy,
  doc,
  updateDoc,
  writeBatch,
  addDoc,
} from "firebase/firestore";
import { onAuthStateChanged } from "firebase/auth";

export default function VerifikasiLariPage() {
  const [submissions, setSubmissions] = useState<any[]>([]);
  const [selectedSubmissions, setSelectedSubmissions] = useState<string[]>([]);
  const [loadingAction, setLoadingAction] = useState<string | null>(null);
  const [adminUser, setAdminUser] = useState<any>(null);

  // Filter State
  const [filter, setFilter] = useState<
    "Pending" | "Approved" | "Rejected" | "All"
  >("Pending");

  // Modal State untuk Image Fullscreen
  const [previewImage, setPreviewImage] = useState<string | null>(null);

  // 1. Ambil Data Admin (Untuk keperluan Log Aktivitas)
  useEffect(() => {
    const unsubscribe = onAuthStateChanged(auth, (user) => {
      setAdminUser(user);
    });
    return () => unsubscribe();
  }, []);

  // 2. Ambil Data Bukti Lari Realtime
  useEffect(() => {
    const q = query(
      collection(db, "vr_submissions"),
      orderBy("createdAt", "desc"),
    );
    const unsubscribe = onSnapshot(q, (snap) => {
      const data = snap.docs.map((doc) => ({ id: doc.id, ...doc.data() }));
      setSubmissions(data);
    });
    return () => unsubscribe();
  }, []);

  // 3. Fungsi Approve / Reject Lari (Dengan Injeksi Log Realtime)
  const handleVerifikasiLari = async (
    id: string,
    action: "Approved" | "Rejected",
    participantName: string,
  ) => {
    const isConfirm = window.confirm(
      `Apakah Anda yakin ingin menandai bukti lari ini sebagai ${action === "Approved" ? "DISETUJUI" : "DITOLAK"}?`,
    );
    if (!isConfirm) return;

    setLoadingAction(id);
    try {
      await updateDoc(doc(db, "vr_submissions", id), { status: action });

      const logData = {
        type: "lari",
        action:
          action === "Approved"
            ? "menyetujui bukti lari"
            : "menolak bukti lari",
        targetName: participantName,
        adminEmail: adminUser?.email || "Admin",
        timestamp: Date.now(),
      };
      await addDoc(collection(db, "vr_logs"), logData);
    } catch (error) {
      toast.error("Gagal memverifikasi data.");
      console.error(error);
    } finally {
      setLoadingAction(null);
    }
  };

  // 4. Fitur Bulk Delete (Hapus Banyak)
  const toggleSelectSubmission = (id: string) => {
    if (selectedSubmissions.includes(id)) {
      setSelectedSubmissions(selectedSubmissions.filter((sid) => sid !== id));
    } else {
      setSelectedSubmissions([...selectedSubmissions, id]);
    }
  };

  const filteredSubmissions = submissions.filter(
    (s) => filter === "All" || s.status === filter,
  );

  const handleSelectAll = () => {
    if (
      selectedSubmissions.length === filteredSubmissions.length &&
      filteredSubmissions.length > 0
    ) {
      setSelectedSubmissions([]);
    } else {
      setSelectedSubmissions(filteredSubmissions.map((s) => s.id));
    }
  };

  const deleteSelected = async () => {
    if (
      !confirm(
        `Yakin ingin menghapus ${selectedSubmissions.length} bukti lari secara permanen? Data yang dihapus tidak dapat dikembalikan.`,
      )
    )
      return;

    setLoadingAction("deleteBulk");
    try {
      const batch = writeBatch(db);
      selectedSubmissions.forEach((id) =>
        batch.delete(doc(db, "vr_submissions", id)),
      );
      await batch.commit();
      setSelectedSubmissions([]);
    } catch (e) {
      toast.error("Gagal menghapus data.");
    } finally {
      setLoadingAction(null);
    }
  };

  const pendingCount = submissions.filter((s) => s.status === "Pending").length;

  return (
    <div className="animate-in fade-in duration-300 max-w-7xl mx-auto pb-10 font-sans">
      {/* MODAL PREVIEW GAMBAR */}
      {previewImage && (
        <div
          className="fixed inset-0 z-[200] flex items-center justify-center bg-slate-900/80 backdrop-blur-sm p-4 md:p-10 animate-in zoom-in-95 duration-200"
          onClick={() => setPreviewImage(null)}
        >
          <div className="relative w-full max-w-4xl flex flex-col items-center justify-center">
            <button
              className="absolute -top-4 -right-4 md:-top-6 md:-right-6 bg-white text-slate-500 hover:text-slate-900 w-10 h-10 md:w-12 md:h-12 rounded-full font-bold text-xl z-50 shadow-xl transition-colors flex items-center justify-center"
              onClick={() => setPreviewImage(null)}
            >
              <svg className="w-6 h-6" fill="currentColor" viewBox="0 0 24 24">
                <path d="M19 6.41L17.59 5 12 10.59 6.41 5 5 6.41 10.59 12 5 17.59 6.41 19 12 13.41 17.59 19 19 17.59 13.41 12z" />
              </svg>
            </button>
            <img
              src={previewImage}
              alt="Preview Bukti"
              className="max-w-full max-h-[85vh] rounded-xl shadow-2xl object-contain bg-slate-900 border border-slate-700"
              onClick={(e) => e.stopPropagation()}
            />
          </div>
        </div>
      )}

      {/* HEADER HALAMAN (GOOGLE STYLE) */}
      <div className="flex flex-col md:flex-row justify-between items-start md:items-end gap-6 mb-8 bg-white p-6 sm:p-8 rounded-xl border border-slate-200 shadow-sm">
        <div>
          <div className="inline-flex items-center gap-2 bg-[#E8F0FE] text-[#1A73E8] px-3 py-1.5 rounded-lg text-xs font-bold uppercase tracking-widest mb-3">
            <svg className="w-4 h-4" fill="currentColor" viewBox="0 0 24 24">
              <path d="M9 16.17L4.83 12l-1.42 1.41L9 19 21 7l-1.41-1.41z" />
            </svg>
            Validasi Data
          </div>
          <h1 className="text-[28px] font-bold text-slate-800 tracking-tight flex items-center gap-3">
            Verifikasi Aktivitas Lari
            {pendingCount > 0 && (
              <span className="bg-[#D93025] text-white text-[11px] font-bold px-3 py-1 rounded-full shadow-sm">
                {pendingCount} Menunggu
              </span>
            )}
          </h1>
          <p className="text-sm text-slate-500 mt-2 font-medium max-w-2xl">
            Periksa tangkapan layar aplikasi lari peserta (Strava, Garmin, dll).
            Setujui data yang valid agar masuk ke total pencapaian kilometer
            mereka.
          </p>
        </div>

        {/* TOMBOL BULK ACTION */}
        <div className="flex flex-wrap gap-3 shrink-0">
          <button
            onClick={handleSelectAll}
            className="text-sm font-bold text-slate-600 bg-white border border-slate-200 hover:bg-slate-50 px-5 py-2.5 rounded-lg transition-colors shadow-sm flex items-center gap-2"
          >
            <div
              className={`w-4 h-4 rounded border flex items-center justify-center ${selectedSubmissions.length === filteredSubmissions.length && filteredSubmissions.length > 0 ? "bg-[#1A73E8] border-[#1A73E8]" : "border-slate-400"}`}
            >
              {selectedSubmissions.length === filteredSubmissions.length &&
                filteredSubmissions.length > 0 && (
                  <svg
                    className="w-3 h-3 text-white"
                    fill="none"
                    viewBox="0 0 24 24"
                    stroke="currentColor"
                  >
                    <path
                      strokeLinecap="round"
                      strokeLinejoin="round"
                      strokeWidth={3}
                      d="M5 13l4 4L19 7"
                    />
                  </svg>
                )}
            </div>
            Pilih Semua
          </button>

          {selectedSubmissions.length > 0 && (
            <button
              onClick={deleteSelected}
              disabled={loadingAction === "deleteBulk"}
              className="text-sm font-bold text-[#D93025] bg-white border border-rose-200 hover:bg-[#FCE8E6] px-5 py-2.5 rounded-lg transition-colors shadow-sm disabled:opacity-50 flex items-center gap-2"
            >
              <svg className="w-4 h-4" fill="currentColor" viewBox="0 0 24 24">
                <path d="M15 4V3H9v1H4v2h1v13c0 1.1.9 2 2 2h10c1.1 0 2-.9 2-2V6h1V4h-5zm2 15H7V6h10v13zM9 8h2v9H9zm4 0h2v9h-2z" />
              </svg>
              {loadingAction === "deleteBulk"
                ? "Menghapus..."
                : `Hapus (${selectedSubmissions.length})`}
            </button>
          )}
        </div>
      </div>

      {/* FILTER TABS (GOOGLE MATERIAL STYLE) */}
      <div className="flex overflow-x-auto gap-2 mb-6 border-b border-slate-200 pb-px hide-scrollbar">
        {["Pending", "Approved", "Rejected", "All"].map((tab) => (
          <button
            key={tab}
            onClick={() => {
              setFilter(tab as any);
              setSelectedSubmissions([]); // Reset pilihan saat pindah tab
            }}
            className={`px-5 py-3 text-sm font-bold whitespace-nowrap transition-colors border-b-2 ${
              filter === tab
                ? "border-[#1A73E8] text-[#1A73E8]"
                : "border-transparent text-slate-500 hover:text-slate-800 hover:bg-slate-50"
            }`}
          >
            {tab === "Pending" && `Menunggu (${pendingCount})`}
            {tab === "Approved" && "Disetujui"}
            {tab === "Rejected" && "Ditolak"}
            {tab === "All" && "Semua Data"}
          </button>
        ))}
      </div>

      {/* AREA DATA */}
      {filteredSubmissions.length === 0 ? (
        <div className="bg-white border border-slate-200 rounded-xl p-16 text-center shadow-sm flex flex-col items-center">
          <svg
            className="w-16 h-16 text-slate-300 mb-4"
            fill="currentColor"
            viewBox="0 0 24 24"
          >
            <path d="M19 3H4.99c-1.11 0-1.98.89-1.98 2L3 19c0 1.1.88 2 1.99 2H19c1.1 0 2-.9 2-2V5c0-1.1-.9-2-2-2zm0 12h-4c0 1.66-1.35 3-3 3s-3-1.34-3-3H4.99V5H19v10z" />
          </svg>
          <p className="text-lg font-bold text-slate-800">Tidak ada data</p>
          <p className="text-sm text-slate-500 mt-2 max-w-sm mx-auto">
            Belum ada bukti lari dengan status{" "}
            <b>
              {filter === "Pending"
                ? "Menunggu"
                : filter === "Approved"
                  ? "Disetujui"
                  : filter === "Rejected"
                    ? "Ditolak"
                    : "Semua"}
            </b>{" "}
            saat ini.
          </p>
        </div>
      ) : (
        /* GRID DATA LARI */
        <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-6">
          {filteredSubmissions.map((sub) => (
            <div
              key={sub.id}
              className={`bg-white rounded-xl overflow-hidden shadow-sm border flex flex-col relative transition-all duration-300 hover:shadow-md ${
                selectedSubmissions.includes(sub.id)
                  ? "border-[#1A73E8] bg-[#E8F0FE]/30"
                  : "border-slate-200"
              }`}
            >
              {/* Checkbox Overlay */}
              <div className="absolute top-4 left-4 z-20">
                <div
                  onClick={() => toggleSelectSubmission(sub.id)}
                  className={`w-5 h-5 rounded border flex items-center justify-center cursor-pointer transition-colors shadow-sm ${selectedSubmissions.includes(sub.id) ? "bg-[#1A73E8] border-[#1A73E8]" : "bg-white border-slate-400"}`}
                >
                  {selectedSubmissions.includes(sub.id) && (
                    <svg
                      className="w-3.5 h-3.5 text-white"
                      fill="none"
                      viewBox="0 0 24 24"
                      stroke="currentColor"
                    >
                      <path
                        strokeLinecap="round"
                        strokeLinejoin="round"
                        strokeWidth={3}
                        d="M5 13l4 4L19 7"
                      />
                    </svg>
                  )}
                </div>
              </div>

              {/* Status Lencana Kanan Atas */}
              <div className="absolute top-4 right-4 z-10">
                {sub.status === "Pending" && (
                  <span className="bg-[#FEF7E0]/90 text-[#B08D00] text-[10px] font-bold px-2.5 py-1 rounded shadow-sm uppercase tracking-wider backdrop-blur-sm border border-[#F9AB00]/20">
                    Menunggu
                  </span>
                )}
                {sub.status === "Approved" && (
                  <span className="bg-[#E6F4EA]/90 text-[#1E8E3E] text-[10px] font-bold px-2.5 py-1 rounded shadow-sm uppercase tracking-wider backdrop-blur-sm border border-[#1E8E3E]/20">
                    Disetujui
                  </span>
                )}
                {sub.status === "Rejected" && (
                  <span className="bg-[#FCE8E6]/90 text-[#D93025] text-[10px] font-bold px-2.5 py-1 rounded shadow-sm uppercase tracking-wider backdrop-blur-sm border border-[#D93025]/20">
                    Ditolak
                  </span>
                )}
              </div>

              {/* Gambar / Bukti Lari */}
              <div
                className="w-full h-48 sm:h-52 bg-slate-100 cursor-pointer overflow-hidden relative group"
                onClick={() => setPreviewImage(sub.imgUrl)}
              >
                <div className="absolute inset-0 bg-slate-900/30 flex items-center justify-center opacity-0 group-hover:opacity-100 transition-opacity z-10 backdrop-blur-[1px]">
                  <span className="text-white text-xs font-bold bg-slate-900/60 px-3 py-1.5 rounded-lg flex items-center gap-2">
                    <svg
                      className="w-4 h-4"
                      fill="currentColor"
                      viewBox="0 0 24 24"
                    >
                      <path d="M15.5 14h-.79l-.28-.27C15.41 12.59 16 11.11 16 9.5 16 5.91 13.09 3 9.5 3S3 5.91 3 9.5 5.91 16 9.5 16c1.61 0 3.09-.59 4.23-1.57l.27.28v.79l5 4.99L20.49 19l-4.99-5zm-6 0C7.01 14 5 11.99 5 9.5S7.01 5 9.5 5 14 7.01 14 9.5 11.99 14 9.5 14z" />
                    </svg>
                    Perbesar
                  </span>
                </div>
                <img
                  src={sub.imgUrl}
                  alt="Bukti Lari"
                  className="w-full h-full object-cover transition-transform duration-500 group-hover:scale-105"
                />
              </div>

              {/* Detail Konten */}
              <div className="p-4 flex-grow flex flex-col">
                <div className="mb-3">
                  <p className="text-[10px] font-bold text-slate-400 uppercase tracking-wider mb-0.5">
                    Nama Peserta
                  </p>
                  <p className="font-bold text-slate-800 text-[15px] line-clamp-1">
                    {sub.nama}
                  </p>
                </div>

                <div className="grid grid-cols-2 gap-2 mb-4 mt-auto">
                  <div className="bg-[#E8F0FE] p-2.5 rounded-lg border border-blue-100">
                    <p className="text-[9px] text-[#1A73E8] font-bold uppercase tracking-wider mb-0.5">
                      Jarak
                    </p>
                    <p className="text-lg font-bold text-[#1A73E8]">
                      {sub.jarakKm} <span className="text-xs">KM</span>
                    </p>
                  </div>
                  <div className="bg-slate-50 border border-slate-200 p-2.5 rounded-lg">
                    <p className="text-[9px] text-slate-500 font-bold uppercase tracking-wider mb-0.5">
                      Durasi
                    </p>
                    <p className="text-base font-bold text-slate-700">
                      {sub.durasi}
                    </p>
                  </div>
                </div>

                <p className="text-[10px] text-slate-500 font-medium flex items-center gap-1.5 mb-4">
                  <svg
                    className="w-3.5 h-3.5"
                    fill="currentColor"
                    viewBox="0 0 24 24"
                  >
                    <path d="M19 4h-1V2h-2v2H8V2H6v2H5c-1.11 0-1.99.9-1.99 2L3 20c0 1.1.89 2 2 2h14c1.1 0 2-.9 2-2V6c0-1.1-.9-2-2-2zm0 16H5V10h14v10zm0-12H5V6h14v2z" />
                  </svg>
                  {new Date(sub.tanggalLari).toLocaleDateString("id-ID", {
                    day: "numeric",
                    month: "long",
                    year: "numeric",
                  })}
                </p>

                {/* Tombol Aksi CRUD (Hanya Aktif jika Pending) */}
                <div className="flex gap-2 pt-3 border-t border-slate-100">
                  <button
                    onClick={() =>
                      handleVerifikasiLari(sub.id, "Rejected", sub.nama)
                    }
                    disabled={
                      loadingAction === sub.id || sub.status !== "Pending"
                    }
                    className={`flex-1 font-bold py-2 rounded-lg text-xs transition-colors flex justify-center items-center gap-1.5 ${sub.status === "Pending" ? "bg-white border border-slate-200 text-[#D93025] hover:bg-[#FCE8E6] hover:border-[#D93025]" : "bg-slate-50 text-slate-300 border border-slate-100 cursor-not-allowed"}`}
                  >
                    Tolak
                  </button>
                  <button
                    onClick={() =>
                      handleVerifikasiLari(sub.id, "Approved", sub.nama)
                    }
                    disabled={
                      loadingAction === sub.id || sub.status !== "Pending"
                    }
                    className={`flex-1 font-bold py-2 rounded-lg text-xs transition-colors shadow-sm flex justify-center items-center gap-1.5 ${sub.status === "Pending" ? "bg-[#1A73E8] text-white hover:bg-[#1557B0]" : "bg-slate-100 text-slate-400 cursor-not-allowed shadow-none"}`}
                  >
                    {loadingAction === sub.id ? (
                      <span className="w-3.5 h-3.5 border-2 border-white/30 border-t-white rounded-full animate-spin"></span>
                    ) : (
                      "Setujui"
                    )}
                  </button>
                </div>
              </div>
            </div>
          ))}
        </div>
      )}
    </div>
  );
}

"use client";

import { useState, useEffect } from "react";
import { toast } from "@/lib/toast";
import { db, auth } from "@/lib/firebase";
import {
  collection,
  doc,
  getDoc,
  getDocs,
  query,
  where,
  orderBy,
  updateDoc,
  addDoc,
  serverTimestamp,
} from "firebase/firestore";
import { onAuthStateChanged } from "firebase/auth";
import Link from "next/link";
import { useRouter } from "next/navigation";

// --- MINIMALIST ICONS ---
