          ) : processedGaleri.length === 0 ? (
            <div className="bg-white rounded-3xl p-16 text-center border border-slate-200 shadow-sm mt-10">
              <div className="w-20 h-20 bg-slate-100 rounded-full flex items-center justify-center mx-auto mb-4">
                <svg
                  className="w-10 h-10 text-slate-400"
                  fill="none"
                  viewBox="0 0 24 24"
                  stroke="currentColor"
                >
                  <path
                    strokeLinecap="round"
                    strokeLinejoin="round"
                    strokeWidth={1.5}
                    d="M4 16l4.586-4.586a2 2 0 012.828 0L16 16m-2-2l1.586-1.586a2 2 0 012.828 0L20 14m-6-6h.01M6 20h12a2 2 0 002-2V6a2 2 0 00-2-2H6a2 2 0 00-2 2v12a2 2 0 002 2z"
                  />
                </svg>
              </div>
              <h3 className="font-black text-slate-800 text-xl mb-2">
                Dokumentasi Tidak Ditemukan
              </h3>
              <p className="text-slate-500 text-sm font-medium max-w-md mx-auto">
                {searchQuery
                  ? `Tidak ada foto yang cocok dengan pencarian "${searchQuery}".`
                  : `Belum ada dokumentasi untuk tahun ${activeYear}.`}
              </p>
            </div>
          ) : (
            <div className="grid grid-cols-2 md:grid-cols-3 lg:grid-cols-4 gap-4 sm:gap-6 animate-in fade-in duration-700">
              {processedGaleri.map((foto) => (
                <div
                  key={foto.id}
                  onClick={() => setSelectedPhoto(foto)}
                  className="relative aspect-[4/3] max-w-full rounded-xl sm:rounded-2xl overflow-hidden group cursor-pointer shadow-sm hover:shadow-2xl transition-all duration-500 border border-slate-200 bg-slate-50 hover:-translate-y-1"
                >
                  <img
                    src={foto.imgUrl}
                    alt={foto.judul || "Dokumentasi Kegiatan"}
                    loading="lazy"
                    className="w-full h-full object-cover transition-transform duration-700 group-hover:scale-110"
                  />

                  {/* Ikon Zoom di Tengah Saat Hover */}
                  <div className="absolute inset-0 flex items-center justify-center opacity-0 group-hover:opacity-100 transition-opacity duration-300 z-10">
                    <div className="w-12 h-12 bg-white/20 backdrop-blur-md rounded-full flex items-center justify-center border border-white/40 text-white">
                      <svg
                        className="w-5 h-5"
                        fill="none"
                        viewBox="0 0 24 24"
                        stroke="currentColor"
                      >
                        <path
                          strokeLinecap="round"
                          strokeLinejoin="round"
                          strokeWidth={2.5}
                          d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0zM10 7v3m0 0v3m0-3h3m-3 0H7"
                        />
                      </svg>
                    </div>
                  </div>

                  {/* Overlay Gradasi & Detail */}
                  <div className="absolute inset-0 bg-gradient-to-t from-[#0F2147]/90 via-[#0F2147]/20 to-transparent opacity-0 group-hover:opacity-100 transition-opacity duration-300 flex flex-col justify-end p-4 md:p-5 z-20">
                    <p className="text-white font-bold text-xs sm:text-sm leading-snug translate-y-3 group-hover:translate-y-0 transition-transform duration-300 line-clamp-2">
                      {foto.judul || "Dokumentasi Kegiatan"}
                    </p>
                    <p className="text-[#FCD116] text-[9px] sm:text-[10px] font-black mt-2 opacity-0 group-hover:opacity-100 transition-opacity duration-500 delay-75 tracking-widest uppercase">
                      {foto.tanggal
                        ? new Date(foto.tanggal).toLocaleDateString("id-ID", {
                            day: "numeric",
                            month: "long",
                            year: "numeric",
                          })
                        : "Arsip IKA UII"}
                    </p>
                  </div>
                </div>
              ))}
            </div>
          )}
        </div>
      </main>

      <FooterPublic />
    </div>
  );
}

"use client";

import { useEffect, useState, useRef } from "react";
import { toast } from "@/lib/toast";
import { doc, getDoc, updateDoc, increment } from "firebase/firestore";
import { db, auth } from "@/lib/firebase";
import { onAuthStateChanged } from "firebase/auth";
import { useParams, useRouter } from "next/navigation";
import QRCode from "react-qr-code";
import { toPng } from "html-to-image";
import jsPDF from "jspdf";
import Link from "next/link";

// ==============================================
// 🔥 KOMPONEN SMART LOADER (PERSENTASE) 🔥
// ==============================================
const SmartLoader = () => {
  const [progress, setProgress] = useState(0);

  useEffect(() => {
    const timer = setInterval(() => {
      setProgress((oldProgress) => {
        if (oldProgress === 100) return 100;
        const diff =
          oldProgress < 50
            ? Math.random() * 15
            : oldProgress < 80
              ? Math.random() * 5
              : oldProgress < 99
                ? Math.random() * 1
                : 0;
        const nextProgress = oldProgress + diff;
        return nextProgress > 99 ? 99 : nextProgress;
      });
    }, 200);

    return () => clearInterval(timer);
  }, []);

  return (
    <div className="min-h-screen fixed inset-0 z-[9999] bg-[#0B2239] flex flex-col items-center justify-center p-6">
      <div className="absolute inset-0 bg-[url('https://www.transparenttextures.com/patterns/hexellence.png')] opacity-10"></div>
      <div className="absolute inset-0 bg-gradient-to-t from-[#0B2239] via-transparent to-[#0B2239]"></div>

      <div className="relative z-10 flex flex-col items-center w-full max-w-xs animate-in zoom-in-95 duration-500">
        <div className="w-24 h-24 bg-white rounded-full p-4 mb-8 shadow-[0_0_30px_rgba(252,209,22,0.3)] animate-pulse border-2 border-[#FCD116]">
          <img
            src="/logo-dpp-ika.png"
            alt="IKA UII Loading"
            className="w-full h-full object-contain"
          />
        </div>
        <h2 className="text-[#FCD116] font-black tracking-widest uppercase mb-1 text-sm">
          Menyiapkan Sistem
        </h2>
        <p className="text-slate-400 text-xs mb-6 font-medium tracking-wide">
          Memuat data aman terenkripsi...
        </p>

        <div className="w-full bg-[#1e3656] rounded-full h-3 mb-3 p-0.5 border border-white/10 shadow-inner overflow-hidden">
          <div
            className="bg-gradient-to-r from-[#F29900] to-[#FCD116] h-full rounded-full transition-all duration-300 ease-out relative"
            style={{ width: `${Math.floor(progress)}%` }}
          >
            <div className="absolute top-0 right-0 bottom-0 left-0 bg-white/20 animate-[shimmer_1.5s_infinite]"></div>
          </div>
        </div>

        <div className="flex justify-between w-full text-[10px] font-bold text-slate-300">
          <span>0%</span>
          <span className="text-[#FCD116] text-lg">
            {Math.floor(progress)}%
          </span>
          <span>100%</span>
        </div>
      </div>
    </div>
  );
};

// ==============================================
// 🔥 KOMPONEN WATERMARK PENGAMAN KARTU 🔥
// ==============================================
const SecurityWatermark = () => (
  <div className="absolute inset-0 z-20 overflow-hidden pointer-events-none opacity-[0.035] flex flex-wrap items-center justify-center p-2">
    {Array.from({ length: 40 }).map((_, i) => (
      <span
        key={i}
        className="text-[14px] font-mono font-bold text-slate-950 mx-2 my-2"
        style={{ transform: "rotate(-30deg)" }}
      >
        IKA UII DIY VALID KTA
      </span>
    ))}
  </div>
);

export default function KTAPage() {
  const params = useParams();
  const router = useRouter();
  const id = params.id as string;

  const [userData, setUserData] = useState<any>(null);
  const [periodeData, setPeriodeData] = useState<any>(null);
  const [isLoading, setIsLoading] = useState(true);

  const [isProcessingPNG, setIsProcessingPNG] = useState(false);
  const [isProcessingPDF, setIsProcessingPDF] = useState(false);

  const [isOwner, setIsOwner] = useState(false);
  const [currentUser, setCurrentUser] = useState<any>(undefined);

  const exportContainerRef = useRef<HTMLDivElement>(null);
  const containerRef = useRef<HTMLDivElement>(null);

  const [currentUrl, setCurrentUrl] = useState("");
  const [scale, setScale] = useState(1);
  const [userKoleksi, setUserKoleksi] = useState("");

  // 1. CEK AUTH STATE
  useEffect(() => {
    const unsubscribe = onAuthStateChanged(auth, (user) => {
      if (user) setCurrentUser(user);
      else setCurrentUser(null);
    });
    return () => unsubscribe();
  }, []);

  // 2. FETCH DATA & CEK OWNER
  useEffect(() => {
    if (typeof window !== "undefined") setCurrentUrl(window.location.href);

    const fetchData = async () => {
      try {
        let docRef = doc(db, "pengurus", id);
        let docSnap = await getDoc(docRef);
        let koleksiFound = "pengurus";

        if (!docSnap.exists()) {
          docRef = doc(db, "pendaftar", id);
          docSnap = await getDoc(docRef);
          koleksiFound = "pendaftar";
        }

        if (docSnap.exists()) {
          const uData: any = { id: docSnap.id, ...docSnap.data() };
          setUserData(uData);
          setUserKoleksi(koleksiFound);

          if (currentUser) {
            const isUidMatch = currentUser.uid === id;
            const isEmailMatch =
              uData.email &&
              currentUser.email &&
              uData.email.toLowerCase() === currentUser.email.toLowerCase();

            if (isUidMatch || isEmailMatch) {
              setIsOwner(true);
            } else {
              setIsOwner(false);
            }
          }

          if (uData.periodeId) {
            const pRef = doc(db, "periode", uData.periodeId);
            const pSnap = await getDoc(pRef);
            if (pSnap.exists()) setPeriodeData(pSnap.data());
          }
        }
      } catch (error) {
        console.error("Error fetching data:", error);
      } finally {
        setIsLoading(false);
      }
    };

    if (id && currentUser !== undefined) fetchData();
  }, [id, currentUser]);

  // 3. LOGIKA RESPONSIVE SCALE
  useEffect(() => {
    const handleResize = () => {
      if (containerRef.current) {
        const containerWidth = containerRef.current.offsetWidth;
        const isDesktop = window.innerWidth >= 1024;
        const baseWidth = isDesktop ? 840 : 400;
        const newScale = Math.min(1, containerWidth / baseWidth);
        setScale(newScale * 0.95);
      }
    };
    setTimeout(handleResize, 150);
    window.addEventListener("resize", handleResize);
    return () => window.removeEventListener("resize", handleResize);
  }, [userData]);

  const getTanggalDaftar = () => {
    if (!userData || !userData.createdAt) return "-";
    return new Date(userData.createdAt).toLocaleDateString("id-ID", {
      day: "2-digit",
      month: "short",
      year: "numeric",
    });
  };

  const getNIA = () => {
    if (!userData) return "";
    if (userData.nia) return userData.nia;
    return "MENUNGGU PENOMORAN";
  };

  const getSingkatanFakultas = (fakultas: string) => {
    if (!fakultas) return "-";
    const lower = fakultas.toLowerCase();
    if (lower.includes("teknologi industri")) return "FTI";
    if (lower.includes("matematika")) return "FMIPA";
    if (lower.includes("hukum")) return "FH";
    if (lower.includes("ekonomi")) return "FE/FBE";
    if (lower.includes("kedokteran")) return "FK";
    if (lower.includes("psikologi")) return "FPSB";
    if (lower.includes("sipil")) return "FTSP";
    if (lower.includes("agama")) return "FIAI";
    return fakultas;
  };

  const updatePrintStats = async () => {
    try {
      const currentDate = new Date().toISOString();
      await updateDoc(doc(db, userKoleksi || "pendaftar", id), {
        printCount: increment(1),
        lastPrintDate: currentDate,
      });
    } catch (error) {
      console.warn("Gagal update statistik KTA, melanjutkan unduhan...", error);
    }
  };

  const handleDownloadPNG = async () => {
    setIsProcessingPNG(true);
    try {
      await updatePrintStats();
      await new Promise((resolve) => setTimeout(resolve, 500));

      if (!exportContainerRef.current)
        throw new Error("Elemen tidak ditemukan");

      const dataUrl = await toPng(exportContainerRef.current, {
        cacheBust: true,
        backgroundColor: "#ffffff",
      });

      const link = document.createElement("a");
      link.href = dataUrl;
      link.download = `E-KTA_${userData?.nama ? userData.nama.replace(/\s+/g, "_") : "Anggota"}.png`;
      document.body.appendChild(link);
      link.click();
      document.body.removeChild(link);
    } catch (error: any) {
      console.error("Unduh PNG Error:", error);
      toast.error(`Gagal mengunduh gambar: ${error?.message || "Kesalahan tak dikenal"}`);
    } finally {
      setIsProcessingPNG(false);
    }
  };

  const handleDownloadPDF = async () => {
    setIsProcessingPDF(true);
    try {
      await updatePrintStats();
      await new Promise((resolve) => setTimeout(resolve, 500));

      if (!exportContainerRef.current)
        throw new Error("Elemen tidak ditemukan");

      const dataUrl = await toPng(exportContainerRef.current, {
        cacheBust: true,
        pixelRatio: 3,
        backgroundColor: "#ffffff",
      });

      const pdf = new jsPDF({
        orientation: "landscape",
        unit: "mm",
        format: "a4",
      });
      const pdfWidth = pdf.internal.pageSize.getWidth();
      const pdfHeight = pdf.internal.pageSize.getHeight();
      const margin = 15;

      const imgProps = pdf.getImageProperties(dataUrl);
      const ratio = imgProps.height / imgProps.width;

      let renderWidth = pdfWidth - margin * 2;
      let renderHeight = renderWidth * ratio;

      if (renderHeight > pdfHeight - margin * 2) {
        renderHeight = pdfHeight - margin * 2;
        renderWidth = renderHeight / ratio;
      }

      const xOffset = (pdfWidth - renderWidth) / 2;
      const yOffset = (pdfHeight - renderHeight) / 2;

      pdf.addImage(dataUrl, "PNG", xOffset, yOffset, renderWidth, renderHeight);
      pdf.save(
        `E-KTA_${userData?.nama ? userData.nama.replace(/\s+/g, "_") : "Anggota"}.pdf`,
      );
    } catch (error: any) {
      console.error("Unduh PDF Error:", error);
      toast.error(`Gagal mengunduh PDF: ${error?.message || "Kesalahan tak dikenal"}`);
    } finally {
      setIsProcessingPDF(false);
    }
  };

  // 🔥 DI SINI SMART LOADER DIPANGGIL 🔥
  if (isLoading) {
    return <SmartLoader />;
  }

  if (!userData) {
    return (
      <div className="min-h-screen flex flex-col items-center justify-center bg-[#F8F9FA] px-4 font-sans">
        <div className="w-16 h-16 bg-slate-200 text-slate-400 rounded-full flex items-center justify-center mb-4">
          <svg
            className="w-8 h-8"
            fill="none"
            viewBox="0 0 24 24"
            stroke="currentColor"
          >
            <path
              strokeLinecap="round"
              strokeLinejoin="round"
              strokeWidth={2}
              d="M6 18L18 6M6 6l12 12"
            />
          </svg>
        </div>
        <h2 className="text-xl font-medium text-[#202124] mb-2">
          Data Tidak Ditemukan
        </h2>
        <p className="text-sm text-[#5F6368] mb-6">
          KTA ini tidak valid atau telah dicabut.
        </p>
        <button
          onClick={() => router.back()}
          className="text-sm font-medium text-[#1A73E8] border border-[#DADCE0] bg-white hover:bg-[#F8F9FA] px-6 py-2 rounded-md transition-colors"
        >
          Kembali
        </button>
      </div>
    );
  }

  const startYear = periodeData?.tglMulai
    ? new Date(periodeData.tglMulai).getFullYear()
    : "";
  const endYear = periodeData?.tglSelesai
    ? new Date(periodeData.tglSelesai).getFullYear()
    : "";
  const displayPeriodeTahun =
    startYear && endYear ? `${startYear} - ${endYear}` : "";

  // ==============================================
  // DESAIN KARTU DEPAN
  // ==============================================
  const CardFront = () => (
    <div className="w-[380px] h-[600px] bg-white rounded-[20px] border border-[#DADCE0] overflow-hidden flex flex-col relative shadow-[0_15px_40px_rgba(0,0,0,0.12)] font-sans shrink-0 text-center">
      <SecurityWatermark />
      <img
        src="/logo-dpp-ika.png"
        className="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 w-56 h-56 opacity-[0.04] grayscale pointer-events-none z-0"
      />

      <div className="relative pt-8 pb-5 w-full shrink-0 z-10 bg-[#0B1528] flex flex-col items-center justify-center">
        <div className="absolute bottom-0 left-0 right-0 h-4 bg-[#224A9A]"></div>
        <div className="bg-white p-1.5 rounded-full w-[64px] h-[64px] flex items-center justify-center shadow-md border-[3px] border-white/20 mb-3 relative z-10">
          <img
            src="/logo-dpp-ika.png"
            alt="Logo UII"
            className="w-full h-full object-contain"
          />
        </div>
        <div className="flex flex-col z-10 px-4">
          <h1 className="text-white font-black text-[18px] tracking-widest uppercase leading-none mb-1.5 drop-shadow-md">
            KARTU TANDA {userData.isPengurus ? "PENGURUS" : "ANGGOTA"}
          </h1>
          <h2 className="text-[#F29900] font-bold text-[9px] tracking-[0.2em] uppercase drop-shadow-sm">
            DPW IKA UII D.I.YOGYAKARTA
          </h2>
        </div>
      </div>
      <div className="h-[6px] w-full bg-[#F29900] shrink-0 z-10 relative shadow-sm"></div>

      <div className="flex-grow flex flex-col items-center px-6 py-6 relative z-10">
        <div className="w-[120px] h-[155px] bg-[#F8F9FA] rounded-xl border-[4px] border-white shadow-[0_8px_20px_rgba(0,0,0,0.15)] overflow-hidden shrink-0 mb-4">
          {userData.fotoUrl ? (
            <img
              src={userData.fotoUrl}
              className="w-full h-full object-cover"
              crossOrigin="anonymous"
              style={{ objectPosition: userData.fotoPosition || "center" }}
            />
          ) : (
            <div className="w-full h-full flex items-center justify-center text-[#9AA0A6] text-xs font-medium bg-[#E8EAED]">
              Tanpa Foto
            </div>
          )}
        </div>

        <div className="w-full space-y-3.5">
          <div>
            <p className="text-[18px] font-black text-[#0B1528] uppercase leading-tight line-clamp-2 px-2">
              {userData.namaLengkap || userData.nama}
            </p>
          </div>
          <div>
            <p className="text-[9px] font-bold text-[#9AA0A6] uppercase tracking-widest mb-0.5">
              Nomor Induk {userData.isPengurus ? "Pengurus" : "Anggota"}
            </p>
            <p className="text-[15px] font-bold text-[#0B1528] tracking-widest leading-none font-mono bg-[#F8F9FA] inline-block px-4 py-1.5 rounded-md border border-[#EBEBEB]">
              {getNIA()}
            </p>
          </div>
          <div>
            <p className="text-[9px] font-bold text-[#9AA0A6] uppercase tracking-widest mb-0.5">
              Program Studi / Angkatan
            </p>
            <p className="text-[12px] font-black text-[#224A9A] uppercase leading-none">
              {getSingkatanFakultas(userData.fakultas)} /{" "}
              {userData.programStudi || "-"} /{" "}
              {userData.angkatan || userData.tahunLulus || "-"}
            </p>
            {displayPeriodeTahun && (
              <p className="text-[10px] font-bold text-slate-500 uppercase tracking-widest mt-1.5">
                Periode {displayPeriodeTahun}
              </p>
            )}

            <div className="mt-2.5">
              <span className="inline-block text-[11px] font-bold text-white bg-[#0B1528] px-3 py-1 rounded-sm uppercase tracking-wider shadow-sm">
                {userData.jabatan === "Koordinator Bidang"
                  ? `Koordinator ${userData.bidang}`
                  : userData.jabatan === "Anggota"
                    ? `Anggota ${userData.bidang}`
                    : userData.jabatan}
              </span>
            </div>
          </div>
        </div>
      </div>

      <div className="pt-0.2 pb-3 bg-[#F8FAFC] border-t border-[#EBEBEB] shrink-0 z-10 relative flex items-center justify-center">
        <p className="text-[12px] font-black tracking-[0.2em] uppercase flex items-center gap-0.5">
          <span className="text-[#0B1528]">IKADIY.</span>
          <span className="text-[#224A9A]">UII</span>
          <span className="text-[#0B1528]">.AC.ID</span>
        </p>
      </div>
    </div>
  );

  // ==============================================
  // DESAIN KARTU BELAKANG
  // ==============================================
  const CardBack = () => (
    <div className="w-[380px] h-[600px] bg-white rounded-[20px] border border-[#DADCE0] overflow-hidden flex flex-col relative shadow-[0_15px_40px_rgba(0,0,0,0.12)] font-sans shrink-0">
      <SecurityWatermark />
      <img
        src="/logo-dpp-ika.png"
        className="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 w-48 h-48 opacity-[0.04] grayscale pointer-events-none z-0"
      />
      <div className="h-[24px] bg-[#0B1528] w-full shrink-0 z-10 flex">
        <div className="w-[70%] bg-[#0B1528] h-full"></div>
        <div
          className="w-[30%] bg-[#224A9A] h-full"
          style={{ clipPath: "polygon(15% 0, 100% 0, 100% 100%, 0% 100%)" }}
        ></div>
      </div>
      <div className="h-[6px] bg-[#F29900] w-full shrink-0 z-10"></div>

      <div className="flex-grow flex flex-col px-8 py-8 items-center z-10 relative">
        <h3 className="text-[16px] font-black text-[#0B1528] uppercase tracking-widest mb-6 border-b-2 border-[#EBEBEB] pb-2 text-center w-full">
          Ketentuan Penggunaan
        </h3>
        <ol className="text-[13px] text-[#5F6368] space-y-4 pl-4 list-decimal leading-relaxed text-justify w-full font-medium mb-auto">
          <li>
            Kartu ini diterbitkan oleh DPW IKA UII Yogyakarta dan merupakan
            bukti keanggotaan yang sah.
          </li>
          <li>
            Kartu tidak dapat dipindahtangankan dan wajib ditunjukkan untuk
            mengakses layanan, acara, atau klaim potongan harga pada mitra
            jaringan bisnis IKA UII DIY.
          </li>
          <li>
            Apabila menemukan kartu ini, harap dikembalikan kepada Sekretariat
            DPW IKA UII DIY melalui email: <strong>ika.diy@uii.ac.id</strong>.
          </li>
        </ol>
        <div className="flex flex-col items-center justify-center w-full mt-8 pt-8 border-t border-[#EBEBEB]">
          <div className="w-[140px] h-[140px] p-3 bg-white border border-[#DADCE0] rounded-xl shadow-sm mb-4 relative z-10 flex-shrink-0">
            <QRCode
              value={currentUrl}
              size={128}
              style={{ width: "100%", height: "100%" }}
              level="M"
            />
          </div>
        </div>
      </div>
    </div>
  );

  return (
    <div className="min-h-screen bg-[#F8F9FA] font-sans flex flex-col overflow-hidden relative">
      <div
        style={{
          position: "absolute",
          top: "-10000px",
          left: "-10000px",
          width: "1200px",
          height: "900px",
        }}
      >
        <div
          ref={exportContainerRef}
          className="bg-white p-12 flex flex-row gap-10 justify-center items-center rounded-lg"
          style={{
            width: "960px",
            height: "750px",
            boxSizing: "border-box",
          }}
        >
          <CardFront />
          <CardBack />
        </div>
      </div>

      <header className="bg-white border-b border-[#DADCE0] sticky top-0 z-40 shrink-0 w-full shadow-sm">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 h-14 flex items-center justify-between">
          <div className="flex items-center gap-3">
            <img
              src="/logo-dpp-ika.png"
              alt="Logo"
              className="w-7 h-7 object-contain"
            />
            <h1 className="font-medium text-[#202124] text-sm sm:text-base">
              Identitas KTA Digital
            </h1>
          </div>
          <span
            className={`text-[10px] font-bold px-3 py-1 rounded-full uppercase tracking-wider ${userData.status_pengurus === "Aktif" || userData.role === "pengurus" ? "bg-[#E6F4EA] text-[#1E8E3E] border border-[#CEEAD6]" : "bg-[#FEF7E0] text-[#B06000] border border-[#FCE8B2]"}`}
          >
            {userData.status_pengurus === "Aktif" ||
            userData.role === "pengurus"
              ? "Terverifikasi"
              : "Pending"}
          </span>
        </div>
      </header>

      <main className="flex-grow flex flex-col items-center py-6 sm:py-10 px-4 sm:px-6 w-full">
        <div className="w-full max-w-7xl bg-white border border-[#DADCE0] rounded-2xl flex flex-col lg:flex-row overflow-hidden shadow-lg items-stretch mb-10">
          <div
            ref={containerRef}
            className="w-full lg:w-[65%] bg-[#F1F3F4] sm:bg-[#F8F9FA] p-6 sm:p-10 border-b lg:border-b-0 lg:border-r border-[#DADCE0] flex flex-col items-center justify-center relative min-h-[650px]"
          >
            <div className="w-full flex justify-between items-center mb-10 max-w-[800px]">
              <p className="text-sm text-[#5F6368] font-semibold flex items-center gap-2">
                <svg
                  className="w-4 h-4 text-[#1A73E8]"
                  fill="none"
                  viewBox="0 0 24 24"
                  stroke="currentColor"
                >
                  <path
                    strokeLinecap="round"
                    strokeLinejoin="round"
                    strokeWidth={2}
                    d="M12 18h.01M8 21h8a2 2 0 002-2V5a2 2 0 00-2-2H8a2 2 0 00-2 2v14a2 2 0 002 2z"
                  />
                </svg>
                Preview Kartu
              </p>
            </div>

            <div
              className="flex flex-col lg:flex-row items-center justify-center gap-8 w-full transition-transform duration-300"
              style={{
                transform: `scale(${scale})`,
                transformOrigin: "top center",
              }}
            >
              <CardFront />
              <CardBack />
            </div>
          </div>

          <div className="w-full lg:w-[35%] flex flex-col bg-white relative">
            {isOwner ? (
              <div className="p-6 sm:p-10 flex flex-col h-full lg:sticky lg:top-14">
                <div className="mb-auto">
                  <h3 className="text-2xl font-bold text-[#202124] mb-3 tracking-tight">
                    Identitas Elektronik
                  </h3>

                  {!userData.fotoUrl && (
                    <div className="text-[13px] text-[#D93025] mb-5 font-medium flex items-start gap-2 bg-[#FCE8E6] p-4 rounded-lg border border-[#FAD2CF]">
                      <svg
                        className="w-5 h-5 shrink-0 mt-0.5"
                        fill="none"
                        viewBox="0 0 24 24"
                        stroke="currentColor"
                      >
                        <path
                          strokeLinecap="round"
                          strokeLinejoin="round"
                          strokeWidth={2}
                          d="M12 9v2m0 4h.01m-6.938 4h13.856c1.54 0 2.502-1.667 1.732-3L13.732 4c-.77-1.333-2.694-1.333-3.464 0L3.34 16c-.77 1.333.192 3 1.732 3z"
                        />
                      </svg>
                      Harap lengkapi Pas Foto di Pengaturan Profil agar KTA Anda
                      sah dan dapat dicetak.
                    </div>
                  )}

                  <p className="text-[#5F6368] text-[15px] leading-relaxed mb-8">
                    Identitas digital Anda kini lebih praktis. Tunjukkan E-KTA
                    ini untuk keperluan presensi agenda IKA UII DIY, sekaligus
                    sebagai akses untuk mengklaim berbagai manfaat istimewa dari
                    mitra jaringan alumni.
                  </p>
                </div>

                <div className="flex flex-col gap-4 mt-6">
                  <p className="text-xs font-semibold text-[#9AA0A6] uppercase tracking-wider">
                    Opsi Unduhan KTA
                  </p>

                  <div className="flex flex-col gap-3">
                    <button
                      onClick={handleDownloadPDF}
                      disabled={isProcessingPDF || isProcessingPNG}
                      className="w-full bg-[#1A73E8] hover:bg-[#1557B0] text-white font-medium py-3.5 px-4 rounded-lg transition-colors flex justify-center items-center gap-2 disabled:opacity-50 text-sm shadow-md"
                    >
                      {isProcessingPDF ? (
                        "Memproses PDF..."
                      ) : (
                        <>
                          <svg
                            className="w-5 h-5"
                            fill="none"
                            viewBox="0 0 24 24"
                            stroke="currentColor"
                          >
                            <path
                              strokeLinecap="round"
                              strokeLinejoin="round"
                              strokeWidth={2}
                              d="M9 12h6m-6 4h6m2 5H7a2 2 0 01-2-2V5a2 2 0 012-2h5.586a1 1 0 01.707.293l5.414 5.414a1 1 0 01.293.707V19a2 2 0 01-2 2z"
                            />
                          </svg>
                          Unduh KTA (Versi PDF)
                        </>
                      )}
                    </button>

                    <button
                      onClick={handleDownloadPNG}
                      disabled={isProcessingPNG || isProcessingPDF}
                      className="w-full bg-white border border-[#DADCE0] hover:bg-[#F8F9FA] text-[#1A73E8] font-medium py-3.5 px-4 rounded-lg transition-colors flex justify-center items-center gap-2 disabled:opacity-50 text-sm shadow-sm"
                    >
                      {isProcessingPNG ? (
                        "Memproses PNG..."
                      ) : (
                        <>
                          <svg
                            className="w-5 h-5"
                            fill="none"
                            viewBox="0 0 24 24"
                            stroke="currentColor"
                          >
                            <path
                              strokeLinecap="round"
                              strokeLinejoin="round"
                              strokeWidth={2}
                              d="M4 16l4.586-4.586a2 2 0 012.828 0L16 16m-2-2l1.586-1.586a2 2 0 012.828 0L20 14m-6-6h.01M6 20h12a2 2 0 002-2V6a2 2 0 00-2-2H6a2 2 0 00-2 2v12a2 2 0 002 2z"
                            />
                          </svg>
                          Unduh KTA (Versi Gambar)
                        </>
                      )}
                    </button>
                  </div>

                  <Link
                    href="/anggota"
                    className="w-full text-center bg-[#F1F3F4] hover:bg-[#E8EAED] text-[#5F6368] hover:text-[#202124] font-medium py-3.5 mt-2 text-sm transition-colors rounded-lg"
                  >
                    Kembali ke Dashboard
                  </Link>
                </div>
              </div>
            ) : (
              <div className="p-6 sm:p-10 flex flex-col justify-center items-center h-full min-h-[400px]">
                <div className="w-24 h-24 bg-[#E6F4EA] text-[#1E8E3E] rounded-full flex items-center justify-center mb-6 shadow-md border-[6px] border-white ring-1 ring-[#CEEAD6]">
                  <svg
                    className="w-12 h-12"
                    fill="none"
                    viewBox="0 0 24 24"
                    stroke="currentColor"
                  >
                    <path
                      strokeLinecap="round"
                      strokeLinejoin="round"
                      strokeWidth={3}
                      d="M5 13l4 4L19 7"
                    />
                  </svg>
                </div>
                <h3 className="text-3xl font-black text-[#202124] mb-3 tracking-tight">
                  KTA Terverifikasi
                </h3>
                <p className="text-[#5F6368] text-[16px] leading-relaxed mb-8 text-center max-w-sm">
                  Kartu Tanda Anggota ini adalah dokumen resmi yang sah dan
                  terdaftar pada database{" "}
                  <strong>DPW IKA UII D.I.YOGYAKARTA</strong>.
                </p>
                <div className="w-full max-w-[200px] h-[2px] bg-[#EBEBEB] mb-8"></div>
                <p className="text-xs text-[#9AA0A6] font-mono tracking-widest uppercase bg-[#F8F9FA] px-4 py-2 rounded-md border border-[#EBEBEB]">
                  Verification Stamp
                </p>
              </div>
            )}
          </div>
        </div>
      </main>

      <footer className="w-full bg-[#0A1022] mt-auto shrink-0 relative overflow-hidden">
        <div className="absolute inset-0 opacity-10 bg-[url('https://www.transparenttextures.com/patterns/hexellence.png')]"></div>
        <div className="max-w-7xl mx-auto relative z-10 flex flex-col sm:flex-row justify-between items-center px-6 py-6 gap-3 text-center sm:text-left">
          <p className="text-[11px] text-[#9AA0A6] font-medium tracking-wider">
            &copy; {new Date().getFullYear()} DPW IKA UII DIY.
          </p>
          <p className="text-[11px] text-[#5F6368] font-medium tracking-wide">
            Dikembangkan melalui kerja sama Media & Publikasi DPW dengan{" "}
            <span className="text-[#A0B4B7]">
              PT Guwigo Teknologi Indonesia
            </span>
            .
          </p>
        </div>
      </footer>
    </div>
  );
}

"use client";

import { useState, useEffect } from "react";
import { db } from "@/lib/firebase";
import {
  collection,
  onSnapshot,
  query,
  where,
  doc,
  getDoc,
} from "firebase/firestore";
import Link from "next/link";

interface Runner {
  id: string;
  namaLengkap: string;
  namaBib: string;
  bibNumber: string;
  jarak: string;
  gender: string;
  kategoriPeserta: string;
  waktuFinish: number;
  durasiMs: number;
  durasiStr: string;
  tahunEvent: number;
  isStravaVerified: boolean; // 🔥 TAMBAHAN UNTUK DETEKSI DATA STRAVA
}

export default function LeaderboardRacePage() {
  const [runners, setRunners] = useState<Runner[]>([]);
  const [distances, setDistances] = useState<string[]>(["5K", "10K"]);
  const [categories, setCategories] = useState<string[]>(["Umum"]);
  const [availableYears, setAvailableYears] = useState<number[]>([2026]);
  const [isLoading, setIsLoading] = useState(true);
  const [isPublished, setIsPublished] = useState(false);

  const [selectedYear, setSelectedYear] = useState<number>(2026);
  const [selectedDistance, setSelectedDistance] = useState<string>("");
  const [selectedGender, setSelectedGender] = useState<string>("L");
  const [selectedKategori, setSelectedKategori] = useState<string>("semua");

  const [currentPage, setCurrentPage] = useState(1);
  const itemsPerPage = 15;

  const [lastUpdate, setLastUpdate] = useState(new Date());

  useEffect(() => {
    const fetchSettings = async () => {
      try {
        const snap = await getDoc(doc(db, "settings", "virtual_run"));
        if (snap.exists()) {
          const data = snap.data();
          setIsPublished(data.showLeaderboard === true);
          let availDistances: string[] = [];
          if (data.offlinePackages && data.offlinePackages.length > 0) {
            availDistances = Array.from(
              new Set(data.offlinePackages.map((p: any) => p.jarak)),
            ) as string[];
          }
          if (availDistances.length > 0) {
            setDistances(availDistances);
            setSelectedDistance(availDistances[0]);
          }
        }
      } catch (err) {
        console.error("Gagal memuat konfigurasi admin:", err);
      }
    };
    fetchSettings();

    // 2. Sedot Data Realtime
    const q = query(
      collection(db, "offline_participants"),
      where("waktuFinish", ">", 0),
    );

    const unsub = onSnapshot(q, (snap) => {
      const yearsSet = new Set<number>([2026]);
      const categoriesSet = new Set<string>();

      const offlineData = snap.docs.map((document) => {
        const d = document.data();

        // 🔥 LOGIKA DURASI TETAP SAMA (Bisa baca dari Admin manual, bisa dari Strava)
        const durationMs =
          d.netTimeMs || d.waktuFinish - (d.waktuStart || d.waktuFinish);
        const thn = d.waktuFinish
          ? new Date(d.waktuFinish).getFullYear()
          : 2026;
        yearsSet.add(thn);

        const hours = Math.floor(durationMs / 3600000);
        const minutes = Math.floor((durationMs % 3600000) / 60000);
        const seconds = Math.floor((durationMs % 60000) / 1000);

        const durasiStr = [
          hours.toString().padStart(2, "0"),
          minutes.toString().padStart(2, "0"),
          seconds.toString().padStart(2, "0"),
        ].join(":");

        const kat = d.kategoriPeserta || "Umum";
        categoriesSet.add(kat);

        return {
          id: document.id,
          namaLengkap: d.namaLengkap || d.nama || "Unknown Runner",
          namaBib: d.namaBib || d.namaLengkap || "Runner",
          bibNumber: d.nomorBIB || d.bibNumber || "000",
          jarak: d.jarak || "5K",
          gender: d.jenisKelamin === "Perempuan" ? "P" : "L",
          kategoriPeserta: kat,
          waktuFinish: d.waktuFinish,
          durasiMs: durationMs,
          durasiStr: durasiStr,
          tahunEvent: thn,
          isStravaVerified: d.isStravaVerified || false, // 🔥 DETEKSI STATUS STRAVA
        };
      });

      setRunners(offlineData);
      setAvailableYears(Array.from(yearsSet).sort((a, b) => b - a));

      const detectedCategories = Array.from(categoriesSet).sort();
      if (detectedCategories.length > 0) {
        setCategories(detectedCategories);
      }

      setLastUpdate(new Date());
      setIsLoading(false);
    });

    return () => unsub();
  }, []);

  const filteredRunners = runners
    .filter(
      (r) =>
        r.tahunEvent === selectedYear &&
        r.jarak === selectedDistance &&
        r.gender === selectedGender &&
        (selectedKategori === "semua" ||
          r.kategoriPeserta === selectedKategori),
    )
    .sort((a, b) => a.durasiMs - b.durasiMs);

  const top3 = filteredRunners.slice(0, 3);
  const totalPages = Math.ceil(filteredRunners.length / itemsPerPage);
  const currentTableData = filteredRunners.slice(
    (currentPage - 1) * itemsPerPage,
    currentPage * itemsPerPage,
  );

  const getInitials = (name: string) => {
    return name
      .split(" ")
      .map((n) => n[0])
      .join("")
      .substring(0, 2)
      .toUpperCase();
  };

  const changeFilter = (setter: any, value: any) => {
    setter(value);
    setCurrentPage(1);
  };

  if (isLoading) {
    return (
      <div className="min-h-screen bg-[#0B2239] flex flex-col items-center justify-center">
        <div className="w-12 h-12 border-4 border-white/10 border-t-[#FCD116] rounded-full animate-spin mb-4"></div>
        <p className="text-white/70 text-xs uppercase font-bold tracking-widest animate-pulse">
          Menghubungkan Papan Klasemen...
        </p>
      </div>
    );
  }

  if (!isPublished) {
    return (
      <div className="min-h-screen bg-[#0B2239] flex flex-col items-center justify-center p-6 text-center">
        <div className="w-20 h-20 bg-white/10 rounded-full flex items-center justify-center mb-6 border border-white/20">
          <svg className="w-10 h-10 text-white/50" fill="none" viewBox="0 0 24 24" stroke="currentColor">
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 15v2m-6 4h12a2 2 0 002-2v-6a2 2 0 00-2-2H6a2 2 0 00-2 2v6a2 2 0 002 2zm10-10V7a4 4 0 00-8 0v4h8z" />
          </svg>
        </div>
        <h1 className="text-2xl md:text-3xl font-black text-white uppercase tracking-widest mb-4 leading-tight">
          Klasemen Belum <br/><span className="text-[#FCD116]">Dipublikasikan</span>
        </h1>
        <p className="text-white/60 text-sm md:text-base max-w-md font-medium leading-relaxed">
          Papan klasemen sedang dikunci oleh admin. Silakan kembali lagi nanti atau pantau informasi terbaru melalui panggung utama.
        </p>
        <Link href="/run" className="mt-8 bg-[#FCD116] hover:bg-yellow-500 text-[#0B2239] font-black px-8 py-3 rounded-full uppercase tracking-wider text-sm transition-all shadow-lg hover:shadow-xl hover:-translate-y-1">
          Kembali ke Event
        </Link>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-[#F8FAFC] font-sans pb-24 selection:bg-[#FCD116] selection:text-[#0B2239]">
      <div className="bg-white border-b border-slate-200 py-4 px-6 md:px-12 sticky top-0 z-40 shadow-sm flex justify-between items-center">
        <Link
          href="/run"
          className="text-slate-500 hover:text-[#0B2239] font-black text-xs uppercase tracking-wider flex items-center gap-2 transition-colors"
        >
          <svg
            className="w-4 h-4"
            fill="none"
            viewBox="0 0 24 24"
            stroke="currentColor"
            strokeWidth={2.5}
          >
            <path
              strokeLinecap="round"
              strokeLinejoin="round"
              d="M10 19l-7-7m0 0l7-7m-7 7h18"
            />
          </svg>
          Kembali ke Event
        </Link>

        <div className="flex items-center gap-2 bg-slate-100 border border-slate-200 px-3 py-1.5 rounded-xl shadow-sm">
          <label className="text-[10px] font-black uppercase text-slate-500 tracking-wider">
            Musim Tahun:
          </label>
          <select
            value={selectedYear}
            onChange={(e) =>
              changeFilter(setSelectedYear, Number(e.target.value))
            }
            className="bg-white text-sm font-black text-[#0B2239] focus:outline-none cursor-pointer rounded border border-slate-200 px-2 py-0.5"
          >
            {availableYears.map((y) => (
              <option key={y} value={y}>
                RUN {y}
              </option>
            ))}
          </select>
        </div>
      </div>

      <div className="max-w-6xl mx-auto px-4 sm:px-6 mt-12">
        <div className="text-center mb-10">
          <h1 className="text-3xl md:text-5xl font-black text-[#0B2239] tracking-tight uppercase mb-2">
            Leaderboard Running IKA UII DIY {selectedYear}
          </h1>
          <p className="text-slate-500 text-sm font-medium">
            Klasemen pelari resmi berwaktu tercepat • Diperbarui otomatis
          </p>
        </div>

        <div className="bg-white border border-slate-200 rounded-[2rem] p-6 shadow-xl mb-12 space-y-5">
          <div className="flex flex-col sm:flex-row items-center justify-between gap-4 border-b border-slate-100 pb-5">
            <div className="flex flex-wrap gap-2 justify-center sm:justify-start">
              <button
                onClick={() => changeFilter(setSelectedKategori, "semua")}
                className={`px-5 py-2 rounded-full text-xs font-black uppercase tracking-wider border transition-all ${selectedKategori === "semua" ? "bg-[#0B2239] border-[#0B2239] text-white shadow-md" : "bg-white text-slate-500 border-slate-200 hover:bg-slate-50"}`}
              >
                Semua Status
              </button>
              {categories.map((cat) => (
                <button
                  key={cat}
                  onClick={() => changeFilter(setSelectedKategori, cat)}
                  className={`px-5 py-2 rounded-full text-xs font-black uppercase tracking-wider border transition-all ${selectedKategori === cat ? "bg-[#0B2239] border-[#0B2239] text-[#FCD116] shadow-md" : "bg-white text-slate-500 border-slate-200 hover:bg-slate-50"}`}
                >
                  {cat === "SMA/Pelajar" ? "Pelajar" : cat}
                </button>
              ))}
            </div>

            <div className="flex items-center gap-2 bg-emerald-50 text-emerald-600 px-4 py-2 rounded-full border border-emerald-100 text-xs font-bold uppercase tracking-widest shrink-0">
              <span className="w-2.5 h-2.5 bg-emerald-500 rounded-full animate-pulse"></span>
              Live Syncing
            </div>
          </div>

          <div className="flex flex-col md:flex-row gap-4 items-center justify-between pt-1">
            <div className="flex flex-wrap gap-2">
              {distances.map((dist) => (
                <button
                  key={dist}
                  onClick={() => changeFilter(setSelectedDistance, dist)}
                  className={`px-6 py-2.5 rounded-xl text-xs font-black uppercase tracking-widest transition-all border ${
                    selectedDistance === dist
                      ? "bg-[#1A73E8] text-white border-[#1A73E8] shadow-md shadow-blue-500/10"
                      : "bg-slate-50 text-slate-500 border-slate-200 hover:bg-white hover:text-[#1A73E8]"
                  }`}
                >
                  {dist}
                </button>
              ))}
            </div>

            <div className="bg-slate-100 p-1 rounded-xl border border-slate-200 flex shrink-0">
              <button
                onClick={() => changeFilter(setSelectedGender, "L")}
                className={`px-6 py-2 rounded-lg text-xs font-black uppercase tracking-wider transition-all ${selectedGender === "L" ? "bg-white text-[#0B2239] shadow-sm font-black" : "text-slate-500 hover:text-slate-800"}`}
              >
                Pria (M)
              </button>
              <button
                onClick={() => changeFilter(setSelectedGender, "P")}
                className={`px-6 py-2 rounded-lg text-xs font-black uppercase tracking-wider transition-all ${selectedGender === "P" ? "bg-white text-rose-600 shadow-sm font-black" : "text-slate-500 hover:text-rose-600"}`}
              >
                Wanita (F)
              </button>
            </div>
          </div>
        </div>

        {filteredRunners.length === 0 ? (
          <div className="text-center py-20 bg-white rounded-[2rem] border border-slate-200 shadow-sm">
            <div className="text-5xl mb-4">🏁</div>
            <h3 className="text-lg font-bold text-[#0B2239] uppercase tracking-wide">
              Belum Ada Finisher
            </h3>
            <p className="text-slate-400 text-xs mt-1">
              Belum ada catatan waktu finish yang masuk untuk filter pencarian
              ini.
            </p>
          </div>
        ) : (
          <>
            <div className="flex flex-col md:flex-row items-stretch justify-center gap-4 md:gap-6 mb-12">
              {/* PODIUM 2 */}
              {top3[1] && (
                <div className="w-full md:w-64 bg-white rounded-3xl p-6 text-center border border-slate-200 shadow-sm flex flex-col justify-between relative order-2 md:order-1 mt-6 md:mt-0">
                  <div className="absolute -top-6 left-1/2 -translate-x-1/2 w-14 h-14 bg-slate-200 border-4 border-white rounded-full flex items-center justify-center text-slate-700 font-black text-sm shadow-md">
                    {getInitials(top3[1].namaBib)}
                  </div>
                  <span className="absolute top-4 right-4 text-xl">🥈</span>
                  <div className="mt-6 flex-grow flex flex-col justify-center">
                    <div className="flex items-center justify-center gap-1.5">
                      <h3 className="font-black text-[#0B2239] text-base uppercase tracking-tight line-clamp-1">
                        {top3[1].namaBib}
                      </h3>
                      {top3[1].isStravaVerified && (
                        <svg
                          className="w-4 h-4 text-[#FC4C02]"
                          viewBox="0 0 24 24"
                          fill="currentColor"
                        >
                          <path d="M15.387 17.944l-2.089-4.116h-3.065L15.387 24l5.15-10.172h-3.066m-7.008-5.599l2.836 5.598h4.172L10.463 0l-7 13.828h4.169" />
                        </svg>
                      )}
                    </div>
                    <p className="text-[9px] text-slate-400 font-bold uppercase tracking-widest mt-0.5">
                      BIB {top3[1].bibNumber}
                    </p>
                    <p className="text-[10px] text-slate-500 font-medium mt-1 uppercase">
                      {top3[1].kategoriPeserta}
                    </p>
                  </div>
                  <div className="mt-4 bg-slate-100 border border-slate-200 text-slate-700 font-black py-2 rounded-xl text-base font-mono">
                    {top3[1].durasiStr}
                  </div>
                </div>
              )}

              {/* PODIUM 1 */}
              {top3[0] && (
                <div className="w-full md:w-72 bg-[#0B2239] rounded-3xl p-6 text-center border-4 border-[#FCD116] shadow-2xl relative z-10 order-1 md:order-2 transform md:scale-105 flex flex-col justify-between">
                  <div className="absolute -top-8 left-1/2 -translate-x-1/2 w-16 h-16 bg-[#FCD116] border-4 border-[#0B2239] rounded-full flex items-center justify-center text-[#0B2239] font-black text-base shadow-xl">
                    {getInitials(top3[0].namaBib)}
                  </div>
                  <span className="absolute -top-6 left-1/2 -translate-x-1/2 text-2xl animate-bounce">
                    👑
                  </span>
                  <div className="mt-8 flex-grow flex flex-col justify-center">
                    <div className="flex items-center justify-center gap-1.5">
                      <h3 className="font-black text-[#FCD116] text-lg uppercase tracking-tight line-clamp-1">
                        {top3[0].namaBib}
                      </h3>
                      {top3[0].isStravaVerified && (
                        <svg
                          className="w-5 h-5 text-[#FC4C02] drop-shadow-md"
                          viewBox="0 0 24 24"
                          fill="currentColor"
                        >
                          <path d="M15.387 17.944l-2.089-4.116h-3.065L15.387 24l5.15-10.172h-3.066m-7.008-5.599l2.836 5.598h4.172L10.463 0l-7 13.828h4.169" />
                        </svg>
                      )}
                    </div>
                    <p className="text-[9px] text-slate-400 font-bold uppercase tracking-widest mt-0.5">
                      BIB {top3[0].bibNumber}
                    </p>
                    <p className="text-xs text-white/70 font-semibold mt-1 uppercase tracking-wider">
                      {top3[0].kategoriPeserta}
                    </p>
                  </div>
                  <div className="mt-5 bg-[#FCD116] text-[#0B2239] font-black py-2.5 rounded-xl text-lg font-mono shadow-md">
                    {top3[0].durasiStr}
                  </div>
                </div>
              )}

              {/* PODIUM 3 */}
              {top3[2] && (
                <div className="w-full md:w-64 bg-white rounded-3xl p-6 text-center border border-slate-200 shadow-sm flex flex-col justify-between relative order-3 md:order-3 mt-6 md:mt-0">
                  <div className="absolute -top-6 left-1/2 -translate-x-1/2 w-14 h-14 bg-amber-100 border-4 border-white rounded-full flex items-center justify-center text-amber-800 font-black text-sm shadow-md">
                    {getInitials(top3[2].namaBib)}
                  </div>
                  <span className="absolute top-4 right-4 text-xl">🥉</span>
                  <div className="mt-6 flex-grow flex flex-col justify-center">
                    <div className="flex items-center justify-center gap-1.5">
                      <h3 className="font-black text-[#0B2239] text-base uppercase tracking-tight line-clamp-1">
                        {top3[2].namaBib}
                      </h3>
                      {top3[2].isStravaVerified && (
                        <svg
                          className="w-4 h-4 text-[#FC4C02]"
                          viewBox="0 0 24 24"
                          fill="currentColor"
                        >
                          <path d="M15.387 17.944l-2.089-4.116h-3.065L15.387 24l5.15-10.172h-3.066m-7.008-5.599l2.836 5.598h4.172L10.463 0l-7 13.828h4.169" />
                        </svg>
                      )}
                    </div>
                    <p className="text-[9px] text-slate-400 font-bold uppercase tracking-widest mt-0.5">
                      BIB {top3[2].bibNumber}
                    </p>
                    <p className="text-[10px] text-slate-500 font-medium mt-1 uppercase">
                      {top3[2].kategoriPeserta}
                    </p>
                  </div>
                  <div className="mt-4 bg-slate-100 border border-slate-200 text-slate-700 font-black py-2 rounded-xl text-base font-mono">
                    {top3[2].durasiStr}
                  </div>
                </div>
              )}
            </div>

            <div className="bg-white rounded-[2rem] shadow-xl border border-slate-200 overflow-hidden">
              <div className="overflow-x-auto">
                <table className="w-full text-left border-collapse">
                  <thead>
                    <tr className="border-b border-slate-200 bg-slate-50 text-slate-400 text-[10px] font-black uppercase tracking-widest">
                      <th className="py-4 px-6 w-20 text-center">Rank</th>
                      <th className="py-4 px-6">Runner / Atlet</th>
                      <th className="py-4 px-6 w-28">BIB</th>
                      <th className="py-4 px-6">Klasifikasi</th>
                      <th className="py-4 px-6 text-right w-36">Net Time</th>
                    </tr>
                  </thead>
                  <tbody className="divide-y divide-slate-100">
                    {currentTableData.map((runner, idx) => {
                      const actualRank =
                        (currentPage - 1) * itemsPerPage + idx + 1;
                      let rankBadge = "bg-slate-100 text-slate-500 font-bold";
                      if (actualRank === 1)
                        rankBadge =
                          "bg-[#FCD116] text-[#0B2239] font-black shadow-inner";
                      else if (actualRank === 2)
                        rankBadge =
                          "bg-slate-300 text-slate-800 font-black shadow-inner";
                      else if (actualRank === 3)
                        rankBadge =
                          "bg-amber-600 text-white font-black shadow-inner";

                      return (
                        <tr
                          key={runner.id}
                          className="hover:bg-blue-50/30 transition-colors group"
                        >
                          <td className="py-4 px-6 text-center">
                            <div
                              className={`w-8 h-8 mx-auto rounded-full flex items-center justify-center text-xs ${rankBadge}`}
                            >
                              {actualRank}
                            </div>
                          </td>
                          <td className="py-4 px-6">
                            <div className="flex items-center gap-3">
                              <div className="w-8 h-8 rounded-full bg-slate-100 text-[#0B2239] border border-slate-200 font-black flex items-center justify-center text-[10px] shrink-0">
                                {getInitials(runner.namaBib)}
                              </div>
                              <div>
                                <div className="flex items-center gap-1.5">
                                  <span className="font-bold text-[#0B2239] text-sm group-hover:text-[#1A73E8] transition-colors block uppercase">
                                    {runner.namaLengkap}
                                  </span>
                                  {/* 🔥 BADGE STRAVA MUNCUL DI TABEL JUGA 🔥 */}
                                  {runner.isStravaVerified && (
                                    <span
                                      title="Strava Verified"
                                      className="bg-orange-50 text-[#FC4C02] rounded px-1 py-0.5"
                                    >
                                      <svg
                                        className="w-3 h-3"
                                        viewBox="0 0 24 24"
                                        fill="currentColor"
                                      >
                                        <path d="M15.387 17.944l-2.089-4.116h-3.065L15.387 24l5.15-10.172h-3.066m-7.008-5.599l2.836 5.598h4.172L10.463 0l-7 13.828h4.169" />
                                      </svg>
                                    </span>
                                  )}
                                </div>
                                <span className="text-[9px] font-black uppercase tracking-wider text-slate-400 mt-0.5 block">
                                  {runner.kategoriPeserta === "SMA/Pelajar"
                                    ? "Pelajar"
                                    : runner.kategoriPeserta}
                                </span>
                              </div>
                            </div>
                          </td>
                          <td className="py-4 px-6">
                            <span className="text-sm font-mono font-black text-slate-700 tracking-wider">
                              {runner.bibNumber}
                            </span>
                          </td>
                          <td className="py-4 px-6">
                            <span className="text-[9px] font-black text-slate-500 uppercase bg-slate-50 border border-slate-200 px-2.5 py-1 rounded-md">
                              {runner.jarak} •{" "}
                              {runner.gender === "L" ? "M" : "F"}
                            </span>
                          </td>
                          <td className="py-4 px-6 text-right font-mono font-black text-sm text-[#0B2239] tracking-wide">
                            {runner.durasiStr}
                          </td>
                        </tr>
                      );
                    })}
                  </tbody>
                </table>
              </div>

              {totalPages > 1 && (
                <div className="p-5 border-t border-slate-100 bg-slate-50 flex justify-between items-center">
                  <span className="text-xs font-bold text-slate-400 uppercase tracking-wider">
                    Halaman {currentPage} dari {totalPages}
                  </span>
                  <div className="flex gap-1.5">
                    <button
                      onClick={() => setCurrentPage((p) => Math.max(1, p - 1))}
                      disabled={currentPage === 1}
                      className="w-8 h-8 rounded-full bg-white border border-slate-200 flex items-center justify-center text-slate-500 hover:border-[#1A73E8] hover:text-[#1A73E8] disabled:opacity-40 disabled:cursor-not-allowed transition-all shadow-sm"
                    >
                      <svg
                        className="w-4 h-4"
                        fill="none"
                        viewBox="0 0 24 24"
                        stroke="currentColor"
                        strokeWidth={2.5}
                      >
                        <path
                          strokeLinecap="round"
                          strokeLinejoin="round"
                          d="M15 19l-7-7 7-7"
                        />
                      </svg>
                    </button>
                    <button
                      onClick={() =>
                        setCurrentPage((p) => Math.min(totalPages, p + 1))
                      }
                      disabled={currentPage === totalPages}
                      className="w-8 h-8 rounded-full bg-white border border-slate-200 flex items-center justify-center text-slate-500 hover:border-[#1A73E8] hover:text-[#1A73E8] disabled:opacity-40 disabled:cursor-not-allowed transition-all shadow-sm"
                    >
                      <svg
                        className="w-4 h-4"
                        fill="none"
                        viewBox="0 0 24 24"
                        stroke="currentColor"
                        strokeWidth={2.5}
                      >
                        <path
                          strokeLinecap="round"
                          strokeLinejoin="round"
                          d="M9 5l7 7-7 7"
                        />
                      </svg>
                    </button>
                  </div>
                </div>
              )}
            </div>
          </>
        )}
      </div>
    </div>
  );
}

"use client";

import { useState, useEffect, useMemo, useRef } from "react";
import { toast } from "@/lib/toast";
import { useParams, useRouter } from "next/navigation";
import { auth, db } from "@/lib/firebase";
import { onAuthStateChanged } from "firebase/auth";
import {
  doc,
  getDoc,
  collection,
  query,
  where,
  getDocs,
  addDoc,
  serverTimestamp,
} from "firebase/firestore";
import NavbarMasterclass from "@/components/layout/NavbarMasterclass";
import FooterPublic from "@/components/layout/FooterPublic";
import Link from "next/link";
import Script from "next/script";

export default function MasterclassPublicDetailPage() {
  const params = useParams();
  const router = useRouter();
  const courseId = params.id as string;

  const [currentUser, setCurrentUser] = useState<any>(null);
  const [accessStatus, setAccessStatus] = useState<
    "loading" | "tamu" | "belum_lunas" | "lunas_admin"
  >("loading");

  const [course, setCourse] = useState<any>(null);
  const [mentor, setMentor] = useState<any>(null);
  const [modules, setModules] = useState<any[]>([]);
  const [reviews, setReviews] = useState<any[]>([]);

  // 🔥 STATE CMS & PAYMENT GABUNGAN 🔥
  const [cms, setCms] = useState<any>(null);

  // 🔥 STATE UNTUK CHECKOUT MODAL 🔥
  const [isCheckoutOpen, setIsCheckoutOpen] = useState(false);
  const [inputPromo, setInputPromo] = useState("");
  const [discountAmount, setDiscountAmount] = useState(0);
  const [buktiBase64, setBuktiBase64] = useState<string | null>(null);
  const [isProcessingCheckout, setIsProcessingCheckout] = useState(false);

  // 🔥 STATE UNTUK ACCORDION SILABUS 🔥
  const [expandedBabs, setExpandedBabs] = useState<string[]>([]);

  // Modal Notifikasi Universal
  const [modalConfig, setModalConfig] = useState({
    isOpen: false,
    type: "success",
    title: "",
    message: "",
    actionText: "Tutup",
    actionLink: "",
  });

  const fileInputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    const unsubscribe = onAuthStateChanged(auth, async (user) => {
      setCurrentUser(user);
      await fetchAllDataAndCheckAccess(user);
    });
    return () => unsubscribe();
  }, [courseId]);

  const fetchAllDataAndCheckAccess = async (user: any) => {
    setAccessStatus("loading");
    try {
      const courseSnap = await getDoc(doc(db, "masterclass_courses", courseId));
      if (!courseSnap.exists()) {
        router.push("/masterclass");
        return;
      }
      const courseData: any = { id: courseSnap.id, ...courseSnap.data() };
      setCourse(courseData);

      const cmsSnap = await getDoc(doc(db, "settings", "masterclass_cms"));
      const paymentSnap = await getDoc(doc(db, "settings", "masterclass"));
      const vrSnap = await getDoc(doc(db, "settings", "virtual_run"));

      let combinedSettings = {};
      if (vrSnap.exists())
        combinedSettings = { ...combinedSettings, ...vrSnap.data() };
      if (paymentSnap.exists())
        combinedSettings = { ...combinedSettings, ...paymentSnap.data() };
      if (cmsSnap.exists())
        combinedSettings = { ...combinedSettings, ...cmsSnap.data() };

      setCms(combinedSettings);

      if (courseData.mentorId) {
        const mentorSnap = await getDoc(
          doc(db, "masterclass_mentors", courseData.mentorId),
        );
        if (mentorSnap.exists())
          setMentor({ id: mentorSnap.id, ...mentorSnap.data() });
      }

      const qModules = query(
        collection(db, "masterclass_modules"),
        where("courseId", "==", courseId),
      );
      const moduleSnaps = await getDocs(qModules);
      setModules(
        moduleSnaps.docs
          .map((d) => ({ id: d.id, ...d.data() }))
          .sort((a: any, b: any) => Number(a.urutan) - Number(b.urutan)),
      );

      const qReviews = query(
        collection(db, "masterclass_reviews"),
        where("courseId", "==", courseId),
      );
      const reviewSnaps = await getDocs(qReviews);
      setReviews(
        reviewSnaps.docs
          .map((d) => ({ id: d.id, ...d.data() }))
          .filter((r: any) => r.status !== "Sembunyi"),
      );

      if (user) {
        const userDoc = await getDoc(doc(db, "users", user.uid));
        const role = userDoc.exists() ? userDoc.data().role?.toLowerCase() : "";

        if (
          role === "admin" ||
          role === "super_admin" ||
          role === "superadmin"
        ) {
          setAccessStatus("lunas_admin");
        } else {
          const qEnroll = query(
            collection(db, "masterclass_enrollments"),
            where("courseId", "==", courseId),
            where("uid", "==", user.uid),
          );
          const snapEnroll = await getDocs(qEnroll);

          if (!snapEnroll.empty) {
            const status = snapEnroll.docs[0].data().statusAkses;
            setAccessStatus(status === "Lunas" ? "lunas_admin" : "belum_lunas");
          } else {
            setAccessStatus("tamu");
          }
        }
      } else {
        setAccessStatus("tamu");
      }
    } catch (error) {
      console.error("Gagal memuat detail:", error);
      setAccessStatus("tamu");
    }
  };

  // 🔥 LOGIKA PENGELOMPOKKAN BAB (SILABUS) 🔥
  const groupedModules = useMemo(() => {
    const groups: Record<string, any[]> = {};
    modules.forEach((mod) => {
      const bab = mod.bab || "Materi Pendahuluan";
      if (!groups[bab]) groups[bab] = [];
      groups[bab].push(mod);
    });
    return groups;
  }, [modules]);

  // Otomatis buka Bab pertama saat data diload
  useEffect(() => {
    const babs = Object.keys(groupedModules);
    if (babs.length > 0 && expandedBabs.length === 0) {
      setExpandedBabs([babs[0]]);
    }
  }, [groupedModules]);

  const toggleBab = (bab: string) => {
    setExpandedBabs((prev) =>
      prev.includes(bab) ? prev.filter((b) => b !== bab) : [...prev, bab],
    );
  };

  const processEnrollment = async (
    finalPrice: number,
    statusAkses: string,
    buktiUrl: string | null,
  ) => {
    setIsProcessingCheckout(true);
    try {
      await addDoc(collection(db, "masterclass_enrollments"), {
        courseId: courseId,
        uid: currentUser.uid,
        emailPeserta: currentUser.email,
        namaPeserta:
          currentUser.displayName ||
          currentUser.email?.split("@")[0] ||
          "Peserta",
        statusAkses: statusAkses,
        tipeHarga: course.tipeHarga,
        hargaTransaksi: finalPrice,
        buktiTransferUrl: buktiUrl,
        createdAt: serverTimestamp(),
        updatedAt: serverTimestamp(),
      });

      setIsCheckoutOpen(false);

      if (statusAkses === "Lunas") {
        setAccessStatus("lunas_admin");
        setModalConfig({
          isOpen: true,
          type: "success",
          title: "Pendaftaran Berhasil!",
          message: "Selamat! Anda sekarang memiliki akses penuh ke kelas ini.",
          actionText: "Masuk Ruang Belajar",
          actionLink: `/masterclass/${courseId}/learn`,
        });
      } else {
        setAccessStatus("belum_lunas");
        setModalConfig({
          isOpen: true,
          type: "success",
          title: "Pesanan Dicatat!",
          message:
            "Bukti pembayaran berhasil diunggah. Silakan tunggu Admin melakukan verifikasi.",
          actionText: "Lihat Status Kelas",
          actionLink: "/masterclass/my-courses",
        });
      }
    } catch (error) {
      setModalConfig({
        isOpen: true,
        type: "error",
        title: "Terjadi Kesalahan",
        message: "Sistem gagal memproses pendaftaran Anda. Coba lagi nanti.",
        actionText: "Tutup",
        actionLink: "",
      });
    } finally {
      setIsProcessingCheckout(false);
    }
  };

  const handleOpenCheckout = () => {
    if (!currentUser) {
      setModalConfig({
        isOpen: true,
        type: "warning",
        title: "Akses Ditolak",
        message: "Anda harus login terlebih dahulu untuk mendaftar kelas ini.",
        actionText: "Login / Daftar Sekarang",
        actionLink: "/login",
      });
      return;
    }
    if (course.tipeHarga === "Gratis") {
      processEnrollment(0, "Lunas", null);
      return;
    }
    setIsCheckoutOpen(true);
  };

  const handleApplyPromo = () => {
    if (!cms?.promoActive || !cms?.promoCode) {
      toast.warning("Saat ini tidak ada promo yang tersedia.");
      return;
    }
    if (inputPromo.toUpperCase() === cms.promoCode.toUpperCase()) {
      const disc = (course.totalHarga * cms.promoDiscount) / 100;
      setDiscountAmount(disc);
    } else {
      toast.warning("Kode voucher tidak valid atau sudah kedaluwarsa.");
      setDiscountAmount(0);
    }
  };

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    if (file.size > 800000) {
      toast.warning("Ukuran gambar terlalu besar! Maksimal 800KB.");
      return;
    }
    const reader = new FileReader();
    reader.onload = (event) => setBuktiBase64(event.target?.result as string);
    reader.readAsDataURL(file);
  };

  const handleSubmitCheckout = async () => {
    const finalPrice = course.totalHarga - discountAmount;
    if (
      (cms?.metodePembayaran === "manual" ||
        cms?.metodePembayaran === "qris") &&
      !buktiBase64
    ) {
      toast.warning("Harap unggah bukti pembayaran (struk transfer) terlebih dahulu.");
      return;
    }

    if (cms?.metodePembayaran === "midtrans") {
      if (!(window as any).snap) {
        toast.warning("Sistem pembayaran belum memuat sepenuhnya. Mohon pastikan API Key Midtrans sudah di-setting di Admin.");
        return;
      }
      setIsProcessingCheckout(true);
      try {
        const newEnrollmentRef = await addDoc(
          collection(db, "masterclass_enrollments"),
          {
            courseId: courseId,
            uid: currentUser.uid,
            emailPeserta: currentUser.email,
            namaPeserta:
              currentUser.displayName ||
              currentUser.email?.split("@")[0] ||
              "Peserta",
            statusAkses: "Pending",
            tipeHarga: course.tipeHarga,
            hargaTransaksi: finalPrice,
            buktiTransferUrl: null,
            createdAt: serverTimestamp(),
            updatedAt: serverTimestamp(),
          },
        );

        const res = await fetch("/api/midtrans-masterclass", {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({
            enrollmentId: newEnrollmentRef.id,
            grossAmount: finalPrice,
            customerName: currentUser.displayName || "Siswa IKA UII",
            customerEmail: currentUser.email,
          }),
        });

        const data = await res.json();
        if (data.token) {
          setIsCheckoutOpen(false);
          (window as any).snap.pay(data.token, {
            onSuccess: function () {
              router.push("/masterclass/my-courses");
            },
            onPending: function () {
              router.push("/masterclass/my-courses");
            },
            onError: function () {
              toast.error("Pembayaran gagal!");
            },
            onClose: function () {
              router.push("/masterclass/my-courses");
            },
          });
        } else {
          toast.error(`Gagal memuat pembayaran Midtrans: ${data.error}`);
        }
      } catch (error) {
        toast.error("Terjadi kesalahan sistem saat menghubungi Midtrans.");
      } finally {
        setIsProcessingCheckout(false);
      }
      return;
    }
    processEnrollment(finalPrice, "Pending", buktiBase64);
  };

  const handleModalAction = () => {
    if (modalConfig.actionLink) router.push(modalConfig.actionLink);
    else setModalConfig({ ...modalConfig, isOpen: false });
  };

  const averageRating = useMemo(() => {
    if (reviews.length === 0) return "5.0";
    const total = reviews.reduce(
      (acc, curr) => acc + Number(curr.rating || 0),
      0,
    );
    return (total / reviews.length).toFixed(1);
  }, [reviews]);

  if (accessStatus === "loading" || !course) {
    return (
      <div className="min-h-screen flex flex-col items-center justify-center bg-white font-sans">
        <div className="w-12 h-12 border-4 border-slate-200 border-t-[#0056D2] rounded-full animate-spin mb-4"></div>
        <p className="font-bold text-slate-500 text-sm">
          Memuat informasi kelas...
        </p>
      </div>
    );
  }

  const finalPrice = course.totalHarga - discountAmount;

  return (
    <div className="bg-white min-h-screen font-sans text-slate-800 flex flex-col relative">
      {/* SCRIPT MIDTRANS */}
      {cms &&
        cms.metodePembayaran === "midtrans" &&
        cms.midtransClientKey &&
        cms.midtransClientKey.trim() !== "" && (
          <Script
            src={
              cms.isProduction
                ? "https://app.midtrans.com/snap/snap.js"
                : "https://app.sandbox.midtrans.com/snap/snap.js"
            }
            data-client-key={cms.midtransClientKey}
            strategy="afterInteractive"
          />
        )}

      {/* MODAL CHECKOUT & PEMBAYARAN */}
      {isCheckoutOpen && (
        <div className="fixed inset-0 z-[100] flex justify-center items-end sm:items-center bg-slate-900/70 backdrop-blur-sm animate-in fade-in duration-300 sm:p-4">
          <div className="bg-white w-full max-w-4xl rounded-t-3xl sm:rounded-3xl shadow-2xl overflow-hidden flex flex-col md:flex-row max-h-[90vh] animate-in slide-in-from-bottom-10 sm:zoom-in-95">
            <div className="flex-1 bg-slate-50 p-6 md:p-8 overflow-y-auto border-r border-slate-200 custom-scrollbar">
              <div className="flex justify-between items-center mb-6">
                <h2 className="text-xl font-black text-slate-900">
                  Selesaikan Pembayaran
                </h2>
                <button
                  onClick={() => setIsCheckoutOpen(false)}
                  className="md:hidden w-8 h-8 bg-slate-200 rounded-full flex items-center justify-center text-slate-500 font-bold"
                >
                  ✕
                </button>
              </div>

              {cms?.metodePembayaran === "midtrans" ? (
                <div className="bg-blue-50 border border-blue-200 p-5 rounded-2xl">
                  <div className="w-12 h-12 bg-white rounded-xl mb-4 flex items-center justify-center shadow-sm">
                    💳
                  </div>
                  <h3 className="font-bold text-blue-900 mb-2">
                    Midtrans Gateway Active
                  </h3>
                  <p className="text-sm text-blue-700/80 leading-relaxed">
                    Anda akan diarahkan ke halaman pembayaran Midtrans yang aman
                    setelah menekan tombol konfirmasi.
                  </p>
                </div>
              ) : cms?.metodePembayaran === "qris" ? (
                <div className="space-y-5">
                  <div className="bg-purple-50 border border-purple-200 p-5 rounded-2xl text-center">
                    <h3 className="font-bold text-purple-900 mb-2">
                      Scan QRIS Berikut
                    </h3>
                    <p className="text-xs text-purple-700/80 mb-4">
                      Gunakan aplikasi M-Banking atau E-Wallet apa saja.
                    </p>
                    <img
                      src={cms.urlQris}
                      alt="QRIS"
                      className="w-48 h-48 mx-auto object-contain bg-white p-2 rounded-xl shadow-sm"
                    />
                  </div>
                </div>
              ) : (
                <div className="bg-amber-50 border border-amber-200 p-5 rounded-2xl">
                  <h3 className="font-bold text-amber-900 mb-4">
                    Transfer Bank Manual
                  </h3>
                  <div className="space-y-3 bg-white p-4 rounded-xl border border-amber-100 shadow-sm">
                    <div>
                      <p className="text-[10px] uppercase font-bold text-slate-400">
                        Bank Tujuan
                      </p>
                      <p className="font-black text-slate-800">
                        {cms?.manualBank || "Menunggu Setting Admin"}
                      </p>
                    </div>
                    <div>
                      <p className="text-[10px] uppercase font-bold text-slate-400">
                        Nomor Rekening
                      </p>
                      <div className="flex justify-between items-center">
                        <p className="font-mono font-black text-xl text-blue-600 tracking-wider">
                          {cms?.manualRekening}
                        </p>
                        <button
                          onClick={() => {
                            navigator.clipboard.writeText(cms?.manualRekening);
                            toast.success("Nomor rekening tersalin!");
                          }}
                          className="text-xs font-bold text-slate-400 hover:text-blue-600 border px-2 py-1 rounded bg-slate-50"
                        >
                          Copy
                        </button>
                      </div>
                    </div>
                    <div>
                      <p className="text-[10px] uppercase font-bold text-slate-400">
                        Atas Nama
                      </p>
                      <p className="font-bold text-slate-800">
                        {cms?.manualNama}
                      </p>
                    </div>
                  </div>
                </div>
              )}

              {cms?.metodePembayaran !== "midtrans" && (
                <div className="mt-6 border-t border-slate-200 pt-6">
                  <h3 className="font-bold text-slate-900 mb-3">
                    Upload Bukti Transfer
                  </h3>
                  {!buktiBase64 ? (
                    <div
                      onClick={() => fileInputRef.current?.click()}
                      className="border-2 border-dashed border-slate-300 hover:border-[#0056D2] hover:bg-blue-50 bg-white rounded-2xl p-6 text-center cursor-pointer transition-colors"
                    >
                      <input
                        type="file"
                        accept="image/*"
                        ref={fileInputRef}
                        onChange={handleFileChange}
                        className="hidden"
                      />
                      <svg
                        className="w-8 h-8 text-slate-400 mx-auto mb-2"
                        fill="none"
                        viewBox="0 0 24 24"
                        stroke="currentColor"
                      >
                        <path
                          strokeLinecap="round"
                          strokeLinejoin="round"
                          strokeWidth={2}
                          d="M4 16v1a3 3 0 003 3h10a3 3 0 003-3v-1m-4-8l-4-4m0 0L8 8m4-4v12"
                        />
                      </svg>
                      <p className="text-sm font-bold text-[#0056D2]">
                        Klik untuk Upload Foto Struk
                      </p>
                      <p className="text-[10px] text-slate-500 mt-1">
                        Maks. 800KB (JPG, PNG)
                      </p>
                    </div>
                  ) : (
                    <div className="relative rounded-2xl overflow-hidden border-2 border-[#0056D2] bg-white group">
                      <img
                        src={buktiBase64}
                        alt="Bukti Transfer"
                        className="w-full max-h-48 object-contain bg-slate-100"
                      />
                      <button
                        onClick={() => setBuktiBase64(null)}
                        className="absolute top-2 right-2 bg-rose-500 text-white text-xs font-bold px-3 py-1.5 rounded-lg opacity-0 group-hover:opacity-100 transition-opacity shadow-lg"
                      >
                        Ganti Foto
                      </button>
                    </div>
                  )}
                </div>
              )}
            </div>

            <div className="w-full md:w-[350px] bg-white p-6 md:p-8 flex flex-col shrink-0">
              <button
                onClick={() => setIsCheckoutOpen(false)}
                className="hidden md:flex self-end text-slate-400 hover:text-slate-600 font-bold text-sm mb-4"
              >
                ✕ Batal
              </button>
              <h3 className="font-bold text-slate-800 mb-4 border-b border-slate-100 pb-2">
                Ringkasan Pesanan
              </h3>
              <div className="flex gap-3 mb-6">
                <div className="w-16 h-12 bg-slate-100 rounded-lg overflow-hidden shrink-0 border border-slate-200">
                  {course.thumbnailUrl && (
                    <img
                      src={course.thumbnailUrl}
                      className="w-full h-full object-cover"
                      alt="cover"
                    />
                  )}
                </div>
                <div>
                  <p className="text-sm font-bold text-slate-800 line-clamp-2 leading-snug">
                    {course.judul}
                  </p>
                  <p className="text-[10px] text-slate-500 uppercase mt-0.5">
                    {course.kategori}
                  </p>
                </div>
              </div>
              <div className="mb-6">
                <label className="text-[10px] font-bold text-slate-500 uppercase tracking-widest block mb-2">
                  Kode Voucher (Opsional)
                </label>
                <div className="flex gap-2">
                  <input
                    type="text"
                    value={inputPromo}
                    onChange={(e) => setInputPromo(e.target.value)}
                    className="flex-1 border border-slate-300 px-3 py-2 rounded-lg text-sm font-bold uppercase tracking-wider outline-none focus:border-blue-500"
                    placeholder="KODE PROMO"
                  />
                  <button
                    onClick={handleApplyPromo}
                    className="bg-slate-800 text-white px-4 py-2 rounded-lg text-xs font-bold hover:bg-slate-700 transition-colors"
                  >
                    Terapkan
                  </button>
                </div>
                {discountAmount > 0 && (
                  <p className="text-xs text-emerald-600 font-bold mt-2">
                    ✓ Promo berhasil diterapkan!
                  </p>
                )}
              </div>
              <div className="space-y-3 border-t border-slate-100 pt-4 mb-6">
                <div className="flex justify-between text-sm text-slate-500 font-medium">
                  <span>Harga Normal</span>
                  <span>
                    Rp {(course.totalHarga || 0).toLocaleString("id-ID")}
                  </span>
                </div>
                {discountAmount > 0 && (
                  <div className="flex justify-between text-sm text-emerald-600 font-bold">
                    <span>Potongan Promo</span>
                    <span>- Rp {discountAmount.toLocaleString("id-ID")}</span>
                  </div>
                )}
                {course.pajak > 0 && (
                  <div className="flex justify-between text-xs text-slate-400">
                    <span>Sudah termasuk PPN {course.pajak}%</span>
                  </div>
                )}
                <div className="flex justify-between text-lg font-black text-slate-900 border-t border-slate-200 pt-3 mt-2">
                  <span>Total Bayar</span>
                  <span>Rp {finalPrice.toLocaleString("id-ID")}</span>
                </div>
              </div>
              <button
                onClick={handleSubmitCheckout}
                disabled={isProcessingCheckout}
                className="w-full mt-auto py-4 rounded-xl font-bold text-white bg-[#0056D2] hover:bg-[#00419E] shadow-lg shadow-blue-500/20 disabled:opacity-50 transition-all flex justify-center items-center gap-2"
              >
                {isProcessingCheckout ? (
                  <>
                    <div className="w-4 h-4 border-2 border-white/30 border-t-white rounded-full animate-spin"></div>{" "}
                    Memproses...
                  </>
                ) : (
                  "Konfirmasi Pembayaran"
                )}
              </button>
            </div>
          </div>
        </div>
      )}

      {/* MODAL NOTIFIKASI */}
      {modalConfig.isOpen && (
        <div className="fixed inset-0 z-[120] flex items-center justify-center p-4 bg-slate-900/60 backdrop-blur-sm animate-in fade-in duration-300">
          <div className="bg-white rounded-3xl shadow-2xl max-w-sm w-full p-8 text-center animate-in zoom-in-95 duration-300">
            <h3 className="text-2xl font-black text-slate-900 mb-2">
              {modalConfig.title}
            </h3>
            <p className="text-slate-500 text-sm leading-relaxed mb-8">
              {modalConfig.message}
            </p>
            <button
              onClick={handleModalAction}
              className="w-full py-4 rounded-xl font-bold text-sm text-white transition-all shadow-lg hover:-translate-y-0.5 bg-blue-600"
            >
              {modalConfig.actionText}
            </button>
          </div>
        </div>
      )}

      <NavbarMasterclass />

      <main className="flex-grow pt-30">
        {/* COURSERA HERO SECTION */}
        <section className="w-full bg-[#F5F7FA] overflow-hidden relative border-b border-slate-200">
          <div className="absolute top-0 right-0 w-[600px] h-full bg-gradient-to-l from-[#E8F0FE] to-transparent opacity-60 hidden lg:block pointer-events-none"></div>

          <div className="max-w-[1200px] mx-auto px-4 sm:px-6 lg:px-8 py-12 lg:py-20 relative z-10 flex flex-col lg:flex-row gap-12 items-center">
            {/* Kiri: Teks & Info */}
            <div className="flex-1 w-full text-center lg:text-left">
              <div className="flex items-center justify-center lg:justify-start gap-2 text-xs font-bold text-[#0056D2] uppercase tracking-wider mb-6">
                <Link href="/masterclass" className="hover:underline">
                  Katalog
                </Link>
                <span className="text-slate-400">/</span>
                <span>{course.kategori}</span>
              </div>
              <h1 className="text-3xl md:text-4xl lg:text-[44px] font-black text-[#1F2432] leading-[1.2] mb-6">
                {course.judul}
              </h1>
              <p className="text-slate-600 text-sm md:text-base leading-relaxed mb-8 max-w-2xl mx-auto lg:mx-0">
                {course.deskripsi?.substring(0, 180)}...
              </p>

              {mentor && (
                <div className="flex items-center justify-center lg:justify-start gap-3 mb-8">
                  <img
                    src={
                      mentor.fotoUrl ||
                      `https://ui-avatars.com/api/?name=${mentor.nama}`
                    }
                    alt={mentor.nama}
                    className="w-10 h-10 rounded-full object-cover border border-slate-200"
                  />
                  <div className="text-left">
                    <p className="text-xs text-slate-500 font-medium">
                      Instruktur Utama
                    </p>
                    <p className="text-sm font-bold text-[#0056D2]">
                      {mentor.nama}
                    </p>
                  </div>
                </div>
              )}

              {/* LOGIKA TOMBOL */}
              <div className="flex flex-col sm:flex-row items-center justify-center lg:justify-start gap-4">
                {accessStatus === "lunas_admin" ? (
                  <button
                    onClick={() =>
                      router.push(`/masterclass/${courseId}/learn`)
                    }
                    className="bg-[#1E8E3E] hover:bg-[#146C2E] text-white px-10 py-4 rounded-lg font-bold text-base transition-colors shadow-lg w-full sm:w-auto flex items-center justify-center gap-2"
                  >
                    Masuk Ruang Belajar
                  </button>
                ) : accessStatus === "belum_lunas" ? (
                  <div className="bg-[#FEF7E0] border border-[#FCE8B2] text-[#B06000] px-6 py-3.5 rounded-lg text-sm font-bold w-full sm:w-auto text-center flex items-center justify-center gap-2">
                    Menunggu Verifikasi Pembayaran
                  </div>
                ) : (
                  <button
                    onClick={handleOpenCheckout}
                    disabled={isProcessingCheckout}
                    className="bg-[#0056D2] hover:bg-[#00419E] text-white px-10 py-4 rounded-lg font-bold text-base transition-colors shadow-lg disabled:opacity-70 w-full sm:w-auto"
                  >
                    {isProcessingCheckout
                      ? "Memproses..."
                      : course.tipeHarga === "Gratis"
                        ? "Daftar Kelas Gratis"
                        : "Daftar & Bayar Sekarang"}
                  </button>
                )}
                {accessStatus !== "lunas_admin" && (
                  <div className="text-sm font-bold text-[#1F2432]">
                    {course.tipeHarga === "Gratis"
                      ? "Akses Penuh"
                      : `Rp ${(course.totalHarga || 0).toLocaleString("id-ID")}`}
                  </div>
                )}
              </div>
            </div>

            {/* Kanan: Cover Image */}
            <div className="w-full lg:w-[450px] shrink-0">
              <div className="rounded-2xl overflow-hidden shadow-2xl border border-slate-200 bg-white aspect-[4/3] relative">
                {course.thumbnailUrl ? (
                  <img
                    src={course.thumbnailUrl}
                    alt="Cover"
                    className="w-full h-full object-cover"
                  />
                ) : (
                  <div className="w-full h-full bg-slate-100 flex items-center justify-center text-slate-400 font-medium">
                    Cover Kelas
                  </div>
                )}
              </div>
            </div>
          </div>
        </section>

        {/* STATS BAR */}
        <section className="border-b border-slate-200 bg-white sticky top-[64px] z-30 shadow-sm hidden md:block">
          <div className="max-w-[1200px] mx-auto px-4 py-4 flex justify-between divide-x divide-slate-200">
            <div className="flex-1 text-center px-4">
              <div className="flex items-center justify-center gap-1 text-lg font-black text-[#1F2432]">
                <span className="text-[#F2D049]">★</span> {averageRating}
              </div>
              <p className="text-[10px] uppercase tracking-widest text-slate-500 font-bold mt-1">
                ({reviews.length} Ulasan)
              </p>
            </div>
            <div className="flex-1 text-center px-4">
              <h4 className="text-lg font-black text-[#1F2432]">
                {modules.length}
              </h4>
              <p className="text-[10px] uppercase tracking-widest text-slate-500 font-bold mt-1">
                Sesi Modul
              </p>
            </div>
            <div className="flex-1 text-center px-4">
              <h4 className="text-lg font-black text-[#1F2432]">Online</h4>
              <p className="text-[10px] uppercase tracking-widest text-slate-500 font-bold mt-1">
                100% Fleksibel
              </p>
            </div>
            <div className="flex-1 text-center px-4">
              <h4 className="text-lg font-black text-[#1F2432]">Sertifikat</h4>
              <p className="text-[10px] uppercase tracking-widest text-slate-500 font-bold mt-1">
                Dapat Dibagikan
              </p>
            </div>
          </div>
        </section>

        {/* KONTEN UTAMA */}
        <div className="max-w-[1000px] mx-auto px-4 sm:px-6 lg:px-8 py-16 space-y-20">
          <section>
            <h2 className="text-2xl font-bold text-[#1F2432] mb-6">
              Tentang kelas ini
            </h2>
            <div className="prose prose-slate max-w-none text-slate-600 text-[15px] leading-relaxed whitespace-pre-wrap">
              {course.deskripsi}
            </div>
          </section>

          {/* 🔥 SILABUS ACCORDION ALAA RUANGGURU 🔥 */}
          {Object.keys(groupedModules).length > 0 && (
            <section>
              <h2 className="text-2xl font-bold text-[#1F2432] mb-6">
                Kurikulum & Silabus Kelas
              </h2>
              <div className="space-y-4">
                {Object.keys(groupedModules).map((babName, bIdx) => (
                  <div
                    key={bIdx}
                    className="border border-slate-200 rounded-2xl overflow-hidden bg-white shadow-sm"
                  >
                    <button
                      onClick={() => toggleBab(babName)}
                      className="w-full bg-slate-50/50 hover:bg-slate-50 px-6 py-4 flex items-center justify-between transition-colors"
                    >
                      <div className="flex items-center gap-4 text-left">
                        <div
                          className={`w-8 h-8 rounded-full flex items-center justify-center transition-colors ${expandedBabs.includes(babName) ? "bg-[#0056D2] text-white" : "bg-blue-50 text-[#0056D2]"}`}
                        >
                          <span className="font-bold text-sm">{bIdx + 1}</span>
                        </div>
                        <div>
                          <h3 className="font-bold text-slate-800 text-[15px] sm:text-base">
                            {babName}
                          </h3>
                          <p className="text-[11px] text-slate-500 font-bold mt-0.5">
                            {groupedModules[babName].length} Topik Pembahasan
                          </p>
                        </div>
                      </div>
                      <div
                        className={`text-slate-400 transition-transform duration-300 ${expandedBabs.includes(babName) ? "rotate-180" : ""}`}
                      >
                        <svg
                          className="w-5 h-5"
                          fill="none"
                          viewBox="0 0 24 24"
                          stroke="currentColor"
                        >
                          <path
                            strokeLinecap="round"
                            strokeLinejoin="round"
                            strokeWidth={2.5}
                            d="M19 9l-7 7-7-7"
                          />
                        </svg>
                      </div>
                    </button>

                    {expandedBabs.includes(babName) && (
                      <div className="divide-y divide-slate-100 border-t border-slate-100">
                        {groupedModules[babName].map((mod, mIdx) => (
                          <div
                            key={mod.id}
                            className="p-5 flex items-start gap-4 hover:bg-slate-50/50 transition-colors pl-8 sm:pl-16"
                          >
                            <div className="mt-0.5 shrink-0">
                              {mod.tipe === "ujian" ? (
                                <div className="w-7 h-7 rounded-lg bg-rose-50 text-rose-500 flex items-center justify-center border border-rose-100">
                                  <svg
                                    className="w-3.5 h-3.5"
                                    fill="none"
                                    viewBox="0 0 24 24"
                                    stroke="currentColor"
                                  >
                                    <path
                                      strokeLinecap="round"
                                      strokeLinejoin="round"
                                      strokeWidth={2.5}
                                      d="M9 12h6m-6 4h6m2 5H7a2 2 0 01-2-2V5a2 2 0 012-2h5.586a1 1 0 01.707.293l5.414 5.414a1 1 0 01.293.707V19a2 2 0 01-2 2z"
                                    />
                                  </svg>
                                </div>
                              ) : mod.tipe === "pdf" ? (
                                <div className="w-7 h-7 rounded-lg bg-indigo-50 text-indigo-500 flex items-center justify-center border border-indigo-100">
                                  <svg
                                    className="w-3.5 h-3.5"
                                    fill="none"
                                    viewBox="0 0 24 24"
                                    stroke="currentColor"
                                  >
                                    <path
                                      strokeLinecap="round"
                                      strokeLinejoin="round"
                                      strokeWidth={2.5}
                                      d="M7 21h10a2 2 0 002-2V9.414a1 1 0 00-.293-.707l-5.414-5.414A1 1 0 0012.586 3H7a2 2 0 00-2 2v14a2 2 0 002 2z"
                                    />
                                  </svg>
                                </div>
                              ) : (
                                <div className="w-7 h-7 rounded-lg bg-emerald-50 text-emerald-500 flex items-center justify-center border border-emerald-100">
                                  <svg
                                    className="w-3.5 h-3.5"
                                    fill="none"
                                    viewBox="0 0 24 24"
                                    stroke="currentColor"
                                  >
                                    <path
                                      strokeLinecap="round"
                                      strokeLinejoin="round"
                                      strokeWidth={2.5}
                                      d="M14.752 11.168l-3.197-2.132A1 1 0 0010 9.87v4.263a1 1 0 001.555.832l3.197-2.132a1 1 0 000-1.664z"
                                    />
                                    <path
                                      strokeLinecap="round"
                                      strokeLinejoin="round"
                                      strokeWidth={2.5}
                                      d="M21 12a9 9 0 11-18 0 9 9 0 0118 0z"
                                    />
                                  </svg>
                                </div>
                              )}
                            </div>
                            <div>
                              <h4 className="font-bold text-slate-800 text-[14px] leading-snug">
                                {mod.judul}
                              </h4>
                              <div className="flex gap-2 text-[10px] font-bold uppercase tracking-widest text-slate-500 mt-2">
                                {mod.tipe === "ujian" ? (
                                  <span className="text-rose-600 bg-rose-50 px-2 py-0.5 rounded border border-rose-100">
                                    Durasi: {mod.durasiUjian || 15} Menit • KKM:{" "}
                                    {mod.kkm || 70}
                                  </span>
                                ) : mod.tipe === "pdf" ? (
                                  <span className="text-indigo-600 bg-indigo-50 px-2 py-0.5 rounded border border-indigo-100">
                                    Dokumen Materi
                                  </span>
                                ) : (
                                  <span className="text-emerald-600 bg-emerald-50 px-2 py-0.5 rounded border border-emerald-100">
                                    Video Pembelajaran
                                  </span>
                                )}
                              </div>
                            </div>
                          </div>
                        ))}
                      </div>
                    )}
                  </div>
                ))}
              </div>
            </section>
          )}

          {mentor && (
            <section>
              <h2 className="text-2xl font-bold text-[#1F2432] mb-6">
                Instruktur Pengajar
              </h2>
              <div className="flex flex-col sm:flex-row gap-6 items-start">
                <img
                  src={
                    mentor.fotoUrl ||
                    `https://ui-avatars.com/api/?name=${mentor.nama}`
                  }
                  alt={mentor.nama}
                  className={`w-32 h-32 rounded-full object-cover border border-slate-200 shrink-0 ${mentor.fotoPosition || "object-center"}`}
                />
                <div>
                  <h3 className="text-xl font-bold text-[#0056D2] mb-1">
                    {mentor.nama}, {mentor.gelar}
                  </h3>
                  <p className="text-sm font-bold text-slate-800 mb-3">
                    {mentor.jabatan} di {mentor.perusahaan}
                  </p>
                  <p className="text-sm text-slate-600 leading-relaxed max-w-2xl">
                    {mentor.bio}
                  </p>
                </div>
              </div>
            </section>
          )}

          {reviews.length > 0 && (
            <section>
              <h2 className="text-2xl font-bold text-[#1F2432] mb-6 flex items-center gap-2">
                <span className="text-[#F2D049]">★</span> {averageRating} Ulasan
                Peserta
              </h2>
              <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                {reviews.map((r) => (
                  <div
                    key={r.id}
                    className="bg-white p-6 border border-slate-200 rounded-xl shadow-sm"
                  >
                    <div className="flex gap-1 mb-3">
                      {[1, 2, 3, 4, 5].map((star) => (
                        <span
                          key={star}
                          className={`text-sm ${star <= Number(r.rating) ? "text-[#F2D049]" : "text-slate-200"}`}
                        >
                          ★
                        </span>
                      ))}
                    </div>
                    <p className="text-slate-700 text-sm italic mb-4 leading-relaxed line-clamp-4">
                      "{r.ulasan}"
                    </p>
                    <div className="flex items-center gap-3">
                      <div className="w-8 h-8 bg-slate-100 rounded-full flex items-center justify-center font-bold text-slate-500 text-xs">
                        {(r.namaPeserta || "A").charAt(0).toUpperCase()}
                      </div>
                      <div>
                        <p className="font-bold text-sm text-[#1F2432]">
                          {r.namaPeserta}
                        </p>
                        <p className="text-[10px] text-slate-500 uppercase">
                          {r.tanggal || "Alumni"}
                        </p>
                      </div>
                    </div>
                  </div>
                ))}
              </div>
            </section>
          )}
        </div>
      </main>
      <FooterPublic />
    </div>
  );
}

"use client";

import { useState, useEffect } from "react";
import { toast } from "@/lib/toast";
import { useParams, useRouter } from "next/navigation";
import { auth, db } from "@/lib/firebase";
import { onAuthStateChanged } from "firebase/auth";
import { sendEmailAction } from "@/app/actions/email";

import {
  doc,
  getDoc,
  collection,
  query,
  where,
  getDocs,
} from "firebase/firestore";

export default function CertificatePage() {
  const params = useParams();
  const router = useRouter();
  const courseId = params.id as string;

  const [currentUser, setCurrentUser] = useState<any>(null);
  const [course, setCourse] = useState<any>(null);
  const [mentor, setMentor] = useState<any>(null);
  const [modules, setModules] = useState<any[]>([]);
  const [completionDate, setCompletionDate] = useState<Date | null>(null);
  const [totalDuration, setTotalDuration] = useState({ hours: 0, mins: 0 });
  const [isLoading, setIsLoading] = useState(true);
  const [isValid, setIsValid] = useState(false);

  // 🔥 STATE UNTUK KIRIM EMAIL & MODAL SUKSES 🔥
  const [isSendingEmail, setIsSendingEmail] = useState(false);
  const [showSuccessModal, setShowSuccessModal] = useState(false);

  useEffect(() => {
    const unsubscribe = onAuthStateChanged(auth, async (user) => {
      if (!user) return router.push("/login");
      setCurrentUser(user);
      await verifyAndFetchCertificate(user);
    });
    return () => unsubscribe();
  }, [courseId, router]);

  const verifyAndFetchCertificate = async (user: any) => {
    setIsLoading(true);
    try {
      // 1. Cek Data Kelas
      const cDoc = await getDoc(doc(db, "masterclass_courses", courseId));
      if (!cDoc.exists()) throw new Error("Kelas tidak ditemukan");
      const cData = cDoc.data();
      setCourse(cData);

      // 2. Cek Data Mentor (dan ambil TTD asli)
      if (cData.mentorId) {
        const mDoc = await getDoc(
          doc(db, "masterclass_mentors", cData.mentorId),
        );
        if (mDoc.exists()) setMentor(mDoc.data());
      }

      // 3. Tarik Data Modul (Untuk Lampiran Silabus Transkrip)
      const qMod = query(
        collection(db, "masterclass_modules"),
        where("courseId", "==", courseId),
      );
      const modSnap = await getDocs(qMod);
      const fetchedModules = modSnap.docs
        .map((d) => ({ id: d.id, ...d.data() }))
        .sort((a: any, b: any) => Number(a.urutan) - Number(b.urutan));

      // 4. Validasi Kelulusan (Progress harus 100%)
      const progDoc = await getDoc(
        doc(db, "masterclass_progress", `${user.uid}_${courseId}`),
      );
      if (!progDoc.exists()) throw new Error("Belum ada progress");

      const progData = progDoc.data();
      const completedArray = progData.completedModules || [];
      const scoresMap = progData.scores || {};

      const totalModules = fetchedModules.length;

      // Filter modul gaib
      const validCompletedCount = completedArray.filter((id: string) =>
        modSnap.docs.some((m) => m.id === id),
      ).length;

      if (totalModules === 0 || validCompletedCount < totalModules) {
        toast.warning("Sertifikat terkunci! Anda belum menyelesaikan semua modul.");
        return router.push(`/masterclass/${courseId}/learn`);
      }

      // 5. Kalkulasi Durasi & Pemrosesan Data Transkrip
      let totalMinutes = 0;
      const processedModules = fetchedModules.map((mod: any) => {
        const durasi = Number(mod.durasi) || Number(mod.durasiUjian) || 15;
        totalMinutes += durasi;

        let nilai = "-";
        let status = "Selesai";

        if (mod.tipe === "ujian") {
          nilai = scoresMap[mod.id]
            ? `${scoresMap[mod.id]}`
            : `Lulus (KKM: ${mod.kkm || 70})`;
          status = "Lulus";
        }

        return { ...mod, durasi, nilai, status };
      });

      const hours = Math.floor(totalMinutes / 60);
      const mins = totalMinutes % 60;
      setTotalDuration({ hours, mins });
      setModules(processedModules);

      // 6. Set Tanggal Kelulusan
      const finishedDate = progData.lastUpdated?.toDate() || new Date();
      setCompletionDate(finishedDate);
      setIsValid(true);
    } catch (error) {
      console.error(error);
      router.push(`/masterclass/${courseId}/learn`);
    } finally {
      setIsLoading(false);
    }
  };

  // Generate Nomor & Link Validasi Sertifikat Unik
  const certNumber = currentUser
    ? `MC-IKA-${currentUser.uid.substring(0, 5).toUpperCase()}-${courseId.substring(0, 5).toUpperCase()}`
    : "";
  const validationUrl = `https://ikadiy.uii.ac.id/verify/${certNumber}`;
  const qrCodeUrl = `https://api.qrserver.com/v1/create-qr-code/?size=150x150&data=${encodeURIComponent(validationUrl)}`;
  const ttdImage =
    mentor?.ttdUrl || mentor?.ttd || mentor?.signatureUrl || mentor?.signature;

  // 🔥 FUNGSI KIRIM EMAIL 🔥
  const handleSendEmail = async () => {
    if (!currentUser || !course) return;

    setIsSendingEmail(true);
    try {
      // Data yang akan dikirim ke endpoint API
      const payload = {
        type: "masterclass_certificate",
        email: currentUser.email,
        nama: currentUser.displayName || currentUser.email.split("@")[0],
        detail: {
          judulKelas: course.judul,
          nomorSertifikat: certNumber,
          tanggalLulus: completionDate?.toLocaleDateString("id-ID", {
            day: "numeric",
            month: "long",
            year: "numeric",
          }),
          linkValidasi: validationUrl,
        },
      };

      const response = await sendEmailAction(payload);

      if (response.success) {
        // 🔥 GANTI ALERT DENGAN MODAL SUKSES 🔥
        setShowSuccessModal(true);
      } else {
        toast.error("Gagal mengirim email. Silakan coba lagi nanti.");
      }
    } catch (error) {
      console.error("Error saat mengirim email:", error);
      toast.error("Terjadi kesalahan sistem saat mencoba mengirim email.");
    } finally {
      setIsSendingEmail(false);
    }
  };

  const handlePrint = () => {
    window.print();
  };

  if (isLoading || !isValid) {
    return (
      <div className="min-h-screen flex flex-col items-center justify-center bg-slate-900 font-sans">
        <div className="w-12 h-12 border-4 border-slate-700 border-t-amber-500 rounded-full animate-spin mb-4"></div>
        <p className="font-bold text-slate-400 text-sm tracking-widest uppercase">
          Mempersiapkan Dokumen Resmi...
        </p>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-slate-100 flex flex-col items-center py-10 font-sans print:p-0 print:bg-white overflow-x-hidden relative">
      {/* 🔥 MODAL SUKSES ELEGAN 🔥 */}
      {showSuccessModal && (
        <div className="fixed inset-0 z-[120] flex items-center justify-center p-4 bg-slate-900/60 backdrop-blur-sm animate-in fade-in duration-300">
          <div className="bg-white rounded-3xl shadow-2xl max-w-sm w-full p-8 text-center animate-in zoom-in-95 duration-300">
            <div className="w-20 h-20 bg-emerald-100 text-emerald-500 rounded-full flex items-center justify-center mx-auto mb-5">
              <svg
                className="w-10 h-10"
                fill="none"
                viewBox="0 0 24 24"
                stroke="currentColor"
              >
                <path
                  strokeLinecap="round"
                  strokeLinejoin="round"
                  strokeWidth={3}
                  d="M5 13l4 4L19 7"
                />
              </svg>
            </div>
            <h3 className="text-2xl font-black text-slate-900 mb-2">
              Berhasil!
            </h3>
            <p className="text-slate-500 text-sm leading-relaxed mb-8">
              Pemberitahuan kelulusan dan tautan E-Certificate telah dikirimkan
              ke email Anda <strong>({currentUser?.email})</strong>. Silakan cek
              kotak masuk atau folder spam Anda.
            </p>
            <button
              onClick={() => setShowSuccessModal(false)}
              className="w-full py-3.5 rounded-xl font-bold text-sm text-white bg-[#0056D2] hover:bg-[#00419E] transition-colors shadow-lg"
            >
              Tutup & Kembali
            </button>
          </div>
        </div>
      )}

      {/* TOMBOL AKSI */}
      <div className="mb-8 flex gap-4 print:hidden z-50">
        <button
          onClick={() => router.back()}
          className="px-6 py-3 bg-white text-slate-700 font-bold rounded-xl shadow-sm border border-slate-200 hover:bg-slate-50 transition-colors flex items-center gap-2"
        >
          <svg
            className="w-5 h-5"
            fill="none"
            viewBox="0 0 24 24"
            stroke="currentColor"
          >
            <path
              strokeLinecap="round"
              strokeLinejoin="round"
              strokeWidth={2.5}
              d="M10 19l-7-7m0 0l7-7m-7 7h18"
            />
          </svg>
          Kembali ke Ruang Belajar
        </button>

        {/* Tombol Native Print/Save as PDF */}
        <button
          onClick={handlePrint}
          className="px-6 py-3 bg-white text-slate-700 font-bold rounded-xl shadow-sm border border-slate-200 hover:bg-slate-50 transition-colors hidden md:flex items-center gap-2"
        >
          <svg
            className="w-5 h-5"
            fill="none"
            viewBox="0 0 24 24"
            stroke="currentColor"
          >
            <path
              strokeLinecap="round"
              strokeLinejoin="round"
              strokeWidth={2}
              d="M17 17h2a2 2 0 002-2v-4a2 2 0 00-2-2H5a2 2 0 00-2 2v4a2 2 0 002 2h2m2 4h6a2 2 0 002-2v-4a2 2 0 00-2-2H9a2 2 0 00-2 2v4a2 2 0 002 2zm8-12V5a2 2 0 00-2-2H9a2 2 0 00-2 2v4h10z"
            />
          </svg>
          Cetak Manual / Unduh
        </button>

        {/* 🔥 TOMBOL KIRIM EMAIL 🔥 */}
        <button
          onClick={handleSendEmail}
          disabled={isSendingEmail}
          className="px-8 py-3 bg-[#0056D2] hover:bg-[#00419E] text-white font-black rounded-xl shadow-lg shadow-blue-500/30 transition-all flex items-center gap-2 disabled:opacity-70"
        >
          {isSendingEmail ? (
            <svg
              className="w-5 h-5 animate-spin"
              fill="none"
              viewBox="0 0 24 24"
            >
              <circle
                className="opacity-25"
                cx="12"
                cy="12"
                r="10"
                stroke="currentColor"
                strokeWidth="4"
              ></circle>
              <path
                className="opacity-75"
                fill="currentColor"
                d="M4 12a8 8 0 018-8v8H4z"
              ></path>
            </svg>
          ) : (
            <svg
              className="w-5 h-5"
              fill="none"
              viewBox="0 0 24 24"
              stroke="currentColor"
            >
              <path
                strokeLinecap="round"
                strokeLinejoin="round"
                strokeWidth={2.5}
                d="M3 8l7.89 5.26a2 2 0 002.22 0L21 8M5 19h14a2 2 0 002-2V7a2 2 0 00-2-2H5a2 2 0 00-2 2v10a2 2 0 002 2z"
              />
            </svg>
          )}
          {isSendingEmail
            ? "MENGIRIM EMAIL..."
            : "KIRIM E-CERTIFICATE KE EMAIL"}
        </button>
      </div>

      {/* PREVIEW SERTIFIKAT DI LAYAR */}
      <div className="certificate-wrapper flex flex-col gap-10 print:gap-0 print:block pointer-events-none select-none">
        {/* ========================================== */}
        {/* HALAMAN 1: SERTIFIKAT UTAMA                */}
        {/* ========================================== */}
        <div className="certificate-page w-[1122px] h-[793px] bg-white relative shadow-2xl overflow-hidden print:shadow-none mx-auto shrink-0 flex flex-col justify-center items-center text-center">
          {/* DESAIN BACKGROUND & WATERMARK TIPIS */}
          <div className="absolute inset-0">
            <div className="absolute inset-4 border-[10px] border-double border-amber-200 opacity-50"></div>
            <div className="absolute inset-6 border-2 border-amber-400 opacity-20"></div>
            <div className="absolute top-0 left-0 w-64 h-64 bg-gradient-to-br from-[#0B1528] to-[#1A73E8] -translate-x-32 -translate-y-32 rotate-45"></div>
            <div className="absolute bottom-0 right-0 w-64 h-64 bg-gradient-to-tl from-amber-400 to-amber-600 -translate-x-[-128px] -translate-y-[-128px] rotate-45"></div>

            <div
              className="absolute inset-0 flex items-center justify-center"
              style={{ opacity: 0.02 }}
            >
              <img
                src="/logo-dpp-ika.png"
                alt="Watermark"
                className="w-[500px] h-[500px] object-contain grayscale"
              />
            </div>
          </div>

          <div className="relative z-10 w-full px-32 flex flex-col items-center">
            <div className="flex items-center justify-center gap-6 mb-10">
              <img
                src="/logo-dpp-ika.png"
                alt="Logo IKA UII"
                className="h-20 object-contain"
              />
              <div className="h-16 w-px bg-slate-300"></div>
              <div className="text-left">
                <h2 className="font-black text-2xl text-[#0B1528] tracking-widest uppercase">
                  MASTERCLASS
                </h2>
                <p className="font-bold text-sm text-slate-500 tracking-[0.2em] uppercase">
                  Ikatan Keluarga Alumni UII DIY
                </p>
              </div>
            </div>

            <h1 className="text-6xl font-black text-[#0B1528] tracking-widest uppercase mb-4 font-serif">
              Certificate
            </h1>
            <p className="text-xl tracking-[0.3em] text-amber-600 font-bold uppercase mb-12">
              Of Completion
            </p>

            <p className="text-slate-500 font-medium italic text-lg mb-4">
              Sertifikat ini diberikan dengan bangga kepada:
            </p>
            <h2 className="text-5xl font-black text-[#103575] mb-6 capitalize leading-tight border-b-2 border-slate-200 pb-4 px-16 inline-block">
              {currentUser?.displayName || currentUser?.email?.split("@")[0]}
            </h2>
            <p className="text-slate-600 text-lg max-w-3xl leading-relaxed mb-16">
              Atas keberhasilannya menyelesaikan seluruh materi kurikulum dan
              lulus evaluasi pada program Masterclass{" "}
              <strong>"{course?.judul}"</strong>.
            </p>

            <div className="flex justify-between items-end w-full px-12 mt-auto">
              <div className="text-left flex items-end gap-5">
                <img
                  src={qrCodeUrl}
                  alt="QR Code"
                  className="w-20 h-20 rounded-lg border-2 border-slate-200 p-1 bg-white shadow-sm"
                />
                <div className="pb-1">
                  <p className="font-bold text-slate-800 text-lg border-b border-slate-400 pb-1 mb-1">
                    {completionDate?.toLocaleDateString("id-ID", {
                      day: "numeric",
                      month: "long",
                      year: "numeric",
                    })}
                  </p>
                  <p className="text-xs text-slate-500 font-bold uppercase tracking-widest mb-1">
                    Tanggal Lulus
                  </p>
                  <p className="text-[9px] text-slate-400 font-mono tracking-wider">
                    ID: {certNumber}
                  </p>
                </div>
              </div>

              <div className="text-center w-70 pb-1 flex flex-col items-center">
                <div className="h-29 flex items-end justify-center mb-0.1 w-full">
                  {ttdImage ? (
                    <img
                      src={ttdImage}
                      alt="Tanda Tangan Mentor"
                      className="max-h-full max-w-full object-contain mix-blend-multiply"
                    />
                  ) : (
                    <span className="font-serif text-4xl text-slate-800 italic opacity-80">
                      {mentor?.nama?.split(" ")[0] || "DPW"}
                    </span>
                  )}
                </div>
                <p className="font-bold text-slate-800 text-sm border-t border-slate-400 pt-2 w-full">
                  {mentor?.nama || "Pengurus DPW IKA UII DIY"}
                </p>
                <p className="text-[10px] text-slate-500 font-bold uppercase tracking-widest mt-1">
                  Instruktur Utama
                </p>
              </div>
            </div>
          </div>
        </div>

        {/* ========================================== */}
        {/* HALAMAN 2: TRANSKRIP & SILABUS             */}
        {/* ========================================== */}
        <div className="certificate-page w-[1122px] h-[793px] bg-white relative shadow-2xl overflow-hidden print:shadow-none mx-auto shrink-0 flex flex-col p-16">
          <div className="absolute inset-0">
            <div
              className="absolute inset-0 flex items-center justify-center"
              style={{ opacity: 0.02 }}
            >
              <img
                src="/logo-dpp-ika.png"
                alt="Watermark"
                className="w-[450px] h-[450px] object-contain grayscale"
              />
            </div>
          </div>

          <div className="relative z-10 w-full h-full flex flex-col">
            <div className="flex justify-between items-end border-b-[3px] border-[#0B1528] pb-6 mb-8">
              <div>
                <h2 className="text-3xl font-black text-[#0B1528] tracking-widest uppercase mb-2">
                  Transkrip Pelatihan
                </h2>
                <p className="text-sm font-bold text-slate-600 uppercase tracking-widest">
                  Masterclass IKA UII DIY - {course?.judul}
                </p>
              </div>
              <div className="text-right">
                <p className="text-[10px] font-bold text-slate-500 uppercase tracking-widest mb-1">
                  Diberikan Kepada
                </p>
                <p className="font-black text-[#0B1528] text-lg uppercase">
                  {currentUser?.displayName ||
                    currentUser?.email?.split("@")[0]}
                </p>
                <p className="text-xs text-slate-500 font-mono mt-1">
                  Ref ID: {certNumber}
                </p>
              </div>
            </div>

            <div className="flex-1 overflow-hidden">
              <table className="w-full text-left border-collapse border border-[#0B1528]">
                <thead>
                  <tr className="bg-slate-100 text-[#0B1528] tracking-widest text-[11px] font-bold uppercase border-b-2 border-[#0B1528]">
                    <th className="p-3 border-r border-[#0B1528] w-12 text-center">
                      No
                    </th>
                    <th className="p-3 border-r border-[#0B1528]">
                      Kurikulum & Materi
                    </th>
                    <th className="p-3 border-r border-[#0B1528] w-32 text-center">
                      Tipe Materi
                    </th>
                    <th className="p-3 border-r border-[#0B1528] w-24 text-center">
                      Durasi
                    </th>
                    <th className="p-3 w-40 text-center">Nilai / Status</th>
                  </tr>
                </thead>
                <tbody className="text-slate-800 text-sm font-medium">
                  {modules.map((mod, idx) => (
                    <tr key={idx} className="border-b border-slate-400">
                      <td className="p-3 border-r border-[#0B1528] text-center font-bold">
                        {idx + 1}
                      </td>
                      <td className="p-3 border-r border-[#0B1528]">
                        <p className="font-bold text-slate-900">
                          {mod.bab || "Materi Pelatihan"}
                        </p>
                        <p className="text-xs text-slate-600 mt-0.5">
                          {mod.judul}
                        </p>
                      </td>
                      <td className="p-3 border-r border-[#0B1528] text-center text-[11px] uppercase tracking-wider font-bold text-slate-600">
                        {mod.tipe === "ujian"
                          ? "Evaluasi"
                          : mod.tipe === "pdf"
                            ? "Dokumen PDF"
                            : "Video"}
                      </td>
                      <td className="p-3 border-r border-[#0B1528] text-center text-sm">
                        {mod.durasi} Menit
                      </td>
                      <td className="p-3 text-center font-black text-slate-800 text-xs">
                        {mod.nilai}
                      </td>
                    </tr>
                  ))}
                  <tr className="bg-slate-100 border-t-2 border-[#0B1528]">
                    <td
                      colSpan={3}
                      className="p-3 border-r border-[#0B1528] text-right font-black uppercase tracking-widest text-xs"
                    >
                      Total Jam Pelatihan
                    </td>
                    <td
                      colSpan={2}
                      className="p-3 text-center font-black text-slate-900 text-sm"
                    >
                      {totalDuration.hours > 0 && `${totalDuration.hours} Jam `}
                      {totalDuration.mins} Menit
                    </td>
                  </tr>
                </tbody>
              </table>
            </div>

            <div className="border-t border-slate-300 pt-6 mt-6 flex justify-between items-end">
              <div className="text-xs text-slate-600 font-medium leading-relaxed">
                <p className="font-bold text-slate-800 mb-1">
                  Pernyataan Validitas:
                </p>
                <p>
                  Transkrip ini diterbitkan secara otomatis oleh Sistem
                  Pembelajaran Masterclass IKA UII DIY.
                </p>
                <p>
                  Dokumen ini sah dan dapat diverifikasi melalui pemindaian QR
                  Code pada Halaman 1.
                </p>
              </div>
              <div className="text-right">
                <p className="text-[10px] uppercase font-bold text-slate-500 tracking-widest mb-1">
                  URL Verifikasi Digital
                </p>
                <p className="font-mono text-xs font-bold text-[#0B1528]">
                  {validationUrl}
                </p>
              </div>
            </div>
          </div>
        </div>
      </div>

      <style jsx global>{`
        /* SCALING DI LAYAR MONITOR/HP BIAR PAS & RAPI */
        @media screen and (max-width: 1300px) {
