            transform: scale(0.85);
            transform-origin: top center;
            margin-bottom: -150px;
          }
        }
        @media screen and (max-width: 1000px) {
          .certificate-wrapper {
            transform: scale(0.65);
            transform-origin: top center;
            margin-bottom: -350px;
          }
        }
        @media screen and (max-width: 600px) {
          .certificate-wrapper {
            transform: scale(0.33);
            transform-origin: top center;
            margin-bottom: -1000px;
          }
        }
        @media print {
          @page {
            size: A4 landscape;
            margin: 0;
          }
          body {
            -webkit-print-color-adjust: exact !important;
            print-color-adjust: exact !important;
            background: white !important;
          }
          .certificate-wrapper {
            gap: 0 !important;
          }
          .certificate-page {
            width: 100% !important;
            height: 100vh !important;
            box-shadow: none !important;
            transform: scale(1) !important;
            page-break-after: always; /* KUNCI POTONG KERTAS */
          }
        }
      `}</style>
    </div>
  );
}

"use client";

import { useState, useEffect, useCallback } from "react";
import { toast } from "@/lib/toast";
import { useParams, useRouter } from "next/navigation";
import { auth, db } from "@/lib/firebase";
import { onAuthStateChanged } from "firebase/auth";
import {
  doc,
  getDoc,
  setDoc,
  updateDoc,
  arrayUnion,
  serverTimestamp,
} from "firebase/firestore";

export default function ExamPage() {
  const params = useParams();
  const router = useRouter();
  const courseId = params.id as string;
  const moduleId = params.moduleId as string;

  const [currentUser, setCurrentUser] = useState<any>(null);
  const [isLoading, setIsLoading] = useState(true);

  // Data Ujian
  const [moduleData, setModuleData] = useState<any>(null);
  const [courseData, setCourseData] = useState<any>(null);

  // State Ujian
  const [answers, setAnswers] = useState<Record<number, string>>({});
  const [timeLeft, setTimeLeft] = useState<number>(0);
  const [isStarted, setIsStarted] = useState(false);
  const [isSubmitted, setIsSubmitted] = useState(false);

  // Hasil
  const [score, setScore] = useState(0);
  const [isPassed, setIsPassed] = useState(false);
  const [isSaving, setIsSaving] = useState(false);

  useEffect(() => {
    const unsubscribe = onAuthStateChanged(auth, async (user) => {
      if (!user) return router.push("/login");
      setCurrentUser(user);
      await fetchExamData(user);
    });
    return () => unsubscribe();
  }, [courseId, moduleId, router]);

  const fetchExamData = async (user: any) => {
    setIsLoading(true);
    try {
      // 1. Ambil Info Kelas
      const cDoc = await getDoc(doc(db, "masterclass_courses", courseId));
      if (cDoc.exists()) setCourseData(cDoc.data());

      // 2. Ambil Info Modul Ujian
      const mDoc = await getDoc(doc(db, "masterclass_modules", moduleId));
      if (!mDoc.exists() || mDoc.data().tipe !== "ujian") {
        toast.error("Modul ujian tidak valid atau tidak ditemukan.");
        return router.push(`/masterclass/${courseId}/learn`);
      }

      const mData = mDoc.data();
      setModuleData(mData);

      // Setup Timer (Menit -> Detik)
      setTimeLeft((mData.durasiUjian || 15) * 60);
    } catch (error) {
      console.error(error);
      toast.error("Gagal memuat ujian.");
    } finally {
      setIsLoading(false);
    }
  };

  // 🔥 LOGIKA TIMER 🔥
  useEffect(() => {
    let timer: any;
    if (isStarted && !isSubmitted && timeLeft > 0) {
      timer = setInterval(() => {
        setTimeLeft((prev) => prev - 1);
      }, 1000);
    } else if (timeLeft === 0 && isStarted && !isSubmitted) {
      // Waktu habis, kumpulkan paksa
      handleAutoSubmit();
    }
    return () => clearInterval(timer);
  }, [isStarted, isSubmitted, timeLeft]);

  // Hindari looping dependencies di useEffect
  const handleAutoSubmit = useCallback(() => {
    handleSubmitExam(true);
  }, [answers, moduleData]);

  // Format waktu ke MM:SS
  const formatTime = (seconds: number) => {
    const m = Math.floor(seconds / 60);
    const s = seconds % 60;
    return `${m.toString().padStart(2, "0")}:${s.toString().padStart(2, "0")}`;
  };

  const handleSelectAnswer = (soalIndex: number, answer: string) => {
    if (isSubmitted) return;
    setAnswers((prev) => ({ ...prev, [soalIndex]: answer }));
  };

  const handleSubmitExam = async (isAutoSubmit = false) => {
    if (!moduleData || !moduleData.soalUjian) return;

    const totalSoal = moduleData.soalUjian.length;
    const answeredCount = Object.keys(answers).length;

    // Jika belum dijawab semua dan dikumpul manual, kasih peringatan
    if (!isAutoSubmit && timeLeft > 0 && answeredCount < totalSoal) {
      if (
        !confirm(
          `Anda baru menjawab ${answeredCount} dari ${totalSoal} soal. Yakin ingin mengumpulkan sekarang?`,
        )
      ) {
        return;
      }
    }

    setIsSaving(true);
    setIsSubmitted(true);

    try {
      // 1. Hitung Nilai
      let correctAnswers = 0;
      moduleData.soalUjian.forEach((soal: any, index: number) => {
        if (answers[index] === soal.jawabanBenar) {
          correctAnswers++;
        }
      });

      const finalScore = Math.round((correctAnswers / totalSoal) * 100);
      const passed = finalScore >= (moduleData.kkm || 70);

      setScore(finalScore);
      setIsPassed(passed);

      // 2. Jika Lulus, Update Progress di Firebase agar gembok terbuka
      if (passed) {
        const progId = `${currentUser.uid}_${courseId}`;
        const progRef = doc(db, "masterclass_progress", progId);

        await setDoc(
          progRef,
          {
            uid: currentUser.uid,
            courseId: courseId,
            completedModules: arrayUnion(moduleId),
            lastUpdated: serverTimestamp(),
          },
          { merge: true },
        );
      }
    } catch (error) {
      console.error(error);
      toast.error("Terjadi kesalahan saat menyimpan nilai.");
    } finally {
      setIsSaving(false);
    }
  };

  const handleRetry = () => {
    setAnswers({});
    setTimeLeft((moduleData.durasiUjian || 15) * 60);
    setIsSubmitted(false);
    setIsPassed(false);
    setScore(0);
  };

  if (isLoading || !moduleData) {
    return (
      <div className="min-h-screen flex flex-col items-center justify-center bg-slate-50 font-sans">
        <div className="w-12 h-12 border-4 border-slate-200 border-t-rose-600 rounded-full animate-spin mb-4"></div>
        <p className="font-bold text-slate-500 text-sm tracking-widest uppercase">
          Menyiapkan Lembar Ujian...
        </p>
      </div>
    );
  }

  // ==========================================
  // LAYAR 1: BRIEFING (SEBELUM MULAI)
  // ==========================================
  if (!isStarted) {
    return (
      <div className="min-h-screen flex items-center justify-center bg-[#F5F7FA] font-sans p-4">
        <div className="bg-white max-w-lg w-full rounded-3xl p-8 sm:p-12 shadow-xl border border-slate-200 text-center animate-in zoom-in-95 duration-500">
          <div className="w-24 h-24 bg-rose-50 text-rose-600 rounded-full flex items-center justify-center mx-auto mb-6 border border-rose-100 shadow-sm">
            <svg
              className="w-10 h-10"
              fill="none"
              viewBox="0 0 24 24"
              stroke="currentColor"
            >
              <path
                strokeLinecap="round"
                strokeLinejoin="round"
                strokeWidth={2}
                d="M9 5H7a2 2 0 00-2 2v12a2 2 0 002 2h10a2 2 0 002-2V7a2 2 0 00-2-2h-2M9 5a2 2 0 002 2h2a2 2 0 002-2M9 5a2 2 0 012-2h2a2 2 0 012 2m-3 7h3m-3 4h3m-6-4h.01M9 16h.01"
              />
            </svg>
          </div>
          <h1 className="text-2xl font-black text-slate-900 mb-2">
            {moduleData.judul}
          </h1>
          <p className="text-slate-500 text-sm mb-8">
            Kerjakan dengan jujur dan teliti. Waktu akan berjalan secara
            otomatis setelah Anda menekan tombol mulai.
          </p>

          <div className="grid grid-cols-3 gap-3 sm:gap-4 mb-10">
            <div className="bg-slate-50 p-3 rounded-2xl border border-slate-100">
              <p className="text-[10px] font-bold text-slate-400 uppercase tracking-widest">
                Durasi
              </p>
              <p className="text-lg font-black text-slate-800">
                {moduleData.durasiUjian} <span className="text-xs">Mnt</span>
              </p>
            </div>
            <div className="bg-slate-50 p-3 rounded-2xl border border-slate-100">
              <p className="text-[10px] font-bold text-slate-400 uppercase tracking-widest">
                Total
              </p>
              <p className="text-lg font-black text-slate-800">
                {moduleData.soalUjian?.length || 0}{" "}
                <span className="text-xs">Soal</span>
              </p>
            </div>
            <div className="bg-slate-50 p-3 rounded-2xl border border-slate-100">
              <p className="text-[10px] font-bold text-slate-400 uppercase tracking-widest">
                KKM
              </p>
              <p className="text-lg font-black text-rose-600">
                {moduleData.kkm || 70}
              </p>
            </div>
          </div>

          <div className="flex flex-col gap-3">
            <button
              onClick={() => setIsStarted(true)}
              className="bg-rose-600 hover:bg-rose-700 text-white py-4 rounded-xl font-black transition-all shadow-lg shadow-rose-600/30 w-full text-lg"
            >
              MULAI UJIAN SEKARANG
            </button>
            <button
              onClick={() => router.push(`/masterclass/${courseId}/learn`)}
              className="text-sm font-bold text-slate-400 hover:text-slate-600 py-2 transition-colors"
            >
              Kembali ke Ruang Belajar
            </button>
          </div>
        </div>
      </div>
    );
  }

  // ==========================================
  // LAYAR 2: HASIL UJIAN (SETELAH KUMPUL)
  // ==========================================
  if (isSubmitted && !isSaving) {
    return (
      <div className="min-h-screen flex items-center justify-center bg-[#F5F7FA] font-sans p-4">
        <div className="bg-white max-w-lg w-full rounded-3xl p-8 sm:p-12 shadow-xl border border-slate-200 text-center animate-in zoom-in-95 duration-500">
          {isPassed ? (
            <div className="w-24 h-24 bg-emerald-50 text-emerald-500 rounded-full flex items-center justify-center mx-auto mb-6 border border-emerald-100 shadow-sm">
              <svg
                className="w-12 h-12"
                fill="none"
                viewBox="0 0 24 24"
                stroke="currentColor"
              >
                <path
                  strokeLinecap="round"
                  strokeLinejoin="round"
                  strokeWidth={3}
                  d="M5 13l4 4L19 7"
                />
              </svg>
            </div>
          ) : (
            <div className="w-24 h-24 bg-rose-50 text-rose-500 rounded-full flex items-center justify-center mx-auto mb-6 border border-rose-100 shadow-sm">
              <svg
                className="w-12 h-12"
                fill="none"
                viewBox="0 0 24 24"
                stroke="currentColor"
              >
                <path
                  strokeLinecap="round"
                  strokeLinejoin="round"
                  strokeWidth={3}
                  d="M6 18L18 6M6 6l12 12"
                />
              </svg>
            </div>
          )}

          <h2
            className={`text-3xl font-black mb-2 ${isPassed ? "text-emerald-600" : "text-rose-600"}`}
          >
            {isPassed ? "LULUS!" : "BELUM LULUS"}
          </h2>
          <p className="text-slate-500 text-sm mb-6 leading-relaxed">
            {isPassed
              ? "Luar biasa! Anda berhasil mencapai nilai standar kelulusan (KKM). Anda dapat melanjutkan materi."
              : `Jangan menyerah! Nilai Anda belum mencapai KKM (${moduleData.kkm}). Silakan pelajari ulang materi dan coba lagi.`}
          </p>

          <div className="bg-slate-50 border border-slate-200 rounded-3xl p-6 mb-8 relative overflow-hidden shadow-inner">
            <div className="absolute top-0 left-0 w-full h-1 bg-slate-200">
              <div
                className={`h-full ${isPassed ? "bg-emerald-500" : "bg-rose-500"}`}
                style={{ width: `${score}%` }}
              ></div>
            </div>
            <p className="text-xs font-bold text-slate-400 uppercase tracking-widest mb-1">
              NILAI AKHIR ANDA
            </p>
            <p
              className={`text-6xl font-black tracking-tighter ${isPassed ? "text-emerald-600" : "text-rose-600"}`}
            >
              {score}
            </p>
          </div>

          <div className="flex flex-col gap-3">
            {isPassed ? (
              <button
                onClick={() => router.push(`/masterclass/${courseId}/learn`)}
                className="bg-[#0056D2] hover:bg-[#00419E] text-white py-4 rounded-xl font-black transition-all shadow-lg shadow-blue-500/30 w-full text-lg"
              >
                LANJUTKAN BELAJAR
              </button>
            ) : (
              <button
                onClick={handleRetry}
                className="bg-slate-800 hover:bg-slate-900 text-white py-4 rounded-xl font-black transition-all shadow-lg shadow-slate-800/30 w-full text-lg"
              >
                COBA UJIAN LAGI
              </button>
            )}
            <button
              onClick={() => router.push(`/masterclass/${courseId}/learn`)}
              className="text-sm font-bold text-slate-400 hover:text-slate-600 py-2 mt-2 transition-colors"
            >
              Kembali ke Ruang Belajar
            </button>
          </div>
        </div>
      </div>
    );
  }

  // ==========================================
  // LAYAR 3: AKTIF UJIAN (KERTAS SOAL)
  // ==========================================
  return (
    <div className="min-h-screen bg-slate-50 font-sans text-slate-800 pb-24">
      {/* HEADER EXAM BERSIH */}
      <nav className="bg-white border-b border-slate-200 px-4 sm:px-8 py-4 flex items-center justify-between sticky top-0 z-50 shadow-sm">
        <div>
          <p className="text-[10px] font-black text-rose-600 uppercase tracking-widest mb-0.5">
            Lembar Ujian
          </p>
          <h1 className="text-sm sm:text-base font-bold text-slate-900 truncate max-w-[200px] sm:max-w-md">
            {moduleData.judul}
          </h1>
        </div>

        <div
          className={`flex items-center gap-2 px-4 py-2 rounded-xl border transition-colors ${timeLeft < 60 ? "bg-rose-50 border-rose-200 text-rose-600 animate-pulse shadow-inner" : "bg-slate-50 border-slate-200 text-slate-700"}`}
        >
          <svg
            className="w-5 h-5"
            fill="none"
            viewBox="0 0 24 24"
            stroke="currentColor"
          >
            <path
              strokeLinecap="round"
              strokeLinejoin="round"
              strokeWidth={2.5}
              d="M12 8v4l3 3m6-3a9 9 0 11-18 0 9 9 0 0118 0z"
            />
            <path
              strokeLinecap="round"
              strokeLinejoin="round"
              strokeWidth={2.5}
              d="M12 8v4l2 2"
            />
          </svg>
          <span className="font-mono font-black text-lg tracking-widest">
            {formatTime(timeLeft)}
          </span>
        </div>
      </nav>

      {/* DAFTAR KERTAS SOAL */}
      <main className="max-w-3xl mx-auto px-4 sm:px-6 pt-10">
        <div className="space-y-8">
          {moduleData.soalUjian?.map((soal: any, index: number) => (
            <div
              key={index}
              className="bg-white p-6 sm:p-8 rounded-3xl shadow-sm border border-slate-200"
            >
              <div className="flex gap-4 mb-6">
                <div className="w-8 h-8 rounded-full bg-rose-100 text-rose-600 flex items-center justify-center font-black shrink-0 border border-rose-200">
                  {index + 1}
                </div>
                <p className="font-bold text-slate-800 text-base leading-relaxed pt-1 whitespace-pre-wrap">
                  {soal.pertanyaan}
                </p>
              </div>

              <div className="space-y-3 pl-0 sm:pl-12">
                {["A", "B", "C", "D"].map((opsi) => {
                  const valueOpsi = soal[`opsi${opsi}`];
                  if (!valueOpsi) return null;
                  const isSelected = answers[index] === opsi;

                  return (
                    <button
                      key={opsi}
                      onClick={() => handleSelectAnswer(index, opsi)}
                      className={`w-full text-left p-4 rounded-xl border-2 transition-all flex items-start gap-4 ${isSelected ? "border-[#0056D2] bg-blue-50/50 shadow-sm" : "border-slate-100 hover:border-slate-300 bg-white"}`}
                    >
                      <div
                        className={`w-5 h-5 rounded-full border-2 flex items-center justify-center shrink-0 mt-0.5 ${isSelected ? "border-[#0056D2] bg-[#0056D2] text-white" : "border-slate-300 text-transparent"}`}
                      >
                        {isSelected && (
                          <svg
                            className="w-3 h-3"
                            fill="none"
                            viewBox="0 0 24 24"
                            stroke="currentColor"
                          >
                            <path
                              strokeLinecap="round"
                              strokeLinejoin="round"
                              strokeWidth={3}
                              d="M5 13l4 4L19 7"
                            />
                          </svg>
                        )}
                      </div>
                      <div className="flex-1">
                        <span className="font-black text-slate-400 mr-2">
                          {opsi}.
                        </span>
                        <span
                          className={`text-sm ${isSelected ? "font-bold text-blue-900" : "font-medium text-slate-600"}`}
                        >
                          {valueOpsi}
                        </span>
                      </div>
                    </button>
                  );
                })}
              </div>
            </div>
          ))}
        </div>

        {/* TOMBOL SUBMIT */}
        <div className="mt-12 flex justify-end">
          <button
            onClick={() => handleSubmitExam(false)}
            disabled={isSaving}
            className="bg-[#0056D2] hover:bg-[#00419E] text-white px-10 py-4 rounded-xl font-black transition-all shadow-lg shadow-blue-500/30 flex items-center gap-3 w-full sm:w-auto justify-center disabled:opacity-50 text-base"
          >
            {isSaving ? "MENGKOREKSI..." : "KUMPULKAN UJIAN"}
            {!isSaving && (
              <svg
                className="w-5 h-5"
                fill="none"
                viewBox="0 0 24 24"
                stroke="currentColor"
              >
                <path
                  strokeLinecap="round"
                  strokeLinejoin="round"
                  strokeWidth={2.5}
                  d="M12 19l9 2-9-18-9 18 9-2zm0 0v-8"
                />
              </svg>
            )}
          </button>
        </div>
      </main>
    </div>
  );
}

"use client";

import { useState, useEffect, useRef, useMemo } from "react";
import { toast } from "@/lib/toast";
import { useParams, useRouter } from "next/navigation";
import { auth, db } from "@/lib/firebase";
import { onAuthStateChanged, signOut } from "firebase/auth";
import {
  doc,
  getDoc,
  collection,
  query,
  where,
  getDocs,
  setDoc,
  addDoc,
  updateDoc,
  serverTimestamp,
  arrayUnion,
} from "firebase/firestore";
import Link from "next/link";
import YouTube from "react-youtube"; // 🔥 TAMBAHAN: Library YouTube API

// 🔥 PERBAIKAN: Helper diubah untuk mengekstrak ID murni YouTube
const extractYouTubeId = (url: string) => {
  if (!url) return "";
  let videoId = "";
  try {
    if (url.includes("youtu.be/")) {
      videoId = url.split("youtu.be/")[1]?.split("?")[0];
    } else if (url.includes("youtube.com/watch")) {
      videoId = new URL(url).searchParams.get("v") || "";
    } else if (url.includes("youtube.com/embed/")) {
      videoId = url.split("youtube.com/embed/")[1]?.split("?")[0];
    }
  } catch (e) {
    return "";
  }
  return videoId;
};

export default function MasterclassLearnPage() {
  const params = useParams();
  const router = useRouter();
  const courseId = params.id as string;

  const [currentUser, setCurrentUser] = useState<any>(null);
  const [isAdmin, setIsAdmin] = useState(false);
  const [accessStatus, setAccessStatus] = useState<
    "loading" | "granted" | "denied"
  >("loading");

  const [course, setCourse] = useState<any>(null);
  const [mentor, setMentor] = useState<any>(null);
  const [modules, setModules] = useState<any[]>([]);
  const [activeModule, setActiveModule] = useState<any>(null);

  const [completedModules, setCompletedModules] = useState<string[]>([]);
  const [isSavingProgress, setIsSavingProgress] = useState(false);

  // 🔥 TAMBAHAN: State untuk Anti-Skip Video
  const [isVideoFinished, setIsVideoFinished] = useState(false);

  const [activeTab, setActiveTab] = useState<"overview" | "downloads" | "qa">(
    "overview",
  );
  const [isSidebarOpen, setIsSidebarOpen] = useState(true);

  const [isProfileDropdownOpen, setIsProfileDropdownOpen] = useState(false);
  const dropdownRef = useRef<HTMLDivElement>(null);

  const [discussions, setDiscussions] = useState<any[]>([]);
  const [newComment, setNewComment] = useState("");
  const [isPosting, setIsPosting] = useState(false);

  // 🔥 STATE UNTUK ULASAN (REVIEW) 🔥
  const [userReview, setUserReview] = useState<any>(null);
  const [isReviewModalOpen, setIsReviewModalOpen] = useState(false);
  const [reviewRating, setReviewRating] = useState(5);
  const [reviewText, setReviewText] = useState("");
  const [isSubmittingReview, setIsSubmittingReview] = useState(false);

  // 🔥 TAMBAHAN: Reset status video tiap pindah modul
  useEffect(() => {
    setIsVideoFinished(false);
  }, [activeModule?.id]);

  useEffect(() => {
    const unsubscribe = onAuthStateChanged(auth, async (user) => {
      if (user) {
        setCurrentUser(user);
        await checkAccessAndFetchData(user);
      } else {
        router.push(`/masterclass/${courseId}`);
      }
    });

    const handleClickOutside = (event: MouseEvent) => {
      if (
        dropdownRef.current &&
        !dropdownRef.current.contains(event.target as Node)
      ) {
        setIsProfileDropdownOpen(false);
      }
    };
    document.addEventListener("mousedown", handleClickOutside);

    return () => {
      unsubscribe();
      document.removeEventListener("mousedown", handleClickOutside);
    };
  }, [courseId]);

  useEffect(() => {
    if (activeModule && activeTab === "qa") {
      fetchDiscussions();
    }
  }, [activeModule, activeTab]);

  const checkAccessAndFetchData = async (user: any) => {
    try {
      let hasAccess = false;
      let adminFlag = false;

      const userDoc = await getDoc(doc(db, "users", user.uid));
      const role = userDoc.exists() ? userDoc.data().role?.toLowerCase() : "";

      if (role === "admin" || role === "super_admin" || role === "superadmin") {
        hasAccess = true;
        adminFlag = true;
      } else {
        const qEnroll = query(
          collection(db, "masterclass_enrollments"),
          where("courseId", "==", courseId),
          where("uid", "==", user.uid),
          where("statusAkses", "==", "Lunas"),
        );
        const snapEnroll = await getDocs(qEnroll);
        if (!snapEnroll.empty) {
          hasAccess = true;
        }
      }

      // Bypass untuk Pengurus
      if (!adminFlag) {
        const qPengurus = query(
          collection(db, "pengurus"),
          where("email", "==", user.email),
        );
        const snapPengurus = await getDocs(qPengurus);
        if (!snapPengurus.empty) {
          hasAccess = true;
          adminFlag = true;
        }
      }

      if (!hasAccess) {
        setAccessStatus("denied");
        setTimeout(() => router.push(`/masterclass/${courseId}`), 3000);
        return;
      }
      setIsAdmin(adminFlag);

      const courseSnap = await getDoc(doc(db, "masterclass_courses", courseId));
      if (courseSnap.exists()) {
        const cData: any = { id: courseSnap.id, ...courseSnap.data() };
        setCourse(cData);
        if (cData.mentorId) {
          const mSnap = await getDoc(
            doc(db, "masterclass_mentors", cData.mentorId),
          );
          if (mSnap.exists()) setMentor(mSnap.data());
        }
      }

      const qModules = query(
        collection(db, "masterclass_modules"),
        where("courseId", "==", courseId),
      );
      const moduleSnaps = await getDocs(qModules);
      const fetchedModules = moduleSnaps.docs
        .map((d) => ({ id: d.id, ...d.data() }))
        .sort((a: any, b: any) => Number(a.urutan) - Number(b.urutan));
      setModules(fetchedModules);

      const progressId = `${user.uid}_${courseId}`;
      const progressSnap = await getDoc(
        doc(db, "masterclass_progress", progressId),
      );
      let completedArray: string[] = [];

      if (progressSnap.exists()) {
        completedArray = progressSnap.data().completedModules || [];
        setCompletedModules(completedArray);
      } else {
        await setDoc(doc(db, "masterclass_progress", progressId), {
          uid: user.uid,
          courseId: courseId,
          completedModules: [],
          startedAt: serverTimestamp(),
        });
      }

      if (fetchedModules.length > 0) {
        const firstUncompleted = fetchedModules.find(
          (m) => !completedArray.includes(m.id),
        );
        setActiveModule(firstUncompleted || fetchedModules[0]);
      }

      // 🔥 CEK APAKAH SUDAH PERNAH KASIH ULASAN 🔥
      const qReview = query(
        collection(db, "masterclass_reviews"),
        where("courseId", "==", courseId),
        where("uid", "==", user.uid),
      );
      const snapReview = await getDocs(qReview);
      if (!snapReview.empty) {
        setUserReview({
          id: snapReview.docs[0].id,
          ...snapReview.docs[0].data(),
        });
      }

      setAccessStatus("granted");
    } catch (error) {
      console.error("Error loading classroom:", error);
      router.push(`/masterclass/${courseId}`);
    }
  };

  const fetchDiscussions = async () => {
    if (!activeModule) return;
    try {
      const qDesc = query(
        collection(db, "masterclass_discussions"),
        where("moduleId", "==", activeModule.id),
      );
      const snap = await getDocs(qDesc);
      const fetched = snap.docs.map((d) => ({ id: d.id, ...d.data() }));
      fetched.sort(
        (a: any, b: any) =>
          (b.createdAt?.seconds || 0) - (a.createdAt?.seconds || 0),
      );
      setDiscussions(fetched);
    } catch (error) {
      console.error("Gagal memuat diskusi:", error);
    }
  };

  const handlePostDiscussion = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!newComment.trim() || !currentUser || !activeModule) return;

    setIsPosting(true);
    try {
      await addDoc(collection(db, "masterclass_discussions"), {
        courseId: courseId,
        moduleId: activeModule.id,
        uid: currentUser.uid,
        userName: currentUser.displayName || currentUser.email.split("@")[0],
        text: newComment.trim(),
        createdAt: serverTimestamp(),
      });
      setNewComment("");
      fetchDiscussions();
    } catch (error) {
      toast.error("Gagal mengirim pesan.");
    } finally {
      setIsPosting(false);
    }
  };

  // 🔥 FUNGSI SUBMIT ULASAN 🔥
  const handleSubmitReview = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!reviewText.trim()) return;
    setIsSubmittingReview(true);

    try {
      if (userReview) {
        await updateDoc(doc(db, "masterclass_reviews", userReview.id), {
          rating: reviewRating,
          ulasan: reviewText,
          updatedAt: serverTimestamp(),
        });
        setUserReview({
          ...userReview,
          rating: reviewRating,
          ulasan: reviewText,
        });
      } else {
        const newRef = await addDoc(collection(db, "masterclass_reviews"), {
          courseId: courseId,
          uid: currentUser.uid,
          namaPeserta:
            currentUser.displayName || currentUser.email.split("@")[0],
          rating: reviewRating,
          ulasan: reviewText,
          status: "Tampil",
          createdAt: serverTimestamp(),
        });
        setUserReview({
          id: newRef.id,
          rating: reviewRating,
          ulasan: reviewText,
        });
      }
      setIsReviewModalOpen(false);
      toast.success("Terima kasih! Ulasan Anda berhasil disimpan.");
    } catch (err) {
      toast.error("Gagal mengirim ulasan.");
    } finally {
      setIsSubmittingReview(false);
    }
  };

  const handleMarkCompleteAndNext = async () => {
    if (!activeModule || !currentUser) return;
    setIsSavingProgress(true);

    const isAlreadyCompleted = completedModules.includes(activeModule.id);
    const currentIndex = modules.findIndex((m) => m.id === activeModule.id);
    const hasNextModule = currentIndex < modules.length - 1;

    try {
      if (!isAlreadyCompleted) {
        const progressId = `${currentUser.uid}_${courseId}`;
        await updateDoc(doc(db, "masterclass_progress", progressId), {
          completedModules: arrayUnion(activeModule.id),
          lastUpdated: serverTimestamp(),
        });
        // Pastikan tidak ada duplikat di state lokal
        setCompletedModules((prev) =>
          prev.includes(activeModule.id) ? prev : [...prev, activeModule.id],
        );
      }

      if (hasNextModule) {
        setActiveModule(modules[currentIndex + 1]);
        setActiveTab("overview");
        document
          .querySelector("main")
          ?.scrollTo({ top: 0, behavior: "smooth" });
      }
    } catch (error) {
      toast.error("Terjadi kesalahan saat menyimpan progres belajar Anda.");
    } finally {
      setIsSavingProgress(false);
    }
  };

  const handlePrevModule = () => {
    const currentIndex = modules.findIndex((m) => m.id === activeModule.id);
    if (currentIndex > 0) setActiveModule(modules[currentIndex - 1]);
  };

  const handleLogout = async () => {
    try {
      await signOut(auth);
      router.push("/masterclass");
    } catch (error) {
      console.error("Gagal logout:", error);
    }
  };

  // 🔥 LOGIKA GROUPING BAB 🔥
  const groupedModules = useMemo(() => {
    const groups: Record<string, any[]> = {};
    modules.forEach((mod) => {
      const bab = mod.bab || "Materi Pembahasan";
      if (!groups[bab]) groups[bab] = [];
      groups[bab].push(mod);
    });
    return groups;
  }, [modules]);

  // 🔥 CEK ANTI SKIP 🔥
  const isModuleLocked = (index: number) => {
    if (isAdmin) return false;
    if (index === 0) return false;
    const prevModuleId = modules[index - 1].id;
    return !completedModules.includes(prevModuleId);
  };

  if (accessStatus === "loading") {
    return (
      <div className="min-h-screen flex flex-col items-center justify-center bg-white">
        <div className="w-10 h-10 border-4 border-slate-100 border-t-[#0056D2] rounded-full animate-spin mb-4"></div>
        <p className="text-slate-500 font-medium text-sm mt-2">
          Menyiapkan Kelas & Progres Anda...
        </p>
      </div>
    );
  }

  if (accessStatus === "denied") {
    return (
      <div className="min-h-screen flex flex-col items-center justify-center bg-white p-6 text-center">
        <h2 className="text-2xl font-bold text-slate-900 mb-2">
          Akses Terlarang
        </h2>
        <p className="text-slate-500 max-w-sm mx-auto mb-4">
          Anda belum memiliki lisensi untuk mengakses modul ini atau pembayaran
          sedang diverifikasi.
        </p>
      </div>
    );
  }

  // 🔥 PERBAIKAN LOGIKA PROGRES (MENCEGAH ERROR 150%) 🔥
  // Filter id modul yang selesai HANYA yang masih ada di database saat ini
  const validCompletedModules = completedModules.filter((id) =>
    modules.some((m) => m.id === id),
  );
  const validCompletedCount = validCompletedModules.length;

  const progressPercentage =
    modules.length > 0
      ? Math.round((validCompletedCount / modules.length) * 100)
      : 0;

  // Syarat lulus: Progres 100%
  const isCourseCompleted = progressPercentage >= 100;

  const isActiveCompleted = activeModule
    ? completedModules.includes(activeModule.id)
    : false;
  const currentIndex = modules.findIndex((m) => m.id === activeModule?.id);
  const isLastModule = currentIndex === modules.length - 1;

  // 🔥 LOGIKA BARU: MENGUNCI TOMBOL JIKA VIDEO BELUM TAMAT 🔥
  const isCurrentVideoType =
    !activeModule?.tipe || activeModule?.tipe === "video";
  const youtubeVideoId = extractYouTubeId(
    activeModule?.videoUrl || course?.urlAkses,
  );
  const isStrictLocked =
    isCurrentVideoType && !isActiveCompleted && !isVideoFinished && !isAdmin;
  const isCompleteBtnDisabled =
    isSavingProgress || (isLastModule && isActiveCompleted) || isStrictLocked;

  return (
    <div className="h-screen bg-white flex flex-col font-sans text-slate-800 overflow-hidden">
      {/* 🔥 MODAL ULASAN 🔥 */}
      {isReviewModalOpen && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-slate-900/80 backdrop-blur-sm animate-in fade-in">
          <form
            onSubmit={handleSubmitReview}
            className="bg-white rounded-3xl p-6 sm:p-8 w-full max-w-md shadow-2xl relative"
          >
            <button
              type="button"
              onClick={() => setIsReviewModalOpen(false)}
              className="absolute top-4 right-4 text-slate-400 hover:bg-slate-100 p-2 rounded-full"
            >
              ✕
            </button>
            <div className="text-center mb-6">
              <div className="w-16 h-16 bg-amber-100 text-amber-500 rounded-full flex items-center justify-center mx-auto mb-4 text-3xl">
                ⭐
              </div>
              <h2 className="text-2xl font-black text-slate-800 tracking-tight">
                Bagaimana pengalamanmu?
              </h2>
              <p className="text-xs text-slate-500 mt-2">
                Ulasanmu membantu peserta lain memilih kelas yang tepat.
              </p>
            </div>

            <div className="flex justify-center gap-2 mb-6">
              {[1, 2, 3, 4, 5].map((star) => (
                <button
                  key={star}
                  type="button"
                  onClick={() => setReviewRating(star)}
                  className={`text-4xl transition-all ${star <= reviewRating ? "text-[#F2D049] scale-110 drop-shadow-sm" : "text-slate-200 hover:text-amber-200"}`}
                >
                  ★
                </button>
              ))}
            </div>

            <textarea
              rows={4}
              required
              value={reviewText}
              onChange={(e) => setReviewText(e.target.value)}
              placeholder="Ceritakan apa yang paling kamu sukai dari kelas ini..."
              className="w-full bg-slate-50 border border-slate-200 p-4 rounded-xl text-sm outline-none focus:bg-white focus:border-amber-400 resize-none mb-6"
            ></textarea>

            <button
              type="submit"
              disabled={isSubmittingReview || !reviewText.trim()}
              className="w-full py-3.5 bg-[#0B1120] hover:bg-slate-800 text-white font-bold rounded-xl shadow-lg disabled:opacity-50 transition-all flex justify-center items-center gap-2"
            >
              {isSubmittingReview
                ? "Menyimpan Ulasan..."
                : "Kirim Ulasan Sekarang"}
            </button>
          </form>
        </div>
      )}

      {/* HEADER */}
      <header className="h-[70px] bg-white border-b border-slate-200 flex items-center justify-between px-4 lg:px-8 shrink-0 z-20 shadow-sm">
        <div className="flex items-center gap-4">
          <Link
            href={`/masterclass/${courseId}`}
            className="text-slate-500 hover:text-[#0056D2] transition-colors p-2 hover:bg-slate-50 rounded-full"
            title="Kembali ke Detail Kelas"
          >
            <svg
              className="w-5 h-5"
              fill="none"
              viewBox="0 0 24 24"
              stroke="currentColor"
            >
              <path
                strokeLinecap="round"
                strokeLinejoin="round"
                strokeWidth={2.5}
                d="M10 19l-7-7m0 0l7-7m-7 7h18"
              />
            </svg>
          </Link>
          <div className="h-6 w-px bg-slate-200 hidden sm:block"></div>
          <div>
            <h1 className="font-bold text-slate-800 text-sm lg:text-base line-clamp-1">
              {course?.judul || "Memuat..."}
            </h1>
            <p className="text-[10px] text-slate-500 uppercase tracking-widest hidden sm:block">
              {course?.kategori}
            </p>
          </div>
        </div>

        <div className="flex items-center gap-4">
          <div className="hidden md:flex flex-col items-end mr-2 border-r border-slate-200 pr-4">
            <span className="text-[10px] font-bold uppercase tracking-widest text-slate-500">
              Progres Belajar
            </span>
            <span className="text-sm font-black text-[#0056D2]">
              {progressPercentage}% Selesai
            </span>
          </div>

          <div className="relative" ref={dropdownRef}>
            <button
              onClick={() => setIsProfileDropdownOpen(!isProfileDropdownOpen)}
              className="flex items-center gap-2 p-1 border border-slate-200 rounded-full hover:bg-slate-50 transition-colors focus:ring-2 focus:ring-blue-100 outline-none"
            >
              <div
                className="w-8 h-8 rounded-full bg-[#0056D2] text-white flex items-center justify-center font-bold text-sm shadow-sm"
                title={currentUser?.displayName || currentUser?.email}
              >
                {(currentUser?.displayName || currentUser?.email || "U")
                  .charAt(0)
                  .toUpperCase()}
              </div>
              <svg
                className={`w-4 h-4 text-slate-400 transition-transform mr-1 hidden sm:block ${isProfileDropdownOpen ? "rotate-180" : ""}`}
                fill="none"
                viewBox="0 0 24 24"
                stroke="currentColor"
              >
                <path
                  strokeLinecap="round"
                  strokeLinejoin="round"
                  strokeWidth={2}
                  d="M19 9l-7 7-7-7"
                />
              </svg>
            </button>

            {isProfileDropdownOpen && (
              <div className="absolute right-0 mt-3 w-56 bg-white rounded-2xl shadow-xl border border-slate-100 overflow-hidden animate-in fade-in slide-in-from-top-2">
                <div className="p-4 border-b border-slate-100 bg-slate-50">
                  <p className="text-xs font-bold text-slate-800 truncate">
                    {currentUser?.displayName || "Siswa"}
                  </p>
                  <p className="text-[10px] text-slate-500 truncate">
                    {currentUser?.email}
                  </p>
                </div>
                <div className="p-2">
                  <Link
                    href="/masterclass/my-courses"
                    onClick={() => setIsProfileDropdownOpen(false)}
                    className="flex items-center gap-3 px-4 py-2.5 text-sm font-bold text-slate-700 hover:bg-blue-50 hover:text-blue-600 rounded-xl transition-colors"
                  >
                    <svg
                      className="w-5 h-5 opacity-70"
                      fill="none"
                      viewBox="0 0 24 24"
                      stroke="currentColor"
                    >
                      <path
                        strokeLinecap="round"
                        strokeLinejoin="round"
                        strokeWidth={2.5}
                        d="M12 6.253v13m0-13C10.832 5.477 9.246 5 7.5 5S4.168 5.477 3 6.253v13C4.168 18.477 5.754 18 7.5 18s3.332.477 4.5 1.253m0-13C13.168 5.477 14.754 5 16.5 5c1.747 0 3.332.477 4.5 1.253v13C19.832 18.477 18.247 18 16.5 18c-1.746 0-3.332.477-4.5 1.253"
                      />
                    </svg>
                    My Courses
                  </Link>
                  <Link
                    href="/masterclass"
                    onClick={() => setIsProfileDropdownOpen(false)}
                    className="flex items-center gap-3 px-4 py-2.5 text-sm font-bold text-slate-700 hover:bg-blue-50 hover:text-blue-600 rounded-xl transition-colors"
                  >
                    <svg
                      className="w-5 h-5 opacity-70"
                      fill="none"
                      viewBox="0 0 24 24"
                      stroke="currentColor"
                    >
                      <path
                        strokeLinecap="round"
                        strokeLinejoin="round"
                        strokeWidth={2.5}
                        d="M3 12l2-2m0 0l7-7 7 7M5 10v10a1 1 0 001 1h3m10-11l2 2m-2-2v10a1 1 0 01-1 1h-3m-6 0a1 1 0 001-1v-4a1 1 0 011-1h2a1 1 0 011 1v4a1 1 0 001 1m-6 0h6"
                      />
                    </svg>
                    Katalog Utama
                  </Link>
                  <button
                    onClick={handleLogout}
                    className="w-full flex items-center gap-3 px-4 py-2.5 text-sm font-bold text-rose-600 hover:bg-rose-50 rounded-xl transition-colors mt-1"
                  >
                    <svg
                      className="w-5 h-5 opacity-70"
                      fill="none"
                      viewBox="0 0 24 24"
                      stroke="currentColor"
                    >
                      <path
                        strokeLinecap="round"
                        strokeLinejoin="round"
                        strokeWidth={2.5}
                        d="M17 16l4-4m0 0l-4-4m4 4H7m6 4v1a3 3 0 01-3 3H6a3 3 0 01-3-3V7a3 3 0 013-3h4a3 3 0 013 3v1"
                      />
                    </svg>
                    Keluar (Logout)
                  </button>
                </div>
              </div>
            )}
          </div>
        </div>
      </header>

      {/* BODY LAYOUT */}
      <div className="flex-1 flex overflow-hidden w-full relative">
        {/* LAYAR UTAMA BELAJAR */}
        <main className="flex-1 flex flex-col overflow-y-auto bg-white custom-scrollbar relative">
          {/* AREA PROPORSIONAL PLAYER / MATERI (16:9) */}
          <div className="w-full bg-[#0B1120] relative shrink-0 border-b border-slate-800">
            <div className="max-w-[1000px] mx-auto w-full aspect-video bg-black relative">
              {/* 1. TAMPILAN JIKA VIDEO (Default) */}
              {(!activeModule?.tipe || activeModule?.tipe === "video") && (
                <>
                  {youtubeVideoId ? (
                    // 🔥 PERUBAHAN: MENGGUNAKAN REACT-YOUTUBE DENGAN STRICT MODE 🔥
                    <YouTube
                      videoId={youtubeVideoId}
                      opts={{
                        width: "100%",
                        height: "100%",
                        playerVars: {
                          autoplay: 0,
                          controls: 0, // Kunci progress bar
                          disablekb: 1, // Kunci keyboard skip
                          rel: 0,
                          modestbranding: 1,
                        },
                      }}
                      onEnd={() => setIsVideoFinished(true)} // Buka gembok pas video habis
                      className="w-full h-full absolute inset-0"
                      iframeClassName="w-full h-full border-0 absolute inset-0"
                    />
                  ) : (
                    <div className="w-full h-full flex flex-col items-center justify-center text-slate-500">
                      <svg
                        className="w-12 h-12 mb-3 opacity-30"
                        fill="none"
                        viewBox="0 0 24 24"
                        stroke="currentColor"
                      >
                        <path
                          strokeLinecap="round"
                          strokeLinejoin="round"
                          strokeWidth={1.5}
                          d="M15 10l4.553-2.276A1 1 0 0121 8.618v6.764a1 1 0 01-1.447.894L15 14M5 18h8a2 2 0 002-2V8a2 2 0 00-2-2H5a2 2 0 00-2 2v8a2 2 0 002 2z"
                        />
                      </svg>
                      <p className="font-bold text-sm">Video tidak tersedia</p>
                    </div>
                  )}
                </>
              )}

              {/* 2. TAMPILAN JIKA DOKUMEN PDF */}
              {activeModule?.tipe === "pdf" && (
                <div className="w-full h-full absolute inset-0 bg-slate-900 flex flex-col items-center justify-center text-slate-300 p-6 text-center">
                  <div className="w-20 h-20 bg-indigo-500/20 text-indigo-400 rounded-full flex items-center justify-center mb-6 border border-indigo-500/30">
                    <svg
                      className="w-10 h-10"
                      fill="none"
                      viewBox="0 0 24 24"
                      stroke="currentColor"
                    >
                      <path
                        strokeLinecap="round"
                        strokeLinejoin="round"
                        strokeWidth={2}
                        d="M9 12h6m-6 4h6m2 5H7a2 2 0 01-2-2V5a2 2 0 012-2h5.586a1 1 0 01.707.293l5.414 5.414a1 1 0 01.293.707V19a2 2 0 01-2 2z"
                      />
                    </svg>
                  </div>
                  <h3 className="text-white font-bold text-xl sm:text-2xl mb-2">
                    {activeModule.judul}
                  </h3>
                  <p className="text-sm max-w-md text-center mb-8">
                    Materi ini disajikan dalam format Dokumen PDF. Silakan buka
                    tautan di bawah untuk membaca atau mengunduhnya.
                  </p>
                  <a
                    href={activeModule.dokumenUrl}
                    target="_blank"
                    rel="noreferrer"
                    className="bg-indigo-600 hover:bg-indigo-500 text-white px-8 py-3.5 rounded-xl font-bold transition-all shadow-lg shadow-indigo-600/30"
                  >
                    Buka Dokumen PDF
                  </a>
                </div>
              )}

              {/* 3. TAMPILAN JIKA UJIAN */}
              {activeModule?.tipe === "ujian" && (
                <div className="w-full h-full absolute inset-0 bg-slate-900 flex flex-col items-center justify-center text-slate-300 p-6 text-center">
                  <div className="w-20 h-20 bg-rose-500/20 text-rose-400 rounded-full flex items-center justify-center mb-4 border border-rose-500/30">
                    <svg
                      className="w-10 h-10"
                      fill="none"
                      viewBox="0 0 24 24"
                      stroke="currentColor"
                    >
                      <path
                        strokeLinecap="round"
                        strokeLinejoin="round"
                        strokeWidth={2}
                        d="M9 5H7a2 2 0 00-2 2v12a2 2 0 002 2h10a2 2 0 002-2V7a2 2 0 00-2-2h-2M9 5a2 2 0 002 2h2a2 2 0 002-2M9 5a2 2 0 012-2h2a2 2 0 012 2m-3 7h3m-3 4h3m-6-4h.01M9 16h.01"
                      />
                    </svg>
                  </div>
                  <h3 className="text-white font-black text-2xl sm:text-3xl mb-2">
                    {activeModule.judul}
                  </h3>
                  <p className="text-sm max-w-lg text-center mb-8">
                    Persiapkan diri Anda. Ujian ini memiliki batas waktu dan
                    nilai kelulusan minimum.
                  </p>

                  <div className="flex gap-4 sm:gap-6 mb-8">
                    <div className="bg-slate-800 px-6 py-3 rounded-xl border border-slate-700 min-w-[100px]">
                      <p className="text-[10px] uppercase tracking-widest text-slate-400 font-bold mb-1">
                        Durasi
                      </p>
                      <p className="text-xl sm:text-2xl font-black text-white">
                        {activeModule.durasiUjian || 15}{" "}
                        <span className="text-xs font-medium text-slate-400">
                          Menit
                        </span>
                      </p>
                    </div>
                    <div className="bg-slate-800 px-6 py-3 rounded-xl border border-slate-700 min-w-[100px]">
                      <p className="text-[10px] uppercase tracking-widest text-slate-400 font-bold mb-1">
                        KKM
                      </p>
                      <p className="text-xl sm:text-2xl font-black text-rose-400">
                        {activeModule.kkm || 70}{" "}
                        <span className="text-xs font-medium text-slate-400">
                          Poin
                        </span>
                      </p>
                    </div>
                  </div>

                  {completedModules.includes(activeModule.id) ? (
                    <div className="bg-emerald-500/20 border border-emerald-500/30 text-emerald-400 px-6 py-3 rounded-xl font-bold flex items-center gap-2">
                      <svg
                        className="w-5 h-5"
                        fill="none"
                        viewBox="0 0 24 24"
                        stroke="currentColor"
                      >
                        <path
                          strokeLinecap="round"
                          strokeLinejoin="round"
                          strokeWidth={3}
                          d="M5 13l4 4L19 7"
                        />
                      </svg>
                      Anda Sudah Lulus Ujian Ini
                    </div>
                  ) : (
                    <button
                      onClick={() =>
                        router.push(
                          `/masterclass/${courseId}/exam/${activeModule.id}`,
                        )
                      }
                      className="bg-rose-600 hover:bg-rose-500 text-white px-8 sm:px-10 py-4 rounded-xl font-black text-lg transition-all shadow-lg shadow-rose-600/20"
                    >
                      MULAI UJIAN SEKARANG
                    </button>
                  )}
                </div>
              )}
            </div>
          </div>

          <div className="max-w-[1000px] w-full mx-auto px-6 py-8">
            <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-6 mb-8">
              <h2 className="text-2xl lg:text-3xl font-bold text-[#1F2432] leading-tight flex-1">
                {activeModule?.urutan}. {activeModule?.judul || course?.judul}
              </h2>

              <div className="flex items-center gap-3 shrink-0 w-full md:w-auto">
                <button
                  onClick={handlePrevModule}
                  disabled={currentIndex === 0 || isSavingProgress}
                  className="flex-1 md:flex-none flex items-center justify-center gap-2 px-5 py-3 rounded-lg border border-slate-300 text-sm font-bold text-slate-700 hover:bg-slate-50 disabled:opacity-30 transition-colors"
                >
                  <svg
                    className="w-4 h-4"
                    fill="none"
                    viewBox="0 0 24 24"
                    stroke="currentColor"
                  >
                    <path
                      strokeLinecap="round"
                      strokeLinejoin="round"
                      strokeWidth={2.5}
                      d="M15 19l-7-7 7-7"
                    />
                  </svg>
                  Sebelumnya
                </button>

                {/* 🔥 PERBAIKAN: TOMBOL SELESAI DENGAN LOGIKA STRICT ANTI SKIP 🔥 */}
                {activeModule?.tipe !== "ujian" && (
                  <button
                    onClick={handleMarkCompleteAndNext}
                    disabled={isCompleteBtnDisabled}
                    className={`flex-1 md:flex-none flex items-center justify-center gap-2 px-6 py-3 rounded-lg text-sm font-bold transition-all shadow-sm ${
                      isActiveCompleted
                        ? "bg-white border border-slate-300 text-slate-700 hover:bg-slate-50"
                        : isStrictLocked
                          ? "bg-slate-200 text-slate-500 cursor-not-allowed opacity-80"
                          : "bg-[#0056D2] hover:bg-[#00419E] text-white border border-[#0056D2]"
                    }`}
                  >
                    {isSavingProgress ? (
                      <svg
                        className="w-4 h-4 animate-spin"
                        fill="none"
                        viewBox="0 0 24 24"
                      >
                        <circle
                          className="opacity-25"
                          cx="12"
                          cy="12"
                          r="10"
                          stroke="currentColor"
                          strokeWidth="4"
                        ></circle>
                        <path
                          className="opacity-75"
                          fill="currentColor"
                          d="M4 12a8 8 0 018-8v8H4z"
                        ></path>
                      </svg>
                    ) : isActiveCompleted ? (
                      isLastModule ? (
                        "Modul Selesai"
                      ) : (
                        "Selanjutnya"
                      )
                    ) : isStrictLocked ? (
                      <>Tonton Video Sampai Habis 🔒</>
                    ) : (
                      <>
                        Tandai Selesai & Lanjut{" "}
                        <svg
                          className="w-4 h-4"
                          fill="none"
                          viewBox="0 0 24 24"
                          stroke="currentColor"
                        >
                          <path
                            strokeLinecap="round"
                            strokeLinejoin="round"
                            strokeWidth={2.5}
                            d="M9 5l7 7-7-7"
                          />
                        </svg>
                      </>
                    )}
                  </button>
                )}
              </div>
            </div>

            <div className="flex gap-8 border-b border-slate-200 overflow-x-auto no-scrollbar mb-8">
              <button
                onClick={() => setActiveTab("overview")}
                className={`pb-4 text-sm font-bold border-b-2 transition-colors whitespace-nowrap ${activeTab === "overview" ? "border-[#0056D2] text-[#0056D2]" : "border-transparent text-slate-500 hover:text-slate-800"}`}
              >
                Ikhtisar Pelajaran
              </button>
              <button
                onClick={() => setActiveTab("downloads")}
                className={`pb-4 text-sm font-bold border-b-2 transition-colors whitespace-nowrap flex items-center gap-2 ${activeTab === "downloads" ? "border-[#0056D2] text-[#0056D2]" : "border-transparent text-slate-500 hover:text-slate-800"}`}
              >
                Materi Unduhan{" "}
                {activeModule?.dokumenUrl && (
                  <span className="bg-rose-500 text-white text-[9px] px-1.5 py-0.5 rounded-full">
                    1
                  </span>
                )}
              </button>
              <button
                onClick={() => setActiveTab("qa")}
                className={`pb-4 text-sm font-bold border-b-2 transition-colors whitespace-nowrap flex items-center gap-2 ${activeTab === "qa" ? "border-[#0056D2] text-[#0056D2]" : "border-transparent text-slate-500 hover:text-slate-800"}`}
              >
                Diskusi & Q&A
              </button>
            </div>

            <div className="min-h-[300px]">
              {activeTab === "overview" && (
                <div className="space-y-8">
                  <div className="prose prose-slate max-w-none text-slate-700 text-base leading-relaxed whitespace-pre-wrap">
                    {activeModule?.deskripsi ||
                      "Tidak ada deskripsi spesifik untuk sesi ini."}
                  </div>
                  {mentor && (
                    <div className="pt-8 border-t border-slate-100 flex flex-col sm:flex-row items-start sm:items-center gap-6">
                      <img
                        src={mentor.fotoUrl}
                        alt={mentor.nama}
                        className="w-16 h-16 rounded-full object-cover border border-slate-200 shrink-0"
                      />
                      <div>
                        <p className="text-xs text-slate-500 font-bold uppercase tracking-widest mb-1">
                          Instruktur Pengajar
                        </p>
                        <h3 className="font-bold text-lg text-[#1F2432]">
                          {mentor.nama}, {mentor.gelar}
                        </h3>
                        <p className="text-sm text-slate-600">
                          {mentor.jabatan} di {mentor.perusahaan}
                        </p>
                      </div>
                    </div>
                  )}
                </div>
              )}

              {activeTab === "downloads" && (
                <div>
                  {activeModule?.dokumenUrl ? (
                    <div className="p-5 border border-slate-200 rounded-xl flex flex-col sm:flex-row items-start sm:items-center justify-between bg-white shadow-sm gap-4">
                      <div className="flex items-center gap-4">
                        <div className="w-12 h-12 bg-blue-50 text-[#0056D2] rounded-xl flex items-center justify-center border border-blue-100 shrink-0">
                          <svg
                            className="w-6 h-6"
                            fill="none"
                            viewBox="0 0 24 24"
                            stroke="currentColor"
                          >
                            <path
                              strokeLinecap="round"
                              strokeLinejoin="round"
                              strokeWidth={2}
                              d="M9 12h6m-6 4h6m2 5H7a2 2 0 01-2-2V5a2 2 0 012-2h5.586a1 1 0 01.707.293l5.414 5.414a1 1 0 01.293.707V19a2 2 0 01-2 2z"
                            />
                          </svg>
                        </div>
                        <div>
                          <p className="font-bold text-base text-slate-800">
                            Modul Pendukung Sesi {activeModule?.urutan}
                          </p>
                          <p className="text-[11px] text-slate-500 uppercase tracking-widest mt-0.5">
                            Format: PDF Document
                          </p>
                        </div>
                      </div>
                      <a
                        href={activeModule.dokumenUrl}
                        target="_blank"
                        rel="noreferrer"
                        className="bg-white border border-[#0056D2] text-[#0056D2] hover:bg-blue-50 px-6 py-2.5 rounded-lg text-sm font-bold transition-colors w-full sm:w-auto text-center"
                      >
                        Unduh Berkas
                      </a>
                    </div>
                  ) : (
                    <div className="text-center py-12 bg-slate-50 rounded-xl border border-dashed border-slate-200">
                      <p className="text-sm text-slate-500">
                        Tidak ada berkas materi yang dilampirkan pada modul ini.
                      </p>
                    </div>
                  )}
                </div>
              )}

              {activeTab === "qa" && (
                <div className="space-y-8">
                  <div className="bg-slate-50 p-5 rounded-2xl border border-slate-200">
                    <form onSubmit={handlePostDiscussion}>
                      <textarea
                        rows={3}
                        placeholder="Ada pertanyaan atau diskusi mengenai materi ini? Tulis di sini..."
                        value={newComment}
                        onChange={(e) => setNewComment(e.target.value)}
                        className="w-full bg-white border border-slate-200 px-4 py-3 rounded-xl focus:border-[#0056D2] outline-none text-sm resize-none mb-3"
                        required
                      />
                      <div className="flex justify-between items-center">
                        <p className="text-[10px] text-slate-400 font-bold uppercase tracking-widest">
                          Komentar Publik
                        </p>
                        <button
                          type="submit"
                          disabled={isPosting || !newComment.trim()}
                          className="bg-[#0056D2] hover:bg-[#00419E] text-white px-6 py-2.5 rounded-lg text-sm font-bold transition-all disabled:opacity-50"
                        >
                          {isPosting ? "Mengirim..." : "Kirim Diskusi"}
                        </button>
                      </div>
                    </form>
                  </div>
                  <div className="space-y-5">
                    {discussions.length === 0 ? (
                      <div className="text-center py-12 border border-dashed border-slate-200 rounded-2xl">
                        <p className="text-sm text-slate-500 font-medium">
                          Belum ada diskusi di sesi ini.
                          <br />
                          Jadilah yang pertama untuk bertanya!
                        </p>
                      </div>
                    ) : (
                      discussions.map((diskusi) => (
                        <div
                          key={diskusi.id}
                          className="flex gap-4 pb-5 border-b border-slate-100 last:border-0 last:pb-0"
                        >
                          <div className="w-10 h-10 bg-blue-100 text-[#0056D2] rounded-full flex items-center justify-center font-bold text-sm shrink-0">
                            {(diskusi.userName || "U").charAt(0).toUpperCase()}
                          </div>
                          <div className="flex-1">
                            <div className="flex items-center gap-2 mb-1">
                              <h4 className="font-bold text-slate-800 text-sm">
                                {diskusi.userName}
                              </h4>
                              <span className="text-[10px] text-slate-400 font-medium">
                                {diskusi.createdAt?.seconds
                                  ? new Date(
                                      diskusi.createdAt.seconds * 1000,
                                    ).toLocaleDateString("id-ID", {
                                      day: "numeric",
                                      month: "short",
                                      year: "numeric",
                                      hour: "2-digit",
                                      minute: "2-digit",
                                    })
                                  : "Baru saja"}
                              </span>
                            </div>
                            <p className="text-sm text-slate-600 leading-relaxed whitespace-pre-wrap">
                              {diskusi.text}
                            </p>
                          </div>
                        </div>
                      ))
                    )}
                  </div>
                </div>
              )}
            </div>

            <footer className="mt-16 pt-6 border-t border-slate-200 text-center pb-8">
              <p className="text-xs text-slate-400">
                © {new Date().getFullYear()} DPW IKA UII. Masterclass Learning
                System.
              </p>
            </footer>
          </div>
        </main>

        {/* KANAN: SIDEBAR PLAYLIST */}
        {isSidebarOpen && (
          <aside className="w-full lg:w-[350px] xl:w-[400px] bg-white border-l border-slate-200 flex flex-col shrink-0 z-10">
            <div className="p-6 border-b border-slate-100 bg-[#F8FAFC]">
              <h3 className="font-bold text-slate-900 text-lg mb-4">
                Isi Kursus
              </h3>
              <div className="space-y-2">
                <div className="flex justify-between text-xs font-bold text-slate-600">
                  <span>
                    {validCompletedCount} dari {modules.length} Selesai
                  </span>
                  <span className="text-[#0056D2]">{progressPercentage}%</span>
                </div>
                <div className="w-full h-2 bg-slate-200 rounded-full overflow-hidden">
                  <div
                    className="h-full bg-[#0056D2] transition-all duration-500"
                    style={{ width: `${progressPercentage}%` }}
                  ></div>
                </div>
              </div>
            </div>

            <div className="flex-1 overflow-y-auto custom-scrollbar">
              {modules.length === 0 ? (
                <div className="text-center p-8 text-sm text-slate-500">
                  Belum ada daftar modul.
                </div>
              ) : (
                <div className="divide-y divide-slate-100">
                  {/* GROUPING BAB DI SIDEBAR */}
                  {Object.keys(groupedModules).map((babName, bIdx) => (
                    <div key={bIdx}>
                      <div className="bg-slate-50 px-5 py-3 border-b border-slate-100/50 sticky top-0 z-10">
                        <h3 className="text-xs font-black text-slate-800 uppercase">
                          {babName}
                        </h3>
                      </div>
                      <div className="divide-y divide-slate-50">
                        {groupedModules[babName].map((mod) => {
                          const globalIndex = modules.findIndex(
                            (m) => m.id === mod.id,
                          );
                          const isLocked = isModuleLocked(globalIndex);
                          const isCompleted = completedModules.includes(mod.id);
                          const isActive = activeModule?.id === mod.id;

                          return (
                            <button
                              key={mod.id}
                              disabled={isLocked && !isAdmin}
                              onClick={() => setActiveModule(mod)}
                              className={`w-full text-left px-5 py-4 flex items-start gap-4 transition-colors ${isActive ? "bg-[#E8F0FE] relative" : "hover:bg-slate-50 bg-white"} ${isLocked ? "opacity-60 cursor-not-allowed" : "cursor-pointer"}`}
                            >
                              {isActive && (
                                <div className="absolute left-0 top-0 bottom-0 w-1 bg-[#0056D2]"></div>
                              )}

                              <div className="mt-0.5 shrink-0">
                                {isLocked ? (
                                  <div className="w-5 h-5 rounded bg-slate-200 flex items-center justify-center text-slate-400">
                                    <svg
                                      className="w-3 h-3"
                                      fill="none"
                                      viewBox="0 0 24 24"
                                      stroke="currentColor"
                                    >
                                      <path
                                        strokeLinecap="round"
                                        strokeLinejoin="round"
                                        strokeWidth={2}
                                        d="M12 15v2m-6 4h12a2 2 0 002-2v-6a2 2 0 00-2-2H6a2 2 0 00-2 2v6a2 2 0 002 2zm10-10V7a4 4 0 00-8 0v4h8z"
                                      />
                                    </svg>
                                  </div>
                                ) : isCompleted ? (
                                  <div className="w-5 h-5 rounded bg-emerald-100 flex items-center justify-center text-emerald-600">
                                    <svg
                                      className="w-3.5 h-3.5"
                                      fill="none"
                                      viewBox="0 0 24 24"
                                      stroke="currentColor"
                                    >
                                      <path
                                        strokeLinecap="round"
                                        strokeLinejoin="round"
                                        strokeWidth={3}
                                        d="M5 13l4 4L19 7"
                                      />
                                    </svg>
                                  </div>
                                ) : isActive ? (
                                  <span className="flex w-5 h-5 items-center justify-center rounded-full border-2 border-[#0056D2] text-[#0056D2]">
                                    <div className="w-2 h-2 rounded-full bg-[#0056D2] animate-pulse"></div>
                                  </span>
                                ) : (
                                  <div className="w-5 h-5 rounded border-2 border-slate-300"></div>
                                )}
                              </div>
                              <div className="flex-1 min-w-0">
                                <h4
                                  className={`text-sm font-bold line-clamp-2 leading-snug ${isActive ? "text-[#0056D2]" : "text-slate-700"}`}
                                >
                                  {mod.urutan}. {mod.judul}
                                </h4>
                                <div className="flex items-center gap-1.5 mt-2 text-[10px] uppercase font-bold tracking-widest text-slate-400">
                                  {mod.tipe === "ujian" ? (
                                    <span className="text-rose-500 bg-rose-50 px-1.5 py-0.5 rounded">
                                      📝 Ujian
                                    </span>
                                  ) : mod.tipe === "pdf" ? (
                                    <span className="text-indigo-500 bg-indigo-50 px-1.5 py-0.5 rounded">
                                      📄 PDF
                                    </span>
                                  ) : (
                                    <span className="text-blue-500 bg-blue-50 px-1.5 py-0.5 rounded">
                                      ▶️ Video
                                    </span>
                                  )}
                                </div>
                              </div>
                            </button>
                          );
                        })}
                      </div>
                    </div>
                  ))}
                </div>
              )}
            </div>

            <div className="p-6 bg-white border-t border-slate-200 shrink-0 space-y-4">
              {/* TOMBOL BERI ULASAN */}
              <button
                onClick={() => {
                  if (userReview) {
                    setReviewRating(userReview.rating);
                    setReviewText(userReview.ulasan);
                  }
                  setIsReviewModalOpen(true);
                }}
                className="w-full py-2.5 rounded-lg text-xs font-bold transition-all flex items-center justify-center gap-2 border-2 border-amber-200 text-amber-700 hover:bg-amber-50 shadow-sm"
              >
                <span className="text-amber-500 text-base leading-none">★</span>
                {userReview ? "Edit Ulasan Anda" : "Beri Ulasan Kelas Ini"}
              </button>

              <div
                className={`p-4 rounded-xl border transition-all ${isCourseCompleted ? "bg-emerald-50 border-emerald-200 shadow-sm" : "bg-slate-50 border-slate-200"}`}
              >
                <div className="flex items-center gap-3 mb-3">
                  <div
                    className={`w-10 h-10 rounded-full flex items-center justify-center shrink-0 ${isCourseCompleted ? "bg-emerald-100 text-emerald-600" : "bg-slate-200 text-slate-400"}`}
                  >
                    <svg
                      className="w-5 h-5"
                      fill="currentColor"
                      viewBox="0 0 20 20"
                    >
                      <path
                        fillRule="evenodd"
                        d="M6.267 3.441A11.026 11.026 0 0010 3c1.32 0 2.583.232 3.733.641.34.12.5.5.385.836l-1.372 4.116a2.001 2.001 0 01-1.258 1.258l-4.116 1.372a.5.5 0 01-.641-.385A11.026 11.026 0 013 10c0-1.32.232-2.583.641-3.733.12-.34.5-.5.836-.385l4.116 1.372a2.001 2.001 0 011.258-1.258l1.372-4.116a.5.5 0 01.385-.641z"
                        clipRule="evenodd"
                      />
                    </svg>
                  </div>
                  <div>
                    <h4 className="text-sm font-bold text-slate-800">
                      E-Certificate
                    </h4>
                    <p className="text-[10px] text-slate-500 font-medium">
                      {isCourseCompleted
                        ? "Siap diunduh sekarang"
                        : "Selesaikan semua modul"}
                    </p>
                  </div>
                </div>
                <button
                  disabled={!isCourseCompleted}
                  onClick={() =>
                    router.push(`/masterclass/${courseId}/certificate`)
                  }
                  className={`w-full py-2.5 rounded-lg text-xs font-bold transition-all flex items-center justify-center gap-2 ${isCourseCompleted ? "bg-emerald-600 hover:bg-emerald-700 text-white shadow-md" : "bg-slate-200 text-slate-400 cursor-not-allowed"}`}
                >
                  {isCourseCompleted ? (
                    <>
                      Klaim Sertifikat{" "}
                      <svg
                        className="w-4 h-4"
                        fill="none"
                        viewBox="0 0 24 24"
                        stroke="currentColor"
                      >
                        <path
                          strokeLinecap="round"
                          strokeLinejoin="round"
                          strokeWidth={2}
                          d="M4 16v1a3 3 0 003 3h10a3 3 0 003-3v-1m-4-4l-4 4m0 0l-4-4m4 4V4"
                        />
                      </svg>
                    </>
                  ) : (
                    "Terkunci"
                  )}
                </button>
              </div>
            </div>
          </aside>
        )}
      </div>

      <style jsx global>{`
        .custom-scrollbar::-webkit-scrollbar {
          width: 6px;
        }
        .custom-scrollbar::-webkit-scrollbar-track {
          background: transparent;
        }
        .custom-scrollbar::-webkit-scrollbar-thumb {
          background: #cbd5e1;
          border-radius: 10px;
        }
        .custom-scrollbar::-webkit-scrollbar-thumb:hover {
          background: #94a3b8;
        }
        .no-scrollbar::-webkit-scrollbar {
          display: none;
        }
        .no-scrollbar {
          -ms-overflow-style: none;
          scrollbar-width: none;
        }
      `}</style>
    </div>
  );
}

"use client";

import { useState, useEffect } from "react";
import { toast } from "@/lib/toast";
import { useRouter } from "next/navigation";
import { auth, db } from "@/lib/firebase";
import { onAuthStateChanged, updateProfile } from "firebase/auth";
import {
  collection,
  query,
  where,
  getDocs,
  doc,
  getDoc,
  setDoc,
  serverTimestamp,
} from "firebase/firestore";
import NavbarMasterclass from "@/components/layout/NavbarMasterclass";
import FooterPublic from "@/components/layout/FooterPublic";
import Link from "next/link";

export default function MyCoursesPage() {
  const router = useRouter();
  const [currentUser, setCurrentUser] = useState<any>(null);
  const [isLoading, setIsLoading] = useState(true);

  // Data State
  const [enrollments, setEnrollments] = useState<any[]>([]);
  const [coursesMap, setCoursesMap] = useState<Record<string, any>>({});
  const [progressMap, setProgressMap] = useState<
    Record<string, { completed: number; total: number }>
  >({});

  // 🔥 PERBAIKAN: Menambahkan "sertifikat" ke dalam type activeTab
  const [activeTab, setActiveTab] = useState<
    "kelas" | "sertifikat" | "transaksi" | "profil"
  >("kelas");

  // Profile Form State
  const [profileForm, setProfileForm] = useState({
    nama: "",
    noHp: "",
    instansi: "",
  });
  const [isSavingProfile, setIsSavingProfile] = useState(false);

  useEffect(() => {
    const unsubscribe = onAuthStateChanged(auth, async (user) => {
      if (!user) {
        router.push("/login");
        return;
      }
      setCurrentUser(user);
      await fetchDashboardData(user);
    });
    return () => unsubscribe();
  }, [router]);

  const fetchDashboardData = async (user: any) => {
    setIsLoading(true);
    try {
      // 1. Tarik Data Profil dari tabel peserta_umum
      const userRef = doc(db, "peserta_umum", user.uid);
      const userSnap = await getDoc(userRef);
      if (userSnap.exists()) {
        setProfileForm({
          nama: userSnap.data().nama || user.displayName || "",
          noHp: userSnap.data().noHp || "",
          instansi: userSnap.data().instansi || "",
        });
      } else {
        setProfileForm({
          nama: user.displayName || "",
          noHp: "",
          instansi: "",
        });
      }

      // 2. Tarik Data Enrollments (Transaksi user ini)
      const qEnroll = query(
        collection(db, "masterclass_enrollments"),
        where("uid", "==", user.uid),
      );
      const snapEnroll = await getDocs(qEnroll);
      const enrollData = snapEnroll.docs
        .map((d) => ({ id: d.id, ...d.data() }))
        .sort(
          (a: any, b: any) =>
            (b.createdAt?.seconds || 0) - (a.createdAt?.seconds || 0),
        );
      setEnrollments(enrollData);

      // Extract unique Course IDs
      const cIds = [...new Set(enrollData.map((e: any) => e.courseId))];

      // 3. Tarik Data Kelas (Untuk nerjemahin ID ke Judul & Gambar)
      const cMap: Record<string, any> = {};
      const snapCourses = await getDocs(collection(db, "masterclass_courses"));
      snapCourses.forEach((d) => {
        cMap[d.id] = d.data();
      });
      setCoursesMap(cMap);

      // 4. Hitung Total Modul per Kelas
      const moduleCount: Record<string, number> = {};
      const snapModules = await getDocs(collection(db, "masterclass_modules"));
      snapModules.forEach((d) => {
        const cId = d.data().courseId;
        moduleCount[cId] = (moduleCount[cId] || 0) + 1;
      });

      // 5. Tarik Progres Belajar Siswa
      const pMap: Record<string, { completed: number; total: number }> = {};
      for (const cid of cIds) {
        const pRef = doc(db, "masterclass_progress", `${user.uid}_${cid}`);
        const pSnap = await getDoc(pRef);
        pMap[cid] = {
          completed: pSnap.exists()
            ? pSnap.data().completedModules?.length || 0
            : 0,
          total: moduleCount[cid] || 1, // Hindari pembagian 0
        };
      }
      setProgressMap(pMap);
    } catch (error) {
      console.error("Gagal memuat dashboard:", error);
    } finally {
      setIsLoading(false);
    }
  };

  const handleSaveProfile = async (e: React.FormEvent) => {
    e.preventDefault();
    setIsSavingProfile(true);
    try {
      // 1. Update ke Firebase Auth (Biar namanya ganti di pojok kanan atas)
      await updateProfile(auth.currentUser!, { displayName: profileForm.nama });

      // 2. Simpan ke database peserta_umum
      await setDoc(
        doc(db, "peserta_umum", currentUser.uid),
        {
          uid: currentUser.uid,
          email: currentUser.email,
          nama: profileForm.nama,
          noHp: profileForm.noHp,
          instansi: profileForm.instansi,
          updatedAt: serverTimestamp(),
        },
        { merge: true },
      );

      toast.success("Profil berhasil diperbarui!");
      // Refresh state lokal
      setCurrentUser({ ...currentUser, displayName: profileForm.nama });
    } catch (error) {
      toast.error("Gagal menyimpan profil.");
    } finally {
      setIsSavingProfile(false);
    }
  };

  if (isLoading) {
    return (
      <div className="min-h-screen flex flex-col items-center justify-center bg-slate-50 font-sans">
        <div className="w-12 h-12 border-4 border-slate-200 border-t-[#0056D2] rounded-full animate-spin mb-4"></div>
        <p className="font-bold text-slate-500 text-sm">
          Memuat Dashboard Anda...
        </p>
      </div>
    );
  }

  return (
    <div className="bg-[#F5F7FA] min-h-screen font-sans text-slate-800 flex flex-col">
      <NavbarMasterclass />

      <main className="flex-grow pt-24 pb-20">
        <div className="max-w-[1200px] mx-auto px-4 sm:px-6 lg:px-8">
          {/* HEADER DASHBOARD */}
          <div className="bg-white rounded-3xl p-8 border border-slate-200 shadow-sm flex flex-col md:flex-row items-center justify-between gap-6 mb-8">
            <div className="flex items-center gap-5">
              <div className="w-16 h-16 rounded-full bg-[#0056D2] text-white flex items-center justify-center text-2xl font-black shadow-lg">
                {(currentUser?.displayName || "S").charAt(0).toUpperCase()}
              </div>
              <div>
                <h1 className="text-2xl font-black text-slate-900">
                  Halo, {currentUser?.displayName || "Siswa"}!
                </h1>
                <p className="text-slate-500 font-medium text-sm">
                  Selamat datang di Ruang Belajar Masterclass Anda.
                </p>
              </div>
            </div>
            <div className="flex gap-4">
              <div className="bg-blue-50 border border-blue-100 px-6 py-3 rounded-2xl text-center">
                <p className="text-[10px] font-black uppercase text-blue-600 tracking-widest">
                  Kelas Saya
                </p>
                <p className="text-2xl font-black text-blue-900">
                  {enrollments.filter((e) => e.statusAkses === "Lunas").length}
                </p>
              </div>
              <div className="bg-emerald-50 border border-emerald-100 px-6 py-3 rounded-2xl text-center">
                <p className="text-[10px] font-black uppercase text-emerald-600 tracking-widest">
                  Sertifikat
                </p>
                <p className="text-2xl font-black text-emerald-900">
                  {
                    enrollments.filter(
                      (e) =>
                        progressMap[e.courseId]?.completed ===
                          progressMap[e.courseId]?.total &&
                        e.statusAkses === "Lunas",
                    ).length
                  }
                </p>
              </div>
            </div>
          </div>

          {/* TAB NAVIGASI */}
          <div className="flex gap-6 border-b border-slate-200 mb-8 overflow-x-auto no-scrollbar">
            <button
              onClick={() => setActiveTab("kelas")}
              className={`pb-4 text-sm font-bold border-b-2 transition-colors whitespace-nowrap ${activeTab === "kelas" ? "border-[#0056D2] text-[#0056D2]" : "border-transparent text-slate-500 hover:text-slate-800"}`}
            >
              Kelas Saya
            </button>
            {/* 🔥 TAMBAHAN TAB SERTIFIKAT 🔥 */}
            <button
              onClick={() => setActiveTab("sertifikat")}
              className={`pb-4 text-sm font-bold border-b-2 transition-colors whitespace-nowrap flex items-center gap-1.5 ${activeTab === "sertifikat" ? "border-emerald-600 text-emerald-600" : "border-transparent text-slate-500 hover:text-slate-800"}`}
            >
              Daftar Sertifikat
            </button>
            <button
              onClick={() => setActiveTab("transaksi")}
              className={`pb-4 text-sm font-bold border-b-2 transition-colors whitespace-nowrap ${activeTab === "transaksi" ? "border-[#0056D2] text-[#0056D2]" : "border-transparent text-slate-500 hover:text-slate-800"}`}
            >
              Riwayat Transaksi
            </button>
            <button
              onClick={() => setActiveTab("profil")}
              className={`pb-4 text-sm font-bold border-b-2 transition-colors whitespace-nowrap ${activeTab === "profil" ? "border-[#0056D2] text-[#0056D2]" : "border-transparent text-slate-500 hover:text-slate-800"}`}
            >
              Pengaturan Profil
            </button>
          </div>

          {/* KONTEN TAB: KELAS SAYA */}
          {activeTab === "kelas" && (
            <div className="space-y-6">
              {enrollments.length === 0 ? (
                <div className="bg-white rounded-3xl p-12 text-center border border-slate-200 shadow-sm">
                  <div className="w-20 h-20 bg-slate-50 rounded-full flex items-center justify-center mx-auto mb-4 text-3xl">
                    📚
                  </div>
                  <h3 className="text-lg font-bold text-slate-800 mb-2">
                    Belum ada kelas yang diikuti
                  </h3>
                  <p className="text-slate-500 mb-6 text-sm">
                    Jelajahi katalog kami dan temukan keahlian baru untuk
                    dikuasai.
                  </p>
                  <Link
                    href="/masterclass"
                    className="bg-[#0056D2] text-white px-6 py-3 rounded-xl font-bold text-sm hover:bg-[#00419E] transition-colors"
                  >
                    Eksplorasi Katalog
                  </Link>
                </div>
              ) : (
                <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
                  {enrollments.map((e) => {
                    const courseInfo = coursesMap[e.courseId];
                    const progress = progressMap[e.courseId];
                    const percentage = progress
                      ? Math.round((progress.completed / progress.total) * 100)
                      : 0;
                    const isLunas = e.statusAkses === "Lunas";

                    return (
                      <div
                        key={e.id}
                        className="bg-white rounded-2xl overflow-hidden border border-slate-200 shadow-sm hover:shadow-lg transition-all group flex flex-col"
                      >
                        <div className="aspect-[4/3] bg-slate-100 relative">
                          {courseInfo?.thumbnailUrl ? (
                            <img
                              src={courseInfo.thumbnailUrl}
                              className="w-full h-full object-cover group-hover:scale-105 transition-transform duration-500"
                              alt="Cover"
                            />
                          ) : (
                            <div className="w-full h-full flex items-center justify-center text-slate-400 font-medium">
                              Cover Kelas
                            </div>
                          )}

                          {/* Badge Status */}
                          <div className="absolute top-3 left-3">
                            {isLunas ? (
                              <span className="bg-emerald-500 text-white text-[10px] font-black px-2.5 py-1 rounded shadow-sm">
                                AKSES TERBUKA
                              </span>
                            ) : e.statusAkses === "Batal" ? (
                              <span className="bg-rose-500 text-white text-[10px] font-black px-2.5 py-1 rounded shadow-sm">
                                DIBATALKAN
                              </span>
                            ) : (
                              <span className="bg-amber-500 text-white text-[10px] font-black px-2.5 py-1 rounded shadow-sm animate-pulse">
                                MENUNGGU VERIFIKASI
                              </span>
                            )}
                          </div>
                        </div>

                        <div className="p-5 flex flex-col flex-grow">
                          <h3 className="font-bold text-slate-800 mb-4 line-clamp-2 leading-snug">
                            {courseInfo?.judul || "Kelas Tidak Ditemukan"}
                          </h3>

                          {isLunas ? (
                            <div className="mt-auto">
                              <div className="flex justify-between text-[10px] font-bold text-slate-500 mb-1.5 uppercase tracking-widest">
                                <span>Progres Belajar</span>
                                <span className="text-[#0056D2]">
                                  {percentage}%
                                </span>
                              </div>
                              <div className="w-full h-2 bg-slate-100 rounded-full overflow-hidden mb-4">
                                <div
                                  className="h-full bg-[#0056D2] transition-all duration-1000"
                                  style={{ width: `${percentage}%` }}
                                ></div>
                              </div>
                              <button
                                onClick={() =>
                                  router.push(
                                    `/masterclass/${e.courseId}/learn`,
                                  )
                                }
                                className="w-full py-2.5 bg-blue-50 hover:bg-[#0056D2] text-[#0056D2] hover:text-white font-bold text-xs rounded-xl transition-colors border border-blue-100 hover:border-[#0056D2]"
                              >
                                {percentage === 0
                                  ? "Mulai Belajar"
                                  : percentage === 100
                                    ? "Tonton Ulang & Sertifikat"
                                    : "Lanjutkan Belajar"}
                              </button>
                            </div>
                          ) : (
                            <div className="mt-auto bg-slate-50 border border-slate-100 p-3 rounded-xl text-center">
                              <p className="text-[11px] text-slate-500 font-medium mb-2 leading-relaxed">
                                Admin sedang melakukan pengecekan terhadap
                                transaksi Anda.
                              </p>
                              <a
                                href="https://wa.me/6281234567890" // Ganti dengan nomor WA admin
                                target="_blank"
                                rel="noreferrer"
                                className="text-xs font-bold text-emerald-600 hover:underline"
                              >
                                Hubungi Admin via WA
                              </a>
                            </div>
                          )}
                        </div>
                      </div>
                    );
                  })}
                </div>
              )}
            </div>
          )}

          {/* 🔥 KONTEN TAB: SERTIFIKAT 🔥 */}
          {activeTab === "sertifikat" && (
            <div className="space-y-6">
              {(() => {
                // Filter kelas yang Lunas DAN Progres 100%
                const completedCourses = enrollments.filter(
                  (e) =>
                    progressMap[e.courseId]?.completed ===
                      progressMap[e.courseId]?.total &&
                    e.statusAkses === "Lunas",
                );

                if (completedCourses.length === 0) {
                  return (
                    <div className="bg-white rounded-3xl p-12 text-center border border-slate-200 shadow-sm max-w-2xl mx-auto">
                      <div className="w-20 h-20 bg-emerald-50 text-emerald-500 rounded-full flex items-center justify-center mx-auto mb-4 text-4xl">
                        🎓
                      </div>
                      <h3 className="text-lg font-bold text-slate-800 mb-2">
                        Belum Ada Sertifikat Kelulusan
                      </h3>
                      <p className="text-slate-500 text-sm max-w-md mx-auto mb-6 leading-relaxed">
                        Selesaikan 100% progres belajar pada modul kelas yang
                        Anda ikuti untuk mengklaim dan mengunduh E-Certificate
                        secara otomatis.
                      </p>
                      <button
                        onClick={() => setActiveTab("kelas")}
                        className="bg-emerald-600 text-white px-8 py-3 rounded-xl font-bold text-sm hover:bg-emerald-700 transition-colors shadow-md"
                      >
                        Lanjut Belajar
                      </button>
                    </div>
                  );
                }

                return (
                  <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-6">
                    {completedCourses.map((e) => {
                      const courseInfo = coursesMap[e.courseId];
                      return (
                        <div
                          key={e.id}
                          className="bg-white rounded-2xl overflow-hidden border border-slate-200 shadow-sm hover:shadow-lg transition-all group flex flex-col p-6 relative"
                        >
                          {/* Hiasan Background Pojok Kanan Atas */}
                          <div className="absolute top-0 right-0 w-28 h-28 bg-emerald-50 rounded-bl-full -z-0"></div>

                          <div className="w-14 h-14 bg-emerald-100 text-emerald-600 rounded-2xl flex items-center justify-center text-2xl mb-6 shadow-inner z-10 relative">
                            📜
                          </div>

                          <div className="z-10 relative flex-grow">
                            <h3 className="font-bold text-slate-800 mb-2 line-clamp-2 leading-snug">
                              {courseInfo?.judul || "Kelas Tidak Diketahui"}
                            </h3>
                            <div className="flex items-center gap-1.5 mb-6">
                              <span className="flex w-2 h-2 rounded-full bg-emerald-500"></span>
                              <p className="text-[10px] text-emerald-600 font-bold uppercase tracking-widest">
                                Telah Diselesaikan
                              </p>
                            </div>
                          </div>

                          <div className="z-10 relative mt-auto">
                            <Link
                              href={`/masterclass/${e.courseId}/certificate`}
                              className="flex items-center justify-center gap-2 w-full py-3.5 bg-[#0B1120] hover:bg-slate-800 text-white font-bold text-xs rounded-xl transition-colors shadow-md"
                            >
                              <svg
                                className="w-4 h-4"
                                fill="none"
                                viewBox="0 0 24 24"
                                stroke="currentColor"
                              >
                                <path
                                  strokeLinecap="round"
                                  strokeLinejoin="round"
                                  strokeWidth={2.5}
                                  d="M4 16v1a3 3 0 003 3h10a3 3 0 003-3v-1m-4-4l-4 4m0 0l-4-4m4 4V4"
                                />
                              </svg>
                              Unduh E-Certificate
                            </Link>
                          </div>
                        </div>
                      );
                    })}
                  </div>
                );
              })()}
            </div>
          )}

          {/* KONTEN TAB: RIWAYAT TRANSAKSI */}
          {activeTab === "transaksi" && (
            <div className="bg-white rounded-3xl border border-slate-200 shadow-sm overflow-hidden">
              <div className="overflow-x-auto">
                <table className="w-full text-left text-sm border-collapse">
                  <thead>
                    <tr className="bg-slate-50/80 text-[10px] font-black uppercase text-slate-500 tracking-widest border-b border-slate-200">
                      <th className="px-6 py-5">Tanggal & ID</th>
                      <th className="px-6 py-5">Detail Kelas</th>
                      <th className="px-6 py-5">Total Pembayaran</th>
                      <th className="px-6 py-5">Status</th>
                    </tr>
                  </thead>
                  <tbody className="divide-y divide-slate-100">
                    {enrollments.length === 0 ? (
                      <tr>
                        <td
                          colSpan={4}
                          className="py-12 text-center text-slate-500"
                        >
                          Belum ada riwayat transaksi.
                        </td>
                      </tr>
                    ) : (
                      enrollments.map((e) => (
                        <tr
                          key={e.id}
                          className="hover:bg-slate-50/50 transition-colors"
                        >
                          <td className="px-6 py-5 align-top">
                            <div className="font-bold text-slate-800">
                              {e.createdAt?.seconds
                                ? new Date(
                                    e.createdAt.seconds * 1000,
                                  ).toLocaleDateString("id-ID", {
                                    day: "numeric",
                                    month: "short",
                                    year: "numeric",
                                  })
                                : "Baru saja"}
                            </div>
                            <div className="text-[10px] text-slate-400 font-mono mt-0.5">
                              INV-{e.id.substring(0, 8).toUpperCase()}
                            </div>
                          </td>
                          <td className="px-6 py-5 align-top max-w-xs">
                            <div className="font-bold text-slate-800 line-clamp-2 leading-snug">
                              {coursesMap[e.courseId]?.judul ||
                                "Kelas Tidak Diketahui"}
                            </div>
                            <div className="text-[10px] text-slate-500 mt-1 uppercase tracking-widest bg-slate-100 inline-block px-2 py-0.5 rounded">
                              {e.tipeHarga}
                            </div>
                          </td>
                          <td className="px-6 py-5 align-top">
                            <div className="font-black text-slate-800">
                              Rp{" "}
                              {(e.hargaTransaksi || 0).toLocaleString("id-ID")}
                            </div>
                          </td>
                          <td className="px-6 py-5 align-top">
                            <span
                              className={`text-[10px] font-black px-3 py-1.5 rounded-md uppercase tracking-wider ${e.statusAkses === "Lunas" ? "bg-emerald-100 text-emerald-700" : e.statusAkses === "Pending" ? "bg-amber-100 text-amber-700" : "bg-rose-100 text-rose-700"}`}
                            >
                              {e.statusAkses}
                            </span>
                          </td>
                        </tr>
                      ))
                    )}
                  </tbody>
                </table>
              </div>
            </div>
          )}

          {/* KONTEN TAB: PENGATURAN PROFIL */}
          {activeTab === "profil" && (
            <div className="bg-white rounded-3xl border border-slate-200 shadow-sm p-6 sm:p-10 max-w-2xl">
              <h2 className="text-xl font-black text-slate-900 mb-6 border-b border-slate-100 pb-4">
                Informasi Akun
              </h2>

              <form onSubmit={handleSaveProfile} className="space-y-6">
                <div>
                  <label className="block text-[11px] font-bold text-slate-500 uppercase tracking-widest mb-2 ml-1">
                    Email (Akun Login)
                  </label>
                  <input
                    type="email"
                    value={currentUser?.email || ""}
                    disabled
                    className="w-full bg-slate-100 border border-slate-200 px-4 py-3 rounded-xl text-sm font-medium text-slate-500 cursor-not-allowed outline-none"
                  />
                  <p className="text-[10px] text-rose-500 font-bold mt-2 ml-1">
                    * Hubungi Administrator jika Anda ingin mengubah alamat
                    email login.
                  </p>
                </div>

                <div>
                  <label className="block text-[11px] font-bold text-slate-500 uppercase tracking-widest mb-2 ml-1">
                    Nama Lengkap
                  </label>
                  <input
                    type="text"
                    required
                    value={profileForm.nama}
                    onChange={(e) =>
                      setProfileForm({ ...profileForm, nama: e.target.value })
                    }
                    className="w-full bg-white border border-slate-300 px-4 py-3 rounded-xl text-sm font-bold text-slate-800 outline-none focus:border-[#0056D2] transition-colors"
                  />
                </div>

                <div className="grid grid-cols-1 sm:grid-cols-2 gap-6">
                  <div>
                    <label className="block text-[11px] font-bold text-slate-500 uppercase tracking-widest mb-2 ml-1">
                      Nomor WhatsApp
                    </label>
                    <input
                      type="tel"
                      value={profileForm.noHp}
                      onChange={(e) =>
                        setProfileForm({ ...profileForm, noHp: e.target.value })
                      }
                      className="w-full bg-white border border-slate-300 px-4 py-3 rounded-xl text-sm font-bold text-slate-800 outline-none focus:border-[#0056D2] transition-colors"
                      placeholder="0812..."
                    />
                  </div>
                  <div>
                    <label className="block text-[11px] font-bold text-slate-500 uppercase tracking-widest mb-2 ml-1">
                      Asal Instansi / Universitas
                    </label>
                    <input
                      type="text"
                      value={profileForm.instansi}
                      onChange={(e) =>
                        setProfileForm({
                          ...profileForm,
                          instansi: e.target.value,
                        })
                      }
                      className="w-full bg-white border border-slate-300 px-4 py-3 rounded-xl text-sm font-bold text-slate-800 outline-none focus:border-[#0056D2] transition-colors"
                      placeholder="Opsional"
                    />
                  </div>
                </div>

                <div className="pt-4">
                  <button
                    type="submit"
                    disabled={isSavingProfile}
                    className="w-full sm:w-auto bg-[#0B1120] hover:bg-slate-800 text-white px-8 py-3.5 rounded-xl font-bold text-sm transition-all disabled:opacity-50"
                  >
                    {isSavingProfile
                      ? "Menyimpan Perubahan..."
                      : "Simpan Pengaturan"}
                  </button>
                </div>
              </form>
            </div>
          )}
        </div>
      </main>

      <FooterPublic />

      <style jsx global>{`
        .no-scrollbar::-webkit-scrollbar {
          display: none;
        }
        .no-scrollbar {
          -ms-overflow-style: none;
          scrollbar-width: none;
        }
      `}</style>
    </div>
  );
}

"use client";

import { useState, useEffect, useMemo } from "react";
