"use client";

import { useEffect, useState, useRef } from "react";
import { toast } from "@/lib/toast";
import { db } from "@/lib/firebase";
import { doc, getDoc, updateDoc } from "firebase/firestore";
import { useParams, useRouter } from "next/navigation";
import html2canvas from "html2canvas";
import dynamic from "next/dynamic";

const MapRoute = dynamic(() => import("@/components/MapRoute"), { ssr: false });

const decodePolyline = (str: string, precision = 5) => {
  let index = 0,
    lat = 0,
    lng = 0,
    coordinates: [number, number][] = [];
  let shift = 0,
    result = 0,
    byte = null,
    latitude_change,
    longitude_change,
    factor = Math.pow(10, precision);
  while (index < str.length) {
    byte = null;
    shift = 0;
    result = 0;
    do {
      byte = str.charCodeAt(index++) - 63;
      result |= (byte & 0x1f) << shift;
      shift += 5;
    } while (byte >= 0x20);
    latitude_change = result & 1 ? ~(result >> 1) : result >> 1;
    shift = result = 0;
    do {
      byte = str.charCodeAt(index++) - 63;
      result |= (byte & 0x1f) << shift;
      shift += 5;
    } while (byte >= 0x20);
    longitude_change = result & 1 ? ~(result >> 1) : result >> 1;
    lat += latitude_change;
    lng += longitude_change;
    coordinates.push([lat / factor, lng / factor]);
  }
  return coordinates;
};

export default function StravaStudioPage() {
  const params = useParams();
  const router = useRouter();
  const id = params.id as string;
  const cardRef = useRef<HTMLDivElement>(null);

  // =========================================================================
  // 🔥 SETTING ANTI-CHEAT (PENGATURAN TANGGAL EVENT) 🔥
  // =========================================================================
  // ⚠️ GANTI TANGGAL INI SESUAI TANGGAL ASLI EVENT UII SEHAT 2026 (Format: YYYY-MM-DD)
  // Jika event hanya 1 hari, isi START dan END dengan tanggal yang sama.
  const EVENT_START_DATE = "2026-08-16";
  const EVENT_END_DATE = "2026-08-16";
  // =========================================================================

  const [isLoading, setIsLoading] = useState(true);
  const [isDownloading, setIsDownloading] = useState(false);
  const [errorMsg, setErrorMsg] = useState("");

  const [isSubmitting, setIsSubmitting] = useState(false);
  const [isSubmitted, setIsSubmitted] = useState(false);

  const [participant, setParticipant] = useState<any>(null);
  const [activities, setActivities] = useState<any[]>([]);
  const [activity, setActivity] = useState<any>(null);
  const [theme, setTheme] = useState<"dark" | "light">("dark");

  useEffect(() => {
    const fetchStravaData = async () => {
      try {
        const docRef = doc(db, "offline_participants", id);
        const docSnap = await getDoc(docRef);

        if (!docSnap.exists() || !docSnap.data().strava_access_token) {
          setErrorMsg("Data peserta atau token Strava tidak valid.");
          setIsLoading(false);
          return;
        }

        const dataPeserta = docSnap.data();
        setParticipant(dataPeserta);

        if (dataPeserta.isStravaVerified) {
          setIsSubmitted(true);
        }

        const res = await fetch(
          "https://www.strava.com/api/v3/athlete/activities?per_page=30",
          {
            headers: {
              Authorization: `Bearer ${dataPeserta.strava_access_token}`,
            },
          },
        );

        const stravaData = await res.json();

        if (!res.ok || !Array.isArray(stravaData) || stravaData.length === 0) {
          setErrorMsg("Gagal mengambil data atau belum ada aktivitas lari.");
          setIsLoading(false);
          return;
        }

        const runs = stravaData.filter((act: any) => act.type === "Run");

        if (runs.length === 0) {
          toast.warning("Semua data aktivitas belum termuat, mohon tunggu sebentar atau muat ulang halaman.");
          return;
        }

        setActivities(runs);
        setActivity(runs[0]);
      } catch (error) {
        console.error("Error fetching data:", error);
        setErrorMsg("Terjadi kesalahan sistem saat menghubungi Strava.");
      } finally {
        setIsLoading(false);
      }
    };

    if (id) fetchStravaData();
  }, [id]);

  const calculatePace = (meters: number, seconds: number) => {
    if (!meters || !seconds) return "0:00";
    const paceSeconds = Math.floor(seconds / (meters / 1000));
    return `${Math.floor(paceSeconds / 60)}:${(paceSeconds % 60).toString().padStart(2, "0")}`;
  };

  const formatDate = (dateStr: string) => {
    if (!dateStr) return "";
    return new Date(dateStr)
      .toLocaleDateString("id-ID", {
        month: "short",
        day: "numeric",
        year: "numeric",
      })
      .toUpperCase();
  };

  // Fungsi Validasi Tanggal
  const checkIsEventDate = (dateString: string) => {
    if (!dateString) return false;
    // Potong string untuk mengambil format YYYY-MM-DD saja dari Strava (contoh: 2026-08-16T06:00:00Z)
    const datePart = dateString.split("T")[0];
    return datePart >= EVENT_START_DATE && datePart <= EVENT_END_DATE;
  };

  // Mengecek apakah aktivitas yang dipilih valid masuk Leaderboard
  const isActivityValidForLeaderboard = activity
    ? checkIsEventDate(activity.start_date_local || activity.start_date)
    : false;

  const handleDownload = async () => {
    if (!cardRef.current) return;
    setIsDownloading(true);

    try {
      await new Promise((r) => setTimeout(r, 600));

      const canvas = await html2canvas(cardRef.current, {
        scale: 3,
        useCORS: true,
        allowTaint: true,
        backgroundColor: theme === "dark" ? "#0A0A0A" : "#FFFFFF",
      });

      const dataUrl = canvas.toDataURL("image/png");
      const link = document.createElement("a");
      link.download = `UII_Sehat_${participant.nomorBIB}_${activity.id}.png`;
      link.href = dataUrl;
      link.click();
    } catch (err) {
      console.error("Gagal memproses gambar:", err);
      toast.error("Terjadi kesalahan memotret peta. Silakan coba lagi.");
    } finally {
      setIsDownloading(false);
    }
  };

  const handleSubmitToLeaderboard = async () => {
    if (!activity) return;

    const netTimeMs = activity.elapsed_time * 1000;
    const paceStr = calculatePace(activity.distance, activity.moving_time);
    const jarakKm = (activity.distance / 1000).toFixed(2);

    const isConfirmed = window.confirm(
      `Setor Waktu ke Leaderboard?\n\nJarak: ${jarakKm} KM\nPace: ${paceStr}/KM\n\nData yang disetor akan dikunci dan tidak bisa diubah. Lanjutkan?`,
    );

    if (!isConfirmed) return;

    setIsSubmitting(true);
    try {
      const docRef = doc(db, "offline_participants", id);

      await updateDoc(docRef, {
        netTimeMs: netTimeMs,
        isStravaVerified: true,
        stravaActivityId: activity.id,
        waktuFinish: new Date(activity.start_date).getTime() + netTimeMs,
      });

      setIsSubmitted(true);
      toast.success("✅ Berhasil! Nama Anda sudah melesat masuk ke Leaderboard IKA UII DIY dengan lencana Strava!");
    } catch (error) {
      console.error("Gagal setor ke leaderboard:", error);
      toast.error("Gagal menyetor data. Pastikan koneksi internet stabil.");
    } finally {
      setIsSubmitting(false);
    }
  };

  if (isLoading || errorMsg) {
    return (
      <div className="h-screen w-screen bg-[#0a0a0a] flex flex-col items-center justify-center font-sans">
        {errorMsg ? (
          <div className="bg-white/10 backdrop-blur-md p-8 rounded-3xl text-center max-w-sm border border-white/10">
            <p className="text-rose-400 font-medium">{errorMsg}</p>
          </div>
        ) : (
          <>
            <div className="w-10 h-10 border-2 border-white/20 border-t-[#FC4C02] rounded-full animate-spin mb-4"></div>
            <p className="text-white/50 text-xs font-bold tracking-widest uppercase">
              Sinkronisasi Strava
            </p>
          </>
        )}
      </div>
    );
  }

  const coordinates = activity?.map?.summary_polyline
    ? decodePolyline(activity.map.summary_polyline)
    : [];

  return (
    <div className="min-h-screen w-full bg-[#EAECEF] flex flex-col font-sans relative pb-10">
      <div className="w-full bg-white border-b border-slate-200 px-6 py-4 flex justify-between items-center shadow-sm z-30 sticky top-0">
        <button
          onClick={() => router.push("/run/strava")}
          className="text-slate-500 hover:text-slate-800 font-bold text-sm flex items-center gap-2 transition-colors"
        >
          <svg
            className="w-4 h-4"
            fill="none"
            viewBox="0 0 24 24"
            stroke="currentColor"
          >
            <path
              strokeLinecap="round"
              strokeLinejoin="round"
              strokeWidth={2.5}
              d="M15 19l-7-7 7-7"
            />
          </svg>
          Kembali
        </button>
        <div className="font-black text-slate-800 tracking-tight text-lg">
          RUN<span className="text-[#FC4C02]">STUDIO</span>
        </div>
        <div className="w-20"></div>
      </div>

      <div className="flex flex-col lg:flex-row items-center lg:items-start justify-center gap-10 mt-8 px-4 max-w-6xl mx-auto w-full">
        {/* KOLOM KIRI: KANVAS KARTU IG STORY */}
        <div className="flex flex-col items-center shrink-0">
          <div className="shadow-[0_20px_50px_rgba(0,0,0,0.15)] rounded-[2.5rem] p-2 bg-white/50 backdrop-blur-xl border border-white">
            <div
              ref={cardRef}
              className={`w-[360px] h-[640px] rounded-[2rem] overflow-hidden flex flex-col relative ${theme === "dark" ? "bg-[#0A0A0A] text-white" : "bg-white text-slate-900"} transition-colors duration-500`}
            >
              <div className="relative h-[55%] w-full bg-slate-100">
                <MapRoute coords={coordinates} theme={theme} />
                <div
                  className={`absolute bottom-0 left-0 w-full h-32 bg-gradient-to-t ${theme === "dark" ? "from-[#0A0A0A]" : "from-white"} to-transparent z-[400] pointer-events-none`}
                ></div>
                <div className="absolute top-6 right-6 opacity-30 shadow-md bg-white/10 p-2 rounded-xl backdrop-blur-md z-[400]">
                  <svg
                    className={`w-4 h-4 ${theme === "dark" ? "text-white" : "text-[#FC4C02]"}`}
                    viewBox="0 0 24 24"
                    fill="currentColor"
                  >
                    <path d="M15.387 17.944l-2.089-4.116h-3.065L15.387 24l5.15-10.172h-3.066m-7.008-5.599l2.836 5.598h4.172L10.463 0l-7 13.828h4.169" />
                  </svg>
                </div>
              </div>

              <div className="relative z-[500] flex-1 flex flex-col px-8 pb-6 justify-end -mt-8 pointer-events-none">
                <div className="mb-6">
                  <h2 className="text-[28px] font-black tracking-tighter leading-tight mb-1 line-clamp-2">
                    {activity.name}
                  </h2>
                  <div
                    className={`flex items-center gap-2 font-bold text-[10px] uppercase tracking-widest ${theme === "dark" ? "text-white/50" : "text-slate-400"}`}
                  >
                    <svg
                      className="w-3.5 h-3.5"
                      fill="none"
                      viewBox="0 0 24 24"
                      stroke="currentColor"
                    >
                      <path
                        strokeLinecap="round"
                        strokeLinejoin="round"
                        strokeWidth={2.5}
                        d="M17.657 16.657L13.414 20.9a1.998 1.998 0 01-2.827 0l-4.244-4.243a8 8 0 1111.314 0z"
                      />
                      <path
                        strokeLinecap="round"
                        strokeLinejoin="round"
                        strokeWidth={2.5}
                        d="M15 11a3 3 0 11-6 0 3 3 0 016 0z"
                      />
                    </svg>
                    <span>
                      {participant.namaLengkap} • BIB {participant.nomorBIB}
                    </span>
                  </div>
                </div>

                <div className="mb-8">
                  <p
                    className={`text-[9px] font-black uppercase tracking-[0.2em] mb-1 ${theme === "dark" ? "text-white/40" : "text-slate-400"}`}
                  >
                    Distance
                  </p>
                  <p className="text-[56px] font-black leading-none tracking-tighter">
                    {(activity.distance / 1000).toFixed(2)}
                    <span className="text-xl font-bold ml-1 opacity-50 tracking-normal">
                      KM
                    </span>
                  </p>
                </div>

                <div className="grid grid-cols-2 gap-4 mb-6">
                  <div>
                    <p
                      className={`text-[9px] font-black uppercase tracking-[0.2em] mb-1 ${theme === "dark" ? "text-white/40" : "text-slate-400"}`}
                    >
                      Avg Pace
                    </p>
                    <p className="text-2xl font-black tracking-tight">
                      {calculatePace(activity.distance, activity.moving_time)}
                      <span className="text-sm font-bold ml-1 opacity-50">
                        /KM
                      </span>
                    </p>
                  </div>
                  <div>
                    <p
                      className={`text-[9px] font-black uppercase tracking-[0.2em] mb-1 ${theme === "dark" ? "text-white/40" : "text-slate-400"}`}
                    >
                      Date
                    </p>
                    <p className="text-2xl font-black tracking-tight">
                      {formatDate(activity.start_date)}
                    </p>
                  </div>
                </div>

                <div
                  className={`pt-4 border-t flex items-center gap-2 ${theme === "dark" ? "border-white/10" : "border-slate-200"}`}
                >
                  <img
                    src="/logo-dpp-ika.png"
                    alt="Logo"
                    className="w-4 h-4 object-contain grayscale opacity-80"
                    onError={(e) => (e.currentTarget.style.display = "none")}
                    crossOrigin="anonymous"
                  />
                  <div className="flex items-center gap-1.5">
                    <span
                      className={`font-bold text-[10px] tracking-widest uppercase ${theme === "dark" ? "text-white/70" : "text-[#152B5B]"}`}
                    >
                      UII Sehat 2026
                    </span>
                    <span className="text-[#FC4C02] font-black text-[10px]">
                      •
                    </span>
                    <span
                      className={`font-medium text-[10px] tracking-widest uppercase ${theme === "dark" ? "text-white/50" : "text-slate-400"}`}
                    >
                      IKA UII DIY
                    </span>
                  </div>
                </div>
              </div>
            </div>
          </div>
        </div>

        {/* KOLOM KANAN: EDITOR & ACTIONS */}
        <div className="w-full max-w-sm flex flex-col gap-6">
          <div className="bg-white p-6 rounded-3xl shadow-sm border border-slate-200">
            <h3 className="text-xs font-black text-slate-400 uppercase tracking-widest mb-4">
              Appearance
            </h3>
            <div className="flex bg-slate-100 rounded-xl p-1.5 border border-slate-200">
              <button
                onClick={() => setTheme("dark")}
                className={`flex-1 py-2.5 rounded-lg text-xs font-bold transition-all ${theme === "dark" ? "bg-white text-slate-900 shadow-sm" : "text-slate-500 hover:text-slate-700"}`}
              >
                Dark Mode
              </button>
              <button
                onClick={() => setTheme("light")}
                className={`flex-1 py-2.5 rounded-lg text-xs font-bold transition-all ${theme === "light" ? "bg-white text-slate-900 shadow-sm" : "text-slate-500 hover:text-slate-700"}`}
              >
                Light Mode
              </button>
            </div>
          </div>

          <div className="bg-white p-6 rounded-3xl shadow-sm border border-slate-200">
            <h3 className="text-xs font-black text-slate-400 uppercase tracking-widest mb-4">
              Recent Activities
            </h3>
            <div className="flex overflow-x-auto gap-3 pb-2 snap-x scrollbar-hide">
              {activities.map((act) => {
                // Periksa apakah aktivitas ini valid (sesuai tanggal event)
                const isValidDate = checkIsEventDate(
                  act.start_date_local || act.start_date,
                );

                return (
                  <div
                    key={act.id}
                    onClick={() => {
                      if (isSubmitted && activity?.id !== act.id) {
                        toast.warning("Anda sudah menyetor waktu. Riwayat lari lain sudah dikunci dari Leaderboard.");
                        return;
                      }
                      setActivity(act);
                    }}
                    className={`shrink-0 snap-center cursor-pointer p-4 rounded-2xl border-2 transition-all w-[140px] flex flex-col justify-between h-[160px] relative overflow-hidden ${
                      activity?.id === act.id
                        ? "bg-slate-900 border-slate-900 text-white shadow-lg"
                        : "bg-white border-slate-100 text-slate-600 hover:border-slate-300"
                    }`}
                  >
                    {!isValidDate && (
                      <div className="absolute top-0 right-0 bg-rose-500 text-white text-[8px] font-black uppercase px-2 py-1 rounded-bl-lg tracking-widest z-10">
                        Invalid
                      </div>
                    )}
                    <p
                      className={`text-[9px] font-black uppercase tracking-wider mb-2 relative z-10 ${activity?.id === act.id ? "text-slate-400" : "text-slate-400"}`}
                    >
                      {formatDate(act.start_date)}
                    </p>
                    <div className="mt-auto relative z-10">
                      <p
                        className={`text-2xl font-black leading-none mb-1 ${activity?.id === act.id ? "text-white" : "text-slate-800"}`}
                      >
                        {(act.distance / 1000).toFixed(2)}
                        <span className="text-[10px] ml-0.5 opacity-70">
                          KM
                        </span>
                      </p>
                      <p className="font-bold text-[10px] truncate opacity-80">
                        {act.name}
                      </p>
                    </div>
                  </div>
                );
              })}
            </div>
          </div>

          <div className="flex flex-col gap-3">
            {/* 🔥 TOMBOL SETOR LEADERBOARD (ANTI-CHEAT TERPASANG) 🔥 */}
            <button
              onClick={handleSubmitToLeaderboard}
              disabled={
                isSubmitting ||
                isSubmitted ||
                isDownloading ||
                !isActivityValidForLeaderboard
              }
              className={`w-full py-4 rounded-2xl font-black text-sm uppercase tracking-widest transition-all flex items-center justify-center gap-3 shadow-[0_10px_30px_rgba(0,0,0,0.1)] ${
                isSubmitted
                  ? "bg-emerald-500 text-white cursor-not-allowed shadow-none"
                  : !isActivityValidForLeaderboard
                    ? "bg-slate-100 text-slate-400 cursor-not-allowed shadow-none border border-slate-200"
                    : "bg-[#1A73E8] hover:bg-[#1557B0] text-white hover:-translate-y-1 active:translate-y-0"
              }`}
            >
              {isSubmitting ? (
                <>
                  <div className="w-5 h-5 border-2 border-slate-400 border-t-slate-600 rounded-full animate-spin"></div>{" "}
                  Menyimpan...
                </>
              ) : isSubmitted ? (
                <>
                  <svg
                    className="w-5 h-5"
                    fill="none"
                    viewBox="0 0 24 24"
                    stroke="currentColor"
                  >
                    <path
                      strokeLinecap="round"
                      strokeLinejoin="round"
                      strokeWidth={3}
                      d="M5 13l4 4L19 7"
                    />
                  </svg>{" "}
                  Tersimpan di Leaderboard
                </>
              ) : !isActivityValidForLeaderboard ? (
                <>
                  <svg
                    className="w-5 h-5"
                    fill="none"
                    viewBox="0 0 24 24"
                    stroke="currentColor"
                  >
                    <path
                      strokeLinecap="round"
                      strokeLinejoin="round"
                      strokeWidth={2.5}
                      d="M12 15v2m-6 4h12a2 2 0 002-2v-6a2 2 0 00-2-2H6a2 2 0 00-2 2v6a2 2 0 002 2zm10-10V7a4 4 0 00-8 0v4h8z"
                    />
                  </svg>{" "}
                  Bukan Tanggal Event
                </>
              ) : (
                <>
                  <svg
                    className="w-5 h-5"
                    fill="none"
                    viewBox="0 0 24 24"
                    stroke="currentColor"
                  >
                    <path
                      strokeLinecap="round"
                      strokeLinejoin="round"
                      strokeWidth={2.5}
                      d="M9 12l2 2 4-4m6 2a9 9 0 11-18 0 9 9 0 0118 0z"
                    />
                  </svg>{" "}
                  Setor ke Leaderboard
                </>
              )}
            </button>

            {/* TOMBOL EXPORT IG STORY (Tetap Bebas Dipakai Kapan Saja) */}
            <button
              onClick={handleDownload}
              disabled={isDownloading}
              className="w-full bg-[#FC4C02] hover:bg-[#E34402] text-white py-4 rounded-2xl font-black text-sm uppercase tracking-widest shadow-[0_10px_30px_rgba(252,76,2,0.3)] transition-all hover:-translate-y-1 active:translate-y-0 flex items-center justify-center gap-3 disabled:opacity-50"
            >
              {isDownloading ? (
                <>
                  <div className="w-5 h-5 border-2 border-white/30 border-t-white rounded-full animate-spin"></div>{" "}
                  Memproses...
                </>
              ) : (
                <>
                  <svg
                    className="w-5 h-5"
                    fill="none"
                    viewBox="0 0 24 24"
                    stroke="currentColor"
                  >
                    <path
                      strokeLinecap="round"
                      strokeLinejoin="round"
                      strokeWidth={2.5}
                      d="M4 16v1a3 3 0 003 3h10a3 3 0 003-3v-1m-4-4l-4 4m0 0l-4-4m4 4V4"
                    />
                  </svg>{" "}
                  Export IG Story
                </>
              )}
            </button>
          </div>
        </div>
      </div>

      <style jsx global>{`
        .scrollbar-hide::-webkit-scrollbar {
          display: none;
        }
        .scrollbar-hide {
          -ms-overflow-style: none;
          scrollbar-width: none;
        }
      `}</style>
    </div>
  );
}

"use client";

import { useEffect, useState } from "react";
import { toast } from "@/lib/toast";
import { db } from "@/lib/firebase";
import { doc, getDoc } from "firebase/firestore";
import { useParams, useRouter } from "next/navigation";
import NavbarPublic from "@/components/layout/NavbarPublic";
import FooterPublic from "@/components/layout/FooterPublic";
import { QRCodeSVG } from "qrcode.react";
import html2canvas from "html2canvas";

export default function ETicketKomunitasPage() {
  const params = useParams();
  const router = useRouter();
  const id = params.id as string;

  const [groupData, setGroupData] = useState<any>(null);
  const [settings, setSettings] = useState<any>(null);
  const [isLoading, setIsLoading] = useState(true);

  // =================================================================
  // 🔥 PENGAMANAN HALAMAN (ANTI KLIK KANAN & INSPECT)
  // =================================================================
  useEffect(() => {
    const handleContextMenu = (e: MouseEvent) => e.preventDefault();
    const handleKeyDown = (e: KeyboardEvent) => {
      if (
        e.key === "F12" ||
        (e.ctrlKey && e.shiftKey && (e.key === "I" || e.key === "J")) ||
        (e.ctrlKey && e.key === "U")
      ) {
        e.preventDefault();
      }
    };

    document.addEventListener("contextmenu", handleContextMenu);
    document.addEventListener("keydown", handleKeyDown);

    return () => {
      document.removeEventListener("contextmenu", handleContextMenu);
      document.removeEventListener("keydown", handleKeyDown);
    };
  }, []);

  // =================================================================
  // 🔥 FETCH DATA KOMUNITAS
  // =================================================================
  useEffect(() => {
    const fetchData = async () => {
      if (!id) return;
      try {
        const pRef = doc(db, "pendaftaran_komunitas", id);
        const pSnap = await getDoc(pRef);

        if (pSnap.exists()) {
          const data = pSnap.data();
          if (data.statusPembayaran !== "Lunas") {
            // Paksa kembali jika belum lunas
            router.push(`/run/checkout-komunitas/${id}`);
            return;
          }
          setGroupData({ id: pSnap.id, ...data });
        } else {
          router.push("/run");
          return;
        }

        const sRef = doc(db, "settings", "virtual_run");
        const sSnap = await getDoc(sRef);
        if (sSnap.exists()) {
          setSettings(sSnap.data());
        }
      } catch (error) {
        console.error("Error fetching ticket:", error);
      } finally {
        setIsLoading(false);
      }
    };

    fetchData();
  }, [id, router]);

  const downloadTicket = async () => {
    const element = document.getElementById("e-ticket-komunitas");
    if (!element) return;
    try {
      const canvas = await html2canvas(element, {
        scale: 2,
        useCORS: true,
      });
      const dataUrl = canvas.toDataURL("image/png");
      const link = document.createElement("a");
      link.download = `E-Ticket-${groupData.kapten?.komunitas || "Komunitas"}.png`;
      link.href = dataUrl;
      link.click();
    } catch (error) {
      toast.error("Gagal mengunduh tiket. Coba gunakan perangkat lain.");
    }
  };

  if (isLoading) {
    return (
      <div className="min-h-screen bg-[#F4F7FB] flex items-center justify-center">
        <div className="w-12 h-12 border-4 border-blue-200 border-t-[#0B2239] rounded-full animate-spin"></div>
      </div>
    );
  }

  if (!groupData) return null;

  return (
    <div className="min-h-screen bg-[#F4F7FB] font-sans flex flex-col relative">
      <NavbarPublic />

      <main className="flex-grow max-w-5xl mx-auto px-4 sm:px-6 lg:px-8 pt-[120px] md:pt-[160px] pb-20 w-full relative z-10 flex flex-col items-center animate-in zoom-in-95 duration-500">
        <div className="text-center mb-8 w-full max-w-2xl">
          <div className="w-16 h-16 bg-emerald-500 text-white rounded-full flex items-center justify-center mx-auto mb-4 shadow-lg border-4 border-emerald-200">
            <svg
              className="w-8 h-8"
              fill="none"
              viewBox="0 0 24 24"
              stroke="currentColor"
              strokeWidth={2.5}
            >
              <path
                strokeLinecap="round"
                strokeLinejoin="round"
                d="M5 13l4 4L19 7"
              />
            </svg>
          </div>
          <h1 className="text-2xl md:text-3xl font-black text-[#0B2239] mb-2 uppercase tracking-tight">
            Pembayaran Diterima!
          </h1>
          <p className="text-slate-500 font-medium max-w-lg mx-auto text-sm leading-relaxed">
            Status pembayaran komunitas{" "}
            <strong>{groupData.kapten?.komunitas}</strong> sudah LUNAS. Berikut
            adalah E-Ticket resmi grup Anda. Silakan unduh atau simpan bukti
            tiket ini.
          </p>
        </div>

        {/* DESAIN KARTU E-TIKET */}
        <div className="w-full max-w-2xl">
          <div
            id="e-ticket-komunitas"
            className="bg-white rounded-3xl overflow-hidden shadow-2xl border border-slate-200 w-full mb-8 relative bg-gradient-to-br from-white to-slate-50"
          >
            <div className="bg-[#0B2239] text-white p-6 border-b-4 border-[#FCD116] flex flex-col sm:flex-row justify-between items-start sm:items-center gap-4">
              <div>
                <span className="text-[10px] font-black tracking-widest text-[#FCD116] bg-[#0B2239] border border-[#FCD116] px-2.5 py-1 rounded-full uppercase">
                  Official E-Ticket
                </span>
                <h2 className="text-xl font-black tracking-tight mt-2 uppercase">
                  {settings?.eventName || "VIRTUAL RUN"}
                </h2>
                <p className="text-xs text-slate-300 font-medium mt-0.5">
                  Kategori: Komunitas / Group Registration
                </p>
              </div>
              <div className="bg-emerald-500 text-white font-black text-xs px-4 py-2 rounded-full shadow-md border border-emerald-300 uppercase tracking-wider">
                LUNAS / PAID
              </div>
            </div>

            <div className="grid md:grid-cols-12 gap-6 p-6 sm:p-8 items-center relative">
              <div className="md:col-span-7 space-y-4 border-b md:border-b-0 md:border-r border-dashed border-slate-200 pb-6 md:pb-0 md:pr-6">
                <div>
                  <p className="text-[10px] font-bold text-slate-400 uppercase tracking-widest mb-0.5">
                    Nama Komunitas / Tim
                  </p>
                  <p className="text-lg font-black text-[#0B2239] uppercase tracking-tight">
                    {groupData.kapten?.komunitas}
                  </p>
                </div>

                <div className="grid grid-cols-2 gap-4">
                  <div>
                    <p className="text-[10px] font-bold text-slate-400 uppercase tracking-widest mb-0.5">
                      Nama Kapten (PJ)
                    </p>
                    <p className="text-sm font-bold text-slate-700 uppercase">
                      {groupData.kapten?.nama}
                    </p>
                  </div>
                  <div>
                    <p className="text-[10px] font-bold text-slate-400 uppercase tracking-widest mb-0.5">
                      Total Anggota
                    </p>
                    <p className="text-sm font-black text-[#0B2239]">
                      {groupData.participants?.length || 0} Orang
                    </p>
                  </div>
                </div>

                <div className="grid grid-cols-2 gap-4">
                  <div>
                    <p className="text-[10px] font-bold text-slate-400 uppercase tracking-widest mb-0.5">
                      ID Registrasi
                    </p>
                    <p className="text-xs font-mono font-bold text-slate-600 bg-slate-100 px-2 py-1 rounded inline-block">
                      {groupData.id}
                    </p>
                  </div>
                  <div>
                    <p className="text-[10px] font-bold text-slate-400 uppercase tracking-widest mb-0.5">
                      Tanggal Daftar
                    </p>
                    <p className="text-xs font-bold text-slate-600">
                      {groupData.createdAt?.seconds
                        ? new Date(
                            groupData.createdAt.seconds * 1000,
                          ).toLocaleDateString("id-ID", {
                            day: "numeric",
                            month: "long",
                            year: "numeric",
                          })
                        : "Terkonfirmasi"}
                    </p>
                  </div>
                </div>
              </div>

              <div className="md:col-span-5 flex flex-col items-center justify-center text-center">
                <div className="p-3 bg-white border border-slate-200 rounded-2xl shadow-inner mb-3">
                  <QRCodeSVG
                    value={groupData.id}
                    size={140}
                    level={"H"}
                    includeMargin={true}
                  />
                </div>
                <p className="text-[10px] font-mono font-bold text-slate-400 uppercase tracking-widest">
                  Scan QR Code saat Check-in
                </p>
              </div>
            </div>

            <div className="bg-slate-50 border-t border-slate-100 px-6 py-4 text-center">
              <p className="text-[11px] text-slate-400 font-medium leading-relaxed">
                Bawa E-Ticket ini saat pengambilan Race Pack secara kolektif
                oleh Kapten. Jangan membagikan QR Code tiket ini kepada pihak
                asing.
              </p>
            </div>
          </div>
        </div>

        <div className="flex flex-col sm:flex-row gap-4 w-full justify-center max-w-2xl">
          <button
            onClick={downloadTicket}
            className="bg-emerald-600 hover:bg-emerald-700 text-white font-bold py-3.5 px-8 rounded-full transition-all shadow-lg text-sm flex items-center justify-center gap-2"
          >
            Unduh E-Ticket (PNG)
          </button>

          <button
            onClick={() =>
              window.open(
                `https://wa.me/?text=Halo Admin, saya Kapten ${groupData.kapten?.nama} dari komunitas ${groupData.kapten?.komunitas}. Ingin melakukan konfirmasi pendaftaran grup kami dengan ID pendaftaran: ${groupData.id}.`,
                "_blank",
              )
            }
            className="bg-[#0B2239] hover:bg-slate-800 text-[#FCD116] font-bold py-3.5 px-8 rounded-full transition-all shadow-lg text-sm flex items-center justify-center gap-2"
          >
            Hubungi Admin (WhatsApp)
          </button>
        </div>
      </main>

      <FooterPublic />
    </div>
  );
}

"use client";

import { useEffect, useState, useRef } from "react";
import { toast } from "@/lib/toast";
import { db } from "@/lib/firebase";
import { doc, getDoc } from "firebase/firestore";
import { useParams, useRouter } from "next/navigation";
import Link from "next/link";
import NavbarPublic from "@/components/layout/NavbarPublic";
import FooterPublic from "@/components/layout/FooterPublic";
import { QRCodeSVG } from "qrcode.react";
import html2canvas from "html2canvas";

export default function ETicketPage() {
  const params = useParams();
  const router = useRouter();
  const id = params.id as string;

  const [participant, setParticipant] = useState<any>(null);
  const [settings, setSettings] = useState<any>(null);
  const [isLoading, setIsLoading] = useState(true);
  const [isDownloading, setIsDownloading] = useState(false);
  const [scale, setScale] = useState(1);

  const ticketRef = useRef<HTMLDivElement>(null);
  const containerRef = useRef<HTMLDivElement>(null);

  const baseUrl =
    typeof window !== "undefined"
      ? window.location.origin
      : "http://localhost:3000";

  // =================================================================
  // PENGAMANAN HALAMAN (ANTI KLIK KANAN & INSPECT)
  // =================================================================
  useEffect(() => {
    const handleContextMenu = (e: MouseEvent) => e.preventDefault();
    const handleKeyDown = (e: KeyboardEvent) => {
      // Blokir F12, Ctrl+Shift+I, Ctrl+Shift+J, Ctrl+U
      if (
        e.key === "F12" ||
        (e.ctrlKey && e.shiftKey && (e.key === "I" || e.key === "J")) ||
        (e.ctrlKey && e.key === "U")
      ) {
        e.preventDefault();
      }
    };

    document.addEventListener("contextmenu", handleContextMenu);
    document.addEventListener("keydown", handleKeyDown);

    return () => {
      document.removeEventListener("contextmenu", handleContextMenu);
      document.removeEventListener("keydown", handleKeyDown);
    };
  }, []);

  // =================================================================
  // FETCH DATA TIKET
  // =================================================================
  useEffect(() => {
    const fetchTicket = async () => {
      if (!id) return;
      try {
        const pRef = doc(db, "offline_participants", id);
        const pSnap = await getDoc(pRef);

        if (pSnap.exists()) {
          const data = pSnap.data();
          if (data.statusPembayaran !== "Lunas") {
            // Jika belum lunas, paksa kembali ke halaman checkout
            router.push(`/run/checkout/${id}`);
            return;
          }
          setParticipant({ id: pSnap.id, ...data });
        } else {
          router.push("/run");
          return;
        }

        const sRef = doc(db, "settings", "virtual_run");
        const sSnap = await getDoc(sRef);
        if (sSnap.exists()) setSettings(sSnap.data());
      } catch (error) {
        console.error("Error loading ticket:", error);
      } finally {
        setIsLoading(false);
      }
    };
    fetchTicket();
  }, [id, router]);

  useEffect(() => {
    const handleResize = () => {
      if (containerRef.current) {
        const containerWidth = containerRef.current.offsetWidth;
        setScale(Math.min(1, containerWidth / 600));
      }
    };
    handleResize();
    window.addEventListener("resize", handleResize);
    return () => window.removeEventListener("resize", handleResize);
  }, [isLoading]);

  const handleDownloadTicket = async () => {
    if (!ticketRef.current) return;
    setIsDownloading(true);
    try {
      await new Promise((resolve) => setTimeout(resolve, 500));
      const canvas = await html2canvas(ticketRef.current, {
        scale: 3,
        useCORS: true,
        allowTaint: true,
        backgroundColor: null,
        logging: false,
      });
      const url = canvas.toDataURL("image/png");
      const a = document.createElement("a");
      a.href = url;
      a.download = `E-Ticket-${participant.namaLengkap.replace(/\s+/g, "-")}.png`;
      a.click();
    } catch (err) {
      toast.error("Gagal mengunduh tiket. Coba gunakan perangkat lain.");
    } finally {
      setIsDownloading(false);
    }
  };

  if (isLoading) {
    return (
      <div className="min-h-screen bg-[#F4F7FB] flex items-center justify-center">
        <div className="w-12 h-12 border-4 border-blue-200 border-t-[#0B2239] rounded-full animate-spin"></div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-[#F4F7FB] font-sans flex flex-col relative">
      <NavbarPublic />
      <main className="flex-grow max-w-5xl mx-auto px-4 sm:px-6 lg:px-8 pt-[120px] md:pt-[160px] pb-20 w-full relative z-10 flex flex-col items-center animate-in zoom-in-95 duration-500">
        <div className="text-center mb-8">
          <div className="w-16 h-16 bg-[#0B2239] text-[#FCD116] rounded-full flex items-center justify-center mx-auto mb-4 shadow-lg border-2 border-[#FCD116]">
            <svg
              className="w-8 h-8"
              fill="none"
              viewBox="0 0 24 24"
              stroke="currentColor"
              strokeWidth={2.5}
            >
              <path
                strokeLinecap="round"
                strokeLinejoin="round"
                d="M5 13l4 4L19 7"
              />
            </svg>
          </div>
          <h1 className="text-2xl md:text-3xl font-black text-[#0B2239] mb-2 uppercase tracking-tight">
            Pendaftaran Selesai!
          </h1>
          <p className="text-slate-500 font-medium max-w-md mx-auto text-sm">
            Tunjukkan E-Ticket di bawah ini saat pengambilan Race Pack.
          </p>
        </div>

        <div
          ref={containerRef}
          className="w-full max-w-[600px] flex justify-center items-center mb-8"
        >
          <div
            className="relative transition-transform duration-300 hover:scale-[1.02] cursor-pointer group drop-shadow-2xl"
            style={{ width: `${600 * scale}px`, height: `${240 * scale}px` }}
            onClick={handleDownloadTicket}
          >
            {/* CONTAINER TIKET (Kodingan asli jenengan yang elegan) */}
            <div
              ref={ticketRef}
              style={{
                position: "absolute",
                top: 0,
                left: 0,
                width: "600px",
                height: "240px",
                transform: `scale(${scale})`,
                transformOrigin: "top left",
                backgroundColor: "#ffffff",
                borderRadius: "16px",
                display: "flex",
                overflow: "hidden",
              }}
            >
              {/* BAGIAN KIRI TIKET */}
              <div
                style={{
                  flex: 1,
                  display: "flex",
                  flexDirection: "column",
                  position: "relative",
                }}
              >
                <div
                  style={{
                    backgroundColor: "#0B2239",
                    height: "65px",
                    display: "flex",
                    alignItems: "center",
                    paddingLeft: "24px",
                    position: "relative",
                    borderBottom: "4px solid #FCD116",
                  }}
                >
                  <img
                    src="/logo-dpp-ika.png"
                    alt="Logo"
                    style={{
                      width: "36px",
                      height: "36px",
                      backgroundColor: "#ffffff",
                      borderRadius: "50%",
                      padding: "4px",
                    }}
                    crossOrigin="anonymous"
                  />
                  <div style={{ marginLeft: "12px", zIndex: 10 }}>
                    <h1
                      style={{
                        margin: 0,
                        color: "#ffffff",
                        fontSize: "18px",
                        fontWeight: 900,
                        letterSpacing: "1px",
                      }}
                    >
                      E-TICKET
                    </h1>
                    <p
                      style={{
                        margin: 0,
                        color: "#FCD116",
                        fontSize: "9px",
                        fontWeight: 700,
                        letterSpacing: "1.5px",
                      }}
                    >
                      {(
                        participant.eventName ||
                        settings?.namaEvent ||
                        "IKA UII DIY RUN"
                      ).toUpperCase()}
                    </p>
                  </div>
                  <div
                    style={{
                      position: "absolute",
                      right: "-30px",
                      top: 0,
                      bottom: 0,
                      width: "120px",
                      backgroundColor: "#1e3a5f",
                      transform: "skewX(-30deg)",
                    }}
                  ></div>
                </div>

                <div
                  style={{
                    position: "absolute",
                    top: "50%",
                    left: "50%",
                    transform: "translate(-50%, -50%)",
                    opacity: 0.05,
                    pointerEvents: "none",
                  }}
                >
                  <img
                    src="/logo-dpp-ika.png"
                    style={{
                      width: "160px",
                      height: "160px",
                      filter: "grayscale(100%)",
                    }}
                    crossOrigin="anonymous"
                  />
                </div>

                <div
                  style={{
                    padding: "20px 24px",
                    display: "flex",
                    flexDirection: "column",
                    flex: 1,
                  }}
                >
                  <p
                    style={{
                      margin: 0,
                      fontSize: "10px",
                      color: "#64748b",
                      fontWeight: 700,
                      textTransform: "uppercase",
                    }}
                  >
                    Nama Pelari
                  </p>
                  <h2
                    style={{
                      margin: 0,
                      fontSize: "24px",
                      color: "#0B2239",
                      fontWeight: 900,
                      textTransform: "uppercase",
                      whiteSpace: "nowrap",
                      overflow: "hidden",
                      textOverflow: "ellipsis",
                      maxWidth: "350px",
                    }}
                  >
                    {participant.namaLengkap}
                  </h2>
                  <p
                    style={{
                      margin: "4px 0 0 0",
                      fontSize: "11px",
                      color: "#64748b",
                      fontWeight: 700,
                    }}
                  >
                    BIB:{" "}
                    <span style={{ color: "#0B2239", fontWeight: 900 }}>
                      {participant.nomorBIB || "0000"}
                    </span>
                  </p>

                  <div
                    style={{ display: "flex", marginTop: "auto", gap: "30px" }}
                  >
                    <div>
                      <p
                        style={{
                          margin: 0,
                          fontSize: "9px",
                          color: "#94a3b8",
                          fontWeight: 700,
                          textTransform: "uppercase",
                        }}
                      >
                        Kategori
                      </p>
                      <p
                        style={{
                          margin: 0,
                          fontSize: "18px",
                          color: "#1A73E8",
                          fontWeight: 900,
                        }}
                      >
                        {participant.jarak}
                      </p>
                    </div>
                    <div>
                      <p
                        style={{
                          margin: 0,
                          fontSize: "9px",
                          color: "#94a3b8",
                          fontWeight: 700,
                          textTransform: "uppercase",
                        }}
                      >
                        Size Jersey
                      </p>
                      <p
                        style={{
                          margin: 0,
                          fontSize: "18px",
                          color: "#0B2239",
                          fontWeight: 900,
                        }}
                      >
                        {participant.ukuranJersey}
                      </p>
                    </div>
                  </div>
                </div>
              </div>

              {/* PEMBATAS PUTUT-PUTUS */}
              <div
                style={{
                  width: "0px",
                  borderLeft: "2px dashed #cbd5e1",
                  position: "relative",
                  zIndex: 10,
                }}
              >
                <div
                  style={{
                    position: "absolute",
                    top: "-12px",
                    left: "-12px",
                    width: "24px",
                    height: "24px",
                    backgroundColor: "#F4F7FB",
                    borderRadius: "50%",
                  }}
                ></div>
                <div
                  style={{
                    position: "absolute",
                    bottom: "-12px",
                    left: "-12px",
                    width: "24px",
                    height: "24px",
                    backgroundColor: "#F4F7FB",
                    borderRadius: "50%",
                  }}
                ></div>
              </div>

              {/* BAGIAN KANAN TIKET (QR CODE) */}
              <div
                style={{
                  width: "160px",
                  backgroundColor: "#f8fafc",
                  display: "flex",
                  flexDirection: "column",
                  alignItems: "center",
                  justifyContent: "center",
                }}
              >
                <p
                  style={{
                    margin: "0 0 8px 0",
                    fontSize: "10px",
                    color: "#0B2239",
                    fontWeight: 900,
                    letterSpacing: "1px",
                  }}
                >
                  SCAN AREA
                </p>
                <div
                  style={{
                    padding: "8px",
                    backgroundColor: "#ffffff",
                    borderRadius: "8px",
                    border: "1px solid #e2e8f0",
                  }}
                >
                  <QRCodeSVG
                    value={`${baseUrl}/verify-ticket/${participant.id}`}
                    size={100}
                    level="M"
                  />
                </div>
                <p
                  style={{
                    margin: "8px 0 0 0",
                    fontSize: "10px",
                    color: "#64748b",
                    fontWeight: 700,
                    letterSpacing: "2px",
                  }}
                >
                  {participant.nomorBIB || "0000"}
                </p>
              </div>
            </div>
          </div>
        </div>

        <div className="flex justify-center gap-3">
          <button
            onClick={handleDownloadTicket}
            disabled={isDownloading}
            className="bg-[#0B2239] hover:bg-blue-950 text-white font-bold py-3.5 px-8 rounded-full shadow-lg flex items-center justify-center gap-2 disabled:opacity-50 text-sm"
          >
            {isDownloading ? "Memproses..." : "Unduh E-Ticket (PNG)"}
          </button>
          <Link
            href="/run"
            className="bg-white border border-slate-200 text-slate-700 font-bold py-3.5 px-8 rounded-full flex items-center gap-2 text-sm"
          >
            Kembali
          </Link>
        </div>
      </main>
      <FooterPublic />
    </div>
  );
}

"use client";

import { useEffect, useState } from "react";
import { useParams } from "next/navigation";
import { db } from "@/lib/firebase";
import {
  doc,
  getDoc,
  collection,
  query,
  where,
  getDocs,
} from "firebase/firestore";
import Link from "next/link";

export default function PublicRunnerProfile() {
  const params = useParams();
  const id = params?.id as string;

  const [participant, setParticipant] = useState<any>(null);
  const [submissions, setSubmissions] = useState<any[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [error, setError] = useState("");

  // --- 1. AMBIL DATA PESERTA & RIWAYAT LARI ---
  useEffect(() => {
    const fetchPublicData = async () => {
      if (!id) return;

      try {
        let pData: any = null;

        // A1. Coba cari berdasarkan field "slug" terlebih dahulu
        const qSlug = query(
          collection(db, "vr_participants"),
          where("slug", "==", id),
        );
        const slugSnap = await getDocs(qSlug);

        if (!slugSnap.empty) {
          // Ketemu pakai Slug!
          const foundDoc = slugSnap.docs[0];
          pData = { id: foundDoc.id, ...foundDoc.data() };
        } else {
          // A2. Kalau tidak ketemu pakai slug, coba cari pakai Document ID asli (sebagai Fallback)
          const pRef = doc(db, "vr_participants", id);
          const pSnap = await getDoc(pRef);

          if (pSnap.exists()) {
            pData = { id: pSnap.id, ...pSnap.data() };
          }
        }

        // Kalau dicarikan pakai slug & ID tetep ga ada, lempar error
        if (!pData) {
          setError("Pelari tidak ditemukan atau ID tidak valid.");
          setIsLoading(false);
          return;
        }

        // Sembunyikan data sensitif di level state (Privacy)
        delete pData.email;
        delete pData.whatsapp;
        delete pData.alamat;
        delete pData.totalTagihan;
        delete pData.nominalDonasi;

        setParticipant(pData);

        // B. Ambil Data Riwayat Lari (Penting: Gunakan pData.id yaitu Doc ID asli, bukan slug URL)
        const sRef = collection(db, "vr_submissions");
        const qSub = query(
          sRef,
          where("participantId", "==", pData.id),
          where("status", "==", "Approved"),
        );
        const sSnap = await getDocs(qSub);

        const sData = sSnap.docs.map((doc) => ({ id: doc.id, ...doc.data() }));

        // Urutkan manual dari yang terbaru
        sData.sort(
          (a: any, b: any) =>
            new Date(b.tanggalLari).getTime() -
            new Date(a.tanggalLari).getTime(),
        );

        setSubmissions(sData);
      } catch (err) {
        console.error("Error fetching data:", err);
        setError("Gagal memuat profil pelari.");
      } finally {
        setIsLoading(false);
      }
    };

    fetchPublicData();
  }, [id]);

  // --- 2. KALKULASI STATISTIK ---
  const targetKm = participant
    ? parseInt(participant.jarak.replace(/\D/g, ""))
    : 0;
  const totalApprovedKm = submissions.reduce(
    (acc, curr) => acc + (curr.jarakKm || 0),
    0,
  );
  const progressPercent = Math.min((totalApprovedKm / targetKm) * 100, 100);
  const isFinisher = totalApprovedKm >= targetKm;

  const hitungTotalDurasi = () => {
    let totalSeconds = 0;
    submissions.forEach((sub) => {
      if (!sub.durasi) return;
      let sec = 0;
      const str = String(sub.durasi).toLowerCase().trim();

      if (str.includes(":")) {
        const parts = str.split(":").map((n) => parseInt(n) || 0);
        if (parts.length >= 3) sec = parts[0] * 3600 + parts[1] * 60 + parts[2];
        else if (parts.length === 2) sec = parts[0] * 60 + parts[1];
      } else if (str.includes("j") || str.includes("h") || str.includes("m")) {
        const jamMatch = str.match(/(\d+)\s*(j|h)/);
        const menitMatch = str.match(/(\d+)\s*(m)/);
        if (jamMatch) sec += parseInt(jamMatch[1]) * 3600;
        if (menitMatch) sec += parseInt(menitMatch[1]) * 60;
      } else {
        const match = str.match(/\d+/);
        if (match) sec = parseInt(match[0]) * 60;
      }
      if (!isNaN(sec)) totalSeconds += sec;
    });

    const h = Math.floor(totalSeconds / 3600);
    const m = Math.floor((totalSeconds % 3600) / 60);
    return `${h}h ${m}m`;
  };

  // --- 3. LOADING & ERROR STATES ---
  if (isLoading) {
    return (
      <div className="min-h-screen bg-[#F4F7FB] flex flex-col items-center justify-center">
        <div className="w-12 h-12 border-4 border-slate-200 border-t-blue-600 rounded-full animate-spin mb-4"></div>
        <p className="text-slate-500 font-bold text-sm uppercase tracking-widest">
          Memuat Profil...
        </p>
      </div>
    );
  }

  if (error || !participant) {
    return (
      <div className="min-h-screen bg-[#F4F7FB] flex flex-col items-center justify-center p-6 text-center">
        <div className="text-6xl mb-4 grayscale opacity-50">🏃‍♂️❓</div>
        <h1 className="text-2xl font-black text-slate-900 mb-2">
          Profil Tidak Ditemukan
        </h1>
        <p className="text-slate-500 mb-8 max-w-sm">
          {error ||
            "Halaman yang Anda tuju mungkin sudah dihapus atau ID tidak valid."}
        </p>
        <Link
          href="/"
          className="bg-blue-600 text-white font-bold px-6 py-3 rounded-xl shadow-md hover:bg-blue-700 transition-colors"
        >
          Kembali ke Beranda
        </Link>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-[#F4F7FB] font-sans pb-20 selection:bg-blue-100 selection:text-blue-900">
      {/* HEADER NAVBAR */}
      <header className="bg-white border-b border-slate-200 sticky top-0 z-50 shadow-sm">
        <div className="max-w-4xl mx-auto px-4 sm:px-6 h-16 flex items-center justify-between">
          <Link href="/" className="flex items-center gap-3">
            <div className="bg-blue-600 p-1.5 rounded-lg">
              <img
                src="/logo-dpp-ika.png"
                alt="Logo"
                className="w-6 h-6 object-contain"
              />
            </div>
            <div>
              <h1 className="font-black text-slate-800 text-sm leading-none tracking-tight">
                IKA UII DIY
              </h1>
              <p className="text-[9px] font-bold text-blue-600 uppercase tracking-widest">
                Virtual Run 2026
              </p>
            </div>
          </Link>
          <Link
            href="/virtual-run/register"
            className="text-xs font-bold bg-yellow-400 hover:bg-yellow-500 text-blue-950 px-4 py-2 rounded-full transition-colors shadow-sm"
          >
            Daftar Event
          </Link>
        </div>
      </header>

      {/* 🔥 HERO PROFIL (DIPERBARUI DENGAN FOTO HEADER & PROFIL DINAMIS) 🔥 */}
      <div className="bg-[#3b5998] pt-10 pb-32 px-4 sm:px-6 text-white relative overflow-hidden">
        {/* Logika Header Photo: Jika ada foto pakai foto, jika tidak pakai tekstur bawaan */}
        {participant.fotoHeaderUrl ? (
          <>
            <img
              src={participant.fotoHeaderUrl}
              alt="Cover"
              className="absolute inset-0 w-full h-full object-cover opacity-30 mix-blend-overlay"
            />
            <div className="absolute inset-0 bg-gradient-to-t from-[#3b5998] via-transparent to-transparent opacity-80"></div>
          </>
        ) : (
          <div className="absolute inset-0 bg-[url('https://www.transparenttextures.com/patterns/cubes.png')] opacity-10"></div>
        )}

        <div className="max-w-4xl mx-auto relative z-10 flex flex-col md:flex-row items-center gap-6 text-center md:text-left mt-4">
          {/* Logika Foto Profil: Jika ada foto pakai foto, jika tidak pakai inisial */}
          {participant.fotoProfilUrl ? (
            <img
              src={participant.fotoProfilUrl}
              alt={participant.nama}
              className="w-32 h-32 rounded-full border-4 border-white/20 shadow-xl shrink-0 object-cover bg-slate-100"
            />
          ) : (
            <div className="w-32 h-32 bg-white/10 rounded-full backdrop-blur-md border-4 border-white/20 flex items-center justify-center text-5xl font-black text-white shadow-xl shrink-0">
              {participant.nama.charAt(0).toUpperCase()}
            </div>
          )}

          <div>
            <div className="flex flex-wrap justify-center md:justify-start gap-2 mb-3">
              <span className="bg-blue-900/50 border border-blue-800 text-blue-200 text-[10px] font-bold px-3 py-1 rounded-full uppercase tracking-widest backdrop-blur-sm">
                Pelari {participant.jarak}
              </span>
              {isFinisher && (
                <span className="bg-emerald-500 text-white text-[10px] font-bold px-3 py-1 rounded-full uppercase tracking-widest shadow-sm flex items-center gap-1">
                  🏅 Finisher
                </span>
              )}
            </div>

            <h1 className="text-3xl sm:text-5xl font-black mb-2 tracking-tight drop-shadow-md">
              {participant.nama}
            </h1>

            {/* Motto / Bio Tambahan */}
            {participant.motto && (
              <p className="text-blue-100 italic mb-3 max-w-lg text-sm md:text-base border-l-4 border-yellow-400 pl-3">
                "{participant.motto}"
              </p>
            )}

            <p className="text-blue-200 text-sm font-medium flex items-center justify-center md:justify-start gap-2">
              <svg
                className="w-4 h-4"
                fill="none"
                viewBox="0 0 24 24"
                stroke="currentColor"
              >
                <path
                  strokeLinecap="round"
                  strokeLinejoin="round"
                  strokeWidth={2}
                  d="M8 7V3m8 4V3m-9 8h10M5 21h14a2 2 0 002-2V7a2 2 0 00-2-2H5a2 2 0 00-2-2v12a2 2 0 002 2z"
                />
              </svg>
              Bergabung{" "}
              {new Date(participant.waktuDaftar).toLocaleDateString("id-ID", {
                month: "long",
                year: "numeric",
              })}
            </p>
          </div>
        </div>
      </div>

      <div className="max-w-4xl mx-auto px-4 sm:px-6 -mt-20 relative z-20 space-y-6">
        {/* STATISTIK GRID */}
        <div className="bg-white rounded-3xl p-6 sm:p-8 shadow-xl shadow-slate-200/50 border border-slate-200 grid grid-cols-3 gap-4 text-center">
          <div>
            <p className="text-[10px] sm:text-xs font-bold text-slate-400 uppercase tracking-widest mb-1">
              Total Jarak
            </p>
            <p className="text-2xl sm:text-4xl font-black text-blue-600">
              {totalApprovedKm.toFixed(2)}
              <span className="text-lg sm:text-xl text-slate-400 ml-1">km</span>
            </p>
          </div>
          <div className="border-x border-slate-100">
            <p className="text-[10px] sm:text-xs font-bold text-slate-400 uppercase tracking-widest mb-1">
              Total Waktu
            </p>
            <p className="text-2xl sm:text-4xl font-black text-slate-800">
              {hitungTotalDurasi()}
            </p>
          </div>
          <div>
            <p className="text-[10px] sm:text-xs font-bold text-slate-400 uppercase tracking-widest mb-1">
              Aktivitas
            </p>
            <p className="text-2xl sm:text-4xl font-black text-slate-800">
              {submissions.length}
            </p>
          </div>
        </div>

        {/* PROGRESS CARD */}
        <div className="bg-white rounded-3xl p-6 sm:p-8 shadow-sm border border-slate-200">
          <div className="flex justify-between items-end mb-4">
            <div>
              <h3 className="font-black text-slate-800 text-lg">
                Progress Challenge
              </h3>
              <p className="text-xs font-medium text-slate-500 mt-0.5">
                Menuju {targetKm} KM Finisher
              </p>
            </div>
            <div className="text-right">
              <span className="text-2xl font-black text-slate-900">
                {Math.round(progressPercent)}%
              </span>
            </div>
          </div>
          <div className="w-full h-4 bg-slate-100 rounded-full overflow-hidden shadow-inner">
            <div
              className={`h-full rounded-full transition-all duration-1000 ${isFinisher ? "bg-emerald-500" : "bg-gradient-to-r from-blue-500 to-blue-400"}`}
              style={{ width: `${progressPercent}%` }}
            ></div>
          </div>
        </div>

        {/* PENCAPAIAN BADGE */}
        <div className="bg-white rounded-3xl p-6 sm:p-8 shadow-sm border border-slate-200">
          <h3 className="font-black text-slate-800 text-lg mb-5 flex items-center gap-2">
            <span className="bg-amber-100 text-amber-600 p-1.5 rounded-lg text-sm">
              🏆
            </span>{" "}
            Pencapaian
          </h3>
          <div className="flex flex-wrap gap-4">
            <div className="bg-slate-50 border border-slate-200 rounded-2xl p-4 w-32 text-center flex flex-col items-center justify-center">
              <div className="w-12 h-12 bg-blue-500 text-white rounded-2xl flex items-center justify-center mb-2 shadow-md">
                <svg
                  className="w-6 h-6"
                  fill="none"
                  viewBox="0 0 24 24"
                  stroke="currentColor"
                >
                  <path
                    strokeLinecap="round"
                    strokeLinejoin="round"
                    strokeWidth={2.5}
                    d="M8 7V3m8 4V3m-9 8h10M5 21h14a2 2 0 002-2V7a2 2 0 00-2-2H5a2 2 0 00-2-2v12a2 2 0 002 2z"
                  />
                </svg>
              </div>
              <p className="font-black text-slate-800 text-xs">First Event</p>
            </div>
            {isFinisher ? (
              <div className="bg-emerald-50 border border-emerald-200 rounded-2xl p-4 w-32 text-center flex flex-col items-center justify-center">
                <div className="w-12 h-12 bg-emerald-500 text-white rounded-2xl flex items-center justify-center mb-2 shadow-md">
                  <svg
                    className="w-6 h-6"
                    fill="none"
                    viewBox="0 0 24 24"
                    stroke="currentColor"
                  >
                    <path
                      strokeLinecap="round"
                      strokeLinejoin="round"
                      strokeWidth={2.5}
                      d="M5 3v4M3 5h4M6 17v4m-2-2h4m5-16l2.286 6.857L21 12l-5.714 2.143L13 21l-2.286-6.857L5 12l5.714-2.143L13 3z"
                    />
                  </svg>
                </div>
                <p className="font-black text-emerald-800 text-xs">Finisher</p>
              </div>
            ) : (
              <div className="bg-slate-50 border border-slate-200 rounded-2xl p-4 w-32 text-center flex flex-col items-center justify-center opacity-50 grayscale">
                <div className="w-12 h-12 bg-slate-300 text-white rounded-2xl flex items-center justify-center mb-2 shadow-inner">
                  <svg
                    className="w-6 h-6"
                    fill="none"
                    viewBox="0 0 24 24"
                    stroke="currentColor"
                  >
                    <path
                      strokeLinecap="round"
                      strokeLinejoin="round"
                      strokeWidth={2.5}
                      d="M12 15v2m-6 4h12a2 2 0 002-2v-6a2 2 0 00-2-2H6a2 2 0 00-2 2v6a2 2 0 002 2zm10-10V7a4 4 0 00-8 0v4h8z"
                    />
                  </svg>
                </div>
                <p className="font-black text-slate-800 text-xs">Finisher</p>
              </div>
            )}
          </div>
        </div>

        {/* RIWAYAT LARI */}
        <div className="bg-white rounded-3xl p-6 sm:p-8 shadow-sm border border-slate-200 mb-10">
          <h3 className="font-black text-slate-800 text-lg mb-6 flex items-center gap-2">
            <span className="bg-blue-100 text-blue-600 p-1.5 rounded-lg text-sm">
