                <div
                  key={index}
                  className="flex items-center gap-4 p-4 border border-slate-100 rounded-2xl bg-slate-50/50"
                >
                  <div className="w-14 h-14 rounded-xl overflow-hidden shrink-0 border border-slate-200">
