                    </h4>
                    <p className="text-xs font-medium text-slate-500 mt-0.5">
                      {new Date(sub.tanggalLari).toLocaleDateString("id-ID", {
                        day: "numeric",
                        month: "long",
                        year: "numeric",
                      })}
                    </p>
                  </div>
                  <div className="shrink-0 text-right">
                    <p className="text-[10px] font-bold text-slate-400 uppercase tracking-widest mb-0.5">
                      Waktu
                    </p>
                    <p className="text-sm font-black text-slate-700">
                      {sub.durasi}
                    </p>
                  </div>
                </div>
              ))}
            </div>
          )}
        </div>

        {/* CTA Bawah */}
        <div className="bg-gradient-to-br from-blue-900 to-blue-950 rounded-3xl p-8 sm:p-10 text-center text-white shadow-xl relative overflow-hidden">
          <div className="absolute inset-0 bg-[url('https://www.transparenttextures.com/patterns/cubes.png')] opacity-10"></div>
          <div className="relative z-10">
            <h2 className="text-2xl sm:text-3xl font-black mb-3">
              Ikuti Jejak {participant.nama.split(" ")[0]}!
            </h2>
            <p className="text-blue-200 text-sm sm:text-base font-medium max-w-md mx-auto mb-6">
              Tantang dirimu dan berdonasi bersama ribuan alumni lainnya di
              Virtual Run IKA UII.
            </p>
            <Link
              href="/virtual-run/register"
              className="inline-block bg-yellow-400 hover:bg-yellow-500 text-blue-950 font-black px-8 py-3.5 rounded-xl shadow-lg transition-transform hover:-translate-y-1"
            >
              Daftar Sekarang
            </Link>
          </div>
        </div>
      </div>
    </div>
  );
}

"use client";

import { useEffect, useState } from "react";
import { toast } from "@/lib/toast";
import { useParams, useRouter } from "next/navigation";
import { db, auth } from "@/lib/firebase";
import { doc, getDoc, updateDoc, addDoc, collection } from "firebase/firestore";
import { onAuthStateChanged } from "firebase/auth";
import Link from "next/link";

export default function VerifyTicketPage() {
  const params = useParams();
  const router = useRouter();
  const id = params.id as string;

  const [participant, setParticipant] = useState<any>(null);
  const [isLoading, setIsLoading] = useState(true);
  const [isAuthLoading, setIsAuthLoading] = useState(true);
  const [isUpdating, setIsUpdating] = useState(false);
  const [errorMsg, setErrorMsg] = useState("");
  const [adminUser, setAdminUser] = useState<any>(null);

  useEffect(() => {
    const unsubscribe = onAuthStateChanged(auth, (user) => {
      setAdminUser(user);
      setIsAuthLoading(false);
    });
    return () => unsubscribe();
  }, []);

  useEffect(() => {
    const fetchParticipant = async () => {
      if (!id) return;
      try {
        const docRef = doc(db, "offline_participants", id);
        const docSnap = await getDoc(docRef);

        if (docSnap.exists()) {
          setParticipant({ id: docSnap.id, ...docSnap.data() });
        } else {
          setErrorMsg("Data tiket tidak ditemukan di database Offline Run.");
        }
      } catch (error) {
        console.error("Error fetching data:", error);
        setErrorMsg("Gagal terhubung ke server database.");
      } finally {
        setIsLoading(false);
      }
    };

    fetchParticipant();
  }, [id]);

  const handleCheckIn = async () => {
    if (!adminUser) {
      toast.error("Akses Ditolak! Hanya Panitia yang dapat melakukan aksi ini.");
      return;
    }

    if (
      !confirm(
        "Konfirmasi: Tandai Race Pack dan Jersey peserta ini SUDAH DIAMBIL?",
      )
    )
      return;

    setIsUpdating(true);
    try {
      const docRef = doc(db, "offline_participants", id);
      const currentTime = new Date().toISOString();
      const handlerName = adminUser.email || "Admin Lapangan";

      await updateDoc(docRef, {
        isRacepackTaken: true,
        waktuAmbilRacepack: currentTime,
        adminHandler: handlerName,
      });

      await addDoc(collection(db, "vr_logs"), {
        type: "resi",
        action: "menyerahkan racepack offline (via scan tiket) untuk",
        targetName: participant.namaLengkap,
        adminEmail: handlerName,
        timestamp: Date.now(),
