      setParticipant((prev: any) => ({
        ...prev,
        isRacepackTaken: true,
        waktuAmbilRacepack: currentTime,
        adminHandler: handlerName,
      }));
    } catch (error) {
      console.error(error);
      toast.error("Gagal mengupdate data. Silakan coba lagi atau cek koneksi.");
    } finally {
      setIsUpdating(false);
    }
  };

  if (isLoading || isAuthLoading) {
    return (
