  );
}

"use client";

import { useState, useEffect } from "react";
import { useParams, useRouter } from "next/navigation";
import { db } from "@/lib/firebase";
import {
  doc,
  getDoc,
  collection,
  getDocs,
  query,
  where,
} from "firebase/firestore";
import Link from "next/link";

export default function VerifyCertificatePage() {
  const params = useParams();
  const router = useRouter();
  const certId = params.id as string; // Contoh: MC-IKA-ABCDE-12345

  const [isLoading, setIsLoading] = useState(true);
  const [status, setStatus] = useState<"loading" | "valid" | "invalid">(
    "loading",
  );

  // Data Hasil Validasi
  const [studentData, setStudentData] = useState<any>(null);
  const [courseData, setCourseData] = useState<any>(null);
  const [completionDate, setCompletionDate] = useState<Date | null>(null);

  useEffect(() => {
    if (certId) {
      verifyCertificate(certId);
    }
  }, [certId]);

  const verifyCertificate = async (id: string) => {
    setIsLoading(true);
    try {
      // 1. Pecah Kode Sertifikat
      const parts = id.split("-");
      if (parts.length !== 4 || parts[0] !== "MC" || parts[1] !== "IKA") {
        setStatus("invalid");
        setIsLoading(false);
        return;
      }

      const uidPrefix = parts[2].toUpperCase();
      const coursePrefix = parts[3].toUpperCase();

      // 2. Tarik semua data progress kelulusan untuk dicocokkan
      const progressSnap = await getDocs(
        collection(db, "masterclass_progress"),
      );
      let foundProgress: any = null;
      let actualUid = "";
      let actualCourseId = "";

      for (const doc of progressSnap.docs) {
        const data = doc.data();
        const dataUid = data.uid || doc.id.split("_")[0];
        const dataCourse = data.courseId || doc.id.split("_")[1];

        // Cocokkan 5 huruf pertama UID dan 5 huruf pertama Course ID
        if (
          dataUid.toUpperCase().startsWith(uidPrefix) &&
          dataCourse.toUpperCase().startsWith(coursePrefix)
        ) {
          foundProgress = data;
          actualUid = dataUid;
          actualCourseId = dataCourse;
          break; // Ketemu! Berhenti mencari
        }
      }

      if (!foundProgress) {
        setStatus("invalid");
        setIsLoading(false);
        return;
      }

      // 3. Validasi ulang apakah benar-benar 100% Selesai
      const qMod = query(
        collection(db, "masterclass_modules"),
        where("courseId", "==", actualCourseId),
      );
      const modSnap = await getDocs(qMod);
      const totalModules = modSnap.size;

      const completedArray = foundProgress.completedModules || [];
      const validCompletedCount = completedArray.filter((modId: string) =>
        modSnap.docs.some((m) => m.id === modId),
      ).length;

      // Jika belum selesai 100%, sertifikat dianggap belum sah
      if (totalModules === 0 || validCompletedCount < totalModules) {
        setStatus("invalid");
        setIsLoading(false);
        return;
      }

      // 4. Tarik Profil Siswa dan Detail Kelas
      const userSnap = await getDoc(doc(db, "users", actualUid));
      const courseSnap = await getDoc(
        doc(db, "masterclass_courses", actualCourseId),
      );

      if (!userSnap.exists() || !courseSnap.exists()) {
        setStatus("invalid");
        setIsLoading(false);
        return;
      }

      // 5. Data Valid! Masukkan ke state
      setStudentData(userSnap.data());
      setCourseData(courseSnap.data());
      setCompletionDate(foundProgress.lastUpdated?.toDate() || new Date());
      setStatus("valid");
    } catch (error) {
      console.error("Verification Error:", error);
      setStatus("invalid");
    } finally {
      setIsLoading(false);
    }
  };

  if (isLoading) {
    return (
      <div className="min-h-screen flex flex-col items-center justify-center bg-slate-50 font-sans">
        <div className="w-16 h-16 border-4 border-slate-200 border-t-[#0056D2] rounded-full animate-spin mb-6 shadow-sm"></div>
        <h2 className="text-xl font-black text-slate-800 mb-2">
          Memverifikasi Dokumen
        </h2>
        <p className="text-slate-500 text-sm font-medium">
          Mencocokkan nomor registrasi dengan database pusat...
        </p>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-slate-100 flex flex-col items-center justify-center py-12 px-4 font-sans relative overflow-hidden">
      {/* Background Ornamen IKA UII */}
      <div className="absolute top-0 left-0 w-full h-96 bg-[#0B1528] rounded-b-[4rem] shadow-xl"></div>

      <div className="relative z-10 w-full max-w-xl">
        {/* LOGO HEADER */}
        <div className="flex flex-col items-center justify-center mb-8">
          <Link href="/" className="bg-white p-3 rounded-2xl shadow-lg mb-4">
            <img
              src="/logo-dpp-ika.png"
              alt="Logo IKA UII"
              className="h-12 object-contain"
            />
          </Link>
          <h1 className="text-white font-black text-2xl tracking-widest uppercase">
            Portal Validasi
          </h1>
          <p className="text-blue-200 text-xs font-bold uppercase tracking-[0.2em] mt-1">
            Masterclass IKA UII DIY
          </p>
        </div>

        {/* KARTU HASIL VERIFIKASI */}
        <div className="bg-white rounded-3xl shadow-2xl overflow-hidden border border-slate-200">
          {status === "valid" ? (
            <>
              <div className="bg-emerald-50 border-b border-emerald-100 p-8 text-center">
                <div className="w-20 h-20 bg-emerald-500 text-white rounded-full flex items-center justify-center mx-auto mb-4 shadow-lg shadow-emerald-500/30 ring-4 ring-white">
                  <svg
                    className="w-10 h-10"
                    fill="none"
                    viewBox="0 0 24 24"
                    stroke="currentColor"
                  >
                    <path
                      strokeLinecap="round"
                      strokeLinejoin="round"
                      strokeWidth={3}
                      d="M5 13l4 4L19 7"
                    />
                  </svg>
                </div>
                <h2 className="text-2xl font-black text-emerald-700 uppercase tracking-wide">
                  Dokumen Valid
                </h2>
                <p className="text-emerald-600/80 text-sm font-medium mt-1">
                  Sertifikat ini resmi dan tercatat di database IKA UII DIY.
                </p>
              </div>

              <div className="p-8 space-y-6">
                <div>
                  <p className="text-[10px] uppercase tracking-widest text-slate-400 font-bold mb-1">
                    Nomor Registrasi Sertifikat
                  </p>
                  <div className="bg-slate-50 border border-slate-200 rounded-xl px-4 py-3 flex items-center justify-between">
                    <p className="font-mono text-lg font-black text-[#0B1528] tracking-widest">
                      {certId}
                    </p>
                    <svg
                      className="w-5 h-5 text-emerald-500"
                      fill="none"
                      viewBox="0 0 24 24"
                      stroke="currentColor"
                    >
                      <path
                        strokeLinecap="round"
                        strokeLinejoin="round"
                        strokeWidth={2}
                        d="M9 12l2 2 4-4m6 2a9 9 0 11-18 0 9 9 0 0118 0z"
                      />
                    </svg>
                  </div>
                </div>

                <div className="grid grid-cols-1 sm:grid-cols-2 gap-6">
                  <div>
                    <p className="text-[10px] uppercase tracking-widest text-slate-400 font-bold mb-1">
                      Diberikan Kepada
                    </p>
                    <p className="text-base font-bold text-slate-900 capitalize leading-snug">
                      {studentData?.displayName ||
                        studentData?.nama ||
                        "Alumni UII"}
                    </p>
                    <p className="text-xs text-slate-500 mt-0.5">
                      {studentData?.email}
                    </p>
                  </div>
                  <div>
                    <p className="text-[10px] uppercase tracking-widest text-slate-400 font-bold mb-1">
                      Tanggal Kelulusan
                    </p>
                    <p className="text-base font-bold text-slate-900 leading-snug">
                      {completionDate?.toLocaleDateString("id-ID", {
                        day: "numeric",
                        month: "long",
                        year: "numeric",
                      })}
                    </p>
                  </div>
                </div>

                <div className="border-t border-slate-100 pt-6">
                  <p className="text-[10px] uppercase tracking-widest text-slate-400 font-bold mb-2">
                    Program Pelatihan Diselesaikan
                  </p>
                  <div className="flex gap-4 items-center">
                    <div className="w-12 h-12 rounded-xl bg-slate-100 border border-slate-200 overflow-hidden shrink-0">
                      {courseData?.thumbnailUrl ? (
                        <img
                          src={courseData.thumbnailUrl}
                          alt="Cover"
                          className="w-full h-full object-cover"
                        />
                      ) : (
                        <div className="w-full h-full flex items-center justify-center bg-blue-50 text-[#0056D2]">
                          <svg
                            className="w-6 h-6"
                            fill="none"
                            viewBox="0 0 24 24"
                            stroke="currentColor"
                          >
                            <path
                              strokeLinecap="round"
                              strokeLinejoin="round"
                              strokeWidth={2}
                              d="M19 11H5m14 0a2 2 0 012 2v6a2 2 0 01-2 2H5a2 2 0 01-2-2v-6a2 2 0 012-2m14 0V9a2 2 0 00-2-2M5 11V9a2 2 0 002-2m0 0V5a2 2 0 012-2h6a2 2 0 012 2v2M7 7h10"
                            />
                          </svg>
                        </div>
                      )}
                    </div>
                    <div>
                      <h4 className="font-bold text-slate-800 text-sm leading-snug">
                        {courseData?.judul}
                      </h4>
                      <p className="text-xs text-slate-500 uppercase tracking-wider mt-1">
                        {courseData?.kategori}
                      </p>
                    </div>
                  </div>
                </div>
              </div>
            </>
          ) : (
            <>
              <div className="bg-rose-50 border-b border-rose-100 p-10 text-center">
                <div className="w-24 h-24 bg-rose-500 text-white rounded-full flex items-center justify-center mx-auto mb-6 shadow-lg shadow-rose-500/30 ring-4 ring-white">
                  <svg
                    className="w-12 h-12"
                    fill="none"
                    viewBox="0 0 24 24"
                    stroke="currentColor"
                  >
                    <path
                      strokeLinecap="round"
                      strokeLinejoin="round"
                      strokeWidth={3}
                      d="M6 18L18 6M6 6l12 12"
                    />
                  </svg>
                </div>
                <h2 className="text-3xl font-black text-rose-700 uppercase tracking-wide">
                  Tidak Valid
                </h2>
                <p className="text-rose-600/80 text-sm font-medium mt-2 max-w-xs mx-auto">
                  Dokumen dengan nomor registrasi tersebut tidak ditemukan di
                  dalam database kami, atau peserta belum menyelesaikan
                  pelatihan.
                </p>
              </div>
              <div className="p-8 text-center bg-slate-50">
                <p className="text-xs text-slate-500 mb-4">
                  Nomor yang Anda cari:
                </p>
                <p className="font-mono text-lg font-bold text-slate-700 tracking-widest bg-white py-2 px-4 rounded-lg border border-slate-200 inline-block">
                  {certId}
                </p>
              </div>
            </>
          )}

          <div className="bg-[#F8FAFC] border-t border-slate-200 p-6 text-center">
            <Link
              href="/"
              className="inline-flex items-center justify-center gap-2 text-sm font-bold text-[#0056D2] hover:text-[#00419E] transition-colors"
            >
              <svg
                className="w-4 h-4"
                fill="none"
                viewBox="0 0 24 24"
                stroke="currentColor"
              >
                <path
                  strokeLinecap="round"
                  strokeLinejoin="round"
                  strokeWidth={2.5}
                  d="M10 19l-7-7m0 0l7-7m-7 7h18"
                />
              </svg>
              Kembali ke Beranda Utama
            </Link>
          </div>
        </div>

        <div className="text-center mt-8 text-slate-400 text-xs">
          <p>
            © {new Date().getFullYear()} Dewan Pimpinan Wilayah Ikatan Keluarga
            Alumni UII DIY.
          </p>
          <p className="mt-1">Sistem Validasi Dokumen Digital v1.0</p>
        </div>
      </div>
    </div>
  );
}

"use client";

import { useState, useEffect } from "react";
import { auth, db } from "@/lib/firebase";
import { GoogleAuthProvider, signInWithPopup, signInWithCustomToken, onAuthStateChanged, signOut } from "firebase/auth";
import {
  collection,
  query,
  where,
  getDocs,
  addDoc,
  onSnapshot,
  orderBy,
  doc,
  getDoc,
  updateDoc,
} from "firebase/firestore";
import Link from "next/link";
import { QRCodeCanvas } from "qrcode.react";
import { Activity, Mail, KeyRound, ArrowRight, ShieldCheck, User, MapPin, Calendar, CreditCard, UploadCloud, ChevronDown, Trophy, Medal, CheckCircle2, Clock, History, Edit3, Camera, FileText, Info, LogOut, Check, X, Eye, Search, Image as ImageIcon, Share2, Copy, Shield } from "lucide-react";
import { sendEmailAction } from "@/app/actions/email";


export default function ParticipantDashboard() {
  // --- STATE LOGIN ---
  const [emailLogin, setEmailLogin] = useState("");
  const [isLoggingIn, setIsLoggingIn] = useState(false);
  const [isCheckingSession, setIsCheckingSession] = useState(true);

  // --- STATE MULTI-EVENT ---
  const [participantList, setParticipantList] = useState<any[]>([]);
  const [participant, setParticipant] = useState<any>(null);

  // --- STATE SETTING ADMIN (DIBUTUHKAN UNTUK METODE BAYAR) ---
  const [vrSettings, setVrSettings] = useState<any>(null);

  // --- STATE DASHBOARD & UPLOAD BUKTI LARI ---
  const [submissions, setSubmissions] = useState<any[]>([]);
  const [uploadData, setUploadData] = useState({
    km: "",
    durasi: "",
    tanggalLari: "",
  });
  const [selectedFile, setSelectedFile] = useState<File | null>(null);
  const [previewUrl, setPreviewUrl] = useState<string | null>(null);
  const [isUploading, setIsUploading] = useState(false);

  // --- STATE UPLOAD BUKTI PEMBAYARAN (MANUAL/QRIS) ---
  const [selectedPaymentFile, setSelectedPaymentFile] = useState<File | null>(
    null,
  );
  const [previewPaymentUrl, setPreviewPaymentUrl] = useState<string | null>(
    null,
  );
  const [isUploadingPayment, setIsUploadingPayment] = useState(false);

  // --- STATE EDIT PROFIL ---
  const [motto, setMotto] = useState("");
  const [profilFile, setProfilFile] = useState<File | null>(null);
  const [headerFile, setHeaderFile] = useState<File | null>(null);
  const [isUpdatingProfil, setIsUpdatingProfil] = useState(false);

  // --- STATE LOGIN & OTP ---
  const [loginStep, setLoginStep] = useState<"email" | "otp">("email");
  const [otpInput, setOtpInput] = useState("");
  const [isVerifyingOtp, setIsVerifyingOtp] = useState(false);

  // --- STATE UI NAVIGATION, MODALS, & PAYMENTS ---
  const [popup, setPopup] = useState<{
    type: "success" | "error" | "info" | "loading";
    title: string;
    text: string;
  } | null>(null);
  const [isDropdownOpen, setIsDropdownOpen] = useState(false);
  const [activeView, setActiveView] = useState<
    "dashboard" | "riwayat" | "profil"
  >("dashboard");
  const [isPaying, setIsPaying] = useState(false);

  // --- BASE URL UNTUK QR CODE ---
  const baseUrl =
    typeof window !== "undefined"
      ? window.location.origin
      : "http://localhost:3000";

  // --- 0. LOAD SCRIPT MIDTRANS & SETTING ADMIN & CEK SESI ---
  useEffect(() => {
    const fetchSettingsAndInit = async () => {
      try {
        const docRef = doc(db, "settings", "virtual_run");
        const docSnap = await getDoc(docRef);

        if (docSnap.exists()) {
          const data = docSnap.data();
          setVrSettings(data);

          // A. Load Script Midtrans HANYA jika metode adalah midtrans
          if (data.metodePembayaran === "midtrans" && data.midtransClientKey) {
            const scriptUrl = data.isProduction
              ? "https://app.midtrans.com/snap/snap.js"
              : "https://app.sandbox.midtrans.com/snap/snap.js";

            if (!document.querySelector(`script[src="${scriptUrl}"]`)) {
              const scriptTag = document.createElement("script");
              scriptTag.src = scriptUrl;
              scriptTag.setAttribute("data-client-key", data.midtransClientKey);
              scriptTag.async = true;
              document.body.appendChild(scriptTag);
            }
          }
        }
      } catch (error) {
        console.error("Gagal load pengaturan:", error);
      }
    };

    fetchSettingsAndInit();

    // B. Cek Session Resmi Firebase
    const unsubscribe = onAuthStateChanged(auth, (user) => {
      if (user && user.email) {
        setEmailLogin(user.email);
        fetchParticipantData(user.email).finally(() => {
          setIsCheckingSession(false);
        });
      } else {
        localStorage.removeItem("vr_user_email");
        setIsCheckingSession(false);
      }
    });

    return () => unsubscribe();
  }, []);

  // Set default motto kalau data participant sudah di-load
  useEffect(() => {
    if (participant && participant.motto) {
      setMotto(participant.motto);
    }
  }, [participant]);

  // --- 1. LOGIKA LOGIN UTAMA ---
  const performLogin = async (emailToCheck: string, isAutoLogin = false) => {
    if (isAutoLogin) {
      await fetchParticipantData(emailToCheck);
      setIsCheckingSession(false);
      return;
    }
    
    setIsLoggingIn(true);
    try {
      const res = await fetch("/api/vr-auth/request-otp", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ email: emailToCheck }),
      });
      
      let data: any = {};
      const contentType = res.headers.get("content-type");
      if (contentType && contentType.includes("application/json")) {
        data = await res.json();
      } else {
        const text = await res.text();
        console.error("Non-JSON response from server (request-otp):", text);
        throw new Error(`Server error (${res.status})`);
      }
      
      if (!res.ok) {
        setPopup({ type: "error", title: "Email Tidak Ditemukan", text: data.error || "Pastikan email yang Anda masukkan terdaftar." });
        localStorage.removeItem("vr_user_email");
      } else {
        setLoginStep("otp");
      }
    } catch (error) {
      console.error("Login error:", error);
      setPopup({ type: "error", title: "Koneksi Bermasalah", text: "Gagal terhubung ke server." });
    } finally {
      setIsLoggingIn(false);
    }
  };

  // --- 1.B LOGIKA LOGIN GOOGLE ---
  const handleGoogleLogin = async () => {
    setIsLoggingIn(true);
    try {
      const provider = new GoogleAuthProvider();
      const result = await signInWithPopup(auth, provider);
      const emailToCheck = result.user.email;
      
      if (!emailToCheck) {
        throw new Error("Tidak dapat membaca email dari Google");
      }

      const q = query(
        collection(db, "vr_participants"),
        where("email", "==", emailToCheck.trim().toLowerCase()),
      );
      const snap = await getDocs(q);

      if (snap.empty) {
        setPopup({ type: "error", title: "Belum Terdaftar", text: "Email Google Anda belum terdaftar sebagai peserta Virtual Run." });
        auth.signOut();
      } else {
        await fetchParticipantData(emailToCheck);
      }
    } catch (error: any) {
      console.error("Google Login Error:", error);
      if (error.code !== "auth/popup-closed-by-user") {
        setPopup({ type: "error", title: "Login Gagal", text: "Terjadi kesalahan saat masuk dengan Google." });
      }
    } finally {
      setIsLoggingIn(false);
    }
  };

  const verifyOtpAndLogin = async (e: React.FormEvent) => {
    e.preventDefault();
    setIsVerifyingOtp(true);
    try {
      const res = await fetch("/api/vr-auth/verify-otp", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ email: emailLogin, code: otpInput }),
      });
      
      let data: any = {};
      const contentType = res.headers.get("content-type");
      if (contentType && contentType.includes("application/json")) {
        data = await res.json();
      } else {
        const text = await res.text();
        console.error("Non-JSON response from server (verify-otp):", text);
        throw new Error(`Server error (${res.status})`);
      }

      if (!res.ok) {
        setPopup({ type: "error", title: "Kode Salah", text: data.error || "Kode OTP tidak valid." });
      } else if (data.token) {
        // Sign in with Firebase Custom Token
        await signInWithCustomToken(auth, data.token);
        await fetchParticipantData(emailLogin);
      }
    } catch (error) {
      setPopup({ type: "error", title: "Error", text: "Gagal memverifikasi OTP." });
    } finally {
      setIsVerifyingOtp(false);
    }
  };

  const fetchParticipantData = async (emailToCheck: string) => {
    try {
      const q = query(
        collection(db, "vr_participants"),
        where("email", "==", emailToCheck.trim().toLowerCase()),
      );
      const snap = await getDocs(q);

      if (!snap.empty) {
        const records = snap.docs.map((doc) => ({ id: doc.id, ...doc.data() }));

        records.sort(
          (a: any, b: any) =>
            new Date(b.waktuDaftar).getTime() -
            new Date(a.waktuDaftar).getTime(),
        );

        setParticipantList(records);

        // Listener realtime agar status lunas langsung update
        onSnapshot(doc(db, "vr_participants", records[0].id), (docSnap) => {
          if (docSnap.exists()) {
            setParticipant({ id: docSnap.id, ...docSnap.data() });
          }
        });

        setActiveView("dashboard");
      } else {
        // Email not found in participants, sign out
        signOut(auth);
        setLoginStep("email");
      }
    } catch (error) {
      console.error("Fetch data error:", error);
    }
  };

  const handleLoginSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    performLogin(emailLogin, false);
  };

  const handleLogout = () => {
    localStorage.removeItem("vr_user_email");
    setParticipantList([]);
    setParticipant(null);
    setEmailLogin("");
    setOtpInput("");
    setLoginStep("email");
    setSubmissions([]);
    setIsDropdownOpen(false);
  };

  const handleLupaEmail = () => {
    setPopup({
      type: "info",
      title: "Lupa Email Pendaftaran?",
      text: "Silakan hubungi WhatsApp/Instagram Admin IKA UII DIY beserta Nama Lengkap Anda.",
    });
  };

  const handleSwitchEvent = (e: React.ChangeEvent<HTMLSelectElement>) => {
    const selectedId = e.target.value;
    const selectedEvent = participantList.find((p) => p.id === selectedId);

    if (selectedEvent) {
      setParticipant(selectedEvent);
      setActiveView("dashboard");
    }
  };

  const pindahKeDashboardEvent = (id: string) => {
    const ev = participantList.find((p) => p.id === id);
    if (ev) {
      setParticipant(ev);
      setActiveView("dashboard");
    }
  };

  // --- 2. AMBIL DATA RIWAYAT LARI ---
  useEffect(() => {
    if (!participant) return;

    const q = query(
      collection(db, "vr_submissions"),
      where("participantId", "==", participant.id),
      orderBy("createdAt", "desc"),
    );

    const unsubscribe = onSnapshot(q, (snapshot) => {
      const data = snapshot.docs.map((doc) => ({ id: doc.id, ...doc.data() }));
      setSubmissions(data);
    });

    return () => unsubscribe();
  }, [participant?.id]);

  // --- 3. LOGIKA UPLOAD BUKTI LARI ---
  const handleFileSelect = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      setSelectedFile(file);
      setPreviewUrl(URL.createObjectURL(file));
    }
  };

  const handleUploadSubmit = async (e: React.FormEvent) => {
    e.preventDefault();

    if (!selectedFile)
      return setPopup({
        type: "error",
        title: "Pilih Foto",
        text: "Anda belum memilih foto screenshot bukti lari.",
      });

    if (!uploadData.km || !uploadData.durasi || !uploadData.tanggalLari)
      return setPopup({
        type: "error",
        title: "Data Belum Lengkap",
        text: "Mohon isi formulir dengan lengkap.",
      });

    setIsUploading(true);

    try {
      const formData = new FormData();
      formData.append("file", selectedFile);
      formData.append("upload_preset", "eventrunning");
      formData.append("cloud_name", "dp8hmxuix");

      const cloudinaryRes = await fetch(
        "https://api.cloudinary.com/v1_1/dp8hmxuix/image/upload",
        { method: "POST", body: formData },
      );

      const cloudinaryData = await cloudinaryRes.json();

      if (!cloudinaryData.secure_url)
        throw new Error("Gagal mengunggah ke Cloudinary");

      const response = await fetch("/api/vr-submit-run", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          email: participant.email,
          participantId: participant.id,
          nama: participant.nama,
          km: uploadData.km,
          durasi: uploadData.durasi,
          tanggalLari: uploadData.tanggalLari,
          imgUrl: cloudinaryData.secure_url,
        }),
      });
      if (!response.ok) {
        const err = await response.json();
        throw new Error(err.error || "Gagal menyimpan ke server");
      }

      // Trigger Email ke Admin
      sendEmailAction({
          type: "admin_notif_run",
          email: "236102601@uii.ac.id", // Ganti dengan email asli admin
          nama: participant.nama,
          detail: { jarakKm: uploadData.km },
        }).catch((e) => console.log(e));

      setPopup({
        type: "success",
        title: "Bukti Terkirim!",
        text: "Menunggu verifikasi admin agar masuk ke Total Kilometer Anda.",
      });

      setSelectedFile(null);
      setPreviewUrl(null);
      setUploadData({ km: "", durasi: "", tanggalLari: "" });
    } catch (error) {
      console.error("DEBUG UPLOAD LARI:", error);
      setPopup({
        type: "error",
        title: "Gagal Mengunggah",
        text: "Pastikan format foto benar dan internet stabil. " + (error instanceof Error ? error.message : ""),
      });
    } finally {
      setIsUploading(false);
    }
  };

  // --- 4. LOGIKA PEMBAYARAN MIDTRANS ---
  const handlePayNow = async (forceNewToken = false) => {
    if (!participant) return;

    setIsPaying(true);

    try {
      let tokenToUse = forceNewToken ? null : participant.snapToken;
      const midtransOrderId = forceNewToken
        ? `${participant.id}-${Date.now()}`
        : participant.id;

      if (!tokenToUse) {
        const response = await fetch("/api/vr-midtrans", {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({
            orderId: midtransOrderId,
