"use client";

import { useEffect, useState } from "react";
import { db } from "@/lib/firebase";
import { collection, getDocs, query, where } from "firebase/firestore";
import Link from "next/link";

export default function LeaderboardPage() {
  // --- STATE LEADERBOARD ---
  const [leaderboard, setLeaderboard] = useState<any[]>([]);
  const [isLoading, setIsLoading] = useState(true);

  // --- STATE FILTER & PENCARIAN ---
  const [activeTab, setActiveTab] = useState("Semua");
  const [activeJarak, setActiveJarak] = useState("Semua");
  const [searchQuery, setSearchQuery] = useState("");

  const [availableDistances, setAvailableDistances] = useState<string[]>([]);

  // --- STATE PAGINATION ---
  const [currentPage, setCurrentPage] = useState(1);
  const [itemsPerPage, setItemsPerPage] = useState(10);

  // --- STATE HEADER ---
  const [loggedInParticipant, setLoggedInParticipant] = useState<any>(null);
  const [isMobileMenuOpen, setIsMobileMenuOpen] = useState(false);

  // Helper Format Tanggal
  const formatDate = (dateValue: any) => {
    if (!dateValue) return "Data tidak tersedia";
    try {
      if (dateValue?.seconds) {
        return (
          new Intl.DateTimeFormat("id-ID", {
            day: "2-digit",
            month: "short",
            year: "numeric",
            hour: "2-digit",
            minute: "2-digit",
          }).format(new Date(dateValue.seconds * 1000)) + " WIB"
        );
      }
      const date = new Date(dateValue);
      if (isNaN(date.getTime())) return "Format invalid";
      return (
        new Intl.DateTimeFormat("id-ID", {
          day: "2-digit",
          month: "short",
          year: "numeric",
          hour: "2-digit",
          minute: "2-digit",
        }).format(date) + " WIB"
      );
    } catch (error) {
      return "-";
    }
  };

  useEffect(() => {
    // 1. Fetch Data Leaderboard
    const fetchLeaderboard = async () => {
      try {
        const pQuery = query(
          collection(db, "vr_participants"),
          where("statusPembayaran", "==", "Lunas"),
        );
        const pSnap = await getDocs(pQuery);
        const participants = pSnap.docs.map((doc) => ({
          id: doc.id,
          ...doc.data(),
        }));

        const distances = new Set<string>();
        participants.forEach((p: any) => {
          if (p.jarak) distances.add(p.jarak);
        });
        setAvailableDistances(Array.from(distances).sort());

        const sQuery = query(
          collection(db, "vr_submissions"),
          where("status", "==", "Approved"),
        );
        const sSnap = await getDocs(sQuery);

        const submissions = sSnap.docs
          .map((doc) => doc.data())
          .sort((a: any, b: any) => {
            const dateA = a.createdAt?.seconds
              ? a.createdAt.seconds
              : new Date(a.createdAt || 0).getTime();
            const dateB = b.createdAt?.seconds
              ? b.createdAt.seconds
              : new Date(b.createdAt || 0).getTime();
            return dateA - dateB;
          });

        const calculatedData = participants.map((p: any) => {
          const userSubmissions = submissions.filter(
            (s: any) => s.participantId === p.id,
          );

          let totalKm = 0;
          let finisherDate = null;
          let totalSeconds = 0; // 🔥 LOGIKA KALKULASI DURASI
          const targetKm = parseInt(p.jarak?.replace(/\D/g, "")) || 0;

          for (const sub of userSubmissions) {
            totalKm += sub.jarakKm || 0;
            if (totalKm >= targetKm && !finisherDate) {
              finisherDate = sub.createdAt;
            }

            // 🔥 SUPER PARSER DURASI: Tahan Banting Segala Format
            if (sub.durasi) {
              let sec = 0;
              const str = String(sub.durasi).toLowerCase().trim();

              if (str.includes(":")) {
                const parts = str
                  .split(":")
                  .map((n) => parseInt(n.replace(/\D/g, "")) || 0);
                if (parts.length >= 3) {
                  // Format HH:MM:SS
                  sec = parts[0] * 3600 + parts[1] * 60 + parts[2];
                } else if (parts.length === 2) {
                  // Format MM:SS
                  sec = parts[0] * 60 + parts[1];
                }
              } else if (
                str.includes("j") ||
                str.includes("h") ||
                str.includes("m") ||
                str.includes("s")
              ) {
                const jamMatch = str.match(/(\d+)\s*(j|h)/);
                const menitMatch = str.match(/(\d+)\s*(m)/);
                const detikMatch = str.match(/(\d+)\s*(s|d)/);
                if (jamMatch) sec += parseInt(jamMatch[1]) * 3600;
                if (menitMatch) sec += parseInt(menitMatch[1]) * 60;
                if (detikMatch) sec += parseInt(detikMatch[1]);
              } else {
                // Kalau cuma ngetik angka misal "30", anggap itu menit
                const num = parseFloat(str);
                if (!isNaN(num)) sec = Math.floor(num * 60);
              }
              if (!isNaN(sec)) totalSeconds += sec;
            }
          }

          // Format hasil akhir durasi
          const h = Math.floor(totalSeconds / 3600);
          const m = Math.floor((totalSeconds % 3600) / 60);
          const s = totalSeconds % 60;

          let totalDurasiFormat = "0j 0m";
          if (h > 0) totalDurasiFormat = `${h}j ${m}m`;
          else if (m > 0) totalDurasiFormat = `${m}m ${s}s`;
          else if (s > 0) totalDurasiFormat = `${s}s`;

          const isFinisher = totalKm >= targetKm;
          const persentase =
            targetKm > 0 ? Math.min(100, (totalKm / targetKm) * 100) : 0;

          return {
            ...p,
            kategori: p.kategori || "Umum",
            totalKm,
            targetKm,
            totalDurasiFormat, // Format Durasi tersimpan
            isFinisher,
            persentase,
            finisherDate,
            registeredDate:
              p.tanggalDaftar || p.createdAt || p.timestamp || null,
          };
        });

        calculatedData.sort((a, b) => {
          if (b.totalKm !== a.totalKm) return b.totalKm - a.totalKm;
          // Kalau KM sama, yang duluan finisher ditaruh atas
          if (
            a.isFinisher &&
            b.isFinisher &&
            a.finisherDate &&
            b.finisherDate
          ) {
            const dateA = a.finisherDate?.seconds
              ? a.finisherDate.seconds
              : new Date(a.finisherDate).getTime();
            const dateB = b.finisherDate?.seconds
              ? b.finisherDate.seconds
              : new Date(b.finisherDate).getTime();
            return dateA - dateB;
          }
          return 0;
        });

        setLeaderboard(calculatedData);
      } catch (error) {
        console.error("Gagal memuat leaderboard:", error);
      } finally {
        setIsLoading(false);
      }
    };

    const checkLogin = async () => {
      try {
        const savedEmail = localStorage.getItem("vr_user_email");
        if (savedEmail) {
          const qUser = query(
            collection(db, "vr_participants"),
            where("email", "==", savedEmail),
          );
          const userSnap = await getDocs(qUser);
          if (!userSnap.empty) {
            const userRecords = userSnap.docs.map((d) => ({
              id: d.id,
              ...d.data(),
            }));
            userRecords.sort((a: any, b: any) => {
              const timeA = new Date(
                a.tanggalDaftar || a.createdAt || 0,
              ).getTime();
              const timeB = new Date(
                b.tanggalDaftar || b.createdAt || 0,
              ).getTime();
              return timeB - timeA;
            });
            setLoggedInParticipant(userRecords[0]);
          }
        }
      } catch (error) {
        console.error("Gagal cek sesi:", error);
      }
    };

    fetchLeaderboard();
    checkLogin();
  }, []);

  const filteredLeaderboard = leaderboard.filter((p) => {
    const matchKategori = activeTab === "Semua" || p.kategori === activeTab;
    const matchJarak = activeJarak === "Semua" || p.jarak === activeJarak;
    const matchSearch = p.nama
      .toLowerCase()
      .includes(searchQuery.toLowerCase());

    return matchKategori && matchJarak && matchSearch;
  });

  useEffect(() => {
    setCurrentPage(1);
  }, [searchQuery, activeTab, activeJarak, itemsPerPage]);

  const totalPages = Math.ceil(filteredLeaderboard.length / itemsPerPage);
  const startIndex = (currentPage - 1) * itemsPerPage;
  const paginatedData = filteredLeaderboard.slice(
    startIndex,
    startIndex + itemsPerPage,
  );

  const isPageOne = currentPage === 1;
  const podiumData = isPageOne ? paginatedData.slice(0, 3) : [];
  const listData = isPageOne ? paginatedData.slice(3) : paginatedData;

  // 🔥 DESAIN PODIUM PROFESIONAL
  const podiumOrder = [
    {
      rank: 2,
      data: podiumData[1],
      height: "h-36",
      bgClass: "bg-gradient-to-t from-slate-200 to-slate-50",
      rankColor: "bg-slate-500",
    },
    {
      rank: 1,
      data: podiumData[0],
      height: "h-44",
      bgClass: "bg-gradient-to-t from-yellow-200 to-yellow-50",
      rankColor: "bg-yellow-500",
      scale: "z-10 shadow-xl", // Ditinggikan sedikit tapi elegan
    },
    {
      rank: 3,
      data: podiumData[2],
      height: "h-28",
      bgClass: "bg-gradient-to-t from-orange-200 to-orange-50",
      rankColor: "bg-orange-600",
    },
  ];

  if (isLoading) {
    return (
      <div className="min-h-screen bg-[#F4F7FB] flex flex-col items-center justify-center">
        <div className="w-14 h-14 border-4 border-slate-200 border-t-yellow-500 rounded-full animate-spin mb-4"></div>
        <p className="text-slate-500 font-bold text-sm uppercase tracking-widest animate-pulse">
          Memuat Klasemen...
        </p>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-[#F4F7FB] font-sans flex flex-col selection:bg-yellow-300 selection:text-blue-900">
      {/* HEADER UNIVERSAL */}
      <header className="fixed top-0 left-0 w-full z-50 bg-white/90 backdrop-blur-md border-b border-slate-200 shadow-sm transition-all">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 h-20 flex items-center justify-between">
          <Link
            href="/"
            className="flex items-center gap-2 sm:gap-3 group shrink-0"
          >
            <div className="bg-blue-600 p-1.5 rounded-lg group-hover:bg-blue-700 transition-colors shrink-0">
              <img
                src="/logo-dpp-ika.png"
                alt="Logo IKA UII"
                className="w-7 h-7 sm:w-8 sm:h-8 object-contain"
              />
            </div>
            <div className="flex flex-col justify-center min-w-0">
              <h1 className="font-black text-slate-800 text-sm sm:text-lg leading-none tracking-tight truncate">
                IKA UII DIY
              </h1>
              <p className="text-[8px] sm:text-[10px] font-bold text-blue-600 uppercase tracking-widest mt-0.5 truncate">
                Virtual Run Event
              </p>
            </div>
          </Link>

          <nav className="hidden md:flex items-center gap-6 lg:gap-8 text-sm font-bold text-slate-600">
            <a
              href="/virtual-run#hero"
              className="hover:text-blue-600 transition-colors"
            >
              Beranda
            </a>
            <a
              href="/virtual-run#race-pack"
              className="hover:text-blue-600 transition-colors"
            >
              Race Pack
            </a>
            <a
              href="/virtual-run#route"
              className="hover:text-blue-600 transition-colors"
            >
              Rute
            </a>
            <a
              href="/virtual-run#timeline"
              className="hover:text-blue-600 transition-colors"
            >
              Timeline
            </a>
            <a
              href="/virtual-run#paket"
              className="hover:text-blue-600 transition-colors"
            >
              Paket Lari
            </a>
            <Link
              href="/virtual-run/leaderboard"
              className="text-blue-600 transition-colors border-b-2 border-blue-600 pb-1"
            >
              Lihat Klasemen
            </Link>
          </nav>

          <div className="flex items-center gap-2 sm:gap-3">
            <Link
              href="/virtual-run/dashboard"
              className={`border font-bold px-4 py-2.5 rounded-full text-xs transition-all shadow-sm flex items-center gap-2 shrink-0 ${loggedInParticipant ? "bg-blue-600 text-white border-blue-600 hover:bg-blue-700" : "bg-white border-slate-200 hover:bg-slate-50 text-slate-800"}`}
            >
              {loggedInParticipant ? (
                <>
                  <span className="w-4 h-4 bg-white/20 rounded-full flex items-center justify-center text-[8px]">
                    👤
                  </span>
                  <span>Dashboard</span>
                </>
              ) : (
                <>
                  <svg
                    className="w-4 h-4 text-blue-600"
                    fill="none"
                    viewBox="0 0 24 24"
                    stroke="currentColor"
                  >
                    <path
                      strokeLinecap="round"
                      strokeLinejoin="round"
                      strokeWidth={2}
                      d="M11 16l-4-4m0 0l4-4m-4 4h14m-5 4v1a3 3 0 01-3 3H6a3 3 0 01-3-3V7a3 3 0 013-3h7a3 3 0 013 3v1"
                    />
                  </svg>
                  <span>Login</span>
                </>
              )}
            </Link>

            <button
              onClick={() => setIsMobileMenuOpen(!isMobileMenuOpen)}
              className="md:hidden p-1.5 text-slate-600 hover:text-blue-600 focus:outline-none shrink-0"
            >
              <svg
                className="w-6 h-6"
                fill="none"
                viewBox="0 0 24 24"
                stroke="currentColor"
              >
                {isMobileMenuOpen ? (
                  <path
                    strokeLinecap="round"
                    strokeLinejoin="round"
                    strokeWidth={2}
                    d="M6 18L18 6M6 6l12 12"
                  />
                ) : (
                  <path
                    strokeLinecap="round"
                    strokeLinejoin="round"
                    strokeWidth={2}
                    d="M4 6h16M4 12h16M4 18h16"
                  />
                )}
              </svg>
            </button>
          </div>
        </div>

        {isMobileMenuOpen && (
          <div className="md:hidden absolute top-20 left-0 w-full bg-white border-b border-slate-200 shadow-lg py-4 px-6 flex flex-col gap-4 text-sm font-bold text-slate-600">
            <a
              href="/virtual-run#hero"
              onClick={() => setIsMobileMenuOpen(false)}
              className="hover:text-blue-600 py-2 border-b border-slate-50"
            >
              Beranda
            </a>
            <a
              href="/virtual-run#race-pack"
              onClick={() => setIsMobileMenuOpen(false)}
              className="hover:text-blue-600 py-2 border-b border-slate-50"
            >
              Race Pack
            </a>
            <a
              href="/virtual-run#route"
              onClick={() => setIsMobileMenuOpen(false)}
              className="hover:text-blue-600 py-2 border-b border-slate-50"
            >
              Rute
            </a>
            <a
              href="/virtual-run#timeline"
              onClick={() => setIsMobileMenuOpen(false)}
              className="hover:text-blue-600 py-2 border-b border-slate-50"
            >
              Timeline
            </a>
            <a
              href="/virtual-run#paket"
              onClick={() => setIsMobileMenuOpen(false)}
              className="hover:text-blue-600 py-2 border-b border-slate-50"
            >
              Paket Lari
            </a>
            <Link
              href="/virtual-run/leaderboard"
              onClick={() => setIsMobileMenuOpen(false)}
              className="text-blue-600 py-2"
            >
              Lihat Klasemen
            </Link>
          </div>
        )}
      </header>

      {/* HERO LEADERBOARD */}
      <div className="bg-[#1E3A8A] pt-32 pb-28 px-4 text-center text-white relative overflow-hidden shrink-0">
        <div className="absolute inset-0 bg-[url('https://www.transparenttextures.com/patterns/cubes.png')] opacity-10"></div>
        <div className="relative z-10 max-w-3xl mx-auto">
          <div className="inline-block bg-yellow-400 text-blue-900 text-[9px] font-black px-4 py-1.5 rounded-full mb-5 uppercase tracking-widest shadow-lg flex items-center gap-2 w-fit mx-auto">
            <span className="relative flex h-2 w-2"></span>
            Live Leaderboard
          </div>
          <h1 className="text-4xl sm:text-5xl font-black mb-4 tracking-tight">
            Klasemen Pelari
          </h1>
          <p className="text-blue-200 text-sm sm:text-base font-medium max-w-lg mx-auto">
            Pantau pencapaian jarak seluruh peserta secara *real-time*. Setiap
            langkah membawa kita lebih dekat ke garis akhir.
          </p>
        </div>
      </div>

      {/* MAIN KONTEN */}
      <main className="flex-grow max-w-5xl mx-auto w-full px-4 sm:px-6 -mt-16 relative z-20 pb-20">
        {/* KONTROL FILTER & SEARCH */}
        <div className="bg-white rounded-2xl shadow-md border border-slate-200 p-4 mb-10 flex flex-col md:flex-row gap-4 items-center justify-between">
          <div className="flex flex-col sm:flex-row w-full md:w-auto gap-3">
            <div className="flex w-full sm:w-auto bg-slate-100 p-1.5 rounded-xl">
              {["Semua", "Alumni", "Umum"].map((tab) => (
                <button
                  key={tab}
                  onClick={() => setActiveTab(tab)}
                  className={`flex-1 sm:flex-none px-5 py-2 rounded-lg text-xs font-bold transition-all ${
                    activeTab === tab
                      ? "bg-white text-blue-700 shadow-sm border border-slate-200"
                      : "text-slate-500 hover:text-slate-800"
                  }`}
                >
                  {tab}
                </button>
              ))}
            </div>

            <div className="flex w-full sm:w-auto items-center">
              <select
                value={activeJarak}
                onChange={(e) => setActiveJarak(e.target.value)}
                className="w-full bg-slate-50 border border-slate-200 text-xs font-bold text-slate-700 rounded-xl px-5 py-2.5 focus:outline-none focus:ring-2 focus:ring-blue-500 focus:bg-white cursor-pointer transition-all"
              >
                <option value="Semua">Semua Kategori Jarak</option>
                {availableDistances.map((jarak) => (
                  <option key={jarak} value={jarak}>
                    Kategori {jarak}
                  </option>
                ))}
              </select>
            </div>
          </div>

          <div className="relative w-full md:w-72">
            <input
              type="text"
              placeholder="Cari nama pelari..."
              value={searchQuery}
              onChange={(e) => setSearchQuery(e.target.value)}
              className="w-full bg-slate-50 border border-slate-200 text-sm font-medium rounded-xl pl-10 pr-4 py-2.5 focus:outline-none focus:ring-2 focus:ring-blue-500 focus:bg-white transition-all"
            />
            <svg
              className="w-4 h-4 text-slate-400 absolute left-3.5 top-3"
              fill="none"
              viewBox="0 0 24 24"
              stroke="currentColor"
            >
              <path
                strokeLinecap="round"
                strokeLinejoin="round"
                strokeWidth={2}
                d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z"
              />
            </svg>
          </div>
        </div>

        {/* 🔥 PODIUM JUARA TOP 3 🔥 */}
        {isPageOne && podiumData.length > 0 && (
          <div className="flex justify-center items-end gap-3 sm:gap-6 mb-12 mt-16 px-2">
            {podiumOrder.map((item) => {
              if (!item.data) {
                return <div key={item.rank} className="w-1/3 opacity-0"></div>;
              }

              return (
                <div
                  key={item.rank}
                  className={`w-1/3 max-w-[200px] flex flex-col items-center relative transition-transform hover:-translate-y-1 ${item.scale || ""}`}
                >
                  <Link
                    href={`/u/${item.data.slug || item.data.id}`}
                    className="relative z-20 -mb-6 group"
                  >
                    {/* Logika Avatar & Foto Profil */}
                    {item.data.fotoProfilUrl ? (
                      <img
                        src={item.data.fotoProfilUrl}
                        alt={item.data.nama}
                        className={`w-14 h-14 sm:w-20 sm:h-20 rounded-full object-cover border-4 border-white shadow-md group-hover:opacity-90 transition-opacity ${item.rank === 1 ? "sm:w-24 sm:h-24" : ""}`}
                      />
                    ) : (
                      <div
                        className={`w-14 h-14 sm:w-20 sm:h-20 rounded-full bg-blue-50 text-blue-600 flex items-center justify-center font-black text-2xl border-4 border-white shadow-md group-hover:opacity-90 transition-opacity ${item.rank === 1 ? "sm:w-24 sm:h-24" : ""}`}
                      >
                        {item.data.nama.charAt(0).toUpperCase()}
                      </div>
                    )}
                    {/* Badge Nomor Rank di atas Avatar */}
                    <div
                      className={`absolute -bottom-1 sm:-bottom-2 right-0 w-6 h-6 sm:w-7 sm:h-7 rounded-full flex items-center justify-center text-xs font-bold text-white border-2 border-white shadow-sm ${item.rankColor}`}
                    >
                      {item.rank}
                    </div>
                  </Link>

                  {/* Kotak Podium */}
                  <div
                    className={`w-full ${item.bgClass} rounded-t-2xl shadow-md border border-slate-200/50 flex flex-col items-center justify-start pt-10 sm:pt-12 px-2 text-center pb-4 ${item.height}`}
                  >
                    <p className="font-bold text-[10px] sm:text-[13px] text-slate-800 leading-tight mb-1 line-clamp-2 w-full px-1">
                      {item.data.nama}
                    </p>
                    <p className="font-mono font-bold text-[9px] sm:text-[10px] text-slate-500 mb-2">
                      BIB: {item.data.nomorBibLengkap || "-"}
                    </p>
                    <div className="bg-white/60 w-full sm:w-11/12 mx-auto py-2 rounded-xl flex flex-col gap-0.5 border border-white/50">
                      <span className="font-black text-xs sm:text-sm text-blue-900">
                        {item.data.totalKm.toFixed(2)} KM
                      </span>
                      <span className="text-[9px] font-bold text-slate-500">
                        {item.data.totalDurasiFormat || "0j 0m"}
                      </span>
                    </div>
                  </div>
                </div>
              );
            })}
          </div>
        )}

        {/* Tabel / List Leaderboard Sisa */}
        <div className="bg-white rounded-3xl shadow-sm border border-slate-200 overflow-hidden mb-6">
          {paginatedData.length === 0 ? (
            <div className="text-center py-20 px-4">
              <div className="text-5xl mb-4 opacity-30 grayscale">🏃‍♂️</div>
              <h3 className="font-black text-slate-700 text-lg mb-1">
                {searchQuery ? "Pelari Tidak Ditemukan" : "Belum Ada Data"}
              </h3>
              <p className="text-sm text-slate-500">
                Coba sesuaikan filter jarak/kategori, atau gunakan kata kunci
                pencarian lain.
              </p>
            </div>
          ) : (
            <div className="divide-y divide-slate-100">
              {listData.length === 0 && isPageOne ? (
                <div className="text-center py-10 text-slate-400 font-medium text-sm bg-slate-50">
                  <p>
                    Hanya terdapat {podiumData.length} pelari pada kategori ini.
                  </p>
                </div>
              ) : (
                listData.map((pelari, index) => {
                  const rank = isPageOne ? index + 4 : startIndex + index + 1;

                  return (
                    <Link
                      href={`/u/${pelari.slug || pelari.id}`}
                      key={pelari.id}
                      className="flex flex-col sm:flex-row sm:items-center p-5 sm:p-6 hover:bg-slate-50 transition-colors group cursor-pointer relative"
                    >
                      {/* Rank Badge Mobile */}
                      <div className="absolute top-5 right-5 sm:hidden">
                        <div className="w-7 h-7 rounded-full flex items-center justify-center text-xs bg-slate-100 text-slate-500 font-bold border border-slate-200">
                          {rank}
                        </div>
                      </div>

                      <div className="flex items-center w-full sm:w-auto">
                        {/* Rank Badge Desktop */}
                        <div className="hidden sm:flex w-10 h-10 rounded-full items-center justify-center text-sm font-bold shrink-0 bg-slate-100 text-slate-500 border border-slate-200 group-hover:bg-blue-100 group-hover:text-blue-700 group-hover:border-blue-200 transition-colors">
                          {rank}
                        </div>

                        <div className="relative ml-0 sm:ml-5 shrink-0">
                          {/* Logika Avatar & Foto Profil */}
                          {pelari.fotoProfilUrl ? (
                            <img
                              src={pelari.fotoProfilUrl}
                              alt={pelari.nama}
                              className="w-14 h-14 sm:w-16 sm:h-16 rounded-full object-cover border-4 border-white shadow-sm"
                            />
                          ) : (
                            <div className="w-14 h-14 sm:w-16 sm:h-16 rounded-full bg-blue-50 text-blue-600 flex items-center justify-center font-black text-2xl border-4 border-white shadow-sm">
                              {pelari.nama.charAt(0).toUpperCase()}
                            </div>
                          )}
                        </div>

                        <div className="ml-4 min-w-0 pr-8 sm:pr-0">
                          <h4 className="font-black text-slate-800 text-base sm:text-lg truncate group-hover:text-blue-600 transition-colors mb-0.5">
                            {pelari.nama}
                          </h4>
                          {/* Info Detail Pelari */}
                          <div className="flex flex-wrap items-center gap-1.5 mt-1">
                            <span className="text-[10px] font-bold text-slate-600 uppercase bg-slate-100 px-2 py-0.5 rounded border border-slate-200">
                              {pelari.kategori}
                            </span>
                            <span className="text-[10px] font-bold text-blue-700 uppercase bg-blue-50 px-2 py-0.5 rounded border border-blue-100">
                              {pelari.jarak}
                            </span>
                            {pelari.nomorBibLengkap && (
                              <span className="text-[10px] font-mono font-bold text-slate-500 uppercase bg-white px-2 py-0.5 rounded border border-slate-200">
                                BIB: {pelari.nomorBibLengkap}
                              </span>
                            )}
                            {pelari.isFinisher && (
                              <span className="text-[10px] font-bold text-emerald-700 uppercase bg-emerald-50 px-2 py-0.5 rounded border border-emerald-200">
                                🏅 Finisher
                              </span>
                            )}
                          </div>
                        </div>
                      </div>

                      <div className="mt-4 sm:mt-0 flex-grow sm:ml-8 flex flex-col justify-center">
                        <div className="flex items-end justify-between mb-1.5">
                          <div className="text-[10px] text-slate-500 font-medium uppercase tracking-widest flex items-center gap-2">
                            <span>Progress</span>
                            <span className="bg-slate-200 w-1 h-1 rounded-full"></span>
                            <span>
                              ⏱️ {pelari.totalDurasiFormat || "0j 0m"}
                            </span>
                          </div>
                          <div className="text-right">
                            <p className="font-black text-lg text-blue-950 leading-none">
                              {pelari.totalKm.toFixed(2)}{" "}
                              <span className="text-xs text-slate-500 font-bold">
                                / {pelari.targetKm} KM
                              </span>
                            </p>
                          </div>
                        </div>

                        <div className="w-full bg-slate-100 rounded-full h-2.5 mb-3 overflow-hidden shadow-inner">
                          <div
                            className={`h-2.5 rounded-full transition-all duration-1000 ${pelari.isFinisher ? "bg-emerald-500" : "bg-gradient-to-r from-blue-400 to-blue-600"}`}
                            style={{ width: `${pelari.persentase}%` }}
                          ></div>
                        </div>

                        <div className="flex items-center justify-between text-[9px] sm:text-[10px]">
                          <div className="text-slate-500 flex items-center gap-1 font-medium">
                            <svg
                              className="w-3 h-3"
                              fill="none"
                              viewBox="0 0 24 24"
                              stroke="currentColor"
                            >
                              <path
                                strokeLinecap="round"
                                strokeLinejoin="round"
                                strokeWidth={2}
                                d="M8 7V3m8 4V3m-9 8h10M5 21h14a2 2 0 002-2V7a2 2 0 00-2-2H5a2 2 0 00-2-2v12a2 2 0 002 2z"
                              />
                            </svg>
                            Daftar: {formatDate(pelari.registeredDate)}
                          </div>
                          {pelari.isFinisher && pelari.finisherDate && (
                            <div className="text-emerald-600 font-bold flex items-center gap-1">
                              <svg
                                className="w-3 h-3"
                                fill="none"
                                viewBox="0 0 24 24"
                                stroke="currentColor"
                              >
                                <path
                                  strokeLinecap="round"
                                  strokeLinejoin="round"
                                  strokeWidth={2.5}
                                  d="M5 13l4 4L19 7"
                                />
                              </svg>
                              Selesai: {formatDate(pelari.finisherDate)}
                            </div>
                          )}
                        </div>
                      </div>
                    </Link>
                  );
                })
              )}
            </div>
          )}
        </div>

        {/* --- KONTROL PAGINATION --- */}
        {filteredLeaderboard.length > 0 && (
          <div className="flex flex-col sm:flex-row items-center justify-between gap-4 bg-white p-4 rounded-2xl shadow-sm border border-slate-200 mt-6">
            <div className="flex items-center gap-3 text-xs text-slate-500 font-bold uppercase tracking-widest">
              Tampilkan
              <select
                value={itemsPerPage}
                onChange={(e) => setItemsPerPage(Number(e.target.value))}
                className="bg-slate-50 border border-slate-200 rounded-lg px-2 py-1.5 focus:outline-none focus:ring-2 focus:ring-blue-500 cursor-pointer font-sans"
              >
                <option value={10}>10</option>
                <option value={25}>25</option>
                <option value={50}>50</option>
                <option value={100}>100</option>
              </select>
              data
            </div>

            <div className="flex items-center gap-2">
              <button
                onClick={() => setCurrentPage((prev) => Math.max(prev - 1, 1))}
                disabled={currentPage === 1}
                className="px-4 py-2 rounded-lg text-xs font-bold transition-all border border-slate-200 text-slate-600 disabled:opacity-40 disabled:bg-slate-50 hover:bg-blue-50 hover:text-blue-700 hover:border-blue-200 active:scale-95"
              >
                &larr; Sebelumnya
              </button>

              <div className="text-xs font-black text-blue-900 bg-blue-100 px-3 py-2 rounded-lg border border-blue-200 shadow-inner">
                Hal {currentPage} / {totalPages}
              </div>

              <button
                onClick={() =>
                  setCurrentPage((prev) => Math.min(prev + 1, totalPages))
                }
                disabled={currentPage === totalPages || totalPages === 0}
                className="px-4 py-2 rounded-lg text-xs font-bold transition-all border border-slate-200 text-slate-600 disabled:opacity-40 disabled:bg-slate-50 hover:bg-blue-50 hover:text-blue-700 hover:border-blue-200 active:scale-95"
              >
                Selanjutnya &rarr;
              </button>
            </div>
          </div>
        )}
      </main>

      {/* FOOTER RESMI */}
      <footer className="bg-slate-900 text-slate-400 py-12 border-t border-slate-800 mt-auto shrink-0">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 grid grid-cols-1 md:grid-cols-3 gap-8">
          <div>
            <div className="flex items-center gap-3 mb-4">
              <div className="bg-white p-1.5 rounded-lg">
                <img
                  src="/logo-dpp-ika.png"
                  alt="Logo IKA UII"
                  className="w-8 h-8 object-contain"
                />
              </div>
              <h3 className="text-white font-black text-xl">IKA UII DIY</h3>
            </div>
            <p className="text-sm leading-relaxed mb-4">
              Wadah silaturahmi, sinergi, dan kolaborasi para alumni Universitas
              Islam Indonesia di wilayah Daerah Istimewa Yogyakarta.
            </p>
          </div>
          <div>
            <h4 className="text-white font-bold mb-4 uppercase tracking-widest text-xs">
              Tautan Cepat
            </h4>
            <ul className="space-y-2 text-sm">
              <li>
                <Link
                  href="/"
                  className="hover:text-blue-400 transition-colors"
                >
                  Portal Utama
                </Link>
              </li>
              <li>
                <Link
                  href="/virtual-run/register"
                  className="hover:text-blue-400 transition-colors"
                >
                  Pendaftaran Event
                </Link>
              </li>
              <li>
                <Link
                  href="/virtual-run/dashboard"
                  className="hover:text-blue-400 transition-colors"
                >
                  Dashboard Pelari
                </Link>
              </li>
            </ul>
          </div>
          <div>
            <h4 className="text-white font-bold mb-4 uppercase tracking-widest text-xs">
              Kontak & Dukungan
            </h4>
            <ul className="space-y-2 text-sm">
              <li className="flex items-center gap-2">
                <span>📧</span> ika.diy@uii.ac.id
              </li>
              <li className="flex items-center gap-2">
                <span>📍</span> Daerah Istimewa Yogyakarta, Indonesia
              </li>
            </ul>
          </div>
        </div>
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 mt-12 pt-8 border-t border-slate-800 text-xs text-center flex flex-col md:flex-row justify-between items-center gap-4">
          <p>
            &copy; {new Date().getFullYear()} DPW IKA UII DIY. Hak Cipta
            Dilindungi.
          </p>
          <p>Made with ❤️ for UII Alumni</p>
        </div>
      </footer>
    </div>
  );
}

"use client";

import { useEffect, useState } from "react";
import { db } from "@/lib/firebase";
import {
  doc,
  getDoc,
  collection,
  query,
  where,
  getDocs,
} from "firebase/firestore";
import Link from "next/link";
import { MapPin, Calendar, Clock, Shirt, Medal, Activity, Building2, Mountain, Home, Package, Trophy, Mail, PartyPopper, Check, Menu, X, ArrowRight, User, Info, Map } from "lucide-react";

export default function VirtualRunLandingPage() {
  const [settings, setSettings] = useState<any>(null);
  const [isLoading, setIsLoading] = useState(true);
  const [timeLeft, setTimeLeft] = useState<{ [key: string]: number } | null>(
    null,
  );
  const [isWaitingToOpen, setIsWaitingToOpen] = useState(false);

  // --- STATE STATISTIK GLOBAL ---
  const [totalDonasi, setTotalDonasi] = useState(0);
  const [totalPeserta, setTotalPeserta] = useState(0);
  const [totalKm, setTotalKm] = useState(0);
  const [packageCounts, setPackageCounts] = useState<{ [key: string]: number }>({});

  // --- STATE DETEKSI USER LOGIN ---
  const [loggedInParticipant, setLoggedInParticipant] = useState<any>(null);
  const [isMobileMenuOpen, setIsMobileMenuOpen] = useState(false);

  // --- AMBIL DATA SETTING, STATISTIK & SESI ---
  useEffect(() => {
    const fetchData = async () => {
      try {
        const docRef = doc(db, "settings", "virtual_run");
        const docSnap = await getDoc(docRef);
        if (docSnap.exists()) {
          setSettings(docSnap.data());
        }

        const qPart = query(
          collection(db, "vr_participants"),
          where("statusPembayaran", "==", "Lunas"),
        );
        const snapPart = await getDocs(qPart);
        let tDonasi = 0;
        const counts: { [key: string]: number } = {};
        setTotalPeserta(snapPart.size);
        snapPart.forEach((doc) => {
          tDonasi += doc.data().nominalDonasi || 0;
          const pkgName = doc.data().paket;
          if (pkgName) {
            counts[pkgName] = (counts[pkgName] || 0) + 1;
          }
        });
        setTotalDonasi(tDonasi);
        setPackageCounts(counts);

        const qSub = query(
          collection(db, "vr_submissions"),
          where("status", "==", "Approved"),
        );
        const snapSub = await getDocs(qSub);
        let tKm = 0;
        snapSub.forEach((doc) => {
          tKm += doc.data().jarakKm || 0;
        });
        setTotalKm(tKm);

        const savedEmail = localStorage.getItem("vr_user_email");
        if (savedEmail) {
          const qUser = query(
            collection(db, "vr_participants"),
            where("email", "==", savedEmail),
          );
          const userSnap = await getDocs(qUser);
          if (!userSnap.empty) {
            const userRecords = userSnap.docs.map((d) => ({
              id: d.id,
              ...d.data(),
            }));
            userRecords.sort(
              (a: any, b: any) =>
                new Date(b.waktuDaftar).getTime() -
                new Date(a.waktuDaftar).getTime(),
            );
            setLoggedInParticipant(userRecords[0]);
          }
        }
      } catch (error) {
        console.error("Gagal mengambil data:", error);
      } finally {
        setIsLoading(false);
      }
    };
    fetchData();
  }, []);
  // --- LOGIKA DETEKSI URUTAN TIMELINE ---
  // Fungsi pintar untuk membaca teks tanggal bahasa Indonesia menjadi angka (waktu)
  const parseIndoDate = (dateStr: string) => {
    if (!dateStr) return 9999999999999; // Fallback jika kosong ditaruh di akhir
    const lower = dateStr.toLowerCase();
    const months = [
      "jan",
      "feb",
      "mar",
      "apr",
      "mei",
      "jun",
      "jul",
      "agu",
      "sep",
      "okt",
      "nov",
      "des",
    ];
    let monthIdx = 11;
    for (let i = 0; i < months.length; i++) {
      if (lower.includes(months[i])) {
        monthIdx = i;
        break;
      }
    }
    const matchNum = lower.match(/\d+/);
    const day = matchNum ? parseInt(matchNum[0]) : 1;
    const matchYear = lower.match(/20\d\d/);
    const year = matchYear ? parseInt(matchYear[0]) : new Date().getFullYear();
    return new Date(year, monthIdx, day).getTime();
  };

  // Cek mana yang lebih dulu: Lari atau Pengiriman?
  const isPengirimanAwal =
    parseIndoDate(settings?.periodePengiriman) <
    parseIndoDate(settings?.periodeLari);
  // --- LOGIKA COUNTDOWN TIMER ---
  useEffect(() => {
    if (!settings) return;
    
    const openDate = settings.tanggalPembukaan ? new Date(settings.tanggalPembukaan) : null;
    const closeDate = settings.tanggalPenutupan ? new Date(settings.tanggalPenutupan) : null;

    const calculateTimeLeft = () => {
      const currentTime = new Date();
      let targetDate = null;
      let waiting = false;

      if (openDate && currentTime < openDate) {
        targetDate = openDate;
        waiting = true;
      } else if (closeDate && currentTime < closeDate) {
        targetDate = closeDate;
      }

      setIsWaitingToOpen(waiting);

      if (!targetDate) return null;

      const difference = +targetDate - +currentTime;
      if (difference > 0) {
        return {
          Hari: Math.floor(difference / (1000 * 60 * 60 * 24)),
          Jam: Math.floor((difference / (1000 * 60 * 60)) % 24),
          Menit: Math.floor((difference / 1000 / 60) % 60),
          Detik: Math.floor((difference / 1000) % 60),
        };
      }
      return null;
    };

    setTimeLeft(calculateTimeLeft());
    const timer = setInterval(() => {
      setTimeLeft(calculateTimeLeft());
    }, 1000);

    return () => clearInterval(timer);
  }, [settings]);

  useEffect(() => {
    document.documentElement.style.scrollBehavior = "smooth";
    return () => {
      document.documentElement.style.scrollBehavior = "auto";
    };
  }, []);

  if (isLoading) {
    return (
      <div className="min-h-screen bg-slate-50 flex items-center justify-center">
        <div className="w-12 h-12 border-4 border-blue-200 border-t-blue-600 rounded-full animate-spin"></div>
      </div>
    );
  }

  if (!settings) {
    return (
      <div className="min-h-screen flex items-center justify-center font-bold text-slate-500">
        Data event belum dikonfigurasi oleh Admin.
      </div>
    );
  }

  let isBuka = settings.statusPendaftaran === "Buka";
  const openDate = settings.tanggalPembukaan ? new Date(settings.tanggalPembukaan) : null;
  const closeDate = settings.tanggalPenutupan ? new Date(settings.tanggalPenutupan) : null;
  const currentTime = new Date();

  if (openDate && currentTime < openDate) {
    isBuka = false;
  }
  if (closeDate && currentTime > closeDate) {
    isBuka = false;
  }

  return (
    <div className="min-h-screen bg-[#F4F7FB] font-sans selection:bg-yellow-300 selection:text-blue-900">
      {/* HEADER UNIVERSAL */}
      <header className="fixed top-0 left-0 w-full z-50 bg-white/90 backdrop-blur-md border-b border-slate-200 shadow-sm transition-all">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 h-20 flex items-center justify-between">
          <Link
            href="/"
            className="flex items-center gap-2 sm:gap-3 group shrink-0"
          >
            <div className="bg-blue-600 p-1.5 rounded-lg group-hover:bg-blue-700 transition-colors shrink-0">
              <img
                src="/logo-dpp-ika.png"
                alt="Logo IKA UII"
                className="w-7 h-7 sm:w-8 sm:h-8 object-contain"
              />
            </div>
            <div className="flex flex-col justify-center min-w-0">
              <h1 className="font-black text-slate-800 text-sm sm:text-lg leading-none tracking-tight truncate">
                IKA UII DIY
              </h1>
              <p className="text-[8px] sm:text-[10px] font-bold text-blue-600 uppercase tracking-widest mt-0.5 truncate">
                Virtual Run Event
              </p>
            </div>
          </Link>

          <nav className="hidden md:flex items-center gap-6 lg:gap-8 text-sm font-bold text-slate-600">
            <a href="#hero" className="hover:text-blue-600 transition-colors">
              Beranda
            </a>
            {settings.isOfflineRunEnabled && (
              <a
                href="#offline-teaser"
                className="hover:text-emerald-600 text-emerald-600 transition-colors flex items-center gap-1"
              >
                <span className="w-2 h-2 rounded-full bg-emerald-500 animate-pulse"></span>{" "}
                Offline Run
              </a>
            )}
            <a
              href="#race-pack"
              className="hover:text-blue-600 transition-colors"
            >
              Race Pack
            </a>
            <a href="#paket" className="hover:text-blue-600 transition-colors">
              Paket Lari
            </a>
            <Link
              href="/virtual-run/leaderboard"
              className="hover:text-blue-600 transition-colors"
            >
              Lihat Klasemen
            </Link>
          </nav>

          <div className="flex items-center gap-2 sm:gap-3">
            <Link
              href="/virtual-run/dashboard"
              className={`border font-bold px-4 py-2.5 rounded-full text-xs transition-all shadow-sm flex items-center gap-2 shrink-0 ${loggedInParticipant ? "bg-blue-600 text-white border-blue-600 hover:bg-blue-700" : "bg-white border-slate-200 hover:bg-slate-50 text-slate-800"}`}
            >
              {loggedInParticipant ? (
                <>
                  <span className="w-5 h-5 bg-white/20 rounded-full flex items-center justify-center">
                    <User className="w-3 h-3 text-white" />
                  </span>
                  <span>Dashboard</span>
                </>
              ) : (
                <>
                  <User className="w-4 h-4 text-blue-600" />
                  <span>Login</span>
                </>
              )}
            </Link>

            <button
              onClick={() => setIsMobileMenuOpen(!isMobileMenuOpen)}
              className="md:hidden p-1.5 text-slate-600 hover:text-blue-600 focus:outline-none shrink-0"
            >
                {isMobileMenuOpen ? (
                  <X className="w-6 h-6" />
                ) : (
                  <Menu className="w-6 h-6" />
                )}
            </button>
          </div>
        </div>

        {/* Menu Mobile */}
        {isMobileMenuOpen && (
          <div className="md:hidden absolute top-20 left-0 w-full bg-white border-b border-slate-200 shadow-lg py-4 px-6 flex flex-col gap-4 text-sm font-bold text-slate-600">
            <a
              href="#hero"
              onClick={() => setIsMobileMenuOpen(false)}
              className="hover:text-blue-600 py-2 border-b border-slate-50"
            >
              Beranda
            </a>
            {settings.isOfflineRunEnabled && (
              <a
                href="#offline-teaser"
                onClick={() => setIsMobileMenuOpen(false)}
                className="hover:text-emerald-600 text-emerald-600 py-2 border-b border-slate-50"
              >
                Offline Run (Kumpul Fisik)
              </a>
            )}
            <a
              href="#race-pack"
              onClick={() => setIsMobileMenuOpen(false)}
              className="hover:text-blue-600 py-2 border-b border-slate-50"
            >
              Race Pack
            </a>
            <a
              href="#paket"
              onClick={() => setIsMobileMenuOpen(false)}
              className="hover:text-blue-600 py-2 border-b border-slate-50"
            >
              Paket Lari
            </a>
            <Link
              href="/virtual-run/leaderboard"
              onClick={() => setIsMobileMenuOpen(false)}
              className="text-blue-600 py-2"
            >
              Lihat Klasemen
            </Link>
          </div>
        )}
      </header>

      {/* HERO SECTION */}
      <section
        id="hero"
        className="relative pt-32 pb-24 lg:pt-40 lg:pb-32 overflow-hidden"
      >
        <div className="absolute inset-0 z-0">
          <div className="absolute inset-0 bg-gradient-to-r from-[#0B1528]/95 via-[#1A73E8]/80 to-transparent z-10"></div>
          <div className="absolute inset-0 bg-gradient-to-t from-[#F4F7FB] via-transparent to-transparent z-10 opacity-100"></div>
          <img
            src={
              settings.urlHeroBg ||
              "https://images.unsplash.com/photo-1552674605-15c9ef04392c?q=80&w=2000"
            }
            alt="Hero Background"
            className="w-full h-full object-cover object-center"
          />
        </div>

        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 relative z-20 text-center lg:text-left flex flex-col lg:items-start items-center">
          <div className="inline-flex items-center gap-2 bg-white/10 backdrop-blur-md border border-white/20 px-4 py-2 rounded-full mb-6">
            <span
              className={`w-2 h-2 rounded-full animate-pulse ${isBuka && timeLeft ? "bg-emerald-400" : "bg-rose-400"}`}
            ></span>
            <span className="text-xs font-bold text-white uppercase tracking-widest">
              {settings.statusPendaftaran === "Buka" && isWaitingToOpen && timeLeft
                ? "Segera Dibuka"
                : isBuka && timeLeft
                  ? "Pendaftaran Dibuka"
                  : "Pendaftaran Ditutup"}
            </span>
          </div>

          <h1 className="text-4xl md:text-6xl lg:text-7xl font-black text-white tracking-tight mb-6 max-w-4xl leading-[1.1]">
            {settings.landingTitle}
          </h1>

          <p className="text-lg md:text-xl text-blue-100 mb-8 max-w-2xl font-medium leading-relaxed">
            {settings.landingDesc}
          </p>

          {(isBuka || isWaitingToOpen) && timeLeft && (
            <div className="mb-10 w-full max-w-md">
              <p className="text-xs font-bold text-yellow-400 uppercase tracking-widest mb-3 text-center lg:text-left">
                {isWaitingToOpen ? "Pendaftaran Dibuka Dalam:" : "Pendaftaran Ditutup Dalam:"}
              </p>
              <div className="flex gap-3 justify-center lg:justify-start">
                {Object.keys(timeLeft).map((interval, index) => (
                  <div
                    key={index}
                    className="flex flex-col items-center bg-blue-900/50 backdrop-blur-sm border border-blue-400/30 rounded-xl p-3 w-16 sm:w-20 shadow-lg"
                  >
                    <span className="text-2xl sm:text-3xl font-black text-white">
                      {timeLeft[interval] || "0"}
                    </span>
                    <span className="text-[9px] sm:text-[10px] uppercase tracking-widest text-blue-200 mt-1">
                      {interval}
                    </span>
                  </div>
                ))}
              </div>
            </div>
          )}

          {isBuka && !timeLeft && settings.tanggalPenutupan && (
            <div className="mb-10 w-full max-w-md bg-rose-500/20 border border-rose-500/50 backdrop-blur-sm rounded-xl p-4 text-center lg:text-left">
              <p className="text-sm font-bold text-rose-100">
                Waktu Pendaftaran Telah Berakhir!
              </p>
            </div>
          )}

          <div className="flex flex-col sm:flex-row items-center gap-4 w-full sm:w-auto">
            {loggedInParticipant ? (
              <Link
                href="/virtual-run/dashboard"
                className="w-full sm:w-auto bg-blue-600 hover:bg-blue-700 text-white font-black px-10 py-4 rounded-full text-sm transition-all shadow-lg flex items-center justify-center gap-2 transform hover:-translate-y-1"
              >
                Lihat Progress Kamu &rarr;
              </Link>
            ) : (isBuka || isWaitingToOpen) && timeLeft ? (
              <Link
                href={isBuka ? "/virtual-run/register" : "#"}
                className={`w-full sm:w-auto font-black px-10 py-4 rounded-full text-sm transition-all shadow-lg flex items-center justify-center gap-2 transform hover:-translate-y-1 ${isBuka ? "bg-yellow-400 hover:bg-yellow-500 text-blue-950 shadow-yellow-400/30" : "bg-slate-400 text-white cursor-not-allowed opacity-80"}`}
              >
                {isBuka ? "Daftar Virtual Run \u2192" : "Pendaftaran Belum Dibuka"}
              </Link>
            ) : (
              <button
                disabled
                className="w-full sm:w-auto bg-slate-500 text-white font-black px-10 py-4 rounded-full text-sm cursor-not-allowed"
              >
                Pendaftaran Ditutup
              </button>
            )}

            {settings.isOfflineRunEnabled && isBuka && timeLeft && (
              <a
                href="#offline-teaser"
                className="w-full sm:w-auto bg-white/10 hover:bg-white/20 border border-white/30 backdrop-blur-sm text-white font-black px-10 py-4 rounded-full text-sm transition-all flex items-center justify-center gap-2 transform hover:-translate-y-1"
              >
                <MapPin className="w-4 h-4" /> Info Lari Offline
              </a>
            )}
          </div>
        </div>
      </section>

      {/* BANNER OFFLINE RUN */}
      {settings.isOfflineRunEnabled && (
        <section
          id="offline-teaser"
          className="relative z-30 max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 -mt-10 mb-20"
        >
          <div className="bg-gradient-to-br from-emerald-600 to-teal-800 rounded-[2rem] p-8 sm:p-12 shadow-2xl relative overflow-hidden border border-emerald-500/50 flex flex-col md:flex-row items-center justify-between gap-8">
            <div className="absolute inset-0 opacity-10 bg-[url('https://www.transparenttextures.com/patterns/cubes.png')]"></div>
            <div className="absolute -right-10 -bottom-10 opacity-20 rotate-12">
              <Activity className="w-64 h-64 text-emerald-900" />
            </div>
            <div className="relative z-10 text-center md:text-left flex-grow">
              
              <h2 className="text-3xl sm:text-4xl font-black text-white mb-3 tracking-tight">
                Ingin Lari & Kumpul Bareng?
              </h2>
              <p className="text-emerald-100 font-medium text-sm sm:text-base max-w-xl">
                Selain berlari secara virtual, kami juga mengadakan acara kumpul
                fisik. Mari lari bersama menyusuri rute:{" "}
                <strong className="text-white">
                  {settings.offlineLocation || "Yogyakarta"}
                </strong>
                .
              </p>
              <div className="flex flex-wrap items-center justify-center md:justify-start gap-4 mt-6">
                <div className="bg-white/10 backdrop-blur-sm border border-white/20 rounded-xl px-4 py-2 flex items-center gap-3">
                  <div className="w-10 h-10 bg-emerald-900/40 rounded-xl flex items-center justify-center text-emerald-400 border border-emerald-500/30">
                    <Calendar className="w-5 h-5" />
                  </div>
                  <div className="text-left">
                    <p className="text-[9px] uppercase tracking-widest text-emerald-200 font-bold">
                      Tanggal Acara
                    </p>
                    <p className="text-white font-black text-sm">
                      {settings.offlineDate
                        ? new Date(settings.offlineDate).toLocaleDateString(
                            "id-ID",
                            { day: "numeric", month: "long", year: "numeric" },
                          )
                        : "-"}
                    </p>
                  </div>
                </div>
                <div className="bg-white/10 backdrop-blur-sm border border-white/20 rounded-xl px-4 py-2 flex items-center gap-3">
                  <div className="w-10 h-10 bg-emerald-900/40 rounded-xl flex items-center justify-center text-emerald-400 border border-emerald-500/30">
                    <Clock className="w-5 h-5" />
                  </div>
                  <div className="text-left">
                    <p className="text-[9px] uppercase tracking-widest text-emerald-200 font-bold">
                      Jam Kumpul
                    </p>
                    <p className="text-white font-black text-sm">
                      {settings.offlineTime || "06:00"} WIB
                    </p>
                  </div>
                </div>
              </div>
            </div>
            <div className="relative z-10 shrink-0 w-full md:w-auto text-center">
              <Link
                href="/run"
                className="w-full md:w-auto inline-block bg-white hover:bg-slate-50 text-emerald-800 font-black px-8 py-4 rounded-xl shadow-lg transition-transform hover:-translate-y-1"
              >
                Daftar Offline Run &rarr;
              </Link>
              <p className="text-[10px] text-emerald-200 font-medium mt-3">
                *Kuota terbatas{" "}
                {settings.offlineQuota
                  ? `hanya untuk ${settings.offlineQuota} pelari`
                  : "segera amankan slotmu"}
                !
              </p>
            </div>
          </div>
        </section>
      )}

      {/* --- 🔥 1. UPDATE STATISTIK GLOBAL REAL-TIME 🔥 --- */}
      <section className="max-w-6xl mx-auto px-4 sm:px-6 lg:px-8 relative z-20 mt-10">
        <div className="bg-white/90 backdrop-blur-xl border border-white rounded-3xl p-6 sm:p-8 flex flex-col md:flex-row justify-around items-center gap-8 shadow-2xl">
          <div className="text-center w-full md:flex-1">
            <p className="text-[10px] text-slate-500 font-bold uppercase tracking-widest mb-1">
              Total Peserta Terdaftar
            </p>
            <div className="text-3xl sm:text-4xl font-black text-slate-800 flex items-center justify-center gap-3">
              {totalPeserta}{" "}
              <span className="text-lg font-bold text-slate-500">Orang</span>
            </div>
          </div>

          <div className="hidden md:block w-px h-16 bg-slate-200"></div>

          <div className="text-center w-full md:flex-1 border-t border-slate-200 pt-6 md:border-t-0 md:pt-0">
            <p className="text-[10px] text-slate-500 font-bold uppercase tracking-widest mb-1">
