        </form>

        {/* Guestbook Messages Wall */}
        <div>
          <div className="flex items-center justify-between mb-3 border-b border-slate-800 pb-2">
            <div className="flex items-center gap-2 text-xs sm:text-sm font-bold text-amber-200">
