            <a
              href={`https://wa.me/${EVENT_DETAILS.contactPhone}`}
              target="_blank"
              rel="noopener noreferrer"
              className="text-amber-300 hover:underline font-semibold"
            >
              {EVENT_DETAILS.contactPerson} ({EVENT_DETAILS.contactPhoneDisplay})
