import { NextResponse } from "next/server";
import type { NextRequest } from "next/server";

export async function middleware(request: NextRequest) {
  // Middleware ini sengaja dibuat minimal untuk menghindari redirect loop
  // yang terjadi akibat ketidakcocokan antara Edge Runtime dan cookie
  // HttpOnly di lingkungan Firebase Hosting + Cloud Run.
  //
  // Keamanan sesungguhnya dijaga oleh 3 lapis yang lebih kuat:
  //   1. layout.tsx masing-masing route (client-side auth guard via onAuthStateChanged)
  //   2. API Routes (/api/vr-admin, dll) validasi token dengan firebase-admin
  //   3. Firestore Security Rules mengunci akses data
  return NextResponse.next();
}

export const config = {
  matcher: [
    // Middleware sengaja dikosongkan dari route protected.
    // Masing-masing layout sudah menjaga autentikasi secara mandiri.
    // Hanya jalankan middleware untuk path yang benar-benar butuh edge processing.
    "/api/placeholder-not-used",
  ],
};

// Tambahan untuk mengecek field NIA di pengurus
// Run: node scripts/admin-firestore.mjs check-nia
import { readFileSync } from "fs";
import { resolve } from "path";
import { initializeApp, cert, getApps } from "firebase-admin/app";
import { getFirestore, Timestamp } from "firebase-admin/firestore";

const envPath = resolve(process.cwd(), ".env.local");
const envRaw = readFileSync(envPath, "utf-8");
const env = {};
for (const line of envRaw.split("\n")) {
  const c = line.trim();
  if (!c || c.startsWith("#")) continue;
  const eq = c.indexOf("=");
  if (eq === -1) continue;
  const key = c.slice(0, eq);
  let val = c.slice(eq + 1);
  if ((val.startsWith('"') && val.endsWith('"')) || (val.startsWith("'") && val.endsWith("'")))
    val = val.slice(1, -1);
  env[key] = val;
}

const projectId = env.FIREBASE_PROJECT_ID || "suratdigitalv2";
const clientEmail = env.FIREBASE_CLIENT_EMAIL;
const privateKey = env.FIREBASE_PRIVATE_KEY?.replace(/\\n/g, "\n");

if (!privateKey) { console.error("FIREBASE_PRIVATE_KEY not found"); process.exit(1); }

const app = getApps().length === 0
  ? initializeApp({ credential: cert({ projectId, clientEmail, privateKey }), projectId })
  : getApps()[0];
const db = getFirestore(app);

async function main() {
  const cmd = process.argv[2] || "list";

  if (cmd === "list") {
    const [users, ae] = await Promise.all([
      db.collection("users").limit(20).get(),
      db.collection("admin_emails").limit(20).get(),
    ]);
    console.log("=== USERS ===");
    if (users.empty) console.log("  (kosong)");
    else users.forEach(d => console.log(`  ${d.id} | role=${d.data().role} | ${d.data().email} | ${d.data().nama}`));
    console.log(`  Total: ${users.size}`);
    console.log("\n=== ADMIN_EMAILS ===");
    if (ae.empty) console.log("  (kosong)");
    else ae.forEach(d => console.log(`  ${d.id} | active=${d.data().active}`));
  }

  if (cmd === "add-admin-email") {
    const email = process.argv[3];
    if (!email) { console.error("Usage: node scripts/admin-firestore.mjs add-admin-email <email>"); process.exit(1); }
    await db.collection("admin_emails").doc(email).set({ email, active: true, createdAt: new Date().toISOString() });
    console.log(`✅ admin_emails/${email} created`);
  }

  if (cmd === "add-user-email") {
    const email = process.argv[3];
    const nama = process.argv[4] || email?.split("@")[0] || "Admin";
    const role = process.argv[5] || "super_admin";
    if (!email) { console.error("Usage: node scripts/admin-firestore.mjs add-user-email <email> [nama] [role]"); process.exit(1); }
    await db.collection("users").doc(email).set({ email, nama, role, isActive: true, bidang: "DPW", aksesModul: ["ringkasan"], createdAt: new Date().toISOString() });
    console.log(`✅ users/${email} created with role=${role}`);
  }

  if (cmd === "check-nia") {
    // Cek sample pengurus yg sudah disahkan
    const snap = await db.collection("pengurus").where("isPengurus", "==", true).limit(10).get();
    console.log(`=== PENGURUS (isPengurus=true) — ${snap.size} docs ===`);
    if (snap.empty) {
      console.log("  (tidak ada pengurus yang sudah disahkan)");
    } else {
      snap.forEach(d => {
        const data = d.data();
        console.log(`  ${d.id} | nama=${data.nama} | noUrut=${data.noUrut} | nia=${data.nia || "(kosong)"} | status=${data.status_pengurus}`);
      });
    }
    // Cari max noUrut untuk generate berikutnya
    const allSnap = await db.collection("pengurus").orderBy("noUrut", "desc").limit(1).get();
    if (!allSnap.empty) {
      const max = allSnap.docs[0].data().noUrut;
      console.log(`\n  Max noUrut: ${max} → next: ${(max || 0) + 1}`);
    }
  }

  if (cmd === "generate-nia") {
    // Ambil semua pengurus aktif, filter yang NIA kosong/null di JS
    // (Firestore tidak support query "nia == ''" atau "nia == null" sekaligus)
    const snap = await db.collection("pengurus")
      .where("isPengurus", "==", true)
      .get();
    const missing = snap.docs.filter(d => {
      const n = d.data().nia;
      return !n || n === "" || n === "Dalam Proses" || n === "null";
    });
    if (missing.length === 0) {
      console.log("✅ Semua pengurus sudah punya NIA valid");
      process.exit(0);
    }
    // Cari max NIA yang sudah ada untuk generate berikutnya
    let maxNia = 0;
    snap.docs.forEach(d => {
      const n = d.data().nia;
      if (n && n !== "" && n !== "Dalam Proses" && n !== "null") {
        const parts = n.split(".");
        const num = parseInt(parts[parts.length - 1], 10);
        if (!isNaN(num) && num > maxNia) maxNia = num;
      }
    });
    console.log(`Ditemukan ${missing.length} pengurus tanpa NIA. Max existing: ${maxNia}`);
    let count = 0;
    for (const doc of missing) {
      maxNia++;
      const nia = `26.08.34.00.${String(maxNia).padStart(4, "0")}`;
      await doc.ref.update({ nia });
      count++;
      console.log(`  ✅ ${doc.data().nama} → NIA=${nia}`);
    }
    console.log(`\n✅ ${count} NIA berhasil di-generate`);
  }

  process.exit(0);
}
main().catch(e => { console.error(e); process.exit(1); });

const fs = require('fs');
const https = require('https');
const path = require('path');

const API_BASE = 'https://wilayah.id/api';

const fetchJson = (url) => {
  return new Promise((resolve, reject) => {
    https.get(url, (res) => {
      let data = '';
      res.on('data', (chunk) => data += chunk);
      res.on('end', () => {
        try {
          resolve(JSON.parse(data));
        } catch (e) {
          reject(e);
        }
      });
    }).on('error', reject);
  });
};

const delay = (ms) => new Promise(res => setTimeout(res, ms));

async function main() {
  console.log('Mulai mengunduh data Provinsi dari wilayah.id...');
  const provRes = await fetchJson(`${API_BASE}/provinces.json`);
  const provinces = provRes.data.map(p => ({ id: p.code, name: p.name }));
  
  let regencies = [];
  let districts = [];

  console.log(`Berhasil mengunduh ${provinces.length} Provinsi.`);
  console.log('Mulai mengunduh Kota/Kabupaten & Kecamatan (ini butuh waktu beberapa detik)...');

  for (let i = 0; i < provinces.length; i++) {
    const prov = provinces[i];
    const regRes = await fetchJson(`${API_BASE}/regencies/${prov.id}.json`);
    const provRegencies = regRes.data.map(r => ({ id: r.code, province_id: prov.id, name: r.name }));
    regencies.push(...provRegencies);
    
    // Batch to avoid rate limit
    for (let j = 0; j < provRegencies.length; j += 10) {
      const batch = provRegencies.slice(j, j + 10);
      const batchPromises = batch.map(r => 
        fetchJson(`${API_BASE}/districts/${r.id}.json`)
          .then(res => res.data ? res.data.map(d => ({ id: d.code, regency_id: r.id, name: d.name })) : [])
          .catch(() => [])
      );
      const results = await Promise.all(batchPromises);
      results.forEach(d => {
        if (Array.isArray(d)) districts.push(...d);
      });
      await delay(20);
    }
    console.log(`[${i+1}/${provinces.length}] Selesai mengunduh data wilayah ${prov.name}`);
  }

  const finalData = {
    provinces,
    regencies,
    districts
  };

  const publicDir = path.join(__dirname, '..', 'public');
  if (!fs.existsSync(publicDir)){
      fs.mkdirSync(publicDir);
  }

  fs.writeFileSync(path.join(publicDir, 'data-wilayah.json'), JSON.stringify(finalData));
  console.log('Data berhasil disimpan di public/data-wilayah.json! Ukuran: ', (JSON.stringify(finalData).length / 1024 / 1024).toFixed(2), 'MB');
}

main().catch(console.error);

const fs = require('fs');
const path = require('path');

const excludeFiles = [
  'app/masterclass/[id]/certificate/page.tsx',
  'app/(dashboard)/dashboard/superadmin/templates/page.tsx',
  'app/(dashboard)/dashboard/proker/[slug]/cetak/[id]/CetakClient.tsx',
  'app/(dashboard)/dashboard/e-office/print/[id]/page.tsx',
  'app/(dashboard)/dashboard/verifikasi-anggota/page.tsx',
  'app/(dashboard)/dashboard/master-data/components/TabAnggotaSah.tsx',
  'app/(dashboard)/dashboard/master-data/components/TabPengurus.tsx',
  'app/(dashboard)/dashboard/master-data/components/TabAnggota.tsx',
];

function getAllFiles(dirPath, arrayOfFiles) {
  let files = fs.readdirSync(dirPath);
  arrayOfFiles = arrayOfFiles || [];
  files.forEach(function(file) {
    if (fs.statSync(dirPath + "/" + file).isDirectory()) {
      if(file !== 'node_modules' && file !== '.next' && file !== '.git') {
         arrayOfFiles = getAllFiles(dirPath + "/" + file, arrayOfFiles);
      }
    } else {
      if(file.endsWith('.tsx')) {
        arrayOfFiles.push(path.join(dirPath, "/", file));
      }
    }
  });
  return arrayOfFiles;
}

const files = getAllFiles('./app');

let modifiedCount = 0;

for (const file of files) {
  const normFile = file.replace(/\\/g, '/');
  if (excludeFiles.some(ex => normFile.includes(ex))) {
    continue; // Skip excluded files
  }

  let content = fs.readFileSync(file, 'utf8');
  
  if (!content.includes('<table')) continue; // No table
  if (content.includes('PaginationProps') || content.includes('Pagination from "@/components')) continue; // Already paginated

  console.log('Processing:', normFile);

  // 1. Find the mapped array name
  const tbodyMatch = content.match(/<tbody[^>]*>[\s\S]*?([a-zA-Z0-9_]+)\.map/);
  if (!tbodyMatch) {
    console.log('  -> Could not find mapped array in tbody for', normFile);
    continue;
  }
  const arrayName = tbodyMatch[1];
  console.log('  -> Found array:', arrayName);

  // 2. Add imports
  if (!content.includes('import Pagination')) {
     const importStatement = `import Pagination from "@/components/ui/Pagination";\n`;
     // insert after last import
     const lastImportIndex = content.lastIndexOf('import ');
     if (lastImportIndex !== -1) {
       const endOfLastImport = content.indexOf('\n', lastImportIndex);
       content = content.slice(0, endOfLastImport + 1) + importStatement + content.slice(endOfLastImport + 1);
     } else {
       content = importStatement + content;
     }
  }

  // 3. Add state inside the component
  // Find component start: export default function X() {
  const compMatch = content.match(/export default function [A-Za-z0-9_]+\s*\([^)]*\)\s*{/);
  if (compMatch) {
    const compStartIdx = compMatch.index + compMatch[0].length;
    
    // Check if useState exists, else we might have to add it, but usually it exists.
    const stateHook = `
  const [itemsPerPage, setItemsPerPage] = useState<number | string>(10);
  const [currentPage, setCurrentPage] = useState(1);
`;
    // Find a good place to insert (after component declaration)
    content = content.slice(0, compStartIdx) + stateHook + content.slice(compStartIdx);
  } else {
     console.log('  -> Component start not found');
     continue;
  }

  // 4. Add paginatedData useMemo
  // Insert before `return (`
  const returnMatch = content.lastIndexOf('\n  return (');
  if (returnMatch !== -1) {
     const useMemoLogic = `
  const paginatedData = React.useMemo(() => {
    if (itemsPerPage === "Semua") return ${arrayName};
    const startIndex = (currentPage - 1) * (itemsPerPage as number);
    return ${arrayName}.slice(startIndex, startIndex + (itemsPerPage as number));
  }, [${arrayName}, currentPage, itemsPerPage]);
`;
     content = content.slice(0, returnMatch) + useMemoLogic + content.slice(returnMatch);
  }

  // 5. Replace mapped array with paginatedData
  const regex = new RegExp(`\\b${arrayName}\\.map`, 'g');
  content = content.replace(regex, `paginatedData.map`);

  // 6. Insert Pagination UI after table
  const tableEndRegex = /<\/table>\s*(?:<\/div>)?/g;
  let match;
  let lastMatchIndex = -1;
  while ((match = tableEndRegex.exec(content)) !== null) {
      lastMatchIndex = match.index + match[0].length;
  }
  
  if (lastMatchIndex !== -1) {
    const paginationUI = `
        <Pagination
          totalItems={${arrayName}.length}
          currentPage={currentPage}
          itemsPerPage={itemsPerPage}
          setCurrentPage={setCurrentPage}
          setItemsPerPage={setItemsPerPage}
        />
`;
    content = content.slice(0, lastMatchIndex) + paginationUI + content.slice(lastMatchIndex);
  }

  fs.writeFileSync(file, content, 'utf8');
  modifiedCount++;
  console.log('  -> Updated successfully!');
}

console.log('Total files paginated:', modifiedCount);
